record* create_records(size_t num_records, long* offsets, int* keys, size_t offset_size, size_t key_size) {
    if (num_records == 0 || offsets == NULL || keys == NULL) {
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % key_size + offset_size;
        records[i].size = keys[i];
    }

    return records;
}

void free_records(record* records, size_t num_records) {
    if (records != NULL) {
        free(records);
    }
}
