void process_file(const Config *config) {
    FILE *input = fopen(config->input_file, "rb");
    if (!input) {
        perror("Failed to open input file");
        return;
    }

    fseek(input, 0, SEEK_END);
    size_t length = ftell(input);
    fseek(input, 0, SEEK_SET);

    char *data = malloc(length);
    if (!data) {
        perror("Failed to allocate memory for file data");
        fclose(input);
        return;
    }

    fread(data, 1, length, input);
    fclose(input);

    char *transformed_data = malloc(length);
    size_t transformed_length = apply_rules(data, length, config->rules_file);
    if (!transformed_data) {
        perror("Failed to allocate memory for transformed data");
        free(data);
        return;
    }

    FILE *output = fopen(config->output_file, "wb");
    if (!output) {
        perror("Failed to open output file");
        free(data);
        free(transformed_data);
        return;
    }

    fwrite(transformed_data, 1, transformed_length, output);
    fclose(output);

    log_message(config->log_level, "File processed successfully");

    free(data);
    free(transformed_data);
}

int main(int argc, char **argv) {
    Config config;
    parse_config(argc, argv, &config);

