#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define BUFFER_SIZE 1024

typedef struct {
    int *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DataBuffer;

void init_buffer(DataBuffer *buffer) {
    buffer->data = (int *)malloc(BUFFER_SIZE * sizeof(int));
    if (!buffer->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    buffer->count = 0;
    buffer->capacity = BUFFER_SIZE;
    pthread_mutex_init(&buffer->mutex, NULL);
}

void free_buffer(DataBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    free(buffer->data);
    buffer->data = NULL;
    buffer->count = 0;
    buffer->capacity = 0;
    pthread_mutex_unlock(&buffer->mutex);
    pthread_mutex_destroy(&buffer->mutex);
}

void add_to_buffer(DataBuffer *buffer, int value) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == buffer->capacity) {
        buffer->capacity *= 2;
        buffer->data = (int *)realloc(buffer->data, buffer->capacity * sizeof(int));
        if (!buffer->data) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    buffer->data[buffer->count++] = value;
    pthread_mutex_unlock(&buffer->mutex);
}

void find_largest(DataBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        printf("No data available\n");
        pthread_mutex_unlock(&buffer->mutex);
        return;
    }

    int max_value = buffer->data[0];
    size_t max_index = 0;

    for (size_t i = 1; i < buffer->count; ++i) {
        if (buffer->data[i] > max_value) {
            max_value = buffer->data[i];
            max_index = i;
        }
    }

    printf("Largest value: %d at index: %zu\n", max_value, max_index);
    pthread_mutex_unlock(&buffer->mutex);
}

void *network_thread(void *arg) {
    DataBuffer *buffer = (DataBuffer *)arg;

    // Simulate network data reception
    for (int i = 0; i < 1000; ++i) {
        add_to_buffer(buffer, rand() % 1000);
        usleep(100); // Simulate network latency
    }

    return NULL;
}

int main() {
    DataBuffer buffer;
    init_buffer(&buffer);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, network_thread, &buffer) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        free_buffer(&buffer);
        exit(EXIT_FAILURE);
    }

    // Simulate processing time
    sleep(2);

    find_largest(&buffer);

    pthread_join(thread_id, NULL);
    free_buffer(&buffer);

    return 0;
}
