#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRINGS 1024
#define MAX_STRING_LENGTH 256

typedef struct {
    char **strings;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} StringArray;

void init_string_array(StringArray *array) {
    array->strings = (char **)malloc(MAX_STRINGS * sizeof(char *));
    if (!array->strings) {
        perror("Failed to allocate memory for string array");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = MAX_STRINGS;
    pthread_mutex_init(&array->lock, NULL);
}

void free_string_array(StringArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->strings[i]);
    }
    free(array->strings);
    pthread_mutex_destroy(&array->lock);
}

int add_string_to_array(StringArray *array, const char *str) {
    if (!array || !str) {
        return -1;
    }

    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        char **new_strings = (char **)realloc(array->strings, new_capacity * sizeof(char *));
        if (!new_strings) {
            perror("Failed to reallocate memory for string array");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->strings = new_strings;
        array->capacity = new_capacity;
    }

    size_t str_len = strlen(str);
    char *new_str = (char *)malloc((str_len + 1) * sizeof(char));
    if (!new_str) {
        perror("Failed to allocate memory for string");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    strcpy(new_str, str);

    array->strings[array->count++] = new_str;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
}

int fetch_and_add_strings(StringArray *array, const char *data_source) {
    if (!array || !data_source) {
        return -1;
    }

    FILE *file = fopen(data_source, "r");
    if (!file) {
        log_error("Failed to open data source: %s\n", data_source);
        return -1;
    }

    char buffer[MAX_STRING_LENGTH];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Remove newline character
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') {
            buffer[len - 1] = '\0';
        }
        if (add_string_to_array(array, buffer) != 0) {
            log_error("Failed to add string from data source\n");
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

int main() {
    StringArray array;
    init_string_array(&array);

    if (fetch_and_add_strings(&array, "data.txt") != 0) {
        log_error("Failed to fetch and add strings\n");
    } else {
        for (size_t i = 0; i < array.count; ++i) {
            printf("%s\n", array.strings[i]);
        }
    }

    free_string_array(&array);
    return 0;
}
