import java.util.*;
import java.util.concurrent.*;

public class PokemonInfoFetcher {
    private static final Map<String, List<String>> TYPE_WEAKNESS_MAP = new HashMap<>();
    private static final Map<String, String> CACHE = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRY_TIME = TimeUnit.MINUTES.toMillis(10);
    private static final Random RANDOM = new Random();

    static {
        // Initialize type weakness mapping
        TYPE_WEAKNESS_MAP.put("Fire", Arrays.asList("Water", "Ground"));
        TYPE_WEAKNESS_MAP.put("Water", Arrays.asList("Electric", "Grass"));
        TYPE_WEAKNESS_MAP.put("Grass", Arrays.asList("Fire", "Ice", "Flying", "Bug"));
        // Add more mappings as needed
    }

    public static String getPokemonInfo(String pokemonName) {
        try {
            String cachedInfo = CACHE.get(pokemonName);
            if (cachedInfo != null && System.currentTimeMillis() - CACHE.getTimestamp(pokemonName) < CACHE_EXPIRY_TIME) {
                return cachedInfo;
            }
        } catch (Exception e) {
            // Handle cache retrieval errors
        }

        String info = fetchPokemonDetails(pokemonName);
        if (info == null) {
            return "Failed to retrieve Pokemon details.";
        }

        CACHE.put(pokemonName, info, System.currentTimeMillis());
        return info;
    }

    private static String fetchPokemonDetails(String pokemonName) {
        try {
            // Simulate network delay
            Thread.sleep(RANDOM.nextInt(401) + 100);

            // Fetch Pokemon details from external API
            String name = fetchName(pokemonName);
            List<String> types = fetchTypes(pokemonName);
            List<String> weaknesses = calculateWeaknesses(types);

            return "Name: " + name + "\nTypes: " + String.join(", ", types) + "\nWeaknesses: " + String.join(", ", weaknesses);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }

    private static String fetchName(String pokemonName) {
        // Simulate API call to fetch name
        return "Simulated Name for " + pokemonName;
    }

    private static List<String> fetchTypes(String pokemonName) {
        // Simulate API call to fetch types
        if (pokemonName.equals("Pikachu")) {
            return Arrays.asList("Electric");
        } else if (pokemonName.equals("Eevee")) {
            return Arrays.asList("Normal", "Fairy");
        }
        return Collections.emptyList();
    }

    private static List<String> calculateWeaknesses(List<String> types) {
        List<String> weaknesses = new ArrayList<>();
        for (String type : types) {
            weaknesses.addAll(TYPE_WEAKNESS_MAP.getOrDefault(type, Collections.emptyList()));
        }
        return weaknesses;
    }

    // Cache class with timestamp
    private static class CacheEntry {
        private final String value;
        private final long timestamp;

        public CacheEntry(String value, long timestamp) {
            this.value = value;
            this.timestamp = timestamp;
        }

        public String getValue() {
            return value;
        }

        public long getTimestamp() {
            return timestamp;
        }
    }
}
