#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    sem_t *sem;
    char name[256];
} Semaphore;

Semaphore* create_semaphore(const char *identifier, int initial_value) {
    Semaphore *s = (Semaphore*)malloc(sizeof(Semaphore));
    snprintf(s->name, sizeof(s->name), "/sem_%s", identifier);
    s->sem = sem_open(s->name, O_CREAT | O_EXCL, 0644, initial_value);
    if (s->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(s);
        return NULL;
    }
    return s;
}

void destroy_semaphore(Semaphore *s) {
    sem_close(s->sem);
    sem_unlink(s->name);
    free(s);
}

int wait_on_semaphore(Semaphore *s, struct timespec *timeout) {
    return sem_timedwait(s->sem, timeout);
}

int signal_semaphore(Semaphore *s) {
    return sem_post(s->sem);
}
