#include <vector>
#include <mutex>
#include <chrono>

class RateLimiter {
public:
    RateLimiter(int maxOpsPerSec) : maxOpsPerSec(maxOpsPerSec), lastReset(std::chrono::steady_clock::now()) {}

    bool canPerformOperation() {
        auto now = std::chrono::steady_clock::now();
        if (now - lastReset >= std::chrono::seconds(1)) {
            operationsThisSecond = 0;
            lastReset = now;
        }
        return operationsThisSecond < maxOpsPerSec;
    }

    void performOperation() {
        if (!canPerformOperation()) {
            throw std::runtime_error("Rate limit exceeded");
        }
        ++operationsThisSecond;
    }

private:
    int maxOpsPerSec;
    std::chrono::time_point<std::chrono::steady_clock> lastReset;
    int operationsThisSecond = 0;
};

std::mutex vectorMutex;

bool modifyVector(std::vector<int>& vec, int target, int replacement, int append, int max_operations) {
    RateLimiter rateLimiter(max_operations);

    std::lock_guard<std::mutex> lock(vectorMutex);
    rateLimiter.performOperation();

    auto it = std::find(vec.begin(), vec.end(), target);
    if (it != vec.end()) {
        *it = replacement;
        return true;
    } else {
        vec.push_back(append);
        return false;
    }
}
