#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <iostream>
#include <memory>
#include <string>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

class HttpClient {
public:
    HttpClient(net::io_context& ioc, std::string host, std::string port)
        : resolver_(ioc), stream_(ioc) {
        resolve(host, port);
    }

    void get(const std::string& target) {
        request_.version(11);
        request_.method(http::verb::get);
        request_.target(target);
        request_.set(http::field::host, host_);
        request_.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        do_request();
    }

    void post(const std::string& target, const std::string& body) {
        request_.version(11);
        request_.method(http::verb::post);
        request_.target(target);
        request_.set(http::field::host, host_);
        request_.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        request_.set(http::field::content_type, "application/json");
        request_.body() = body;
        request_.prepare_payload();

        do_request();
    }

private:
    void resolve(const std::string& host, const std::string& port) {
        resolver_.async_resolve(host, port,
            [this](beast::error_code ec, tcp::resolver::results_type results) {
                if (!ec)
                    do_connect(results);
            });
    }

    void do_connect(tcp::resolver::results_type results) {
        net::async_connect(stream_.lowest_layer(), results,
            [this](beast::error_code ec, tcp::resolver::results_type::endpoint_type endpoint) {
                if (!ec)
                    do_handshake();
            });
    }

    void do_handshake() {
        stream_.async_handshake(net::ssl::stream_base::client,
            [this](beast::error_code ec) {
                if (!ec)
                    do_write();
            });
    }

    void do_write() {
        http::async_write(stream_, request_,
            [this](beast::error_code ec, std::size_t bytes_transferred) {
                if (!ec)
                    do_read();
            });
    }

    void do_read() {
        http::async_read(stream_, buffer_, response_,
            [this](beast::error_code ec, std::size_t bytes_transferred) {
                if (!ec)
                    handle_response();
            });
    }

    void handle_response() {
        // Handle the response here
    }

    tcp::resolver resolver_;
    net::ssl::stream<tcp::socket> stream_;
    http::request<http::string_body> request_;
    http::response<http::dynamic_body> response_;
    beast::flat_buffer buffer_;
    std::string host_;
};

int main() {
    try {
        net::io_context ioc;
        HttpClient client(ioc, "example.com", "443");

        client.get("/");
        client.post("/api/data", "{\"key\":\"value\"}");

        ioc.run();
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
