#include <boost/log/attributes/named_scope.hpp>

namespace logging = boost::log;
namespace src = boost::log::sources;
namespace expr = boost::log::expressions;
namespace keywords = boost::log::keywords;

BOOST_LOG_GLOBAL_LOGGER(my_logger, src::severity_logger_mt<boost::log::trivial::severity_level>)

void init_logging() {
    // Add file logging
    auto file_sink = std::make_shared<logging::sinks::text_file_backend>(
        keywords::file_name = "application_%N.log",
        keywords::rotation_size = 10 * 1024 * 1024,
        keywords::time_based_rotation = expr::on_date_change(expr::format_date_time<boost::posix_time::ptime>("TimeStamp", "%Y-%m-%d"))
    );

    logging::sinks::synchronous_sink<logging::sinks::text_file_backend> file_sink_wrapper(file_sink);
    file_sink_wrapper.set_filter(expr::attr<boost::log::trivial::severity_level>("Severity") >= boost::log::trivial::info);

    // Add console logging
    auto console_sink = std::make_shared<logging::sinks::text_ostream_backend>();
    console_sink->add_stream(std::clog);
    logging::sinks::synchronous_sink<logging::sinks::text_ostream_backend> console_sink_wrapper(console_sink);
    console_sink_wrapper.set_filter(expr::attr<boost::log::trivial::severity_level>("Severity") >= boost::log::trivial::warning);

    // Add to core
    logging::core::get()->add_sink(file_sink_wrapper);
    logging::core::get()->add_sink(console_sink_wrapper);

    // Set up common attributes
    logging::add_common_attributes();
}

int main() {
    init_logging();

    BOOST_LOG_TRIVIAL(trace) << "This is a trace severity message";
    BOOST_LOG_TRIVIAL(debug) << "This is a debug severity message";
    BOOST_LOG_TRIVIAL(info) << "This is an info severity message";
    BOOST_LOG_TRIVIAL(warning) << "This is a warning severity message";
    BOOST_LOG_TRIVIAL(error) << "This is an error severity message";
    BOOST_LOG_TRIVIAL(fatal) << "This is a fatal severity message";

    return 0;
}
