public class PhysicsEngineConfig
{
    public double GravityStrength { get; set; }
    public double CollisionDetectionSensitivity { get; set; }
    public int SimulationFrameRate { get; set; }
}

public class PhysicsEngine
{
    private PhysicsEngineConfig config;

    public PhysicsEngine(string configFilePath)
    {
        LoadConfig(configFilePath);
    }

    private void LoadConfig(string filePath)
    {
        if (File.Exists(filePath))
        {
            string json = File.ReadAllText(filePath);
            config = JsonConvert.DeserializeObject<PhysicsEngineConfig>(json);
        }
        else
        {
            throw new FileNotFoundException("Configuration file not found.");
        }
    }

    public void UpdateConfig(double gravity, double sensitivity, int frameRate)
    {
        config.GravityStrength = gravity;
        config.CollisionDetectionSensitivity = sensitivity;
        config.SimulationFrameRate = frameRate;

        // Apply changes to the engine
        ApplyConfigChanges();
    }

    private void ApplyConfigChanges()
    {
        // Logic to apply new configuration settings to the physics engine
        Console.WriteLine($"Gravity: {config.GravityStrength}, Sensitivity: {config.CollisionDetectionSensitivity}, Frame Rate: {config.SimulationFrameRate}");
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        string configFilePath = "path_to_config_file.json";
        PhysicsEngine engine = new PhysicsEngine(configFilePath);

        // Example of updating configuration in real-time
        engine.UpdateConfig(9.81, 0.5, 60);
    }
}
