using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public class ResourceController : ControllerBase
{
    private readonly MyDbContext _context;

    public ResourceController(MyDbContext context)
    {
        _context = context;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, [FromBody] Resource updatedResource, string ifMatch)
    {
        var resource = await _context.Resources.FindAsync(id);
        if (resource == null)
            return NotFound();

        if (!ETagMatches(resource.ETag, ifMatch))
            return StatusCode(412, "Precondition Failed");

        resource.Update(updatedResource);
        resource.ETag = GenerateETag();
        _context.Entry(resource).State = EntityState.Modified;
        await _context.SaveChangesAsync();

        LogOperation("Update", id, HttpContext.Connection.RemoteIpAddress.ToString());

        return Ok(resource);
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        var resource = await _context.Resources.FindAsync(id);
        if (resource == null)
            return NotFound();

        try
        {
            await ProcessPaymentAsync(resource);
        }
        catch (Exception ex)
        {
            LogOperation("Delete", id, HttpContext.Connection.RemoteIpAddress.ToString(), error: ex.Message);
            return StatusCode(500, "Internal Server Error");
        }

        _context.Resources.Remove(resource);
        await _context.SaveChangesAsync();

        LogOperation("Delete", id, HttpContext.Connection.RemoteIpAddress.ToString());

        return NoContent();
    }

    private bool ETagMatches(string serverETag, string clientETag)
    {
        return serverETag == clientETag;
    }

    private string GenerateETag()
    {
        // Implement ETag generation logic
        return Guid.NewGuid().ToString("N");
    }

    private async Task ProcessPaymentAsync(Resource resource)
    {
        var paymentService = new PaymentService();
        for (int i = 0; i < 3; i++)
        {
            try
            {
                await paymentService.ProcessTransaction(resource);
                break;
            }
            catch (Exception ex)
            {
                LogOperation("Payment", resource.Id, HttpContext.Connection.RemoteIpAddress.ToString(), error: ex.Message);
                if (i == 2) throw;
                await Task.Delay((int)Math.Pow(2, i) * 100); // Exponential backoff
            }
        }
    }

    private void LogOperation(string operation, int resourceId, string ipAddress, string error = null)
    {
        var logEntry = new LogEntry
        {
            Timestamp = DateTime.UtcNow,
            UserId = HttpContext.User.Identity.Name,
            Operation = operation,
            ResourceId = resourceId,
            IPAddress = ipAddress,
            Error = error
        };

        _context.LogEntries.Add(logEntry);
        _context.SaveChanges();
    }
}

