using System;
using System.IO;
using System.Xml.Linq;

public class ProjectDirectoryManager
{
    private static readonly string[] Environments = { "development", "staging", "production" };
    private static readonly Dictionary<string, string> EnvironmentVariables = new Dictionary<string, string>();
    private static XDocument configXml;
    private static DateTime lastConfigLoadTime;

    public static void Initialize(string xmlFilePath)
    {
        LoadConfiguration(xmlFilePath);
    }

    public static string GetProjectDirectory(string environment)
    {
        if (!Environments.Contains(environment))
            throw new ArgumentException("Invalid environment");

        var directoryPath = Environment.GetEnvironmentVariable($"{environment}_PROJECT_DIR");
        if (directoryPath == null)
        {
            directoryPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, environment);
            Environment.SetEnvironmentVariable($"{environment}_PROJECT_DIR", directoryPath);
        }

        return directoryPath;
    }

    public static void SetConfiguration(string key, string value)
    {
        configXml.Root.Element(key).Value = value;
        SaveConfiguration();
        UpdateEnvironmentVariables();
    }

    private static void LoadConfiguration(string xmlFilePath)
    {
        configXml = XDocument.Load(xmlFilePath);
        lastConfigLoadTime = DateTime.Now;
        UpdateEnvironmentVariables();
    }

    private static void SaveConfiguration()
    {
        configXml.Save(configXml.BaseUri.LocalPath);
    }

    private static void UpdateEnvironmentVariables()
    {
        foreach (var element in configXml.Root.Elements())
        {
            Environment.SetEnvironmentVariable(element.Name.LocalName, element.Value);
        }
    }

    public static bool IsConfigurationChanged(string xmlFilePath)
    {
        var fileInfo = new FileInfo(xmlFilePath);
        if (fileInfo.LastWriteTime > lastConfigLoadTime)
        {
            LoadConfiguration(xmlFilePath);
            return true;
        }
        return false;
    }
}
```

This code snippet provides a basic implementation of the `ProjectDirectoryManager` class, which manages project directories and configuration settings. It includes methods to initialize the configuration, retrieve project directories based on the current environment, set configuration values, load and save XML configurations, update environment variables, and detect changes in the underlying XML configuration.

To use this class, you would call `Initialize` with the path to your XML configuration file before using any other methods. The `GetProjectDirectory` method will return the appropriate project directory based on the current environment. The `SetConfiguration` method allows updating configuration values dynamically, and `IsConfigurationChanged` can be used to check if the configuration has been updated since the last load.

Remember that this is a basic implementation and may need further refinement for production use, such as adding error handling, logging, and more sophisticated dependency management.']

