import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {

    private static final int THREAD_POOL_SIZE = 10;
    private static final String MD5_ALGORITHM = "MD5";

    public static String hashStrings(List<String> inputStrings) {
        ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        StringBuilder resultBuilder = new StringBuilder();

        for (String input : inputStrings) {
            executorService.submit(() -> {
                try {
                    byte[] md5Bytes = MessageDigest.getInstance(MD5_ALGORITHM).digest(input.getBytes());
                    String hash = bytesToHex(md5Bytes);
                    synchronized (resultBuilder) {
                        resultBuilder.append(hash);
                    }
                } catch (NoSuchAlgorithmException e) {
                    // Handle the exception, possibly by logging or rethrowing
                }
            });
        }

        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(100, TimeUnit.MILLISECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }

        return resultBuilder.toString();
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // Example usage
        List<String> inputStrings = List.of("example1", "example2", "example3");
        String result = hashStrings(inputStrings);
        System.out.println(result);
    }
}
