    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement([FromBody] ElementUpdateRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var user = await _authenticationService.GetCurrentUserAsync();
        if (user == null || !await _authenticationService.IsAuthorizedAsync(user, request.ElementId))
        {
            return Unauthorized();
        }

        if (!await _rateLimiter.AllowUpdateAsync(request.ElementId))
        {
            return StatusCode(429, "Too Many Requests");
        }

        try
        {
            var validationResult = await ValidateHtmlContentAsync(request.HtmlContent);
            if (validationResult != null)
            {
                return BadRequest(validationResult);
            }

            await _elementService.UpdateElementAsync(request.PageSectionId, request.ElementId, request.HtmlContent, user);

            _logger.LogInformation("Updated element {ElementId} on page section {PageSectionId} by user {UserId}", request.ElementId, request.PageSectionId, user.Id);

            return Ok(new { Refresh = true });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update element {ElementId} on page section {PageSectionId}", request.ElementId, request.PageSectionId);
            return StatusCode(500, "Internal Server Error");
