public interface IRateLimiter
{
    Task<bool> AllowUpdateAsync(string elementId);
}

public class RateLimiter : IRateLimiter
{
    private readonly IDistributedCache _cache;

    public RateLimiter(IDistributedCache cache)
    {
        _cache = cache;
    }

    public async Task<bool> AllowUpdateAsync(string elementId)
    {
        var key = $"rate_limit:{elementId}";
        var count = await _cache.GetStringAsync(key);
        if (count == null)
        {
            await _cache.SetStringAsync(key, "1", new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(60) });
            return true;
        }

        int updateCount = int.Parse(count);
        if (updateCount >= 10)
        {
            return false;
        }

        await _cache.SetStringAsync(key, (updateCount + 1).ToString(), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(60) });
        return true;
    }
}

