    public static void checkAndRecycleThemeBitmap(Bitmap bitmap) {
        if (bitmap != null && bitmap.isRecyclable()) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    public static void configureDefaultThemeDirectory(String defaultPath) {
        String themeDir = System.getProperty("theme.dir");
        if (themeDir == null || themeDir.isEmpty()) {
            System.setProperty("theme.dir", defaultPath);
        }
    }

    public static void parseAndCachePNGFile() {
        String cacheRoot = System.getProperty("cache.root");
        if (cacheRoot != null && !cacheRoot.isEmpty()) {
            File pngFile = new File(cacheRoot, "default.png");
            try (InputStream is = new FileInputStream(pngFile)) {
                Bitmap bitmap = BitmapFactory.decodeStream(is);
                // Cache the bitmap
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        String filePath = "path/to/state/file";
        MoSTState state = loadState(filePath);
        checkAndRecycleThemeBitmap(state.getThemeBitmap());
        configureDefaultThemeDirectory("/default/theme/dir");
        parseAndCachePNGFile();
    }
