using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using System.Security.Cryptography;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Numerics;
using System;

public class ApplicationUser : IdentityUser
{
    public string FirstName { get; set; }
    public string LastName { get; set; }
}

public class ApplicationDbContext : IdentityDbContext<ApplicationUser>
{
    public ApplicationDbContext(DbContextOptions<ApplicationDbContext> options)
        : base(options)
    {
    }

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        // Configure user lockout settings
        builder.Entity<IdentityUserLogin<string>>().ToTable("UserLogins");
        builder.Entity<IdentityUserRole<string>>().ToTable("UserRoles");
        builder.Entity<IdentityUserClaim<string>>().ToTable("UserClaims");
        builder.Entity<IdentityUserToken<string>>().ToTable("UserTokens");

        // Configure user lockout settings
        builder.Entity<ApplicationUser>().Property(u => u.LockoutEnabled).HasDefaultValue(true);
        builder.Entity<ApplicationUser>().Property(u => u.LockoutEnd).IsRequired(false);

        // Configure password complexity rules
        builder.Entity<IdentityUser>().Property(u => u.PasswordHash)
            .IsRequired()
            .HasMaxLength(128)
            .HasAnnotation("PasswordComplexity", new { MinLength = 8, RequireNonLetterOrDigit = true, RequireDigit = true, RequireLowercase = true, RequireUppercase = true });

        // Configure concurrency using row versioning
        builder.Entity<ApplicationUser>().Property(u => u.ConcurrencyStamp).IsConcurrencyToken();
    }
}

public class AccountManager : IAccountManager
{
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly SignInManager<ApplicationUser> _signInManager;

    public AccountManager(UserManager<ApplicationUser> userManager, SignInManager<ApplicationUser> signInManager)
    {
        _userManager = userManager;
        _signInManager = signInManager;
    }

    public async Task<IdentityResult> RegisterAsync(string email, string password, string firstName, string lastName)
    {
        var user = new ApplicationUser { UserName = email, Email = email, FirstName = firstName, LastName = lastName };
        return await _userManager.CreateAsync(user, password);
    }

    public async Task<SignInResult> LoginAsync(string email, string password, bool rememberMe)
    {
        return await _signInManager.PasswordSignInAsync(email, password, rememberMe, lockoutOnFailure: true);
    }

    public async Task SignOutAsync()
    {
        await _signInManager.SignOutAsync();
    }

    public async Task<IdentityResult> ChangePasswordAsync(string userId, string currentPassword, string newPassword)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null) return IdentityResult.Failed("User not found.");

        return await _userManager.ChangePasswordAsync(user, currentPassword, newPassword);
    }

    public async Task<IdentityResult> SetTwoFactorEnabledAsync(string userId, bool enabled)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null) return IdentityResult.Failed("User not found.");

        return await _userManager.SetTwoFactorEnabledAsync(user, enabled);
    }

    public async Task<IdentityResult> AddLoginProviderAsync(string userId, string loginProvider, string providerKey)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null) return IdentityResult.Failed("User not found.");

        return await _userManager.AddLoginAsync(user, new UserLoginInfo(loginProvider, providerKey));
    }
}

public interface IAccountManager
{
    Task<IdentityResult> RegisterAsync(string email, string password, string firstName, string lastName);
    Task<SignInResult> LoginAsync(string email, string password, bool rememberMe);
    Task SignOutAsync();
    Task<IdentityResult> ChangePasswordAsync(string userId, string currentPassword, string newPassword);
    Task<IdentityResult> SetTwoFactorEnabledAsync(string userId, bool enabled);
    Task<IdentityResult> AddLoginProviderAsync(string userId, string loginProvider, string providerKey);
}
