["```javascript
const fs = require('fs').promises;
const path = require('path');
const cache = new Map();

async function readAndProcessFiles(directory, lineThreshold) {
  if (cache.has(directory)) {
    return cache.get(directory);
  }

  const files = await fs.readdir(directory);
  let totalLines = 0;
  const largeFiles = [];

  for (const file of files) {
    const filePath = path.join(directory, file);
    const stats = await fs.stat(filePath);

    if (stats.isFile()) {
      const content = await fs.readFile(filePath, 'utf8');
      const lines = content.split('\n').length;
      totalLines += lines;

      if (lines > lineThreshold) {
        largeFiles.push(file);
      }
    } else if (stats.isDirectory()) {
      // Recursively process subdirectories
      const result = await readAndProcessFiles(filePath, lineThreshold);
      totalLines += result.totalLines;
      largeFiles.push(...result.largeFiles.filter(f => !largeFiles.includes(f)));
    }
  }

  const summary = { totalLines, largeFiles };
  cache.set(directory, summary);

  return summary;
}

// Example usage:
(async () => {
  try {
    const directoryPath = './your-directory-path';
    const lineThreshold = 1000; // Adjust as needed
    const result = await readAndProcessFiles(directoryPath, lineThreshold);
    console.log(result);
  } catch (error) {
    console.error('Error processing files:', error);
  }
})();
```

This code snippet defines an asynchronous function `readAndProcessFiles` that reads multiple files from a specified directory, processes their contents, and returns a summary object containing the total number of lines across all files and a list of files that exceed a specified line count threshold. It uses caching to avoid redundant file reading operations if the directory is accessed multiple times within a short period. The function is designed to be modular and can handle directories with thousands of files efficiently without consuming excessive memory or processing time."]

