["```javascript
function renderFooterScripts(scripts) {
    const footer = document.querySelector('footer');
    if (!footer) {
        console.error('Footer element not found.');
        return '';
    }

    scripts.forEach(script => {
        if (typeof script !== 'object' || !script) {
            console.warn('Invalid script object:', script);
            return;
        }

        const { key, type, src, charset } = script;

        if (!key || !type || !src) {
            console.warn('Missing required properties in script object:', script);
            return;
        }

        let element;

        switch (type) {
            case 'text/javascript':
                element = document.createElement('script');
                element.src = src;
                element.type = type;
                if (charset) element.charset = charset;
                break;
            case 'text/css':
                element = document.createElement('link');
                element.rel = 'stylesheet';
                element.href = src;
                break;
            default:
                console.warn(`Unsupported script type: ${type}`);
                return;
        }

        const existingElement = footer.querySelector(`[${key}]`);
        if (existingElement) {
            console.log(`Script with key ${key} already exists. Skipping.`);
            return;
        }

        element.setAttribute('data-key', key);
        footer.appendChild(element);

        element.onload = () => {
            console.log(`Script loaded successfully: ${src}`);
        };

        element.onerror = () => {
            console.error(`Failed to load script: ${src}`);
        };
    });

    return footer.outerHTML;
}
