function refreshDialogFields(resourceId, url, fields) {
    var forwardList = this.$scope.forwardList; // Assuming $scope is accessible

    function updateField(fieldName, data) {
        var fieldElement = document.getElementById(fieldName);
        if (fieldElement) {
            fieldElement.value = data;
        }
    }

    function sendMessageToParent(fieldName, data) {
        try {
            window.parent.postMessage({ fieldName: fieldName, data: data }, '*');
        } catch (e) {
            console.error('Failed to send message to parent:', e);
        }
    }

    function fetchAndUpdateField(fieldName) {
        fetch(url + '/' + resourceId + '/' + fieldName)
            .then(response => response.json())
            .then(data => {
                updateField(fieldName, data);
                sendMessageToParent(fieldName, data);
            })
            .catch(error => {
                console.error('Failed to fetch data for field', fieldName, error);
            });
    }

    fields.forEach(fetchAndUpdateField);

    // Update forward list
    var firstMatchIndex = forwardList.findIndex(item => typeof item === 'string' && fields.includes(item));
    if (firstMatchIndex !== -1) {
        forwardList.splice(firstMatchIndex + 1, 0, url);
    } else {
        forwardList.push(url);
    }
}
