class DataIngestionManager {
  constructor(apiUrl, messageService, interval, delay) {
    this.apiUrl = apiUrl;
    this.messageService = messageService;
    this.interval = interval;
    this.delay = delay;
    this.isPaused = false;
    this.dataQueue = [];
    this.timerId = null;
  }

  async validateData(data) {
    try {
      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
      return response.ok;
    } catch (error) {
      console.error('Validation failed:', error);
      return false;
    }
  }

  async storeDataInDatabase(data) {
    // Simulate database storage
    console.log('Storing data in database:', data);
  }

  async notifySystemAdmin() {
    try {
      await this.messageService.sendNotification('Data ingestion paused');
    } catch (error) {
      console.error('Failed to notify system admin:', error);
    }
  }

  startIngestion() {
    if (!this.timerId && !this.isPaused) {
      this.timerId = setInterval(async () => {
        if (this.dataQueue.length > 0) {
          const data = this.dataQueue.shift();
          if (await this.validateData(data)) {
            await this.storeDataInDatabase(data);
          } else {
            console.error('Invalid data:', data);
          }
        }
      }, this.interval + Math.random() * this.delay);
    }
  }

  pauseIngestion() {
    this.isPaused = true;
    clearInterval(this.timerId);
    this.timerId = null;
    this.notifySystemAdmin();
  }

  resumeIngestion() {
    this.isPaused = false;
    this.startIngestion();
  }

  addDataToQueue(data) {
    if (!this.isPaused) {
      this.dataQueue.push(data);
    }
  }

  async restartIngestion() {
    this.pauseIngestion();
    await new Promise(resolve => setTimeout(resolve, this.delay));
    this.resumeIngestion();
  }
}

// Example usage
const apiUrl = 'https://api.example.com/validate';
const messageService = {
  sendNotification: async (message) => {
    console.log('Sending notification:', message);
  }
};
const ingestionManager = new DataIngestionManager(apiUrl, messageService, 1000, 500);

// Simulate data ingestion
setInterval(() => {
  const newData = { id: Date.now(), value: Math.random() };
  ingestionManager.addDataToQueue(newData);
}, 2000);

// Simulate restarts
setInterval(async () => {
  await ingestionManager.restartIngestion();
}, 10000);
