class DataBuffer {
  constructor(initialSize = 1024) {
    this.buffer = new ArrayBuffer(initialSize);
    this.view = new DataView(this.buffer);
    this.size = initialSize;
    this.position = 0;
    this.paused = false;
    this.compressionAlgorithm = 'gzip'; // Default compression algorithm
  }

  async addData(data) {
    if (this.paused) return;

    while (data.length > 0) {
      const bytesToWrite = Math.min(data.length, this.size - this.position);
      for (let i = 0; i < bytesToWrite; i++) {
        this.view.setUint8(this.position + i, data[i]);
      }
      data = data.slice(bytesToWrite);
      this.position += bytesToWrite;

      if (this.position === this.size) {
        await this.resizeBuffer();
      }
    }

    return this.compressData();
  }

  async resizeBuffer() {
    const newSize = Math.min(this.size * 2, 1048576); // Double the size but limit to 1MB
    const newBuffer = new ArrayBuffer(newSize);
    const newView = new DataView(newBuffer);

    for (let i = 0; i < this.position; i++) {
      newView.setUint8(i, this.view.getUint8(i));
    }

    this.buffer = newBuffer;
    this.view = newView;
    this.size = newSize;
  }

  async compressData() {
    if (this.compressionAlgorithm === 'gzip') {
      // Implement gzip compression logic here
      // Example: return await gzip(this.buffer.slice(0, this.position));
    } else if (this.compressionAlgorithm === 'lz4') {
      // Implement lz4 compression logic here
      // Example: return await lz4.compress(this.buffer.slice(0, this.position));
    }

    return this.buffer.slice(0, this.position);
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  setCompressionAlgorithm(algorithm) {
    if (['gzip', 'lz4'].includes(algorithm)) {
      this.compressionAlgorithm = algorithm;
    } else {
      throw new Error('Unsupported compression algorithm');
    }
  }
}

// Example usage:
const buffer = new DataBuffer();
buffer.addData([1, 2, 3, 4]);
buffer.setCompressionAlgorithm('gzip');
buffer.pause();
setTimeout(() => {
  buffer.resume();
}, 5000);
