["```javascript
function fetchAndFilterElements(node, selector, config, callback) {
    if (!node || !selector || typeof callback !== 'function') return [];

    const { maxDepth = 5, timeout = 1000, onError } = config;
    let depth = 0;

    function traverse(currentNode, currentDepth) {
        if (currentDepth > depth) depth = currentDepth;
        if (depth >= maxDepth) return [];

        const elements = Array.from(currentNode.querySelectorAll(selector));
        const filteredElements = elements.filter(element => {
            try {
                return callback(element);
            } catch (error) {
                onError && onError(error, element);
                return false;
            }
        });

        let childrenResults = [];
        if (currentDepth < maxDepth) {
            for (let child of currentNode.children) {
                childrenResults = childrenResults.concat(traverse(child, currentDepth + 1));
            }
        }

        return filteredElements.concat(childrenResults);
    }

    return traverse(node, 0);
}
