    document.head.appendChild(script);
  });
}

function modifyFilename(filename, extension, sequence) {
  const baseName = filename.split('.').slice(0, -1).join('.');
  return `${baseName}-${sequence}.${extension}`;
}

async function executeScript(url, sequence, extension) {
  try {
    const modifiedUrl = modifyFilename(url.split('/').pop(), extension, sequence);
    await loadLibrary(modifiedUrl);
    console.log(`Script ${modifiedUrl} loaded and executed successfully.`);
  } catch (error) {
    console.error(error.message);
  }
}

// Example usage:
executeScript('https://example.com/library.js', '12345', 'js');
