import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class NioServer {
    private static final int PORT = 8080;
    private static final int MAX_CONNECTIONS = 1024;
    private static final int IDLE_TIMEOUT = 60; // in seconds

    public static void main(String[] args) throws IOException {
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(PORT));
        serverSocketChannel.configureBlocking(false);

        Selector selector = Selector.open();
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        ByteBuffer buffer = ByteBuffer.allocate(1024);

        while (true) {
            selector.select();

            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isAcceptable()) {
                    handleAccept(key, serverSocketChannel);
                } else if (key.isReadable()) {
                    handleRead(key, buffer);
                }

                keyIterator.remove();
            }
        }
    }

    private static void handleAccept(SelectionKey key, ServerSocketChannel serverSocketChannel) throws IOException {
        SocketChannel clientChannel = serverSocketChannel.accept();
        clientChannel.configureBlocking(false);
        clientChannel.register(key.selector(), SelectionKey.OP_READ);
    }

    private static void handleRead(SelectionKey key, ByteBuffer buffer) throws IOException {
        SocketChannel clientChannel = (SocketChannel) key.channel();

        int bytesRead = clientChannel.read(buffer);

        if (bytesRead == -1) {
            clientChannel.close();
        } else if (bytesRead > 0) {
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            String message = new String(data);
            System.out.println("Received: " + message);

            // Process the message and send a response
            String response = "Response to: " + message;
            ByteBuffer responseBuffer = ByteBuffer.wrap(response.getBytes());
            clientChannel.write(responseBuffer);

            buffer.clear();
        }
    }

    public static void main(String[] args) throws IOException {
        NioServer server = new NioServer();
        server.start();
    }
}
```

This code snippet provides a basic structure for a Java NIO server that handles multiple concurrent client connections. It uses a `Selector` to manage the selection keys and efficiently process incoming data from clients. The server listens on port 8080 and accepts new connections, then reads data from connected clients and sends responses.

To implement a robust service with connection pooling, graceful degradation, and horizontal scaling, additional components and strategies would need to be integrated into this basic framework. This includes using a connection pool library like HikariCP or Apache Commons Pool, implementing a monitoring system for resource usage and performance metrics, and designing the application architecture to support load balancing across multiple instances.']

