use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use libc::{c_char, c_int, va_list, vsnprintf};
use rustc_driver::{self, Compilation, CompilerInput, RunCompiler};
use rustc_session::{EarlyErrorHandler, Session};

static mut LOG_FILE: *mut c_char = std::ptr::null_mut();

extern "C" {
    fn open_log_file(filename: *const c_char) -> *mut c_char;
    fn log_message(message: *const c_char);
    fn close_log_file();
}

fn compile_and_log() -> i32 {
    unsafe {
        LOG_FILE = open_log_file(b"rust_compile.log\0".as_ptr());
    }

    let start_time = Instant::now();

    let exit_code = rustc_driver::catch_with_exit_code(|| {
        let input = CompilerInput::File(std::path::PathBuf::from("src/main.rs"));
        let config = rustc_session::config::Config {
            crate_name: Some("my_crate".to_string()),
            edition: rustc_ast::edition::Edition::Edition2018,
            ..Default::default()
        };

        let early_error = EarlyErrorHandler::new();
        let session = Session::build_and_setup(&early_error, &config);

        let result = rustc_driver::run_compiler(
            &[input],
            &session,
            None,
            |compiler| {
                compiler.compile_crate(Compilation::ToExecutable)
            },
        );

        if let Err(e) = result {
            early_error.emit_err(e);
        }

        0
    });

    let duration = start_time.elapsed();
    unsafe {
        log_message(b"Compilation took: {:.2?}\n\0".as_ptr());
        close_log_file();
    }

    exit_code
}

fn main() {
    compile_and_log();
}
```

