<?php

use Predis\Client;
use GuzzleHttp\Client as HttpClient;

function updateUserAttributes($userToken, $newAttributes) {
    // Initialize Redis client for distributed locking
    $redis = new Client();

    // Attempt to acquire lock on the user token
    if (!$redis->setnx('lock:' . $userToken, 1)) {
        return "Conflict: Another update is in progress.";
    }

    try {
        // Simulate database connection and update operation
        $dbClient = new PDO('mysql:host=localhost;dbname=users', 'username', 'password');
        $dbClient->beginTransaction();

        $stmt = $dbClient->prepare("SELECT * FROM users WHERE token = :token FOR UPDATE");
        $stmt->execute(['token' => $userToken]);
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$user) {
            return "Error: User not found.";
        }

        // Update user attributes
        foreach ($newAttributes as $key => $value) {
            $user[$key] = $value;
        }

        $updateStmt = $dbClient->prepare("UPDATE users SET first_name = :first_name, last_name = :last_name, email = :email, role = :role WHERE token = :token");
        $updateStmt->execute($user);

        // Commit transaction
        $dbClient->commit();

        // Log update attempt
        logUpdateAttempt($userToken, $newAttributes, $user);

        // Send confirmation email and notify other systems
        sendConfirmationEmail($user['email'], $newAttributes);
        notifyOtherSystems($userToken, $newAttributes);

        return "Success: User attributes updated successfully.";
    } catch (PDOException $e) {
        // Rollback transaction in case of error
        if ($dbClient->inTransaction()) {
            $dbClient->rollBack();
        }

        // Log error
        logError($userToken, $newAttributes, $e);

        return "Error: Failed to update user attributes.";
    } finally {
        // Release lock on the user token
        $redis->del('lock:' . $userToken);
    }
}

function logUpdateAttempt($userToken, $newAttributes, $currentAttributes) {
    // Log update attempt with current and updated attributes
    error_log("User {$userToken} updated from " . json_encode($currentAttributes) . " to " . json_encode($newAttributes));
}

function sendConfirmationEmail($email, $attributes) {
    // Simulate sending confirmation email
    $httpClient = new HttpClient();
    $response = $httpClient->request('POST', 'https://api.example.com/send-email', [
        'json' => [
            'to' => $email,
            'subject' => 'User Attributes Updated',
            'body' => "Your user attributes have been updated to: " . json_encode($attributes)
        ]
    ]);

    if ($response->getStatusCode() !== 200) {
        error_log("Failed to send confirmation email to {$email}");
    }
}

function notifyOtherSystems($userToken, $newAttributes) {
    // Simulate notifying other systems
    $httpClient = new HttpClient();
    $response = $httpClient->request('POST', 'https://api.example.com/notify-systems', [
        'json' => [
            'user_token' => $userToken,
            'updates' => $newAttributes
        ]
    ]);

    if ($response->getStatusCode() !== 200) {
        error_log("Failed to notify other systems about user {$userToken} update");
    }
}

function logError($userToken, $newAttributes, $exception) {
    // Log error with exception details
    error_log("Error updating user {$userToken}: " . $exception->getMessage());
}
