import time
from collections import defaultdict
from typing import Dict, Any

class SessionProcessor:
    def __init__(self, timeout: int):
        self.sessions: Dict[str, Dict[str, Any]] = {}
        self.timeout = timeout
        self.last_cleanup_time = 0

    def process_session(self, session_id: str, activity_timestamp: float) -> None:
        current_time = time.time()

        if session_id not in self.sessions:
            self.sessions[session_id] = {
                'last_active': activity_timestamp,
                'total_duration': 0,
                'activity_count': 0
            }

        last_activity = self.sessions[session_id]['last_active']
        duration = current_time - last_activity

        if duration > self.timeout:
            self.sessions[session_id]['total_duration'] += duration
            self.sessions[session_id]['activity_count'] += 1
            self.sessions[session_id]['last_active'] = activity_timestamp

        # Cleanup old sessions
        if current_time - self.last_cleanup_time > self.timeout * 2:
            self.cleanup_sessions()

    def cleanup_sessions(self) -> None:
        current_time = time.time()
        for session_id, session_data in list(self.sessions.items()):
            if current_time - session_data['last_active'] > self.timeout * 3:
                del self.sessions[session_id]
        self.last_cleanup_time = current_time

# Example usage
processor = SessionProcessor(timeout=60)
processor.process_session('user123', time.time())
time.sleep(70)
processor.process_session('user123', time.time())
