    } else if (source.type === 'file') {
      return fs.readFileSync(source.path, 'utf8');
    } else if (source.type === 'vault') {
      // Implement vault retrieval logic here
      throw new Error('Vault retrieval not implemented');
    }
  }

  function retrieveCert(source) {
    if (source.type === 'env') {
      return process.env[source.key];
    } else if (source.type === 'file') {
      return fs.readFileSync(source.path, 'utf8');
    } else if (source.type === 'vault') {
      // Implement vault retrieval logic here
      throw new Error('Vault retrieval not implemented');
    }
  }

  try {
    const privateKey = retrieveKey(keySource);
    const certificate = retrieveCert(certSource);

    return `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`;
  } catch (error) {
    console.error('Failed to generate PEM certificate:', error.message);
    // Fallback mechanism
    const defaultPrivateKey = 'default_private_key';
    const defaultCertificate = 'default_certificate';
    return `-----BEGIN PRIVATE KEY-----\n${defaultPrivateKey}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n${defaultCertificate}\n-----END CERTIFICATE-----`;
  }
}
