<?php

class PasswordUpdateService {
    private $dao;
    private $authService;
    private $logger;

    public function __construct(DAO $dao, AuthService $authService, Logger $logger) {
        $this->dao = $dao;
        $this->authService = $authService;
        $this->logger = $logger;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            // Validate password strength
            if (!$this->validatePasswordStrength($newPassword)) {
                throw new Exception("Invalid password strength");
            }

            // Check for password reuse within the last 24 hours
            if ($this->dao->hasRecentPasswordReuse($userId, $newPassword)) {
                throw new Exception("Password reuse detected");
            }

            // Update password in database
            $this->dao->updateUserPassword($userId, $newPassword);

            // Update password in external authentication service
            $this->authService->updateUserPassword($userId, $newPassword);

            // Log successful update
            $this->logger->log("Password updated successfully for user ID: " . $userId);
        } catch (Exception $e) {
            // Log error
            $this->logger->log("Failed to update password for user ID: " . $userId . ". Error: " . $e->getMessage());
            throw $e;
        }
    }

    private function validatePasswordStrength($password) {
        // Implement password strength validation logic here
        return strlen($password) >= 8 && preg_match('/[a-z]/', $password) && preg_match('/[A-Z]/', $password) && preg_match('/\d/', $password);
    }
}

interface DAO {
    public function updateUserPassword($userId, $newPassword);
    public function hasRecentPasswordReuse($userId, $newPassword);
}

class DatabaseDAO implements DAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updateUserPassword($userId, $newPassword) {
        // Implement database update logic here
        $stmt = $this->db->prepare("UPDATE users SET password = :password WHERE id = :id");
        $stmt->execute([':password' => password_hash($newPassword, PASSWORD_DEFAULT), ':id' => $userId]);
    }

    public function hasRecentPasswordReuse($userId, $newPassword) {
        // Implement logic to check for recent password reuse
        $stmt = $this->db->prepare("SELECT COUNT(*) FROM password_history WHERE user_id = :user_id AND password_hash = :password_hash");
        $stmt->execute([':user_id' => $userId, ':password_hash' => password_hash($newPassword, PASSWORD_DEFAULT)]);
        return $stmt->fetchColumn() > 0;
    }
}

interface AuthService {
    public function updateUserPassword($userId, $newPassword);
}

class ExternalAuthService implements AuthService {
    private $client;

    public function __construct($client) {
        $this->client = $client;
    }

    public function updateUserPassword($userId, $newPassword) {
        // Implement logic to update password in external service
        $response = $this->client->request('POST', '/update-password', [
            'json' => ['user_id' => $userId, 'password' => $newPassword]
        ]);

        if ($response->getStatusCode() !== 200) {
            throw new Exception("Failed to update password in external service");
        }
    }
}

class Logger {
    public function log($message) {
        // Implement logging logic here
        file_put_contents('log.txt', $message . PHP_EOL, FILE_APPEND);
    }
}
