typedef struct {
    int *states;
    int count;
} FSA;

typedef void (*StateCallback)(int **new_states, int *new_count);

void* manage_state_transitions(int **current_states, int current_count, FSA *fsa, int last_state, int max_length, StateCallback callback) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    int *new_states = NULL;
    int new_count = 0;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Asynchronously retrieve additional states from the external source
    callback(&new_states, &new_count);

    // Wait for the state retrieval to complete
    while (new_states == NULL) {
        pthread_cond_wait(&cond, &lock);
    }

    // Check if there is sufficient memory for the new state list
    if (current_count + new_count > max_length) {
        free(new_states);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Allocate memory for the new state list
    int *new_state_list = realloc(*current_states, (current_count + new_count) * sizeof(int));
    if (new_state_list == NULL) {
        free(new_states);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Copy the new states into the existing state list
    for (int i = 0; i < new_count; i++) {
        new_state_list[current_count + i] = new_states[i];
    }

    // Update the current state list and count
    *current_states = new_state_list;
    (*fsa).count += new_count;

    // Free the memory for the temporary state list
    free(new_states);

    // Signal that the state retrieval is complete
    pthread_cond_signal(&cond);

    // Unlock the mutex to allow other threads access
    pthread_mutex_unlock(&lock);

    return *current_states;
}
