#define MAX_PACKETS 1000
#define MAX_SOURCE_PACKETS 100
#define MAX_SOURCE_SIZE 5 * 1024 * 1024 // 5MB

typedef struct {
    time_t timestamp;
    int size;
    char source_ip[16];
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int front, rear;
    int count;
} Queue;

Queue packet_queue;

void init_queue() {
    packet_queue.front = packet_queue.rear = -1;
    packet_queue.count = 0;
}

int is_empty() {
    return packet_queue.count == 0;
}

int is_full() {
    return packet_queue.count == MAX_PACKETS;
}

void enqueue(Packet packet) {
    if (is_full()) {
        printf("Queue is full\n");
        return;
    }
    if (is_empty()) {
        packet_queue.front = packet_queue.rear = 0;
    } else {
        packet_queue.rear = (packet_queue.rear + 1) % MAX_PACKETS;
    }
    packet_queue.packets[packet_queue.rear] = packet;
    packet_queue.count++;
}

Packet dequeue() {
    Packet packet;
    if (is_empty()) {
        printf("Queue is empty\n");
        packet.timestamp = -1;
        packet.size = -1;
        strcpy(packet.source_ip, "");
        return packet;
    }
    packet = packet_queue.packets[packet_queue.front];
    if (packet_queue.front == packet_queue.rear) {
        packet_queue.front = packet_queue.rear = -1;
    } else {
        packet_queue.front = (packet_queue.front + 1) % MAX_PACKETS;
    }
    packet_queue.count--;
    return packet;
}

int main() {
    init_queue();

    // Simulate incoming packets
    for (int i = 0; i < 200; i++) {
        Packet packet;
        time_t current_time = time(NULL);
        packet.timestamp = current_time - i * 5; // Simulate varying timestamps
        packet.size = rand() % 1000 + 1; // Random size between 1 and 1000 bytes
        snprintf(packet.source_ip, sizeof(packet.source_ip), "192.168.%d.%d", rand() % 256, rand() % 256);
        enqueue(packet);
    }

    // Process packets
    while (!is_empty()) {
        Packet packet = dequeue();
        if (time(NULL) - packet.timestamp > 10) {
            printf("Discarding old packet\n");
            continue;
        }
        // Additional filtering logic here

        // Simulate processing
        printf("Processing packet from %s, size %d bytes\n", packet.source_ip, packet.size);
    }

    return 0;
}
