class SharedMemoryCache {
public:
    static std::map<std::string, std::pair<int64_t, int>> cooldowns;
    static std::mutex cacheMutex;

    static bool getCooldown(const std::string& attackName, int64_t& lastUsed, int& count) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        auto it = cooldowns.find(attackName);
        if (it != cooldowns.end()) {
            lastUsed = it->second.first;
            count = it->second.second;
            return true;
        }
        return false;
    }

    static void setCooldown(const std::string& attackName, int64_t now, int count) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        cooldowns[attackName] = {now, count};
    }
};

