using System;
using System.Threading;

public class DynamicValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private readonly object _lock = new object();

    public DynamicValueGenerator(int seed)
    {
        _random = new Random(seed);
        _minValue = 0;
        _maxValue = 100;
    }

    public int MinValue
    {
        get => _minValue;
        set
        {
            lock (_lock)
            {
                if (value > _maxValue)
                    throw new ArgumentException("Min value cannot be greater than max value.");
                _minValue = value;
            }
        }
    }

    public int MaxValue
    {
        get => _maxValue;
        set
        {
            lock (_lock)
            {
                if (value < _minValue)
                    throw new ArgumentException("Max value cannot be less than min value.");
                _maxValue = value;
            }
        }
    }

    public float GenerateRandomFloat()
    {
        lock (_lock)
        {
            return _random.Next(_minValue, _maxValue + 1) / (float)(_maxValue - _minValue);
        }
    }

    public int GenerateRandomInt()
    {
        lock (_lock)
        {
            return _random.Next(_minValue, _maxValue + 1);
        }
    }

    public void ResetGenerator(int seed)
    {
        lock (_lock)
        {
            _random = new Random(seed);
        }
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator: Min={_minValue}, Max={_maxValue}";
    }
}
