function customReduceAsync(numbers, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let retries = 0;
    const maxRetries = 5;

    function performReduction(index, accumulatedValue) {
      if (index >= numbers.length) {
        resolve(accumulatedValue);
        return;
      }

      try {
        callback(accumulatedValue, numbers[index], { retries }, (err, result) => {
          if (err) {
            if (retries < maxRetries) {
              retries++;
              performReduction(index + 1, accumulatedValue);
            } else {
              reject(err);
            }
          } else {
            performReduction(index + 1, result);
          }
        });
      } catch (error) {
        if (retries < maxRetries) {
          retries++;
          performReduction(index + 1, accumulatedValue);
        } else {
          reject(error);
        }
      }
    }

    performReduction(0, initialValue);
  });
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;
const callback = (acc, num, context, cb) => {
  setTimeout(() => {
    if (num === 3) {
      cb(new Error('Transient error'));
    } else {
      cb(null, acc + num);
    }
  }, Math.random() * 1000); // Simulate async operation with random delay
};

customReduceAsync(numbers, initialValue, callback)
  .then(result => console.log('Final result:', result))
  .catch(error => console.error('Error:', error));
