UserProfile profiles[MAX_PROFILES];
int profile_count = 0;

void load_profiles_from_csv(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open CSV file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        UserProfile profile;
        sscanf(line, "%[^,],%d", profile.name, &profile.age);
        profiles[profile_count++] = profile;

        if (profile_count >= MAX_PROFILES) {
            printf("Profile limit reached. Increase MAX_PROFILES.\n");
            break;
        }
    }

    fclose(file);
}

int get_profile_count() {
    return profile_count;
}

// Additional functions for managing user profiles can be added here
