#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <time.h>
#include <unistd.h>

#define MAX_FILENAME_LENGTH 150

void rename_files(const char *directory_path, const char **filenames, int num_filenames) {
    DIR *dir;
    struct dirent *entry;
    time_t now = time(NULL);
    srand(now);

    if ((dir = opendir(directory_path)) == NULL) {
        perror("Error opening directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        for (int i = 0; i < num_filenames; i++) {
            if (strcmp(entry->d_name, filenames[i]) == 0) {
                char old_path[MAX_FILENAME_LENGTH];
                char new_path[MAX_FILENAME_LENGTH];
                char *ext = strrchr(entry->d_name, '.');
                int name_length = strlen(entry->d_name);
                int unique_id = rand() % 10000;
                time_t timestamp = now;

                if (ext != NULL) {
                    snprintf(old_path, MAX_FILENAME_LENGTH, "%s/%s", directory_path, entry->d_name);
                    snprintf(new_path, MAX_FILENAME_LENGTH, "%s/%.*s_%ld_%d_%04d%s",
                             directory_path, name_length - strlen(ext), entry->d_name,
                             timestamp, unique_id, rand() % 10000, ext);

                    while (access(new_path, F_OK) == 0) {
                        unique_id++;
                        snprintf(new_path, MAX_FILENAME_LENGTH, "%s/%.*s_%ld_%d_%04d%s",
                                 directory_path, name_length - strlen(ext), entry->d_name,
                                 timestamp, unique_id, rand() % 10000, ext);
                    }

                    if (rename(old_path, new_path) != 0) {
                        perror("Error renaming file");
                    }
                }
            }
        }
    }

    closedir(dir);
}

int main() {
    const char *directory_path = "/path/to/directory";
    const char *filenames[] = {"file1.txt", "file2.jpg"};
    int num_filenames = sizeof(filenames) / sizeof(filenames[0]);

    rename_files(directory_path, filenames, num_filenames);

    return 0;
}
