#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_COMMANDS 10

typedef struct {
    pid_t pid;
    int status;
} BackgroundProcess;

BackgroundProcess background_processes[MAX_COMMANDS];
int process_count = 0;

void execute_command(const char *command) {
    if (process_count >= MAX_COMMANDS) {
        fprintf(stderr, "Maximum number of concurrent processes reached.\n");
        return;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    } else if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        background_processes[process_count].pid = pid;
        background_processes[process_count].status = 0;
        process_count++;
    }
}

void wait_for_all_processes() {
    for (int i = 0; i < process_count; i++) {
        int status;
        if (waitpid(background_processes[i].pid, &status, 0) == -1) {
            perror("waitpid");
        } else {
            background_processes[i].status = WEXITSTATUS(status);
        }
    }
    process_count = 0;
}

void signal_handler(int signum) {
    for (int i = 0; i < process_count; i++) {
        if (kill(background_processes[i].pid, SIGTERM) == -1) {
            perror("kill");
        }
    }
    wait_for_all_processes();
    exit(signum);
}

int main() {
    // Register signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGHUP, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Example commands
    execute_command("sleep 5");
    execute_command("echo Hello World");

    // Wait for all processes to complete
    wait_for_all_processes();

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of the described functionality. It includes functions to execute commands in the background, wait for their completion, and handle signals to terminate background processes gracefully. The main function demonstrates how to use these functions with example commands.']

