public class WebsiteManager
{
    private readonly string _logServiceUrl = "https://logs.example.com/api/log";
    private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(10, 100);
    private static readonly ConcurrentDictionary<string, DateTime> _lastAdditionTimes = new ConcurrentDictionary<string, DateTime>();

    public async Task<OperationStatus> AddWebsiteAsync(string directoryPath, string siteName, int timeoutSeconds = 30)
    {
        if (!Directory.Exists(directoryPath) || !File.Exists(Path.Combine(directoryPath, "web.config")))
            return new OperationStatus { Success = false, Errors = new[] { "Invalid directory or missing web.config" } };

        if (_lastAdditionTimes.TryGetValue(siteName, out DateTime lastAdditionTime) && (DateTime.Now - lastAdditionTime).TotalSeconds < 1)
            return new OperationStatus { Success = false, Errors = new[] { "Site already exists within the last second" } };

        try
        {
            await _semaphore.WaitAsync();
            if (_lastAdditionTimes.TryGetValue(siteName, out lastAdditionTime) && (DateTime.Now - lastAdditionTime).TotalSeconds < 1)
                return new OperationStatus { Success = false, Errors = new[] { "Site already exists within the last second" } };

            var stopwatch = Stopwatch.StartNew();
            using (var httpClient = new HttpClient())
            {
                for (int attempt = 0; attempt <= 5; attempt++)
                {
                    try
                    {
                        await LogAsync($"Adding site '{siteName}' to directory '{directoryPath}'", "INFO");
                        // Simulate website initialization
                        await Task.Delay(1000); // Replace with actual initialization logic
                        _lastAdditionTimes[siteName] = DateTime.Now;
                        return new OperationStatus { Success = true, Duration = stopwatch.Elapsed };
                    }
                    catch (Exception ex)
                    {
                        if (!IsTransientError(ex))
                            throw;

                        await LogAsync($"Attempt {attempt + 1} failed: {ex.Message}", "ERROR");
                        await Task.Delay(100); // Wait before retrying
                    }
                }
            }
        }
        finally
        {
            _semaphore.Release();
        }

        return new OperationStatus { Success = false, Errors = new[] { "Failed to add site after multiple attempts" } };
    }

    private async Task LogAsync(string message, string level)
    {
        try
        {
            using (var content = new StringContent(message))
            {
                await HttpClient.PostAsync(_logServiceUrl, content);
            }
        }
        catch
        {
            // Fallback logging strategy if external service is unavailable
            Console.WriteLine($"{DateTime.Now}: {level} - {message}");
        }
    }

    private bool IsTransientError(Exception ex)
    {
        // Implement logic to determine if the error is transient
        return true; // Placeholder
    }

