using System;
using System.Security.Cryptography;
using System.Text;

public struct ConnectionSettings
{
    public string Title { get; set; }
}

public delegate void CallbackFunction(string message);

public class ConnectionProcessor
{
    private const int InsufficientCredentials = -1;
    private const int IncompleteConfiguration = -2;
    private const int MissingCallback = -3;
    private const int EncodingIssues = -4;
    private const int DecryptionFailure = -5;

    public string ProcessConnection(ConnectionConfig config, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(config.Password))
        {
            return InsufficientCredentials.ToString();
        }

        if (string.IsNullOrEmpty(config.ConnectionSettings.Title))
        {
            return IncompleteConfiguration.ToString();
        }

        if (config.CallbackFunction == null)
        {
            return MissingCallback.ToString();
        }

        try
        {
            byte[] messageBytes = Convert.FromBase64String(config.Message);
            using (TripleDES des = TripleDES.Create())
            {
                des.Key = key;
                des.IV = iv;
                des.Mode = CipherMode.CBC;
                des.Padding = PaddingMode.PKCS7;

                ICryptoTransform decryptor = des.CreateDecryptor();
                byte[] decryptedBytes = decryptor.TransformFinalBlock(messageBytes, 0, messageBytes.Length);
                return Encoding.UTF8.GetString(decryptedBytes);
            }
        }
        catch (FormatException)
        {
            return EncodingIssues.ToString();
        }
        catch (CryptographicException)
        {
            return DecryptionFailure.ToString();
        }
    }
}

public struct ConnectionConfig
{
    public string Password { get; set; }
    public ConnectionSettings ConnectionSettings { get; set; }
    public CallbackFunction CallbackFunction { get; set; }
    public string Message { get; set; }
}
