    public async Task DecryptLogFileAsync(string filePath)
    {
        if (string.IsNullOrEmpty(filePath))
        {
            _logger.Log("Error: File path is empty.");
            return;
        }

        try
        {
            using (var reader = new StreamReader(filePath, Encoding.UTF8))
            {
                string line;
                while ((line = await reader.ReadLineAsync()) != null)
                {
                    await DecryptMessageAsync(line);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Log($"Error reading file: {ex.Message}");
        }
    }

    private async Task DecryptMessageAsync(string base64EncodedMessage)
    {
        try
        {
            var messageBytes = Convert.FromBase64String(base64EncodedMessage);
            using (var decryptor = Aes.Create())
            {
                decryptor.Key = _key;
                decryptor.IV = _iv;
                decryptor.Mode = CipherMode.CBC;
                decryptor.Padding = PaddingMode.PKCS7;

                using (var msDecrypt = new MemoryStream(messageBytes))
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor.CreateDecryptor(), CryptoStreamMode.Read))
                using (var srDecrypt = new StreamReader(csDecrypt))
                {
                    string decryptedMessage = await srDecrypt.ReadToEndAsync();
                    _logger.Log($"Decrypted: {decryptedMessage}");
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Log($"Error decrypting message: {ex.Message}");
        }
    }

    public interface ILogger
    {
        void Log(string message);
    }
}
```

This code snippet defines a `LogDecryptor` class that processes a log file containing encrypted messages. It uses asynchronous methods to handle decryption without blocking the main application thread. The class supports a configurable logging mechanism and handles various edge cases, ensuring efficient resource management and responsiveness under heavy load.']

