using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHashProcessor
{
    private readonly HttpClient _httpClient;
    private const int MaxRetries = 5;
    private static readonly Random _random = new Random();

    public FileHashProcessor()
    {
        _httpClient = new HttpClient();
    }

    public async Task<Dictionary<string, string>> ProcessFilePathsAsync(List<string> filePaths)
    {
        var fileHashes = new Dictionary<string, string>();

        foreach (var path in filePaths)
        {
            try
            {
                if (!Path.IsPathFullyQualified(path))
                {
                    throw new ArgumentException("Invalid file path.", nameof(path));
                }

                if (!File.Exists(path) && !await IsRemoteFileAccessibleAsync(path))
                {
                    throw new FileNotFoundException($"File not found: {path}");
                }

                var hash = await CalculateHashAsync(path);
                fileHashes[path] = hash;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing file {path}: {ex.Message}");
            }
        }

        return fileHashes;
    }

    private async Task<bool> IsRemoteFileAccessibleAsync(string path)
    {
        var uri = new Uri(path);
        for (int attempt = 0; attempt < MaxRetries; attempt++)
        {
            try
            {
                using (var response = await _httpClient.GetAsync(uri, HttpCompletionOption.ResponseHeadersRead))
                {
                    if (response.IsSuccessStatusCode)
                    {
                        return true;
                    }
                }
            }
            catch (HttpRequestException)
            {
                // Ignore and retry on network errors
            }

            await Task.Delay(GetExponentialBackoffDelay(attempt));
        }

        return false;
    }

    private async Task<string> CalculateHashAsync(string path)
    {
        using (var sha256 = SHA256.Create())
        using (var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, true))
        {
            return BitConverter.ToString(sha256.ComputeHash(stream)).Replace("-", "").ToLower();
        }
    }

    private static TimeSpan GetExponentialBackoffDelay(int attempt)
    {
        var delay = (int)Math.Pow(2, attempt) * 100; // Exponential backoff with base 2
        return TimeSpan.FromMilliseconds(delay + _random.Next(0, 50)); // Add some jitter
    }
}
