['```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    public byte[] Decrypt(byte[] ciphertext, byte[] macValue, byte[] key, byte[] iv, EncryptionConfig config = null)
    {
        // Validate input sizes
        if (ciphertext.Length > 10 * 1024 * 1024 || macValue.Length != 32)
            throw new ArgumentException("Invalid input size");

        // Perform HMAC check
        byte[] computedMac = ComputeHmac(ciphertext, key);
        if (!computedMac.SequenceEqual(macValue))
            throw new InvalidOperationException("MAC verification failed");

        // Initialize AES-CBC decryptor
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = config?.PaddingMode ?? PaddingMode.PKCS7;

            // Decrypt data
            using (ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV))
            {
                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        byte[] plaintext = new byte[ciphertext.Length];
                        int bytesRead = csDecrypt.Read(plaintext, 0, plaintext.Length);
                        Array.Resize(ref plaintext, bytesRead);
                        return plaintext;
                    }
                }
            }
        }
    }

    private byte[] ComputeHmac(byte[] data, byte[] key)
    {
        using (HMACSHA256 hmac = new HMACSHA256(key))
        {
            return hmac.ComputeHash(data);
        }
    }
}

public class EncryptionConfig
{
    public PaddingMode PaddingMode { get; set; } = PaddingMode.PKCS7;
}
```

