["```javascript
const axios = require('axios');
const crypto = require('crypto');

async function uploadFileWithRetry(url, minIntValue, maxIntValue, retries = 5, delay = 100) {
    for (let attempt = 0; attempt <= retries; attempt++) {
        try {
            const response = await axios.post(url, { int: crypto.randomInt(minIntValue, maxIntValue + 1) });
            console.log(`File uploaded successfully with int value: ${response.data.int}`);
            return response;
        } catch (error) {
            if (attempt === retries) {
                console.error('Failed to upload file after multiple attempts');
                throw error;
            }
            const backoff = Math.pow(2, attempt) * delay;
            console.log(`Attempt ${attempt + 1} failed. Retrying in ${backoff}ms...`);
            await new Promise(resolve => setTimeout(resolve, backoff));
        }
    }
}

// Example usage
uploadFileWithRetry('https://example.com/upload', 100, 200)
    .then(response => {
        console.log('Final response:', response);
    })
    .catch(error => {
        console.error('Error uploading file:', error);
    });
```

This code snippet demonstrates a basic implementation of the described functionality. It uses `axios` for making HTTP requests and `crypto` for generating random integers. The function `uploadFileWithRetry` attempts to upload a file with a random integer value within a specified range, handling retries with exponential backoff in case of failures. Error logging is included for auditing purposes."]

