use std::env;
use tokio::task;
use log::{info, error};
use reqwest::Client;
use chrono::Utc;

mod api;
mod cache;
mod config;
mod logger;

#[tokio::main]
async fn main() {
    // Initialize logging
    logger::init();

    // Parse command line arguments
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        error!("Usage: {} <api_name>", args[0]);
        return;
    }
    let api_name = &args[1];

    // Load configuration
    let config = config::load_config();

    // Initialize cache
    let cache = cache::init_cache();

    // Create HTTP client
    let client = Client::new();

    // Execute asynchronous function based on the API name
    match api_name {
        "api1" => execute_api1(&client, &cache, &config).await,
        "api2" => execute_api2(&client, &cache, &config).await,
        _ => error!("Unknown API: {}", api_name),
    }
}

async fn execute_api1(client: &Client, cache: &cache::Cache, config: &config::Config) {
    // Check cache
    if let Some(data) = cache.get("api1") {
        info!("Using cached data for API1");
        return;
    }

    // Fetch data from external API
    let start_time = Utc::now();
    match client.get(&config.api1_url).send().await {
        Ok(response) => {
            if response.status().is_success() {
                let data = response.text().await.unwrap_or_else(|e| format!("Error: {}", e));
                cache.set("api1", data.clone());
                info!("Fetched data for API1 in {:?}", Utc::now() - start_time);
                // Process data
            } else {
                error!("API1 request failed with status: {}", response.status());
            }
        },
        Err(e) => error!("Error fetching data from API1: {}", e),
    }
}

async fn execute_api2(client: &Client, cache: &cache::Cache, config: &config::Config) {
    // Check cache
    if let Some(data) = cache.get("api2") {
        info!("Using cached data for API2");
        return;
    }

    // Fetch data from external API
    let start_time = Utc::now();
    match client.get(&config.api2_url).send().await {
        Ok(response) => {
            if response.status().is_success() {
                let data = response.text().await.unwrap_or_else(|e| format!("Error: {}", e));
                cache.set("api2", data.clone());
                info!("Fetched data for API2 in {:?}", Utc::now() - start_time);
                // Process data
            } else {
                error!("API2 request failed with status: {}", response.status());
            }
        },
        Err(e) => error!("Error fetching data from API2: {}", e),
    }
}
