import json
from threading import Lock

class DynamicJsonParser:
    _registry = {}
    _lock = Lock()

    @staticmethod
    def add_factory(factory_id, factory_function):
        with DynamicJsonParser._lock:
            if factory_id in DynamicJsonParser._registry:
                raise ValueError(f"Factory ID '{factory_id}' already exists.")
            DynamicJsonParser._registry[factory_id] = factory_function

    @staticmethod
    def create_instance(factory_id, json_data):
        with DynamicJsonParser._lock:
            if factory_id not in DynamicJsonParser._registry:
                raise KeyError(f"No factory found for ID '{factory_id}'.")
            factory_function = DynamicJsonParser._registry[factory_id]
            return factory_function(json_data)

    @staticmethod
    def to_json(data):
        return json.dumps(data, indent=4)

    @staticmethod
    def from_json(json_string):
        return json.loads(json_string)

class VersionedFactory:
    def __init__(self, version, factory_function):
        self.version = version
        self.factory_function = factory_function

    def create_instance(self, json_data):
        return self.factory_function(json_data)

# Example usage
def custom_factory(json_data):
    # Custom logic for creating instances
    pass

DynamicJsonParser.add_factory('custom', VersionedFactory(1, custom_factory).create_instance)
instance = DynamicJsonParser.create_instance('custom', '{"key": "value"}')
