#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    size_t size;
    void* data_block;
} record;

long generate_random_number(long min, long max) {
    return min + rand() % (max - min + 1);
}

void process_and_find_max(int num_records, int min_value, int max_value) {
    srand(time(NULL));
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return;
    }

    long* offsets = malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        free(records);
        return;
    }

    int* keys = malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        free(records);
        free(offsets);
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = generate_random_number(min_value, max_value);
        offsets[i] = generate_random_number(0, num_records * sizeof(record));
