#include <stdio.h>
#include <stdlib.h>

// Function to find the largest integer and its index
void findLargestInteger() {
    int *array = NULL;
    size_t count = 0;
    ssize_t read;

    // Read integers from standard input
    while ((read = scanf("%d", &array[count])) != EOF) {
        if (read == -1) {
            fprintf(stderr, "Error reading integer.\n");
            free(array);
            return;
        }
        count++;
        array = realloc(array, count * sizeof(int));
        if (!array) {
            fprintf(stderr, "Memory allocation failed.\n");
            return;
        }
    }

    // Check for empty input list
    if (count == 0) {
        printf("No integers provided.\n");
        free(array);
        return;
    }

    // Find the largest integer and its index
    int max = array[0];
    size_t maxIndex = 0;
    for (size_t i = 1; i < count; i++) {
        if (array[i] > max) {
            max = array[i];
            maxIndex = i;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d, Index: %zu\n", max, maxIndex);

    // Free dynamically allocated memory
    free(array);
}

int main() {
    findLargestInteger();
    return 0;
}
