class PEMCertificateGenerator {
  constructor() {
    this.cache = new Map();
    this.logFile = 'pem_generator.log';
  }

  async generatePEMCertificate(oauthRequest) {
    const { privateKeyUrl, certificateUrl } = oauthRequest;
    const cacheKey = `${privateKeyUrl}-${certificateUrl}`;

    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    try {
      const [privateKey, certificate] = await Promise.all([
        this.fetchSecureData(privateKeyUrl),
        this.fetchSecureData(certificateUrl)
      ]);

      const pemCertificate = this.createPEM(privateKey, certificate);
      this.cache.set(cacheKey, pemCertificate);

      return pemCertificate;
    } catch (error) {
      this.logError(error);
      throw error;
    }
  }

  async fetchSecureData(url) {
    try {
      const response = await fetch(url, { method: 'GET', headers: { 'Authorization': 'Bearer YOUR_TOKEN' } });
      if (!response.ok) {
        throw new Error(`Failed to fetch data from ${url}`);
      }
      return response.text();
    } catch (error) {
      this.logError(error);
      throw error;
    }
  }

  createPEM(privateKey, certificate) {
    const pem = `-----BEGIN PRIVATE KEY-----\n${privateKey}\n-----END PRIVATE KEY-----\n`;
    pem += `-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----\n`;
    return pem;
  }

  logError(error) {
    const timestamp = new Date().toISOString();
    const sanitizedMessage = this.sanitizeLogMessage(error.message);
    fs.appendFileSync(this.logFile, `${timestamp} - ERROR: ${sanitizedMessage}\n`);
  }

  sanitizeLogMessage(message) {
    // Implement sanitization logic here
    return message;
  }
}

module.exports = PEMCertificateGenerator;
