// Define packet structure
typedef struct {
    time_t timestamp;
    size_t size;
    char source_ip[16];
} Packet;

// Define queue structure
typedef struct {
    Packet *packets;
    int front, rear, capacity;
} Queue;

// Initialize queue
Queue* create_queue(int capacity) {
    Queue *queue = (Queue*)malloc(sizeof(Queue));
    queue->capacity = capacity;
    queue->front = queue->rear = -1;
    queue->packets = (Packet*)malloc(queue->capacity * sizeof(Packet));
    return queue;
}

// Check if queue is full
int is_full(Queue *queue) {
    return ((queue->rear + 1) % queue->capacity == queue->front);
}

// Check if queue is empty
int is_empty(Queue *queue) {
    return (queue->front == -1);
}

// Enqueue packet
void enqueue(Queue *queue, Packet packet) {
    if (is_full(queue)) {
        printf("Queue is full\n");
        return;
    }
    if (is_empty(queue))
        queue->front = 0;
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->packets[queue->rear] = packet;
}

// Dequeue packet
Packet dequeue(Queue *queue) {
    Packet packet;
    if (is_empty(queue)) {
        printf("Queue is empty\n");
        return (Packet){0};
    }
    packet = queue->packets[queue->front];
    if (queue->front == queue->rear)
        queue->front = queue->rear = -1;
    else
        queue->front = (queue->front + 1) % queue->capacity;
    return packet;
}

// Filter packets based on criteria
void filter_packets(Queue *queue, int max_age, size_t max_size_per_source, size_t max_total_size_per_source) {
    time_t current_time = time(NULL);
    for (int i = queue->front; i != -1; i = (i + 1) % queue->capacity) {
        Packet packet = queue->packets[i];
        if (current_time - packet.timestamp > max_age || packet.size > max_size_per_source) {
            dequeue(queue);
        }
    }
}

// Update metrics and rate limits
