using System;
using System.Collections.Concurrent;
using System.Threading;

public class DynamicDataProcessor
{
    private readonly int bufferSizeLimit;
    private readonly TimeSpan delayThreshold;
    private readonly ConcurrentQueue<byte[]> dataBuffer = new ConcurrentQueue<byte[]>();
    private DateTime lastProcessedTimestamp;

    public DynamicDataProcessor(int bufferSizeLimit, TimeSpan delayThreshold)
    {
        if (bufferSizeLimit <= 0) throw new ArgumentException("Buffer size limit must be greater than zero.");
        if (delayThreshold < TimeSpan.Zero) throw new ArgumentException("Delay threshold cannot be negative.");

        this.bufferSizeLimit = bufferSizeLimit;
        this.delayThreshold = delayThreshold;
        lastProcessedTimestamp = DateTime.UtcNow;
    }

    public int CurrentBufferSize => dataBuffer.Count;

    public void AddData(byte[] dataChunk)
    {
        if (dataChunk == null || dataChunk.Length == 0) return;

        dataBuffer.Enqueue(dataChunk);
        CheckAndProcessBatch();
    }

    private void CheckAndProcessBatch()
    {
        if (CurrentBufferSize >= bufferSizeLimit || DateTime.UtcNow - lastProcessedTimestamp > delayThreshold)
        {
            ProcessBatch();
        }
    }

    private void ProcessBatch()
    {
        while (dataBuffer.TryDequeue(out byte[] dataChunk))
        {
            // Process the data chunk
        }

        lastProcessedTimestamp = DateTime.UtcNow;
    }

    public void FlushBuffer()
    {
        while (dataBuffer.TryDequeue(out _)) { }
        lastProcessedTimestamp = DateTime.UtcNow;
    }

    public bool CompareState(DynamicDataProcessor other)
    {
        if (other == null) return false;

        return dataBuffer.SequenceEqual(other.dataBuffer) && CurrentBufferSize == other.CurrentBufferSize;
    }
}
