#include <string.h>

typedef void (*CallbackFunction)(char*);

void processLargeTextFile(const char* filePath, size_t maxBufferSize, CallbackFunction callback) {
    FILE* file = fopen(filePath, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char* buffer = (char*)malloc(maxBufferSize);
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        fclose(file);
        return;
    }

    size_t bufferSize = 0;
    while (fgets(buffer + bufferSize, maxBufferSize - bufferSize, file)) {
        size_t lineLength = strlen(buffer + bufferSize);
        if (lineLength == maxBufferSize - bufferSize - 1) {
            // Line is too long for the buffer, process what we have and reset
            buffer[bufferSize] = '\0';
            callback(buffer);
            bufferSize = 0;
        } else {
            bufferSize += lineLength;
        }
    }

    if (bufferSize > 0) {
        buffer[bufferSize] = '\0';
        callback(buffer);
    }

    free(buffer);
    fclose(file);
}
