    Record data;
    struct node *next;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Record data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int find_largest(int arr[], int n) {
    if (n <= 0) {
        return -1; // Handle edge case
    }
    int largest = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void free_memory(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int n, min_val, max_val;
    printf("Enter the number of records: ");
    scanf("%d", &n);
    printf("Enter the range for random values (min max): ");
    scanf("%d %d", &min_val, &max_val);

    Record* records = (Record*)malloc(n * sizeof(Record));
    if (records == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        records[i].size = sizeof(int);
        records[i].offset = (long*)malloc(records[i].size);
        if (records[i].offset == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }

    int* arr = (int*)malloc(n * sizeof(int));
    if (arr == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers: ", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        insert_node(&head, records[i]);
    }

    int largest = find_largest(arr, n);
    printf("Largest integer: %d\n", largest);

    free_memory(head);
    free(records);
    free(arr);

    return 0;
}
