// Define a structure for each record
typedef struct {
    int random_value;
    char* string_ptr;
} Record;

// Function to initialize the records with random values and strings
int init_records(Record** records, size_t num_records, const char* string_list[], size_t list_size, size_t memory_limit) {
    if (records == NULL || string_list == NULL || num_records == 0 || list_size == 0 || memory_limit == 0) {
        return -1; // Invalid input
    }

    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        return -2; // Memory allocation failed
    }

    size_t total_memory_used = num_records * sizeof(Record);
    for (size_t i = 0; i < num_records && total_memory_used <= memory_limit; ++i) {
        (*records)[i].random_value = rand() % list_size;
        (*records)[i].string_ptr = strdup(string_list[(*records)[i].random_value]);
        if ((*records)[i].string_ptr == NULL) {
            // Free previously allocated records
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j].string_ptr);
            }
            free(*records);
            return -3; // Memory allocation failed
        }
        total_memory_used += strlen((*records)[i].string_ptr) + 1;
    }

    if (total_memory_used > memory_limit) {
        // Free partially allocated records
        for (size_t i = 0; i < num_records; ++i) {
            free((*records)[i].string_ptr);
        }
        free(*records);
        return -4; // Memory limit exceeded
    }

    return 0; // Success
}

// Function to clean up the records and free allocated memory
void cleanup_records(Record* records, size_t num_records) {
    if (records != NULL) {
        for (size_t i = 0; i < num_records; ++i) {
            free(records[i].string_ptr);
        }
        free(records);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    const char* string_list[] = {"apple", "banana", "cherry"};
    size_t list_size = sizeof(string_list) / sizeof(string_list[0]);
    size_t num_records = 10;
    size_t memory_limit = 1024 * 1024; // 1MB

    Record* records;
    int result = init_records(&records, num_records, string_list, list_size, memory_limit);
    if (result != 0) {
        printf("Initialization failed with error code: %d\n", result);
        return 1;
    }

    // Use the records...

    cleanup_records(records, num_records);

    return 0;
}
