            exit(EXIT_FAILURE);
        }

        // Monitor memory usage and ensure it does not exceed the limit
        size_t currentMemoryUsage = sizeof(Record) + strlen(identifiers[i]) + externalLibraryGetResourceSize(records[i]->externalResource);
