#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    int ref_count;
    pthread_mutex_t lock;
} Record;

typedef struct RecordManager {
    Record** records;
    size_t max_capacity;
    size_t current_size;
    pthread_mutex_t manager_lock;
} RecordManager;

Record* create_record(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    record->ref_count = 1;
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

RecordManager* create_record_manager(size_t max_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;
    manager->records = (Record**)calloc(max_capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }
    manager->max_capacity = max_capacity;
    manager->current_size = 0;
    pthread_mutex_init(&manager->manager_lock, NULL);
    return manager;
}

int record_manager_add(RecordManager* manager, int key, long offset) {
    pthread_mutex_lock(&manager->manager_lock);
    if (manager->current_size >= manager->max_capacity) {
        pthread_mutex_unlock(&manager->manager_lock);
        return -1; // Capacity exceeded
    }
    Record* new_record = create_record(key, offset);
    if (!new_record) {
        pthread_mutex_unlock(&manager->manager_lock);
        return -2; // Memory allocation failed
    }
    manager->records[manager->current_size++] = new_record;
    pthread_mutex_unlock(&manager->manager_lock);
    return 0;
}

void record_manager_free(RecordManager* manager) {
    pthread_mutex_lock(&manager->manager_lock);
    for (size_t i = 0; i < manager->current_size; ++i) {
        Record* record = manager->records[i];
        pthread_mutex_destroy(&record->lock);
        free(record);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->manager_lock);
    free(manager);
}

void record_manager_gc(RecordManager* manager) {
    pthread_mutex_lock(&manager->manager_lock);
    for (size_t i = 0; i < manager->current_size; ++i) {
        Record* record = manager->records[i];
        if (record->ref_count == 0) {
            pthread_mutex_destroy(&record->lock);
            free(record);
            manager->records[i] = NULL;
            // Shift elements to fill the gap
            for (size_t j = i; j < manager->current_size - 1; ++j) {
                manager->records[j] = manager->records[j + 1];
            }
            --manager->current_size;
            --i; // Adjust index after shifting
        }
    }
    pthread_mutex_unlock(&manager->manager_lock);
}
