#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <openssl/md5.h>

#define MAX_FILENAME_LENGTH 200

void rename_files(const char *source_dir, const char *target_dir, const char **filenames, int num_files, const char *template) {
    DIR *dir;
    struct dirent *entry;
    char source_path[1024];
    char target_path[1024];
    char new_filename[MAX_FILENAME_LENGTH];
    time_t now = time(NULL);
    unsigned long unique_id = strlen(filenames[0]);
    int random_number = rand() % 9000 + 1000; // Random 4-digit number
    MD5_CTX md5;
    unsigned char digest[MD5_DIGEST_LENGTH];
    char hash_str[33];

    if ((dir = opendir(source_dir)) == NULL) {
        perror("Failed to open source directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        for (int i = 0; i < num_files; i++) {
            if (strcmp(entry->d_name, filenames[i]) == 0) {
                snprintf(source_path, sizeof(source_path), "%s/%s", source_dir, entry->d_name);
                snprintf(target_path, sizeof(target_path), "%s/%s", target_dir, entry->d_name);

                FILE *file = fopen(source_path, "rb");
                if (file == NULL) {
                    perror("Failed to open file for reading");
                    continue;
                }

                fseek(file, 0, SEEK_END);
                long file_size = ftell(file);
                fseek(file, 0, SEEK_SET);

                unsigned char *buffer = malloc(file_size);
                if (buffer == NULL) {
                    perror("Failed to allocate memory for file content");
                    fclose(file);
                    continue;
                }

                fread(buffer, 1, file_size, file);
                fclose(file);

                MD5_Init(&md5);
                MD5_Update(&md5, buffer, file_size);
                MD5_Final(digest, &md5);

                snprintf(hash_str, sizeof(hash_str), "%02x%02x%02x%02x", digest[0], digest[1], digest[2], digest[3]);

                snprintf(new_filename, sizeof(new_filename), template, now, unique_id, random_number, hash_str);
                new_filename[MAX_FILENAME_LENGTH - 1] = '\0';

                char *new_target_path = malloc(strlen(target_dir) + strlen(new_filename) + 2);
                if (new_target_path == NULL) {
                    perror("Failed to allocate memory for new target path");
                    free(buffer);
                    continue;
                }

                snprintf(new_target_path, sizeof(new_target_path), "%s/%s", target_dir, new_filename);

                if (rename(source_path, new_target_path) != 0) {
                    perror("Failed to rename file");
                } else {
                    printf("Renamed %s to %s\n", source_path, new_target_path);
                }

                free(new_target_path);
                free(buffer);
            }
        }
    }

    closedir(dir);
}

int main() {
    const char *source_dir = "/path/to/source";
    const char *target_dir = "/path/to/target";
    const char *filenames[] = {"file1.txt", "file2.txt"};
    int num_files = sizeof(filenames) / sizeof(filenames[0]);
    const char *template = "new_%lu_%d_%s_%s";

    srand(time(NULL));
    rename_files(source_dir, target_dir, filenames, num_files, template);

    return 0;
}
