#include <stdlib.h>
#include <string.h>
#include "task_scheduler_library.h"

typedef struct {
    char* name;
    int priority;
    time_t execution_time;
    void* dependencies;
    void* resource_requirements;
} Task;

typedef struct {
    Task** tasks;
    size_t capacity;
    size_t size;
    size_t memory_limit;
} TaskCollection;

TaskCollection* create_task_collection(size_t initial_capacity, size_t memory_limit) {
    TaskCollection* collection = (TaskCollection*)malloc(sizeof(TaskCollection));
    if (!collection) return NULL;

    collection->tasks = (Task**)malloc(initial_capacity * sizeof(Task*));
    if (!collection->tasks) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->memory_limit = memory_limit;

    return collection;
}

void destroy_task_collection(TaskCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->tasks[i]->name);
        free(collection->tasks[i]->dependencies);
        free(collection->tasks[i]->resource_requirements);
        free(collection->tasks[i]);
    }
    free(collection->tasks);
    free(collection);
}

int add_task(TaskCollection* collection, const char* name, int priority, time_t execution_time, void* dependencies, void* resource_requirements) {
    if (collection->size >= collection->capacity) {
        Task** new_tasks = (Task**)realloc(collection->tasks, collection->capacity * 2 * sizeof(Task*));
        if (!new_tasks) return -1;
        collection->tasks = new_tasks;
        collection->capacity *= 2;
    }

    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) return -1;

    task->name = strdup(name);
    task->priority = priority;
    task->execution_time = execution_time;
    task->dependencies = dependencies;
    task->resource_requirements = resource_requirements;

    collection->tasks[collection->size++] = task;

    return 0;
}

int schedule_tasks(TaskCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        if (!schedule_task(collection->tasks[i])) {
            return -1;
        }
    }

    return 0;
}
