#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_OFFSETS_SIZE 100
#define INITIAL_KEYS_SIZE 100
#define INITIAL_RECORDS_SIZE 50

typedef struct {
    int *offsets;
    int offsets_size;
    int offsets_capacity;

    int *keys;
    int keys_size;
    int keys_capacity;

    long *records;
    int records_size;
    int records_capacity;
} DataStructures;

DataStructures ds;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_data_structures() {
    ds.offsets = (int *)malloc(INITIAL_OFFSETS_SIZE * sizeof(int));
    ds.keys = (int *)malloc(INITIAL_KEYS_SIZE * sizeof(int));
    ds.records = (long *)malloc(INITIAL_RECORDS_SIZE * sizeof(long));

    ds.offsets_size = 0;
    ds.keys_size = 0;
    ds.records_size = 0;

    ds.offsets_capacity = INITIAL_OFFSETS_SIZE;
    ds.keys_capacity = INITIAL_KEYS_SIZE;
    ds.records_capacity = INITIAL_RECORDS_SIZE;
}

void resize_offsets() {
    ds.offsets_capacity *= 2;
    ds.offsets = (int *)realloc(ds.offsets, ds.offsets_capacity * sizeof(int));
}

void resize_keys() {
    ds.keys_capacity *= 2;
    ds.keys = (int *)realloc(ds.keys, ds.keys_capacity * sizeof(int));
}

void resize_records() {
    ds.records_capacity += 10;
    ds.records = (long *)realloc(ds.records, ds.records_capacity * sizeof(long));
}

void insert_record(int key, long record) {
    pthread_mutex_lock(&lock);

    int index = -1;
    for (int i = 0; i < ds.keys_size; i++) {
        if (ds.keys[i] == key) {
            index = i;
            break;
        }
    }

    if (index != -1) {
        ds.records[index] = record;
    } else {
        if (ds.keys_size >= ds.keys_capacity) resize_keys();
        if (ds.offsets_size >= ds.offsets_capacity) resize_offsets();

        ds.keys[ds.keys_size++] = key;
        ds.offsets[ds.offsets_size++] = ds.records_size;

        if (ds.records_size >= ds.records_capacity) resize_records();
        ds.records[ds.records_size++] = record;
    }

    pthread_mutex_unlock(&lock);
}

long retrieve_record(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < ds.keys_size; i++) {
        if (ds.keys[i] == key) {
            pthread_mutex_unlock(&lock);
            return ds.records[ds.offsets[i]];
        }
    }

    pthread_mutex_unlock(&lock);
    return -1; // Key not found
}

void free_data_structures() {
    free(ds.offsets);
    free(ds.keys);
    free(ds.records);
}
