typedef enum { PLANNED, STARTED, COMPLETED } ProjectStatus;

typedef struct {
    int id;
    ProjectStatus status;
    int priority;
    struct timeval deadline;
} Project;

typedef struct Node {
    Project project;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} ProjectList;

void initProjectList(ProjectList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* createNode(Project project) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->project = project;
    newNode->next = NULL;
    return newNode;
}

void insertProject(ProjectList* list, Project project) {
    Node* newNode = createNode(project);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

Node* findProjectsByStatus(ProjectList* list, ProjectStatus status) {
    // Implement retrieval by status
}

Node* findProjectsByPriority(ProjectList* list, int priority) {
    // Implement retrieval by priority
}

Node* findProjectsByDeadline(ProjectList* list, struct timeval deadline) {
    // Implement retrieval by deadline
}

void updateProject(ProjectList* list, int id, Project newProject) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->project.id == id) {
            current->project = newProject;
            return;
        }
        current = current->next;
    }
}

void deleteProject(ProjectList* list, int id) {
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->project.id == id) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

void freeProjectList(ProjectList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}
