#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 200

typedef struct {
    double x, y, z;
} point;

typedef struct {
    char* strings;
    double* doubles;
    point* points;
    int capacity;
    int size;
    pthread_mutex_t mutex;
} data_structures;

data_structures* create_data_structures() {
    data_structures* ds = (data_structures*)malloc(sizeof(data_structures));
    ds->strings = (char*)malloc(INITIAL_CAPACITY * sizeof(char*));
    ds->doubles = (double*)malloc(INITIAL_CAPACITY * sizeof(double));
    ds->points = (point*)malloc(INITIAL_CAPACITY * sizeof(point));
    ds->capacity = INITIAL_CAPACITY;
    ds->size = 0;
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void resize(data_structures* ds) {
    ds->capacity *= 2;
    ds->strings = (char*)realloc(ds->strings, ds->capacity * sizeof(char*));
    ds->doubles = (double*)realloc(ds->doubles, ds->capacity * sizeof(double));
    ds->points = (point*)realloc(ds->points, ds->capacity * sizeof(point));
}

void insert_point(data_structures* ds, const char* id, double value, point p) {
    pthread_mutex_lock(&ds->mutex);
    for (int i = 0; i < ds->size; ++i) {
        if (strcmp(ds->strings[i], id) == 0) {
            ds->doubles[i] = value;
            ds->points[i] = p;
            pthread_mutex_unlock(&ds->mutex);
            return;
        }
    }
    if (ds->size >= ds->capacity) resize(ds);
    ds->strings[ds->size] = strdup(id);
    ds->doubles[ds->size] = value;
    ds->points[ds->size++] = p;
    pthread_mutex_unlock(&ds->mutex);
}

point* get_point(data_structures* ds, const char* id) {
    pthread_mutex_lock(&ds->mutex);
    for (int i = 0; i < ds->size; ++i) {
        if (strcmp(ds->strings[i], id) == 0) {
            pthread_mutex_unlock(&ds->mutex);
            return &ds->points[i];
        }
    }
    pthread_mutex_unlock(&ds->mutex);
    return NULL;
}

double euclidean_distance(point p1, point p2) {
    return sqrt(pow(p1.x - p2.x, 2) + pow(p1.y - p2.y, 2) + pow(p1.z - p2.z, 2));
}

void destroy_data_structures(data_structures* ds) {
    for (int i = 0; i < ds->size; ++i) free(ds->strings[i]);
    pthread_mutex_destroy(&ds->mutex);
    free(ds->strings);
    free(ds->doubles);
    free(ds->points);
    free(ds);
}
