#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEMENTS 1000
#define MAX_SUM 5000

void processNetworkStream(const char* stream, int rangeMin, int rangeMax) {
    int* numbers = (int*)malloc(MAX_ELEMENTS * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    int sum = 0;

    char* token = strtok((char*)stream, " ");
    while (token != NULL && count < MAX_ELEMENTS) {
        int num = atoi(token);
        if (num < rangeMin || num > rangeMax) {
            fprintf(stderr, "Invalid number: %d\n", num);
            free(numbers);
            exit(EXIT_FAILURE);
        }

        numbers[count++] = num;
        sum += num;

        if (sum > MAX_SUM) {
            fprintf(stderr, "Cumulative sum exceeds threshold\n");
            free(numbers);
            exit(EXIT_FAILURE);
        }

        token = strtok(NULL, " ");
    }

    printf("Processed %d elements with sum: %d\n", count, sum);

    free(numbers);
}

int main() {
    const char* networkStream = "10 20 30 40 50";
    processNetworkStream(networkStream, 10, 60);
    return 0;
}
