#define MAX_REQUESTS 10000

typedef enum {
    REQUEST_TYPE_A,
    REQUEST_TYPE_B,
    REQUEST_TYPE_C
} RequestType;

typedef struct {
    int id;
    RequestType type;
    double latency;
    double frequency;
    int priority;
    clock_t start_time;
} NetworkRequest;

NetworkRequest request_queue[MAX_REQUESTS];
int queue_size = 0;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;

void* process_request(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue_lock);
        while (queue_size == 0) {
            pthread_cond_wait(&queue_not_empty, &queue_lock);
        }

        NetworkRequest request = request_queue[--queue_size];
        pthread_mutex_unlock(&queue_lock);

        // Simulate processing time
        clock_t start_time = clock();
        // Process the request here
        clock_t end_time = clock();

        double processing_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

        // Log the request metadata
        log_request_metadata(request, processing_time);

        // Update statistics
        update_statistics(&request, processing_time);
    }
}

void enqueue_request(NetworkRequest request) {
    pthread_mutex_lock(&queue_lock);
    while (queue_size == MAX_REQUESTS) {
        pthread_cond_wait(&queue_not_full, &queue_lock);
    }

    request_queue[queue_size++] = request;
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&queue_lock);
}

void log_request_metadata(NetworkRequest request, double processing_time) {
    // Implement logging logic here
    printf("Request ID: %d, Type: %d, Latency: %.2f, Frequency: %.2f, Priority: %d, Processing Time: %.2f\n",
           request.id, request.type, request.latency, request.frequency, request.priority, processing_time);
}

void update_statistics(NetworkRequest* request, double processing_time) {
    // Implement statistics update logic here
    printf("Updated statistics for Request ID: %d\n", request->id);
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_request, NULL);
    }

    // Simulate enqueuing requests
    for (int i = 0; i < MAX_REQUESTS; i++) {
        NetworkRequest request;
        request.id = i;
        request.type = REQUEST_TYPE_A;
        request.latency = 1.0 + rand() % 5;
        request.frequency = 1.0 + rand() % 3;
        request.priority = rand() % 10;
        clock_t start_time = clock();
        enqueue_request(request);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
