import java.io.*;
import java.nio.file.*;
import javax.imageio.ImageIO;
import javax.imageio.stream.ImageInputStream;
import org.apache.tika.metadata.Metadata;
import org.apache.tika.parser.ParseContext;
import org.apache.tika.parser.tiff.TIFFParser;

public class ImageMetadataExtractor {

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Usage: java ImageMetadataExtractor <input_directory>");
            return;
        }

        Path inputDirectory = Paths.get(args[0]);
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(inputDirectory)) {
            for (Path file : stream) {
                if (Files.isRegularFile(file) && file.toString().toLowerCase().endsWith(".tiff")) {
                    extractMetadata(file);
                }
            }
        } catch (IOException e) {
            System.err.println("Error processing directory: " + e.getMessage());
        }
    }

    private static void extractMetadata(Path filePath) {
        try (ImageInputStream iis = ImageIO.createImageInputStream(filePath.toFile())) {
            TIFFParser parser = new TIFFParser();
            Metadata metadata = new Metadata();
            ParseContext context = new ParseContext();

            parser.parse(iis, metadata, context);

            int bitsPerSample = Integer.parseInt(metadata.get("tiff:BitsPerSample"));
            int samplesPerPixel = Integer.parseInt(metadata.get("tiff:SamplesPerPixel"));

            if (bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16) {
                System.out.println("File: " + filePath);
                System.out.println("Bits per Sample: " + bitsPerSample);
                System.out.println("Samples per Pixel: " + samplesPerPixel);

                String extraSamples = metadata.get("tiff:ExtraSamples");
                if (extraSamples != null) {
                    System.out.println("Extra Samples: " + extraSamples);
                }
            } else {
                System.err.println("Unsupported bit depth for file: " + filePath);
            }

        } catch (IOException e) {
            System.err.println("Error processing file: " + filePath + " - " + e.getMessage());
        }
    }
}
```

This Java application uses the Apache Tika library to parse TIFF files and extract metadata. It handles different bit depths and reports errors for unsupported formats. The main method processes a directory of TIFF files, extracting metadata from each one. Error handling is included for file I/O operations and corrupted files.']

