#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <openssl/md5.h>

#define MAX_FILENAME_LENGTH 256

void rename_files_in_directory(const char *directory_path) {
    DIR *dir;
    struct dirent *entry;
    struct stat file_stat;
    char old_file_path[MAX_FILENAME_LENGTH];
    char new_file_path[MAX_FILENAME_LENGTH];
    time_t last_modified_time;
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    char hash_str[33];

    if ((dir = opendir(directory_path)) == NULL) {
        perror("Error opening directory");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        snprintf(old_file_path, sizeof(old_file_path), "%s/%s", directory_path, entry->d_name);

        if (stat(old_file_path, &file_stat) == -1) {
            perror("Error getting file stats");
            continue;
        }

        last_modified_time = file_stat.st_mtime;

        // Generate MD5 hash of the file content
        FILE *file = fopen(old_file_path, "rb");
        if (!file) {
            perror("Error opening file for reading");
            continue;
        }
        MD5_CTX md5_ctx;
        MD5_Init(&md5_ctx);
        unsigned char buffer[1024];
        size_t bytes_read;
        while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
            MD5_Update(&md5_ctx, buffer, bytes_read);
        }
        fclose(file);
        MD5_Final(md5_hash, &md5_ctx);

        // Convert hash to a string
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            snprintf(hash_str + i * 2, 3, "%02x", md5_hash[i]);
        }

        // Create new file name with timestamp and hash
        time_t current_time = time(NULL);
        struct tm *timeinfo = localtime(&current_time);
        strftime(new_file_path, sizeof(new_file_path), "%Y%m%d%H%M%S_", timeinfo);
        strncat(new_file_path, entry->d_name, MAX_FILENAME_LENGTH - strlen(new_file_path) - 1);
        strcat(new_file_path, "_");
        strncat(new_file_path, hash_str, MAX_FILENAME_LENGTH - strlen(new_file_path) - 1);

        // Check if new file name already exists
        struct stat new_file_stat;
        if (stat(new_file_path, &new_file_stat) == 0) {
            fprintf(stderr, "File with new name already exists: %s\n", new_file_path);
            continue;
        }

        // Rename the file
        if (rename(old_file_path, new_file_path) != 0) {
            perror("Error renaming file");
        }
    }

    closedir(dir);
}

int main() {
    const char *directory_path = "/path/to/directory";
    rename_files_in_directory(directory_path);
    return 0;
}
```

This code snippet provides a basic implementation of the described functionality. It opens a directory, reads each entry, and renames files by appending a timestamp and an MD5 hash of their content to their names. Error handling is included for file operations and permission issues. The function assumes that the MD5 library is available and linked during compilation.']

