#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_FRAMES 1000
#define MAX_STATS 50

typedef struct {
    int frame_id;
    // Other metadata fields
} DL_FRAME_METADATA;

typedef struct {
    int stat_id;
    // Other PHY layer stats fields
} PHY_LAYER_STATS;

typedef struct {
    DL_FRAME_METADATA *metadata;
    PHY_LAYER_STATS **stats;
    int num_stats;
} LTE_DL_FRAME;

LTE_DL_FRAME* manageLTEFrames(int num_frames, pthread_mutex_t *mutex) {
    LTE_DL_FRAME *frames = (LTE_DL_FRAME*)malloc(num_frames * sizeof(LTE_DL_FRAME));
    if (!frames) {
        perror("Failed to allocate memory for frames");
        return NULL;
    }

    for (int i = 0; i < num_frames; i++) {
        pthread_mutex_lock(mutex);
        frames[i].metadata = (DL_FRAME_METADATA*)malloc(sizeof(DL_FRAME_METADATA));
        if (!frames[i].metadata) {
            perror("Failed to allocate memory for metadata");
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        frames[i].stats = (PHY_LAYER_STATS**)malloc(MAX_STATS * sizeof(PHY_LAYER_STATS*));
        if (!frames[i].stats) {
            perror("Failed to allocate memory for stats pointers");
            free(frames[i].metadata);
            pthread_mutex_unlock(mutex);
            return NULL;
        }

        // Populate metadata and stats with data
        frames[i].metadata->frame_id = i + 1;
