                free(frames[i].metadata);
                for (int k = 0; k < j; k++) {
                    free(frames[i].stats[k]);
                }
                free(frames[i].stats);
                pthread_mutex_unlock(mutex);
                return NULL;
            }
            // Populate PHY layer stats with data
        }

        frames[i].num_stats = MAX_STATS;
        pthread_mutex_unlock(mutex);
    }

    return frames;
}

void freeLTEFrames(LTE_DL_FRAME *frames, int num_frames) {
    for (int i = 0; i < num_frames; i++) {
        free(frames[i].metadata);
        for (int j = 0; j < frames[i].num_stats; j++) {
            free(frames[i].stats[j]);
        }
        free(frames[i].stats);
    }
    free(frames);
}

void logError(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] ERROR: %s\n", ctime(&now), message);
}

void logWarning(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] WARNING: %s\n", ctime(&now), message);
}
