#define INITIAL_OFFSETS_SIZE 100
#define MAX_OFFSETS_SIZE 200
#define INITIAL_KEYS_SIZE 100
#define MAX_KEYS_SIZE 200
#define INITIAL_RECORDS_SIZE 50
#define RECORDS_INCREMENT 10

typedef struct {
    int *offsets;
    int offsets_size;
    int max_offsets_size;
    char **keys;
    int keys_size;
    int max_keys_size;
    FILE **records;
    int records_size;
    int max_records_size;
} DataStructures;

DataStructures ds;

pthread_mutex_t offsets_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t keys_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_data_structures() {
    ds.offsets = (int *)malloc(INITIAL_OFFSETS_SIZE * sizeof(int));
    ds.keys = (char **)malloc(INITIAL_KEYS_SIZE * sizeof(char *));
    ds.records = (FILE **)malloc(INITIAL_RECORDS_SIZE * sizeof(FILE *));
    ds.offsets_size = 0;
    ds.max_offsets_size = INITIAL_OFFSETS_SIZE;
    ds.keys_size = 0;
    ds.max_keys_size = INITIAL_KEYS_SIZE;
    ds.records_size = 0;
    ds.max_records_size = INITIAL_RECORDS_SIZE;
}

void resize_offsets() {
    pthread_mutex_lock(&offsets_mutex);
    if (ds.offsets_size == ds.max_offsets_size) {
        ds.max_offsets_size += MAX_OFFSETS_SIZE - ds.max_offsets_size;
        ds.offsets = realloc(ds.offsets, ds.max_offsets_size * sizeof(int));
    }
    pthread_mutex_unlock(&offsets_mutex);
}

void resize_keys() {
    pthread_mutex_lock(&keys_mutex);
    if (ds.keys_size == ds.max_keys_size) {
        ds.max_keys_size += MAX_KEYS_SIZE - ds.max_keys_size;
        ds.keys = realloc(ds.keys, ds.max_keys_size * sizeof(char *));
    }
    pthread_mutex_unlock(&keys_mutex);
}

void resize_records() {
    pthread_mutex_lock(&records_mutex);
    if (ds.records_size == ds.max_records_size) {
        ds.max_records_size += RECORDS_INCREMENT - ds.max_records_size;
        ds.records = realloc(ds.records, ds.max_records_size * sizeof(FILE *));
    }
    pthread_mutex_unlock(&records_mutex);
}

int insert_record(const char *file_name, const char *output_file_name) {
    resize_records();
    ds.records[ds.records_size] = fopen(output_file_name, "w");
    if (ds.records[ds.records_size] == NULL) {
        return 1;
    }
    // Convert JPEG to PDF using a third-party tool
    int result = system("convert -density 300 input.jpg output.pdf");
    if (result != 0) {
        fclose(ds.records[ds.records_size]);
        ds.records[ds.records_size] = NULL;
        return 1;
    }
    ds.records_size++;
    return 0;
}

int retrieve_record(int key) {
    pthread_mutex_lock(&keys_mutex);
    for (int i = 0; i < ds.keys_size; i++) {
        if (atoi(ds.keys[i]) == key) {
            pthread_mutex_unlock(&keys_mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&keys_mutex);
    return -1; // Key not found
}

void *insert_thread(void *arg) {
    int *data = (int *)arg;
    insert_record(data[0], data[1]);
    free(arg);
    return NULL;
}

void *retrieve_thread(void *arg) {
    int key = *(int *)arg;
    int result = retrieve_record(key);
    printf("Key %d found at index %d\n", key, result);
    free(arg);
    return NULL;
}

int main() {
    initialize_data_structures();
    pthread_t insert_threads[10];
    pthread_t retrieve_threads[5];

    for (int i = 0; i < 10; i++) {
        int *data = malloc(sizeof(int) * 2);
        data[0] = i;
        sprintf(data[1], "output_%d.pdf", i);
        pthread_create(&insert_threads[i], NULL, insert_thread, data);
    }

    for (int i = 0; i < 5; i++) {
        int *key = malloc(sizeof(int));
        *key = rand() % 20;
        pthread_create(&retrieve_threads[i], NULL, retrieve_thread, key);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(insert_threads[i], NULL);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(retrieve_threads[i], NULL);
    }

    free(ds.offsets);
    free(ds.keys);
    for (int i = 0; i < ds.records_size; i++) {
        if (ds.records[i] != NULL) {
            fclose(ds.records[i]);
        }
    }
    free(ds.records);

    return 0;
}
