public class PokemonReportGenerator {

    private static final String REDIS_HOST = "localhost";
    private static final int REDIS_PORT = 6379;
    private static final Jedis jedis = new Jedis(REDIS_HOST, REDIS_PORT);

    public static String generatePokemonReport(Pokemon pokemon) {
        try {
            // Simulate network latency
            Thread.sleep((long) (Math.random() * 401) + 100); // 100ms to 500ms

            // Retrieve Pokemon data from external API
            String name = fetchPokemonName(pokemon.getId());
            String type = fetchPokemonType(pokemon.getId());

            if (name == null || type == null) {
                return "Error: Unable to retrieve Pokemon data.";
            }

            // Check cache for weaknesses
            String cachedWeaknesses = jedis.get("weaknesses:" + name);
            if (cachedWeaknesses != null) {
                return generateReport(name, type, cachedWeaknesses);
            }

            // Determine primary and secondary weaknesses based on type
            String[] weaknesses = determineWeaknesses(type);

            // Store weaknesses in cache with expiration
            jedis.setex("weaknesses:" + name, 3600, String.join(",", weaknesses)); // Cache for 1 hour

            return generateReport(name, type, String.join(", ", weaknesses));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return "Error: Network latency simulation interrupted.";
        }
    }

    private static String fetchPokemonName(int id) {
        // Simulate API call to retrieve Pokemon name
        return CompletableFuture.supplyAsync(() -> {
            try {
                // External API call logic here
                return "Pikachu"; // Example name
            } catch (Exception e) {
                return null;
            }
        }).join();
    }

    private static String fetchPokemonType(int id) {
        // Simulate API call to retrieve Pokemon type
        return CompletableFuture.supplyAsync(() -> {
            try {
                // External API call logic here
                return "Electric"; // Example type
            } catch (Exception e) {
                return null;
            }
        }).join();
    }

    private static String[] determineWeaknesses(String type) {
        switch (type.toLowerCase()) {
            case "electric":
                return new String[]{"Ground", "Flying"};
            case "fire":
                return new String[]{"Water", "Grass"};
            // Add more cases as needed
            default:
                return new String[]{"None"};
        }
    }

    private static String generateReport(String name, String type, String weaknesses) {
        return "Pokemon Report:\nName: " + name + "\nType: " + type + "\nWeaknesses: " + weaknesses;
    }

    public static void main(String[] args) {
        Pokemon pokemon = new Pokemon(1); // Example Pokemon ID
        System.out.println(generatePokemonReport(pokemon));
    }
}

class Pokemon {
    private int id;

    public Pokemon(int id) {
        this.id = id;
    }

    public int getId() {
