#include <string.h>
#include <pthread.h>

typedef struct node {
    double value;
    char* str;
    size_t len;
    struct node* next;
} Node;

typedef struct linked_list {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(double value, const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->value = value;
    node->len = strlen(str);
    node->str = (char*)malloc(node->len + 1);
    if (!node->str) {
        free(node);
        return NULL;
    }
    strcpy(node->str, str);
    node->next = NULL;
    return node;
}

void insert_node(LinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    node->next = list->head;
    list->head = node;
    pthread_mutex_unlock(&list->lock);
}

Node* remove_node(LinkedList* list, double value) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (current->value == value) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

