#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    time_t timestamp;
    float sensor_readings[5];
    int device_status;
    char message_payload[MAX_PAYLOAD_SIZE + 1];
    int device_id;
} MessageRecord;

typedef struct {
    MessageRecord *records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageCollection;

void init_message_collection(MessageCollection *collection, size_t initial_capacity) {
    collection->records = (MessageRecord *)malloc(initial_capacity * sizeof(MessageRecord));
    if (!collection->records) {
        perror("Failed to allocate memory for message records");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_message_record(MessageCollection *collection, MessageRecord record) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        collection->records = (MessageRecord *)realloc(collection->records, new_capacity * sizeof(MessageRecord));
        if (!collection->records) {
            perror("Failed to reallocate memory for message records");
            exit(EXIT_FAILURE);
        }
        collection->capacity = new_capacity;
    }
    collection->records[collection->count++] = record;
    pthread_mutex_unlock(&collection->lock);
}

void validate_and_update_timestamps(MessageCollection *collection, time_t freshness_threshold) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (time(NULL) - collection->records[i].timestamp > freshness_threshold) {
            collection->records[i].timestamp = time(NULL);
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void serialize_message_collection(const MessageCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(collection->records, sizeof(MessageRecord), collection->count, file);
    fclose(file);
}

void deserialize_message_collection(MessageCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    size_t count = fread(collection->records, sizeof(MessageRecord), collection->capacity, file);
    if (count > collection->capacity) {
        fprintf(stderr, "Deserialized more records than capacity\n");
    } else {
        collection->count = count;
    }
    fclose(file);
}

void destroy_message_collection(MessageCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->records);
}
