#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct record {
    int value;
    size_t size;
    long *offset;
} record;

typedef struct rb_node {
    int key;
    struct rb_node *left, *right, *parent;
    atomic_int color; // 0 for red, 1 for black
} rb_node;

typedef struct rb_tree {
    rb_node *root;
    pthread_mutex_t lock;
} rb_tree;

void init_rb_tree(rb_tree *tree) {
    tree->root = NULL;
    pthread_mutex_init(&tree->lock, NULL);
}

rb_node* create_rb_node(int key) {
    rb_node *node = (rb_node*)malloc(sizeof(rb_node));
    if (!node) return NULL;
    node->key = key;
    node->left = node->right = node->parent = NULL;
    atomic_store(&node->color, 0); // Red
    return node;
}

void left_rotate(rb_tree *tree, rb_node *x) {
    rb_node *y = x->right;
    x->right = y->left;
    if (y->left != NULL)
        y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL)
        tree->root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void right_rotate(rb_tree *tree, rb_node *y) {
    rb_node *x = y->left;
    y->left = x->right;
    if (x->right != NULL)
        x->right->parent = y;
    x->parent = y->parent;
    if (y->parent == NULL)
        tree->root = x;
    else if (y == y->parent->right)
        y->parent->right = x;
    else
        y->parent->left = x;
    x->right = y;
    y->parent = x;
}

void rb_insert(rb_tree *tree, int key) {
    pthread_mutex_lock(&tree->lock);
    rb_node *node = create_rb_node(key);
    if (!node) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        pthread_mutex_unlock(&tree->lock);
        return;
    }

    rb_node *y = NULL, *x = tree->root;

    while (x != NULL) {
        y = x;
        if (key < x->key)
            x = x->left;
        else
            x = x->right;
    }
    node->parent = y;
    if (y == NULL)
        tree->root = node;
    else if (key < y->key)
        y->left = node;
    else
        y->right = node;

    node->left = NULL;
    node->right = NULL;
    atomic_store(&node->color, 0); // Red

    while (atomic_load(&node->parent) != NULL && atomic_load(&node->parent->color) == 0) {
        if (node->parent == atomic_load(&node->parent->parent)->left) {
            rb_node *y = atomic_load(&node->parent->parent)->right;
            if (atomic_load(&y->color) == 0) {
                atomic_store(&node->parent->color, 1); // Black
                atomic_store(&y->color, 1); // Black
                atomic_store(&node->parent->parent->color, 0); // Red
                node = atomic_load(&node->parent->parent);
            } else {
                if (node == atomic_load(&node->parent)->right) {
                    node = atomic_load(&node->parent);
                    left_rotate(tree, node);
                }
                y = atomic_load(&node->parent->parent);
                atomic_store(&node->parent->color, 1); // Black
                atomic_store(&y->color, 0); // Red
                right_rotate(tree, y);
            }
        } else {
            rb_node *y = atomic_load(&node->parent->parent)->left;
            if (atomic_load(&y->color) == 0) {
                atomic_store(&node->parent->color, 1); // Black
                atomic_store(&y->color, 1); // Black
                atomic_store(&node->parent->parent->color, 0); // Red
                node = atomic_load(&node->parent->parent);
            } else {
                if (node == atomic_load(&node->parent)->left) {
                    node = atomic_load(&node->parent);
                    right_rotate(tree, node);
                }
                y = atomic_load(&node->parent->parent);
                atomic_store(&node->parent->color, 1); // Black
                atomic_store(&y->color, 0); // Red
                left_rotate(tree, y);
            }
        }
    }
    atomic_store(&tree->root->color, 1); // Black
    pthread_mutex_unlock(&tree->lock);
}

void free_rb_tree(rb_node *node) {
    if (node == NULL)
        return;
    free_rb_tree(node->left);
    free_rb_tree(node->right);
    free(node);
}

int main() {
    rb_tree tree;
    init_rb_tree(&tree);

    int value;
    while (scanf("%d", &value) != EOF) {
        rb_insert(&tree, value);
    }

    // Free all allocated memory
    free_rb_tree(tree.root);

    return 0;
}
