        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

int processLTEFramesAdvanced(LTE_DL_FRAME_POOL *pool, int frame_id, PHY_LAYER_STATS stats[], size_t stats_count) {
    if (!pool || !stats || stats_count > MAX_FRAMES) return -1;

    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        // Resize the pool
        DL_FRAME_METADATA *new_frames = (DL_FRAME_METADATA*)realloc(pool->frames, pool->capacity * 2 * sizeof(DL_FRAME_METADATA));
        if (!new_frames) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        pool->frames = new_frames;
        pool->capacity *= 2;
    }

    DL_FRAME_METADATA *frame = &pool->frames[pool->count++];
    frame->timestamp = time(NULL);
    frame->frame_id = frame_id;

    for (size_t i = 0; i < stats_count && i < MAX_FRAMES; ++i) {
        frame->stats[i] = stats[i];
    }

    pthread_mutex_unlock(&pool->lock);

    return 0;
}

