    key* keys = (key*)malloc(key_count * sizeof(key));
    if (!keys) {
        free(offsets);
        return -1;
    }

    record* records = (record*)malloc(record_count * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        return -1;
    }

    buffer* buffers = (buffer*)aligned_alloc(64, buffer_count * sizeof(buffer));
    if (!buffers) {
        free(records);
        free(keys);
        free(offsets);
        return -1;
    }

    // Initialize structures
    for (size_t i = 0; i < record_count; ++i) {
        records[i].value = rand() % (max_random_value - min_random_value + 1) + min_random_value;
