        memset(records[i].metadata, 0, sizeof(records[i].metadata));
        records[i].log_access = NULL; // Set callback function if needed
        records[i].reference_count = 0;
    }

    // Free allocated memory
    free(buffers);
    free(records);
    free(keys);
