#include <stdlib.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    double amount;
    char status[20];
} Transaction;

typedef struct {
    Transaction *transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TransactionPool;

TransactionPool* create_transaction_pool(size_t initial_capacity) {
    TransactionPool *pool = (TransactionPool*)malloc(sizeof(TransactionPool));
    pool->transactions = (Transaction*)malloc(initial_capacity * sizeof(Transaction));
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_transaction_pool(TransactionPool *pool) {
    free(pool->transactions);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_transaction(TransactionPool *pool, double amount, const char *status) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Transaction *new_transactions = (Transaction*)realloc(pool->transactions, new_capacity * sizeof(Transaction));
        if (!new_transactions) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->transactions = new_transactions;
        pool->capacity = new_capacity;
    }
    time_t current_time = time(NULL);
    pool->transactions[pool->count].timestamp = current_time;
    pool->transactions[pool->count].amount = amount;
    snprintf(pool->transactions[pool->count].status, sizeof(pool->transactions[pool->count].status), "%s", status);
    pool->count++;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void* transaction_worker(void *arg) {
    TransactionPool *pool = (TransactionPool*)arg;
    while (1) {
        pthread_mutex_lock(&pool->lock);
        if (pool->count == 0) {
            pthread_mutex_unlock(&pool->lock);
            break; // No transactions to process
        }
        Transaction transaction = pool->transactions[pool->count - 1];
        pool->count--;
        pthread_mutex_unlock(&pool->lock);

        // Process the transaction here
        printf("Processing transaction: timestamp=%ld, amount=%.2f, status=%s\n", transaction.timestamp, transaction.amount, transaction.status);
    }
    return NULL;
}

int main() {
    TransactionPool *pool = create_transaction_pool(10);
    pthread_t worker_thread;

    // Start the worker thread
    if (pthread_create(&worker_thread, NULL, transaction_worker, pool) != 0) {
        destroy_transaction_pool(pool);
        return -1; // Thread creation failed
    }

    // Add transactions to the pool
    add_transaction(pool, 100.50, "Completed");
    add_transaction(pool, 200.75, "Pending");

    // Wait for the worker thread to finish
    pthread_join(worker_thread, NULL);

    destroy_transaction_pool(pool);
    return 0;
}
