    }
    free(pool->frames);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void lte_dl_frame_pool_add(LTE_DL_FRAME_POOL *pool, LTE_DL_FRAME frame) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        pool->capacity *= 2;
        pool->frames = realloc(pool->frames, pool->capacity * sizeof(LTE_DL_FRAME));
    }
    pool->frames[pool->size++] = frame;
    pthread_mutex_unlock(&pool->lock);
}

LTE_DL_FRAME lte_dl_frame_pool_get(LTE_DL_FRAME_POOL *pool) {
    LTE_DL_FRAME frame;
    pthread_mutex_lock(&pool->lock);
    if (pool->size > 0) {
        frame = pool->frames[--pool->size];
    } else {
        // Handle error or return a default value
        memset(&frame, 0, sizeof(LTE_DL_FRAME));
    }
    pthread_mutex_unlock(&pool->lock);
    return frame;
}

