#include <pthread.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection) {
        pthread_mutex_lock(&collection->mutex);
        free(collection->records);
        pthread_mutex_unlock(&collection->mutex);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_record(RecordCollection *collection, int key, long offset) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Record *new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);
    return 0; // Success
}

Record* get_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            Record *record = &collection->records[i];
            pthread_mutex_unlock(&collection->mutex);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return NULL; // Key not found
}
