#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} EncryptionContext;

int init_encryption_context(EncryptionContext **ctx, const char *passphrase, int aes_key_size) {
    // Initialize OpenSSL
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Create new context
    *ctx = EVP_CIPHER_CTX_new();
    if (*ctx == NULL) return -1;

    // Generate random IV
    if (!RAND_bytes((*ctx)->iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc()))) {
        EVP_CIPHER_CTX_free(*ctx);
        return -1;
    }

    // Derive key using PBKDF2 with SHA-256
    unsigned char key[EVP_MAX_KEY_LENGTH];
    if (!PKCS5_PBKDF2_HMAC(passphrase, strlen(passphrase), NULL, 0, 10000, EVP_sha256(), aes_key_size / 8, key)) {
        EVP_CIPHER_CTX_free(*ctx);
        return -1;
    }

    // Initialize encryption context
    if (aes_key_size == 128) {
        if (!EVP_EncryptInit_ex(*ctx, EVP_aes_128_cbc(), NULL, key, (*ctx)->iv)) {
            EVP_CIPHER_CTX_free(*ctx);
            return -1;
        }
    } else if (aes_key_size == 192) {
        if (!EVP_EncryptInit_ex(*ctx, EVP_aes_192_cbc(), NULL, key, (*ctx)->iv)) {
            EVP_CIPHER_CTX_free(*ctx);
            return -1;
        }
    } else if (aes_key_size == 256) {
        if (!EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, key, (*ctx)->iv)) {
            EVP_CIPHER_CTX_free(*ctx);
            return -1;
        }
    } else {
        EVP_CIPHER_CTX_free(*ctx);
        return -1;
    }

    return 0;
}

int encrypt_data(EncryptionContext *ctx, unsigned char *input, int input_len, unsigned char **output, int *output_len) {
    // Allocate memory for output
    *output = (unsigned char *)malloc(input_len + EVP_CIPHER_block_size(ctx->cipher));
    if (*output == NULL) return -1;

    // Perform encryption
    int len;
    if (!EVP_EncryptUpdate(ctx, *output, &len, input, input_len)) {
        free(*output);
        return -1;
    }
    *output_len = len;

    // Finalize encryption
    if (!EVP_EncryptFinal_ex(ctx, (*output) + len, &len)) {
        free(*output);
        return -1;
    }
    *output_len += len;

    return 0;
}

void cleanup_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
