typedef enum {
    DEVICE_STATUS_OK,
    DEVICE_STATUS_ERROR
} DeviceStatus;

typedef struct {
    int sequence_number;
    char buffer[1024];
    uint8_t priority_level;
} MessagePayload;

typedef struct {
    size_t index;
} MessageReference;

typedef struct {
    time_t last_update;
    int batch_size;
    MessageReference* message_references;
} BatchMetadata;

typedef struct {
    long* timestamps;
    float* sensor_readings;
    DeviceStatus* device_statuses;
    MessagePayload* message_payloads;
    char** device_ids;
    BatchMetadata metadata;
} SensorBatchData;

SensorBatchData* create_sensor_batch_data(int batch_size) {
    // Allocate memory for the data structure
    SensorBatchData* data = (SensorBatchData*)malloc(sizeof(SensorBatchData));
    if (!data) return NULL;

    data->timestamps = (long*)calloc(batch_size, sizeof(long));
    data->sensor_readings = (float*)calloc(batch_size, sizeof(float));
    data->device_statuses = (DeviceStatus*)calloc(batch_size, sizeof(DeviceStatus));
    data->message_payloads = (MessagePayload*)calloc(batch_size, sizeof(MessagePayload));
    data->device_ids = (char**)malloc(batch_size * sizeof(char*));

    for (int i = 0; i < batch_size; i++) {
        data->device_ids[i] = (char*)malloc(256); // Assuming device IDs are up to 255 characters
    }

    data->metadata.message_references = (MessageReference*)calloc(batch_size, sizeof(MessageReference));
    data->metadata.batch_size = batch_size;

    return data;
}

void destroy_sensor_batch_data(SensorBatchData* data) {
    if (!data) return;

    free(data->timestamps);
    free(data->sensor_readings);
    free(data->device_statuses);

    for (int i = 0; i < data->metadata.batch_size; i++) {
        free(data->message_payloads[i].buffer);
        free(data->device_ids[i]);
    }

    free(data->message_payloads);
    free(data->device_ids);
    free(data->metadata.message_references);
    free(data);
}

void update_timestamps(SensorBatchData* data, time_t threshold) {
    pthread_mutex_lock(&data->mutex); // Assuming a mutex is used for thread safety
    for (int i = 0; i < data->metadata.batch_size; i++) {
        if (time(NULL) - data->timestamps[i] > threshold) {
            data->timestamps[i] = time(NULL);
        }
    }
    pthread_mutex_unlock(&data->mutex);
}

void serialize_sensor_batch_data(SensorBatchData* data, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    // Serialize the data structure to a binary file
    fwrite(data->timestamps, sizeof(long), data->metadata.batch_size, file);
    fwrite(data->sensor_readings, sizeof(float), data->metadata.batch_size, file);
    fwrite(data->device_statuses, sizeof(DeviceStatus), data->metadata.batch_size, file);

    for (int i = 0; i < data->metadata.batch_size; i++) {
        fwrite(&data->message_payloads[i].sequence_number, sizeof(int), 1, file);
        fwrite(data->message_payloads[i].buffer, sizeof(char), 1024, file);
        fwrite(&data->message_payloads[i].priority_level, sizeof(uint8_t), 1, file);
    }

    for (int i = 0; i < data->metadata.batch_size; i++) {
        fwrite(data->device_ids[i], sizeof(char), 256, file); // Assuming device IDs are up to 255 characters
    }

    fwrite(&data->metadata.last_update, sizeof(time_t), 1, file);
    fwrite(&data->metadata.batch_size, sizeof(int), 1, file);

    for (int i = 0; i < data->metadata.batch_size; i++) {
        fwrite(&data->metadata.message_references[i].index, sizeof(size_t), 1, file);
    }

    fclose(file);
}

void deserialize_sensor_batch_data(SensorBatchData* data, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    // Deserialize the data structure from a binary file
    fread(data->timestamps, sizeof(long), data->metadata.batch_size, file);
    fread(data->sensor_readings, sizeof(float), data->metadata.batch_size, file);
    fread(data->device_statuses, sizeof(DeviceStatus), data->metadata.batch_size, file);

    for (int i = 0; i < data->metadata.batch_size; i++) {
        fread(&data->message_payloads[i].sequence_number, sizeof(int), 1, file);
        fread(data->message_payloads[i].buffer, sizeof(char), 1024, file);
        fread(&data->message_payloads[i].priority_level, sizeof(uint8_t), 1, file);
    }

    for (int i = 0; i < data->metadata.batch_size; i++) {
        fread(data->device_ids[i], sizeof(char), 256, file); // Assuming device IDs are up to 255 characters
    }

    fread(&data->metadata.last_update, sizeof(time_t), 1, file);
    fread(&data->metadata.batch_size, sizeof(int), 1, file);

    for (int i = 0; i < data->metadata.batch_size; i++) {
        fread(&data->metadata.message_references[i].index, sizeof(size_t), 1, file);
    }

    fclose(file);
}

void log_sensor_batch_data(SensorBatchData* data) {
    // Log the total number of messages processed and a summary of failed allocations
    printf("Total messages processed: %d\n", data->metadata.batch_size);
    // Add code to log failed allocations if any
}

void compress_sensor_batch_data(SensorBatchData* data, const char* filename) {
    // Implement a configurable compression algorithm to reduce storage footprint
    // This is a placeholder for the actual compression logic
    serialize_sensor_batch_data(data, filename);
}

void decompress_sensor_batch_data(SensorBatchData* data, const char* filename) {
    // Implement a configurable decompression algorithm to restore the original data structure
    deserialize_sensor_batch_data(data, filename);
}
