    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <parsing_rules>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* input_file = argv[1];
    const char* output_file = argv[2];
    const char* parsing_rules = argv[3];

    FILE* infile = fopen(input_file, "rb");
    if (!infile) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    // Dynamically allocate memory for arrays
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        fclose(infile);
        return EXIT_FAILURE;
    }

    // Read binary file and parse data
    size_t num_records = 0;
    while (fread(&offsets[num_records], sizeof(long), 1, infile) == 1 &&
           fread(&keys[num_records], sizeof(int), 1, infile) == 1 &&
           fread(&records[num_records].size, sizeof(size_t), 1, infile) == 1) {
        records[num_records].value = rand() % 100; // Example random value
        num_records++;
    }

    fclose(infile);

    // Create threads for processing data
    pthread_t threads[MAX_RECORDS];
    for (size_t i = 0; i < num_records; i++) {
        if (pthread_create(&threads[i], NULL, process_data, &records[i])) {
            perror("Thread creation failed");
            free(offsets);
            free(keys);
            free(records);
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < num_records; i++) {
        pthread_join(threads[i], NULL);
    }

    // Write processed data to output file
    FILE* outfile = fopen(output_file, "wb");
    if (!outfile) {
        perror("Failed to open output file");
        free(offsets);
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < num_records; i++) {
        fwrite(&offsets[i], sizeof(long), 1, outfile);
        fwrite(&keys[i], sizeof(int), 1, outfile);
        fwrite(&records[i].value, sizeof(int), 1, outfile);
        fwrite(&records[i].size, sizeof(size_t), 1, outfile);
    }

    fclose(outfile);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
