void* process_csv(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    FILE* infile = fopen(data->input_file, "r");
    if (!infile) {
        perror("Failed to open input file");
        return NULL;
    }

    FILE* outfile = fopen(data->output_file, "w");
    if (!outfile) {
        perror("Failed to open output file");
        fclose(infile);
        return NULL;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), infile)) {
        // Apply transformations and filtering here
        // Example: Skip empty lines or lines with missing data
        if (strlen(buffer) > 0 && buffer[strlen(buffer) - 1] == '\n') {
            buffer[strlen(buffer) - 1] = '\0';
        }
        if (strlen(buffer) > 0) {
            fprintf(outfile, "%s\n", buffer);
        }
    }

    fclose(infile);
    fclose(outfile);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    ThreadData data[MAX_THREADS];

    // Initialize thread data and create threads
    for (int i = 0; i < MAX_THREADS; i++) {
        data[i].input_file = "large_input.csv";
        data[i].output_file = "output_thread_";
        data[i].thread_id = i;
        pthread_create(&threads[i], NULL, process_csv, &data[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
