    size_t capacity;
    size_t size;
} NFAPI_CRC_ARRAY_T;

NFAPI_CRC_ARRAY_T* create_crc_array() {
    NFAPI_CRC_ARRAY_T* array = (NFAPI_CRC_ARRAY_T*)malloc(sizeof(NFAPI_CRC_ARRAY_T));
    if (!array) return NULL;
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY_T* array) {
    if (array) {
        free(array->data);
        free(array);
    }
}

int insert_crc_indication(NFAPI_CRC_ARRAY_T* array, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    if (!array || array->size >= array->capacity) return -1;

    NFAPI_CRC_INDICATION_PDU_T new_entry;
    new_entry.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry.RNTI = RNTI;
    new_entry.CRCFLAG = (rand() % 2); // Randomly set CRCFLAG

    array->data[array->size++] = new_entry;

    return 0;
}

int verify_crc_indications(NFAPI_CRC_ARRAY_T* array) {
    if (!array || !array->data) return -1;

    for (size_t i = 0; i < array->size; ++i) {
        // Placeholder for CRC verification logic
        // For demonstration, we assume the CRCFLAG is always correct
        if (array->data[i].CRCFLAG != (rand() % 2)) {
            return -1;
        }
    }

    return 0;
}

int resize_crc_array(NFAPI_CRC_ARRAY_T* array) {
    if (!array || array->size < array->capacity) return -1;

    size_t new_capacity = array->capacity * GROWTH_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return -1;

    array->data = new_data;
    array->capacity = new_capacity;

    return 0;
}
