typedef struct {
    int accessCount;
    double totalTimeSpent;
    time_t lastAccessed;
} metadata;

typedef struct {
    time_t timestamp;
    char type[10];
} logEntry;

void allocateAndInitializeData(size_t initialSize, int valueRange, size_t updateInterval, size_t maxLogEntries) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(initialSize * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return;
    }

    int* keys = (int*)malloc(initialSize * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return;
    }

    record* records = (record*)malloc(initialSize * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return;
    }

    metadata* metadatas = (metadata*)malloc(initialSize * sizeof(metadata));
    if (!metadatas) {
        free(offsets);
        free(keys);
        free(records);
        perror("Failed to allocate memory for metadatas");
        return;
    }

    logEntry* logs = (logEntry*)malloc(maxLogEntries * sizeof(logEntry));
    if (!logs) {
        free(offsets);
        free(keys);
        free(records);
        free(metadatas);
        perror("Failed to allocate memory for logs");
        return;
    }

    // Initialize arrays
    srand(time(NULL));
    for (size_t i = 0; i < initialSize; ++i) {
        offsets[i] = i * 100L;
        keys[i] = rand() % valueRange + 1;
        records[i].value = keys[i];
        records[i].size = sizeof(record);
        records[i].lastAccessed = time(NULL);
        metadatas[i].accessCount = 0;
        metadatas[i].totalTimeSpent = 0.0;
        metadatas[i].lastAccessed = time(NULL);
        logs[i].timestamp = time(NULL);
        snprintf(logs[i].type, sizeof(logs[i].type), "Initial");
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(metadatas);
    free(logs);
}
