int add_element(DynamicArray *da, RX_UE_INFORMATION_TAG rx_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_flag) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size].rx_tag = rx_tag;
    da->array[da->size].rnti = rnti;
    da->array[da->size].crc_flag = crc_flag;
    da->size++;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int remove_element(DynamicArray *da, RNTI rnti) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->size; i++) {
        if (da->array[i].rnti == rnti) {
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            da->size--;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return -1; // Element not found
}

int update_crc_flag(DynamicArray *da, RX_UE_INFORMATION_TAG rx_tag, CRC_INDICATION_REL8_TAG new_crc_flag) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->size; i++) {
        if (da->array[i].rx_tag == rx_tag) {
            da->array[i].crc_flag = new_crc_flag;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return -1; // Element not found
}

void compact_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, da->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array) {
        da->array = new_array;
        da->capacity = da->size;
    }
    pthread_mutex_unlock(&da->lock);
}
