#define MAX_FRAMES 1024

typedef struct {
    int frequency;
    int bandwidth;
} DL_FRAME_METADATA;

typedef struct {
    int rssi;
    int snr;
} PHY_LAYER_STATS;

typedef struct {
    DL_FRAME_METADATA metadata;
    PHY_LAYER_STATS *stats;
    int stats_count;
} LTE_DL_FRAME;

LTE_DL_FRAME *frames[MAX_FRAMES];
int frame_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

LTE_DL_FRAME* create_frame(DL_FRAME_METADATA metadata, PHY_LAYER_STATS *stats, int stats_count) {
    LTE_DL_FRAME *frame = allocate_memory(sizeof(LTE_DL_FRAME));
    frame->metadata = metadata;
    frame->stats = allocate_memory(stats_count * sizeof(PHY_LAYER_STATS));
    memcpy(frame->stats, stats, stats_count * sizeof(PHY_LAYER_STATS));
    frame->stats_count = stats_count;
    return frame;
}

void add_frame(LTE_DL_FRAME *frame) {
    pthread_mutex_lock(&mutex);
    if (frame_count < MAX_FRAMES) {
        frames[frame_count++] = frame;
    } else {
        fprintf(stderr, "Frame limit reached\n");
    }
    pthread_mutex_unlock(&mutex);
}

void delete_frame(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < frame_count) {
        free(frames[index]->stats);
        free(frames[index]);
        for (int i = index; i < frame_count - 1; i++) {
            frames[i] = frames[i + 1];
        }
        frame_count--;
    } else {
        fprintf(stderr, "Invalid frame index\n");
    }
    pthread_mutex_unlock(&mutex);
}

void handle_http_put(int id, LTE_DL_FRAME *new_frame) {
    delete_frame(id);
    add_frame(new_frame);
}

void handle_http_delete(int id) {
    delete_frame(id);
}
