typedef struct record {
    int value;
    size_t size;
    long *offset;
} Record;

typedef struct rb_node {
    int key;
    struct rb_node *left, *right, *parent;
    int color; // 0 for red, 1 for black
} RBNode;

RBNode* create_rb_node(int key) {
    RBNode* node = (RBNode*)malloc(sizeof(RBNode));
    if (!node) return NULL;
    node->key = key;
    node->left = node->right = node->parent = NULL;
    node->color = 0; // Red
    return node;
}

void left_rotate(RBNode** root, RBNode* x) {
    RBNode* y = x->right;
    x->right = y->left;
    if (y->left != NULL)
        y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL)
        *root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void right_rotate(RBNode** root, RBNode* y) {
    RBNode* x = y->left;
    y->left = x->right;
    if (x->right != NULL)
        x->right->parent = y;
    x->parent = y->parent;
    if (y->parent == NULL)
        *root = x;
    else if (y == y->parent->right)
        y->parent->right = x;
    else
        y->parent->left = x;
    x->right = y;
    y->parent = x;
}

void rb_insert_fixup(RBNode** root, RBNode* z) {
    while (z->parent != NULL && z->parent->color == 0) {
        if (z->parent == z->parent->parent->left) {
            RBNode* y = z->parent->parent->right;
            if (y != NULL && y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(root, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                right_rotate(root, z->parent->parent);
            }
        } else {
            RBNode* y = z->parent->parent->left;
            if (y != NULL && y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(root, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                left_rotate(root, z->parent->parent);
            }
        }
    }
    (*root)->color = 1;
}

void rb_insert(RBNode** root, int key) {
    RBNode* z = create_rb_node(key);
    if (z == NULL) return;

    RBNode* y = NULL;
    RBNode* x = *root;

    while (x != NULL) {
        y = x;
        if (z->key < x->key)
            x = x->left;
        else
            x = x->right;
    }

    z->parent = y;
    if (y == NULL)
        *root = z;
    else if (z->key < y->key)
        y->left = z;
    else
        y->right = z;

    z->left = NULL;
    z->right = NULL;
    z->color = 0;

    rb_insert_fixup(root, z);
}

int find_max(RBNode* root) {
    if (root == NULL)
        return -1; // Assuming the tree is not empty
    while (root->right != NULL)
        root = root->right;
    return root->key;
}

void free_rb_tree(RBNode* node) {
    if (node == NULL)
        return;
    free_rb_tree(node->left);
    free_rb_tree(node->right);
    free(node);
}

int main() {
    RBNode* root = NULL;

    int n, min_val, max_val;
    printf("Enter the number of elements: ");
    scanf("%d", &n);
    printf("Enter the range (min max): ");
    scanf("%d %d", &min_val, &max_val);

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        int value = min_val + rand() % (max_val - min_val + 1);
        rb_insert(&root, value);
    }

    printf("Largest element: %d\n", find_max(root));

    free_rb_tree(root);

    return 0;
}
