Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_system() {
    srand(time(NULL));
}

void* allocate_data(size_t size) {
    return malloc(size);
}

void free_data(void* ptr) {
    free(ptr);
}

void set_random_value(int* value, int min, int max) {
    *value = rand() % (max - min + 1) + min;
}

int data_management_system(int operation_type, int record_index, size_t data_size, int min_value, int max_value) {
    pthread_mutex_lock(&lock);
    if (record_count >= MAX_RECORDS || data_size > MAX_DATA_SIZE) {
        pthread_mutex_unlock(&lock);
        return -1; // Error: Too many records or data size exceeds limit
    }

    Record* record = &records[record_index];
    record->data = allocate_data(data_size);
    if (!record->data) {
        pthread_mutex_unlock(&lock);
        return -2; // Error: Memory allocation failed
    }

    set_random_value(&record->value, min_value, max_value);
    record->size = data_size;
    record_count++;
    pthread_mutex_unlock(&lock);

    return 0; // Success
}

int main() {
    initialize_system();
    int result = data_management_system(1, 0, 1024, 0, 100);
    if (result == 0) {
        printf("Record created successfully.\n");
    } else {
        printf("Error creating record: %d\n", result);
    }
    return 0;
}
