#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    size_t size;
    void* data;
} Record;

typedef struct MemoryPool {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]->data);
        free(pool->records[i]);
    }
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* allocate_record(MemoryPool* pool, int key, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count == pool->capacity) {
        Record** new_records = (Record**)realloc(pool->records, pool->capacity * 2 * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->records = new_records;
        pool->capacity *= 2;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    record->key = key;
    record->size = size;
    record->data = malloc(size);
    if (!record->data) {
        free(record);
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->records[pool->count++] = record;

    pthread_mutex_unlock(&pool->lock);
    return record;
}

void deallocate_record(MemoryPool* pool, Record* record) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->records[i] == record) {
            free(record->data);
            free(record);
            pool->records[i] = pool->records[--pool->count];
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    MemoryPool* pool = create_memory_pool(10);

    Record* record1 = allocate_record(pool, 1, 1024);
    Record* record2 = allocate_record(pool, 2, 2048);

    deallocate_record(pool, record1);
    deallocate_record(pool, record2);

    destroy_memory_pool(pool);

    return 0;
}
