#define MAX_MESSAGES 1000
#define BUFFER_SIZE 1024

typedef struct {
    int sequence_number;
    char buffer[BUFFER_SIZE];
    uint8_t priority_level;
} MessagePayload;

typedef struct {
    time_t last_update;
    int batch_size;
    MessagePayload** messages;
} BatchMetadata;

typedef struct {
    size_t index;
} MessageReference;

typedef struct {
    time_t* timestamps;
    float* sensor_readings;
    char** device_statuses;
    MessagePayload** message_payloads;
    char** device_ids;
    BatchMetadata* batch_metadata;
    FILE* logging_file;
} DataStructures;

DataStructures* initialize_data_structures() {
    DataStructures* ds = (DataStructures*)malloc(sizeof(DataStructures));
    if (!ds) {
        perror("Failed to allocate memory for data structures");
        return NULL;
    }

    ds->timestamps = (time_t*)calloc(MAX_MESSAGES, sizeof(time_t));
    ds->sensor_readings = (float*)calloc(MAX_MESSAGES, sizeof(float));
    ds->device_statuses = (char**)malloc(MAX_MESSAGES * sizeof(char*));
    ds->message_payloads = (MessagePayload**)malloc(MAX_MESSAGES * sizeof(MessagePayload*));
    ds->device_ids = (char**)malloc(MAX_MESSAGES * sizeof(char*));
    ds->batch_metadata = (BatchMetadata*)malloc(sizeof(BatchMetadata));

    if (!ds->timestamps || !ds->sensor_readings || !ds->device_statuses || !ds->message_payloads ||
        !ds->device_ids || !ds->batch_metadata) {
        perror("Failed to allocate memory for individual data structures");
        free(ds);
        return NULL;
    }

    ds->logging_file = fopen("log.txt", "w");
    if (!ds->logging_file) {
        perror("Failed to open log file");
        free(ds->timestamps);
        free(ds->sensor_readings);
        free(ds->device_statuses);
        free(ds->message_payloads);
        free(ds->device_ids);
        free(ds->batch_metadata);
        free(ds);
        return NULL;
    }

    // Initialize other data structures and populate with random data
    for (int i = 0; i < MAX_MESSAGES; i++) {
        ds->device_statuses[i] = (char*)malloc(256 * sizeof(char));
        ds->message_payloads[i] = (MessagePayload*)malloc(sizeof(MessagePayload));
        // Populate with random data and set priority levels
    }

    // Initialize batch metadata
    ds->batch_metadata->last_update = time(NULL);
    ds->batch_metadata->batch_size = MAX_MESSAGES;
    ds->batch_metadata->messages = (MessageReference**)malloc(MAX_MESSAGES * sizeof(MessageReference*));

