typedef struct {
    int key;
    size_t size;
    char* data;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} StorageSystem;

StorageSystem* create_storage_system(size_t initial_capacity) {
    StorageSystem* system = (StorageSystem*)malloc(sizeof(StorageSystem));
    if (!system) return NULL;

    system->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!system->records) {
        free(system);
        return NULL;
    }

    system->capacity = initial_capacity;
    system->count = 0;
    pthread_mutex_init(&system->lock, NULL);

    return system;
}

void destroy_storage_system(StorageSystem* system) {
    for (size_t i = 0; i < system->count; ++i) {
        free(system->records[i]->data);
        free(system->records[i]);
    }
    free(system->records);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

Record* create_record(int key, size_t size, const char* data) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->size = size;
    record->data = (char*)malloc(size);
    if (!record->data) {
        free(record);
        return NULL;
    }

    memcpy(record->data, data, size);

    return record;
}

void destroy_record(Record* record) {
    free(record->data);
    free(record);
}

int add_record(StorageSystem* system, Record* record) {
    pthread_mutex_lock(&system->lock);
    if (system->count >= system->capacity) {
        size_t new_capacity = system->capacity * 2;
        Record** new_records = (Record**)realloc(system->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&system->lock);
            return -1; // Out of memory
        }
        system->records = new_records;
        system->capacity = new_capacity;
    }

    system->records[system->count++] = record;
    pthread_mutex_unlock(&system->lock);

    return 0;
}

Record* get_record(StorageSystem* system, int key) {
    pthread_mutex_lock(&system->lock);
    for (size_t i = 0; i < system->count; ++i) {
        if (system->records[i]->key == key) {
            Record* record = system->records[i];
            pthread_mutex_unlock(&system->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&system->lock);
    return NULL;
}

int remove_record(StorageSystem* system, int key) {
    pthread_mutex_lock(&system->lock);
    for (size_t i = 0; i < system->count; ++i) {
        if (system->records[i]->key == key) {
            destroy_record(system->records[i]);
            memmove(&system->records[i], &system->records[i + 1], (system->count - i - 1) * sizeof(Record*));
            --system->count;
            pthread_mutex_unlock(&system->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&system->lock);
    return -1; // Record not found
}

