// Function to dynamically manage memory for multiple geometric shapes
Shape** createShapes(int numShapes, areaCalculationFunction calculateArea) {
    if (numShapes <= 0 || calculateArea == NULL) {
        return NULL;
    }

    Shape** shapes = (Shape**)malloc(numShapes * sizeof(Shape*));
    if (shapes == NULL) {
        fprintf(stderr, "Memory allocation failed for shapes array.\n");
        return NULL;
    }

    for (int i = 0; i < numShapes; i++) {
        shapes[i] = (Shape*)malloc(sizeof(Shape));
        if (shapes[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for shape %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(shapes[j]);
            }
            free(shapes);
            return NULL;
        }

        shapes[i]->point = (Point*)malloc(sizeof(Point));
        if (shapes[i]->point == NULL) {
            fprintf(stderr, "Memory allocation failed for point in shape %d.\n", i);
            // Free previously allocated memory
            free(shapes[i]);
            for (int j = 0; j < i; j++) {
                free(shapes[j]->point);
                free(shapes[j]);
            }
            free(shapes);
            return NULL;
        }

        shapes[i]->perimeter = 0.0;
        shapes[i]->color = RED; // Default color
        shapes[i]->area = 0.0;

        // Populate the area using the user-provided function
        shapes[i]->area = calculateArea(*shapes[i]);
    }

    return shapes;
}

