#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t records_lock;

void initialize_records() {
    pthread_mutex_init(&records_lock, NULL);
}

void add_record(int value) {
    pthread_mutex_lock(&records_lock);
    if (record_count < MAX_RECORDS) {
        records[record_count].value = value;
        record_count++;
    }
    pthread_mutex_unlock(&records_lock);
}

int get_record_value(int id) {
    if (id >= 0 && id < record_count) {
        return records[id].value;
    }
    return -1; // Invalid ID
}

void update_record(int id, int new_value) {
    pthread_mutex_lock(&records_lock);
    if (id >= 0 && id < record_count) {
        records[id].value = new_value;
    }
    pthread_mutex_unlock(&records_lock);
}

void delete_record(int id) {
    pthread_mutex_lock(&records_lock);
    if (id >= 0 && id < record_count) {
        records[id].value = 0; // Reset to default value
    }
    pthread_mutex_unlock(&records_lock);
}

