    if (!ctx) {
        perror("Failed to create cipher context");
        return NULL;
    }

    const char *env_dir = getenv("MY_DIR_ENV_VAR");
    if (env_dir && strlen(env_dir) > 0) {
        // Use the environment variable if it's set and valid
        printf("Using directory from environment: %s\n", env_dir);
    } else {
        // Create a new directory if the environment variable is not set or invalid
        char *new_dir = malloc(strlen(dir_name) + 10); // Allocate enough space for path and "/newdir"
        snprintf(new_dir, strlen(dir_name) + 10, "%s/newdir", dir_name);
        if (mkdir(new_dir, 0755) == -1) {
            perror("Failed to create directory");
            EVP_CIPHER_CTX_free(ctx);
            free(new_dir);
            return NULL;
        }
        printf("Created new directory: %s\n", new_dir);

        // Set the environment variable atomically
        if (setenv("MY_DIR_ENV_VAR", new_dir, 1) == -1) {
            perror("Failed to set environment variable");
            EVP_CIPHER_CTX_free(ctx);
            free(new_dir);
            return NULL;
        }
        printf("Set environment variable: MY_DIR_ENV_VAR=%s\n", new_dir);

        // Free the allocated memory for the new directory path
        free(new_dir);
    }

    // Perform the specific operation using OpenSSL (example: initialize cipher)
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, (unsigned char *)"0123456789abcdef", (unsigned char *)"0123456789abcdef")) {
        perror("Failed to initialize cipher");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    printf("Cipher operation initialized successfully\n");
    return ctx;
}
