#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define RECORD_THRESHOLD 500000

typedef struct {
    int value;
} record;

record* allocate_records(int count, long* offsets, int* keys) {
    if (count > MAX_RECORDS) {
        fprintf(stderr, "Error: Record count exceeds maximum limit.\n");
        return NULL;
    }

    record* records = malloc(count * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < count; i++) {
        offsets[i] = rand() % 1000000L; // Example offset calculation
        keys[i] = rand() % 1000; // Example key calculation
        records[i].value = rand() % (RECORD_THRESHOLD + 1); // Initialize with random value
    }

    return records;
}

void* thread_function(void* arg) {
    int count = *(int*)arg;
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];

    record* records = allocate_records(count, offsets, keys);
    if (!records) {
        pthread_exit(NULL);
    }

    // Simulate processing
    for (int i = 0; i < count; i++) {
        // Process each record
    }

    free(records);
    pthread_exit(NULL);
}

int main() {
    int num_threads = 4;
    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_args[i] = MAX_RECORDS / num_threads * (i + 1);
        if (pthread_create(&threads[i], NULL, thread_function, &thread_args[i]) != 0) {
            perror("Thread creation failed");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
```

