#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    CIPHER_DES_ECB,
    CIPHER_DES_EDE,
    CIPHER_DES_EDE3,
    CIPHER_AES_128,
    CIPHER_AES_192,
    CIPHER_AES_256,
    CIPHER_CHACHA20
} CipherType;

EVP_CIPHER* select_cipher(CipherType type, const char* key, const char* iv) {
    EVP_CIPHER* cipher = NULL;
    switch (type) {
        case CIPHER_DES_ECB:
            cipher = EVP_des_ecb();
            break;
        case CIPHER_DES_EDE:
            cipher = EVP_des_ede3_cbc();
            break;
        case CIPHER_AES_128:
            cipher = EVP_aes_128_cbc();
            break;
        case CIPHER_AES_192:
            cipher = EVP_aes_192_cbc();
            break;
        case CIPHER_AES_256:
            cipher = EVP_aes_256_cbc();
            break;
        case CIPHER_CHACHA20:
            cipher = EVP_chacha20_poly1305();
            break;
        default:
            return NULL; // Invalid cipher type
    }

    if (cipher == NULL) {
        return NULL; // OpenSSL error
    }

    // Validate key and IV lengths
    size_t key_len = EVP_CIPHER_key_length(cipher);
    size_t iv_len = EVP_CIPHER_iv_length(cipher);

    if ((key == NULL || strlen(key) != key_len) ||
        (iv == NULL && iv_len > 0)) {
        return NULL; // Invalid key or IV
    }

    return cipher;
}

int main() {
    CipherType type = CIPHER_AES_256;
    const char* key = "0123456789abcdef0123456789abcdef";
    const char* iv = "01234567";

    EVP_CIPHER* cipher = select_cipher(type, key, iv);
    if (cipher != NULL) {
        // Use the cipher for encryption/decryption
        EVP_CIPHER_free(cipher);
    }

    return 0;
}
```

This code snippet provides a basic implementation of a flexible cryptographic cipher selector in C using OpenSSL. It includes error handling for invalid cipher types, key lengths, and IV requirements. The `select_cipher` function dynamically selects the appropriate OpenSSL cipher based on the input parameters and returns a pointer to an `EVP_CIPHER` structure. The main function demonstrates how to use this cipher selector with AES-256 in CBC mode.']

