#define AES_IV_SIZE 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_IV_SIZE];
} aes_cipher_ctx_t;

aes_cipher_ctx_t* aes_init(const char *password, int password_len) {
    aes_cipher_ctx_t *ctx = malloc(sizeof(aes_cipher_ctx_t));
    if (!ctx) return NULL;

    // Securely derive key and IV from the password
    if (PKCS5_PBKDF2_HMAC(password, password_len, NULL, 0, 10000, EVP_sha256(), AES_KEY_SIZE, ctx->key) != 1 ||
        RAND_bytes(ctx->iv, AES_IV_SIZE) != 1) {
        free(ctx);
        return NULL;
    }

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx->key);
        free(ctx);
        return NULL;
    }

    // Initialize the cipher context
    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx->key);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void aes_cleanup(aes_cipher_ctx_t *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx->key);
        free(ctx);
    }
}

