#include <vector>
#include <cstdlib>
#include <ctime>
#include <atomic>

struct Record {
    int value;
    size_t dataSize;
    time_t lastAccessed;
};

void processVectorAndInitializeData(std::vector<int>& vec, int findValue, int replaceValue, int appendValue) {
    auto it = std::find(vec.begin(), vec.end(), findValue);
    if (it != vec.end()) {
        *it = replaceValue;
    } else {
        vec.push_back(appendValue);
    }
}

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation failure
        throw std::bad_alloc();
    }
    return ptr;
}

void initializeArrays(size_t initialSize, int valueRange, double scalingFactor,
                      long*& offsetArray, int*& keyArray, Record*& recordArray) {
    size_t capacity = static_cast<size_t>(initialSize * scalingFactor);
    offsetArray = static_cast<long*>(allocateMemory(capacity * sizeof(long)));
    keyArray = static_cast<int*>(allocateMemory(capacity * sizeof(int)));
    recordArray = static_cast<Record*>(allocateMemory(capacity * sizeof(Record)));

    for (size_t i = 0; i < capacity; ++i) {
        offsetArray[i] = rand() % initialSize;
        keyArray[i] = rand() % valueRange;
        recordArray[i].value = rand() % valueRange;
        recordArray[i].dataSize = rand() % 1024 + 1;
        recordArray[i].lastAccessed = time(nullptr);
    }
}

void resizeArrays(long*& offsetArray, int*& keyArray, Record*& recordArray,
                 size_t& capacity, double scalingFactor) {
    size_t newCapacity = static_cast<size_t>(capacity * scalingFactor);
    long* newOffsetArray = static_cast<long*>(allocateMemory(newCapacity * sizeof(long)));
    int* newKeyArray = static_cast<int*>(allocateMemory(newCapacity * sizeof(int)));
    Record* newRecordArray = static_cast<Record*>(allocateMemory(newCapacity * sizeof(Record)));

    // Copy existing data to new arrays
    std::copy(offsetArray, offsetArray + capacity, newOffsetArray);
    std::copy(keyArray, keyArray + capacity, newKeyArray);
    std::copy(recordArray, recordArray + capacity, newRecordArray);

    // Free old memory
    free(offsetArray);
    free(keyArray);
    free(recordArray);

    // Update pointers and capacity
    offsetArray = newOffsetArray;
    keyArray = newKeyArray;
    recordArray = newRecordArray;
    capacity = newCapacity;
}

void freeMemory(long* offsetArray, int* keyArray, Record* recordArray) {
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}
