typedef struct {
    double temperature;
    time_t timestamp;
    char location[100];
} WeatherData;

typedef struct {
    WeatherData *data;
    int count;
    int capacity;
} WeatherRecordSet;

typedef struct {
    WeatherData *predictions;
    int count;
    int capacity;
} ForecastSet;

// Function to initialize weather data record set
WeatherRecordSet* init_weather_record_set() {
    WeatherRecordSet *set = (WeatherRecordSet*)malloc(sizeof(WeatherRecordSet));
    if (!set) return NULL;
    set->data = NULL;
    set->count = 0;
    set->capacity = 0;
    return set;
}

// Function to add weather data to the record set
void add_weather_data(WeatherRecordSet *set, WeatherData data) {
    // Resize if necessary
    if (set->count >= set->capacity) {
        set->capacity = (set->capacity == 0) ? 1 : set->capacity * 2;
        set->data = realloc(set->data, set->capacity * sizeof(WeatherData));
    }
    set->data[set->count++] = data;
}

// Function to generate random temperature within a specified range
double generate_random_temperature(double min, double max) {
    if (min > max) return -1; // Invalid range
    return min + (rand() / (RAND_MAX / (max - min)));
}

// Example usage and test cases
