    srand(time(NULL)); // Seed for random number generation

    WeatherRecordSet *weather_set = init_weather_record_set();
    if (!weather_set) {
        fprintf(stderr, "Failed to initialize weather record set\n");
        return 1;
    }

    WeatherData data;
    data.temperature = generate_random_temperature(-20.0, 40.0);
    data.timestamp = time(NULL);
    strcpy(data.location, "New York");

    add_weather_data(weather_set, data);

    // Add more test cases and edge cases here

    free(weather_set->data);
    free(weather_set);

    return 0;
}
