#include <time.h>

typedef struct {
    int value;
    size_t size;
    void* offset;
} record;

int random_between(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void process_and_sort_records(record** records, size_t* num_records, int min_val, int max_val, int (*compare)(const void*, const void*)) {
    *num_records = 5; // Example number of records
    *records = malloc(*num_records * sizeof(record));

    for (size_t i = 0; i < *num_records; ++i) {
        (*records)[i].value = random_between(min_val, max_val);
        (*records)[i].size = sizeof(int);
        (*records)[i].offset = &((*records)[i].value);
    }

    qsort(*records, *num_records, sizeof(record), compare);

    // Example usage of custom comparison function
    int descending_compare(const void* a, const void* b) {
        return ((record*)b)->value - ((record*)a)->value;
    }
    qsort(*records, *num_records, sizeof(record), descending_compare);
}

void free_records(record** records, size_t num_records) {
    free(*records);
    *records = NULL;
}

int main() {
    record* records;
    size_t num_records;

    srand(time(NULL));
    process_and_sort_records(&records, &num_records, 10, 100, qsort);

    for (size_t i = 0; i < num_records; ++i) {
        printf("Value: %d\n", records[i].value);
    }

    free_records(&records, num_records);
    return 0;
}
