#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_DEVICES 1024
#define PAYLOAD_SIZE 1024

typedef enum {
    STATUS_OK,
    STATUS_WARNING,
    STATUS_ERROR
} DeviceStatus;

typedef struct {
    int sequence_number;
    char buffer[PAYLOAD_SIZE];
} MessagePayload;

typedef struct {
    long timestamp;
    float sensor_reading;
    DeviceStatus status;
    MessagePayload payload;
    char device_id[10];
} DeviceData;

DeviceData* devices[MAX_DEVICES];
int device_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_device(DeviceData** device) {
    *device = (DeviceData*)malloc(sizeof(DeviceData));
    (*device)->timestamp = time(NULL);
    (*device)->sensor_reading = (float)(rand() % 100) / 10.0;
    (*device)->status = STATUS_OK;
    (*device)->payload.sequence_number = rand();
    snprintf((*device)->payload.buffer, PAYLOAD_SIZE, "Initial message");
    snprintf((*device)->device_id, 10, "Device%d", device_count);
}

void* add_device(void* arg) {
    pthread_mutex_lock(&mutex);
    if (device_count < MAX_DEVICES) {
        initialize_device(&devices[device_count]);
        device_count++;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void validate_timestamps(int threshold) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < device_count; i++) {
        if ((time(NULL) - devices[i]->timestamp) > threshold) {
            devices[i]->sensor_reading = (float)(rand() % 100) / 10.0;
            devices[i]->status = STATUS_WARNING;
            snprintf(devices[i]->payload.buffer, PAYLOAD_SIZE, "Timestamp updated");
        }
    }
    pthread_mutex_unlock(&mutex);
}

void log_update(DeviceData* device) {
    FILE* log_file = fopen("device_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "Device ID: %s, Timestamp: %ld, Reading: %.2f, Status: %d, Payload: %s\n",
                device->device_id, device->timestamp, device->sensor_reading, device->status, device->payload.buffer);
        fclose(log_file);
    }
}

void backup_data() {
    FILE* backup_file = fopen("device_backup.dat", "wb");
    if (backup_file != NULL) {
        fwrite(devices, sizeof(DeviceData), device_count, backup_file);
        fclose(backup_file);
    }
}

int main() {
    pthread_t thread;
    srand(time(NULL));

    // Add devices
    for (int i = 0; i < 5; i++) {
        pthread_create(&thread, NULL, add_device, NULL);
        pthread_join(thread, NULL);
    }

    // Validate timestamps and log updates
    validate_timestamps(60); // Every minute
    for (int i = 0; i < device_count; i++) {
        log_update(devices[i]);
    }

    // Backup data
    backup_data();

    return 0;
}
