#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for image processing tasks
typedef struct {
    char *filename;
    int target_width;
    int target_height;
    char *filter_algorithm;
    char *output_format;
    // Add other metadata fields as needed
} ImageTask;

// Define the priority queue structure
typedef struct {
    ImageTask **tasks;
    int size;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} TaskQueue;

// Function to initialize the task queue
void init_task_queue(TaskQueue *queue, int initial_capacity) {
    queue->tasks = (ImageTask **)malloc(initial_capacity * sizeof(ImageTask *));
    if (!queue->tasks) {
        perror("Failed to allocate memory for task queue");
        exit(EXIT_FAILURE);
    }
    queue->size = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

// Function to add a task to the priority queue
void enqueue_task(TaskQueue *queue, ImageTask *task) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->tasks[queue->size++] = task;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

// Function to remove and return the highest priority task from the queue
ImageTask *dequeue_task(TaskQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    ImageTask *task = queue->tasks[0];
    for (int i = 1; i < queue->size; i++) {
        queue->tasks[i - 1] = queue->tasks[i];
    }
    queue->size--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return task;
}

// Function to free all allocated memory for the task queue
void free_task_queue(TaskQueue *queue) {
    for (int i = 0; i < queue->size; i++) {
        free(queue->tasks[i]);
    }
    free(queue->tasks);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
}

// Function to process image tasks
void *process_image_tasks(void *arg) {
    TaskQueue *queue = (TaskQueue *)arg;
    while (1) {
        ImageTask *task = dequeue_task(queue);
        if (!task) break; // Exit thread when no more tasks are available

        // Process the task here
        printf("Processing image: %s\n", task->filename);

        // Free the task after processing
        free(task);
    }
    return NULL;
}

int main() {
    TaskQueue queue;
    init_task_queue(&queue, 10);

    // Example usage of the task queue
    ImageTask *task = (ImageTask *)malloc(sizeof(ImageTask));
    strcpy(task->filename, "example.jpg");
    task->target_width = 800;
    task->target_height = 600;
    strcpy(task->filter_algorithm, "gaussian");
    strcpy(task->output_format, "png");

    enqueue_task(&queue, task);

    // Create and start worker threads
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, process_image_tasks, &queue);
    pthread_create(&thread2, NULL, process_image_tasks, &queue);

    // Wait for all tasks to be processed
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free_task_queue(&queue);
    return 0;
}
