typedef struct {
    time_t timestamp;
    double amount;
    char status[20];
    char category[50];
} FinancialOperation;

typedef struct {
    FinancialOperation *operations;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} FinancialManager;

FinancialManager* financial_manager_init(size_t initial_capacity) {
    FinancialManager *manager = (FinancialManager*)malloc(sizeof(FinancialManager));
    manager->operations = (FinancialOperation*)calloc(initial_capacity, sizeof(FinancialOperation));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void financial_manager_add_operation(FinancialManager *manager, FinancialOperation operation) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->operations = realloc(manager->operations, new_capacity * sizeof(FinancialOperation));
        manager->capacity = new_capacity;
    }
    manager->operations[manager->count++] = operation;
    pthread_mutex_unlock(&manager->lock);
}

void financial_manager_free(FinancialManager *manager) {
    free(manager->operations);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
```

