        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i * 100L; // Example initialization
        key_array[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        record_array[i].value = i;
    }

    // Shuffle records
    for (int i = num_records - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        record temp = record_array[i];
        record_array[i] = record_array[j];
        record_array[j] = temp;
    }

