#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    FREE,
    OCCUPIED
} status;

typedef struct record {
    int key;
    long offset;
    status state;
} record;

typedef struct memory_pool {
    record *pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} memory_pool;

memory_pool *create_memory_pool(size_t initial_size) {
    memory_pool *mp = (memory_pool *)malloc(sizeof(memory_pool));
    mp->pool = (record *)calloc(initial_size, sizeof(record));
    mp->size = initial_size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(memory_pool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

int allocate_record(memory_pool *mp, int key, long offset) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->size; ++i) {
        if (mp->pool[i].state == FREE && mp->pool[i].key == key) {
            mp->pool[i].offset = offset;
            mp->pool[i].state = OCCUPIED;
            pthread_mutex_unlock(&mp->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&mp->lock);
    return -1; // Key not found or pool full
}

void deallocate_record(memory_pool *mp, int key) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->size; ++i) {
        if (mp->pool[i].state == OCCUPIED && mp->pool[i].key == key) {
            mp->pool[i].state = FREE;
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

void *thread_function(void *arg) {
    memory_pool *mp = (memory_pool *)arg;
    int key = rand() % 1000; // Example unique key generation
    long offset = rand(); // Example offset value

    if (allocate_record(mp, key, offset) == 0) {
        printf("Record allocated for key: %d\n", key);
    } else {
        printf("Failed to allocate record for key: %d\n", key);
    }

    deallocate_record(mp, key);
    return NULL;
}

int main() {
    memory_pool *mp = create_memory_pool(100); // Initial pool size of 100 records

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, thread_function, mp);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(mp);
    return 0;
}
```

This code provides a basic implementation of a memory pool for managing records in a multi-threaded environment. It includes functions for creating and destroying the memory pool, allocating and deallocating records, and handling concurrent access using mutex locks. The example demonstrates how to use these functions in a simple multi-threaded scenario.']

