using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class QueryConfig
{
    public string QueryType { get; set; }
    public Dictionary<string, object> Conditions { get; set; }
    public List<string> SortCriteria { get; set; }
    public int PageNumber { get; set; }
    public int PageSize { get; set; }
    public CipherMode CipherMode { get; set; }
    public bool UseNullEncryption { get; set; }
}

public enum CipherMode
{
    ECB,
    EDE,
    EDE3,
    CFB
}

public class DatabaseHelper
{
    public static List<Dictionary<string, object>> ExecuteDynamicSQLQuery(
        SqlConnection connection,
        QueryConfig config)
    {
        if (connection == null || !connection.State.HasFlag(ConnectionState.Open))
            throw new ArgumentException("Invalid database connection.");

        if (config == null)
            throw new ArgumentNullException(nameof(config));

        var parameters = new Dictionary<string, object>();
        foreach (var condition in config.Conditions)
        {
            parameters.Add($"@{condition.Key}", condition.Value);
        }

        string query = $"SELECT * FROM {config.QueryType} WHERE 1=1";
        foreach (var param in parameters)
        {
            query += $" AND {param.Key} = @{param.Key}";
        }

        if (config.SortCriteria != null && config.SortCriteria.Count > 0)
        {
            query += " ORDER BY ";
            query += string.Join(", ", config.SortCriteria);
        }

        query += $" OFFSET {(config.PageNumber - 1) * config.PageSize} ROWS FETCH NEXT {config.PageSize} ROWS ONLY";

        using (var command = new SqlCommand(query, connection))
        {
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }

            var results = new List<Dictionary<string, object>>();
            using (var reader = command.ExecuteReader())
            {
                while (reader.Read())
                {
                    var row = new Dictionary<string, object>();
                    for (int i = 0; i < reader.FieldCount; i++)
                    {
                        row[reader.GetName(i)] = reader[i];
                    }
                    results.Add(row);
                }
            }

            return results;
        }
    }
}
