#include <time.h>

typedef struct {
    int value;
    size_t size;
    time_t timestamp;
} record;

typedef struct {
    unsigned long accessCount;
    double totalAccessTime;
    time_t lastAccessed;
} metadata;

typedef struct {
    char* message;
    time_t timestamp;
} logEntry;

typedef struct {
    void** data;
    size_t capacity;
    size_t size;
} secondaryStorage;

void allocateAndInitializeData(size_t initialSize, int valueRange, time_t updateInterval, size_t maxLogCapacity, double resizeFactor) {
    // Allocate memory for each data structure
    long* offsetValues = (long*)malloc(initialSize * sizeof(long));
    int* keys = (int*)malloc(initialSize * sizeof(int));
    record* records = (record*)malloc(initialSize * sizeof(record));
    metadata* metadataStructs = (metadata*)malloc(initialSize * sizeof(metadata));
    logEntry* logs = (logEntry*)malloc(maxLogCapacity * sizeof(logEntry));
    secondaryStorage* storage = (secondaryStorage*)malloc(sizeof(secondaryStorage));

    // Initialize each data structure
    for (size_t i = 0; i < initialSize; ++i) {
        offsetValues[i] = rand() % (2 * valueRange + 1);
        keys[i] = rand();
        records[i].value = rand() % (2 * valueRange + 1);
        records[i].size = sizeof(record);
        records[i].timestamp = time(NULL);
        metadataStructs[i].accessCount = 0;
        metadataStructs[i].totalAccessTime = 0.0;
        metadataStructs[i].lastAccessed = time(NULL);
        logs[i].message = (char*)malloc(256 * sizeof(char));
        sprintf(logs[i].message, "Log entry %zu", i);
        logs[i].timestamp = time(NULL);
        storage->data = (void**)realloc(storage->data, (i + 1) * sizeof(void*));
        storage->data[i] = malloc(sizeof(record));
        memcpy(storage->data[i], &records[i], sizeof(record));
    }

    // Shuffle records randomly
    for (size_t i = initialSize - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }

    // Log initialization process
    printf("Initialization complete.\n");

    // Free allocated memory
    free(offsetValues);
    free(keys);
    for (size_t i = 0; i < initialSize; ++i) {
        free(records[i].message);
        free(storage->data[i]);
    }
    free(records);
    free(metadataStructs);
    for (size_t i = 0; i < maxLogCapacity; ++i) {
        free(logs[i].message);
    }
    free(logs);
    free(storage->data);
    free(storage);
}
