using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Linq;
using log4net;

public class GameConfigManager
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(GameConfigManager));
    private Dictionary<string, object> configCache = new Dictionary<string, object>();
    private XDocument configXml;

    public GameConfigManager(string configFilePath)
    {
        LoadConfig(configFilePath);
    }

    private void LoadConfig(string filePath)
    {
        try
        {
            if (!File.Exists(filePath))
            {
                Log.Error("Configuration file not found: " + filePath);
                throw new FileNotFoundException("Configuration file not found.");
            }

            configXml = XDocument.Load(filePath);
            Log.Info("Configuration loaded successfully.");
        }
        catch (Exception ex)
        {
            Log.Fatal("Failed to load configuration file.", ex);
            throw;
        }
    }

    public T GetConfig<T>(string key)
    {
        if (!configCache.ContainsKey(key))
        {
            var value = configXml.Descendants(key).FirstOrDefault()?.Value;
            if (value == null)
            {
                Log.Warn($"Configuration key '{key}' not found.");
                return default(T);
            }

            try
            {
                var parsedValue = Convert.ChangeType(value, typeof(T));
                configCache[key] = parsedValue;
                Log.Debug($"Cached configuration value for '{key}': {parsedValue}");
            }
            catch (Exception ex)
            {
                Log.Error($"Failed to parse configuration value for '{key}'.", ex);
                return default(T);
            }
        }

        return (T)configCache[key];
    }

    public void UpdateConfig(string key, object newValue)
    {
        var element = configXml.Descendants(key).FirstOrDefault();
        if (element == null)
        {
            Log.Warn($"Configuration key '{key}' not found.");
            return;
        }

        element.Value = newValue.ToString();
        SaveConfig();
        Log.Info($"Updated configuration value for '{key}': {newValue}");
    }

    private void SaveConfig()
    {
        try
        {
            configXml.Save(configXml.BaseUri.LocalPath);
            Log.Info("Configuration saved successfully.");
        }
        catch (Exception ex)
        {
            Log.Fatal("Failed to save configuration file.", ex);
            throw;
        }
    }
}
