            free(dynamic_array[i]->stats);
            free(dynamic_array[i]);
        }
        free(dynamic_array);
        dynamic_array = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

void* thread_function(void* arg) {
    int index = *(int*)arg;
    populate_frame(index, index * 100); // Example data
    return NULL;
}

int main() {
    load_config();
    initialize_dynamic_array(MAX_FRAMES);

    pthread_t threads[MAX_FRAMES];
    int indices[MAX_FRAMES];

    for (int i = 0; i < MAX_FRAMES; i++) {
        indices[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &indices[i]);
    }

    for (int i = 0; i < MAX_FRAMES; i++) {
        pthread_join(threads[i], NULL);
    }

    free_dynamic_array();
    return 0;
}
