#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct {
    int value;
} record;

void load_config(const char* filename, int* offset_size, int* key_size) {
    xmlDocPtr doc = xmlReadFile(filename, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        exit(EXIT_FAILURE);
    }

    xmlNodePtr root_node = xmlDocGetRootElement(doc);
    xmlNodePtr cur_node = root_node->children;

    while (cur_node != NULL) {
        if (xmlStrcmp(cur_node->name, (const xmlChar *)"offset_size") == 0) {
            *offset_size = atoi((char*)xmlNodeGetContent(cur_node));
        } else if (xmlStrcmp(cur_node->name, (const xmlChar *)"key_size") == 0) {
            *key_size = atoi((char*)xmlNodeGetContent(cur_node));
        }
        cur_node = cur_node->next;
    }

    xmlFreeDoc(doc);
}

record* allocate_records(int size) {
    record* records = malloc(size * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return records;
}

void populate_records(record* records, int size, int min_value, int max_value) {
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void shuffle_records(record* records, int size) {
    for (int i = size - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        record temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }
}

void log_message(const char* message, const char* log_file) {
    FILE* file = fopen(log_file, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

void free_records(record* records, int size) {
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <config_file> <min_value> <max_value> <max_memory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int offset_size, key_size;
    load_config(argv[1], &offset_size, &key_size);

    record* records = allocate_records(offset_size);
    populate_records(records, offset_size, atoi(argv[2]), atoi(argv[3]));
    shuffle_records(records, offset_size);

    log_message("Records initialized and shuffled", "app.log");

    free_records(records, offset_size);

    return EXIT_SUCCESS;
}
