long* generate_random_numbers(int min, int max, int count) {
    long* numbers = (long*)malloc(count * sizeof(long));
    if (numbers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < count; i++) {
        numbers[i] = min + rand() % (max - min + 1);
    }
    return numbers;
}

void process_and_find_max(int min, int max, int input_count) {
    if (input_count <= 0) {
        fprintf(stderr, "Invalid input count\n");
        return;
    }

    long* offsets = generate_random_numbers(0, 1000, input_count);
    int* keys = generate_random_numbers(min, max, input_count);

    record* records = (record*)malloc(input_count * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < input_count; i++) {
        records[i].value = keys[i];
        records[i].size = sizeof(int);
        records[i].offset = &offsets[i];
    }

    int max_value = INT_MIN;
    for (int i = 0; i < input_count; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Maximum value: %d\n", max_value);

    free(records);
    free(keys);
    free(offsets);
}

int main() {
    srand(time(NULL));
    int min, max, input_count;
    printf("Enter minimum and maximum values for random numbers: ");
    scanf("%d %d", &min, &max);
    printf("Enter the number of integers to read: ");
    scanf("%d", &input_count);

    process_and_find_max(min, max, input_count);

    return 0;
}
