void init_log_array(LogArray *log_array, size_t initial_capacity) {
    log_array->entries = (LogEntry **)malloc(initial_capacity * sizeof(LogEntry *));
    if (!log_array->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    log_array->count = 0;
    log_array->capacity = initial_capacity;
}

void add_log_entry(LogArray *log_array, LogEntry *entry) {
    if (log_array->count == log_array->capacity) {
        size_t new_capacity = log_array->capacity * 2;
        LogEntry **new_entries = (LogEntry **)realloc(log_array->entries, new_capacity * sizeof(LogEntry *));
        if (!new_entries) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        log_array->entries = new_entries;
        log_array->capacity = new_capacity;
    }
    log_array->entries[log_array->count++] = entry;
}

