        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < count; ++i) {
        numbers[i] = min + rand() % (max - min + 1);
    }
    return numbers;
}

void merge_sorted_records(record* arr1, int size1, record* arr2, int size2, record** result) {
    *result = (record*)malloc((size1 + size2) * sizeof(record));
    if (!(*result)) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    int i = 0, j = 0, k = 0;
    while (i < size1 && j < size2) {
        if (arr1[i].value <= arr2[j].value) {
            (*result)[k++] = arr1[i++];
        } else {
            (*result)[k++] = arr2[j++];
        }
    }
    while (i < size1) {
        (*result)[k++] = arr1[i++];
    }
    while (j < size2) {
        (*result)[k++] = arr2[j++];
    }
}

void process_and_find_max(int min, int max, int input_count) {
    long* offsets = generate_random_numbers(0, 1000, 6);
    int* keys = generate_random_numbers(min, max, 6);
    record* records = (record*)malloc(6 * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < 6; ++i) {
        records[i].value = keys[i];
        records[i].size = sizeof(int);
        records[i].offset = &offsets[i];
    }

    int* input_array = (int*)malloc(input_count * sizeof(int));
    if (!input_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < input_count; ++i) {
        scanf("%d", &input_array[i]);
    }

    record* merged_records;
    merge_sorted_records(records, 6, records + 3, 3, &merged_records);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(input_array);
    free(merged_records);
}

int main() {
    srand(time(NULL));
    int min = -100;
    int max = 100;
    int input_count = 10;
    process_and_find_max(min, max, input_count);
    return 0;
}
