typedef enum {
    INT_TYPE,
    FLOAT_TYPE,
    STRING_TYPE
} DataType;

typedef struct {
    int value;
    size_t size;
    DataType type;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    void** data_blocks;
    size_t total_memory_usage;
    size_t capacity;
    size_t size;
} DataManagementSystem;

DataManagementSystem* create_data_management_system(size_t initial_capacity) {
    DataManagementSystem* system = (DataManagementSystem*)malloc(sizeof(DataManagementSystem));
    if (!system) return NULL;

    system->offsets = (long*)calloc(initial_capacity, sizeof(long));
    system->keys = (int*)calloc(initial_capacity, sizeof(int));
    system->records = (Record*)calloc(initial_capacity, sizeof(Record));
    system->data_blocks = (void**)calloc(initial_capacity, sizeof(void*));
    if (!system->offsets || !system->keys || !system->records || !system->data_blocks) {
        free(system);
        return NULL;
    }

    system->total_memory_usage = 0;
    system->capacity = initial_capacity;
    system->size = 0;

    srand(time(NULL)); // Seed for random number generation

    return system;
}

void destroy_data_management_system(DataManagementSystem* system) {
    if (!system) return;

    for (size_t i = 0; i < system->size; ++i) {
        free(system->data_blocks[i]);
    }

    free(system->offsets);
    free(system->keys);
    free(system->records);
    free(system->data_blocks);

    free(system);
}

void add_record(DataManagementSystem* system, int key, int value, size_t data_size, DataType type) {
    if (system->size >= system->capacity) {
        // Resize the arrays
        long* new_offsets = (long*)realloc(system->offsets, system->capacity * 2 * sizeof(long));
        int* new_keys = (int*)realloc(system->keys, system->capacity * 2 * sizeof(int));
        Record* new_records = (Record*)realloc(system->records, system->capacity * 2 * sizeof(Record));
        void** new_data_blocks = (void**)realloc(system->data_blocks, system->capacity * 2 * sizeof(void*));

        if (!new_offsets || !new_keys || !new_records || !new_data_blocks) {
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        }

        system->offsets = new_offsets;
        system->keys = new_keys;
        system->records = new_records;
        system->data_blocks = new_data_blocks;
        system->capacity *= 2;
    }

    system->offsets[system->size] = system->total_memory_usage;
    system->keys[system->size] = key;
    system->records[system->size].value = value;
    system->records[system->size].size = data_size;
    system->records[system->size].type = type;

    switch (type) {
        case INT_TYPE:
            system->data_blocks[system->size] = malloc(data_size * sizeof(int));
            if (!system->data_blocks[system->size]) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            // Initialize data block with random values
            for (size_t i = 0; i < data_size; ++i) {
                ((int*)system->data_blocks[system->size])[i] = rand() % 100;
            }
            break;
        case FLOAT_TYPE:
            system->data_blocks[system->size] = malloc(data_size * sizeof(float));
            if (!system->data_blocks[system->size]) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            // Initialize data block with random values
            for (size_t i = 0; i < data_size; ++i) {
                ((float*)system->data_blocks[system->size])[i] = (float)(rand() % 100) / 100.0f;
            }
            break;
        case STRING_TYPE:
            system->data_blocks[system->size] = malloc(data_size * sizeof(char));
            if (!system->data_blocks[system->size]) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            // Initialize data block with random values
            for (size_t i = 0; i < data_size; ++i) {
                ((char*)system->data_blocks[system->size])[i] = 'a' + rand() % 26;
            }
            break;
    }

    system->total_memory_usage += data_size * sizeof(int); // Simplified for demonstration
    ++system->size;
}

int main() {
    DataManagementSystem* system = create_data_management_system(10);
    if (!system) return 1;

    add_record(system, 1, 42, 5, INT_TYPE);

    destroy_data_management_system(system);
    return 0;
}
```

