Record* create_records(int n, size_t max_memory, int min_int, int max_int, long min_long, long max_long, double min_double, double max_double) {
    if (n <= 0 || max_memory <= 0) return NULL;

    // Calculate the size of one record
    size_t record_size = sizeof(Record);
    size_t string_size = strlen("Hello World!") + 1;
    size_t total_size = n * (record_size + string_size);

    if (total_size > max_memory) {
        n = max_memory / (record_size + string_size);
        total_size = n * (record_size + string_size);
    }

    Record* records = malloc(total_size);
    if (!records) return NULL;

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        records[i].key = rand() % (max_int - min_int + 1) + min_int;
        records[i].offset = rand() % (max_long - min_long + 1) + min_long;
        records[i].value = ((double)rand() / RAND_MAX) * (max_double - min_double) + min_double;

        records[i].string = malloc(string_size);
        if (!records[i].string) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(records[j].string);
            free(records);
            return NULL;
        }
        strcpy(records[i].string, "Hello World!");
    }

    return records;
}

void free_records(Record* records, int n) {
    if (!records) return;

    for (int i = 0; i < n; ++i) {
        free(records[i].string);
    }
    free(records);
}
