#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct session {
    long* offsets;
    int* keys;
    Record** records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} Session;

unsigned int hash_function(int key, int capacity) {
    return (key * 31) % capacity;
}

Session* create_session(int initial_capacity) {
    Session* session = malloc(sizeof(Session));
    if (!session) return NULL;

    session->offsets = malloc(initial_capacity * sizeof(long));
    session->keys = malloc(initial_capacity * sizeof(int));
    session->records = malloc(initial_capacity * sizeof(Record*));
    if (!session->offsets || !session->keys || !session->records) {
        free(session);
        return NULL;
    }

    session->size = 0;
    session->capacity = initial_capacity;
    pthread_mutex_init(&session->lock, NULL);

    return session;
}

void destroy_session(Session* session) {
    for (int i = 0; i < session->size; i++) {
        free(session->records[i]);
    }
    free(session->offsets);
    free(session->keys);
    free(session->records);
    pthread_mutex_destroy(&session->lock);
    free(session);
}

void add_record(Session* session, int key, int value) {
    pthread_mutex_lock(&session->lock);

    if (session->size == session->capacity) {
        // Resize the arrays
        session->offsets = realloc(session->offsets, session->capacity * 2 * sizeof(long));
        session->keys = realloc(session->keys, session->capacity * 2 * sizeof(int));
        session->records = realloc(session->records, session->capacity * 2 * sizeof(Record*));
        if (!session->offsets || !session->keys || !session->records) {
            pthread_mutex_unlock(&session->lock);
            return;
        }
        session->capacity *= 2;
    }

    int index = hash_function(key, session->capacity);
    while (session->keys[index] != -1 && session->keys[index] != key) {
        index = (index + 1) % session->capacity; // Linear probing
    }

    if (session->keys[index] == -1) {
        session->size++;
    }

    session->keys[index] = key;
    Record* new_record = malloc(sizeof(Record));
    new_record->value = value;
    session->records[index] = new_record;

    pthread_mutex_unlock(&session->lock);
}

Record* get_record(Session* session, int key) {
    pthread_mutex_lock(&session->lock);

    int index = hash_function(key, session->capacity);
    while (session->keys[index] != -1 && session->keys[index] != key) {
        index = (index + 1) % session->capacity; // Linear probing
    }

    Record* record = NULL;
    if (session->keys[index] == key) {
        record = session->records[index];
    }

    pthread_mutex_unlock(&session->lock);
    return record;
}

// Documentation:
// To optimize for latency, increase the initial capacity of the session.
// To optimize for throughput, use a larger number of sessions and distribute keys evenly across them.
