#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    size_t dataSize;
    time_t timestamp;
    void* data;
    int refCount;
} record;

typedef struct {
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    int loggingEnabled;
    FILE* logFile;
} recordManager;

recordManager* createRecordManager(size_t initialCapacity, int enableLogging) {
    recordManager* manager = (recordManager*)malloc(sizeof(recordManager));
    if (!manager) return NULL;

    manager->records = (record**)calloc(initialCapacity, sizeof(record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    manager->loggingEnabled = enableLogging;

    if (enableLogging) {
        manager->logFile = fopen("record_manager.log", "w");
        if (!manager->logFile) {
            free(manager->records);
            pthread_mutex_destroy(&manager->mutex);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void destroyRecordManager(recordManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]->data);
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);

    if (manager->loggingEnabled && manager->logFile) {
        fclose(manager->logFile);
    }

    free(manager);
}

void* addRecord(recordManager* manager, int key, size_t dataSize, time_t timestamp, void* data, int refCount) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size == manager->capacity) {
        record** newRecords = (record**)realloc(manager->records, manager->capacity * 2 * sizeof(record*));
        if (!newRecords) {
            pthread_mutex_unlock(&manager->mutex);
            return NULL;
        }
        manager->records = newRecords;
        manager->capacity *= 2;
    }

    record* newRecord = (record*)malloc(sizeof(record));
    if (!newRecord) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    newRecord->key = key;
    newRecord->dataSize = dataSize;
    newRecord->timestamp = timestamp;
    newRecord->data = malloc(dataSize);
    if (!newRecord->data) {
        free(newRecord);
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }
    memcpy(newRecord->data, data, dataSize);
    newRecord->refCount = refCount;

    manager->records[manager->size++] = newRecord;

    if (manager->loggingEnabled) {
        fprintf(manager->logFile, "Added record with key %d\n", key);
    }

    pthread_mutex_unlock(&manager->mutex);
    return newRecord;
}

