typedef struct TaskList {
    Task** tasks;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TaskList;

Task* create_task(int id, int priority, time_t start_time, int duration) {
    Task* task = (Task*)malloc(sizeof(Task));
    if (task == NULL) {
        perror("Failed to allocate memory for task");
        return NULL;
    }
    task->id = id;
    task->priority = priority;
    task->start_time = start_time;
    task->duration = duration;
    // Initialize other fields as needed
    return task;
}

void free_task(Task* task) {
    if (task != NULL) {
        free(task);
    }
}

TaskList* create_task_list() {
    TaskList* list = (TaskList*)malloc(sizeof(TaskList));
    if (list == NULL) {
        perror("Failed to allocate memory for task list");
        return NULL;
    }
    list->tasks = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_task_list(TaskList* list) {
    if (list != NULL) {
        for (size_t i = 0; i < list->count; ++i) {
            free_task(list->tasks[i]);
        }
        free(list->tasks);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void add_task(TaskList* list, Task* task) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        Task** new_tasks = (Task**)realloc(list->tasks, new_capacity * sizeof(Task*));
        if (new_tasks == NULL) {
            perror("Failed to reallocate memory for task list");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }
    list->tasks[list->count++] = task;
    pthread_mutex_unlock(&list->lock);
}

void remove_task(TaskList* list, int id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i]->id == id) {
            free_task(list->tasks[i]);
            for (size_t j = i; j < list->count - 1; ++j) {
                list->tasks[j] = list->tasks[j + 1];
            }
            --list->count;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void modify_task(TaskList* list, int id, Task* new_task) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i]->id == id) {
            free_task(list->tasks[i]);
            list->tasks[i] = new_task;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

