    size_t bytes_transferred;
} TRANSFER_STATISTICS;

typedef struct {
    TCP_CONNECTION metadata;
    TRANSFER_STATISTICS *stats;
    size_t stats_count;
} CONNECTION_RECORD;

CONNECTION_RECORD *connections = NULL;
size_t connection_count = 0;
pthread_mutex_t connections_lock = PTHREAD_MUTEX_INITIALIZER;

void load_config() {
    // Load configuration from file
}

int add_connection(int id, const char *ip) {
    pthread_mutex_lock(&connections_lock);
    if (connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&connections_lock);
        return -1; // Error: Max connections reached
    }
    connections = realloc(connections, (connection_count + 1) * sizeof(CONNECTION_RECORD));
    if (connections == NULL) {
        pthread_mutex_unlock(&connections_lock);
        return -2; // Error: Insufficient memory
    }
    CONNECTION_RECORD *new_conn = &connections[connection_count++];
    new_conn->metadata.id = id;
    strcpy(new_conn->metadata.ip, ip);
    new_conn->stats = NULL;
    new_conn->stats_count = 0;
    pthread_mutex_unlock(&connections_lock);
    return 0; // Success
}

int add_transfer_stats(int conn_id, size_t bytes) {
    pthread_mutex_lock(&connections_lock);
    CONNECTION_RECORD *conn = NULL;
    for (size_t i = 0; i < connection_count; ++i) {
        if (connections[i].metadata.id == conn_id) {
            conn = &connections[i];
            break;
        }
    }
    if (conn == NULL || conn->stats_count >= MAX_STATS_PER_CONN) {
        pthread_mutex_unlock(&connections_lock);
        return -1; // Error: Invalid connection or max stats reached
    }
    TRANSFER_STATISTICS *new_stats = realloc(conn->stats, (conn->stats_count + 1) * sizeof(TRANSFER_STATISTICS));
    if (new_stats == NULL) {
        pthread_mutex_unlock(&connections_lock);
        return -2; // Error: Insufficient memory
    }
    conn->stats = new_stats;
    conn->stats[conn->stats_count].timestamp = time(NULL);
    conn->stats[conn->stats_count++].bytes_transferred = bytes;
    pthread_mutex_unlock(&connections_lock);
    return 0; // Success
}

void log_error(int error_code, const char *message) {
    // Log error with timestamp and code
}

int main() {
    load_config();
    add_connection(1, "192.168.1.1");
    add_transfer_stats(1, 1024);
    return 0;
}
