#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int value;
    size_t bufferSize;
    union {
        char* buffer;
        double doubleValue;
    } data;
} record;

typedef struct {
    size_t longArraySize;
    size_t intArraySize;
    size_t recordArraySize;
    int longRangeMin;
    int longRangeMax;
    int intValue;
    size_t bufferSize;
    int initialValue;
} config;

int initializeDataStructure(config* cfg, long** longArray, int** intArray, record** recordArray) {
    *longArray = (long*)malloc(cfg->longArraySize * sizeof(long));
    if (*longArray == NULL) {
        fprintf(stderr, "Failed to allocate memory for long array\n");
        return -1;
    }

    *intArray = (int*)malloc(cfg->intArraySize * sizeof(int));
    if (*intArray == NULL) {
        free(*longArray);
        fprintf(stderr, "Failed to allocate memory for int array\n");
        return -1;
    }

    *recordArray = (record*)malloc(cfg->recordArraySize * sizeof(record));
    if (*recordArray == NULL) {
        free(*longArray);
        free(*intArray);
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return -1;
    }

    // Initialize arrays and records
    for (size_t i = 0; i < cfg->longArraySize; ++i) {
        (*longArray)[i] = rand() % (cfg->longRangeMax - cfg->longRangeMin + 1) + cfg->longRangeMin;
    }

    for (size_t i = 0; i < cfg->intArraySize; ++i) {
        (*intArray)[i] = cfg->intValue;
    }

    for (size_t i = 0; i < cfg->recordArraySize; ++i) {
        (*recordArray)[i].value = cfg->initialValue;
        (*recordArray)[i].bufferSize = cfg->bufferSize;
        if (cfg->bufferSize > 0) {
            (*recordArray)[i].data.buffer = (char*)malloc(cfg->bufferSize);
            if ((*recordArray)[i].data.buffer == NULL) {
                fprintf(stderr, "Failed to allocate memory for buffer in record %zu\n", i);
                return -1;
            }
        } else {
            (*recordArray)[i].data.doubleValue = 0.0;
        }
    }

    return 0;
}

// Example usage
int main() {
    config cfg = {10, 5, 3, 0, 100, 42, 1024, 0};
    long* longArray;
    int* intArray;
    record* recordArray;

    if (initializeDataStructure(&cfg, &longArray, &intArray, &recordArray) == 0) {
        // Use the allocated arrays and records
        free(recordArray);
        for (size_t i = 0; i < cfg.recordArraySize; ++i) {
            if (cfg.bufferSize > 0) {
                free(recordArray[i].data.buffer);
            }
        }
        free(intArray);
        free(longArray);
    }

    return 0;
}
