#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    size_t size;
    void* data;
} record;

void initializeDataStructures(long** offsets, int** keys, record** records, int numRecords, int minRandomValue, int maxRandomValue) {
    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));
    *records = (record*)malloc(numRecords * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle allocation failure
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = i * sizeof(record);
        (*keys)[i] = rand() % (maxRandomValue - minRandomValue + 1) + minRandomValue;
        (*records)[i].value = (*keys)[i];
        (*records)[i].size = (*keys)[i] * sizeof(int); // Example size calculation
        (*records)[i].data = malloc((*records)[i].size);

        if ((*records)[i].data == NULL) {
            // Handle allocation failure for individual record data block
            return;
        }

        // Fill the data block with random data
        for (size_t j = 0; j < (*records)[i].size / sizeof(int); j++) {
            ((int*)((*records)[i].data))[j] = rand() % (maxRandomValue - minRandomValue + 1) + minRandomValue;
        }
    }
}

void freeDataStructures(long* offsets, int* keys, record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].data != NULL) {
            free(records[i].data);
        }
    }

    free(offsets);
    free(keys);
    free(records);
}

void resizeDataStructures(long** offsets, int** keys, record** records, int* currentSize, int newSize, int minRandomValue, int maxRandomValue) {
    if (newSize <= *currentSize) {
        return; // No need to resize
    }

    long* newOffsets = (long*)realloc(*offsets, newSize * sizeof(long));
    int* newKeys = (int*)realloc(*keys, newSize * sizeof(int));
    record* newRecords = (record*)realloc(*records, newSize * sizeof(record));

    if (newOffsets == NULL || newKeys == NULL || newRecords == NULL) {
        // Handle reallocation failure
        return;
    }

    *offsets = newOffsets;
    *keys = newKeys;
    *records = newRecords;

    for (int i = *currentSize; i < newSize; i++) {
        (*offsets)[i] = i * sizeof(record);
        (*keys)[i] = rand() % (maxRandomValue - minRandomValue + 1) + minRandomValue;
        (*records)[i].value = (*keys)[i];
        (*records)[i].size = (*keys)[i] * sizeof(int); // Example size calculation
        (*records)[i].data = malloc((*records)[i].size);

        if ((*records)[i].data == NULL) {
            // Handle allocation failure for individual record data block
            return;
        }

        // Fill the data block with random data
        for (size_t j = 0; j < (*records)[i].size / sizeof(int); j++) {
            ((int*)((*records)[i].data))[j] = rand() % (maxRandomValue - minRandomValue + 1) + minRandomValue;
        }
    }

    *currentSize = newSize;
}
