#include <vector>
#include <cstdlib>
#include <ctime>
#include <atomic>

struct Record {
    int value;
    size_t dataSize;
    time_t lastAccessed;
};

void processVectorAndInitializeData(std::vector<int>& vec, int findValue, int replaceValue, int appendValue,
                                   long* offsetArray, int* keyArray, Record** recordArray,
                                   size_t initialSize, int range, double resizeFactor) {
    // Find and replace or append value in vector
    auto it = std::find(vec.begin(), vec.end(), findValue);
    if (it != vec.end()) {
        *it = replaceValue;
    } else {
        vec.push_back(appendValue);
    }

    // Initialize arrays with dynamic memory allocation
    try {
        offsetArray = new long[initialSize];
        keyArray = new int[initialSize];
        recordArray = new Record*[initialSize];

        for (size_t i = 0; i < initialSize; ++i) {
            offsetArray[i] = static_cast<long>(rand()) % 1000;
            keyArray[i] = rand() % range;
            recordArray[i] = new Record{keyArray[i], static_cast<size_t>(rand()) % 1024, time(nullptr)};
        }
    } catch (const std::bad_alloc& e) {
        // Handle memory allocation failure
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        exit(EXIT_FAILURE);
    }

    // Dynamic resizing mechanism
    if (vec.size() > initialSize * resizeFactor) {
        size_t newSize = static_cast<size_t>(initialSize * resizeFactor);
        long* newOffsetArray = new long[newSize];
        int* newKeyArray = new int[newSize];
        Record** newRecordArray = new Record*[newSize];

        // Copy existing data to new arrays
        std::copy(offsetArray, offsetArray + initialSize, newOffsetArray);
        std::copy(keyArray, keyArray + initialSize, newKeyArray);
        for (size_t i = 0; i < initialSize; ++i) {
            newRecordArray[i] = recordArray[i];
        }

        // Delete old arrays
        delete[] offsetArray;
        delete[] keyArray;
        for (size_t i = 0; i < initialSize; ++i) {
            delete recordArray[i];
        }
        delete[] recordArray;

        // Update pointers and sizes
        offsetArray = newOffsetArray;
        keyArray = newKeyArray;
        recordArray = newRecordArray;
        initialSize = newSize;
    }

    // Thread safety (using atomic operations for shared data)
    std::atomic<int> counter(0);
    ++counter;

    // Free all allocated memory
    delete[] offsetArray;
    delete[] keyArray;
    for (size_t i = 0; i < initialSize; ++i) {
        delete recordArray[i];
    }
    delete[] recordArray;
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5};
    long* offsetArray = nullptr;
    int* keyArray = nullptr;
    Record** recordArray = nullptr;

    processVectorAndInitializeData(vec, 3, 10, 20, offsetArray, keyArray, recordArray, 10, 100, 1.5);

    return 0;
}
