#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    unsigned long id;
    int value;
    char data[256];
} Item;

typedef struct {
    Item* items;
    size_t count;
    size_t capacity;
    void* (*allocator)(size_t);
    void (*deallocator)(void*);
} DynamicList;

DynamicList* create_dynamic_list(void* (*allocator)(size_t), void (*deallocator)(void*)) {
    DynamicList* list = (DynamicList*)allocator(sizeof(DynamicList));
    if (!list) return NULL;

    list->items = (Item*)allocator(INITIAL_CAPACITY * sizeof(Item));
    if (!list->items) {
        deallocator(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = INITIAL_CAPACITY;
    list->allocator = allocator;
    list->deallocator = deallocator;

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        list->deallocator(list->items[i].data);
    }
    list->deallocator(list->items);
    list->deallocator(list);
}

int add_item(DynamicList* list, unsigned long id, int value, const char* data) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        Item* new_items = (Item*)list->allocator(new_capacity * sizeof(Item));
        if (!new_items) return -1;

        memcpy(new_items, list->items, list->count * sizeof(Item));
        for (size_t i = 0; i < list->count; ++i) {
            list->deallocator(list->items[i].data);
        }
        list->deallocator(list->items);
        list->items = new_items;
        list->capacity = new_capacity;
    }

    Item* item = &list->items[list->count++];
    item->id = id;
    item->value = value;
    size_t data_len = strlen(data) + 1;
    item->data = (char*)list->allocator(data_len);
    if (!item->data) return -1;
    memcpy(item->data, data, data_len);

    return 0;
}

Item* get_item_by_id(DynamicList* list, unsigned long id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i].id == id) {
            return &list->items[i];
        }
    }
    return NULL;
}
