#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    float data;
    int *keyArrayIndex;
    int refCount;
    pthread_mutex_t lock;
} Record;

typedef struct RecordManager {
    Record **records;
    int size;
    pthread_mutex_t recordsLock;
} RecordManager;

Record* create_record(int key, float data) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        return NULL;
    }
    record->key = key;
    record->data = data;
    record->refCount = 1;
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void destroy_record(Record *record) {
    if (record) {
        pthread_mutex_destroy(&record->lock);
        free(record);
    }
}

RecordManager* create_record_manager(int initial_size) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) {
        perror("Failed to allocate memory for record manager");
        return NULL;
    }
    manager->records = (Record**)calloc(initial_size, sizeof(Record*));
    if (!manager->records) {
        perror("Failed to allocate memory for records array");
        free(manager);
        return NULL;
    }
    manager->size = initial_size;
    pthread_mutex_init(&manager->recordsLock, NULL);
    return manager;
}

void destroy_record_manager(RecordManager *manager) {
    if (manager) {
        for (int i = 0; i < manager->size; ++i) {
            if (manager->records[i]) {
                destroy_record(manager->records[i]);
            }
        }
        free(manager->records);
        pthread_mutex_destroy(&manager->recordsLock);
        free(manager);
    }
}

void add_record(RecordManager *manager, Record *record) {
    pthread_mutex_lock(&manager->recordsLock);
    if (manager->size <= record->key) {
        manager->records = realloc(manager->records, (record->key + 1) * sizeof(Record*));
        if (!manager->records) {
            perror("Failed to reallocate memory for records array");
            pthread_mutex_unlock(&manager->recordsLock);
            return;
        }
        for (int i = manager->size; i <= record->key; ++i) {
            manager->records[i] = NULL;
        }
        manager->size = record->key + 1;
    }
    manager->records[record->key] = record;
    pthread_mutex_unlock(&manager->recordsLock);
}

Record* get_record(RecordManager *manager, int key) {
    Record *record = NULL;
    pthread_mutex_lock(&manager->recordsLock);
    if (key >= 0 && key < manager->size && manager->records[key]) {
        record = manager->records[key];
        pthread_mutex_lock(&record->lock);
        record->refCount++;
        pthread_mutex_unlock(&record->lock);
    }
    pthread_mutex_unlock(&manager->recordsLock);
    return record;
}

void release_record(Record *record) {
    if (record) {
        pthread_mutex_lock(&record->lock);
        record->refCount--;
        if (record->refCount == 0) {
            destroy_record(record);
        } else {
            pthread_mutex_unlock(&record->lock);
        }
    }
}
