item* create_items(size_t count, unsigned long* identifiers, double* values) {
    if (count == 0 || identifiers == NULL || values == NULL) return NULL;

    item* items = malloc(count * sizeof(item));
    if (items == NULL) return NULL;

    for (size_t i = 0; i < count; ++i) {
        items[i].value = (int)values[i];
        items[i].string = malloc(256);
        if (items[i].string == NULL) {
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) free(items[j].string);
            free(items);
            return NULL;
        }
        time_t current_time = time(NULL);
        generate_unique_string(items[i].string, 256, identifiers[i], current_time);
        items[i].timestamp = current_time;
    }

    return items;
}

void free_items(item* items, size_t count) {
    if (items == NULL) return;

    for (size_t i = 0; i < count; ++i) {
        free(items[i].string);
    }
    free(items);
}
