u_char* dns_resolve(const char *hostname) {
    struct addrinfo hints, *res, *p;
    u_char ip[INET6_ADDRSTRLEN];
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ip, sizeof ip);
        printf("  %s: %s\n", ipver, ip);

        freeaddrinfo(res); // all done with this structure
        return (u_char*)ip;
    }

    return NULL;
}

void* process_file(void *arg) {
    FileLine *file_line = (FileLine *)arg;
    FILE *fp = fopen(file_line->filename, "r");
    if (!fp) {
        perror("Error opening file");
        return NULL;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, fp)) != -1) {
        // Process each line here
        printf("%s", line);
    }

    free(line);
    fclose(fp);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    pthread_t threads[MAX_FILES];
    FileLine file_lines[MAX_FILES];

    for (int i = 1; i < argc; i++) {
        file_lines[i - 1].filename = argv[i];
        if (pthread_create(&threads[i - 1], NULL, process_file, &file_lines[i - 1]) != 0) {
            perror("Error creating thread");
            return 1;
        }
    }

    for (int i = 0; i < argc - 1; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
