#include <vector>
#include <iostream>

bool isPrime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) return false;
    }
    return true;
}

void replaceOrAppend(std::vector<int>& vec, int& insertVal, bool stressTest) {
    if (!stressTest) {
        for (auto& elem : vec) {
            if (isPrime(elem)) {
                elem = insertVal;
                return;
            }
        }
        vec.push_back(insertVal);
    } else {
        // Stress test implementation
        for (int i = 0; i < vec.size(); ++i) {
            if (isPrime(vec[i])) {
                vec[i] = insertVal;
                break;
            }
        }
        if (!isPrime(vec.back())) {
            vec.push_back(insertVal);
        }
    }
}

int main() {
    std::vector<int> numbers = {4, 6, 8, 10};
    int valueToInsert = 7;
    bool stressTestFlag = false;

    replaceOrAppend(numbers, valueToInsert, stressTestFlag);

    for (const auto& num : numbers) {
        std::cout << num << " ";
    }
    return 0;
}
