        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < keys_size; ++i) {
        keys[i] = i;
        records[i].key = rand() % (max_val - min_val + 1) + min_val;
        records[i].offset_ptr = &offsets[keys[i]];
    }

    free(offsets);
    free(keys);

    return records;
}

