#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int* key;
    long* offset;
} record;

int* allocate_long_array(size_t size) {
    return (int*)malloc(size * sizeof(int));
}

int* allocate_int_array(size_t size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocate_record_array(size_t size) {
    return (record*)malloc(size * sizeof(record));
}

void initialize_pipeline(size_t size, int min_priority, int max_priority, long* offsets, int* keys, record** records) {
    if (size == 0 || min_priority > max_priority) {
        fprintf(stderr, "Invalid input: size must be greater than 0 and min_priority <= max_priority\n");
        return;
    }

    *records = allocate_record_array(size);
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    srand(time(NULL));
    int* used_keys = allocate_int_array(size);
    if (used_keys == NULL) {
        fprintf(stderr, "Memory allocation failed for used keys\n");
        free(*records);
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        (*records)[i].key = &keys[i];
        (*records)[i].offset = &offsets[i];

        int priority;
        do {
            priority = rand() % (max_priority - min_priority + 1) + min_priority;
        } while (find(used_keys, i, priority) != -1);

        used_keys[i] = priority;
        (*records)[i].key = &keys[i];
    }

    free(used_keys);
}

void free_pipeline(size_t size, record* records) {
    for (size_t i = 0; i < size; ++i) {
        free(records[i].key);
        free(records[i].offset);
    }
    free(records);
}
