function renderFooter(scripts) {
    const loadedScripts = new Set();
    const dependencyMap = {};
    const errorLog = [];

    // Build dependency map
    scripts.forEach(script => {
        if (script.dependencies) {
            script.dependencies.forEach(dep => {
                if (!dependencyMap[dep]) dependencyMap[dep] = [];
                dependencyMap[dep].push(script);
            });
        }
    });

    function loadScript(script, retries = 0) {
        if (loadedScripts.has(script.id)) return;
        loadedScripts.add(script.id);

        const scriptTag = document.createElement('script');
        scriptTag.src = script.versions[script.version] || script.versions['default'];
        scriptTag.onload = () => {
            console.log(`Script ${script.id} loaded successfully.`);
            if (dependencyMap[script.id]) {
                dependencyMap[script.id].forEach(dep => loadScript(dep));
            }
        };
        scriptTag.onerror = () => {
            if (retries < 3) {
                setTimeout(() => loadScript(script, retries + 1), 1000);
            } else {
                errorLog.push(`Failed to load script ${script.id}`);
                console.error(`Failed to load script ${script.id}`);
            }
        };
        document.body.appendChild(scriptTag);
    }

    // Start loading scripts
    Object.values(dependencyMap).forEach(scripts => {
        scripts.forEach(script => loadScript(script));
    });

    return errorLog.join('<br>');
}
