long* offsets = NULL;
int* keys = NULL;
Record* records = NULL;
size_t num_offsets, num_keys, num_records;
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays() {
    num_offsets = 1024; // Initial guess
    num_keys = 1024;   // Initial guess
    num_records = 1024; // Initial guess

    while (num_offsets * sizeof(long) + num_keys * sizeof(int) > MAX_MEMORY_LIMIT) {
        num_offsets /= 2;
        num_keys /= 2;
        num_records /= 2;
    }

    offsets = allocate_memory(num_offsets * sizeof(long));
    keys = allocate_memory(num_keys * sizeof(int));
    records = allocate_memory(num_records * sizeof(Record));

    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = i;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = keys[i];
        records[i].offset_ptr = offsets + i;
    }
}

void* process_data(void* arg) {
    size_t thread_id = *(size_t*)arg;

    pthread_mutex_lock(&records_mutex);
    for (size_t i = thread_id; i < num_records; i += num_threads) {
        // Simulate data processing
        records[i].key *= 2;
    }
    pthread_mutex_unlock(&records_mutex);

    return NULL;
}

int main() {
    size_t num_threads = 4;

    initialize_arrays();

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, process_data, &i);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
