#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    int* offsets;
    int* keys;
    record** records;
    int size;
} array_manager;

typedef struct {
    int* parent;
    int* rank;
    int count;
} union_find;

array_manager* create_array_manager(int size) {
    array_manager* manager = (array_manager*)malloc(sizeof(array_manager));
    manager->offsets = (int*)malloc(size * sizeof(int));
    manager->keys = (int*)malloc(size * sizeof(int));
    manager->records = (record**)malloc(size * sizeof(record*));
    for (int i = 0; i < size; i++) {
        manager->records[i] = (record*)malloc(sizeof(record));
    }
    manager->size = size;
    return manager;
}

void free_array_manager(array_manager* manager) {
    for (int i = 0; i < manager->size; i++) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

union_find* create_union_find(int size) {
    union_find* uf = (union_find*)malloc(sizeof(union_find));
    uf->parent = (int*)malloc(size * sizeof(int));
    uf->rank = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
    uf->count = size;
    return uf;
}

void free_union_find(union_find* uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

int find(union_find* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_sets(union_find* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
        uf->count--;
    }
}

int initialize_records(array_manager* manager, int key_range) {
    srand(time(NULL));
    for (int i = 0; i < manager->size; i++) {
        manager->keys[i] = rand() % key_range;
        manager->records[i]->value = rand();
    }
    return 0;
}

int identify_disjoint_sets(array_manager* manager, union_find* uf) {
    for (int i = 0; i < manager->size - 1; i++) {
        for (int j = i + 1; j < manager->size; j++) {
            if (manager->keys[i] == manager->keys[j]) {
                union_sets(uf, i, j);
            }
        }
    }
    return uf->count;
}

int main() {
    int size = 1000;
    array_manager* manager = create_array_manager(size);
    union_find* uf = create_union_find(size);

    initialize_records(manager, 100);

    clock_t start = clock();
    int disjoint_sets = identify_disjoint_sets(manager, uf);
    clock_t end = clock();

    printf("Number of disjoint sets: %d\n", disjoint_sets);
    printf("Execution time: %f seconds\n", ((double)(end - start)) / CLOCKS_PER_SEC);

    free_array_manager(manager);
    free_union_find(uf);

    return 0;
}
