typedef struct {
    int value;
} Key;

Offset* manageDynamicMemory(int offsetCount, int keyRangeStart, int keyRangeEnd) {
    srand(time(NULL));
    Offset* offsets = (Offset*)malloc(offsetCount * sizeof(Offset));
    if (!offsets) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < offsetCount; ++i) {
        offsets[i].value = rand() % 1001; // Unique long value from 0 to 1000

        Key* key = (Key*)malloc(sizeof(Key));
        if (!key) {
            for (int j = 0; j < i; ++j) {
                free(offsets[j].key);
            }
            free(offsets);
            return NULL; // Memory allocation failed
        }

        offsets[i].key = key;
        offsets[i].key->value = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;

        if ((i + 1) * sizeof(Offset) + i * sizeof(Key) > MAX_SIZE) {
            for (int j = 0; j <= i; ++j) {
                free(offsets[j].key);
            }
            free(offsets);
            return NULL; // Exceeded memory limit
        }
    }

    return offsets;
}

void freeDynamicMemory(Offset* offsets, int offsetCount) {
    for (int i = 0; i < offsetCount; ++i) {
        free(offsets[i].key);
    }
    free(offsets);
}
