const zlib = require('zlib');
const { Transform } = require('stream');

class DataMerger {
  constructor(maxBufferSize = 1024 * 1024) {
    this.maxBufferSize = maxBufferSize;
    this.buffer = Buffer.alloc(0);
    this.streamCount = 0;
    this.totalSizeBeforeCompression = 0;
    this.totalSizeAfterCompression = 0;
    this.compressionRatio = 0;
    this.loggingEnabled = true;
  }

  enableLogging() {
    this.loggingEnabled = true;
  }

  disableLogging() {
    this.loggingEnabled = false;
  }

  async mergeStreams(streams) {
    for (const stream of streams) {
      await this.processStream(stream);
    }
    if (this.loggingEnabled) {
      this.logStatistics();
    }
    return this.buffer;
  }

  async processStream(stream) {
    return new Promise((resolve, reject) => {
      const dataChunks = [];
      let dataSize = 0;

      stream.on('data', chunk => {
        dataChunks.push(chunk);
        dataSize += chunk.length;
      });

      stream.on('end', () => {
        this.totalSizeBeforeCompression += dataSize;
        const mergedData = Buffer.concat(dataChunks);
        this.buffer = Buffer.concat([this.buffer, mergedData]);
        if (this.buffer.length > this.maxBufferSize) {
          this.handleBufferOverflow(mergedData);
        }
        resolve();
      });

      stream.on('error', reject);
    });
  }

  handleBufferOverflow(newData) {
    const excessData = newData.slice(this.maxBufferSize - this.buffer.length);
    this.buffer = Buffer.concat([this.buffer, excessData]);
    if (this.loggingEnabled) {
      console.warn('Buffer overflow detected. Excess data discarded.');
    }
  }

  logStatistics() {
    this.totalSizeAfterCompression = this.buffer.length;
    this.compressionRatio = (1 - this.totalSizeAfterCompression / this.totalSizeBeforeCompression).toFixed(2);
    console.log(`Streams processed: ${this.streamCount}`);
    console.log(`Total data size before compression: ${this.totalSizeBeforeCompression} bytes`);
    console.log(`Total data size after compression: ${this.totalSizeAfterCompression} bytes`);
    console.log(`Compression ratio achieved: ${this.compressionRatio * 100}%`);
  }
}

module.exports = DataMerger;
