#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct {
    int value;
    time_t timestamp;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record records[MAX_RECORDS];
} DataStructures;

typedef struct {
    int parent[MAX_RECORDS];
    int rank[MAX_RECORDS];
} UnionFind;

void init_data_structures(DataStructures *ds, int num_records) {
    ds->offsets = (long *)malloc(num_records * sizeof(long));
    ds->keys = (int *)malloc(num_records * sizeof(int));
    for (int i = 0; i < num_records; ++i) {
        ds->records[i].value = rand();
        ds->records[i].timestamp = time(NULL);
    }
}

void init_union_find(UnionFind *uf, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void union_sets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int check_disjointness(UnionFind *uf, int x, int y) {
    return find(uf, x) != find(uf, y);
}

void free_data_structures(DataStructures *ds) {
    free(ds->offsets);
    free(ds->keys);
}

void *disjointness_check_thread(void *arg) {
    DataStructures *ds = (DataStructures *)arg;
    UnionFind uf;
    init_union_find(&uf, MAX_RECORDS);

    clock_t start_time = clock();
    int disjoint_pairs = 0;

    for (int i = 0; i < MAX_RECORDS - 1; ++i) {
        for (int j = i + 1; j < MAX_RECORDS; ++j) {
            if (check_disjointness(&uf, ds->records[i].value, ds->records[j].value)) {
                union_sets(&uf, ds->records[i].value, ds->records[j].value);
                disjoint_pairs++;
            }
        }
    }

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Disjoint pairs: %d\n", disjoint_pairs);
    printf("Average time per check: %.2f ms\n", (time_taken * 1000) / (MAX_RECORDS * (MAX_RECORDS - 1) / 2));

    free_data_structures(ds);
    pthread_exit(NULL);
}

int main() {
    DataStructures ds;
    init_data_structures(&ds, MAX_RECORDS);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, disjointness_check_thread, &ds) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread_id, NULL);
    return 0;
}
