int record::totalCount = 0;

record* createRecord(int value, size_t size, const char* metadata) {
    record* newRecord = (record*)malloc(sizeof(record));
    newRecord->value = value;
    newRecord->size = size;
    strncpy(newRecord->metadata, metadata, sizeof(newRecord->metadata) - 1);
    newRecord->metadata[sizeof(newRecord->metadata) - 1] = '\0';
    newRecord->logAccessTime = NULL; // Placeholder for actual logging function
    pthread_mutex_init(&newRecord->refCountMutex, NULL);
    newRecord->refCount = (int*)malloc(sizeof(int));
    *newRecord->refCount = 1;
    pthread_mutex_init(&newRecord->totalCountMutex, NULL);
    pthread_mutex_lock(&record::totalCountMutex);
    record::totalCount++;
    pthread_mutex_unlock(&record::totalCountMutex);
    return newRecord;
}

void destroyRecord(record* rec) {
    if (rec == NULL) return;
    pthread_mutex_lock(&rec->refCountMutex);
    (*rec->refCount)++;
    pthread_mutex_unlock(&rec->refCountMutex);
    if (*rec->refCount > 1) return;
    free(rec->refCount);
    pthread_mutex_destroy(&rec->refCountMutex);
    pthread_mutex_lock(&record::totalCountMutex);
    record::totalCount--;
    pthread_mutex_unlock(&record::totalCountMutex);
    free(rec);
}

void manageDynamicDataComponents(int offsetCount, int keyCount, int recordCount) {
    offset* offsets = (offset*)malloc(offsetCount * sizeof(offset));
    key* keys = (key*)malloc(keyCount * sizeof(key));
    record** records = (record**)malloc(recordCount * sizeof(record*));

    for (int i = 0; i < recordCount; i++) {
        records[i] = createRecord(i, i * 1024, "Sample metadata");
    }

    // Simulate processing
    for (int i = 0; i < recordCount; i++) {
        destroyRecord(records[i]);
    }

    free(offsets);
    free(keys);
    free(records);
}
