    RetryMechanism retry;
    LoadBalancer lb({"server1", "server2", "server3"});
    HealthCheck healthCheck;
    MockInterfaceTable interfaceTable;
    Cache cache;
    Authentication auth;

    std::vector<std::thread> threads;
    for (int i = 0; i < 5000; ++i) {
        threads.emplace_back([&pool, &retry, &lb, &healthCheck, &interfaceTable, &cache, &auth]() {
            while (true) {
                std::string server = lb.getNextServer();
                HttpClient client = pool.getConnection();
                if (!auth.validateRequest("request")) continue;
                retry.retryRequest([&client, &server]() {
