    int* keyArray;
    record** recordArray;
    size_t arraySize;
} DataStructureConfig;

DataStructureConfig* initializeDataStructure(size_t arraySize, int keyRangeStart, int keyRangeEnd, size_t bufferSize) {
    if (arraySize == 0 || keyRangeStart > keyRangeEnd || bufferSize == 0) {
        return NULL; // Handle invalid input
    }

    DataStructureConfig* config = (DataStructureConfig*)malloc(sizeof(DataStructureConfig));
    if (!config) {
        return NULL; // Memory allocation failed
    }

    config->offsetArray = (long*)calloc(arraySize, sizeof(long));
    config->keyArray = (int*)calloc(arraySize, sizeof(int));
    config->recordArray = (record**)calloc(arraySize, sizeof(record*));

    if (!config->offsetArray || !config->keyArray || !config->recordArray) {
        free(config->offsetArray);
        free(config->keyArray);
        free(config->recordArray);
        free(config);
        return NULL; // Memory allocation failed
    }

    for (size_t i = 0; i < arraySize; ++i) {
        config->recordArray[i] = (record*)malloc(sizeof(record));
        if (!config->recordArray[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(config->recordArray[j]);
            }
            free(config->offsetArray);
            free(config->keyArray);
            free(config->recordArray);
            free(config);
            return NULL; // Memory allocation failed
        }

        config->offsetArray[i] = (long)i * 100; // Example initialization
        config->keyArray[i] = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        config->recordArray[i]->value = config->keyArray[i];
        config->recordArray[i]->bufferSize = bufferSize;
        config->recordArray[i]->data.buffer = (char*)malloc(bufferSize);
        if (!config->recordArray[i]->data.buffer) {
            for (size_t j = 0; j <= i; ++j) {
                free(config->recordArray[j]);
            }
            free(config->offsetArray);
            free(config->keyArray);
            free(config->recordArray);
            free(config);
            return NULL; // Memory allocation failed
        }

        // Initialize buffer with example data
        for (size_t j = 0; j < bufferSize; ++j) {
            config->recordArray[i]->data.buffer[j] = 'A' + (j % 26);
        }
    }

    config->arraySize = arraySize;
    return config;
}

void freeDataStructure(DataStructureConfig* config) {
    if (!config) {
        return;
    }

    for (size_t i = 0; i < config->arraySize; ++i) {
        free(config->recordArray[i]->data.buffer);
        free(config->recordArray[i]);
    }
    free(config->offsetArray);
    free(config->keyArray);
    free(config->recordArray);
    free(config);
}
