#include <stdlib.h>
#include <stdio.h>

#define MAX_FRAMES 1000
#define MAX_STATS_PER_FRAME 10

typedef struct {
    int frequency;
    int bandwidth;
} DL_FRAME_METADATA;

typedef struct {
    int rssi;
    int snr;
} PHY_LAYER_STATS;

typedef struct FrameNode {
    DL_FRAME_METADATA metadata;
    PHY_LAYER_STATS stats[MAX_STATS_PER_FRAME];
    struct FrameNode* next;
} FrameNode;

typedef struct {
    FrameNode* head;
    FrameNode* freeList;
    size_t totalMemory;
    size_t usedMemory;
} LTEFrameManager;

LTEFrameManager* createLTEFrameManager() {
    LTEFrameManager* manager = (LTEFrameManager*)malloc(sizeof(LTEFrameManager));
    if (!manager) return NULL;
    manager->head = NULL;
    manager->freeList = NULL;
    manager->totalMemory = 0;
    manager->usedMemory = 0;
    return manager;
}

void destroyLTEFrameManager(LTEFrameManager* manager) {
    FrameNode* current = manager->head;
    while (current) {
        FrameNode* next = current->next;
        free(current);
        current = next;
    }
    free(manager);
}

int addLTEFrame(LTEFrameManager* manager, DL_FRAME_METADATA metadata, PHY_LAYER_STATS* stats, int numStats) {
    if (numStats > MAX_STATS_PER_FRAME || numStats <= 0) return -1;

    FrameNode* newNode = NULL;
    if (manager->freeList) {
        newNode = manager->freeList;
        manager->freeList = newNode->next;
    } else {
        newNode = (FrameNode*)malloc(sizeof(FrameNode));
        if (!newNode) return -2;
        manager->totalMemory += sizeof(FrameNode);
    }

    newNode->metadata = metadata;
    for (int i = 0; i < numStats; i++) {
        newNode->stats[i] = stats[i];
    }
    newNode->next = NULL;

    if (!manager->head) {
        manager->head = newNode;
    } else {
        FrameNode* current = manager->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }

    manager->usedMemory += sizeof(FrameNode);
    return 0;
}

int removeLTEFrame(LTEFrameManager* manager, int frameIndex) {
    FrameNode* current = manager->head;
    FrameNode* prev = NULL;

    for (int i = 0; i < frameIndex && current; i++) {
        prev = current;
        current = current->next;
    }

    if (!current) return -1;

    if (prev) {
        prev->next = current->next;
    } else {
        manager->head = current->next;
    }

    if (manager->freeList) {
        current->next = manager->freeList;
        manager->freeList = current;
    } else {
        free(current);
        manager->totalMemory -= sizeof(FrameNode);
    }

    manager->usedMemory -= sizeof(FrameNode);
    return 0;
}

void garbageCollect(LTEFrameManager* manager) {
    FrameNode* current = manager->head;
    FrameNode* prev = NULL;

    while (current) {
        if (!current->next) {
            break;
        }
        FrameNode* next = current->next;
        if (next->next == NULL) {
            if (prev) {
                prev->next = next;
            } else {
                manager->head = next;
            }
            free(current);
            manager->totalMemory -= sizeof(FrameNode);
            current = next;
        } else {
            prev = current;
            current = next;
        }
    }

    FrameNode* freeCurrent = manager->freeList;
    while (freeCurrent) {
        FrameNode* freeNext = freeCurrent->next;
        if (!freeNext || freeNext->next == NULL) {
            break;
        }
        FrameNode* freeNextNext = freeNext->next;
        if (!freeNextNext || freeNextNext->next == NULL) {
            free(freeNext);
            manager->totalMemory -= sizeof(FrameNode);
            freeCurrent->next = freeNextNext;
        } else {
            freeCurrent = freeNext;
        }
    }
}
