#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_PAYLOAD_SIZE 1024

typedef enum {
    DEVICE_STATUS_OK,
    DEVICE_STATUS_WARNING,
    DEVICE_STATUS_ERROR
} DeviceStatus;

typedef struct {
    int sequence_number;
    char buffer[MAX_PAYLOAD_SIZE];
} MessagePayload;

typedef struct {
    long timestamp;
    float sensor_reading;
    DeviceStatus status;
    MessagePayload payload;
    char device_id[10];
} MessageRecord;

MessageRecord* create_message_records(int num_records) {
    return (MessageRecord*)malloc(num_records * sizeof(MessageRecord));
}

void initialize_message_records(MessageRecord* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        records[i].timestamp = time(NULL);
        records[i].sensor_reading = (float)(rand() % 100) / 10.0;
        records[i].status = DEVICE_STATUS_OK;
        snprintf(records[i].payload.buffer, MAX_PAYLOAD_SIZE, "Record %d", i);
        records[i].payload.sequence_number = i;
        snprintf(records[i].device_id, 10, "Device%d", i);
    }
}

void update_timestamps(MessageRecord* records, int num_records, time_t threshold) {
    for (int i = 0; i < num_records; i++) {
        if ((time(NULL) - records[i].timestamp) > threshold) {
            records[i].timestamp = time(NULL);
        }
    }
}

void send_to_analytics_service(MessageRecord* records, int num_records) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        for (int i = 0; i < num_records; i++) {
            char post_data[1024];
            snprintf(post_data, sizeof(post_data), "{\"timestamp\": %ld, \"sensor_reading\": %.2f, \"status\": \"%s\", \"payload\": {\"sequence_number\": %d, \"buffer\": \"%s\"}, \"device_id\": \"%s\"}",
                     records[i].timestamp, records[i].sensor_reading,
                     (records[i].status == DEVICE_STATUS_OK) ? "OK" :
                     (records[i].status == DEVICE_STATUS_WARNING) ? "WARNING" : "ERROR",
                     records[i].payload.sequence_number, records[i].payload.buffer, records[i].device_id);

            curl_easy_setopt(curl, CURLOPT_URL, "http://analytics-service.com/api/record");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            }
        }
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

void* message_processing_thread(void* arg) {
    int num_records = *(int*)arg;
    MessageRecord* records = create_message_records(num_records);
    initialize_message_records(records, num_records);

    while (1) {
        update_timestamps(records, num_records, 3600); // Update every hour
        send_to_analytics_service(records, num_records);
        sleep(60); // Check every minute
    }

    free(records);
    return NULL;
}

int main() {
    int num_threads = 4;
    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_args[i] = 1000; // Number of records per thread
        pthread_create(&threads[i], NULL, message_processing_thread, &thread_args[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
