#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_RECORDS 1000
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 100

typedef struct record {
    int value;
    size_t size;
    u_char *offset;
} Record;

typedef struct node {
    Record data;
    struct node *next;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_record(Node** head, Record data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int find_largest_value(Node* head) {
    int max_value = MIN_RANDOM_VALUE - 1;
    Node* temp = head;
    while (temp != NULL) {
        if (temp->data.value > max_value) {
            max_value = temp->data.value;
        }
        temp = temp->next;
    }
    return max_value;
}

void free_memory(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int process_and_manage_dns(char* hostname, int min_value, int max_value) {
    Record records[MAX_RECORDS];
    Node* head = NULL;

    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].size = sizeof(int);
        records[i].offset = (u_char*)malloc(records[i].size);
        if (records[i].offset == NULL) {
            perror("Failed to allocate memory for record data");
            free_memory(&head);
            return EXIT_FAILURE;
        }
        memcpy(records[i].offset, &records[i].value, records[i].size);
        insert_record(&head, records[i]);
    }

    int largest_value = find_largest_value(head);
    printf("Largest value: %d\n", largest_value);

    free_memory(&head);

    return EXIT_SUCCESS;
}
