class DynamicFrameAndSessionManager {
public:
    DynamicFrameAndSessionManager(size_t initialFrameSize, size_t initialSessionSize, int defaultTimeout, int updateInterval)
        : frameList(initialFrameSize), sessionList(initialSessionSize), defaultTimeout(defaultTimeout), updateInterval(updateInterval) {}

    void addFrame(const LTE_DL_FRAME& frame) {
        std::lock_guard<std::mutex> lock(mutex);
        if (frameList.size() == frameList.capacity()) resizeFrames();
        frameList.push_back(frame);
    }

    void addUserSession(int id, int lastAccessTime, int requestCount, int sessionTimeout) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessionList.size() == sessionList.capacity()) resizeSessions();
        sessionList.push_back({id, lastAccessTime, requestCount, sessionTimeout});
    }

    // Add other methods as per the requirements

private:
    std::vector<LTE_DL_FRAME> frameList;
    std::vector<UserSession> sessionList;
    int defaultTimeout;
    int updateInterval;
    std::mutex mutex;

    void resizeFrames() {
        size_t newSize = frameList.capacity() * 2;
        std::vector<LTE_DL_FRAME> newFrameList(newSize);
        std::copy(frameList.begin(), frameList.end(), newFrameList.begin());
        frameList.swap(newFrameList);
    }

    void resizeSessions() {
        size_t newSize = sessionList.capacity() * 2;
        std::vector<UserSession> newSessionList(newSize);
        std::copy(sessionList.begin(), sessionList.end(), newSessionList.begin());
        sessionList.swap(newSessionList);
    }
};

struct UserSession {
    int id;
    int lastAccessTime;
    int requestCount;
    int sessionTimeout;
};
