#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Record**)calloc(TABLE_SIZE, sizeof(Record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insertRecord(HashTable *table, int key, int value) {
    pthread_mutex_lock(&table->lock);
    Record *newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->value = value;
    newRecord->next = NULL;

    int index = key % TABLE_SIZE;
    if (table->buckets[index] == NULL) {
        table->buckets[index] = newRecord;
    } else {
        Record *current = table->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }
    pthread_mutex_unlock(&table->lock);
}

int lookupRecord(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    int index = key % TABLE_SIZE;
    Record *current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&table->lock);
            return current->value;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}

void deleteRecord(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    int index = key % TABLE_SIZE;
    Record *current = table->buckets[index];
    Record *prev = NULL;

    while (current != NULL) {
        if (current->key == key) {
            if (prev == NULL) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void garbageCollect(HashTable *table, time_t lastAccessTime) {
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            if (difftime(time(NULL), current->lastAccessed) > lastAccessTime) {
                Record *temp = current;
                current = current->next;
                free(temp);
            } else {
                current = current->next;
            }
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void destroyHashTable(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}
