#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_LIST_SIZE 1024
#define CACHE_SIZE 128

typedef struct {
    int *list;
    size_t list_size;
    size_t list_capacity;
} IntegerList;

typedef struct {
    int key;
    int frequency;
    pthread_mutex_t lock;
} CacheEntry;

typedef struct {
    CacheEntry entries[CACHE_SIZE];
    pthread_mutex_t cache_lock;
} Cache;

typedef struct {
    FILE *log_file;
} AccessLog;

void initialize_list(IntegerList *list) {
    list->list = (int *)malloc(INITIAL_LIST_SIZE * sizeof(int));
    if (!list->list) {
        fprintf(stderr, "Memory allocation failed for integer list\n");
        exit(EXIT_FAILURE);
    }
    list->list_size = 0;
    list->list_capacity = INITIAL_LIST_SIZE;
}

void initialize_cache(Cache *cache) {
    pthread_mutex_init(&cache->cache_lock, NULL);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache->entries[i].key = -1;
        cache->entries[i].frequency = 0;
        pthread_mutex_init(&cache->entries[i].lock, NULL);
    }
}

void initialize_log(AccessLog *log) {
    log->log_file = fopen("access.log", "w");
    if (!log->log_file) {
        fprintf(stderr, "Failed to open access log file\n");
        exit(EXIT_FAILURE);
    }
}

void resize_list(IntegerList *list) {
    list->list_capacity *= 2;
    int *new_list = (int *)realloc(list->list, list->list_capacity * sizeof(int));
    if (!new_list) {
        fprintf(stderr, "Memory reallocation failed for integer list\n");
        exit(EXIT_FAILURE);
    }
    list->list = new_list;
}

void add_to_cache(Cache *cache, int key) {
    pthread_mutex_lock(&cache->cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->entries[i].key == key) {
            pthread_mutex_lock(&cache->entries[i].lock);
            cache->entries[i].frequency++;
            pthread_mutex_unlock(&cache->entries[i].lock);
            pthread_mutex_unlock(&cache->cache_lock);
            return;
        }
    }
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->entries[i].key == -1) {
            cache->entries[i].key = key;
            cache->entries[i].frequency = 1;
            pthread_mutex_unlock(&cache->cache_lock);
            return;
        }
    }
    // Evict least recently used item
    int lru_index = 0;
    for (int i = 1; i < CACHE_SIZE; ++i) {
        if (cache->entries[i].frequency < cache->entries[lru_index].frequency) {
            lru_index = i;
        }
    }
    pthread_mutex_lock(&cache->entries[lru_index].lock);
    cache->entries[lru_index].key = key;
    cache->entries[lru_index].frequency = 1;
    pthread_mutex_unlock(&cache->entries[lru_index].lock);
    pthread_mutex_unlock(&cache->cache_lock);
}

void log_access(AccessLog *log, int value) {
    fprintf(log->log_file, "%d\n", value);
}

int find_largest(IntegerList *list) {
    if (list->list_size == 0) return -1;
    int largest = list->list[0];
    for (size_t i = 1; i < list->list_size; ++i) {
        if (list->list[i] > largest) {
            largest = list->list[i];
        }
    }
    return largest;
}

void print_frequency_report(IntegerList *list, Cache *cache) {
    pthread_mutex_lock(&cache->cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache->entries[i].key != -1) {
            printf("(%d, %d)\n", cache->entries[i].key, cache->entries[i].frequency);
        }
    }
    pthread_mutex_unlock(&cache->cache_lock);
}

void free_resources(IntegerList *list, Cache *cache, AccessLog *log) {
    free(list->list);
    fclose(log->log_file);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        pthread_mutex_destroy(&cache->entries[i].lock);
    }
    pthread_mutex_destroy(&cache->cache_lock);
}

void process_and_analyze_stream() {
    IntegerList list;
    Cache cache;
    AccessLog log;

    initialize_list(&list);
    initialize_cache(&cache);
    initialize_log(&log);

    int value;
    while (scanf("%d", &value) != EOF) {
        if (list.list_size >= list.list_capacity) {
            resize_list(&list);
        }
        list.list[list.list_size++] = value;
        add_to_cache(&cache, value);
        log_access(&log, value);
    }

    int largest = find_largest(&list);
    printf("Largest integer: %d\n", largest);

    print_frequency_report(&list, &cache);

    free_resources(&list, &cache, &log);
}
