#include <forward_list>
#include <string>
#include <mutex>
#include <memory>
#include <atomic>

class ForwardListManager {
public:
    void insert_after_forward_list(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == target) {
                list.insert_after(it, insertion);
                return;
            }
            ++it;
        }
        list.push_back(insertion);
    }

private:
    std::mutex mutex_;
};

// Example usage
int main() {
    ForwardListManager manager;
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    manager.insert_after_forward_list(myList, "banana", "grape");
    // myList now contains: apple, banana, grape, cherry
    return 0;
}
```

