#define MAX_RECORDS 1000
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    long offset;
    int key;
    char* identifier;
    struct record {
        int value;
        char* external_id;
        void* external_resource;
    } data;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    size_t count;
    size_t memory_usage;
    pthread_mutex_t lock;
} RecordManager;

void init_record_manager(RecordManager* manager) {
    memset(manager, 0, sizeof(*manager));
    pthread_mutex_init(&manager->lock, NULL);
}

int allocate_record(RecordManager* manager, long offset, int key, const char* identifier, int value, const char* external_id, void* external_resource) {
    pthread_mutex_lock(&manager->lock);
    if (manager->memory_usage + sizeof(Record) > MEMORY_LIMIT) {
        printf("Warning: Memory limit exceeded. Allocation paused.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    Record* record = &manager->records[manager->count++];
    record->offset = offset;
    record->key = key;
    record->identifier = strdup(identifier);
    record->data.value = value;
    record->data.external_id = strdup(external_id);
    record->data.external_resource = external_resource;

    manager->memory_usage += sizeof(Record) + strlen(identifier) + strlen(external_id);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_record_manager(RecordManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        Record* record = &manager->records[i];
        free(record->identifier);
        free(record->data.external_id);
    }
    pthread_mutex_destroy(&manager->lock);
}

int main() {
    RecordManager manager;
    init_record_manager(&manager);

    // Example usage
    void* external_resource = NULL; // Placeholder for actual resource
    allocate_record(&manager, 100, 42, "example", 99, "ext_id", external_resource);

    free_record_manager(&manager);
    return 0;
}
