#define MAX_ELEMENTS 10

typedef struct {
    int index;
    bool flag;
} element;

typedef struct {
    element* elements[MAX_ELEMENTS];
    int count;
} container;

container* create_container() {
    container* c = (container*)malloc(sizeof(container));
    if (c == NULL) {
        // Log error
        return NULL;
    }
    c->count = 0;
    return c;
}

void destroy_container(container* c) {
    for (int i = 0; i < c->count; i++) {
        free(c->elements[i]);
    }
    free(c);
}

element* create_element(int index, bool flag) {
    element* e = (element*)malloc(sizeof(element));
    if (e == NULL) {
        // Log error
        return NULL;
    }
    e->index = index;
    e->flag = flag;
    return e;
}

void destroy_element(element* e) {
    free(e);
}

bool add_element(container* c, element* e) {
    if (c->count >= MAX_ELEMENTS) {
        // Log error
        return false;
    }
    c->elements[c->count++] = e;
    return true;
}

element* get_element(container* c, int index) {
    for (int i = 0; i < c->count; i++) {
        if (c->elements[i]->index == index) {
            return c->elements[i];
        }
    }
    // Log error
    return NULL;
}

void remove_element(container* c, int index) {
    for (int i = 0; i < c->count; i++) {
        if (c->elements[i]->index == index) {
            destroy_element(c->elements[i]);
            for (int j = i; j < c->count - 1; j++) {
                c->elements[j] = c->elements[j + 1];
            }
            c->count--;
            break;
        }
    }
}

void serialize_container(container* c, FILE* file) {
    fwrite(&c->count, sizeof(int), 1, file);
    for (int i = 0; i < c->count; i++) {
        fwrite(c->elements[i], sizeof(element), 1, file);
    }
}

container* deserialize_container(FILE* file) {
    container* c = create_container();
    int count;
    fread(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        element* e = (element*)malloc(sizeof(element));
        fread(e, sizeof(element), 1, file);
        add_element(c, e);
    }
    return c;
}

void populate_container(container* c) {
    srand(time(NULL));
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        element* e = create_element(i, rand() % 2 == 0);
        if (e != NULL && !add_element(c, e)) {
            destroy_element(e);
        }
    }
}

void print_container(container* c) {
    for (int i = 0; i < c->count; i++) {
        printf("Element %d: Index=%d, Flag=%s\n", i, c->elements[i]->index, c->elements[i]->flag ? "true" : "false");
    }
}
