#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

// Define a structure to hold encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} EncryptionContext;

// Function to initialize the encryption context
int init_encryption_context(EncryptionContext *ctx, const unsigned char *key, const unsigned char *iv) {
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) return -1;
    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        return -1;
    }
    memcpy(ctx->key, key, 32);
    memcpy(ctx->iv, iv, 16);
    return 0;
}

// Function to encrypt data
int encrypt_data(EncryptionContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    if (1 != EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;
    int ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) return -1;
    ciphertext_len += len;
    return ciphertext_len;
}

// Function to free the encryption context
void free_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    memset(ctx, 0, sizeof(*ctx));
}

// Thread-safe function to generate a secure random IV
int generate_secure_iv(unsigned char *iv, size_t iv_len) {
    return RAND_bytes(iv, iv_len) == 1;
}

// Function to encrypt a file
int encrypt_file(const char *input_filename, const char *output_filename, const unsigned char *key, const unsigned char *iv) {
    FILE *in = fopen(input_filename, "rb");
    if (!in) return -1;
    FILE *out = fopen(output_filename, "wb");
    if (!out) {
        fclose(in);
        return -1;
    }

    EncryptionContext ctx;
    if (init_encryption_context(&ctx, key, iv) != 0) {
        fclose(in);
        fclose(out);
        return -1;
    }

    unsigned char buffer[4096];
    int bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        int ciphertext_len = encrypt_data(&ctx, buffer, bytes_read, buffer);
        if (ciphertext_len < 0) {
            free_encryption_context(&ctx);
            fclose(in);
            fclose(out);
            return -1;
        }
        fwrite(buffer, 1, ciphertext_len, out);
    }

    free_encryption_context(&ctx);
    fclose(in);
    fclose(out);
    return 0;
}

// Example usage
int main() {
    unsigned char key[32];
    unsigned char iv[16];

    // Generate a secure random key and IV
    if (!RAND_bytes(key, sizeof(key)) || !generate_secure_iv(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate key or IV\n");
        return 1;
    }

    // Encrypt a file
    if (encrypt_file("input.txt", "output.enc", key, iv) != 0) {
        fprintf(stderr, "Failed to encrypt file\n");
        return 1;
    }

    printf("File encrypted successfully\n");
    return 0;
}
```

