#include <stdlib.h>
#include <string.h>

typedef struct processing_unit {
    size_t length;
    void* data;
    void (*process)(void*);
} processing_unit;

typedef struct workload {
    char name[256];
    int priority;
    processing_unit* unit;
    struct workload* next;
} workload;

workload* create_workload(const char* name, int priority, processing_unit* unit) {
    workload* new_workload = (workload*)malloc(sizeof(workload));
    if (new_workload == NULL) return NULL;

    strncpy(new_workload->name, name, sizeof(new_workload->name) - 1);
    new_workload->priority = priority;
    new_workload->unit = unit;
    new_workload->next = NULL;

    return new_workload;
}

void free_workload(workload* workload) {
    if (workload == NULL) return;

    free(workload->unit->data);
    free(workload->unit);
    free(workload);
}

void update_priority(workload* workload, int priority) {
    if (workload != NULL && priority >= 0) {
        workload->priority = priority;
    }
}

void process_workload(workload* workload) {
    if (workload != NULL && workload->unit != NULL && workload->unit->process != NULL) {
        workload->unit->process(workload->unit->data);
    }
}

void iterate_workloads(workload* head, void (*callback)(workload*)) {
    for (workload* current = head; current != NULL; current = current->next) {
        callback(current);
    }
}

void free_all_workloads(workload** head) {
    workload* current = *head;
    while (current != NULL) {
        workload* next = current->next;
        free_workload(current);
        current = next;
    }
    *head = NULL;
}
