    int active;
} Component;

Component* registry = NULL;
size_t registry_size = 0;
pthread_mutex_t registry_lock = PTHREAD_MUTEX_INITIALIZER;

void save_registry() {
    // Implement a method to persist component details in an efficient and scalable manner
}

void load_registry() {
    // Load the registry from a persistent storage
}

void update_component(long id, char* name, char* description, size_t version) {
    pthread_mutex_lock(&registry_lock);
    for (size_t i = 0; i < registry_size; ++i) {
        if (registry[i].id == id) {
            free(registry[i].description);
            strcpy(registry[i].name, name);
            registry[i].description = strdup(description);
            registry[i].version = version;
            registry[i].last_modified = time(NULL);
            pthread_mutex_unlock(&registry_lock);
            save_registry();
            return;
        }
    }
    Component new_component = {id, name, strdup(description), time(NULL), version, 1};
    registry = realloc(registry, (registry_size + 1) * sizeof(Component));
    if (!registry) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&registry_lock);
        return;
    }
    registry[registry_size++] = new_component;
    pthread_mutex_unlock(&registry_lock);
    save_registry();
}

void deactivate_component(long id) {
    pthread_mutex_lock(&registry_lock);
    for (size_t i = 0; i < registry_size; ++i) {
        if (registry[i].id == id) {
            registry[i].active = 0;
            pthread_mutex_unlock(&registry_lock);
            save_registry();
            return;
        }
    }
    pthread_mutex_unlock(&registry_lock);
}

char* process_action(long id, char* name, char* description, size_t version, char* sub_action) {
    if (sub_action && strcmp(sub_action, "deactivate") == 0) {
        deactivate_component(id);
        return "{\"message\": \"success\"}";
    } else {
        update_component(id, name, description, version);
        return "{\"message\": \"success\"}";
    }
}

int main() {
    load_registry();
    // Example usage
    printf("%s\n", process_action(1, "ComponentA", "Description of Component A", 1, NULL));
    printf("%s\n", process_action(2, "ComponentB", "Description of Component B", 2, "deactivate"));
    return 0;
}
