        records[i].key = rand() % (max_key - min_key + 1) + min_key;

        records[i].data = malloc(data_size);
        if (!records[i].data) {
            perror("Failed to allocate memory for record data");
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j].data);
            }
            free(records);
            return NULL;
        }

        // Initialize data with random values or a specific pattern
        for (size_t j = 0; j < data_size; ++j) {
            records[i].data[j] = rand() % 256;
        }
    }

    return records;
}

