long* generate_random_number(long min, long max) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    srand(time(NULL));
    long random_number = (rand() % (max - min + 1)) + min;
    pthread_mutex_unlock(&mutex);
    return &random_number;
}

void manage_and_process_records(int num_records, int min_value, int max_value) {
    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records = malloc(num_records * sizeof(record));
    int *sorted_order = malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = *generate_random_number(0, 1000);
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = keys[i];
        records[i].size = sizeof(int);
        records[i].offset = &offsets[i];
    }

    // Sort records based on integer values
    for (int i = 0; i < num_records; i++) {
        sorted_order[i] = i;
    }
    qsort(sorted_order, num_records, sizeof(int), compare_records);

    // Process data using external service
    process_data_with_service(records, sorted_order, num_records);

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; i++) {
        free(records[i].offset);
    }
    free(records);
    free(sorted_order);
}

int compare_records(const void *a, const void *b) {
    int index_a = *(int *)a;
    int index_b = *(int *)b;
    return records[index_b].value - records[index_a].value; // Descending order
