function manageUserAccount($_REQUEST) {
    // Initialize variables
    $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
    $name = isset($_REQUEST['name']) ? $_REQUEST['name'] : '';
    $email = isset($_REQUEST['email']) ? $_REQUEST['email'] : '';
    $password = isset($_REQUEST['password']) ? $_REQUEST['password'] : '';
    $sub_action = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : '';

    // Validate input
    if (empty($name) || empty($email)) {
        logError('Invalid request: Missing name or email');
        return false;
    }

    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        logError('Invalid request: Invalid email format');
        return false;
    }

    // Check for duplicate emails
    if (userExistsByEmail($email) && ($id === null || !userExistsById($id))) {
        logError('Invalid request: Duplicate email');
        return false;
    }

    // Validate password complexity
    if (!validatePasswordComplexity($password)) {
        logError('Invalid request: Password does not meet complexity requirements');
        return false;
    }

    // Check user roles and permissions
    if (!isValidUserRole($_REQUEST['role'])) {
        logError('Invalid request: Invalid user role');
        return false;
    }

    // Handle sub_action
    if ($sub_action === 'delete') {
        if (userExistsById($id)) {
            deleteUserAccount($id);
            logSuccess("User account deleted successfully with ID: $id");
        } else {
            logError('Invalid request: User not found for deletion');
            return false;
        }
    } else {
        // Create or update user
        if ($id === null) {
            $newId = createUserAccount($name, $email, $password, $_REQUEST['role']);
            logSuccess("User account created successfully with ID: $newId");
        } else {
            updateUserAccount($id, $name, $email, $password, $_REQUEST['role']);
            logSuccess("User account updated successfully with ID: $id");
        }
    }

    return true;
}

