typedef struct block_data {
    // Define the structure to hold data specific to the resource item
} block_data;

typedef struct resource_item {
    int identifier;
    block_data *data;
} resource_item;

typedef struct resource_bundle {
    size_t count;
    resource_item **items;
} resource_bundle;

int load_resource_bundle(const char *path, resource_bundle *bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    // Read the number of items from the file
    size_t count;
    if (fscanf(file, "%zu", &count) != 1) {
        fclose(file);
        perror("Failed to read item count");
        return -1;
    }

    bundle->count = count;
    bundle->items = malloc(count * sizeof(resource_item *));
    if (!bundle->items) {
        fclose(file);
        perror("Failed to allocate memory for items");
        return -1;
    }

    // Dynamically allocate memory for each item and initialize
    for (size_t i = 0; i < count; ++i) {
        bundle->items[i] = malloc(sizeof(resource_item));
        if (!bundle->items[i]) {
            perror("Failed to allocate memory for item");
            // Free previously allocated items
            for (size_t j = 0; j < i; ++j) {
                free(bundle->items[j]);
            }
            free(bundle->items);
            fclose(file);
            return -1;
        }

        // Initialize the identifier with a random value within a specified range
        bundle->items[i]->identifier = rand() % (MAX_IDENTIFIER_VALUE + 1);

        // Allocate memory for block_data and initialize it
        bundle->items[i]->data = malloc(sizeof(block_data));
        if (!bundle->items[i]->data) {
            perror("Failed to allocate memory for block_data");
            // Free previously allocated items and data
            for (size_t j = 0; j <= i; ++j) {
                free(bundle->items[j]->data);
                free(bundle->items[j]);
            }
            free(bundle->items);
            fclose(file);
            return -1;
        }

        // Initialize block_data as needed
    }

    fclose(file);
    return count;
}

void free_resource_bundle(resource_bundle *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->items[i]->data);
        free(bundle->items[i]);
    }
    free(bundle->items);
}
