using System;
using System.Net.Http;
using System.Threading.Tasks;

public class PageSectionUpdater
{
    private readonly HttpClient _httpClient;
    private readonly string[] _allowedPageSections = { "header", "footer", "sidebar" };
    private readonly string[] _allowedElementIds = { "logo", "menu", "contact" };

    public PageSectionUpdater(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    public async Task<HttpResponseMessage> UpdatePageSectionAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (!IsAllowedPageSection(pageSectionId))
        {
            return new HttpResponseMessage(System.Net.HttpStatusCode.Forbidden) { Content = new StringContent("Unauthorized update to page section") };
        }

        if (!IsAllowedElementId(elementId))
        {
            return new HttpResponseMessage(System.Net.HttpStatusCode.Forbidden) { Content = new StringContent("Unauthorized update to element ID") };
        }

        if (htmlContent.Length > 1024)
        {
            return new HttpResponseMessage(System.Net.HttpStatusCode.BadRequest) { Content = new StringContent("HTML content exceeds size limit") };
        }

        if (ContainsForbiddenTags(htmlContent))
        {
            return new HttpResponseMessage(System.Net.HttpStatusCode.BadRequest) { Content = new StringContent("HTML content contains forbidden tags") };
        }

        try
        {
            var maintenanceStatus = await CheckMaintenanceStatusAsync(pageSectionId);
            if (maintenanceStatus)
            {
                return new HttpResponseMessage(System.Net.HttpStatusCode.ServiceUnavailable) { Content = new StringContent("System is undergoing maintenance") };
            }
        }
        catch (Exception ex)
        {
            // Log the exception and continue with the update
            Console.WriteLine($"Error checking maintenance status: {ex.Message}");
        }

        try
        {
            var response = await _httpClient.PostAsync($"/api/update?section={pageSectionId}&element={elementId}", new StringContent(htmlContent));
            return response;
        }
        catch (HttpRequestException ex)
        {
            // Log the exception and retry the request
            Console.WriteLine($"Request failed: {ex.Message}");
            return await _httpClient.PostAsync($"/api/update?section={pageSectionId}&element={elementId}", new StringContent(htmlContent));
        }
    }

    private bool IsAllowedPageSection(string pageSectionId)
    {
        return Array.IndexOf(_allowedPageSections, pageSectionId) >= 0;
    }

    private bool IsAllowedElementId(string elementId)
    {
        return Array.IndexOf(_allowedElementIds, elementId) >= 0;
    }

    private bool ContainsForbiddenTags(string htmlContent)
    {
        // Implement logic to check for forbidden tags
        return false;
    }

    private async Task<bool> CheckMaintenanceStatusAsync(string pageSectionId)
    {
        try
        {
            var response = await _httpClient.GetAsync($"/api/maintenance?section={pageSectionId}");
            if (response.IsSuccessStatusCode)
            {
                var maintenanceStatus = await response.Content.ReadAsAsync<bool>();
                return maintenanceStatus;
            }
        }
        catch (HttpRequestException ex)
        {
            // Log the exception and continue with the update
            Console.WriteLine($"Error checking maintenance status: {ex.Message}");
        }

        return false;
    }
}
