typedef struct {
    int value;
    size_t size;
    void* data;
} record;

void initialize_records(record** records, long* offsets, int* keys, int num_records, int min_val, int max_val, const char* data_str) {
    srand(time(NULL));

    *records = (record*)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }

    offsets = (long*)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        free(*records);
        exit(EXIT_FAILURE);
    }

    keys = (int*)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*records);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % (max_val - min_val + 1) + min_val;
        (*records)[i].size = strlen(data_str) + 1;
        (*records)[i].data = malloc((*records)[i].size);
        if ((*records)[i].data == NULL) {
            fprintf(stderr, "Memory allocation failed for record data\n");
            free(*records);
            free(offsets);
            free(keys);
            exit(EXIT_FAILURE);
        }
        strcpy((char*)(*records)[i].data, data_str);

        offsets[i] = i * sizeof(record);
        keys[i] = i;
    }
}

void free_records(record** records, long* offsets, int* keys, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free((*records)[i].data);
    }

    free(*records);
    free(offsets);
    free(keys);
}
