async function loadAndTestModules(moduleName, modulePath, testSuite) {
    const blueslip = require('blueslip');
    const fs = require('fs').promises;
    const path = require('path');

    let config = {
        timeout: 5000,
        logLevel: 'info',
        resourceLimit: 100
    };

    function loadModule(modulePath) {
        return import(path.join(modulePath, `${moduleName}.js`));
    }

    async function runTests(module, testSuite) {
        for (const test of testSuite) {
            try {
                await test(module);
                console.log(`Test passed: ${test.name}`);
            } catch (error) {
                blueslip.error(`Test failed: ${test.name}`, { error });
            }
        }
    }

    async function executeTests() {
        const module = await loadModule(modulePath);
        await runTests(module, testSuite);
    }

    executeTests();
}
