#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define BUFFER_SIZE 1024

typedef struct {
    long timestamp;
    double measurement;
} SensorRecord;

typedef struct {
    SensorRecord *records;
    size_t capacity;
    size_t count;
    FILE *file;
} SensorLog;

SensorLog* init_sensor_log(const char *filename) {
    SensorLog *log = (SensorLog*)malloc(sizeof(SensorLog));
    if (!log) return NULL;

    log->capacity = 10;
    log->count = 0;
    log->records = (SensorRecord*)malloc(log->capacity * sizeof(SensorRecord));
    if (!log->records) {
        free(log);
        return NULL;
    }

    log->file = fopen(filename, "r");
    if (!log->file) {
        free(log->records);
        free(log);
        return NULL;
    }

    return log;
}

void destroy_sensor_log(SensorLog *log) {
    if (log->file) fclose(log->file);
    free(log->records);
    free(log);
}

int read_next_record(SensorLog *log, SensorRecord *record) {
    if (log->count == log->capacity) {
        size_t new_capacity = log->capacity * 2;
        SensorRecord *new_records = (SensorRecord*)realloc(log->records, new_capacity * sizeof(SensorRecord));
        if (!new_records) return -1;
        log->records = new_records;
        log->capacity = new_capacity;
    }

    if (fscanf(log->file, "%ld %lf", &record->timestamp, &record->measurement) != 2) {
        return -1; // End of file or error
    }

    log->count++;
    return 0;
}

int main() {
    SensorLog *log = init_sensor_log("sensor_data.log");
    if (!log) {
        fprintf(stderr, "Failed to initialize sensor log.\n");
        return EXIT_FAILURE;
    }

    SensorRecord record;
    while (read_next_record(log, &record) == 0) {
        printf("Timestamp: %ld, Measurement: %.2f\n", record.timestamp, record.measurement);
    }

    destroy_sensor_log(log);
    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a sensor log manager in C. It includes functions to initialize and destroy the log, read records from a file, and handle memory allocation dynamically. The `main` function demonstrates how to use these functions to read and process sensor data from a file.']

