typedef struct {
    long timestamp;
} Timestamp;

typedef struct {
    double measurement;
} Measurement;

typedef struct {
    Timestamp timestamp;
    Measurement measurement;
} SensorRecord;

SensorRecord* allocate_sensor_records(const char* filename, size_t* num_records) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Estimate initial number of records
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t initial_capacity = file_size / (sizeof(Timestamp) + sizeof(Measurement));
    SensorRecord* records = malloc(initial_capacity * sizeof(SensorRecord));
    if (!records) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t count = 0;
    while (fread(&records[count].timestamp, sizeof(Timestamp), 1, file) == 1 &&
           fread(&records[count].measurement, sizeof(Measurement), 1, file) == 1) {
        count++;
        if (count >= initial_capacity) {
            // Reallocate memory
            SensorRecord* new_records = realloc(records, (initial_capacity * 2) * sizeof(SensorRecord));
            if (!new_records) {
                perror("Failed to reallocate memory");
                free(records);
                fclose(file);
                return NULL;
            }
            records = new_records;
            initial_capacity *= 2;
        }
    }

    *num_records = count;
    fclose(file);
    return records;
}

void* thread_function(void* arg) {
    // Simulate concurrent access
    size_t num_records;
    SensorRecord* records = allocate_sensor_records("sensor_data.csv", &num_records);
    if (records) {
        // Process records
        free(records);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (size_t i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (size_t i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
