#define MAX_THEME_SIZE 1024 * 1024 // 1MB

typedef struct {
    char* path;
    int item_count;
} ResourceBundle;

int manageThemeCache(Bitmap** themeBitmap) {
    if (themeBitmap && *themeBitmap) {
        free(*themeBitmap);
        *themeBitmap = NULL;
    }
    return 0;
}

ResourceBundle* loadResourceBundle(const char* filePath, int* error_code) {
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        *error_code = -1; // Memory allocation failed
        return NULL;
    }

    FILE* file = fopen(filePath, "rb");
    if (!file) {
        *error_code = -2; // File open failed
        free(bundle);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (fileSize > MAX_THEME_SIZE) {
        *error_code = -3; // File size exceeds limit
        fclose(file);
        free(bundle);
        return NULL;
    }

    bundle->path = strdup(filePath);
    bundle->item_count = fread(bundle->path, sizeof(char), fileSize, file);

    if (ferror(file)) {
        *error_code = -4; // Read error
        fclose(file);
        free(bundle->path);
        free(bundle);
        return NULL;
    }

    fclose(file);
    *error_code = 0; // Success
    return bundle;
}

int getBundleItemCount(ResourceBundle* bundle) {
    if (!bundle) {
        return -1; // Invalid bundle
    }
    return bundle->item_count;
}
