#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <condition_variable>

class ConfigEntry {
public:
    std::string key;
    std::string value;
    std::string source;
    time_t timestamp;

    ConfigEntry(std::string k, std::string v, std::string s, time_t t)
        : key(k), value(v), source(s), timestamp(t) {}
};

class ConfigManager {
private:
    std::unordered_map<std::string, ConfigEntry> configMap;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void addSource(std::function<void()> updateFunction);
    void removeSource(std::function<void()> updateFunction);

    ConfigEntry getConfig(const std::string& key);
    void updateConfig(const std::string& key, const std::string& value, const std::string& source, time_t timestamp);
};

void ConfigManager::addSource(std::function<void()> updateFunction) {
    std::lock_guard<std::mutex> lock(mutex);
    // Add the source to a list of sources and start an update thread
    std::thread([this, updateFunction]() {
        while (true) {
            updateFunction();
            cv.notify_all();
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock);
        }
    }).detach();
}

void ConfigManager::removeSource(std::function<void()> updateFunction) {
    // Remove the source from the list of sources
}

ConfigEntry ConfigManager::getConfig(const std::string& key) {
    std::lock_guard<std::mutex> lock(mutex);
    return configMap[key];
}

void ConfigManager::updateConfig(const std::string& key, const std::string& value, const std::string& source, time_t timestamp) {
    std::lock_guard<std::mutex> lock(mutex);
    if (configMap.find(key) == configMap.end() || timestamp > configMap[key].timestamp) {
        configMap[key] = ConfigEntry(key, value, source, timestamp);
        cv.notify_all();
    }
}
