#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long id;
    char name[256];
    char* description;
    time_t last_modified;
    size_t version;
    int active;
} Component;

typedef struct {
    Component** components;
    size_t count;
    size_t capacity;
} Registry;

Registry* create_registry() {
    Registry* registry = (Registry*)malloc(sizeof(Registry));
    if (!registry) return NULL;
    registry->components = NULL;
    registry->count = 0;
    registry->capacity = 0;
    return registry;
}

void destroy_registry(Registry* registry) {
    for (size_t i = 0; i < registry->count; ++i) {
        free(registry->components[i]->description);
        free(registry->components[i]);
    }
    free(registry->components);
    free(registry);
}

int add_or_update_component(Registry* registry, long id, const char* name, const char* description, size_t version, int sub_action) {
    for (size_t i = 0; i < registry->count; ++i) {
        if (registry->components[i]->id == id) {
            free(registry->components[i]->description);
            strcpy(registry->components[i]->name, name);
            registry->components[i]->description = strdup(description);
            registry->components[i]->version = version;
            registry->components[i]->last_modified = time(NULL);
            if (sub_action == 1) {
                registry->components[i]->active = 0;
            }
            return 0; // Success
        }
    }

    Component* new_component = (Component*)malloc(sizeof(Component));
    if (!new_component) return -1; // Memory allocation failed

    new_component->id = id;
    strcpy(new_component->name, name);
    new_component->description = strdup(description);
    new_component->version = version;
    new_component->last_modified = time(NULL);
    new_component->active = (sub_action != 1);

    if (registry->count == registry->capacity) {
        size_t new_capacity = (registry->capacity > 0) ? registry->capacity * 2 : 4;
        Component** new_components = (Component**)realloc(registry->components, new_capacity * sizeof(Component*));
        if (!new_components) {
            free(new_component);
            return -1; // Memory allocation failed
        }
        registry->components = new_components;
        registry->capacity = new_capacity;
    }

    registry->components[registry->count++] = new_component;

    return 0; // Success
}

char* get_registry_status(Registry* registry) {
    char* status = (char*)malloc(256 * sizeof(char));
    if (!status) return NULL; // Memory allocation failed

    snprintf(status, 256, "{\"message\": \"success\"}");
    return status;
}
