#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_TASKS 1000

typedef struct {
    char *filename;
    int target_width;
    int target_height;
    char output_format[5];
} ImageTask;

typedef struct {
    ImageTask task;
    sem_t semaphore;
} TaskQueueItem;

TaskQueueItem task_queue[MAX_TASKS];
int front = 0, rear = -1;
pthread_mutex_t queue_lock;
sem_t queue_not_full, queue_not_empty;

void init_task_queue() {
    pthread_mutex_init(&queue_lock, NULL);
    sem_init(&queue_not_full, 0, MAX_TASKS);
    sem_init(&queue_not_empty, 0, 0);
}

int enqueue_task(ImageTask task) {
    sem_wait(&queue_not_full);
    pthread_mutex_lock(&queue_lock);
    rear = (rear + 1) % MAX_TASKS;
    task_queue[rear].task = task;
    sem_post(&queue_not_empty);
    pthread_mutex_unlock(&queue_lock);
    return 0;
}

ImageTask dequeue_task() {
    ImageTask task;
    sem_wait(&queue_not_empty);
    pthread_mutex_lock(&queue_lock);
    task = task_queue[front].task;
    front = (front + 1) % MAX_TASKS;
    sem_post(&queue_not_full);
    pthread_mutex_unlock(&queue_lock);
    return task;
}

void *process_image_task(void *arg) {
    ImageTask task = *(ImageTask *)arg;
    // Perform image processing operations here
    printf("Processing image: %s\n", task.filename);
    free(arg); // Free the allocated memory for the task
    return NULL;
}

void process_images() {
    init_task_queue();
    char filename[256];
    while (scanf("%s", filename) != EOF) {
        ImageTask *task = malloc(sizeof(ImageTask));
        if (!task) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        task->filename = strdup(filename);
        // Set other parameters for the task
        enqueue_task(*task);
    }

    pthread_t threads[MAX_TASKS];
    int num_threads = 0;
    while (front != rear || sem_getvalue(&queue_not_empty, NULL) > 0) {
        ImageTask task = dequeue_task();
        if (num_threads < MAX_TASKS && sem_getvalue(&queue_not_full, NULL) > 0) {
            pthread_create(&threads[num_threads++], NULL, process_image_task, &task);
        } else {
            pthread_join(threads[--num_threads], NULL);
            pthread_create(&threads[num_threads++], NULL, process_image_task, &task);
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free all allocated memory
    for (int i = front; i != rear; i = (i + 1) % MAX_TASKS) {
        free(task_queue[i].task.filename);
        free(&task_queue[i]);
    }
}

int main() {
    process_images();
    return 0;
}
