['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    size_t dataSize;
    time_t lastAccessed;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t offsetSize;
    size_t keySize;
    size_t recordSize;
    pthread_mutex_t mutex;
} dataManager;

dataManager* dataManager_init(size_t initialOffsetSize, size_t initialKeySize, size_t initialRecordSize) {
    dataManager *dm = (dataManager*)malloc(sizeof(dataManager));
    if (!dm) return NULL;

    dm->offsets = (long*)calloc(initialOffsetSize, sizeof(long));
    dm->keys = (int*)calloc(initialKeySize, sizeof(int));
    dm->records = (record**)calloc(initialRecordSize, sizeof(record*));
    if (!dm->offsets || !dm->keys || !dm->records) {
        free(dm);
        return NULL;
    }

    dm->offsetSize = initialOffsetSize;
    dm->keySize = initialKeySize;
    dm->recordSize = initialRecordSize;
    pthread_mutex_init(&dm->mutex, NULL);

    return dm;
}

void dataManager_setRandomValues(dataManager *dm, int minValue, int maxValue) {
    pthread_mutex_lock(&dm->mutex);
    for (size_t i = 0; i < dm->recordSize; ++i) {
        if (!dm->records[i]) continue;
        dm->records[i]->value = rand() % (maxValue - minValue + 1) + minValue;
    }
    pthread_mutex_unlock(&dm->mutex);
}

void dataManager_updateTimestamps(dataManager *dm, time_t interval) {
    pthread_mutex_lock(&dm->mutex);
    for (size_t i = 0; i < dm->recordSize; ++i) {
        if (!dm->records[i]) continue;
        dm->records[i]->lastAccessed += interval;
    }
    pthread_mutex_unlock(&dm->mutex);
}

void dataManager_free(dataManager *dm) {
    pthread_mutex_lock(&dm->mutex);
    for (size_t i = 0; i < dm->recordSize; ++i) {
        if (dm->records[i]) free(dm->records[i]);
    }
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_unlock(&dm->mutex);
    pthread_mutex_destroy(&dm->mutex);
    free(dm);
}
