typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

IDataReader* createNfadbCommand(const char* connectionString, NFAPI_CRC_INDICATION_PDU_T* pduList, int listSize, const char* baseSqlCommand) {
    sqlite3* db;
    IDataReader* reader = NULL;
    char* sqlCommand = NULL;
    int i;

    // Connect to the database
    if (sqlite3_open(connectionString, &db) != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return NULL;
    }

    // Allocate memory for SQL command
    sqlCommand = (char*)malloc(strlen(baseSqlCommand) + listSize * 100); // Adjust size as needed
    if (!sqlCommand) {
        fprintf(stderr, "Memory allocation failed\n");
        sqlite3_close(db);
        return NULL;
    }

    // Construct the parameterized SQL command
    strcpy(sqlCommand, baseSqlCommand);
    for (i = 0; i < listSize; i++) {
        char temp[100];
        snprintf(temp, sizeof(temp), ",(?, ?, ?)");
        strcat(sqlCommand, temp);
    }
    sqlCommand[strlen(sqlCommand) - 1] = '\0'; // Remove the last comma

    // Prepare and execute the SQL command
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sqlCommand, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        free(sqlCommand);
        sqlite3_close(db);
        return NULL;
    }

    // Bind parameters
    for (i = 0; i < listSize; i++) {
        sqlite3_bind_int(stmt, i * 3 + 1, pduList[i].RX_UE_INFORMATION_TAG);
        sqlite3_bind_int(stmt, i * 3 + 2, pduList[i].RNTI);
        sqlite3_bind_int(stmt, i * 3 + 3, pduList[i].CRC_INDICATION_REL8_TAG);
    }

    // Execute the command
    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "SQL execution error: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        free(sqlCommand);
        sqlite3_close(db);
        return NULL;
    }

    // Create and return the IDataReader
    reader = createIDataReader(stmt); // Assume this function exists to create an IDataReader from a sqlite3_stmt

    // Clean up
    sqlite3_finalize(stmt);
    free(sqlCommand);
    sqlite3_close(db);

    return reader;
}
