NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **current = &head;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) return NULL;

        new_node->rx_ue_info.RX_UE_INFORMATION_TAG = i;
        new_node->rx_ue_info.RNTI = i * 10;
        new_node->crc_ind_rel8.CRCFLAG = (i % 2 == 0) ? 1 : 0; // Example checksum logic
        new_node->next = NULL;

        *current = new_node;
        current = &new_node->next;
    }

    return head;
}
