#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    char* identifier;
    unsigned long hash;
    time_t timestamp;
} MetaData;

typedef struct {
    Record** records;
    MetaData** metadata;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} RecordList;

unsigned long hash_string(const char* str) {
    // Simple hash function for demonstration purposes
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

char* generate_random_string(size_t length, const char* charset) {
    size_t charset_length = strlen(charset);
    char* result = (char*)malloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        result[i] = charset[rand() % charset_length];
    }
    result[length] = '\0';
    return result;
}

void initialize_record_list(RecordList* list, size_t initial_capacity) {
    list->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    list->metadata = (MetaData**)malloc(initial_capacity * sizeof(MetaData*));
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_record(RecordList* list, int value, const char* identifier) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Record** new_records = (Record**)realloc(list->records, new_capacity * sizeof(Record*));
        MetaData** new_metadata = (MetaData**)realloc(list->metadata, new_capacity * sizeof(MetaData*));
        if (!new_records || !new_metadata) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->records = new_records;
        list->metadata = new_metadata;
        list->capacity = new_capacity;
    }
    Record* record = (Record*)malloc(sizeof(Record));
    MetaData* meta = (MetaData*)malloc(sizeof(MetaData));
    if (!record || !meta) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    meta->identifier = generate_random_string(strlen(identifier), identifier);
    meta->hash = hash_string(meta->identifier);
    meta->timestamp = time(NULL);
    list->records[list->count] = record;
    list->metadata[list->count] = meta;
    ++list->count;
    pthread_mutex_unlock(&list->mutex);
}

void free_record_list(RecordList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
        free(list->metadata[i]->identifier);
        free(list->metadata[i]);
    }
    free(list->records);
    free(list->metadata);
    pthread_mutex_destroy(&list->mutex);
}

int main() {
    srand(time(NULL));
    RecordList list;
    initialize_record_list(&list, 10);

    for (size_t i = 0; i < 20; ++i) {
        add_record(&list, rand(), "abcdef");
    }

    free_record_list(&list);
    return 0;
}
