record* process_and_find_max(int num_records, int min_val, int max_val) {
    // Allocate memory for the collection of records
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each record with random values and dynamically allocated block_data
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % (max_val - min_val + 1) + min_val;
        records[i].offset = i * sizeof(record);
        records[i].rec.value = rand() % (max_val - min_val + 1) + min_val;
        records[i].rec.size = sizeof(int);
        records[i].rec.data = malloc(records[i].rec.size);
        if (!records[i].rec.data) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memcpy(records[i].rec.data, &records[i].rec.value, records[i].rec.size);
    }

    // Process input stream and update the internal array dynamically
    int new_value;
    while (scanf("%d", &new_value) != EOF) {
        num_records++;
        records = realloc(records, num_records * sizeof(record));
        if (!records) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[num_records - 1].key = new_value;
        records[num_records - 1].offset = (num_records - 1) * sizeof(record);
        records[num_records - 1].rec.value = new_value;
        records[num_records - 1].rec.size = sizeof(int);
        records[num_records - 1].rec.data = malloc(records[num_records - 1].rec.size);
        if (!records[num_records - 1].rec.data) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memcpy(records[num_records - 1].rec.data, &records[num_records - 1].rec.value, records[num_records - 1].rec.size);
    }

    // Find and return the maximum value
    int max_value = records[0].key;
    for (int i = 1; i < num_records; ++i) {
        if (records[i].key > max_value) {
            max_value = records[i].key;
        }
    }

    // Free allocated memory
    for (int i = 0; i < num_records; ++i) {
        free(records[i].rec.data);
    }
    free(records);

    return records;
}
