#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define BUFFER_LENGTH 50

typedef struct {
    int value;
    char buffer[BUFFER_LENGTH];
    double timestamp;
} record;

void log_operation(const char* operation, int success) {
    time_t now = time(NULL);
    printf("%s: %s\n", ctime(&now), operation);
    if (!success) {
        printf("Operation failed.\n");
    }
}

int initialize_records(long** offsets, int** keys, record** records, int max_records) {
    *offsets = (long*)malloc(max_records * sizeof(long));
    *keys = (int*)malloc(max_records * sizeof(int));
    *records = (record*)malloc(max_records * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        log_operation("Memory allocation failed", 0);
        return -1;
    }

    srand(time(NULL));
    int count = 0;

    while (count < max_records) {
        int key = rand() % max_records;
        int found = 0;

        for (int i = 0; i < count; i++) {
            if ((*keys)[i] == key) {
                found = 1;
                break;
            }
        }

        if (!found) {
            (*keys)[count] = key;
            (*records)[count].value = rand() % max_records;
            snprintf((*records)[count].buffer, BUFFER_LENGTH, "Prefix_%d", key);
            (*records)[count].timestamp = (double)rand() / RAND_MAX * time(NULL);
            count++;
        }
    }

    log_operation("Records initialized successfully", 1);
    return count;
}

void free_records(long* offsets, int* keys, record* records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
    log_operation("Records freed successfully", 1);
}

int main() {
    long* offsets;
    int* keys;
    record* records;
    int max_records = MAX_RECORDS;

    int count = initialize_records(&offsets, &keys, &records, max_records);

    if (count >= 0) {
        // Use the records here
        free_records(offsets, keys, records);
    }

    return 0;
}
