#define MAX_KEYS 1001

typedef struct {
    long offset;
    int key;
    char status;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* initialize_records(int num_records, long* offsets, int* keys) {
    record* records = safe_malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].status = 'A'; // Active
    }
    return records;
}

void set_random_values(record* records, int num_records, int min_value, int max_value) {
    srand(time(NULL));
    int values[MAX_KEYS] = {0};
    for (int i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (values[value]);
        records[i].key = value;
        values[value] = 1;
    }
}

void log_records(record* records, int num_records, const char* filename) {
    FILE* file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    for (int i = 0; i < num_records; ++i) {
        if (records[i].status == 'A') {
            fprintf(file, "Offset: %ld, Key: %d, Value: %d\n", records[i].offset, records[i].key, records[i].key);
        }
    }
    fclose(file);
}

int main() {
    int num_records = 500;
    long offsets[num_records];
    int keys[num_records];

    // Initialize offsets and keys
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i * 1024L; // Example offset calculation
        keys[i] = i % MAX_KEYS; // Ensure unique keys within the range
    }

    record* records = initialize_records(num_records, offsets, keys);
    set_random_values(records, num_records, 100, 999);

    log_records(records, num_records, "log.txt");

    free(records);
    return 0;
}
