#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef enum { SUCCESS, PARTIAL, FAILURE } status_t;

typedef struct {
    int value;
    char buffer[1024];
    double timestamp;
} record_data_t;

typedef struct {
    int ref_count;
    size_t memory_usage;
    record_data_t data;
} record_t;

typedef struct {
    int key;
    long offset;
    record_t* record;
    status_t status;
} batch_record_t;

typedef struct {
    int max_records_per_batch;
    size_t memory_limit;
    pthread_mutex_t lock;
    size_t total_memory_usage;
    int successful_records;
    int partial_records;
    int failed_records;
} batch_manager_t;

void log_message(const char* message) {
    // External logging function
}

int initialize_batch_manager(batch_manager_t* manager, int max_records_per_batch, size_t memory_limit) {
    manager->max_records_per_batch = max_records_per_batch;
    manager->memory_limit = memory_limit;
    pthread_mutex_init(&manager->lock, NULL);
    manager->total_memory_usage = 0;
    manager->successful_records = 0;
    manager->partial_records = 0;
    manager->failed_records = 0;
    return 0;
}

batch_record_t* create_batch_record(int key, long offset) {
    batch_record_t* record = (batch_record_t*)malloc(sizeof(batch_record_t));
    if (!record) {
        log_message("Failed to allocate memory for batch record");
        return NULL;
    }
    record->key = key;
    record->offset = offset;
    record->record = NULL;
    record->status = FAILURE;
    return record;
}

int initialize_record(record_t* record, int value, const char* buffer, double timestamp) {
    record->ref_count = 1;
    record->memory_usage = sizeof(record_data_t);
    record->data.value = value;
    strncpy(record->data.buffer, buffer, sizeof(record->data.buffer));
    record->data.timestamp = timestamp;
    return 0;
}

int add_record_to_batch(batch_manager_t* manager, batch_record_t* record) {
    pthread_mutex_lock(&manager->lock);
    if (manager->total_memory_usage + record->record->memory_usage > manager->memory_limit) {
        log_message("Memory limit exceeded");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->total_memory_usage += record->record->memory_usage;
    if (record->status == SUCCESS) {
        manager->successful_records++;
    } else if (record->status == PARTIAL) {
        manager->partial_records++;
    } else {
        manager->failed_records++;
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void free_batch_record(batch_record_t* record) {
    free(record);
}

void free_record(record_t* record) {
    // Free any additional resources if needed
    free(record);
}

void print_summary_report(batch_manager_t* manager) {
    printf("Summary Report:\n");
    printf("Successful Records: %d\n", manager->successful_records);
    printf("Partial Records: %d\n", manager->partial_records);
    printf("Failed Records: %d\n", manager->failed_records);
    printf("Total Memory Usage: %zu bytes\n", manager->total_memory_usage);
}

int main() {
    batch_manager_t manager;
    initialize_batch_manager(&manager, 100, 1024 * 1024); // Example configuration

    // Example usage
    batch_record_t* record = create_batch_record(1, 100);
    if (record) {
        record_t* rec = (record_t*)malloc(sizeof(record_t));
        initialize_record(rec, 42, "Example buffer", 1633072800.0);
        record->record = rec;
        add_record_to_batch(&manager, record);
    }

    print_summary_report(&manager);

    // Cleanup
    free_batch_record(record);
    free_record(record->record);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

This code provides a basic structure for managing a batch of records with concurrent access handling and memory management. It includes functions to initialize the manager, create batch records, add records to the batch, and print a summary report. The actual implementation details such as logging, error handling, and memory management optimizations are left as an exercise for the developer.']

