#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char buffer[256];
    double timestamp;
    size_t size;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t count;
    size_t max_count;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t max_count) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->offsets = (long*)malloc(max_count * sizeof(long));
    manager->keys = (int*)malloc(max_count * sizeof(int));
    manager->records = (Record**)malloc(max_count * sizeof(Record*));
    manager->count = 0;
    manager->max_count = max_count;
    pthread_mutex_init(&manager->lock, NULL);

    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager);
        return NULL;
    }

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(RecordManager* manager, int value_range_start, int value_range_end) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->max_count) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Manager is full
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Error: Memory allocation failed
    }

    new_record->value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
    snprintf(new_record->buffer, sizeof(new_record->buffer), "Prefix_%d", new_record->value);
    new_record->timestamp = time(NULL);
    new_record->size = strlen(new_record->buffer);

    manager->offsets[manager->count] = (long)new_record;
    manager->keys[manager->count] = new_record->value;
    manager->records[manager->count++] = new_record;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int remove_record(RecordManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->keys[i] == key) {
            free(manager->records[i]);
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->offsets[j] = manager->offsets[j + 1];
                manager->keys[j] = manager->keys[j + 1];
                manager->records[j] = manager->records[j + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: Key not found
}

void log_operation(RecordManager* manager, const char* operation, int result) {
    printf("Operation: %s, Result: %d\n", operation, result);
}
