#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    PENDING,
    IN_PROGRESS,
    COMPLETED
} status;

typedef struct project {
    char* name;
    size_t priority;
    void* data;
    status current_status;
    struct project* next;
} project;

typedef struct project_list {
    project* head;
    pthread_mutex_t lock;
} project_list;

project* create_project(const char* name, size_t priority, void* data, status current_status) {
    project* new_project = (project*)malloc(sizeof(project));
    if (!new_project) return NULL;

    new_project->name = strdup(name);
    new_project->priority = priority;
    new_project->data = data;
    new_project->current_status = current_status;
    new_project->next = NULL;

    return new_project;
}

void free_project(project* project) {
    if (project) {
        free(project->name);
        free(project);
    }
}

int add_project(project_list* list, project* new_project) {
    pthread_mutex_lock(&list->lock);
    new_project->next = list->head;
    list->head = new_project;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

project* find_project_by_name(project_list* list, const char* name) {
    pthread_mutex_lock(&list->lock);
    project* current = list->head;
    while (current) {
        if (strcmp(current->name, name) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int update_project(project_list* list, const char* name, size_t priority, void* data, status current_status) {
    project* project = find_project_by_name(list, name);
    if (!project) return -1;

    free_project(project);
    project = create_project(name, priority, data, current_status);
    if (!project) return -1;

    add_project(list, project);
    return 0;
}

int remove_project(project_list* list, const char* name) {
    pthread_mutex_lock(&list->lock);
    project* current = list->head;
    project* prev = NULL;
    while (current) {
        if (strcmp(current->name, name) == 0) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free_project(current);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

void iterate_projects(project_list* list, void (*callback)(project*)) {
    pthread_mutex_lock(&list->lock);
    project* current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_project_list(project_list* list) {
    pthread_mutex_lock(&list->lock);
    project* current = list->head;
    while (current) {
        project* next = current->next;
        free_project(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void log_project_change(project* project, const char* action) {
    printf("Project %s: %s\n", project->name, action);
}
