#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    int value;
    char buffer[256];
    double timestamp;
    size_t data_size;
    void* metadata;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
} RecordStore;

void init_record_store(RecordStore* store) {
    store->count = 0;
}

int add_record(RecordStore* store, long offset, int key, char* buffer, size_t data_size, void* metadata) {
    if (store->count >= MAX_RECORDS) return -1; // Store is full
    Record* record = &store->records[store->count++];
    record->offset = offset;
    record->key = key;
    record->value = rand() % 1000; // Random value between 0 and 999
    strncpy(record->buffer, buffer, sizeof(record->buffer));
    record->timestamp = time(NULL);
    record->data_size = data_size;
    record->metadata = metadata;
    return 0;
}

Record* get_record(RecordStore* store, int key) {
    for (int i = 0; i < store->count; i++) {
        if (store->records[i].key == key) return &store->records[i];
    }
    return NULL;
}

int update_record(RecordStore* store, int key, char* buffer, size_t data_size, void* metadata) {
    Record* record = get_record(store, key);
    if (!record) return -1; // Record not found
    strncpy(record->buffer, buffer, sizeof(record->buffer));
    record->data_size = data_size;
    record->metadata = metadata;
    return 0;
}

int delete_record(RecordStore* store, int key) {
    for (int i = 0; i < store->count; i++) {
        if (store->records[i].key == key) {
            memmove(&store->records[i], &store->records[i + 1], sizeof(Record) * (store->count - i - 1));
            store->count--;
            return 0;
        }
    }
    return -1; // Record not found
}

void log_operation(const char* operation, int success, size_t memory_usage) {
    printf("%s: %s, Memory Usage: %zu bytes\n", operation, success ? "Success" : "Failure", memory_usage);
}
