    *count = 0;

    if (*offsets == NULL || *keys == NULL || *records == NULL || *buffers == NULL || *timestamps == NULL || *sizes == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < max_count; ++i) {
        (*keys)[i] = rand() % max_count;
        while (i > 0 && (*keys)[i] == (*keys)[i - 1]) {
            (*keys)[i] = rand() % max_count;
        }
        (*records)[i].value = rand() % 1000;
        (*buffers)[i] = (char*)malloc(256 * sizeof(char));
        snprintf((*buffers)[i], 256, "P%d", (*keys)[i]);
        (*timestamps)[i] = time(NULL);
        (*sizes)[i] = rand() % 1024;
    }
}

void cleanup_records(long* offsets, int* keys, Record* records, char** buffers, double* timestamps, size_t* sizes, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(buffers[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(buffers);
    free(timestamps);
    free(sizes);
}

int main() {
    long* offsets;
    int* keys;
    Record* records;
    char** buffers;
    double* timestamps;
    size_t* sizes;
    size_t count;

    initialize_records(&offsets, &keys, &records, &buffers, &timestamps, &sizes, &count, 1000);

    // Perform operations on the records...

    cleanup_records(offsets, keys, records, buffers, timestamps, sizes, count);

    return 0;
}
