typedef enum { PENDING, IN_PROGRESS, COMPLETED } TaskStatus;

typedef struct {
    int id;
    TaskStatus status;
    int priority;
} Task;

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    size_t size;
    void* data;
} DataBlock;

typedef struct {
    Task** tasks;
    size_t task_count;
    size_t task_capacity;
    Record* records;
    long* offsets;
    int* keys;
    size_t record_count;
    size_t record_capacity;
    DataBlock* data_blocks;
} TaskManager;

TaskManager* create_task_manager() {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    if (!manager) return NULL;

    manager->tasks = NULL;
    manager->task_count = 0;
    manager->task_capacity = 0;
    manager->records = NULL;
    manager->offsets = NULL;
    manager->keys = NULL;
    manager->record_count = 0;
    manager->record_capacity = 0;
    manager->data_blocks = NULL;

    return manager;
}

void free_task_manager(TaskManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->task_count; ++i) {
        free(manager->tasks[i]);
    }
    free(manager->tasks);

    for (size_t i = 0; i < manager->record_count; ++i) {
        free(manager->data_blocks[i].data);
    }
    free(manager->records);
    free(manager->offsets);
    free(manager->keys);
    free(manager->data_blocks);

    free(manager);
}

void insert_task(TaskManager* manager, int id, TaskStatus status, int priority) {
    if (manager->task_count >= manager->task_capacity) {
        // Resize tasks array
    }

    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) return;

    new_task->id = id;
    new_task->status = status;
    new_task->priority = priority;

    manager->tasks[manager->task_count++] = new_task;
}

void insert_record(TaskManager* manager, long offset, int key, size_t data_size) {
    if (manager->record_count >= manager->record_capacity) {
        // Resize records array
    }

    Record* new_record = &manager->records[manager->record_count++];
    new_record->offset = offset;
    new_record->key = key;

    DataBlock* new_block = &manager->data_blocks[manager->record_count - 1];
    new_block->size = data_size;
    new_block->data = malloc(data_size);
    if (!new_block->data) return;

    // Initialize data block with random values
    srand(time(NULL));
    for (size_t i = 0; i < data_size; ++i) {
        ((char*)new_block->data)[i] = rand() % 256;
    }
}

// Additional functions to retrieve tasks by status or priority, and free memory safely

int main() {
    TaskManager* manager = create_task_manager();
    if (!manager) return -1;

    insert_task(manager, 1, PENDING, 3);
    insert_record(manager, 0, 100, 1024);

    // Use the task and record management functions

    free_task_manager(manager);
    return 0;
}
