#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the component structure
typedef struct {
    long id;
    char name[256];
    char description[1024];
    time_t last_modified;
    size_t version;
    int active;
} Component;

// Define a simple linked list for storing components
typedef struct Node {
    Component data;
    struct Node* next;
} Node;

Node* head = NULL;
int total_components = 0;
int created = 0, updated = 0, deactivated = 0, failed_to_allocate = 0;

// Function to create or update a component
char* manage_component(long id, char* name, char* description, size_t version, char* sub_action) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.id == id) {
            // Update existing component
            strcpy(current->data.name, name);
            strcpy(current->data.description, description);
            current->data.version = version;
            current->data.last_modified = time(NULL);
            current->data.active = sub_action && strcmp(sub_action, "deactivate") == 0 ? 0 : 1;
            updated++;
            return "{\"message\": \"success\"}";
        }
        current = current->next;
    }

    // Create new component
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        failed_to_allocate++;
        return "{\"message\": \"error\", \"details\": \"Failed to allocate memory\"}";
    }
    new_node->data.id = id;
    strcpy(new_node->data.name, name);
    strcpy(new_node->data.description, description);
    new_node->data.version = version;
    new_node->data.last_modified = time(NULL);
    new_node->data.active = sub_action && strcmp(sub_action, "deactivate") == 0 ? 0 : 1;
    new_node->next = head;
    head = new_node;
    created++;
    total_components++;
    return "{\"message\": \"success\"}";
}

// Function to serialize components to a file
void serialize_components(char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error opening file for writing\n");
        return;
    }
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(Component), 1, file);
        current = current->next;
    }
    fclose(file);
}

// Function to deserialize components from a file
void deserialize_components(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening file for reading\n");
        return;
    }
    Component component;
    while (fread(&component, sizeof(Component), 1, file) == 1) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            failed_to_allocate++;
            continue;
        }
        new_node->data = component;
        new_node->next = head;
        head = new_node;
        total_components++;
    }
    fclose(file);
}

// Function to validate and update component versions
void validate_and_update_versions(size_t version_threshold) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.version < version_threshold) {
            // Update component version
            current->data.version++;
            updated++;
        }
        current = current->next;
    }
}

int main() {
    // Example usage of the manage_component function
    printf("%s\n", manage_component(1, "ComponentA", "Description A", 1, NULL));
    printf("%s\n", manage_component(2, "ComponentB", "Description B", 1, "deactivate"));
    printf("%s\n", manage_component(1, "UpdatedComponentA", "Updated Description A", 2, NULL));

    // Serialize and deserialize components
    serialize_components("components.bin");
    deserialize_components("components.bin");

    // Validate and update component versions
    validate_and_update_versions(2);

    return 0;
}
