#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    int value;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(RecordManager* manager, int key, long offset, int value) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        Record** new_records = (Record**)realloc(manager->records, manager->capacity * 2 * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->records = new_records;
        manager->capacity *= 2;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    record->key = key;
    record->offset = offset;
    record->value = value;

    manager->records[manager->size++] = record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

Record* get_record(RecordManager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i]->key == key) {
            Record* record = manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int update_record(RecordManager* manager, int key, long offset, int value) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i]->key == key) {
            Record* record = manager->records[i];
            record->offset = offset;
            record->value = value;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;
}
