#include <stdlib.h>
#include <pthread.h>

typedef union {
    int i;
    double d;
} Data;

typedef struct Node {
    unsigned long timestamp;
    int event_type;
    Data data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Node* create_node(unsigned long timestamp, int event_type, Data data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->timestamp = timestamp;
    node->event_type = event_type;
    node->data = data;
    node->next = NULL;
    return node;
}

void add_node(LinkedList* list, unsigned long timestamp, int event_type, Data data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(timestamp, event_type, data);
    if (new_node) {
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

Node* get_node(LinkedList* list, unsigned long timestamp) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current && current->timestamp != timestamp) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

void remove_node(LinkedList* list, unsigned long timestamp) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current && current->timestamp != timestamp) {
        prev = current;
        current = current->next;
    }
    if (current) {
        if (prev) {
            prev->next = current->next;
        } else {
            list->head = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}
