Node** create_node_array(int num_nodes, int min_val, int max_val) {
    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    if (!nodes) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_nodes; ++i) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(nodes[j]);
            free(nodes);
            return NULL;
        }
        nodes[i]->value = rand() % (max_val - min_val + 1) + min_val;

        // Allocate string from shared pool
        nodes[i]->str = (char*)malloc(20); // Assuming strings are up to 19 characters long
        if (!nodes[i]->str) {
            // Handle memory allocation failure
            for (int j = 0; j <= i; ++j) {
                free(nodes[j]->str);
                free(nodes[j]);
            }
            free(nodes);
            return NULL;
        }
    }

    return nodes;
}

void free_node_array(Node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; ++i) {
        free(nodes[i]->str);
        free(nodes[i]);
    }
    free(nodes);
}

int main() {
    int num_nodes = 500;
    Node** nodes = create_node_array(num_nodes, 1, 1000);

