    int EPS_BEARER_ID;
    int EMM_TAG;
    // Add other fields as needed
} LTE_MME_CONFIG_T;

LTE_MME_CONFIG_STATUS initializeLTEConfig(LTE_MME_CONFIG_T **configArray, int *arraySize, int mmeId, int bearerId, int emmTag) {
    if (bearerId >= arraySize) {
        return LTE_MME_CONFIG_STATUS_NO_MORE_BEARERS;
    }

    if (*configArray == NULL) {
        *arraySize = 10; // Initial size
        *configArray = malloc(*arraySize * sizeof(LTE_MME_CONFIG_T));
        if (*configArray == NULL) {
            return LTE_MME_CONFIG_STATUS_OUT_OF_MEMORY;
        }
    } else if (bearerId >= *arraySize) {
        int newSize = *arraySize * 2; // Double the size
        LTE_MME_CONFIG_T *newArray = realloc(*configArray, newSize * sizeof(LTE_MME_CONFIG_T));
        if (newArray == NULL) {
            return LTE_MME_CONFIG_STATUS_OUT_OF_MEMORY;
        }
        *configArray = newArray;
        *arraySize = newSize;
    }

    (*configArray)[bearerId].MME_ID = mmeId;
    (*configArray)[bearerId].EPS_BEARER_ID = bearerId;
    (*configArray)[bearerId].EMM_TAG = emmTag;

    return LTE_MME_CONFIG_STATUS_SUCCESS;
}

int main() {
    srand(time(NULL));
    LTE_MME_CONFIG_T *configArray = NULL;
    int arraySize = 0;

    for (int i = 0; i < 1000; i++) {
        int mmeId = rand() % 10 + 1;
        int bearerId = rand() % 1000;
        int emmTag = rand() % 100 + 1;

        LTE_MME_CONFIG_STATUS status = initializeLTEConfig(&configArray, &arraySize, mmeId, bearerId, emmTag);
        if (status != LTE_MME_CONFIG_STATUS_SUCCESS) {
            printf("Failed to initialize config: %d\n", status);
            break;
        }
    }

    free(configArray);

    return 0;
}
