#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONFIGS 100000
#define HASH_TABLE_SIZE 131072 // Prime number to reduce collisions

typedef enum {
    MOBILITY_STATE_IDLE,
    MOBILITY_STATE_CONNECTED,
    MOBILITY_STATE_TRANSITIONING
} MobilityState;

typedef struct LTE_MME_CONFIG_T {
    int MME_ID;
    int EPS_BEARER_ID;
    MobilityState mobility_state;
} LTE_MME_CONFIG_T;

typedef struct HashEntry {
    int EPS_BEARER_ID;
    pthread_mutex_t lock;
    struct HashEntry *next;
} HashEntry;

HashEntry *hash_table[HASH_TABLE_SIZE];

pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash_function(int EPS_BEARER_ID) {
    return EPS_BEARER_ID % HASH_TABLE_SIZE;
}

int insert_into_hash_table(int EPS_BEARER_ID) {
    unsigned int index = hash_function(EPS_BEARER_ID);
    pthread_mutex_lock(&hash_table_lock);
    HashEntry *entry = hash_table[index];
    while (entry != NULL) {
        if (entry->EPS_BEARER_ID == EPS_BEARER_ID) {
            pthread_mutex_unlock(&hash_table_lock);
            return -1; // Duplicate ID
        }
        entry = entry->next;
    }
    HashEntry *new_entry = malloc(sizeof(HashEntry));
    new_entry->EPS_BEARER_ID = EPS_BEARER_ID;
    new_entry->next = hash_table[index];
    hash_table[index] = new_entry;
    pthread_mutex_unlock(&hash_table_lock);
    return 0; // Success
}

LTE_MME_CONFIG_T *initialize_config_array(int capacity) {
    LTE_MME_CONFIG_T *config_array = malloc(capacity * sizeof(LTE_MME_CONFIG_T));
    if (config_array == NULL) {
        // Log error: Memory allocation failed
        return NULL;
    }
    for (int i = 0; i < capacity; i++) {
        int EPS_BEARER_ID;
        do {
            EPS_BEARER_ID = rand() % MAX_CONFIGS; // Random EPS_BEARER_ID generation
        } while (insert_into_hash_table(EPS_BEARER_ID) == -1); // Handle duplicates
        config_array[i].MME_ID = i + 1; // Unique MME_ID
        config_array[i].EPS_BEARER_ID = EPS_BEARER_ID;
        config_array[i].mobility_state = (MobilityState)(rand() % 3); // Random mobility state
    }
    return config_array;
}

void free_config_array(LTE_MME_CONFIG_T *config_array, int capacity) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        HashEntry *entry = hash_table[i];
        while (entry != NULL) {
            HashEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
    free(config_array);
}
