    if (it != vec.end()) {
        *it = replaceValue;
    } else {
        vec.push_back(appendValue);
    }
}

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        std::cerr << "Memory allocation failed!" << std::endl;
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long* initializeLongArray(size_t initialSize, double scalingFactor) {
    long* array = static_cast<long*>(allocateMemory(initialSize * sizeof(long)));
    for (size_t i = 0; i < initialSize; ++i) {
        array[i] = static_cast<long>(rand() * scalingFactor);
    }
    return array;
}

int* initializeIntArray(size_t initialSize, int rangeStart, int rangeEnd) {
    int* array = static_cast<int*>(allocateMemory(initialSize * sizeof(int)));
    for (size_t i = 0; i < initialSize; ++i) {
        array[i] = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }
    return array;
}

Record* initializeRecordArray(size_t initialSize, int valueRangeStart, int valueRangeEnd, double scalingFactor) {
    Record* array = static_cast<Record*>(allocateMemory(initialSize * sizeof(Record)));
    for (size_t i = 0; i < initialSize; ++i) {
        array[i].value = rand() % (valueRangeEnd - valueRangeStart + 1) + valueRangeStart;
        array[i].dataSize = static_cast<size_t>(rand() * scalingFactor);
        array[i].lastAccessed = time(nullptr);
    }
    return array;
}

void freeMemory(void* ptr) {
    free(ptr);
}
