class GameCharacter {
public:
    void useRandomAttack(std::forward_list<std::string>& attacks, const std::string& targetAttack, const std::string& newAttack, int cooldown) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (std::find(attacks.begin(), attacks.end(), targetAttack) != attacks.end()) {
            // Target attack found, use a random predefined attack
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 1);
            int choice = dis(gen);
            if (choice == 0) {
                std::cout << "Using Attack A" << std::endl;
            } else {
                std::cout << "Using Attack B" << std::endl;
            }
        } else {
            // Target attack not found, add new attack to the list
            attacks.push_front(newAttack);
            std::cout << "New attack added: " << newAttack << std::endl;
        }

        // Simulate cooldown period asynchronously
        std::async(std::launch::async, [this, &attacks, cooldown]() {
            std::this_thread::sleep_for(std::chrono::seconds(cooldown));
            std::lock_guard<std::mutex> lock(mutex_);
            // Reset cooldown logic here if needed
        });
    }

private:
    std::mutex mutex_;
};

int main() {
    GameCharacter character;
    std::forward_list<std::string> attacks = {"Fireball", "Ice Lance"};
    character.useRandomAttack(attacks, "Lightning Bolt", "Thunder Shock", 5);
    return 0;
}
