#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct SensorData {
    time_t timestamp;
    char *label;
} SensorData;

typedef struct SensorCollection {
    SensorData **sensors;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SensorCollection;

SensorCollection* create_sensor_collection() {
    SensorCollection *collection = (SensorCollection*)malloc(sizeof(SensorCollection));
    if (!collection) return NULL;

    collection->sensors = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_sensor_collection(SensorCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->sensors[i]->label);
        free(collection->sensors[i]);
    }
    free(collection->sensors);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_sensor(SensorCollection *collection, time_t timestamp, const char *label) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        SensorData **new_sensors = realloc(collection->sensors, new_capacity * sizeof(SensorData*));
        if (!new_sensors) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Allocation failed
        }
        collection->sensors = new_sensors;
        collection->capacity = new_capacity;
    }

    SensorData *sensor = (SensorData*)malloc(sizeof(SensorData));
    if (!sensor) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Allocation failed
    }

    sensor->timestamp = timestamp;
    sensor->label = strdup(label);
    if (!sensor->label) {
        free(sensor);
        pthread_mutex_unlock(&collection->lock);
        return -1; // Allocation failed
    }

    collection->sensors[collection->count++] = sensor;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_sensor(SensorCollection *collection, size_t index, time_t timestamp, const char *label) {
    if (index >= collection->count) return -1; // Invalid index

    pthread_mutex_lock(&collection->lock);

    free(collection->sensors[index]->label);
    collection->sensors[index]->timestamp = timestamp;
    collection->sensors[index]->label = strdup(label);
    if (!collection->sensors[index]->label) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Allocation failed
    }

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

SensorData* get_sensor_by_index(SensorCollection *collection, size_t index) {
