    }

    long* offsets = malloc(sizeof(long) * num_records);
    int* keys = malloc(sizeof(int) * num_records);
    record* records = malloc(sizeof(record) * num_records);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    return records;
}

void cleanup_records(record* records, int num_records) {
    free(records);
}
