    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    srand(time(NULL)); // Seed the random number generator once

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100 + 1; // Random value between 1 and 100
        records[i].key = &keys[i];
    }

    return records;
}

void print_records(record* records, int num_records) {
    if (!records || num_records <= 0) return;

    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: Value = %d, Key = %d\n", i, records[i].value, *records[i].key);
    }
}

void free_records(record* records, int num_records) {
    if (!records || num_records <= 0) return;

    for (int i = 0; i < num_records; ++i) {
        // No need to free individual keys as they are not dynamically allocated
    }

    free(records);
}

int main() {
    const int num_records = 10;
    int keys[num_records];
    long offsets[num_records];

    for (int i = 0; i < num_records; ++i) {
        keys[i] = i * 10;
        offsets[i] = i * 100L;
