// Define packet structure
typedef struct {
    time_t timestamp;
    size_t size;
    char source_ip[16];
} Packet;

// Define queue node structure
typedef struct QueueNode {
    Packet data;
    struct QueueNode* next;
} QueueNode;

// Define queue structure
typedef struct {
    QueueNode* front;
    QueueNode* rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConcurrentQueue;

// Initialize concurrent queue
void init_queue(ConcurrentQueue* q) {
    q->front = q->rear = NULL;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
}

// Enqueue packet into the queue
void enqueue(ConcurrentQueue* q, Packet data) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&q->mutex);
    if (q->rear == NULL) {
        q->front = q->rear = new_node;
    } else {
        q->rear->next = new_node;
        q->rear = new_node;
    }
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
}

// Dequeue packet from the queue
Packet dequeue(ConcurrentQueue* q) {
    Packet data;
    pthread_mutex_lock(&q->mutex);
    while (q->front == NULL) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    QueueNode* temp = q->front;
    data = temp->data;
    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    pthread_mutex_unlock(&q->mutex);
    return data;
}

