packet_manager* create_packet_manager(size_t num_packets, unsigned long min_time, unsigned long max_time, size_t max_memory_kb, void (*metadata_source)(packet_header *)) {
    if (num_packets <= 0 || min_time >= max_time) {
        return NULL;
    }

    size_t total_size = num_packets * sizeof(packet_header);
    if (total_size > max_memory_kb * 1024) {
        return NULL;
    }

    packet_manager *manager = malloc(sizeof(packet_manager));
    if (!manager) {
        return NULL;
    }

    manager->headers = malloc(total_size);
    if (!manager->headers) {
        free(manager);
        return NULL;
    }

    pthread_rwlock_init(&manager->lock, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < num_packets; ++i) {
        manager->headers[i].timestamp = min_time + rand() % (max_time - min_time + 1);
        if (metadata_source) {
            metadata_source(&manager->headers[i]);
        }
    }

    return manager;
}

void destroy_packet_manager(packet_manager *manager) {
    if (!manager) {
        return;
    }

    pthread_rwlock_destroy(&manager->lock);
    free(manager->headers);
    free(manager);
}

packet_header* get_packet_header(packet_manager *manager, size_t index) {
    if (!manager || index >= manager->num_packets) {
        return NULL;
    }

    pthread_rwlock_rdlock(&manager->lock);
    packet_header *header = &manager->headers[index];
    pthread_rwlock_unlock(&manager->lock);

    return header;
}

void trim_packet_manager(packet_manager *manager, unsigned long current_time, size_t max_age_seconds) {
