import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {

    private static final String QUEUE_NAME = "md5_queue";
    private static final int MAX_CONCURRENT_THREADS = 10;
    private static final long CACHE_EXPIRY_TIME = TimeUnit.HOURS.toMillis(1);
    private static final long MAX_INPUT_AGE = TimeUnit.MINUTES.toMillis(30);

    private ExecutorService executorService;
    private LinkedBlockingQueue<String> queue;
    private Cache cache;

    public MD5Hasher() {
        this.queue = new LinkedBlockingQueue<>();
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);
        this.cache = new Cache(CACHE_EXPIRY_TIME, MAX_INPUT_AGE);
        startProcessing();
    }

    private void startProcessing() {
        for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
            executorService.submit(() -> processQueue());
        }
    }

    public String hashInputs(String[] inputs) throws InterruptedException {
        StringBuilder result = new StringBuilder();
        for (String input : inputs) {
            if (input == null || input.isEmpty()) continue;
            String cachedHash = cache.get(input);
            if (cachedHash != null) {
                result.append(cachedHash).append(",");
            } else {
                queue.put(input);
            }
        }
        return result.toString();
    }

    private void processQueue() {
        while (true) {
            try {
                String input = queue.take();
                String hash = computeMD5(input);
                cache.put(input, hash);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    private static class Cache {
        private final java.util.Map<String, String> cache;
        private final long expiryTime;
        private final long maxInputAge;

        public Cache(long expiryTime, long maxInputAge) {
            this.cache = new java.util.concurrent.ConcurrentHashMap<>();
            this.expiryTime = expiryTime;
            this.maxInputAge = maxInputAge;
        }

        public String get(String key) {
            if (cache.containsKey(key)) {
                return cache.get(key);
            }
            return null;
        }

        public void put(String key, String value) {
            long now = System.currentTimeMillis();
            cache.put(key, value + "|" + now);
        }

        public void invalidate() {
            long now = System.currentTimeMillis();
            cache.entrySet().removeIf(entry -> (now - Long.parseLong(entry.getValue().split("\\|")[1])) > expiryTime);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        MD5Hasher hasher = new MD5Hasher();
        String[] inputs = {"input1", "input2", null, "input3"};
        String result = hasher.hashInputs(inputs);
        System.out.println(result);
    }
}
