#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct Record {
    long offset;
    int key;
    double value;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t size;
    size_t count;
} HashTable;

HashTable* create_hash_table(size_t initial_size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->buckets = (Record**)calloc(initial_size, sizeof(Record*));
    ht->size = initial_size;
    ht->count = 0;
    return ht;
}

void resize_hash_table(HashTable *ht) {
    size_t new_size = ht->size * 2;
    Record **new_buckets = (Record**)calloc(new_size, sizeof(Record*));

    for (size_t i = 0; i < ht->size; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            size_t new_index = current->key % new_size;
            Record *next = current->next;
            current->next = new_buckets[new_index];
            new_buckets[new_index] = current;
            current = next;
        }
    }

    free(ht->buckets);
    ht->buckets = new_buckets;
    ht->size = new_size;
}

void insert_record(HashTable *ht, Record *record) {
    if (ht->count >= ht->size * 0.75) {
        resize_hash_table(ht);
    }

    size_t index = record->key % ht->size;
    record->next = ht->buckets[index];
    ht->buckets[index] = record;
    ++ht->count;
}

Record* find_record(HashTable *ht, int key) {
    size_t index = key % ht->size;
    Record *current = ht->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void free_records(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

int main() {
    srand(time(NULL));
    HashTable *ht = create_hash_table(10);

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        Record *record = (Record*)malloc(sizeof(Record));
        record->offset = i;
        record->key = rand() % 1000;
        record->value = ((double)rand()) / RAND_MAX;
        insert_record(ht, record);
    }

    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        Record *record = find_record(ht, i);
        if (record != NULL) {
            printf("Key: %d, Value: %f\n", record->key, record->value);
        }
    }

    free_records(ht);

    return 0;
}
