#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct SensorData {
    time_t timestamp;
    char* label;
    double metrics[10]; // Example: 10 generic metric fields
} SensorData;

typedef struct SensorCollection {
    SensorData** sensors;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SensorCollection;

SensorCollection* create_sensor_collection() {
    SensorCollection* collection = (SensorCollection*)malloc(sizeof(SensorCollection));
    if (!collection) return NULL;

    collection->sensors = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_sensor_collection(SensorCollection* collection) {
    if (collection) {
        for (size_t i = 0; i < collection->count; ++i) {
            free(collection->sensors[i]->label);
            free(collection->sensors[i]);
        }
        free(collection->sensors);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_sensor(SensorCollection* collection, const char* label, double* metrics, size_t metric_count) {
    if (!collection || !label || !metrics || metric_count > 10) return -1;

    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 4;
        SensorData** new_sensors = (SensorData**)realloc(collection->sensors, new_capacity * sizeof(SensorData*));
        if (!new_sensors) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->sensors = new_sensors;
        collection->capacity = new_capacity;
    }

    SensorData* sensor = (SensorData*)malloc(sizeof(SensorData));
    if (!sensor) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    sensor->timestamp = time(NULL);
    sensor->label = strdup(label);
    memcpy(sensor->metrics, metrics, metric_count * sizeof(double));

    collection->sensors[collection->count++] = sensor;

    pthread_mutex_unlock(&collection->lock);

    return 0;
}

// Additional functions for updating and retrieving sensor data can be implemented here
```

