#define MAX_FILES 100
#define MAX_CONCURRENT_OPS 5
#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1GB

typedef struct {
    char *filename;
    int line_number;
    double average;
} FileLine;

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(ip_address, (char*)addr);
    }

    freeaddrinfo(res); // all done with this structure
    return 0;
}

void *process_file(void *arg) {
    FileLine *file_line = (FileLine *)arg;
    FILE *fp = fopen(file_line->filename, "r");
    if (!fp) {
        perror("Error opening file");
        return NULL;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, fp)) != -1) {
        // Process each line here
        printf("%s", line);
    }

    free(line);
    fclose(fp);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> <file2> ... <fileN>\n", argv[0]);
        return 1;
    }

    pthread_t threads[MAX_FILES];
    int num_files = argc - 1;

    for (int i = 0; i < num_files; i++) {
        FileLine *file_line = malloc(sizeof(FileLine));
        file_line->filename = argv[i + 1];
        if (pthread_create(&threads[i], NULL, process_file, file_line) != 0) {
            perror("Error creating thread");
            free(file_line);
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
