record* create_records(int min_val, int max_val, size_t num_records, size_t max_string_size) {
    record *records = (record*)custom_malloc(num_records * sizeof(record));
    long *offsets = (long*)custom_malloc(num_records * sizeof(long));
    int *keys = (int*)custom_malloc(num_records * sizeof(int));

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        keys[i] = min_val + rand() % (max_val - min_val + 1);
        records[i].value = keys[i];
        records[i].size = max_string_size;
        records[i].buffer = (char*)custom_malloc(max_string_size * sizeof(char));
    }

    return records;
}

void free_records(record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].buffer);
    }
    free(records);
}

