// Define a custom hashing function to generate version numbers based on filenames
function hashFilename(filename) {
    let hash = 0;
    for (let i = 0; i < filename.length; i++) {
        hash = ((hash << 5) - hash) + filename.charCodeAt(i);
        hash |= 0; // Convert to 32bit integer
    }
    return Math.abs(hash).toString(16);
}

// Function to load a single JavaScript file with versioning and error handling
async function loadScript(url, retries = 0) {
    const maxRetries = 5;
    const backoffFactor = 2;

    try {
        // Attempt to fetch the script
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Failed to load ${url}`);
        }

        // Create a new script element and append it to the document
        const script = document.createElement('script');
        script.src = url;
        document.head.appendChild(script);

        return new Promise((resolve, reject) => {
            script.onload = resolve;
            script.onerror = () => {
                document.head.removeChild(script);
                reject(new Error(`Failed to load ${url}`));
            };
        });
    } catch (error) {
        if (retries < maxRetries) {
            const delay = backoffFactor ** retries * 100; // Exponential backoff
            console.warn(`Loading ${url} failed. Retrying in ${delay}ms...`);
            return new Promise(resolve => setTimeout(() => resolve(loadScript(url, retries + 1)), delay));
        } else {
            throw error;
        }
    }
}

// Function to load multiple scripts in a predefined sequence
async function loadScripts(urls) {
    for (const url of urls) {
        try {
            const version = hashFilename(url);
            const timestamp = new Date().getTime();
            const modifiedUrl = `${url.split('.').slice(0, -1).join('.')}-${version}-${timestamp}.js`;

            await loadScript(modifiedUrl);
            console.log(`Successfully loaded ${modifiedUrl}`);
        } catch (error) {
            console.error(`Failed to load ${url}:`, error);
            // Fallback mechanism for default extension handling
            try {
                await loadScript(url);
                console.log(`Successfully loaded fallback version of ${url}`);
            } catch (fallbackError) {
                console.error(`Failed to load fallback version of ${url}:`, fallbackError);
            }
        }
    }
}

// Example usage
const scriptUrls = [
    'path/to/script1.js',
    'path/to/script2.js',
    'path/to/script3.js'
];

loadScripts(scriptUrls).then(() => {
    console.log('All scripts loaded successfully');
}).catch(error => {
    console.error('Failed to load one or more scripts:', error);
});
```

This code snippet provides a basic implementation of the described functionality. It includes a custom hashing function, a script loading function with retry logic and exponential backoff, and a function to load multiple scripts in sequence. The example usage demonstrates how to use these functions to load a list of JavaScript files."]

