typedef struct SensorReading {
    float temperature;
    double humidity;
    char* description;
    char* location;
    int status;
} SensorReading;

typedef struct SensorCollection {
    SensorReading** readings;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SensorCollection;

SensorCollection* create_sensor_collection(size_t initial_capacity) {
    SensorCollection* collection = (SensorCollection*)malloc(sizeof(SensorCollection));
    if (!collection) return NULL;

    collection->readings = (SensorReading**)malloc(initial_capacity * sizeof(SensorReading*));
    if (!collection->readings) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_sensor_collection(SensorCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->readings[i]->description);
        free(collection->readings[i]->location);
        free(collection->readings[i]);
    }
    free(collection->readings);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_sensor_reading(SensorCollection* collection, float temperature, double humidity, const char* description, const char* location, int status) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        SensorReading** new_readings = (SensorReading**)realloc(collection->readings, new_capacity * sizeof(SensorReading*));
        if (!new_readings) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->readings = new_readings;
        collection->capacity = new_capacity;
    }

    SensorReading* reading = (SensorReading*)malloc(sizeof(SensorReading));
    if (!reading) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }

    reading->temperature = temperature;
    reading->humidity = humidity;
    reading->description = strdup(description);
    reading->location = strdup(location);
    reading->status = status;

    collection->readings[collection->count++] = reading;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

int update_sensor_reading(SensorCollection* collection, size_t index, float temperature, double humidity, const char* description, const char* location, int status) {
    if (index >= collection->count) return -1; // Invalid index

    pthread_mutex_lock(&collection->lock);

    SensorReading* reading = collection->readings[index];
    reading->temperature = temperature;
    reading->humidity = humidity;
    free(reading->description);
    reading->description = strdup(description);
    free(reading->location);
    reading->location = strdup(location);
    reading->status = status;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

void print_sensor_readings(SensorCollection* collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        SensorReading* reading = collection->readings[i];
        printf("Sensor %zu: Temp=%.2f, Humidity=%.2f, Desc=%s, Loc=%s, Status=%d\n",
               i, reading->temperature, reading->humidity, reading->description, reading->location, reading->status);
    }

    pthread_mutex_unlock(&collection->lock);
}
