#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    float value;
    char identifier;
    size_t size;
} element;

typedef struct {
    element* elements;
    size_t count;
    pthread_mutex_t mutex;
} element_collection;

element* create_element(float value, char identifier, size_t size) {
    element* e = (element*)malloc(sizeof(element));
    if (!e) return NULL;
    e->value = value;
    e->identifier = identifier;
    e->size = size;
    return e;
}

int initialize_collection(element_collection* collection, size_t count, float min_float, float max_float, char min_char, char max_char, size_t* sizes, size_t sizes_count) {
    pthread_mutex_init(&collection->mutex, NULL);
    collection->elements = (element*)malloc(count * sizeof(element));
    if (!collection->elements) {
        pthread_mutex_destroy(&collection->mutex);
        return -1;
    }
    collection->count = count;

    for (size_t i = 0; i < count; ++i) {
        float value = min_float + (max_float - min_float) * ((float)rand() / RAND_MAX);
        char identifier = min_char + rand() % (max_char - min_char + 1);
        size_t size;
        if (i < sizes_count) {
            size = sizes[i];
        } else {
            size = min_size + (max_size - min_size) * ((float)rand() / RAND_MAX);
        }
        element* e = create_element(value, identifier, size);
        if (!e) {
            for (size_t j = 0; j < i; ++j) {
                free(collection->elements[j].identifier);
                free(collection->elements[j].data);
            }
            free(collection->elements);
            pthread_mutex_destroy(&collection->mutex);
            return -1;
        }
        collection->elements[i] = *e;
        free(e);
    }

    return 0;
}

void destroy_collection(element_collection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->elements[i].identifier);
        free(collection->elements[i].data);
    }
    free(collection->elements);
    pthread_mutex_destroy(&collection->mutex);
}

void* thread_function(void* arg) {
    element_collection* collection = (element_collection*)arg;
    // Perform operations on the collection
    return NULL;
}

int main() {
    element_collection collection;
    size_t sizes[] = {1024, 2048, 3072};
    if (initialize_collection(&collection, 5, -1.0f, 1.0f, 'a', 'z', sizes, 3) != 0) {
        fprintf(stderr, "Failed to initialize collection\n");
        return 1;
    }

    pthread_t threads[4];
    for (size_t i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &collection) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (size_t i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_collection(&collection);

    return 0;
}
