#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <random>
#include <chrono>
#include <cstring>
#include <openssl/md5.h>

struct Element {
    double value;
    enum class Status { ACTIVE, INACTIVE, DELETED };
    Status status;
    float* ptrFloat;
};

class DataProcessor {
public:
    DataProcessor(size_t floatSize, size_t elementSize, size_t charSize)
        : floatData(new float[floatSize]), elementData(new Element[elementSize]), charData(new char[charSize]) {}

    ~DataProcessor() {
        delete[] floatData;
        delete[] elementData;
        delete[] charData;
    }

    void initializeStreams(size_t numElements) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(0.0, 1.0);

        for (size_t i = 0; i < numElements; ++i) {
            elementData[i].value = dis(gen);
            elementData[i].status = static_cast<Element::Status>(dis(gen) * 3);
            elementData[i].ptrFloat = &floatData[i];
        }
    }

    void sortElements() {
        std::sort(elementData, elementData + numElements, [](const Element& a, const Element& b) {
            return a.status < b.status;
        });
    }

private:
    float* floatData;
    Element* elementData;
    char* charData;
    size_t numElements;
};

int main() {
    DataProcessor processor(1000, 1000, 1000);
    processor.initializeStreams(1000);
    processor.sortElements();
    return 0;
}
