<?php
function update_password($username, $newPassword) {
    $host = 'localhost';
    $dbname = 'your_database';
    $user = 'your_username';
    $pass = 'your_password';

    try {
        $pdo = new PDO("mysql:host=$host;dbname=$dbname", $user, $pass);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Check password complexity
        if (strlen($newPassword) < 8 || !preg_match('/[a-z]/', $newPassword) || !preg_match('/[A-Z]/', $newPassword) || !preg_match('/\d/', $newPassword)) {
            throw new Exception("Password must be at least 8 characters long and include at least one lowercase, one uppercase, and one digit.");
        }

        // Update password
        $stmt = $pdo->prepare("UPDATE users SET password = :password WHERE username = :username");
        $stmt->bindParam(':password', password_hash($newPassword, PASSWORD_DEFAULT));
        $stmt->bindParam(':username', $username);
        $stmt->execute();

        echo "Password updated successfully.";
    } catch (PDOException $e) {
        echo "Database error: " . $e->getMessage();
    }
}
?>
