#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the struct element
typedef enum { STATUS_OK, STATUS_WARNING, STATUS_ERROR } Status;
typedef struct {
    double value;
    Status status;
    float *ptr_float;
    int index;
    long long timestamp;
} Element;

// Function to initialize arrays and elements
void initialize_arrays(int size) {
    // Allocate memory for each array
    float *float_array = (float *)malloc(size * sizeof(float));
    Element *element_array = (Element *)malloc(size * sizeof(Element));
    char **char_array = (char **)malloc(size * sizeof(char *));
    int *int_array = (int *)malloc(size * sizeof(int));
    long long *long_long_array = (long long *)malloc(size * sizeof(long long));

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        float_array[i] = 0.0f;
        element_array[i].value = 0.0;
        element_array[i].status = STATUS_OK;
        element_array[i].ptr_float = &float_array[i];
        element_array[i].index = i;
        element_array[i].timestamp = time(NULL);
        char_array[i] = (char *)malloc(256 * sizeof(char));
        int_array[i] = 0;
        long_long_array[i] = 0LL;
    }

    // Set random values for double fields based on enum type
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        switch (element_array[i].status) {
            case STATUS_OK:
                element_array[i].value = ((double)rand() / RAND_MAX) * 10.0;
                break;
            case STATUS_WARNING:
                element_array[i].value = ((double)rand() / RAND_MAX) * 50.0;
                break;
            case STATUS_ERROR:
                element_array[i].value = ((double)rand() / RAND_MAX) * 100.0;
                break;
        }
    }

    // Sort arrays based on enum type and int index
    qsort(element_array, size, sizeof(Element), compare_elements);

    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(char_array[i]);
    }
    free(float_array);
    free(element_array);
    free(char_array);
    free(int_array);
    free(long_long_array);
}

// Comparison function for qsort
int compare_elements(const void *a, const void *b) {
    Element *elem_a = (Element *)a;
    Element *elem_b = (Element *)b;

    if (elem_a->status != elem_b->status) {
        return (elem_a->status - elem_b->status);
    }
    return (elem_a->index - elem_b->index);
}

int main() {
    initialize_arrays(5);
    return 0;
}
