#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TEMP 100.0
#define MIN_TEMP -50.0

typedef struct {
    time_t timestamp;
    float temperature;
    char* temp_str;
} sensor_data;

typedef struct hash_node {
    sensor_data data;
    struct hash_node* next;
} hash_node;

typedef struct {
    hash_node** buckets;
    size_t size;
    size_t count;
} hash_table;

hash_node* create_hash_node(sensor_data data) {
    hash_node* node = (hash_node*)malloc(sizeof(hash_node));
    if (node == NULL) {
        perror("Failed to allocate memory for hash node");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

hash_table* create_hash_table(size_t size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (table == NULL) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->buckets = (hash_node**)calloc(size, sizeof(hash_node*));
    if (table->buckets == NULL) {
        perror("Failed to allocate memory for hash table buckets");
        free(table);
        exit(EXIT_FAILURE);
    }
    table->size = size;
    table->count = 0;
    return table;
}

void insert_into_hash_table(hash_table* table, sensor_data data) {
    size_t index = (size_t)data.timestamp % table->size;
    hash_node* node = create_hash_node(data);
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->count++;
}

sensor_data read_temperature_from_file(FILE* file) {
    sensor_data data;
    if (fscanf(file, "%ld %f", &data.timestamp, &data.temperature) != 2) {
        fprintf(stderr, "Error reading temperature from file\n");
        exit(EXIT_FAILURE);
    }
    data.temp_str = (char*)malloc(10 * sizeof(char));
    if (data.temp_str == NULL) {
        perror("Failed to allocate memory for temperature string");
        exit(EXIT_FAILURE);
    }
    snprintf(data.temp_str, 10, "%.2f", data.temperature);
    return data;
}

void process_sensor_data(const char* filename, float min_temp, float max_temp) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    hash_table* table = create_hash_table(1024);

    sensor_data data;
    while ((data = read_temperature_from_file(file)).temperature != EOF) {
        insert_into_hash_table(table, data);
    }

    fclose(file);
    // Further processing can be done here

    for (size_t i = 0; i < table->size; i++) {
        hash_node* node = table->buckets[i];
        while (node != NULL) {
            free(node->data.temp_str);
            hash_node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->buckets);
    free(table);
}

int main() {
    process_sensor_data("sensor_data.txt", MIN_TEMP, MAX_TEMP);
    return 0;
}
