#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct entry {
    char *key;
    double value;
    struct entry *next;
} Entry;

typedef struct hash_table {
    Entry **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

size_t hash(const char *key, size_t capacity) {
    size_t hash = 0;
    while (*key) {
        hash = (hash * 31 + *key++) % capacity;
    }
    return hash;
}

HashTable* create_hash_table() {
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->buckets = calloc(INITIAL_CAPACITY, sizeof(Entry *));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    ht->capacity = INITIAL_CAPACITY;
    ht->size = 0;
    pthread_mutex_init(&ht->lock, NULL);

    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        Entry *entry = ht->buckets[i];
        while (entry) {
            Entry *next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int add_entry(HashTable *ht, const char *key, double value) {
    pthread_mutex_lock(&ht->lock);

    size_t index = hash(key, ht->capacity);
    Entry *entry = ht->buckets[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            entry->value = value;
            pthread_mutex_unlock(&ht->lock);
            return 1; // Key already exists
        }
        entry = entry->next;
    }

    Entry *new_entry = malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&ht->lock);
        return -1; // Memory allocation failed
    }

    new_entry->key = strdup(key);
    if (!new_entry->key) {
        free(new_entry);
        pthread_mutex_unlock(&ht->lock);
        return -1; // Memory allocation failed
    }
    new_entry->value = value;
    new_entry->next = ht->buckets[index];
    ht->buckets[index] = new_entry;

    ++ht->size;

    if (ht->size >= ht->capacity * 0.75) {
        size_t new_capacity = ht->capacity * GROWTH_FACTOR;
        Entry **new_buckets = calloc(new_capacity, sizeof(Entry *));
        if (!new_buckets) {
            pthread_mutex_unlock(&ht->lock);
            return -1; // Memory allocation failed
        }

        for (size_t i = 0; i < ht->capacity; ++i) {
            Entry *entry = ht->buckets[i];
            while (entry) {
                size_t new_index = hash(entry->key, new_capacity);
                Entry *next = entry->next;
                entry->next = new_buckets[new_index];
                new_buckets[new_index] = entry;
                entry = next;
            }
        }

        free(ht->buckets);
        ht->buckets = new_buckets;
        ht->capacity = new_capacity;
    }

    pthread_mutex_unlock(&ht->lock);
    return 0; // Entry added successfully
}

double get_entry(HashTable *ht, const char *key) {
    pthread_mutex_lock(&ht->lock);

    size_t index = hash(key, ht->capacity);
    Entry *entry = ht->buckets[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            double value = entry->value;
            pthread_mutex_unlock(&ht->lock);
            return value; // Key found
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&ht->lock);
    return -1.0; // Key not found
}
