#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Transaction {
    time_t timestamp;
    int id;
    double amount;
} Transaction;

typedef struct Node {
    Transaction data;
    struct Node *left, *right;
} Node;

Node* createNode(Transaction data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

Node* insert(Node* node, Transaction data) {
    if (node == NULL)
        return createNode(data);

    if (data.timestamp < node->data.timestamp)
        node->left = insert(node->left, data);
    else if (data.timestamp > node->data.timestamp)
        node->right = insert(node->right, data);

    return node;
}

Node* search(Node* root, int id) {
    if (root == NULL || root->data.id == id)
        return root;

    if (id < root->data.id)
        return search(root->left, id);
    else
        return search(root->right, id);
}

void inorderTraversal(Node* root) {
    if (root != NULL) {
        inorderTraversal(root->left);
        printf("Timestamp: %ld, ID: %d, Amount: %.2f\n", root->data.timestamp, root->data.id, root->data.amount);
        inorderTraversal(root->right);
    }
}

int main() {
    Node* root = NULL;
    Transaction transactions[] = {
        {time(NULL), 101, 50.0},
        {time(NULL) + 3600, 102, 75.0},
        {time(NULL) + 7200, 103, 100.0}
    };

    for (int i = 0; i < 3; i++) {
        root = insert(root, transactions[i]);
    }

    inorderTraversal(root);

    Node* result = search(root, 102);
    if (result != NULL) {
        printf("Found transaction: Timestamp: %ld, ID: %d, Amount: %.2f\n", result->data.timestamp, result->data.id, result->data.amount);
    } else {
        printf("Transaction not found\n");
    }

    return 0;
}
