#include <string.h>

#define MAX_NAME_LENGTH 256

typedef struct {
    int id;
    float price;
    char* name;
} Product;

int processProducts(const char* filename, float scale_factor) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    // Estimate the number of products (simple heuristic)
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    int estimated_count = size / 256; // Simplified estimation
    Product* products = malloc(estimated_count * sizeof(Product));
    if (!products) {
        perror("Failed to allocate memory");
        fclose(file);
        return -1;
    }

    char line[4096];
    int count = 0;

    while (fgets(line, sizeof(line), file)) {
        // Simulate parsing and error handling
        char* token = strtok(line, ",");
        if (!token) continue; // Skip empty lines

        products[count].id = atoi(token);
        token = strtok(NULL, ",");
        if (token && *token != '\0') {
            products[count].price = atof(token) * scale_factor;
        } else {
            products[count].price = 0.0f; // Default price
        }

        token = strtok(NULL, ",");
        if (token && *token != '\0' && strlen(token) < MAX_NAME_LENGTH) {
            products[count].name = strdup(token);
        } else {
            products[count].name = NULL; // Handle invalid names
        }

        count++;
        if (count >= estimated_count) {
            estimated_count *= 2;
            Product* new_products = realloc(products, estimated_count * sizeof(Product));
            if (!new_products) {
                perror("Failed to reallocate memory");
                free(products);
                fclose(file);
                return -1;
            }
            products = new_products;
        }
    }

    fclose(file);

    // Free allocated resources
    for (int i = 0; i < count; i++) {
        if (products[i].name) {
            free(products[i].name);
        }
    }
    free(products);

    return count;
}
