typedef struct {
    long *offsets;
    int *keys;
    entry **entries;
    pthread_mutex_t mutex;
} data_structures;

data_structures* create_data_structures(int size) {
    data_structures *ds = (data_structures *)malloc(sizeof(data_structures));
    ds->offsets = (long *)malloc(size * sizeof(long));
    ds->keys = (int *)malloc(size * sizeof(int));
    ds->entries = (entry **)malloc(size * sizeof(entry *));
    for (int i = 0; i < size; i++) {
        ds->entries[i] = (entry *)malloc(sizeof(entry));
    }
    pthread_mutex_init(&ds->mutex, NULL);
    return ds;
}

void destroy_data_structures(data_structures *ds, int size) {
    for (int i = 0; i < size; i++) {
        free(ds->entries[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->entries);
    pthread_mutex_destroy(&ds->mutex);
}

void update_data(data_structures *ds, int index, long offset, int key, const char *buffer, int timestamp) {
    pthread_mutex_lock(&ds->mutex);
    ds->offsets[index] = offset;
    ds->keys[index] = key;
    strcpy(ds->entries[index]->buffer, buffer);
    ds->entries[index]->timestamp = timestamp;
    pthread_mutex_unlock(&ds->mutex);
}

void get_data(data_structures *ds, int index, long *offset, int *key, char *buffer, int *timestamp) {
    pthread_mutex_lock(&ds->mutex);
    *offset = ds->offsets[index];
    *key = ds->keys[index];
    strcpy(buffer, ds->entries[index]->buffer);
    *timestamp = ds->entries[index]->timestamp;
    pthread_mutex_unlock(&ds->mutex);
}
