record **records = NULL;
long *offsets = NULL;
int records_size = 0, offsets_size = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void resize_records(int new_size) {
    pthread_mutex_lock(&mutex);
    if (new_size > MAX_SIZE) new_size = MAX_SIZE;
    record **new_records = realloc(records, new_size * sizeof(record *));
    if (!new_records) {
        perror("Failed to resize records");
        exit(EXIT_FAILURE);
    }
    records = new_records;
    pthread_mutex_unlock(&mutex);
}

void resize_offsets(int new_size) {
    pthread_mutex_lock(&mutex);
    if (new_size > MAX_SIZE) new_size = MAX_SIZE;
    long *new_offsets = realloc(offsets, new_size * sizeof(long));
    if (!new_offsets) {
        perror("Failed to resize offsets");
        exit(EXIT_FAILURE);
    }
    offsets = new_offsets;
    pthread_mutex_unlock(&mutex);
}

void init_record(int index, int value, long offset) {
    records[index] = (record *)malloc(sizeof(record));
    records[index]->value = value;
    records[index]->offset = &offsets[offset];
    records[index]->ref_count = 1;
}

void *init_records(void *arg) {
    int range_start = *(int *)arg, range_end = *(int *)(arg + sizeof(int));
    free(arg);

    srand(time(NULL));

    for (int i = 0; i < records_size; i++) {
        init_record(i, rand() % (range_end - range_start + 1) + range_start, i);
    }

    return NULL;
}

void add_record(int value, long offset) {
    pthread_mutex_lock(&mutex);
    if (records_size >= offsets_size) resize_offsets(offsets_size * 2);
    records_size++;
    resize_records(records_size);
    init_record(records_size - 1, value, offset);
    pthread_mutex_unlock(&mutex);
}

void free_all() {
    for (int i = 0; i < records_size; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
}

int main() {
    int range_start = 1, range_end = 100;
    pthread_t thread;

    records_size = offsets_size = 100;
    records = (record **)malloc(records_size * sizeof(record *));
    offsets = (long *)malloc(offsets_size * sizeof(long));

    if (!records || !offsets) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }

    int *args = (int *)malloc(2 * sizeof(int));
    args[0] = range_start;
    args[1] = range_end;

    pthread_create(&thread, NULL, init_records, args);

    // Simulate adding records
    for (int i = 0; i < 50; i++) {
        add_record(rand() % (range_end - range_start + 1) + range_start, i);
    }

    pthread_join(thread, NULL);

    free_all();

    return 0;
}
