// Define the record structure
typedef struct {
    int identifier;
    time_t timestamp;
    char* metadata_json;
} Record;

// Function to allocate memory for records and initialize them from JSON files
Record* allocate_and_initialize_records(const char** json_files, int num_files, int interval) {
    Record* records = (Record*)malloc(num_files * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(json_files[i], "r");
        if (!file) {
            perror("Failed to open JSON file");
            free(records);
            return NULL;
        }

        // Simulate reading and parsing JSON
        char buffer[1024];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        fclose(file);

        records[i].identifier = i + 1; // Unique identifier for each record
        records[i].timestamp = time(NULL) + interval * i; // Adjusted timestamp
        records[i].metadata_json = (char*)malloc(bytes_read + 1);
        if (!records[i].metadata_json) {
            perror("Failed to allocate memory for metadata JSON");
            free(records);
            return NULL;
        }
        memcpy(records[i].metadata_json, buffer, bytes_read);
        records[i].metadata_json[bytes_read] = '\0';

        // Convert timestamp to human-readable format
        char* readable_time = ctime(&records[i].timestamp);
        printf("Record %d: Identifier=%d, Timestamp=%s Metadata=%s\n", i + 1, records[i].identifier, readable_time, records[i].metadata_json);
    }

    return records;
}

// Function to free the allocated memory for records
void free_records(Record* records, int num_files) {
    for (int i = 0; i < num_files; ++i) {
        free(records[i].metadata_json);
    }
    free(records);
}

int main() {
    const char* json_files[] = {"file1.json", "file2.json", "file3.json"};
    int num_files = sizeof(json_files) / sizeof(json_files[0]);
    int interval = 60; // Time interval adjustment in seconds

    Record* records = allocate_and_initialize_records(json_files, num_files, interval);
    if (records) {
        free_records(records, num_files);
    }

    return 0;
}
