    // Process files here
    for (int i = 0; i < config->num_files; ++i) {
        FileData file_data = { .original_filename = config->filenames[i] };
        clock_t start = clock();
        int result = apply_transformations(&file_data, config, stats);
        clock_t end = clock();

        if (result == 0) {
            pthread_mutex_lock(&stats->lock);
            ++stats->processed_files;
            stats->total_time += (double)(end - start) / CLOCKS_PER_SEC;
            pthread_mutex_unlock(&stats->lock);
        } else {
            pthread_mutex_lock(&stats->lock);
            ++stats->errors;
            pthread_mutex_unlock(&stats->lock);
        }
    }

    pthread_exit(NULL);
}

