#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct Entry {
    char* key;
    double value;
    struct Entry* next;
} Entry;

typedef struct HashTable {
    Entry** buckets;
    size_t capacity;
    size_t size;
} HashTable;

size_t hash(const char* key, size_t capacity) {
    size_t hash = 0;
    while (*key) {
        hash = (hash * 31 + *key++) % capacity;
    }
    return hash;
}

HashTable* create_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(INITIAL_CAPACITY, sizeof(Entry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = INITIAL_CAPACITY;
    table->size = 0;

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Entry* entry = table->buckets[i];
        while (entry) {
            Entry* next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    free(table);
}

int add_entry(HashTable* table, const char* key, double value) {
    if (table->size >= table->capacity * 0.75) {
        size_t new_capacity = table->capacity * GROWTH_FACTOR;
        Entry** new_buckets = realloc(table->buckets, new_capacity * sizeof(Entry*));
        if (!new_buckets) return -1;

        memset(new_buckets + table->capacity, 0, (new_capacity - table->capacity) * sizeof(Entry*));
        for (size_t i = 0; i < table->capacity; ++i) {
            Entry* entry = table->buckets[i];
            while (entry) {
                size_t new_index = hash(entry->key, new_capacity);
                Entry* next = entry->next;
                entry->next = new_buckets[new_index];
                new_buckets[new_index] = entry;
                entry = next;
            }
        }

        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }

    size_t index = hash(key, table->capacity);
    Entry* new_entry = malloc(sizeof(Entry));
    if (!new_entry) return -1;

    new_entry->key = strdup(key);
    new_entry->value = value;
    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;
    ++table->size;

    return 0;
}

double* get_value(HashTable* table, const char* key) {
    size_t index = hash(key, table->capacity);
    Entry* entry = table->buckets[index];
    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            return &entry->value;
        }
        entry = entry->next;
    }
    return NULL;
}

int main() {
    HashTable* table = create_hash_table();
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    add_entry(table, "key1", 3.14);
    double* value = get_value(table, "key1");
    if (value) {
        printf("Value for key1: %f\n", *value);
    } else {
        printf("Key not found\n");
    }

    destroy_hash_table(table);
    return 0;
}
