#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pthread.h>

#define MAX_COMMANDS 100
#define BUFFER_SIZE 256

typedef struct {
    int *data;
    size_t count;
    pthread_mutex_t lock;
} SharedData;

void* process_commands(void* arg) {
    SharedData *shared_data = (SharedData*)arg;
    char buffer[BUFFER_SIZE];
    pid_t pids[MAX_COMMANDS] = {0};
    int status[MAX_COMMANDS];

    while (1) {
        // Receive command from network
        if (recv(network_socket, buffer, BUFFER_SIZE - 1, 0) <= 0) {
            break;
        }
        buffer[BUFFER_SIZE - 1] = '\0';

        // Execute command in background
        pids[shared_data->count % MAX_COMMANDS] = fork();
        if (pids[shared_data->count % MAX_COMMANDS] == 0) {
            execl("/bin/sh", "sh", "-c", buffer, NULL);
            exit(EXIT_FAILURE);
        }

        // Update shared data
        pthread_mutex_lock(&shared_data->lock);
        shared_data->data[shared_data->count % MAX_COMMANDS] = pids[shared_data->count % MAX_COMMANDS];
        shared_data->count++;
        pthread_mutex_unlock(&shared_data->lock);

        // Check for completed commands
        for (int i = 0; i < shared_data->count; i++) {
            if (waitpid(pids[i], &status[i], WNOHANG) == pids[i]) {
                // Update status array
                pthread_mutex_lock(&shared_data->lock);
                shared_data->data[i] = status[i];
                pthread_mutex_unlock(&shared_data->lock);
            }
        }
    }

    return NULL;
}

void* process_integers(void* arg) {
    SharedData *shared_data = (SharedData*)arg;
    char buffer[BUFFER_SIZE];
    int max_value = INT_MIN;
    size_t max_index = -1;

    while (1) {
        // Receive integer from network
        if (recv(network_socket, buffer, BUFFER_SIZE - 1, 0) <= 0) {
            break;
        }
        buffer[BUFFER_SIZE - 1] = '\0';

        int value = atoi(buffer);
        if (value > max_value) {
            max_value = value;
            max_index = shared_data->count % MAX_COMMANDS;
        }

        // Update shared data
        pthread_mutex_lock(&shared_data->lock);
        shared_data->data[shared_data->count % MAX_COMMANDS] = value;
        shared_data->count++;
        pthread_mutex_unlock(&shared_data->lock);
    }

    printf("Largest integer: %d at index: %zu\n", max_value, max_index);

    return NULL;
}

int main() {
    SharedData shared_data;
    shared_data.data = (int*)malloc(MAX_COMMANDS * sizeof(int));
    shared_data.count = 0;
    pthread_mutex_init(&shared_data.lock, NULL);

    pthread_t command_thread, integer_thread;

    pthread_create(&command_thread, NULL, process_commands, &shared_data);
    pthread_create(&integer_thread, NULL, process_integers, &shared_data);

    pthread_join(command_thread, NULL);
    pthread_join(integer_thread, NULL);

    free(shared_data.data);
    pthread_mutex_destroy(&shared_data.lock);

    return 0;
}
