    PHY_LAYER_STATS *stats;
    int num_stats;
    int version;
} LTE_DL_FRAME;

typedef struct {
    LTE_DL_FRAME **frames;
    int size;
    int capacity;
    pthread_mutex_t lock;
} LTE_FRAME_ARRAY;

LTE_FRAME_ARRAY* create_frame_array() {
    LTE_FRAME_ARRAY *array = (LTE_FRAME_ARRAY*)malloc(sizeof(LTE_FRAME_ARRAY));
    array->frames = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_frame_array(LTE_FRAME_ARRAY *array) {
    for (int i = 0; i < array->size; i++) {
        free(array->frames[i]->stats);
        free(array->frames[i]);
    }
    free(array->frames);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void add_frame(LTE_FRAME_ARRAY *array, LTE_DL_FRAME *frame) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        array->frames = (LTE_DL_FRAME**)realloc(array->frames, array->capacity * sizeof(LTE_DL_FRAME*));
    }
    array->frames[array->size++] = frame;
    pthread_mutex_unlock(&array->lock);
}

void remove_frame(LTE_FRAME_ARRAY *array, int index) {
    pthread_mutex_lock(&array->lock);
    if (index >= 0 && index < array->size) {
        free(array->frames[index]->stats);
        free(array->frames[index]);
        for (int i = index; i < array->size - 1; i++) {
            array->frames[i] = array->frames[i + 1];
        }
        array->size--;
    }
    pthread_mutex_unlock(&array->lock);
}

LTE_DL_FRAME* create_dl_frame(DL_FRAME_METADATA metadata, PHY_LAYER_STATS *stats, int num_stats, int version) {
    LTE_DL_FRAME *frame = (LTE_DL_FRAME*)malloc(sizeof(LTE_DL_FRAME));
    frame->metadata = metadata;
    frame->stats = (PHY_LAYER_STATS*)malloc(num_stats * sizeof(PHY_LAYER_STATS));
    for (int i = 0; i < num_stats; i++) {
        frame->stats[i] = stats[i];
    }
    frame->num_stats = num_stats;
    frame->version = version;
    return frame;
}

void destroy_dl_frame(LTE_DL_FRAME *frame) {
    free(frame->stats);
    free(frame);
}
