#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE 10000

typedef struct {
    int value;
    long *offset;
    double *weight;
    int ref_count;
} record;

record **records;
long *offsets;
int *keys;
double *weights;
int size = 0;
int max_size = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(const char *operation, int current_size) {
    time_t now = time(NULL);
    printf("[%ld] %s: Current memory usage - %d/%d\n", now, operation, current_size, max_size);
}

void initialize_records(int count, int key_range, long offset_range, double weight_range) {
    pthread_mutex_lock(&mutex);
    if (count > max_size) {
        records = realloc(records, count * sizeof(record *));
        offsets = realloc(offsets, count * sizeof(long));
        keys = realloc(keys, count * sizeof(int));
        weights = realloc(weights, count * sizeof(double));
        max_size = count;
    }
    for (int i = 0; i < count; i++) {
        records[i] = malloc(sizeof(record));
        records[i]->value = rand() % key_range + 1;
        records[i]->offset = &offsets[rand() % offset_range];
        records[i]->weight = &weights[rand() % weight_range];
        records[i]->ref_count = 0;
    }
    size += count;
    log_memory_usage("Initialization", size);
    pthread_mutex_unlock(&mutex);
}

void resize_records(int new_size) {
    if (new_size > max_size) {
        records = realloc(records, new_size * sizeof(record *));
        offsets = realloc(offsets, new_size * sizeof(long));
        keys = realloc(keys, new_size * sizeof(int));
        weights = realloc(weights, new_size * sizeof(double));
        max_size = new_size;
    }
    size = new_size;
    log_memory_usage("Resize", size);
}

void* thread_function(void *arg) {
    int id = *(int *)arg;
    pthread_mutex_lock(&mutex);
    initialize_records(100, 1000, 10000, 1.0);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
