#include <openssl/ssl.h>
#include <openssl/err.h>
#include <yaml.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    SSL_CTX *ctx;
    int timeout_connect;
    int timeout_transfer;
} TLSConfig;

TLSConfig* load_config(const char *filename) {
    YAML_document_t doc;
    if (!yaml_document_read_file(&doc, filename)) {
        fprintf(stderr, "Failed to read YAML file\n");
        return NULL;
    }

    TLSConfig *config = malloc(sizeof(TLSConfig));
    config->ctx = SSL_CTX_new(TLS_client_method());
    if (!config->ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        yaml_document_delete(&doc);
        free(config);
        return NULL;
    }

    YAML_node_t *root = yaml_document_get_root_node(&doc);
    if (yaml_node_is_mapping(root)) {
        for (YAML_node_pair_t pair = yaml_node_pair_begin(root); pair != yaml_node_pair_end(root); ++pair) {
            const char *key = yaml_node_string(yaml_node_pair_key(pair));
            YAML_node_t *value = yaml_node_pair_value(pair);
            if (strcmp(key, "ca_bundle") == 0 && yaml_node_is_scalar(value)) {
                SSL_CTX_load_verify_locations(config->ctx, yaml_node_string(value), NULL);
            } else if (strcmp(key, "timeout_connect") == 0 && yaml_node_is_sequence(value) && yaml_node_length(value) > 0) {
                config->timeout_connect = atoi(yaml_node_string(yaml_node_item(value, 0)));
            } else if (strcmp(key, "timeout_transfer") == 0 && yaml_node_is_sequence(value) && yaml_node_length(value) > 1) {
                config->timeout_transfer = atoi(yaml_node_string(yaml_node_item(value, 1)));
            }
        }
    }

    yaml_document_delete(&doc);
    return config;
}

SSL* create_tls_session(const char *hostname, TLSConfig *config) {
    SSL *ssl = SSL_new(config->ctx);
    if (!ssl) {
        fprintf(stderr, "Failed to create SSL object\n");
        return NULL;
    }

    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to create socket\n");
        SSL_free(ssl);
        return NULL;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(443);
    if (inet_pton(AF_INET, hostname, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported\n");
        close(fd);
        SSL_free(ssl);
        return NULL;
    }

    int retries = 0;
    while (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0 && retries < 3) {
        perror("Connect failed");
        sleep(1);
        retries++;
    }
    if (retries == 3) {
        fprintf(stderr, "Failed to connect after multiple attempts\n");
        close(fd);
        SSL_free(ssl);
        return NULL;
    }

    SSL_set_fd(ssl, fd);
    int ret = SSL_connect(ssl);
    if (ret != 1) {
        ERR_print_errors_fp(stderr);
        SSL_shutdown(ssl);
        SSL_free(ssl);
        close(fd);
        return NULL;
    }

    return ssl;
}

void close_tls_session(SSL *ssl) {
    SSL_shutdown(ssl);
    SSL_free(ssl);
