// Function to initialize the network data pipeline
void network_data_pipeline(size_t num_records, size_t window_size, int udp_socket) {
    // Allocate memory for records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return;
    }

    // Initialize bloom filter and binary heap
    BloomFilter *bloom_filter = initialize_bloom_filter();
    BinaryHeap *binary_heap = initialize_binary_heap();

    // Initialize circular buffer
    CircularBuffer *circular_buffer = (CircularBuffer *)malloc(sizeof(CircularBuffer));
    if (!circular_buffer) {
        perror("Failed to allocate memory for circular buffer");
        free(records);
        return;
    }
    circular_buffer->buffer = (Record *)malloc(num_records * sizeof(Record));
    if (!circular_buffer->buffer) {
        perror("Failed to allocate memory for circular buffer data");
        free(circular_buffer);
        free(records);
        return;
    }
    circular_buffer->head = 0;
    circular_buffer->tail = 0;
    circular_buffer->capacity = num_records;
    pthread_mutex_init(&circular_buffer->lock, NULL);

    // Read data from UDP socket and process
    while (1) {
        Record packet;
        if (read_udp_packet(udp_socket, &packet) == -1) {
            break; // Exit loop on error or end of stream
        }

        // Update bloom filter and binary heap
        if (!bloom_filter_contains(bloom_filter, packet.sequence_number)) {
            bloom_filter_add(bloom_filter, packet.sequence_number);
            binary_heap_insert(binary_heap, packet);
        }
    }

    // Process and print top-N records
    process_top_n_records(binary_heap, 10);

    // Free allocated memory
    free(records);
    destroy_bloom_filter(bloom_filter);
    destroy_binary_heap(binary_heap);
    pthread_mutex_destroy(&circular_buffer->lock);
    free(circular_buffer->buffer);
    free(circular_buffer);
}

