#include <string.h>
#include <time.h>

typedef struct record {
    int value;
    size_t size;
    long *offset;
} Record;

typedef struct node {
    Record data;
    struct node *next;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Record data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int find_largest(int arr[], int n) {
    if (n <= 0) {
        fprintf(stderr, "Invalid array size\n");
        return -1;
    }
    int largest = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void free_memory(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    int arr[n];
    for (int i = 0; i < n; i++) {
        printf("Enter element %d: ", i + 1);
        scanf("%d", &arr[i]);
    }

    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        Record data = {arr[i], sizeof(arr[i]), NULL};
        insert_node(&head, data);
    }

    int largest = find_largest(arr, n);
    printf("Largest element: %d\n", largest);

    free_memory(head);

    return 0;
}
