#include <time.h>

#define TABLE_SIZE 1000

typedef struct {
    long offset;
    int key;
    double value;
} record;

unsigned int hash_function(int key) {
    return key % TABLE_SIZE;
}

int insert_record(record **records, int *keys, double *values, int size, int *hash_table) {
    for (int i = 0; i < size; ++i) {
        unsigned int index = hash_function(keys[i]);
        while (hash_table[index] != -1 && records[hash_table[index]]->key != keys[i]) {
            index = (index + 1) % TABLE_SIZE;
        }
        if (hash_table[index] == -1) {
            hash_table[index] = i;
            records[i]->offset = i * sizeof(record);
            records[i]->key = keys[i];
            records[i]->value = values[i];
        } else {
            printf("Error: Duplicate key detected.\n");
            return 0;
        }
    }
    return 1;
}

void free_records(record **records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(records);
}

record** initialize_records(int *keys, double *values, int size) {
    record **records = malloc(size * sizeof(record *));
    if (!records) {
        printf("Error: Memory allocation failed for records.\n");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            printf("Error: Memory allocation failed for record %d.\n", i);
            free_records(records, i);
            return NULL;
        }
    }

    int *hash_table = malloc(TABLE_SIZE * sizeof(int));
    if (!hash_table) {
        printf("Error: Memory allocation failed for hash table.\n");
        free_records(records, size);
        return NULL;
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        hash_table[i] = -1;
    }

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        values[i] = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
    }

    if (!insert_record(records, keys, values, size, hash_table)) {
        free_records(records, size);
        free(hash_table);
        return NULL;
    }

    free(hash_table);
    return records;
}

int main() {
    int keys[] = {1, 2, 3};
    double *values = malloc(3 * sizeof(double));
    record **records = initialize_records(keys, values, 3);

    if (records) {
        for (int i = 0; i < 3; ++i) {
            printf("Record %d: Offset=%ld, Key=%d, Value=%.2f\n", i, records[i]->offset, records[i]->key, records[i]->value);
        }
        free_records(records, 3);
    }

    free(values);
    return 0;
}
