} DataManagementSystem;

DataManagementSystem* dataManagementSystem(int initialSize, int valueRange, time_t updateInterval, int maxLogEntries) {
    // Allocate memory for the main structure
    DataManagementSystem *dms = (DataManagementSystem *)malloc(sizeof(DataManagementSystem));
    if (!dms) return NULL;

    // Initialize offsets
    dms->offsets = (long *)calloc(initialSize, sizeof(long));
    if (!dms->offsets) {
        free(dms);
        return NULL;
    }

    // Initialize keys
    dms->keys = (int *)calloc(initialSize, sizeof(int));
    if (!dms->keys) {
        free(dms->offsets);
        free(dms);
        return NULL;
    }

    // Initialize records
    dms->records = (struct Record *)malloc(initialSize * sizeof(struct Record));
    if (!dms->records) {
        free(dms->keys);
        free(dms->offsets);
        free(dms);
        return NULL;
    }
    for (int i = 0; i < initialSize; i++) {
        dms->records[i].value = rand() % valueRange;
        dms->records[i].size = sizeof(struct Record);
        dms->records[i].lastAccessed = time(NULL);
    }

    // Initialize metadata
    dms->metadata = (struct Metadata *)malloc(initialSize * sizeof(struct Metadata));
    if (!dms->metadata) {
        free(dms->records);
        free(dms->keys);
        free(dms->offsets);
        free(dms);
        return NULL;
    }
    for (int i = 0; i < initialSize; i++) {
        dms->metadata[i].accessCount = 0;
        dms->metadata[i].cumulativeDuration = 0;
        dms->metadata[i].lastAccessed = time(NULL);
    }

    // Initialize logs
    dms->logs = (char **)malloc(maxLogEntries * sizeof(char *));
    if (!dms->logs) {
        free(dms->metadata);
        free(dms->records);
        free(dms->keys);
        free(dms->offsets);
        free(dms);
        return NULL;
    }
    for (int i = 0; i < maxLogEntries; i++) {
        dms->logs[i] = (char *)malloc(256 * sizeof(char));
        if (!dms->logs[i]) {
            for (int j = 0; j < i; j++) free(dms->logs[j]);
            free(dms->logs);
            free(dms->metadata);
            free(dms->records);
            free(dms->keys);
            free(dms->offsets);
            free(dms);
            return NULL;
        }
    }

    // Initialize synchronization mechanisms
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        for (int i = 0; i < maxLogEntries; i++) free(dms->logs[i]);
        free(dms->logs);
        free(dms->metadata);
        free(dms->records);
        free(dms->keys);
        free(dms->offsets);
        free(dms);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);

    // Initialize other necessary variables and structures

    return dms;
}

