    memset(table.keys, -1, HASH_TABLE_SIZE * sizeof(int));
    table.next_index = 0;
}

unsigned int hash_function(int key) {
    return (key % HASH_TABLE_SIZE + HASH_TABLE_SIZE) % HASH_TABLE_SIZE;
}

int insert_record(int offset, int key, float weight) {
    unsigned int index = hash_function(key);
    while (table.keys[index] != -1 && table.keys[index] != key) {
        index = (index + 1) % HASH_TABLE_SIZE;
    }
    if (table.keys[index] == -1) {
        table.keys[index] = key;
        pool.records[table.next_index].offset = offset;
        pool.records[table.next_index].key = key;
        pool.records[table.next_index].weight = weight;
        pthread_mutex_lock(&pool.lock);
        pool.records[table.next_index].value = (double)(rand() % 100) / 10.0; // Random value between 0 and 9.9
        pthread_mutex_unlock(&pool.lock);
        table.next_index++;
        return 1;
    }
    return 0;
}

void cleanup_memory_pool() {
    free(pool.records);
    pthread_mutex_destroy(&pool.lock);
}

int main() {
    srand(time(NULL));
    init_memory_pool();
    init_hash_table();

    int offsets[MAX_RECORDS] = { /* pre-populated array of offsets */ };
    int keys[MAX_RECORDS] = { /* pre-populated array of unique keys */ };
    float weights[MAX_RECORDS] = { /* pre-populated array of weights */ };

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (!insert_record(offsets[i], keys[i], weights[i])) {
            fprintf(stderr, "Failed to insert record with key %d\n", keys[i]);
        }
    }

    cleanup_memory_pool();
    return 0;
}
