#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 1024
#define RESIZE_THRESHOLD 0.75

typedef struct {
    long offset;
    int key;
    double value;
    char label;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable* create_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table.\n");
        exit(EXIT_FAILURE);
    }
    table->records = calloc(INITIAL_CAPACITY, sizeof(Record));
    if (!table->records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        free(table);
        exit(EXIT_FAILURE);
    }
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    return table;
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    Record *new_records = calloc(new_capacity, sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Memory allocation failed for resized records array.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->records[i].key != -1) {
            size_t index = hash_function(table->records[i].key, new_capacity);
            while (new_records[index].key != -1) {
                index = (index + 1) % new_capacity;
            }
            new_records[index] = table->records[i];
        }
    }

    free(table->records);
    table->records = new_records;
    table->capacity = new_capacity;
}

void insert_record(HashTable *table, Record record) {
    if ((double)table->size / table->capacity >= RESIZE_THRESHOLD) {
        resize_hash_table(table);
    }

    size_t index = hash_function(record.key, table->capacity);
    while (table->records[index].key != -1 && table->records[index].key != record.key) {
        index = (index + 1) % table->capacity;
    }

    if (table->records[index].key == -1) {
        table->records[index] = record;
        ++table->size;
    } else {
        fprintf(stderr, "Duplicate key detected: %d\n", record.key);
    }
}

void free_hash_table(HashTable *table) {
    free(table->records);
    free(table);
}

// Additional functions for reading from CSV files, JSON logs, network API calls,
// exporting to binary file, and validating data integrity would be implemented here.

int main() {
    HashTable *table = create_hash_table();

    // Example usage:
    Record record1 = {0, 12345, 3.14, 'A'};
    insert_record(table, record1);

    free_hash_table(table);
    return 0;
}
```

This code provides a basic structure for a hash table implementation in C that can be expanded to include the required features such as reading from different data sources, handling memory allocation failures, and exporting records to a binary file. The `hash_function` is a simple modulo operation, which may not be optimal for all distributions of keys. You would need to implement a more sophisticated hash function based on your specific requirements.

The code also includes a basic resizing mechanism that doubles the capacity when the load factor exceeds 75%. This can be adjusted based on performance considerations and memory constraints.

Remember to handle potential I/O errors gracefully, especially when reading from files or network sources. You may want to use functions like `fopen`, `fread`, `fwrite`, and `fclose` with error checking to ensure data integrity during export.

For real-world deployment scenarios, consider profiling the function under stress conditions to identify bottlenecks and optimize performance further. This may involve tweaking the hash function, resizing strategy, or other aspects of the implementation based on empirical evidence.']

