#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    size_t size;
    long *offset;
} Record;

typedef struct node {
    int key;
    Record *data;
    struct node *left, *right;
} Node;

Node* newNode(int item, Record *rec) {
    Node* temp = (Node*)malloc(sizeof(Node));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    temp->key = item;
    temp->data = rec;
    temp->left = temp->right = NULL;
    return temp;
}

Node* insert(Node* node, int key, Record *rec) {
    if (node == NULL)
        return newNode(key, rec);

    if (key < node->key)
        node->left = insert(node->left, key, rec);
    else if (key > node->key)
        node->right = insert(node->right, key, rec);

    return node;
}

Node* minValueNode(Node* node) {
    Node* current = node;
    while (current && current->left != NULL)
        current = current->left;

    return current;
}

Node* deleteNode(Node* root, int key) {
    if (root == NULL)
        return root;

    if (key < root->key)
        root->left = deleteNode(root->left, key);
    else if (key > root->key)
        root->right = deleteNode(root->right, key);
    else {
        if ((root->left == NULL) || (root->right == NULL)) {
            Node *temp = root->left ? root->left : root->right;

            if (temp == NULL) {
                temp = root;
                root = NULL;
            } else
                *root = *temp;

            free(temp);
        } else {
            Node* temp = minValueNode(root->right);

            root->key = temp->key;
            root->data = temp->data;

            root->right = deleteNode(root->right, temp->key);
        }
    }

    if (root == NULL)
        return root;

    // Balance the tree
    // ...

    return root;
}

int findMax(int arr[], int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++)
        if (arr[i] > max)
            max = arr[i];
    return max;
}

void freeMemory(Node* node, Record *recs, int numRecords) {
    if (node != NULL) {
        freeMemory(node->left, recs, numRecords);
        freeMemory(node->right, recs, numRecords);
        free(node);
    }

    for (int i = 0; i < numRecords; i++) {
        free(recs[i].offset);
        free(recs[i].data);
    }
    free(recs);
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    int arr[n];
    for (int i = 0; i < n; i++) {
        printf("Enter element %d: ", i + 1);
        scanf("%d", &arr[i]);
    }

    Node* root = NULL;
    Record *recs = (Record*)malloc(n * sizeof(Record));
    if (!recs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < n; i++) {
        recs[i].value = arr[i];
        recs[i].size = sizeof(int);
        recs[i].offset = (long*)malloc(sizeof(long));
        if (!recs[i].offset) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        *recs[i].offset = i;
        root = insert(root, arr[i], &recs[i]);
    }

    int max = findMax(arr, n);
    printf("The largest number is: %d\n", max);

    freeMemory(root, recs, n);

    return 0;
}
