// Define task status enum
typedef enum {
    PENDING,
    IN_PROGRESS,
    COMPLETED
} TaskStatus;

// Define task structure
typedef struct {
    int id;
    TaskStatus status;
    int priority;
} Task;

// Define record structure
typedef struct {
    int value;
    size_t size;
} Record;

// Function to initialize a dynamic list of tasks
Task** init_task_list(size_t initial_size) {
    return (Task**)malloc(initial_size * sizeof(Task*));
}

// Function to insert a task into the list based on user-defined criteria
void insert_task(Task** list, size_t* size, Task* new_task, int (*compare)(const Task*, const Task*)) {
    if (*size == 0) {
        list[(*size)++] = new_task;
    } else {
        for (size_t i = 0; i < *size; ++i) {
            if (compare(list[i], new_task) > 0) {
                memmove(&list[i + 1], &list[i], (*size - i) * sizeof(Task*));
                list[i] = new_task;
                (*size)++;
                return;
            }
        }
        list[(*size)++] = new_task;
    }
}

// Function to retrieve tasks by status
Task** get_tasks_by_status(Task** list, size_t size, TaskStatus status, size_t* result_size) {
    *result_size = 0;
    for (size_t i = 0; i < size; ++i) {
        if (list[i]->status == status) {
            (*result_size)++;
        }
    }
    Task** result = (Task**)malloc((*result_size) * sizeof(Task*));
    size_t j = 0;
    for (size_t i = 0; i < size; ++i) {
        if (list[i]->status == status) {
            result[j++] = list[i];
        }
    }
    return result;
}

// Function to retrieve tasks by priority
Task** get_tasks_by_priority(Task** list, size_t size, int min_priority, int max_priority, size_t* result_size) {
    *result_size = 0;
    for (size_t i = 0; i < size; ++i) {
        if (list[i]->priority >= min_priority && list[i]->priority <= max_priority) {
            (*result_size)++;
        }
    }
    Task** result = (Task**)malloc((*result_size) * sizeof(Task*));
    size_t j = 0;
    for (size_t i = 0; i < size; ++i) {
        if (list[i]->priority >= min_priority && list[i]->priority <= max_priority) {
            result[j++] = list[i];
        }
    }
    return result;
}

// Function to free memory allocated for the task list
void free_task_list(Task** list, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(list[i]);
    }
    free(list);
}

// Function to allocate memory for an array of records with random values within a specified range
Record* init_records(size_t count, int min_value, int max_value) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].size = sizeof(int);
    }
    return records;
}

// Function to free memory allocated for the record array
void free_records(Record* records, size_t count) {
    free(records);
}
