namespace DataStreamProcessor {
    class DataProcessor {
        // Class implementation goes here
    };

    struct Component {
        long id;
        char name[256];
        char* description;
        std::time_t lastModified;
        size_t version;

        Component(long id, const char* name, const char* description, std::time_t lastModified, size_t version)
            : id(id), lastModified(lastModified), version(version) {
            strncpy(this->name, name, 256);
            this->description = new char[strlen(description) + 1];
            strcpy(this->description, description);
        }

        ~Component() {
            delete[] description;
        }
    };

    class ComponentRegistry {
    public:
        static std::unique_ptr<ComponentRegistry> getInstance() {
            static std::unique_ptr<ComponentRegistry> instance(new ComponentRegistry());
            return instance;
        }

        void createOrUpdateComponent(long id, const char* name, const char* description, std::time_t lastModified, size_t version) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (components_.find(id) != components_.end()) {
                // Update existing component
                Component& comp = components_[id];
                strncpy(comp.name, name, 256);
                delete[] comp.description;
                comp.description = new char[strlen(description) + 1];
                strcpy(comp.description, description);
                comp.lastModified = lastModified;
                comp.version = version;
            } else {
                // Create new component
                components_[id] = Component(id, name, description, lastModified, version);
            }
        }

        void deactivateComponent(long id) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (components_.find(id) != components_.end()) {
                components_[id].version++;
            }
        }

    private:
        ComponentRegistry() {}
        ~ComponentRegistry() {}

        std::unordered_map<long, Component> components_;
        std::mutex mutex_;
    };
}

int main() {
    auto processor = std::make_unique<DataStreamProcessor::DataProcessor>();
    DataStreamProcessor::ComponentRegistry& registry = *DataStreamProcessor::ComponentRegistry::getInstance();
    registry.createOrUpdateComponent(1, "ComponentA", "Description of Component A", time(nullptr), 1);
    registry.deactivateComponent(1);

    return 0;
}
