#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct record {
    int value;
    size_t size;
    long *offset;
    struct record *next, *prev;
} Record;

typedef struct {
    Record *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void init_doubly_linked_list(DoublyLinkedList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_record(DoublyLinkedList *list, Record *new_record) {
    pthread_mutex_lock(&list->lock);
    if (list->tail == NULL) {
        list->head = list->tail = new_record;
    } else {
        list->tail->next = new_record;
        new_record->prev = list->tail;
        list->tail = new_record;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_doubly_linked_list(DoublyLinkedList *list) {
    Record *current = list->head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

int find_largest(int *array, int size) {
    if (size <= 0) return -1;
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

void *generate_random_number(void *arg) {
    int min = *(int *)arg, max = *(int *)(arg + sizeof(int));
    return (void *)(rand() % (max - min + 1) + min);
}

void process_and_manage_data(int min_val, int max_val) {
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    Record records[MAX_RECORDS];
    DoublyLinkedList list;
    init_doubly_linked_list(&list);

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i];
        records[i].size = sizeof(int);
        records[i].offset = &offsets[i];
        insert_record(&list, &records[i]);
    }

    int array[MAX_RECORDS], size = 0;
    while (scanf("%d", &array[size]) != EOF) {
        size++;
    }

    int largest = find_largest(array, size);
    printf("Largest integer: %d\n", largest);

    free_doubly_linked_list(&list);
}

int main() {
    process_and_manage_data(10, 100);
    return 0;
}
