    char data[BUFFER_SIZE];
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int head;
    int tail;
    int count;
    sem_t lock;
    sem_t slots;
    sem_t items;
} PacketBuffer;

void init_buffer(PacketBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    sem_init(&buffer->lock, 0, 1);
    sem_init(&buffer->slots, 0, MAX_PACKETS);
    sem_init(&buffer->items, 0, 0);
}

int enqueue_packet(PacketBuffer *buffer, Packet packet) {
    sem_wait(&buffer->slots);
    sem_wait(&buffer->lock);

    buffer->packets[buffer->tail] = packet;
    buffer->tail = (buffer->tail + 1) % MAX_PACKETS;
    buffer->count++;

    sem_post(&buffer->lock);
    sem_post(&buffer->items);

    return 0;
}

int dequeue_packet(PacketBuffer *buffer, Packet *packet) {
    sem_wait(&buffer->items);
    sem_wait(&buffer->lock);

    if (buffer->count == 0) {
        sem_post(&buffer->lock);
        sem_post(&buffer->slots);
        return -1; // Buffer is empty
    }

    *packet = buffer->packets[buffer->head];
    buffer->head = (buffer->head + 1) % MAX_PACKETS;
    buffer->count--;

    sem_post(&buffer->lock);
    sem_post(&buffer->slots);

    return 0;
}

void* process_packets(void *arg) {
    PacketBuffer *buffer = (PacketBuffer *)arg;
    Packet packet;

    while (1) {
        if (dequeue_packet(buffer, &packet) == 0) {
            // Process the packet
            printf("Processing packet with timestamp: %d\n", packet.timestamp);
        }
    }

    return NULL;
}

int main() {
    PacketBuffer buffer;
    init_buffer(&buffer);

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, process_packets, &buffer);

    // Simulate enqueuing packets
    for (int i = 0; i < 10; i++) {
        Packet packet;
        packet.timestamp = i;
        packet.length = 1024;
        strcpy(packet.protocol, "TCP");
        enqueue_packet(&buffer, packet);
    }

    pthread_join(processor_thread, NULL);

    return 0;
}
