typedef struct {
    float x;
    float y;
} point;

typedef struct {
    char* value;
    double* number;
    point* location;
    size_t length;
} data_record;

data_record* create_data_records(size_t count, size_t min_length, size_t max_length) {
    if (count == 0 || min_length > max_length) {
        return NULL;
    }

    data_record* records = malloc(count * sizeof(data_record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        records[i].value = malloc((max_length + 1) * sizeof(char));
        if (!records[i].value) {
            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j].value);
            }
            free(records);
            return NULL;
        }

        records[i].number = malloc(sizeof(double));
        if (!records[i].number) {
            free(records[i].value);
            for (size_t j = 0; j <= i; ++j) {
                free(records[j].number);
            }
            free(records);
            return NULL;
        }

        records[i].location = malloc(sizeof(point));
        if (!records[i].location) {
            free(records[i].value);
            free(records[i].number);
            for (size_t j = 0; j <= i; ++j) {
                free(records[j].location);
            }
            free(records);
            return NULL;
        }

        records[i].length = min_length + rand() % (max_length - min_length + 1);

        // Generate random hexadecimal string
        for (size_t j = 0; j < records[i].length; ++j) {
            records[i].value[j] = "0123456789ABCDEF"[rand() % 16];
        }
        records[i].value[records[i].length] = '\0';

        *records[i].number = (double)(rand() % 1000) / 10.0;
        records[i].location->x = (float)(rand() % 1000) / 100.0;
        records[i].location->y = (float)(rand() % 1000) / 100.0;
    }

    return records;
}

void free_data_records(data_record* records, size_t count) {
    if (!records) {
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        free(records[i].value);
        free(records[i].number);
        free(records[i].location);
    }
    free(records);
}

int main() {
    size_t count = 10;
    size_t min_length = 5;
    size_t max_length = 20;

    data_record* records = create_data_records(count, min_length, max_length);
    if (records) {
        // Use the records
        free_data_records(records, count);
    }

    return 0;
}
