    insert_node(&config_tree, "repo_url", "http://example.com/repo");

    ConfigNode *node = search_node(config_tree, "api_key");
    if (node != NULL) {
        printf("API Key: %s\n", node->value);
    }

    free_config_tree(&config_tree);

    return 0;
}
