const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

function executeSQLQuery(query) {
  return new Promise((resolve, reject) => {
    const child = exec(`mysql -h your_host -u your_user -pyour_password -D your_database -e "${query}"`, (error, stdout, stderr) => {
      if (error) {
        console.error('Error executing SQL query:', error);
        return reject(error);
      }
      if (stderr) {
        console.error('SQL query output:', stderr);
        return reject(stderr);
      }
      resolve(stdout);
    });
  });
}

async function fetchAndFormatData(query) {
  try {
    const result = await executeSQLQuery(query);
    const data = JSON.parse(result); // Assuming the result is in JSON format
    console.log('Successful query:', query);
    return data;
  } catch (error) {
    console.error('Error fetching and formatting data:', error);
    throw error;
  }
}

// Example usage:
const sqlQuery = 'SELECT * FROM your_table';
fetchAndFormatData(sqlQuery)
  .then(data => console.log(data))
  .catch(error => console.error(error));
```

