typedef struct {
    int frame_id;
    int metadata_size;
    void* metadata;
    int stats_count;
    PHY_LAYER_STATS* stats[MAX_STATS];
} DL_FRAME_METADATA;

typedef struct {
    pthread_mutex_t lock;
    DL_FRAME_METADATA** frames;
    int count;
    int capacity;
} LTE_FRAME_MANAGER;

LTE_FRAME_MANAGER* createFrameManager() {
    LTE_FRAME_MANAGER* manager = (LTE_FRAME_MANAGER*)malloc(sizeof(LTE_FRAME_MANAGER));
    if (!manager) return NULL;
    manager->frames = (DL_FRAME_METADATA**)malloc(MAX_FRAMES * sizeof(DL_FRAME_METADATA*));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->capacity = MAX_FRAMES;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyFrameManager(LTE_FRAME_MANAGER* manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->frames[i]->metadata);
        for (int j = 0; j < manager->frames[i]->stats_count; j++) {
            free(manager->frames[i]->stats[j]);
        }
        free(manager->frames[i]);
    }
    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void logError(const char* message) {
    time_t now = time(NULL);
    printf("[%s] ERROR: %s\n", ctime(&now), message);
}

void logWarning(const char* message) {
    time_t now = time(NULL);
    printf("[%s] WARNING: %s\n", ctime(&now), message);
}

int processLTEFramesDynamic(LTE_FRAME_MANAGER* manager, DL_FRAME_METADATA** frames, int count) {
    pthread_mutex_lock(&manager->lock);
    if (count + manager->count > manager->capacity) {
        logError("Insufficient memory for new frames");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    for (int i = 0; i < count; i++) {
        DL_FRAME_METADATA* frame = frames[i];
        if (!frame || !frame->metadata || frame->stats_count > MAX_STATS) {
            logError("Invalid input frame");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->frames[manager->count++] = frame;
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

