<?php

class ClinicUpdater {
    private $db;
    private $apiClient;

    public function __construct($db, $apiClient) {
        $this->db = $db;
        $this->apiClient = $apiClient;
    }

    public function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
        // Validate input
        if (!is_numeric($clinicId) || !in_array($newStatus, ['active', 'inactive'])) {
            throw new InvalidArgumentException('Invalid clinic ID or status');
        }

        // Fetch current clinic data from the database
        $stmt = $this->db->prepare("SELECT id, version FROM clinics WHERE id = :id FOR UPDATE");
        $stmt->execute(['id' => $clinicId]);
        $currentClinic = $stmt->fetch(PDO::FETCH_ASSOC);

        if (!$currentClinic) {
            throw new Exception('Clinic not found');
        }

        // Validate clinic information using the external API
        try {
            $apiResponse = $this->apiClient->validateClinic($clinicId);
            if ($apiResponse['status'] !== 'valid') {
                throw new Exception('API validation failed: ' . $apiResponse['message']);
            }
        } catch (Exception $e) {
            // Handle API failure gracefully
            error_log("API failure for clinic ID {$clinicId}: " . $e->getMessage());
            // Fallback mechanism to update the database without API validation
            $newStatus = 'inactive'; // Default status in case of failure
        }

        // Prepare and execute the update statement with optimistic locking
        $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ipAddress, last_modified_date = NOW(), version = version + 1 WHERE id = :id AND version = :currentVersion");
        $stmt->execute([
            'status' => $newStatus,
            'ipAddress' => $ipAddress,
            'id' => $clinicId,
            'currentVersion' => $currentClinic['version']
        ]);

        if ($stmt->rowCount() === 0) {
            throw new Exception('Update failed due to concurrent modification');
        }

        // Log the successful update
        error_log("Successfully updated clinic ID {$clinicId} to status {$newStatus}");
    }
}

// Example usage:
$db = new PDO('mysql:host=localhost;dbname=clinics', 'username', 'password');
$apiClient = new HealthDataApiClient();
$updater = new ClinicUpdater($db, $apiClient);
$updater->updateClinicStatus(123, 'active', $_SERVER['REMOTE_ADDR']);
?>
```

