    for (int i = 0; i < num_records; ++i) {
        records[i] = (data_record*)malloc(sizeof(data_record));
        if (!records[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->value = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!records[i]->value) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; ++j) {
                free(records[j]->value);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->number = (double*)malloc(sizeof(double));
        if (!records[i]->number) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; ++j) {
                free(records[j]->value);
                free(records[j]->number);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->location = (point*)malloc(sizeof(point));
        if (!records[i]->location) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; ++j) {
                free(records[j]->value);
                free(records[j]->number);
                free(records[j]->location);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->id = i + 1;
        records[i]->length = min_length + rand() % (max_length - min_length + 1);

        // Generate random hexadecimal string
        for (size_t j = 0; j < records[i]->length; ++j) {
            records[i]->value[j] = "0123456789ABCDEF"[rand() % 16];
        }
        records[i]->value[records[i]->length] = '\0';

        // Initialize other fields as needed
    }

    return records;
}

void free_data_records(data_record** records, int num_records) {
    if (!records || num_records <= 0) {
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i]->value);
        free(records[i]->number);
        free(records[i]->location);
        free(records[i]);
    }
    free(records);
}

int main() {
    int num_records = 10;
    int min_length = 5;
    int max_length = 20;

    data_record** records = create_data_records(num_records, min_length, max_length);
    if (records) {
        // Use the records as needed
        free_data_records(records, num_records);
    }

    return 0;
}
```

