record* create_record(size_t size, int offset_range) {
    record *r = (record *)malloc(sizeof(record));
    if (!r) {
        perror("Failed to allocate memory for record");
        return NULL;
    }
    r->value = *(int*)generate_random_number(&offset_range);
    r->size = size;
    r->offset = (long *)malloc(size * sizeof(long));
    if (!r->offset) {
        perror("Failed to allocate memory for offset array");
        free(r);
        return NULL;
    }
    pthread_t thread;
    pthread_create(&thread, NULL, generate_random_number, &offset_range);
    pthread_join(thread, (void **)&(r->offset[0]));
    return r;
}

int process_and_find_max_async(int *array, size_t length) {
    if (!array || length == 0) {
        fprintf(stderr, "Invalid input array\n");
        return -1;
    }
    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Maximum value: %d\n", max);
    return 0;
}

