void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

long parse_positive_integer(const char* arg) {
    long num = atol(arg);
    if (num <= 0) {
        fprintf(stderr, "Invalid input: %s is not a positive integer\n", arg);
        exit(EXIT_FAILURE);
    }
    return num;
}

void initialize_records(record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 1001;
    }
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <positive_integer>\n", argv[0]);
        return EXIT_FAILURE;
    }

    long num_offsets = parse_positive_integer(argv[1]);
    int num_keys = num_offsets / 2;

    long* offsets = safe_malloc(num_offsets * sizeof(long));
    int* keys = safe_malloc(num_keys * sizeof(int));
    record* records = safe_malloc(num_offsets * sizeof(record));

    srand(time(NULL)); // Seed the random number generator
    initialize_records(records, num_offsets);

    // Use offsets and keys as needed

    free_memory(offsets, keys, records);
    return EXIT_SUCCESS;
}
