#define MAX_DEVICES 10000

typedef struct {
    int *device_id;
    float *sensor_readings;
    float average;
} DeviceData;

DeviceData *initialize_device_data(int device_count) {
    if (device_count > MAX_DEVICES) {
        fprintf(stderr, "Error: Exceeds maximum number of devices.\n");
        return NULL;
    }

    DeviceData *data = malloc(device_count * sizeof(DeviceData));
    if (!data) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < device_count; ++i) {
        data[i].device_id = malloc(sizeof(int));
        data[i].sensor_readings = malloc(10 * sizeof(float)); // Assuming 10 readings per device
        if (!data[i].device_id || !data[i].sensor_readings) {
            perror("Memory allocation failed");
            for (int j = 0; j < i; ++j) {
                free(data[j].device_id);
                free(data[j].sensor_readings);
            }
            free(data);
            return NULL;
        }
    }

    return data;
}

void calculate_averages(DeviceData *data, int device_count) {
    for (int i = 0; i < device_count; ++i) {
        float sum = 0.0f;
        for (int j = 0; j < 10; ++j) { // Assuming 10 readings per device
            sum += data[i].sensor_readings[j];
        }
        data[i].average = sum / 10.0f;
    }
}

void free_device_data(DeviceData *data, int device_count) {
    for (int i = 0; i < device_count; ++i) {
        free(data[i].device_id);
        free(data[i].sensor_readings);
    }
    free(data);
}

// Example usage
int main() {
    int device_count = 5;
    DeviceData *data = initialize_device_data(device_count);
    if (data) {
        calculate_averages(data, device_count);
        // Process data...
        free_device_data(data, device_count);
    }
    return 0;
}
