}

record* process_and_manage_records(size_t num_records, int range_min, int range_max, unsigned int seed) {
    record* records = allocate_memory(num_records * sizeof(record));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = generate_random(range_min, range_max, seed);
        records[i].size = rand() % 1024 + 1; // Random size between 1 and 1024
        records[i].offset = allocate_memory(records[i].size * sizeof(long));
    }

    return records;
}

void export_to_csv(record* records, size_t num_records, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        fprintf(file, "%d,%zu,%ld\n", records[i].value, records[i].size, *records[i].offset);
    }

    fclose(file);
}

void free_records(record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].offset);
    }
    free(records);
