#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock;
} EncryptionState;

EncryptionState* create_encryption_state(const char* algorithm) {
    EncryptionState* state = malloc(sizeof(EncryptionState));
    if (!state) return NULL;

    state->ctx = EVP_CIPHER_CTX_new();
    if (!state->ctx) {
        free(state);
        return NULL;
    }

    pthread_mutex_init(&state->lock, NULL);

    if (1 != EVP_EncryptInit_ex(state->ctx, EVP_get_cipherbyname(algorithm), NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    }

    return state;
}

void destroy_encryption_state(EncryptionState* state) {
    pthread_mutex_lock(&state->lock);
    EVP_CIPHER_CTX_free(state->ctx);
    pthread_mutex_unlock(&state->lock);
    pthread_mutex_destroy(&state->lock);
    free(state);
}

int encrypt_data(EncryptionState* state, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    pthread_mutex_lock(&state->lock);
    int len;
    if (1 != EVP_EncryptUpdate(state->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        pthread_mutex_unlock(&state->lock);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(state->ctx, ciphertext + len, &len)) {
        pthread_mutex_unlock(&state->lock);
        return -1;
    }
    ciphertext_len += len;

    pthread_mutex_unlock(&state->lock);
    return ciphertext_len;
}

int main() {
    EncryptionState* state = create_encryption_state("AES-256-CBC");
    if (!state) {
        fprintf(stderr, "Failed to create encryption state\n");
        return 1;
    }

    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((char*)plaintext);
    unsigned char ciphertext[1024];

    int ciphertext_len = encrypt_data(state, plaintext, plaintext_len, ciphertext);
    if (ciphertext_len < 0) {
        fprintf(stderr, "Encryption failed\n");
        destroy_encryption_state(state);
        return 1;
    }

    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    destroy_encryption_state(state);
    return 0;
}
