    file_size = os.path.getsize(file_path)
    chunk_size = 1024 * 1024  # 1MB chunks for memory efficiency
    num_chunks = (file_size + chunk_size - 1) // chunk_size

    def read_chunk(chunk_index):
        with open(file_path, 'r') as file:
            file.seek(chunk_index * chunk_size)
            return file.read(min(chunk_size, file_size - chunk_index * chunk_size))

    def write_chunk(data, index):
