            return gzip.compress(data.encode('utf-8'))
        elif any(char in data for char in 'BZh9'):
            return bz2.compress(data.encode('utf-8'))
        elif any(char in data for char in '7z\xbc\xaf'):
            return lzma.compress(data.encode('utf-8'))
        else:
            return data.encode('utf-8')

    def decompress_data(data):
        try:
            return gzip.decompress(data).decode('utf-8')
        except (gzip.BadGzipFile, EOFError):
            pass
        try:
            return bz2.decompress(data).decode('utf-8')
        except (bz2.BZ2Error, EOFError):
            pass
        try:
            return lzma.decompress(data).decode('utf-8')
        except lzma.LZMAError:
            pass
        return data.decode('utf-8')

    def process_chunk_with_retry(chunk_index, attempt=0):
        while attempt < max_retries:
            try:
                chunk_data = read_chunk(chunk_index)
                processed_chunk = process_chunk(chunk_data)
                compressed_chunk = compress_data(processed_chunk)
                write_chunk(compressed_chunk, chunk_index)
                break
            except Exception as e:
                print(f"Error processing chunk {chunk_index}, retrying... ({attempt + 1}/{max_retries})")
                time.sleep(retry_interval)
                attempt += 1

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = [executor.submit(process_chunk_with_retry, i) for i in range(num_chunks)]
        for future in concurrent.futures.as_completed(futures):
            try:
