#include <string.h>

typedef struct {
    float value;
    char* str;
    size_t length;
} dataUnit;

double polynomialFunction(int index) {
    // Example polynomial function: f(x) = x^2 + 3x + 1
    return (index * index) + (3 * index) + 1;
}

void manageMemory(double** doubleArray, char*** charArray, dataUnit*** structArray, int size) {
    *doubleArray = (double*)malloc(size * sizeof(double));
    *charArray = (char**)malloc(size * sizeof(char*));
    *structArray = (dataUnit**)malloc(size * sizeof(dataUnit*));

    if (*doubleArray == NULL || *charArray == NULL || *structArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < size; i++) {
        (*doubleArray)[i] = polynomialFunction(i);

        // Allocate memory for the string and copy data
        (*charArray)[i] = (char*)malloc((i + 1) * sizeof(char));
        if ((*charArray)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        snprintf((*charArray)[i], i + 2, "%d", i);

        // Initialize dataUnit
        (*structArray)[i] = (dataUnit*)malloc(sizeof(dataUnit));
        if ((*structArray)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        (*structArray)[i]->value = polynomialFunction(i);
        (*structArray)[i]->str = (*charArray)[i];
        (*structArray)[i]->length = i + 1;
    }
}

void freeMemory(double* doubleArray, char** charArray, dataUnit** structArray, int size) {
    for (int i = 0; i < size; i++) {
        free(charArray[i]);
        free(structArray[i]);
    }
    free(doubleArray);
    free(charArray);
    free(structArray);
}

int main() {
    int size = 10;
    double* doubleArray;
    char** charArray;
    dataUnit** structArray;

    manageMemory(&doubleArray, &charArray, &structArray, size);

    // Use the arrays...

    freeMemory(doubleArray, charArray, structArray, size);

    return 0;
}
