#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Event {
    time_t timestamp;
    int status_flag;
    struct Item *item;
} Event;

typedef struct Item {
    int id;
    char name[256];
    Event *event;
    pthread_mutex_t lock;
} Item;

typedef struct Node {
    Item *item;
    struct Node *next;
} Node;

typedef struct LinkedList {
    Node *head;
    pthread_mutex_t lock;
} LinkedList;

Item* create_item(int id, const char *name) {
    Item *item = (Item *)malloc(sizeof(Item));
    if (!item) return NULL;
    item->id = id;
    strncpy(item->name, name, sizeof(item->name) - 1);
    item->event = NULL;
    pthread_mutex_init(&item->lock, NULL);
    return item;
}

Event* create_event(time_t timestamp, int status_flag, Item *item) {
    Event *event = (Event *)malloc(sizeof(Event));
    if (!event) return NULL;
    event->timestamp = timestamp;
    event->status_flag = status_flag;
    event->item = item;
    return event;
}

void add_item_to_list(LinkedList *list, Item *item) {
    pthread_mutex_lock(&list->lock);
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->item = item;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

Item* find_item_by_id(LinkedList *list, int id) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current) {
        if (current->item->id == id) {
            pthread_mutex_unlock(&list->lock);
            return current->item;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void cleanup_unused_resources(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    Node *prev = NULL;
    while (current) {
        if (current->item->event == NULL) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            pthread_mutex_unlock(&list->lock);
            free(current->item);
            free(current);
            pthread_mutex_lock(&list->lock);
        } else {
            prev = current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void* worker_thread(void *arg) {
    LinkedList *list = (LinkedList *)arg;
    // Simulate work with the list
    return NULL;
}

int main() {
    LinkedList list;
    pthread_mutex_init(&list.lock, NULL);

    // Example usage
    Item *item1 = create_item(1, "Item 1");
    Event *event1 = create_event(time(NULL), 0, item1);
    item1->event = event1;

    add_item_to_list(&list, item1);

    Item *found_item = find_item_by_id(&list, 1);
    if (found_item) {
        printf("Found item: %s\n", found_item->name);
    }

    cleanup_unused_resources(&list);

    pthread_mutex_destroy(&list.lock);
    return 0;
}
```

This code provides a basic structure for managing items and events in a distributed environment with thread safety. It includes functions to create items and events, add items to a linked list, find an item by ID, and clean up unused resources. The main function demonstrates how to use these functions. Note that this is a simplified example and does not include advanced features like load balancing, fault tolerance, or optimizations for large-scale systems.']

