#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int data;
    struct node* next;
    struct node* prev;
    pthread_mutex_t counter_mutex;
    int thread_counter;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t max_capacity;
    size_t current_size;
    pthread_mutex_t list_mutex;
} DoublyLinkedList;

DoublyLinkedList* create_list(size_t max_capacity) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->max_capacity = max_capacity;
    list->current_size = 0;
    pthread_mutex_init(&list->list_mutex, NULL);

    return list;
}

Node* create_node(int data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;
    node->prev = NULL;
    pthread_mutex_init(&node->counter_mutex, NULL);
    node->thread_counter = 0;

    return node;
}

void insert_node(DoublyLinkedList* list, Node* new_node) {
    pthread_mutex_lock(&list->list_mutex);
    if (list->current_size >= list->max_capacity) {
        pthread_mutex_unlock(&list->list_mutex);
        free(new_node);
        return;
    }

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->current_size++;
    pthread_mutex_unlock(&list->list_mutex);
}

void delete_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->list_mutex);
    free(list);
}

// Additional functions for read, write operations and memory management can be implemented here.
```

