    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void process_and_find_max_async(size_t num_records, size_t data_block_size) {
    long *offsets = safe_malloc(num_records * sizeof(long));
    int *keys = safe_malloc(num_records * sizeof(int));
    record *records = safe_malloc(num_records * sizeof(record));

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = data_block_size * i;
        keys[i] = generate_random(1, 100);
        records[i].value = keys[i];
        records[i].size = data_block_size;
        records[i].offset = &offsets[i];
    }

    int max_value = INT_MIN;
    for (size_t i = 0; i < num_records; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

