#include <semaphore.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    sem_t *sem;
    char name[256];
    int ref_count;
} Semaphore;

Semaphore* create_semaphore(const char *identifier, int initial_value) {
    // Generate a unique name for the semaphore
    snprintf(Semaphore->name, sizeof(Semaphore->name), "/sem_%s", identifier);

    // Create or open the semaphore with the specified initial value
    Semaphore->sem = sem_open(Semaphore->name, O_CREAT | O_EXCL, 0644, initial_value);
    if (Semaphore->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }

    Semaphore->ref_count = 1;
    return Semaphore;
}

void destroy_semaphore(Semaphore *semaphore) {
    // Decrement the reference count
    if (--semaphore->ref_count > 0) {
        return;
    }

    // Close and unlink the semaphore
    sem_close(semaphore->sem);
    sem_unlink(semaphore->name);
}

int wait_on_semaphore(Semaphore *semaphore, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;

    return sem_timedwait(semaphore->sem, &ts);
}

int try_lock_semaphore(Semaphore *semaphore) {
    return sem_trywait(semaphore->sem);
}

void increase_semaphore_value(Semaphore *semaphore) {
    sem_post(semaphore->sem);
}

void decrease_semaphore_value(Semaphore *semaphore) {
    sem_wait(semaphore->sem);
}

int get_semaphore_value(Semaphore *semaphore) {
    int value;
    sem_getvalue(semaphore->sem, &value);
    return value;
}
