    for (size_t i = 0; i < num_records; ++i) {
        set_initial_value(&records[i], initial_value);
        meta_data[i].data = &records[i];
        meta_data[i].start = i * sizeof(int);
        meta_data[i].end = meta_data[i].start + sizeof(int);
        meta_data[i].total_size = sizeof(int);
    }

    int *input_array = malloc(num_records * sizeof(int));
    if (input_array == NULL) {
