void process_and_find_max(int num_records, long offset, int key_range_min, int key_range_max, size_t max_block_size) {
    srand(time(NULL));

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return;
    }

    long total_size = 0;
    for (int i = 0; i < num_records; ++i) {
        records[i].value = generate_random(key_range_min, key_range_max);
        printf("Enter size of data block %d: ", i + 1);
        scanf("%zu", &records[i].size);
        total_size += records[i].size;
    }

    if (total_size > max_block_size) {
        fprintf(stderr, "Total size exceeds maximum block size limit.\n");
        free(records);
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].data = malloc(records[i].size * sizeof(char));
        if (!records[i].data) {
            fprintf(stderr, "Memory allocation failed for data block %d.\n", i + 1);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].data);
            }
            free(records);
            return;
        }
    }

    int max_value = records[0].value;
    for (int i = 1; i < num_records; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Largest integer in the input list: %d\n", max_value);

    // Free all allocated memory
    for (int i = 0; i < num_records; ++i) {
        free(records[i].data);
