#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

class HttpClient {
public:
    HttpClient(net::io_context& ioc, std::string host, std::string port)
        : resolver_(ioc), stream_(ioc) {
        resolve(host, port);
    }

    void get(const std::string& target) {
        http::request<http::string_body> req{http::verb::get, target, 11};
        req.set(http::field::host, host_);
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        do_request(std::move(req));
    }

    void post(const std::string& target, const std::string& body) {
        http::request<http::string_body> req{http::verb::post, target, 11};
        req.set(http::field::host, host_);
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        req.set(http::field::content_type, "application/json");
        req.body() = body;
        req.prepare_payload();

        do_request(std::move(req));
    }

private:
    void resolve(const std::string& host, const std::string& port) {
        resolver_.async_resolve(host, port,
            [this](beast::error_code ec, tcp::resolver::results_type results) {
                if (!ec)
                    do_connect(results);
            });
    }

    void do_connect(tcp::resolver::results_type results) {
        net::async_connect(stream_, results,
            [this](beast::error_code ec, const tcp::endpoint&) {
                if (!ec)
                    do_read();
            });
    }

    void do_request(http::request<http::string_body> req) {
        http::async_write(stream_, req,
            [this](beast::error_code ec, std::size_t bytes_transferred) {
                if (!ec)
                    do_read();
            });
    }

    void do_read() {
        http::async_read(stream_, buffer_,
            [this](beast::error_code ec, std::size_t bytes_transferred) {
                if (!ec)
                    do_request(http::request<http::string_body>{});
            });
    }

    tcp::resolver resolver_;
