#include <time.h>

typedef struct {
    int value;
    char buffer[256];
    double timestamp;
    size_t size;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t count;
    size_t capacity;
    FILE* log_file;
} RecordManager;

RecordManager* init_record_manager(size_t initial_capacity) {
    RecordManager* rm = (RecordManager*)malloc(sizeof(RecordManager));
    if (!rm) return NULL;

    rm->offsets = (long*)calloc(initial_capacity, sizeof(long));
    rm->keys = (int*)calloc(initial_capacity, sizeof(int));
    rm->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    rm->count = 0;
    rm->capacity = initial_capacity;
    rm->log_file = fopen("record_manager.log", "w");
    if (!rm->log_file) {
        free(rm);
        return NULL;
    }

    srand(time(NULL));
    return rm;
}

void log_operation(RecordManager* rm, const char* operation, int success) {
    fprintf(rm->log_file, "%s %s\n", operation, success ? "SUCCESS" : "FAILURE");
}

int add_record(RecordManager* rm, size_t offset, int key, double timestamp, size_t size) {
    if (rm->count >= rm->capacity) {
        // Resize the arrays
        long* new_offsets = realloc(rm->offsets, 2 * rm->capacity * sizeof(long));
        int* new_keys = realloc(rm->keys, 2 * rm->capacity * sizeof(int));
        Record** new_records = realloc(rm->records, 2 * rm->capacity * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            log_operation(rm, "RESIZE", 0);
            return -1;
        }

        rm->offsets = new_offsets;
        rm->keys = new_keys;
        rm->records = new_records;
        rm->capacity *= 2;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        log_operation(rm, "ALLOCATE_RECORD", 0);
        return -1;
    }

    record->value = rand() % 1000; // Random value between 0 and 999
    record->timestamp = timestamp;
    record->size = size;

    rm->offsets[rm->count] = offset;
    rm->keys[rm->count] = key;
    rm->records[rm->count++] = record;

    log_operation(rm, "ADD_RECORD", 1);
    return 0;
}

void free_record_manager(RecordManager* rm) {
    for (size_t i = 0; i < rm->count; ++i) {
        free(rm->records[i]);
    }
    free(rm->offsets);
    free(rm->keys);
    free(rm->records);
    fclose(rm->log_file);
    free(rm);
}
