#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1024 * 1024 / sizeof(struct Record) // 1 MB limit

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(MAX_RECORDS, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = MAX_RECORDS;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    pthread_mutex_lock(&collection->mutex);
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(RecordCollection* collection, long offset, int key) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Collection is full
    }

    collection->records[collection->size].offset = offset;
    collection->records[collection->size].key = key;
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

int update_record(RecordCollection* collection, int key, long new_offset) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            collection->records[i].offset = new_offset;
            pthread_mutex_unlock(&collection->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return -1; // Record not found
}

Record* get_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            Record* record = &collection->records[i];
            pthread_mutex_unlock(&collection->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return NULL; // Record not found
}

void log_allocations(size_t allocations, size_t deallocations) {
    printf("Allocations: %zu, Deallocations: %zu\n", allocations, deallocations);
}
