        free(rm);
        return NULL;
    }

    rm->buffers = (char**)malloc(max_records * sizeof(char*));
    if (!rm->buffers) {
        free(rm->records);
        free(rm);
        return NULL;
    }

    rm->timestamps = (double*)malloc(max_records * sizeof(double));
    if (!rm->timestamps) {
        free(rm->buffers);
        free(rm->records);
        free(rm);
        return NULL;
    }

    for (size_t i = 0; i < max_records; ++i) {
        rm->records[i].offset = -1;
        rm->records[i].key = -1;
        rm->records[i].value = rand() % 1000; // Random value between 0 and 999
        rm->buffers[i] = NULL;
        rm->timestamps[i] = 0.0;
    }

    return rm;
}

