    for (size_t i = 0; i < max_records; ++i) {
        if (rm->buffers[i]) free(rm->buffers[i]);
    }
    free(rm->timestamps);
    free(rm->buffers);
    free(rm->records);
    free(rm);
}

int main() {
    srand(time(NULL));
    size_t max_records = 1000;
    record_manager* rm = create_record_manager(max_records);

