#define MAX_CONNECTIONS 1024

typedef struct {
    int socket_descriptor;
    int in_progress;
    time_t timeout;
    int reference_count;
} Connection;

Connection connections[MAX_CONNECTIONS];
int active_connections = 0;
pthread_mutex_t connection_lock;

void initialize_connection_manager() {
    pthread_mutex_init(&connection_lock, NULL);
}

int add_connection(int socket_descriptor) {
    pthread_mutex_lock(&connection_lock);
    if (active_connections >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&connection_lock);
        return -1; // Error: Maximum connections reached
    }
    connections[active_connections].socket_descriptor = socket_descriptor;
    connections[active_connections].in_progress = 0;
    connections[active_connections].timeout = time(NULL);
    connections[active_connections].reference_count = 0;
    active_connections++;
    pthread_mutex_unlock(&connection_lock);
    return 0; // Success
}

void remove_connection(int socket_descriptor) {
    pthread_mutex_lock(&connection_lock);
    for (int i = 0; i < active_connections; i++) {
        if (connections[i].socket_descriptor == socket_descriptor) {
            memmove(&connections[i], &connections[i + 1], sizeof(Connection) * (active_connections - i - 1));
            active_connections--;
            break;
        }
    }
    pthread_mutex_unlock(&connection_lock);
}

void update_connection(int socket_descriptor, int in_progress, time_t timeout, int reference_count) {
    pthread_mutex_lock(&connection_lock);
    for (int i = 0; i < active_connections; i++) {
        if (connections[i].socket_descriptor == socket_descriptor) {
            connections[i].in_progress = in_progress;
            connections[i].timeout = timeout;
            connections[i].reference_count = reference_count;
            break;
        }
    }
    pthread_mutex_unlock(&connection_lock);
}

