#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

typedef struct RecordList {
    Record *head;
    pthread_mutex_t lock;
} RecordList;

Record* create_record(int key, int value) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = NULL;
    return new_record;
}

void insert_record(RecordList *list, int key, int value) {
    pthread_mutex_lock(&list->lock);
    Record *new_record = create_record(key, value);
    if (list->head == NULL) {
        list->head = new_record;
    } else {
        Record *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    Record *previous = NULL;
    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }
    if (current != NULL) {
        if (previous == NULL) {
            list->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&list->lock);
}

Record* lookup_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

void compact_records(RecordList *list) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    Record *previous = NULL;
    while (current != NULL) {
        if (current->value == -1) { // Assuming -1 indicates an inactive record
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            Record *temp = current;
            current = current->next;
            free(temp);
        } else {
            previous = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_records(RecordList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->value, sizeof(int), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void deserialize_records(RecordList *list, FILE *file) {
    pthread_mutex_lock(&list->lock);
    while (!feof(file)) {
        int key, value;
        fread(&key, sizeof(int), 1, file);
        fread(&value, sizeof(int), 1, file);
        insert_record(list, key, value);
    }
    pthread_mutex_unlock(&list->lock);
}

void* garbage_collection(void *arg) {
    RecordList *list = (RecordList*)arg;
    while (1) {
        compact_records(list);
        sleep(60); // Compact every minute
    }
    return NULL;
}
