void init_project_collection(ProjectCollection *collection) {
    collection->pairs = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_project_to_category(ProjectCollection *collection, int category_id, Project project) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        CategoryProjectPair **new_pairs = realloc(collection->pairs, new_capacity * sizeof(CategoryProjectPair *));
        if (!new_pairs) {
            perror("Failed to reallocate memory for project collection");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->pairs = new_pairs;
        collection->capacity = new_capacity;
    }
    CategoryProjectPair *pair = malloc(sizeof(CategoryProjectPair));
    pair->id = category_id;
    pair->project = project;
    pthread_mutex_init(&pair->lock, NULL);
    collection->pairs[collection->count++] = pair;
    pthread_mutex_unlock(&collection->lock);
