#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef enum {
    AUDIT_LOGIN,
    AUDIT_LOGOUT,
    AUDIT_ERROR,
    AUDIT_INFO
} AuditEventType;

typedef struct AuditEntry {
    AuditEventType eventType;
    char *description;
    time_t timestamp;
} AuditEntry;

typedef struct AuditCollection {
    AuditEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} AuditCollection;

void audit_collection_init(AuditCollection *collection, size_t initial_capacity) {
    collection->entries = (AuditEntry **)malloc(initial_capacity * sizeof(AuditEntry *));
    if (!collection->entries) {
        perror("Failed to allocate memory for audit entries");
        exit(EXIT_FAILURE);
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void audit_collection_add(AuditCollection *collection, AuditEventType eventType, const char *description) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        AuditEntry **new_entries = (AuditEntry **)realloc(collection->entries, new_capacity * sizeof(AuditEntry *));
        if (!new_entries) {
            perror("Failed to reallocate memory for audit entries");
            exit(EXIT_FAILURE);
        }
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }
    AuditEntry *entry = (AuditEntry *)malloc(sizeof(AuditEntry));
    if (!entry) {
        perror("Failed to allocate memory for audit entry");
        exit(EXIT_FAILURE);
    }
    entry->eventType = eventType;
    entry->description = strdup(description);
    entry->timestamp = time(NULL);
    collection->entries[collection->count++] = entry;
    pthread_mutex_unlock(&collection->lock);
}

void audit_collection_free(AuditCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->entries[i]->description);
        free(collection->entries[i]);
    }
    free(collection->entries);
    pthread_mutex_destroy(&collection->lock);
}

void audit_collection_filter(AuditCollection *collection, AuditEventType eventType, void (*callback)(AuditEntry *)) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->entries[i]->eventType == eventType) {
            callback(collection->entries[i]);
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void print_audit_entry(AuditEntry *entry) {
    printf("Event Type: %d, Description: %s, Timestamp: %ld\n", entry->eventType, entry->description, entry->timestamp);
}
```

