#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataStream;

DataStream* createDataStream(size_t initialCapacity) {
    DataStream* stream = (DataStream*)malloc(sizeof(DataStream));
    if (!stream) return NULL;

    stream->data = (int*)malloc(initialCapacity * sizeof(int));
    if (!stream->data) {
        free(stream);
        return NULL;
    }

    stream->capacity = initialCapacity;
    stream->size = 0;
    pthread_mutex_init(&stream->lock, NULL);

    return stream;
}

void destroyDataStream(DataStream* stream) {
    if (stream) {
        pthread_mutex_destroy(&stream->lock);
        free(stream->data);
        free(stream);
    }
}

int addRecord(DataStream* stream, int record) {
    pthread_mutex_lock(&stream->lock);
    if (stream->size >= stream->capacity) {
        size_t newCapacity = stream->capacity * 2;
        int* newData = (int*)realloc(stream->data, newCapacity * sizeof(int));
        if (!newData) {
            pthread_mutex_unlock(&stream->lock);
            return -1; // Memory allocation failed
        }
        stream->data = newData;
        stream->capacity = newCapacity;
    }
    stream->data[stream->size++] = record;
    pthread_mutex_unlock(&stream->lock);
    return 0;
}

int findLargestRecord(DataStream* stream) {
    if (stream->size == 0) return -1; // No records in the stream

    int largest = stream->data[0];
    for (size_t i = 1; i < stream->size; ++i) {
        if (stream->data[i] > largest) {
            largest = stream->data[i];
        }
    }
    return largest;
}

void logStreamStats(DataStream* stream, FILE* logFile) {
    pthread_mutex_lock(&stream->lock);
    fprintf(logFile, "Stream size: %zu\n", stream->size);
    pthread_mutex_unlock(&stream->lock);
}
