#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <curl/curl.h>

#define MAX_IP_LENGTH 16
#define CACHE_SIZE 100

typedef struct {
    char hostname[256];
    char access_token[256];
} OAuthRequest;

typedef struct {
    char ip[MAX_IP_LENGTH];
    time_t last_updated;
} DNSCacheEntry;

DNSCacheEntry dns_cache[CACHE_SIZE];

u_char* dnsResolveAndOAuthAuthenticate(const char* hostname, OAuthRequest* oauth_request) {
    // DNS resolution
    u_char ip[MAX_IP_LENGTH] = {0};
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(ip, ipstr);
        break; // Assuming first result is sufficient
    }

    freeaddrinfo(res); // all done with this structure

    if (strlen(ip) == 0) {
        fprintf(stderr, "Failed to resolve hostname\n");
        return NULL;
    }

    // OAuth authentication and user information retrieval
    CURL *curl;
    CURLcode res_code;
    char* access_token = oauth_request->access_token;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct MemoryStruct chunk;
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/userinfo");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, oauth_request->headers);

        res_code = curl_easy_perform(curl);
        if(res_code != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res_code));

        // Process the response
        printf("%lu bytes retrieved\n", (unsigned long)chunk.size);
        free(chunk.memory);

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    return ip;
}

size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}
