typedef struct {
    int key;
    size_t size;
    char* data;
} record;

record* create_records(int count, int min_key, int max_key, size_t min_size, size_t max_size, unsigned long seed) {
    srand(seed);
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < count; ++i) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].size = rand() % (max_size - min_size + 1) + min_size;
        records[i].data = (char*)malloc(records[i].size);
        if (!records[i].data) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) free(records[j].data);
            free(records);
            return NULL;
        }
        // Initialize data with random values or from external source
    }

    return records;
}

void free_records(record* records, int count) {
    for (int i = 0; i < count; ++i) free(records[i].data);
    free(records);
}

// Helper function to generate random numbers within a specified range
int random_between(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Custom comparison function for sorting records based on integer key
int compare_records(const void* a, const void* b) {
    record* recA = (record*)a;
    record* recB = (record*)b;
    return recA->key - recB->key;
}

// Example usage of the create_records function with custom sorting
void example_usage() {
    int count = 10;
    int min_key = 1, max_key = 100;
    size_t min_size = 10, max_size = 100;
    unsigned long seed = time(NULL);

    record* records = create_records(count, min_key, max_key, min_size, max_size, seed);
    if (!records) {
        printf("Failed to allocate memory for records.\n");
        return;
    }

    // Sort records using qsort
    qsort(records, count, sizeof(record), compare_records);

    // Print sorted records
    for (int i = 0; i < count; ++i) {
        printf("Key: %d, Size: %zu\n", records[i].key, records[i].size);
    }

    free_records(records, count);
}

int main() {
    example_usage();
    return 0;
}
