#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct DataRecord {
    int value;
    size_t dataSize;
    void* dataBlock;
    time_t timestamp;
} DataRecord;

typedef struct RecordList {
    DataRecord** records;
    size_t count;
    size_t capacity;
} RecordList;

void init_record_list(RecordList* list, size_t initial_capacity) {
    list->records = (DataRecord**)malloc(initial_capacity * sizeof(DataRecord*));
    list->count = 0;
    list->capacity = initial_capacity;
}

void add_record(RecordList* list, int value, size_t dataSize, void* dataBlock, time_t timestamp) {
    if (list->count >= list->capacity) {
        list->capacity *= 2;
        list->records = (DataRecord**)realloc(list->records, list->capacity * sizeof(DataRecord*));
    }
    DataRecord* new_record = (DataRecord*)malloc(sizeof(DataRecord));
    new_record->value = value;
    new_record->dataSize = dataSize;
    new_record->dataBlock = dataBlock;
    new_record->timestamp = timestamp;
    list->records[list->count++] = new_record;
}

void free_record_list(RecordList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->records[i]);
    }
    free(list->records);
    list->records = NULL;
    list->count = 0;
    list->capacity = 0;
}

int find_max_value(RecordList* list) {
    int max_value = INT_MIN;
    for (size_t i = 0; i < list->count; ++i) {
        if (list->records[i]->value > max_value) {
            max_value = list->records[i]->value;
        }
    }
    return max_value;
}

void process_and_find_max(int min_val, int max_val, RecordList* list) {
    srand(time(NULL));
    while (1) {
        printf("Enter an integer (-1 to stop): ");
        int input;
        scanf("%d", &input);
        if (input == -1) break;

        size_t dataSize = sizeof(int);
        void* dataBlock = malloc(dataSize);
        memcpy(dataBlock, &input, dataSize);

        time_t timestamp = time(NULL);
        add_record(list, input, dataSize, dataBlock, timestamp);
    }

    int max_value = find_max_value(list);
    printf("Maximum value found: %d\n", max_value);

    free_record_list(list);
}

int main() {
    RecordList list;
    init_record_list(&list, 10); // Initial capacity of 10 records
    process_and_find_max(1, 100, &list);
    return 0;
}
