int findLargestInteger(int* arr, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size\n");
        return -1;
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

