#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum { PENDING, IN_PROGRESS, COMPLETED } TaskStatus;

typedef struct {
    int id;
    TaskStatus status;
    int priority;
} Task;

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    size_t size;
    void* data;
} DataBlock;

typedef struct {
    Task** tasks;
    size_t task_count;
    size_t task_capacity;
    Record* records;
    long* offsets;
    int* keys;
    size_t record_count;
    size_t record_capacity;
    DataBlock* data_blocks;
} TaskManager;

TaskManager* create_task_manager() {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    if (!manager) return NULL;

    manager->tasks = NULL;
    manager->task_count = 0;
    manager->task_capacity = 0;
    manager->records = NULL;
    manager->offsets = NULL;
    manager->keys = NULL;
    manager->record_count = 0;
    manager->record_capacity = 0;
    manager->data_blocks = NULL;

    return manager;
}

void destroy_task_manager(TaskManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->task_count; ++i) {
        free(manager->tasks[i]);
    }
    free(manager->tasks);

    for (size_t i = 0; i < manager->record_count; ++i) {
        free(manager->data_blocks[i].data);
    }
    free(manager->records);
    free(manager->offsets);
    free(manager->keys);
    free(manager->data_blocks);

    free(manager);
}

void insert_task(TaskManager* manager, int id, TaskStatus status, int priority) {
    if (manager->task_count >= manager->task_capacity) {
        size_t new_capacity = manager->task_capacity == 0 ? 1 : manager->task_capacity * 2;
        Task** new_tasks = (Task**)realloc(manager->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) return;
        manager->tasks = new_tasks;
        manager->task_capacity = new_capacity;
    }

    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) return;

    task->id = id;
    task->status = status;
    task->priority = priority;

    manager->tasks[manager->task_count++] = task;
}

void insert_record(TaskManager* manager, long offset, int key, size_t data_size) {
    if (manager->record_count >= manager->record_capacity) {
        size_t new_capacity = manager->record_capacity == 0 ? 1 : manager->record_capacity * 2;
        Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
        long* new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
        DataBlock* new_data_blocks = (DataBlock*)realloc(manager->data_blocks, new_capacity * sizeof(DataBlock));
        if (!new_records || !new_offsets || !new_keys || !new_data_blocks) return;
        manager->records = new_records;
        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->data_blocks = new_data_blocks;
        manager->record_capacity = new_capacity;
    }

    Record record = { offset, key };
    DataBlock data_block = { data_size, malloc(data_size) };

    if (!record.data || !data_block.data) return;

    manager->records[manager->record_count] = record;
    manager->offsets[manager->record_count] = offset;
    manager->keys[manager->record_count] = key;
    manager->data_blocks[manager->record_count++] = data_block;
}

void set_random_record_value(TaskManager* manager, int min_val, int max_val) {
    srand(time(NULL));
    for (size_t i = 0; i < manager->record_count; ++i) {
        int random_value = rand() % (max_val - min_val + 1) + min_val;
        memcpy(manager->data_blocks[i].data, &random_value, sizeof(int));
    }
}
