#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

typedef struct DataRecord {
    int key;
    long offset;
    size_t size;
    void* data;
} DataRecord;

typedef struct RecordCollection {
    DataRecord** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (DataRecord**)calloc(initial_capacity, sizeof(DataRecord*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->data);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection* collection, int key, long offset, size_t size, void* data) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        DataRecord** new_records = (DataRecord**)realloc(collection->records, collection->capacity * 2 * sizeof(DataRecord*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->records = new_records;
        collection->capacity *= 2;
    }

    DataRecord* record = (DataRecord*)malloc(sizeof(DataRecord));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    record->key = key;
    record->offset = offset;
    record->size = size;
    record->data = malloc(size);
    if (!record->data) {
        free(record);
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }
    memcpy(record->data, data, size);

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void* get_record_data(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            void* data = collection->records[i]->data;
            pthread_mutex_unlock(&collection->lock);
            return data;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int free_record_data(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]->data);
            free(collection->records[i]);
            memmove(collection->records + i, collection->records + i + 1, (collection->count - i - 1) * sizeof(DataRecord*));
            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}
