#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
    record *data;
    size_t size;
    time_t last_modified;
    void *buffer;
} data_block;

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

void free_aligned(void *ptr) {
    free(ptr);
}

data_block* init_data_blocks(int num_records, int min_val, int max_val, size_t alignment) {
    data_block *blocks = (data_block*)malloc(num_records * sizeof(data_block));
    if (!blocks) {
        return NULL;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

    for (int i = 0; i < num_records; ++i) {
        blocks[i].offset = rand();
        blocks[i].key = rand() % (max_val - min_val + 1) + min_val;
        blocks[i].data = (record*)malloc(sizeof(record));
        if (!blocks[i].data) {
            free(blocks);
            return NULL;
        }
        blocks[i].data->value = blocks[i].key;

        pthread_mutex_init(&blocks[i].mutex, &attr);

        blocks[i].size = rand() % 1024 + 64; // Random size between 64 and 1088
        blocks[i].buffer = aligned_malloc(blocks[i].size, alignment);
        if (!blocks[i].buffer) {
            free(blocks[i].data);
            for (int j = 0; j < i; ++j) {
                pthread_mutex_destroy(&blocks[j].mutex);
                free_aligned(blocks[j].buffer);
                free(blocks[j].data);
            }
            free(blocks);
            return NULL;
        }

        time_t current_time;
        time(&current_time);
        blocks[i].last_modified = current_time;
    }

    pthread_mutexattr_destroy(&attr);
    return blocks;
}

void destroy_data_blocks(data_block *blocks, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_destroy(&blocks[i].mutex);
        free_aligned(blocks[i].buffer);
        free(blocks[i].data);
    }
    free(blocks);
}
