class AttackStrategy {
public:
    void selectAttack() {
        auto now = std::chrono::steady_clock::now();
        int selectedAttack = -1;
        double minTimeSinceLastUse = std::numeric_limits<double>::max();

        for (int i = 0; i < 4; ++i) {
            double timeSinceLastUse = std::chrono::duration_cast<std::chrono::seconds>(now - lastUseTimes[i]).count();
            if (timeSinceLastUse > minTimeSinceLastUse) {
                continue;
            }
            if (timeSinceLastUse == minTimeSinceLastUse && randomGenerator() < 0.5) {
                continue;
            }
            selectedAttack = i;
            minTimeSinceLastUse = timeSinceLastUse;
        }

        if (selectedAttack != -1) {
            lastUseTimes[selectedAttack] = now;
            executeAttack(selectedAttack);
        } else {
            log("No attack available, cooldowns too short.");
        }
