#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    JOB_STATUS_PENDING,
    JOB_STATUS_RUNNING,
    JOB_STATUS_COMPLETED,
    JOB_STATUS_FAILED
} JobStatus;

typedef struct Job {
    uint64_t id;
    time_t scheduled_time;
    JobStatus status;
    struct Job *next;
} Job;

typedef struct JobQueue {
    Job *head;
    pthread_mutex_t lock;
    size_t max_jobs;
    size_t current_jobs;
} JobQueue;

JobQueue* job_queue_create(size_t max_jobs) {
    JobQueue *queue = (JobQueue*)malloc(sizeof(JobQueue));
    if (!queue) return NULL;
    queue->max_jobs = max_jobs;
    queue->current_jobs = 0;
    pthread_mutex_init(&queue->lock, NULL);
    queue->head = NULL;
    return queue;
}

void job_queue_destroy(JobQueue *queue) {
    Job *job = queue->head;
    while (job) {
        Job *next = job->next;
        free(job);
        job = next;
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int job_add(JobQueue *queue, uint64_t id, time_t scheduled_time) {
    pthread_mutex_lock(&queue->lock);
    if (queue->current_jobs >= queue->max_jobs) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is full
    }
    Job *new_job = (Job*)malloc(sizeof(Job));
    if (!new_job) {
        pthread_mutex_unlock(&queue->lock);
        return -2; // Memory allocation failed
    }
    new_job->id = id;
    new_job->scheduled_time = scheduled_time;
    new_job->status = JOB_STATUS_PENDING;
    new_job->next = queue->head;
    queue->head = new_job;
    queue->current_jobs++;
    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

JobStatus job_get_status(JobQueue *queue, uint64_t id) {
    pthread_mutex_lock(&queue->lock);
    Job *job = queue->head;
    while (job) {
        if (job->id == id) {
            pthread_mutex_unlock(&queue->lock);
            return job->status;
        }
        job = job->next;
    }
    pthread_mutex_unlock(&queue->lock);
    return JOB_STATUS_FAILED; // Job not found
}

int job_update_status(JobQueue *queue, uint64_t id, JobStatus new_status) {
    pthread_mutex_lock(&queue->lock);
    Job *job = queue->head;
    while (job) {
        if (job->id == id) {
            job->status = new_status;
            pthread_mutex_unlock(&queue->lock);
            return 0; // Success
        }
        job = job->next;
    }
    pthread_mutex_unlock(&queue->lock);
    return -1; // Job not found
}

Job* job_list_pending(JobQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    Job *pending_jobs = NULL;
    Job *job = queue->head;
    while (job) {
        if (job->status == JOB_STATUS_PENDING) {
            Job *new_job = (Job*)malloc(sizeof(Job));
            if (!new_job) {
                pthread_mutex_unlock(&queue->lock);
                job_list_free(pending_jobs);
                return NULL; // Memory allocation failed
            }
            new_job->id = job->id;
            new_job->scheduled_time = job->scheduled_time;
            new_job->status = job->status;
            new_job->next = pending_jobs;
            pending_jobs = new_job;
        }
        job = job->next;
    }
    pthread_mutex_unlock(&queue->lock);
    return pending_jobs;
}

void job_list_free(Job *jobs) {
    while (jobs) {
        Job *next = jobs->next;
        free(jobs);
        jobs = next;
    }
}
