typedef struct element {
    char value;
    int index;
    double data;
} Element;

typedef struct tree_node {
    Element *data;
    struct tree_node *left, *right;
} TreeNode;

typedef struct tree {
    TreeNode *root;
} Tree;

TreeNode* create_node(Element *data) {
    TreeNode *node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!node) return NULL;
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

Tree* create_tree() {
    Tree *tree = (Tree*)malloc(sizeof(Tree));
    if (!tree) return NULL;
    tree->root = NULL;
    return tree;
}

TreeNode* insert(TreeNode *node, Element *data) {
    if (node == NULL) return create_node(data);
    if (data->index < node->data->index || 
        (data->index == node->data->index && data->value < node->data->value)) {
        node->left = insert(node->left, data);
    } else if (data->index > node->data->index || 
               (data->index == node->data->index && data->value > node->data->value)) {
        node->right = insert(node->right, data);
    }
    return node;
}

TreeNode* search(TreeNode *node, int index, char value) {
    if (node == NULL || (node->data->index == index && node->data->value == value))
        return node;
    if (index < node->data->index || 
        (index == node->data->index && value < node->data->value)) {
        return search(node->left, index, value);
    } else {
        return search(node->right, index, value);
    }
}

void free_node(TreeNode *node) {
    if (node) {
        free_node(node->left);
        free_node(node->right);
        free(node->data);
        free(node);
    }
}

void free_tree(Tree *tree) {
    if (tree) {
        free_node(tree->root);
        free(tree);
    }
}

// Additional functions for deletion, traversal, and concurrent access can be implemented here.

