#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the struct element
typedef struct {
    char value;
    int index;
    double d1, d2;
    enum Status { ACTIVE, INACTIVE } status;
    float *f_ptr;
    int int_index;
    long long timestamp;
} Element;

// Define the BST node
typedef struct TreeNode {
    Element data;
    struct TreeNode *left, *right;
} TreeNode;

// Function to create a new tree node
TreeNode* newNode(Element data) {
    TreeNode* temp = (TreeNode*)malloc(sizeof(TreeNode));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    temp->data = data;
    temp->left = temp->right = NULL;
    return temp;
}

// Function to insert a new node in BST
TreeNode* insertNode(TreeNode* root, Element data) {
    if (root == NULL) return newNode(data);

    if (data.index < root->data.index || (data.index == root->data.index && data.value < root->data.value)) {
        root->left = insertNode(root->left, data);
    } else if (data.index > root->data.index || (data.index == root->data.index && data.value > root->data.value)) {
        root->right = insertNode(root->right, data);
    }

    return root;
}

// Function to search a node in BST
TreeNode* searchNode(TreeNode* root, int index, char value) {
    if (root == NULL || root->data.index == index && root->data.value == value)
        return root;

    if (index < root->data.index || (index == root->data.index && value < root->data.value))
        return searchNode(root->left, index, value);

    return searchNode(root->right, index, value);
}

// Function to delete a node from BST
TreeNode* minValueNode(TreeNode* node) {
    TreeNode* current = node;
    while (current && current->left != NULL)
        current = current->left;

    return current;
}

TreeNode* deleteNode(TreeNode* root, int index, char value) {
    if (root == NULL) return root;

    if (index < root->data.index || (index == root->data.index && value < root->data.value))
        root->left = deleteNode(root->left, index, value);

    else if (index > root->data.index || (index == root->data.index && value > root->data.value))
        root->right = deleteNode(root->right, index, value);

    else {
        if (root->left == NULL) {
            TreeNode* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            TreeNode* temp = root->left;
            free(root);
            return temp;
        }

        TreeNode* temp = minValueNode(root->right);

        root->data = temp->data;

        root->right = deleteNode(root->right, temp->data.index, temp->data.value);
    }
    return root;
}

// Function to traverse the BST in-order
void inorderTraversal(TreeNode* root) {
    if (root != NULL) {
        inorderTraversal(root->left);
        printf("Index: %d, Value: %c\n", root->data.index, root->data.value);
        inorderTraversal(root->right);
    }
}

// Function to initialize the struct element with random values
void initElement(Element *elem, int range_min, int range_max) {
    elem->value = 'A' + rand() % 26;
    elem->index = rand() % (range_max - range_min + 1) + range_min;
    elem->d1 = ((double)rand() / RAND_MAX) * (range_max - range_min) + range_min;
    elem->d2 = ((double)rand() / RAND_MAX) * (range_max - range_min) + range_min;
    elem->status = rand() % 2 ? ACTIVE : INACTIVE;
    elem->f_ptr = (float*)malloc(sizeof(float));
    if (!elem->f_ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    *elem->f_ptr = ((double)rand() / RAND_MAX) * (range_max - range_min) + range_min;
    elem->int_index = rand() % (range_max - range_min + 1) + range_min;
    elem->timestamp = time(NULL);
}

// Main function to demonstrate the usage of BST operations
int main() {
    srand(time(NULL));
    TreeNode* root = NULL;

    Element elem;
    initElement(&elem, 0, 100);

    root = insertNode(root, elem);
    inorderTraversal(root);

    TreeNode* search_result = searchNode(root, elem.index, elem.value);
    if (search_result) {
        printf("Found: Index %d, Value %c\n", search_result->data.index, search_result->data.value);
    } else {
        printf("Not Found\n");
    }

    root = deleteNode(root, elem.index, elem.value);
    inorderTraversal(root);

    return 0;
}
```

