typedef struct {
    int value;
    size_t size;
} record;

record* records = NULL;
size_t capacity = 0;
size_t count = 0;

void init_records(size_t initial_capacity) {
    capacity = initial_capacity;
    records = (record*)malloc(capacity * sizeof(record));
}

void resize_records() {
    capacity *= 2;
    records = (record*)realloc(records, capacity * sizeof(record));
}

void add_record(int value, size_t size) {
    if (count >= capacity) {
        resize_records();
    }
    records[count].value = value;
    records[count].size = size;
    count++;
}

void set_random_value(size_t index, int min, int max) {
    if (index < count) {
        records[index].value = rand() % (max - min + 1) + min;
    }
}

void free_records() {
    free(records);
    records = NULL;
    capacity = 0;
    count = 0;
}

int main() {
    srand(time(NULL));
    init_records(10);

    add_record(42, 1024);
    set_random_value(0, 1, 100);

    free_records();
    return 0;
}
