#include <time.h>

typedef struct {
    int value;
    size_t size;
    void* offset;
    void* key;
} record;

record* create_records(size_t num_records, size_t data_size) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
        records[i].size = data_size;

        records[i].offset = malloc(data_size);
        if (!records[i].offset) {
            perror("Failed to allocate memory for offset");
            free_records(records, i);
            return NULL;
        }

        records[i].key = malloc(data_size);
        if (!records[i].key) {
            perror("Failed to allocate memory for key");
            free_records(records, i);
            return NULL;
        }
    }

    return records;
}

void free_records(record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].offset);
        free(records[i].key);
    }
    free(records);
}

