#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct element {
    char value;
    int index;
    double d_value;
} Element;

typedef struct tree_node {
    Element data;
    struct tree_node *left, *right;
} TreeNode;

typedef struct tree {
    TreeNode *root;
} Tree;

TreeNode* createNode(Element data) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

Tree* createTree() {
    Tree* tree = (Tree*)malloc(sizeof(Tree));
    if (tree == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    tree->root = NULL;
    return tree;
}

void insertNode(TreeNode** root, Element data) {
    if (*root == NULL) {
        *root = createNode(data);
        return;
    }

    if (data.index < (*root)->data.index)
        insertNode(&(*root)->left, data);
    else
        insertNode(&(*root)->right, data);
}

TreeNode* searchNode(TreeNode* root, int index) {
    if (root == NULL || root->data.index == index)
        return root;

    if (index < root->data.index)
        return searchNode(root->left, index);

    return searchNode(root->right, index);
}

void freeTree(TreeNode* node) {
    if (node != NULL) {
        freeTree(node->left);
        freeTree(node->right);
        free(node);
    }
}

int resolveHostname(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), sizeof(u_char)*4);

    freeaddrinfo(res);
    return 0;
}

int main() {
    Tree* bst = createTree();
    Element e1 = {'a', 1, 3.14};
    Element e2 = {'b', 2, 2.71};
    Element e3 = {'c', 3, 1.61};

    insertNode(&bst->root, e1);
    insertNode(&bst->root, e2);
    insertNode(&bst->root, e3);

    TreeNode* foundNode = searchNode(bst->root, 2);
    if (foundNode != NULL) {
        printf("Found: %c\n", foundNode->data.value);
    }

    u_char ip_address[4];
    if (resolveHostname("example.com", ip_address) == 0) {
        printf("IP Address: %d.%d.%d.%d\n", ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    freeTree(bst->root);
    free(bst);

    return 0;
}
