#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TASKS 100
#define MAX_METADATA 4

typedef enum { INT, FLOAT, CHAR_PTR } MetadataType;

typedef struct {
    int id;
    int priority;
    char status[20];
    void* metadata[MAX_METADATA];
    MetadataType type[MAX_METADATA];
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    int count;
    pthread_mutex_t lock;
} TaskManager;

TaskManager task_manager;

void init_task_manager() {
    memset(&task_manager, 0, sizeof(task_manager));
    pthread_mutex_init(&task_manager.lock, NULL);
}

void add_task(int id, int priority, char* status) {
    pthread_mutex_lock(&task_manager.lock);
    if (task_manager.count < MAX_TASKS) {
        Task* task = &task_manager.tasks[task_manager.count++];
        task->id = id;
        task->priority = priority;
        strcpy(task->status, status);
        for (int i = 0; i < MAX_METADATA; i++) {
            task->metadata[i] = NULL;
            task->type[i] = INT;
        }
    } else {
        printf("Task manager is full\n");
    }
    pthread_mutex_unlock(&task_manager.lock);
}

void* process_task(void* arg) {
    int index = *(int*)arg;
    Task* task = &task_manager.tasks[index];
    // Simulate task processing
    sleep(task->priority); // Higher priority tasks take longer to process
    printf("Task %d processed\n", task->id);
    return NULL;
}

void manage_tasks() {
    pthread_t threads[MAX_TASKS];
    int thread_ids[MAX_TASKS];

    for (int i = 0; i < task_manager.count; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, process_task, &thread_ids[i]) != 0) {
            printf("Failed to create thread\n");
        }
    }

    for (int i = 0; i < task_manager.count; i++) {
        pthread_join(threads[i], NULL);
    }
}

void free_task(int id) {
    pthread_mutex_lock(&task_manager.lock);
    for (int i = 0; i < task_manager.count; i++) {
        if (task_manager.tasks[i].id == id) {
            // Free metadata
            for (int j = 0; j < MAX_METADATA; j++) {
                if (task_manager.tasks[i].metadata[j] != NULL) {
                    free(task_manager.tasks[i].metadata[j]);
                }
            }
            // Move the last task to fill the gap
            memmove(&task_manager.tasks[i], &task_manager.tasks[i + 1], sizeof(Task) * (task_manager.count - i - 1));
            task_manager.count--;
            break;
        }
    }
    pthread_mutex_unlock(&task_manager.lock);
}

void free_all_tasks() {
    pthread_mutex_lock(&task_manager.lock);
    for (int i = 0; i < task_manager.count; i++) {
        // Free metadata
        for (int j = 0; j < MAX_METADATA; j++) {
            if (task_manager.tasks[i].metadata[j] != NULL) {
                free(task_manager.tasks[i].metadata[j]);
            }
        }
    }
    task_manager.count = 0;
    pthread_mutex_unlock(&task_manager.lock);
}

int main() {
    init_task_manager();
    add_task(1, 5, "Pending");
    add_task(2, 3, "Pending");
    manage_tasks();
    free_task(1);
    free_all_tasks();
    return 0;
}
