class DistributedHashTable {
public:
    static std::unique_ptr<DistributedHashTable> createDHT(size_t nodeSize, size_t partitionCount, size_t dataCapacity) {
        if (nodeSize == 0 || partitionCount == 0 || dataCapacity == 0) {
            return nullptr; // Invalid parameters
        }

        auto dht = std::make_unique<DistributedHashTable>();
        dht->nodeSize = nodeSize;
        dht->partitionCount = partitionCount;
        dht->dataCapacity = dataCapacity;

        // Initialize partitions and nodes
        dht->partitions.resize(partitionCount);
        for (auto& partition : dht->partitions) {
            partition.nodes.reserve(nodeSize);
        }

        return dht;
    }

private:
    size_t nodeSize;
    size_t partitionCount;
    size_t dataCapacity;
    std::vector<std::vector<Node>> partitions;

    DistributedHashTable() = default; // Private constructor for singleton pattern
};

int main() {
    auto dht = DistributedHashTable::createDHT(10, 5, 1000);
    if (dht) {
        std::cout << "DHT created successfully." << std::endl;
    } else {
        std::cout << "Failed to create DHT." << std::endl;
    }
    return 0;
}
