#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/sha.h>

#define MAX_CONCURRENT_LOGS 10000

typedef struct {
    int value;
    size_t size;
} Record;

typedef struct {
    long *offset;
    int *key;
    Record *record;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int log_count;
} LoggingSystem;

LoggingSystem *init_logging_system(int initial_size) {
    LoggingSystem *sys = (LoggingSystem *)malloc(sizeof(LoggingSystem));
    if (!sys) return NULL;

    sys->offset = (long *)calloc(initial_size, sizeof(long));
    sys->key = (int *)calloc(initial_size, sizeof(int));
    sys->record = (Record *)calloc(initial_size, sizeof(Record));
    if (!sys->offset || !sys->key || !sys->record) {
        free(sys);
        return NULL;
    }

    pthread_mutex_init(&sys->mutex, NULL);
    pthread_cond_init(&sys->cond, NULL);
    sys->log_count = 0;

    return sys;
}

void destroy_logging_system(LoggingSystem *sys) {
    if (sys) {
        free(sys->offset);
        free(sys->key);
        for (int i = 0; i < sys->log_count; i++) {
            free(sys->record[i].data);
        }
        free(sys->record);
        pthread_mutex_destroy(&sys->mutex);
        pthread_cond_destroy(&sys->cond);
        free(sys);
    }
}

void log_event(LoggingSystem *sys, int event_type, int id) {
    pthread_mutex_lock(&sys->mutex);
    while (sys->log_count >= MAX_CONCURRENT_LOGS) {
        pthread_cond_wait(&sys->cond, &sys->mutex);
    }

    sys->record[sys->log_count].value = event_type;
    sys->record[sys->log_count].size = sizeof(int);
    sys->key[sys->log_count] = id;
    sys->offset[sys->log_count] = time(NULL);

    sys->log_count++;
    pthread_cond_signal(&sys->cond);
    pthread_mutex_unlock(&sys->mutex);
}

void set_random_values(LoggingSystem *sys, int min_value, int max_value) {
    pthread_mutex_lock(&sys->mutex);
    for (int i = 0; i < sys->log_count; i++) {
        sys->record[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    pthread_mutex_unlock(&sys->mutex);
}

void log_execution_time(LoggingSystem *sys, int verbosity) {
    if (verbosity > 0) {
        printf("Execution time: %ld\n", time(NULL));
    }
}

unsigned char* compute_sha256(const char *input, size_t length) {
    unsigned char *hash = (unsigned char *)malloc(SHA256_DIGEST_LENGTH);
    if (!hash) return NULL;

    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, input, length);
    SHA256_Final(hash, &sha256);

    return hash;
}

void free_sha256(unsigned char *hash) {
    if (hash) free(hash);
}
