void parse_config_file(const char *config_path, int *min_val, int *max_val) {
    FILE *file = fopen(config_path, "r");
    if (!file) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }
    fscanf(file, "%d %d", min_val, max_val);
    fclose(file);
}

void log_message(const char *log_path, const char *message) {
    FILE *log_file = fopen(log_path, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s: %s\n", ctime(&now), message);
    fclose(log_file);
}

int find_max(int *array, int size) {
    if (size <= 0) return -1;
    int max_val = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max_val) {
            max_val = array[i];
        }
    }
    return max_val;
}

void process_and_find_max(const char *config_path, const char *log_path, int input_size) {
    int min_val, max_val;
    parse_config_file(config_path, &min_val, &max_val);

    long *offsets = (long *)malloc(input_size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return;
    }

    int *keys = (int *)malloc(input_size * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return;
    }

    record *records = (record *)malloc(input_size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < input_size; i++) {
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i];
        records[i].size = BUFFER_SIZE;
        records[i].offset = (char *)malloc(BUFFER_SIZE);
        if (!records[i].offset) {
            for (int j = 0; j < i; j++) free(records[j].offset);
            free(offsets);
            free(keys);
            free(records);
            perror("Failed to allocate memory for record buffer");
            return;
        }
        snprintf(records[i].offset, BUFFER_SIZE, "PFX_%d", keys[i]);
    }

    int *input_array = (int *)malloc(input_size * sizeof(int));
    if (!input_array) {
        for (int i = 0; i < input_size; i++) free(records[i].offset);
        free(offsets);
        free(keys);
        free(records);
        perror("Failed to allocate memory for input array");
        return;
    }

    for (int i = 0; i < input_size; i++) {
        scanf("%d", &input_array[i]);
    }

    int max_val = find_max(input_array, input_size);
    log_message(log_path, "Maximum value found: %d", max_val);

    for (int i = 0; i < input_size; i++) free(records[i].offset);
    free(offsets);
    free(keys);
    free(records);
    free(input_array);
}

int main() {
    const char *config_path = "config.txt";
    const char *log_path = "log.txt";
    int input_size;

    printf("Enter the number of integers: ");
    scanf("%d", &input_size);

    process_and_find_max(config_path, log_path, input_size);

    return 0;
}
