#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <time.h>

typedef struct {
    char* filename;
    int length;
    FILE* file_ptr;
} file_info;

void log_message(const char* message) {
    time_t now = time(NULL);
    fprintf(stderr, "%s: %s\n", ctime(&now), message);
}

file_info* process_and_filter_data(const char* directory_path, const char* log_file_path, int (*filter_criteria)(const file_info*)) {
    DIR* dir;
    struct dirent* ent;
    file_info* files = NULL;
    int count = 0;

    if ((dir = opendir(directory_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", directory_path, ent->d_name);
            FILE* file = fopen(path, "r");
            if (file) {
                struct stat st;
                if (fstat(fileno(file), &st) == 0) {
                    if (filter_criteria((file_info){ent->d_name, st.st_size, file})) {
                        files = realloc(files, (count + 1) * sizeof(file_info));
                        if (!files) {
                            log_message("Memory allocation failed");
                            return NULL;
                        }
                        files[count++] = (file_info){strdup(ent->d_name), st.st_size, file};
                    } else {
                        fclose(file);
                    }
                } else {
                    log_message("Failed to get file stats");
                    fclose(file);
                }
            } else {
                log_message("Failed to open file");
            }
        }
        closedir(dir);
    } else {
        log_message("Failed to open directory");
        return NULL;
    }

    if (log_file_path) {
        FILE* log_file = fopen(log_file_path, "a");
        if (log_file) {
            fprintf(log_file, "Processed %d files\n", count);
            fclose(log_file);
        } else {
            log_message("Failed to open log file");
        }
    }

    return files;
}

int main() {
    // Example usage
    file_info* files = process_and_filter_data("/path/to/directory", "/path/to/logfile.log", NULL);
    if (files) {
        for (int i = 0; files[i].filename != NULL; i++) {
            printf("File: %s, Size: %d\n", files[i].filename, files[i].length);
            fclose(files[i].file_ptr);
            free(files[i].filename);
        }
        free(files);
    }
    return 0;
}
