    // Allocate memory for arrays and structures
    long *offsets = malloc(100 * sizeof(long));
    int *keys = malloc(100 * sizeof(int));
    Record *records = malloc(100 * sizeof(Record));

    // Initialize records with random values and offsets
    for (int i = 0; i < 100; i++) {
        records[i].value = generate_random(min_val, max_val);
        records[i].size = sizeof(int);
        records[i].offset = &offsets[i];
    }

    // Read integers from standard input and store them in an array
    int *input_array = malloc(100 * sizeof(int));
    for (int i = 0; i < 100; i++) {
        scanf("%d", &input_array[i]);
    }

    // Insert integers into the red-black tree
    // (Assuming a red-black tree implementation is available)

    // Find and print the largest integer in the array
    int max_value = input_array[0];
    for (int i = 1; i < 100; i++) {
        if (input_array[i] > max_value) {
            max_value = input_array[i];
