#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* str;
    int num;
    float fnum;
} CustomData;

typedef struct Node {
    CustomData data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t log_count;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    list->log_count = 0;
    return list;
}

void free_list(DynamicList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->data.str);
        free(current);
        current = next;
    }
    free(list);
}

Node* create_node(const char* str, int num, float fnum) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data.str = strdup(str);
    node->data.num = num;
    node->data.fnum = fnum;
    node->next = NULL;
    return node;
}

void add_entry(DynamicList* list, const char* str, int num, float fnum) {
    Node* new_node = create_node(str, num, fnum);
    if (!new_node) return;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    list->log_count++;
}

void update_entry(DynamicList* list, size_t index, const char* str, int num, float fnum) {
    Node* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }
    if (!current) return;
    free(current->data.str);
    current->data.str = strdup(str);
    current->data.num = num;
    current->data.fnum = fnum;
    list->log_count++;
}

CustomData* get_entry(DynamicList* list, size_t index) {
    Node* current = list->head;
    for (size_t i = 0; i < index && current; i++) {
        current = current->next;
    }
    if (!current) return NULL;
    return &current->data;
}

void set_random_values(CustomData* data, int min_num, int max_num, float min_fnum, float max_fnum) {
    srand(time(NULL));
    data->num = rand() % (max_num - min_num + 1) + min_num;
    data->fnum = ((float)rand()) / RAND_MAX * (max_fnum - min_fnum) + min_fnum;
}

void log_operation(DynamicList* list, const char* operation) {
    printf("%s operation performed. Total operations: %zu\n", operation, list->log_count);
}
