#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    size_t size;
    time_t timestamp;
    int* key_ptr;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
} log_entry;

log_entry* create_log(size_t initial_capacity) {
    log_entry* log = (log_entry*)malloc(sizeof(log_entry));
    if (!log) return NULL;

    log->offsets = (long*)calloc(initial_capacity, sizeof(long));
    log->keys = (int*)calloc(initial_capacity, sizeof(int));
    log->records = (record**)calloc(initial_capacity, sizeof(record*));
    log->capacity = initial_capacity;
    log->size = 0;

    if (!log->offsets || !log->keys || !log->records) {
        free(log);
        return NULL;
    }

    return log;
}

void destroy_log(log_entry* log) {
    for (size_t i = 0; i < log->size; ++i) {
        free(log->records[i]);
    }
    free(log->offsets);
    free(log->keys);
    free(log->records);
    free(log);
}

int insert_record(log_entry* log, int key, record* rec) {
    if (log->size >= log->capacity) {
        size_t new_capacity = log->capacity * 2;
        long* new_offsets = (long*)realloc(log->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(log->keys, new_capacity * sizeof(int));
        record** new_records = (record**)realloc(log->records, new_capacity * sizeof(record*));

        if (!new_offsets || !new_keys || !new_records) {
            return -1;
        }

        log->offsets = new_offsets;
        log->keys = new_keys;
        log->records = new_records;
        log->capacity = new_capacity;
    }

    log->offsets[log->size] = rec->value;
    log->keys[log->size] = key;
    log->records[log->size++] = rec;

    return 0;
}

record* get_record(log_entry* log, int event_id) {
    for (size_t i = 0; i < log->size; ++i) {
        if (log->keys[i] == event_id) {
            return log->records[i];
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    log_entry* my_log = create_log(10);

    record* new_record = (record*)malloc(sizeof(record));
    new_record->value = rand();
    new_record->size = sizeof(int);
    new_record->timestamp = time(NULL);
    new_record->key_ptr = &my_log->keys[0];

    insert_record(my_log, 1, new_record);

    record* retrieved_record = get_record(my_log, 1);
    if (retrieved_record) {
        printf("Retrieved value: %d\n", retrieved_record->value);
    }

    destroy_log(my_log);
    free(new_record);

    return 0;
}
