typedef struct {
    char *timestamp;
    int id;
    char *data;
} Record;

Record* allocate_records(int count) {
    return (Record*)malloc(count * sizeof(Record));
}

void initialize_record(Record *record, const char *timestamp, int id, const char *data) {
    record->timestamp = strdup(timestamp);
    record->id = id;
    record->data = strdup(data);
}

void free_records(Record *records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].timestamp);
        free(records[i].data);
    }
    free(records);
}

int load_data_from_csv(const char *filename, Record **records, int *count) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char*)malloc(file_size + 1);
    fread(buffer, 1, file_size, file);
    buffer[file_size] = '\0';
    fclose(file);

    int lines = 0;
    for (int i = 0; buffer[i]; i++) {
        if (buffer[i] == '\n') lines++;
    }

    *records = allocate_records(lines);
    *count = lines;

    char *line = strtok(buffer, "\n");
    for (int i = 0; line != NULL; i++, line = strtok(NULL, "\n")) {
        char *token = strtok(line, ",");
        if (token) initialize_record(&(*records)[i], token, atoi(strtok(NULL, ",")), strtok(NULL, ","));
    }

    free(buffer);
    return lines;
}

int main() {
    Record *records;
    int count;

    if (load_data_from_csv("data.csv", &records, &count) < 0) {
        printf("Failed to load data from CSV.\n");
        return 1;
    }

    // Use records...

    free_records(records, count);
    return 0;
}
