#include <sys/resource.h>

void adjust_fd_limits(pid_t child_pid) {
    struct rlimit rl;
    int max_fds;

    // Get the current soft limit for file descriptors
    if (getrlimit(RLIMIT_NOFILE, &rl) == -1) {
        perror("Failed to get file descriptor limits");
        return;
    }

    // Calculate a safe upper limit for child processes
    max_fds = rl.rlim_cur / 2;

    // Set the soft and hard limits for the child process
    rl.rlim_cur = max_fds;
    rl.rlim_max = max_fds;
    if (setrlimit(RLIMIT_NOFILE, &rl) == -1) {
        perror("Failed to set file descriptor limits");
        return;
    }

    // Close unnecessary file descriptors in the parent process
    for (int fd = 3; fd < rl.rlim_cur; ++fd) {
        close(fd);
    }

    // Log the adjustment for auditing purposes
    FILE *log_file = fopen("audit.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "Child process %d: File descriptor limits adjusted to %d\n", child_pid, max_fds);
        fclose(log_file);
    }
}

int main() {
    pid_t pid = fork();

    if (pid == -1) {
        perror("Failed to fork");
        return 1;
    } else if (pid == 0) {
        // Child process
        adjust_fd_limits(getpid());
        // Continue with child-specific operations
    } else {
        // Parent process
        // Perform parent-specific operations
    }

    return 0;
}
