typedef struct {
    KeyRecord *keys;
    OffsetRecord *offsets;
    size_t num_keys;
    size_t num_offsets;
} ConfigRecord;

ConfigRecord* allocate_config_records(size_t n, size_t m, size_t p, int min_key, int max_key, long min_offset, long max_offset) {
    ConfigRecord *records = (ConfigRecord*)malloc(n * sizeof(ConfigRecord));
    if (!records) return NULL;

    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        records[i].keys = (KeyRecord*)malloc(m * sizeof(KeyRecord));
        records[i].offsets = (OffsetRecord*)malloc(p * sizeof(OffsetRecord));
        if (!records[i].keys || !records[i].offsets) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(records[j].keys);
                free(records[j].offsets);
            }
            free(records);
            return NULL;
        }

        records[i].num_keys = m;
        records[i].num_offsets = p;

        // Populate keys with unique random values
        for (size_t j = 0; j < m; ++j) {
            int key;
            do {
                key = rand() % (max_key - min_key + 1) + min_key;
            } while (is_key_unique(records, i, key));
            records[i].keys[j].key = key;
        }

        // Populate offsets with random values
        for (size_t j = 0; j < p; ++j) {
            records[i].offsets[j].offset = rand() % (max_offset - min_offset + 1) + min_offset;
        }
    }

    return records;
}

int is_key_unique(ConfigRecord *records, size_t record_index, int key) {
    for (size_t i = 0; i < record_index; ++i) {
        for (size_t j = 0; j < records[i].num_keys; ++j) {
            if (records[i].keys[j].key == key) return 1;
        }
    }
    return 0;
}

void free_config_records(ConfigRecord *records, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        free(records[i].keys);
        free(records[i].offsets);
    }
    free(records);
}
