#define MAX_RECORD_SIZE 1024
#define MAX_TIMESTAMP_RANGE 3600 // 1 hour

typedef struct {
    time_t timestamp;
    int id;
    char* query;
} Record;

void initialize_record(Record* record, int min_id, int max_id, time_t past_timestamp, time_t future_timestamp) {
    record->timestamp = past_timestamp + rand() % (future_timestamp - past_timestamp);
    record->id = min_id + rand() % (max_id - min_id);
    record->query = malloc(MAX_RECORD_SIZE * sizeof(char));
    if (record->query == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memset(record->query, 0, MAX_RECORD_SIZE);
}

void free_record(Record* record) {
    free(record->query);
}

int load_data_from_json(const char* filename, Record** records, int* count, size_t max_size) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open JSON file");
        return -1;
    }

    struct json_object* root = json_tokener_parse_file(file);
    fclose(file);

    if (root == NULL) {
        fprintf(stderr, "Failed to parse JSON\n");
        return -1;
    }

    struct json_array* array = json_object_get_array(root);
    *count = json_array_length(array);

    size_t total_size = (*count) * sizeof(Record);
    if (total_size > max_size) {
        fprintf(stderr, "Total allocated size exceeds maximum limit\n");
        json_object_put(root);
        return -1;
    }

    *records = malloc(total_size);
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        json_object_put(root);
        return -1;
    }

    for (int i = 0; i < *count; i++) {
        struct json_object* obj = json_array_get_idx(array, i);
        struct json_object* timestamp_obj, *id_obj, *query_obj;

        if (!json_object_object_get_ex(obj, "timestamp", &timestamp_obj) ||
            !json_object_object_get_ex(obj, "id", &id_obj) ||
            !json_object_object_get_ex(obj, "query", &query_obj)) {
            fprintf(stderr, "Malformed JSON data\n");
            free(*records);
            json_object_put(root);
            return -1;
        }

        time_t timestamp = (time_t)json_object_get_int(timestamp_obj);
        int id = json_object_get_int(id_obj);
        const char* query = json_object_get_string(query_obj);

        (*records)[i].timestamp = timestamp;
        (*records)[i].id = id;
        (*records)[i].query = malloc(strlen(query) + 1);
        if ((*records)[i].query == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; j++) {
                free((*records)[j].query);
            }
            free(*records);
            json_object_put(root);
            return -1;
        }
        strcpy((*records)[i].query, query);
    }

    json_object_put(root);
    return 0;
}

void free_records(Record* records, int count) {
    for (int i = 0; i < count; i++) {
        free_record(&records[i]);
    }
    free(records);
}
