#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char *name;
    int ref_count;
} item;

typedef struct {
    item **items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} item_collection;

item* create_item(double value, const char *name) {
    item *new_item = (item *)malloc(sizeof(item));
    if (!new_item) {
        perror("Failed to allocate memory for new item");
        return NULL;
    }
    new_item->value = value;
    new_item->name = strdup(name);
    if (!new_item->name) {
        free(new_item);
        perror("Failed to allocate memory for item name");
        return NULL;
    }
    new_item->ref_count = 0;
    return new_item;
}

void destroy_item(item *item) {
    free(item->name);
    free(item);
}

item_collection* create_collection(size_t initial_capacity) {
    item_collection *collection = (item_collection *)malloc(sizeof(item_collection));
    if (!collection) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }
    collection->items = (item **)calloc(initial_capacity, sizeof(item *));
    if (!collection->items) {
        free(collection);
        perror("Failed to allocate memory for items array");
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(item_collection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        destroy_item(collection->items[i]);
    }
    free(collection->items);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_item(item_collection *collection, item *item) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        item **new_items = (item **)realloc(collection->items, new_capacity * sizeof(item *));
        if (!new_items) {
            pthread_mutex_unlock(&collection->lock);
            perror("Failed to reallocate memory for items array");
            return -1;
        }
        collection->items = new_items;
        collection->capacity = new_capacity;
    }
    collection->items[collection->count++] = item;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_item(item_collection *collection, const char *name) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->items[i]->name, name) == 0) {
            destroy_item(collection->items[i]);
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->items[j] = collection->items[j + 1];
            }
            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    fprintf(stderr, "Item with name '%s' not found\n", name);
    return -1;
}

int update_item(item_collection *collection, const char *name, double new_value) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->items[i]->name, name) == 0) {
            collection->items[i]->value = new_value;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    fprintf(stderr, "Item with name '%s' not found\n", name);
    return -1;
}

void increment_ref_count(item_collection *collection, const char *name) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->items[i]->name, name) == 0) {
            ++collection->items[i]->ref_count;
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    fprintf(stderr, "Item with name '%s' not found\n", name);
}

void decrement_ref_count(item_collection *collection, const char *name) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->items[i]->name, name) == 0) {
            --collection->items[i]->ref_count;
            if (collection->items[i]->ref_count <= 0) {
                destroy_item(collection->items[i]);
                for (size_t j = i; j < collection->count - 1; ++j) {
                    collection->items[j] = collection->items[j + 1];
                }
                --collection->count;
            }
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    fprintf(stderr, "Item with name '%s' not found\n", name);
}

void garbage_collection(item_collection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i]->ref_count <= 0) {
            destroy_item(collection->items[i]);
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->items[j] = collection->items[j + 1];
            }
            --collection->count;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}
