import java.util.concurrent.*;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class WebAppServer {
    private static final int POOL_SIZE = 10;
    private static final long MEMORY_POOL_LIMIT = 1024 * 1024 * 1024; // 1 GB
    private static final long REQUEST_MEMORY_LIMIT = 1024 * 1024; // 1 MB

    private ExecutorService workerThreadPool;
    private BlockingQueue<HttpRequest> requestQueue;
    private MemoryPool memoryPool;

    public WebAppServer() {
        this.workerThreadPool = Executors.newFixedThreadPool(POOL_SIZE);
        this.requestQueue = new LinkedBlockingQueue<>();
        this.memoryPool = new MemoryPool(MEMORY_POOL_LIMIT, REQUEST_MEMORY_LIMIT);
    }

    public void start() {
        for (int i = 0; i < POOL_SIZE; i++) {
            workerThreadPool.submit(new Worker());
        }
    }

    public void stop() {
        workerThreadPool.shutdown();
        try {
            if (!workerThreadPool.awaitTermination(60, TimeUnit.SECONDS)) {
                workerThreadPool.shutdownNow();
            }
        } catch (InterruptedException e) {
            workerThreadPool.shutdownNow();
        }
    }

    public void enqueueRequest(HttpRequest request) throws InterruptedException {
        memoryPool.allocate(request);
        requestQueue.put(request);
    }

    private class Worker implements Runnable {
        @Override
        public void run() {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    HttpRequest request = requestQueue.take();
                    HttpClient client = HttpClient.newHttpClient();
                    HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
                    memoryPool.deallocate(request);
                    // Process the response
                } catch (InterruptedException | IOException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    private class MemoryPool {
        private final long totalMemory;
        private final long requestMemoryLimit;
        private long usedMemory;

        public MemoryPool(long totalMemory, long requestMemoryLimit) {
            this.totalMemory = totalMemory;
            this.requestMemoryLimit = requestMemoryLimit;
            this.usedMemory = 0;
        }

        public synchronized void allocate(HttpRequest request) throws InterruptedException {
            while (usedMemory + requestMemoryLimit > totalMemory) {
                wait();
            }
            usedMemory += requestMemoryLimit;
        }

        public synchronized void deallocate(HttpRequest request) {
            usedMemory -= requestMemoryLimit;
            notifyAll();
        }
    }
}
