#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    size_t size;
} record;

union find {
    int parent;
    int rank;
};

int find(union find *uf, int i) {
    if (uf[i].parent != i)
        uf[i].parent = find(uf, uf[i].parent);
    return uf[i].parent;
}

void union_set(union find *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

int process_files(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <binary_file> <csv_file> <output_file>\n", argv[0]);
        return 1;
    }

    const char *binary_file = argv[1];
    const char *csv_file = argv[2];
    const char *output_file = argv[3];

    // Open files
    FILE *bin_fp = fopen(binary_file, "rb");
    if (!bin_fp) {
        perror("Failed to open binary file");
        return 1;
    }

    FILE *csv_fp = fopen(csv_file, "r");
    if (!csv_fp) {
        perror("Failed to open CSV file");
        fclose(bin_fp);
        return 1;
    }

    FILE *out_fp = fopen(output_file, "w");
    if (!out_fp) {
        perror("Failed to open output file");
        fclose(bin_fp);
        fclose(csv_fp);
        return 1;
    }

    // Memory allocation
    size_t num_records = 1024; // Initial guess
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        fclose(bin_fp);
        fclose(csv_fp);
        fclose(out_fp);
        return 1;
    }

    union find *uf = malloc(1024 * sizeof(union find)); // Initial guess
    if (!uf) {
        perror("Failed to allocate memory for union-find structure");
        free(records);
        fclose(bin_fp);
        fclose(csv_fp);
        fclose(out_fp);
        return 1;
    }

    // Initialize union-find structure
    for (size_t i = 0; i < 1024; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }

    // Read binary file and parse records
    size_t record_count = 0;
    while (fread(&records[record_count], sizeof(record), 1, bin_fp) == 1) {
        if (record_count >= num_records - 1) {
            num_records *= 2;
            records = realloc(records, num_records * sizeof(record));
            uf = realloc(uf, num_records * sizeof(union find));
            if (!records || !uf) {
                perror("Failed to reallocate memory");
                free(records);
                free(uf);
                fclose(bin_fp);
                fclose(csv_fp);
                fclose(out_fp);
                return 1;
            }
        }

        // Union-find operations
        union_set(uf, records[record_count].value % num_records, (records[record_count].value + 1) % num_records);

        record_count++;
    }

    // Process CSV file and write output
    int key;
    while (fscanf(csv_fp, "%d", &key) == 1) {
        fprintf(out_fp, "Key: %d, Parent: %d\n", key, find(uf, key));
    }

    // Clean up
    free(records);
    free(uf);
    fclose(bin_fp);
    fclose(csv_fp);
    fclose(out_fp);

    return 0;
}

int main(int argc, char *argv[]) {
    return process_files(argc, argv);
}
