int insert_into_hash_table(hash_table* table, int key, void* value) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->num_buckets;
    if (!table->buckets[index]) {
        table->buckets[index] = (hash_table_entry*)malloc(sizeof(hash_table_entry));
        if (!table->buckets[index]) {
            pthread_mutex_unlock(&table->lock);
            return -1; // Memory allocation failed
        }
    }
    table->buckets[index]->key = key;
    table->buckets[index]->value = value;
    pthread_mutex_unlock(&table->lock);
    return 0; // Success
}
