const crypto = require('crypto');

function generatePEMCertificate(oauthRequest) {
  const { privateKeyUrl, certificateUrl, version } = oauthRequest;
  const cacheKey = `${privateKeyUrl}-${certificateUrl}-${version}`;
  let cachedCertificate;

  function fetchResource(url) {
    return new Promise((resolve, reject) => {
      https.get(url, (res) => {
        if (res.statusCode !== 200) {
          reject(new Error(`Failed to fetch resource: ${url}`));
        }
        const data = [];
        res.on('data', (chunk) => data.push(chunk));
        res.on('end', () => resolve(Buffer.concat(data)));
      }).on('error', (err) => reject(err));
    });
  }

  function parseResource(data, format) {
    switch (format) {
      case 'json':
        return JSON.parse(data.toString());
      case 'xml':
        // Implement XML parsing logic
        break;
      default:
        throw new Error(`Unsupported format: ${format}`);
    }
  }

  function createPEMCertificate(privateKey, certificate) {
    const pem = `-----BEGIN PRIVATE KEY-----
${privateKey}
-----END PRIVATE KEY-----
-----BEGIN CERTIFICATE-----
${certificate}
-----END CERTIFICATE-----`;
    return pem;
  }

  async function fetchAndCacheCertificate() {
    try {
      const [privateKeyData, certificateData] = await Promise.all([
        fetchResource(privateKeyUrl),
        fetchResource(certificateUrl)
      ]);
      const privateKey = parseResource(privateKeyData, 'json').key;
      const certificate = parseResource(certificateData, 'json').certificate;
      cachedCertificate = createPEMCertificate(privateKey, certificate);
    } catch (error) {
      console.error('Error fetching or parsing resources:', error);
      throw error;
    }
  }

  async function getCertificate() {
    if (!cachedCertificate) {
      await fetchAndCacheCertificate();
    }
    return cachedCertificate;
  }

  return getCertificate();
}
