int error_flag = 0;

Record* initialize_records(int num_offsets, int num_keys, int min_value, int max_value) {
    if (num_keys > MAX_KEYS) {
        error_flag = 1;
        return NULL;
    }

    long* offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        error_flag = 1;
        return NULL;
    }

    int* keys = malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        error_flag = 1;
        return NULL;
    }

    Record* records = malloc(num_offsets * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        error_flag = 1;
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % num_keys;
        records[i].value = malloc(sizeof(long));
        if (!records[i].value) {
            error_flag = 1;
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(records[j].value);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        *records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = keys[offsets[i]];
        records[i].status = 'U';
    }

    // Clean up temporary keys array
    free(keys);

    return records;
}
