#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    long long value;
    void* custom_data;
    int ref_count;
    struct Node* next;
} Node;

Node* create_node(long long value, void* custom_data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node\n");
        return NULL;
    }
    new_node->value = value;
    new_node->custom_data = custom_data;
    new_node->ref_count = 1;
    new_node->next = NULL;
    return new_node;
}

void increment_ref_count(Node* node) {
    if (node) {
        pthread_mutex_lock(&node->mutex);
        node->ref_count++;
        pthread_mutex_unlock(&node->mutex);
    }
}

void decrement_ref_count(Node* node, Node** head) {
    if (node) {
        pthread_mutex_lock(&node->mutex);
        node->ref_count--;
        if (node->ref_count == 0) {
            if (node == *head) {
                *head = node->next;
            } else {
                Node* current = *head;
                while (current && current->next != node) {
                    current = current->next;
                }
                if (current) {
                    current->next = node->next;
                }
            }
            free(node);
        }
        pthread_mutex_unlock(&node->mutex);
    }
}

void insert_node(Node** head, long long value, void* custom_data) {
    Node* new_node = create_node(value, custom_data);
    if (new_node) {
        pthread_mutex_lock(&(*head)->mutex);
        new_node->next = *head;
        *head = new_node;
        increment_ref_count(new_node);
        pthread_mutex_unlock(&(*head)->mutex);
    }
}

void delete_node(Node** head, long long value) {
    Node* current = *head;
    Node* previous = NULL;
    while (current && current->value != value) {
        previous = current;
        current = current->next;
    }
    if (current) {
        decrement_ref_count(current, head);
    }
}

int main() {
    Node* head = create_node(10, NULL);
    insert_node(&head, 20, NULL);
    delete_node(&head, 10);
    return 0;
}
