#include <stdlib.h>
#include <pthread.h>
#include <libpmemobj.h>

#define LAYOUT_NAME "item_store"

struct item {
    double value;
    char *key;
    int ref_count;
};

typedef struct {
    PMEMobjpool *pop;
    pthread_rwlock_t lock;
} item_store;

PMEMoid create_item(PMEMobjpool *pop, double value, const char *key) {
    PMEMoid oid = pmemobj_alloc(pop, sizeof(struct item), LAYOUT_NAME, 0666, NULL);
    if (OID_IS_NULL(oid)) {
        return OID_NULL;
    }
    struct item *item = pmemobj_direct(oid);
    item->value = value;
    item->key = strdup(key);
    item->ref_count = 1;
    return oid;
}

void destroy_item(PMEMobjpool *pop, PMEMoid oid) {
    if (OID_IS_NULL(oid)) {
        return;
    }
    struct item *item = pmemobj_direct(oid);
    free(item->key);
    pmemobj_free(&oid);
}

void increment_ref_count(PMEMobjpool *pop, PMEMoid oid) {
    pthread_rwlock_wrlock(&pop->lock);
    struct item *item = pmemobj_direct(oid);
    item->ref_count++;
    pthread_rwlock_unlock(&pop->lock);
}

void decrement_ref_count(PMEMobjpool *pop, PMEMoid oid) {
    pthread_rwlock_wrlock(&pop->lock);
    struct item *item = pmemobj_direct(oid);
    item->ref_count--;
    if (item->ref_count == 0) {
        destroy_item(pop, oid);
    }
    pthread_rwlock_unlock(&pop->lock);
}

void update_item(PMEMobjpool *pop, PMEMoid oid, double value, const char *key) {
    pthread_rwlock_wrlock(&pop->lock);
    struct item *item = pmemobj_direct(oid);
    free(item->key);
    item->value = value;
    item->key = strdup(key);
    pthread_rwlock_unlock(&pop->lock);
}

void *item_store_init(size_t size) {
    PMEMobjpool *pop = pmemobj_create("item_store", LAYOUT_NAME, size, 0666);
    if (pop == NULL) {
        return NULL;
    }
    item_store *store = malloc(sizeof(item_store));
    store->pop = pop;
    pthread_rwlock_init(&store->lock, NULL);
    return store;
}

void item_store_destroy(void *store_ptr) {
    item_store *store = (item_store *)store_ptr;
    pthread_rwlock_destroy(&store->lock);
    pmemobj_close(store->pop);
    free(store);
}
