#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef union {
    int i;
    double d;
} data;

typedef struct node {
    unsigned long timestamp;
    int event_type;
    data data;
    struct node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_node(LinkedList* list, unsigned long timestamp, int event_type, data data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->timestamp = timestamp;
    new_node->event_type = event_type;
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

int get_list_size(LinkedList* list) {
    int size = 0;
    Node* current = list->head;
    while (current != NULL) {
        size++;
        current = current->next;
    }
    return size;
}

void free_linked_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
