typedef struct {
    char identifier[100];
    int hash;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateAndRefreshNFACRCIndications(int listSize, const char* inputString, const char* charset) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    srand(time(NULL));

    for (int i = 0; i < listSize; i++) {
        // Generate unique identifier
        snprintf(list[i].identifier, sizeof(list[i].identifier), "%.*s", 10, charset + rand() % strlen(charset));
        while (i > 0 && strcmp(list[i].identifier, list[i - 1].identifier) == 0) {
            snprintf(list[i].identifier, sizeof(list[i].identifier), "%.*s", 10, charset + rand() % strlen(charset));
        }

        // Generate hash
        list[i].hash = 0;
        for (int j = 0; inputString[j] != '\0'; j++) {
            list[i].hash += inputString[j];
        }

        // Set random CRCFLAG
        list[i].crc_flag = rand() % 2;
    }

    return list;
}

