import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class WorkerPoolManager {
    private ExecutorService workerPool;
    private int instanceCount = 10; // Initial number of instances

    public void start() {
        workerPool = Executors.newFixedThreadPool(instanceCount);
        Runtime.getRuntime().addShutdownHook(new Thread(this::shutdown));
    }

    public void stop() {
        shutdown();
    }

    private void shutdown() {
        if (workerPool != null) {
            workerPool.shutdown();
            try {
                if (!workerPool.awaitTermination(60, TimeUnit.SECONDS)) {
                    workerPool.shutdownNow();
                }
            } catch (InterruptedException e) {
                workerPool.shutdownNow();
            }
        }
    }

    public void scale(int newInstances) {
        instanceCount = newInstances;
        ExecutorService newWorkerPool = Executors.newFixedThreadPool(instanceCount);
        workerPool.shutdown();
        try {
            if (!workerPool.awaitTermination(60, TimeUnit.SECONDS)) {
                workerPool.shutdownNow();
            }
        } catch (InterruptedException e) {
            workerPool.shutdownNow();
        }
        workerPool = newWorkerPool;
    }

    public void submitTask(Runnable task) {
        workerPool.submit(task);
    }

    // Health check and scaling logic can be added here
}

class Worker implements Runnable {
    @Override
    public void run() {
        // Task execution logic
    }
}
