#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    long *offsets;
    int *keys;
    double *weights;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DataStructure;

DataStructure* create_data_structure() {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->offsets = (long*)calloc(MAX_ELEMENTS, sizeof(long));
    ds->keys = (int*)calloc(MAX_ELEMENTS, sizeof(int));
    ds->weights = (double*)calloc(MAX_ELEMENTS, sizeof(double));
    ds->size = 0;
    ds->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_data_structure(DataStructure *ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->weights);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int resize_data_structure(DataStructure *ds, size_t new_capacity) {
    if (new_capacity > MAX_ELEMENTS) return -1;

    long *new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    double *new_weights = (double*)realloc(ds->weights, new_capacity * sizeof(double));

    if (!new_offsets || !new_keys || !new_weights) return -1;

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->weights = new_weights;
    ds->capacity = new_capacity;

    return 0;
}

void add_element(DataStructure *ds, long offset, int key, double weight) {
    pthread_mutex_lock(&ds->lock);
    if (ds->size >= ds->capacity && resize_data_structure(ds, ds->capacity * 2) != 0) {
        perror("Failed to resize data structure");
        pthread_mutex_unlock(&ds->lock);
        return;
    }
    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->weights[ds->size] = weight;
    ds->size++;
    pthread_mutex_unlock(&ds->lock);
}

void log_memory_usage(DataStructure *ds) {
    printf("Memory usage: %zu bytes\n", ds->size * (sizeof(long) + sizeof(int) + sizeof(double)));
}
