typedef struct Session {
    int id;
    // Other session-specific fields
    struct Session* next;
} Session;

typedef struct SessionConfig {
    int param1;
    // Other configuration parameters
} SessionConfig;

Session* manageSessions(Session** currentList, int currentCount, SessionConfig* config, int maxSessions) {
    if (currentCount >= maxSessions) {
        return NULL; // Maximum sessions reached
    }

    Session* newSession = (Session*)malloc(sizeof(Session));
    if (!newSession) {
        return NULL; // Memory allocation failed
    }

    // Initialize the new session with configuration parameters
    newSession->id = currentCount + 1;
    // Initialize other fields as needed

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    if (*currentList == NULL) {
        *currentList = newSession;
        newSession->next = NULL;
    } else {
        Session* current = *currentList;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newSession;
        newSession->next = NULL;
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return *currentList;
}
