public class WebsiteManager
{
    private readonly string _directoryPath;
    private readonly ILogger _logger;
    private readonly SemaphoreSlim _semaphore;
    private readonly ConcurrentDictionary<string, Website> _websites;

    public WebsiteManager(string directoryPath, ILogger logger)
    {
        _directoryPath = directoryPath;
        _logger = logger;
        _semaphore = new SemaphoreSlim(10);
        _websites = new ConcurrentDictionary<string, Website>();
    }

    public async Task<Website> AddWebsiteAsync(string siteName)
    {
        if (!Directory.Exists(_directoryPath) || !Directory.EnumerateFiles(_directoryPath).Any(f => Path.GetFileName(f) == "web.config"))
            return null;

        if (_websites.ContainsKey(siteName))
            return null;

        var website = new Website(siteName);
        _websites.TryAdd(siteName, website);

        await _semaphore.WaitAsync();
        try
        {
            // Simulate initialization with a timeout
            using (var cts = new CancellationTokenSource(30000))
            {
                await Task.Run(() => InitializeWebsite(website), cts.Token);
            }
        }
        catch (OperationCanceledException)
        {
            _websites.TryRemove(siteName, out _);
            website.Dispose();
            return null;
        }
        finally
        {
            _semaphore.Release();
        }

        return website;
    }

    private void InitializeWebsite(Website website)
    {
        // Simulate initialization logic
        Thread.Sleep(5000); // Simulate time-consuming operation
        website.PopulateRecords();
    }

    public async Task ShutdownAsync()
    {
        foreach (var website in _websites.Values.ToList())
        {
            await _semaphore.WaitAsync();
            try
            {
                website.Shutdown();
            }
            finally
            {
                _semaphore.Release();
            }
        }
    }

    public void PrintRecords()
    {
        foreach (var website in _websites.Values)
        {
            website.PrintRecords();
        }
    }
}

