import java.io.*;
import java.util.concurrent.*;

public class BatchCommandExecutor {

    public static void main(String[] args) {
        String filePath = "path/to/your/file.txt";
        List<String> commands = Arrays.asList("command1", "command2", "command3");
        int maxRetries = 3;
        long timeout = 60; // in seconds

        try {
            deleteFile(filePath);
            executeCommands(commands, maxRetries, timeout);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static void deleteFile(String filePath) throws IOException {
        File file = new File(filePath);
        if (file.exists()) {
            if (!file.delete()) {
                throw new IOException("Failed to delete file: " + filePath);
            }
        }
    }

    private static void executeCommands(List<String> commands, int maxRetries, long timeout) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(commands.size());
        CompletionService<Integer> completionService = new ExecutorCompletionService<>(executor);

        for (String command : commands) {
            completionService.submit(() -> executeCommand(command, maxRetries, timeout));
        }

        for (int i = 0; i < commands.size(); i++) {
            Future<Integer> future = completionService.take();
            try {
                int exitValue = future.get();
                logExecutionInfo(command, exitValue);
            } catch (TimeoutException e) {
                System.err.println("Command timed out: " + command);
            }
        }

        executor.shutdown();
    }

    private static int executeCommand(String command, int maxRetries, long timeout) throws InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        Process process = processBuilder.start();

        Future<Integer> future = Executors.newSingleThreadExecutor().submit(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                 BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
                while ((line = errorReader.readLine()) != null) {
                    System.err.println(line);
                }

                return process.waitFor();
            } catch (IOException | InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        try {
            return future.get(timeout, TimeUnit.SECONDS);
        } catch (TimeoutException e) {
            process.destroyForcibly();
            throw e;
        }
    }

    private static void logExecutionInfo(String command, int exitValue) {
        System.out.println("Command: " + command);
        System.out.println("Exit Value: " + exitValue);
        System.out.println("Success: " + (exitValue == 0));
    }
}
