using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Net;
using System.Text.Json;
using System.Threading.Tasks;

public class LogProcessor
{
    private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();
    private const int CacheSize = 1000;
    private const int PersistenceFrequency = 60; // in seconds

    public DataTableReader ProcessLogs(string logFilePath)
    {
        var dataTable = new DataTable();
        dataTable.Columns.Add("Timestamp", typeof(DateTime));
        dataTable.Columns.Add("UserID", typeof(int));
        dataTable.Columns.Add("ActionType", typeof(string));
        dataTable.Columns.Add("DeviceInfo", typeof(string));
        dataTable.Columns.Add("GeographicalLocation", typeof(string));

        if (!Directory.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Analytics")))
        {
            Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Analytics"));
        }

        var logLines = File.ReadAllLines(logFilePath);
        Parallel.ForEach(logLines, line =>
        {
            try
            {
                var logEntry = ParseLogLine(line);
                if (logEntry != null)
                {
                    lock (_cache)
                    {
                        _cache[line] = JsonSerializer.Serialize(logEntry);
                        if (_cache.Count > CacheSize)
                        {
                            PersistCache();
                        }
                    }

                    dataTable.Rows.Add(
                        logEntry.Timestamp,
                        logEntry.UserID,
                        logEntry.ActionType,
                        logEntry.DeviceInfo,
                        logEntry.GeographicalLocation
                    );
                }
            }
            catch (Exception ex)
            {
                // Log error and continue processing
                Console.WriteLine($"Error processing log line: {ex.Message}");
            }
        });

        return dataTable.CreateDataReader();
    }

    private static LogEntry ParseLogLine(string line)
    {
        var parts = line.Split(' ');
        if (parts.Length < 5) return null;

        var timestamp = DateTime.Parse(parts[0]);
        var userID = int.Parse(parts[1]);
        var actionType = parts[2];
        var deviceInfo = string.Join(" ", parts.Skip(3).TakeWhile(p => !p.Contains(',')));
        var ipAddress = parts.Last();

        var geographicalLocation = GetGeographicalLocation(ipAddress);

        return new LogEntry
        {
            Timestamp = timestamp,
            UserID = userID,
            ActionType = actionType,
            DeviceInfo = deviceInfo,
            GeographicalLocation = geographicalLocation
        };
    }

    private static string GetGeographicalLocation(string ipAddress)
    {
        using (var client = new WebClient())
        {
            var response = client.DownloadString($"http://ip-api.com/json/{ipAddress}");
            return JsonSerializer.Deserialize<JsonElement>(response).GetProperty("country").GetString();
        }
    }

    private void PersistCache()
    {
        lock (_cache)
        {
            foreach (var entry in _cache.Values.Take(CacheSize))
            {
                File.AppendAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Analytics", "log_cache.txt"), entry + Environment.NewLine);
            }
            _cache.Clear();
        }
    }

    private class LogEntry
    {
        public DateTime Timestamp { get; set; }
        public int UserID { get; set; }
        public string ActionType { get; set; }
        public string DeviceInfo { get; set; }
        public string GeographicalLocation { get; set; }
    }
}
