using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class DataProcessor
{
    private readonly int _minValue;
    private readonly int _maxValue;
    private readonly string _delimiter;
    private readonly Encoding _encoding;

    public DataProcessor(int minValue, int maxValue, string delimiter = ";", Encoding encoding = null)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _delimiter = delimiter ?? ";";
        _encoding = encoding ?? Encoding.UTF8;
    }

    public List<string> DecryptMessages(string encryptedMessages, string hexKey, string hexIV)
    {
        var decryptedMessages = new List<string>();
        try
        {
            using (var des = TripleDES.Create())
            {
                des.Key = Convert.FromHexString(hexKey);
                des.IV = Convert.FromHexString(hexIV);

                var messages = encryptedMessages.Split(_delimiter.ToCharArray(), StringSplitOptions.RemoveEmptyEntries);
                foreach (var message in messages)
                {
                    var decryptedBytes = Convert.FromBase64String(message);
                    using (var msDecrypt = new MemoryStream(decryptedBytes))
                    {
                        using (var csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(des.Key, des.IV), CryptoStreamMode.Read))
                        {
                            using (var srDecrypt = new StreamReader(csDecrypt, _encoding))
                            {
                                decryptedMessages.Add(srDecrypt.ReadToEnd());
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Decryption error: {ex.Message}");
        }

        return decryptedMessages;
    }

    public int GenerateRandomInt()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            byte[] randomBytes = new byte[4];
            rng.GetBytes(randomBytes);
            int result = BitConverter.ToInt32(randomBytes, 0);
            return _minValue + (result % (_maxValue - _minValue + 1));
        }
    }

    public float GenerateRandomFloat()
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            byte[] randomBytes = new byte[4];
            rng.GetBytes(randomBytes);
            int result = BitConverter.ToInt32(randomBytes, 0);
            return _minValue + ((result % (_maxValue - _minValue)) / (float)int.MaxValue * (_maxValue - _minValue));
        }
    }
}
