    public DataLoader(IMemoryCache cache, string cloudStorageUrl)
    {
        _cache = cache;
        _cloudStorageUrl = cloudStorageUrl;
    }

    public async Task<T> LoadDataAsync<T>(string filePath, Func<Task<Stream>> downloadFileAsync)
    {
        var cacheKey = $"data:{filePath}";
        if (_cache.TryGetValue(cacheKey, out T cachedData))
        {
            return cachedData;
        }

        try
        {
            using (var stream = await downloadFileAsync())
            {
                var data = Deserialize<T>(stream);
                _cache.Set(cacheKey, data, new MemoryCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1)
                });
                return data;
            }
        }
        catch (Exception ex)
        {
            // Log the error and rethrow or handle it appropriately
            throw;
        }
    }

    private T Deserialize<T>(Stream stream)
    {
        try
        {
            return (T)_formatter.Deserialize(stream);
        }
        catch (SerializationException)
        {
            // Handle deserialization errors, e.g., by using a fallback mechanism or rethrowing with more context
            throw;
        }
    }

    public async Task<T> LoadDataAsync<T>(string filePath)
