import com.google.protobuf.InvalidProtocolBufferException;
import com.google.protobuf.Message;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.TimeUnit;

public class ProtocolBufferProcessor {

    private final ForkJoinPool forkJoinPool = new ForkJoinPool();

    public <T extends Message> T processMessage(byte[] data, int version) throws VersionNotFoundException {
        try (CodedInputStream input = CodedInputStream.newInstance(data)) {
            switch (version) {
                case 1:
                    return (T) MyProtoMessageV1.parseFrom(input);
                case 2:
                    return (T) MyProtoMessageV2.parseFrom(input);
                default:
                    throw new VersionNotFoundException("Unsupported version: " + version);
            }
        } catch (InvalidProtocolBufferException e) {
            System.err.println("Malformed data or missing required fields: " + e.getMessage());
            return null;
        }
    }

    public <T extends Message> void processMessagesStream(Stream<byte[]> inputStream, int version) {
        forkJoinPool.submit(() -> {
            try {
                for (byte[] data : inputStream) {
                    T message = processMessage(data, version);
                    if (message != null) {
                        // Process the deserialized message
                    }
                }
            } catch (VersionNotFoundException e) {
                System.err.println("Error processing messages: " + e.getMessage());
            }
        });
    }

    public static class VersionNotFoundException extends Exception {
        public VersionNotFoundException(String message) {
            super(message);
        }
    }
}
