use tokio::task;
use log::{info, error};
use std::sync::{Arc, Mutex};
use rand::{thread_rng, Rng};

#[derive(Debug)]
struct Record {
    value: i32,
}

type DataBlock = Vec<u8>;

struct DynamicData {
    offsets: Arc<Mutex<Vec<usize>>>,
    keys: Arc<Mutex<Vec<i32>>>,
    records: Arc<Mutex<Vec<Record>>>,
    data_blocks: Arc<Mutex<Vec<DataBlock>>>,
}

impl DynamicData {
    fn new() -> Self {
        DynamicData {
            offsets: Arc::new(Mutex::new(Vec::new())),
            keys: Arc::new(Mutex::new(Vec::new())),
            records: Arc::new(Mutex::new(Vec::new())),
            data_blocks: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn add_record(&self, value_range: (i32, i32)) {
        let mut rng = thread_rng();
        let record = Record { value: rng.gen_range(value_range) };
        self.records.lock().unwrap().push(record);
        self.keys.lock().unwrap().push(rng.gen());
        self.offsets.lock().unwrap().push(self.data_blocks.lock().unwrap().len() * 1024); // Assuming each block is 1KB
        let mut data_block = vec![0; 1024]; // 1KB block
        rng.fill(&mut data_block);
        self.data_blocks.lock().unwrap().push(data_block);
    }

    fn get_record(&self, key: i32) -> Option<&Record> {
        if let Some(index) = self.keys.lock().unwrap().iter().position(|&k| k == key) {
            return self.records.lock().unwrap().get(index);
        }
        None
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let dynamic_data = Arc::new(DynamicData::new());

    tokio::spawn(async move {
        // Simulate processing command line arguments
        for arg in std::env::args().skip(1) {
            match arg.as_str() {
                "add" => {
                    dynamic_data.add_record((-100, 100));
                    info!("Added new record");
                }
                "get" => {
                    if let Some(record) = dynamic_data.get_record(thread_rng().gen_range(-100..100)) {
                        info!("Record value: {}", record.value);
                    } else {
                        error!("Record not found");
                    }
                }
                _ => error!("Unknown command"),
            }
        }
    }).await.unwrap();
}
