} record;

void manage_memory(int offsets_size, int keys_size, int records_size, int max_value) {
    long *offsets = (long *)malloc(offsets_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    int *keys = (int *)malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    record *records = (record *)malloc(records_size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    // Initialize offsets array
    for (int i = 0; i < offsets_size; i++) {
        offsets[i] = i;
    }

    // Initialize keys array with random values
    srand(time(NULL));
    for (int i = 0; i < keys_size; i++) {
        keys[i] = rand() % 1001;
    }

    // Initialize records array with random values and log initialization
    for (int i = 0; i < records_size; i++) {
        records[i].value = rand() % (max_value + 1);
        records[i].offset_index = rand() % offsets_size;
        printf("Record initialized: value=%d, key=%d, offset_index=%d\n", records[i].value, keys[records[i].offset_index], records[i].offset_index);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int offsets_size = 100;
    int keys_size = 200;
    int records_size = 300;
    int max_value = 500;

    manage_memory(offsets_size, keys_size, records_size, max_value);

    return 0;
}
