#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    double measurement;
} Record;

Record* init_records(int initial_size, int *current_size);
void populate_records(Record *records, int start_date, int end_date, int precision, int *current_size);
void resize_records(Record **records, int new_size, int *current_size);
void free_records(Record *records);

int main() {
    int initial_size = 100;
    int current_size = 0;

    Record *records = init_records(initial_size, &current_size);

    // Example usage
    populate_records(records, 20230101, 20230131, 1, &current_size);
    printf("Current size: %d\n", current_size);

    free_records(records);
    return 0;
}

Record* init_records(int initial_size, int *current_size) {
    Record *records = (Record*)malloc(initial_size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    *current_size = 0;
    return records;
}

void populate_records(Record *records, int start_date, int end_date, int precision, int *current_size) {
    for (int date = start_date; date <= end_date; date += precision) {
        if (*current_size >= initial_size) {
            resize_records(&records, initial_size * 2, current_size);
        }
        records[*current_size].timestamp = mktime(gmtime((time_t*)&date));
        records[*current_size].measurement = rand() / (double)RAND_MAX; // Example measurement
        (*current_size)++;
    }
}

void resize_records(Record **records, int new_size, int *current_size) {
    Record *new_records = (Record*)realloc(*records, new_size * sizeof(Record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    *records = new_records;
}

void free_records(Record *records) {
    free(records);
}
```

This code provides a basic structure for managing dynamic memory allocation for records with timestamps and measurements. It includes functions to initialize the records, populate them within a specified date range, resize the records array as needed, and free the allocated memory when done. The example usage in `main` demonstrates initializing the records, populating them, and then freeing the memory.']

