import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.Id;
import java.util.Random;

@SpringBootApplication
public class ProductApiApplication {

    public static void main(String[] args) {
        SpringApplication.run(ProductApiApplication.class, args);
    }

    @RestController
    public class ProductController {

        private final OrderService orderService;

        public ProductController(OrderService orderService) {
            this.orderService = orderService;
        }

        @PostMapping("/products")
        public String submitProduct(@RequestBody Product product) {
            try {
                orderService.placeOrder(product);
                return "Product submitted successfully";
            } catch (Exception e) {
                return "Failed to submit product: " + e.getMessage();
            }
        }
    }

    @Entity
    public class Product {

        @Id
        @GeneratedValue(strategy = GenerationType.IDENTITY)
        private Long id;
        private String name;
        private double price;
        private String description;

        // Getters and setters

        public void setPrice(double price) {
            this.price = price;
        }

        public void setDescription(String description) {
            this.description = description;
        }
    }

    @Bean
    public OrderService orderService() {
        return new MockOrderService();
    }

    public interface OrderService {
        void placeOrder(Product product);
    }

    public static class MockOrderService implements OrderService {

        private final Random random = new Random();

        @Override
        public void placeOrder(Product product) {
            System.out.println("Order placed: " + product.getName() + ", Price: " + product.getPrice());
            // Simulate database insertion with a random failure rate
            if (random.nextDouble() < 0.1) {
                throw new RuntimeException("Database insertion failed");
            }
        }
    }

    public static void main(String[] args) {
        ProductApiApplication app = new ProductApiApplication();
        OrderService orderService = app.orderService();

        long[] ids = new long[5];
        String[] names = {"Product1", "Product2", "Product3", "Product4", "Product5"};
        Product[] products = new Product[5];

        for (int i = 0; i < products.length; i++) {
            products[i] = new Product();
            ids[i] = i + 1;
            names[i] = names[i];
            products[i].setName(names[i]);
            products[i].setPrice(10.0 * random.nextDouble());
            products[i].setDescription("Description for " + names[i]);
        }

        int successfulTransactions = 0;
        int failedValidations = 0;
        int databaseInsertionErrors = 0;

        for (Product product : products) {
            try {
                orderService.placeOrder(product);
                successfulTransactions++;
            } catch (Exception e) {
                if (e.getMessage().contains("Validation failed")) {
                    failedValidations++;
                } else if (e.getMessage().contains("Database insertion failed")) {
                    databaseInsertionErrors++;
                }
            }
        }

        System.out.println("Successful transactions: " + successfulTransactions);
        System.out.println("Failed validations: " + failedValidations);
        System.out.println("Database insertion errors: " + databaseInsertionErrors);
    }
}
