typedef struct {
    int frequency;
    float signalStrength;
} PHY_LAYER_STATS;

typedef struct DL_FRAME_METADATA {
    int frameNumber;
    char cellId[10];
} DL_FRAME_METADATA;

typedef struct LTE_FRAME {
    DL_FRAME_METADATA metadata;
    PHY_LAYER_STATS *stats;
    size_t statsCapacity;
    size_t statsCount;
} LTE_FRAME;

LTE_FRAME* create_lte_frame(DL_FRAME_METADATA metadata, size_t initialStatsCapacity) {
    LTE_FRAME *frame = (LTE_FRAME*)malloc(sizeof(LTE_FRAME));
    if (!frame) return NULL;

    frame->metadata = metadata;
    frame->statsCapacity = initialStatsCapacity;
    frame->statsCount = 0;
    frame->stats = (PHY_LAYER_STATS*)calloc(initialStatsCapacity, sizeof(PHY_LAYER_STATS));
    if (!frame->stats) {
        free(frame);
        return NULL;
    }

    return frame;
}

int append_stats(LTE_FRAME *frame, PHY_LAYER_STATS *newStats, size_t count) {
    if (!frame || !newStats || count == 0) return -1;

    if (frame->statsCount + count > frame->statsCapacity) {
        size_t newCapacity = frame->statsCapacity * 2;
        while (newCapacity < frame->statsCount + count) newCapacity *= 2;
        PHY_LAYER_STATS *newStatsArray = (PHY_LAYER_STATS*)realloc(frame->stats, newCapacity * sizeof(PHY_LAYER_STATS));
        if (!newStatsArray) return -1;
        frame->stats = newStatsArray;
        frame->statsCapacity = newCapacity;
    }

    memcpy(&frame->stats[frame->statsCount], newStats, count * sizeof(PHY_LAYER_STATS));
    frame->statsCount += count;

    return 0;
}

size_t get_stats_count(LTE_FRAME *frame) {
    if (!frame) return 0;
    return frame->statsCount;
}

void free_lte_frame(LTE_FRAME *frame) {
    if (frame) {
        free(frame->stats);
        free(frame);
    }
}
