#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MEMORY 2 * 1024 * 1024

typedef struct {
    double value;
    char* label;
    size_t index;
} item;

typedef struct {
    double* values;
    char** labels;
    size_t size;
} metadata;

void initialize_data(size_t num_values, size_t num_labels, const char* labels[], double initial_values[], double user_values[]) {
    if (num_values * sizeof(double) + num_labels * sizeof(char*) > MAX_MEMORY) {
        // Truncate arrays to fit within the memory limit
        while (num_values * sizeof(double) + num_labels * sizeof(char*) > MAX_MEMORY) {
            num_values--;
            num_labels--;
        }
    }

    metadata* data = malloc(sizeof(metadata));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    data->values = malloc(num_values * sizeof(double));
    if (!data->values) {
        fprintf(stderr, "Memory allocation failed\n");
        free(data);
        return;
    }

    data->labels = malloc(num_labels * sizeof(char*));
    if (!data->labels) {
        fprintf(stderr, "Memory allocation failed\n");
        free(data->values);
        free(data);
        return;
    }

    data->size = num_values;

    for (size_t i = 0; i < num_values; i++) {
        data->values[i] = initial_values[i];
    }

    for (size_t i = 0; i < num_labels; i++) {
        data->labels[i] = strdup(labels[i]);
    }

    item* items = malloc(num_values * sizeof(item));
    if (!items) {
        fprintf(stderr, "Memory allocation failed\n");
        for (size_t i = 0; i < num_labels; i++) {
            free(data->labels[i]);
        }
        free(data->values);
        free(data->labels);
        free(data);
        return;
    }

    for (size_t i = 0; i < num_values; i++) {
        items[i].value = user_values[i];
        items[i].label = data->labels[data->values[i]];
        items[i].index = i;

        printf("Item initialized: label=%s, value=%.2f, index=%zu\n", items[i].label, items[i].value, items[i].index);
    }

    // Free allocated memory
    for (size_t i = 0; i < num_labels; i++) {
        free(data->labels[i]);
    }
    free(data->values);
    free(data->labels);
    free(items);

    free(data);
}

int main() {
    size_t num_values, num_labels;
    printf("Enter number of values: ");
    scanf("%zu", &num_values);
    printf("Enter number of labels: ");
    scanf("%zu", &num_labels);

    double initial_values[num_values];
    char* labels[num_labels];
    double user_values[num_values];

    for (size_t i = 0; i < num_values; i++) {
        initial_values[i] = i * 1.0;
    }

    for (size_t i = 0; i < num_labels; i++) {
        char label[256];
        printf("Enter label %zu: ", i);
        scanf("%s", label);
        labels[i] = strdup(label);
    }

    for (size_t i = 0; i < num_values; i++) {
        printf("Enter value for item %zu: ", i);
        scanf("%lf", &user_values[i]);
    }

    initialize_data(num_values, num_labels, labels, initial_values, user_values);

    return 0;
}
