#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>
#include <curl/curl.h>

#define KDS_URL "https://example.com/kds"
#define MAX_RETRIES 5
#define FALLBACK_CIPHER "AES-128-CBC"

typedef struct {
    char *password;
    char *key;
} EncryptionKey;

typedef struct {
    CURL *handle;
    int retry_count;
} KDSClient;

KDSClient* kds_client_init() {
    KDSClient *client = (KDSClient*)malloc(sizeof(KDSClient));
    client->handle = curl_easy_init();
    client->retry_count = 0;
    return client;
}

void kds_client_cleanup(KDSClient *client) {
    if (client->handle) {
        curl_easy_cleanup(client->handle);
    }
    free(client);
}

int kds_request_key(KDSClient *client, const char *password, char **key) {
    CURLcode res;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Accept: application/json");

    char json_data[256];
    snprintf(json_data, sizeof(json_data), "{\"password\":\"%s\"}", password);

    curl_easy_setopt(client->handle, CURLOPT_URL, KDS_URL);
    curl_easy_setopt(client->handle, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(client->handle, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(client->handle, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(client->handle, CURLOPT_WRITEDATA, key);

    res = curl_easy_perform(client->handle);
    if (res != CURLE_OK) {
        client->retry_count++;
        if (client->retry_count >= MAX_RETRIES) {
            *key = strdup(FALLBACK_CIPHER);
            return 1;
        }
        return -1;
    }

    client->retry_count = 0;
    return 0;
}

EncryptionKey* generate_encryption_key(const char *password) {
    EncryptionKey *key = (EncryptionKey*)malloc(sizeof(EncryptionKey));
    key->password = strdup(password);
    key->key = NULL;

    KDSClient *client = kds_client_init();
    if (kds_request_key(client, password, &key->key) != 0) {
        printf("Failed to get encryption key from KDS. Using fallback.\n");
        key->key = strdup(FALLBACK_CIPHER);
    }

    kds_client_cleanup(client);
    return key;
}

void free_encryption_key(EncryptionKey *key) {
    if (key->password) {
        free(key->password);
    }
    if (key->key) {
        free(key->key);
    }
    free(key);
}
