#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t count;
    size_t growth_threshold;
    pthread_mutex_t mutex;
} dynamic_array;

int init_dynamic_array(dynamic_array* array, size_t initial_size, size_t growth_threshold) {
    if (initial_size == 0 || growth_threshold < initial_size) {
        return -1; // Invalid input
    }

    array->records = (record*)aligned_alloc(64, initial_size * sizeof(record));
    if (!array->records) {
        return -2; // Memory allocation failed
    }

    array->capacity = initial_size;
    array->count = 0;
    array->growth_threshold = growth_threshold;
    pthread_mutex_init(&array->mutex, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        array->records[i].value = rand(); // Assign random values
    }

    return 0;
}

void resize_dynamic_array(dynamic_array* array) {
    size_t new_capacity = array->capacity * 2;
    record* new_records = (record*)aligned_alloc(64, new_capacity * sizeof(record));
    if (!new_records) {
        return; // Memory allocation failed
    }

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        new_records[i].value = array->records[i].value;
    }
    free(array->records);
    array->records = new_records;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->mutex);
}

void add_record(dynamic_array* array, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->growth_threshold) {
        resize_dynamic_array(array);
    }
    array->records[array->count].value = value;
    ++array->count;
    pthread_mutex_unlock(&array->mutex);
}

void free_dynamic_array(dynamic_array* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->records);
    pthread_mutex_destroy(&array->mutex);
    pthread_mutex_unlock(&array->mutex);
}
