#define MAX_RECORDS 1000000
#define MAX_STRING_LENGTH 256

typedef struct {
    int value;
} record;

typedef struct {
    unsigned long id;
    char* string;
    time_t timestamp;
} item;

void* initialize_data_structures(void* arg) {
    int num_records = *(int*)arg;
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));
    double* floats = (double*)malloc(num_records * sizeof(double));
    unsigned long* ids = (unsigned long*)malloc(num_records * sizeof(unsigned long));
    item* items = (item*)malloc(num_records * sizeof(item));

    if (!offsets || !keys || !records || !floats || !ids || !items) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 1000;
        records[i].value = rand() % 10000;
        floats[i] = (double)rand() / RAND_MAX;

        ids[i] = (unsigned long)i;
        items[i].id = ids[i];
        items[i].string = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        snprintf(items[i].string, MAX_STRING_LENGTH, "ID%lu_%ld", ids[i], time(NULL));
        items[i].timestamp = time(NULL);
    }

    // Simulate periodic pruning
    time_t now;
    while ((now = time(NULL)) - items[0].timestamp < 3600) {
        sleep(1);
    }
    for (int i = 0; i < num_records; i++) {
        if (now - items[i].timestamp > 3600) {
            free(items[i].string);
            memmove(&items[i], &items[i + 1], (num_records - i - 1) * sizeof(item));
            num_records--;
            i--;
        }
    }

    // Simulate data loading from external source
    FILE* file = fopen("data.txt", "r");
    if (file) {
        int new_records;
        fscanf(file, "%d", &new_records);
        item* new_items = (item*)realloc(items, (num_records + new_records) * sizeof(item));
        for (int i = num_records; i < num_records + new_records; i++) {
            fscanf(file, "%lu %s %ld", &new_items[i].id, new_items[i].string, &new_items[i].timestamp);
            items = new_items;
            num_records++;
        }
        fclose(file);
    }

    // Free allocated memory
    for (int i = 0; i < num_records; i++) {
        free(items[i].string);
    }
    free(offsets);
    free(keys);
    free(records);
    free(floats);
    free(ids);
    free(items);

    return NULL;
}

int main() {
    int num_records = MAX_RECORDS;
    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_data_structures, &num_records) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }
    pthread_join(thread, NULL);
    return 0;
}
