} record;

record* initialize_records(int num_records, int max_key_value, int seed) {
    if (num_records <= 0 || max_key_value < 0) {
        return NULL; // Handle edge cases
    }

    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Handle memory allocation failure
    }

    srand(seed);

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i;
        keys[i] = rand() % (max_key_value + 1);
        records[i].value = rand();
        records[i].timestamp = ((double)rand()) / RAND_MAX * 100.0;
        records[i].status = (i % 2 == 0) ? 'T' : 'F';
    }

    // Ensure unique keys
    for (int i = 0; i < num_records; ++i) {
        int key = keys[i];
        for (int j = i + 1; j < num_records; ++j) {
            if (keys[j] == key) {
                keys[j] = rand() % (max_key_value + 1);
                --j; // Retry the current index
            }
        }
    }

    return records;
}

void free_records(record* records, int num_records) {
    free(records); // Free the allocated memory for records
}
