record* create_records(size_t count, size_t data_size, long min_value, long max_value, const char* init_string) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < count; ++i) {
        records[i].key = i;
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].data = (char*)malloc(data_size * sizeof(char));
        if (!records[i].data) {
            // Handle memory allocation failure for data buffer
            free_records(records, i); // Free previously allocated records
            return NULL;
        }
        strncpy(records[i].data, init_string, data_size - 1);
        records[i].data[data_size - 1] = '\0'; // Ensure null-termination
    }

    return records;
}

void free_records(record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].data);
    }
    free(records);
}
