        return NULL; // Handle invalid input
    }

    TransactionList* list = (TransactionList*)malloc(sizeof(TransactionList));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    list->transactions = (Transaction*)calloc(initial_size, sizeof(Transaction));
    if (!list->transactions) {
        free(list);
        return NULL; // Memory allocation failed
    }

    pthread_mutex_init(&list->lock, NULL);

    list->capacity = initial_size;
    list->size = 0;
    list->total_amount = 0.0;

    struct timeval now;
    gettimeofday(&now, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        list->transactions[i].id = i + 1;
        list->transactions[i].timestamp.tv_sec = now.tv_sec;
        list->transactions[i].timestamp.tv_usec = now.tv_usec;
        list->transactions[i].amount = 10.0 + (double)(rand() % 991) / 10.0; // Random between 10.0 and 1000.0
        list->transactions[i].status = (i % 2 == 0) ? 'C' : 'P';
        list->total_amount += list->transactions[i].amount;
    }

    return list;
}

// Additional functions for insertion, deletion, and cleanup would be implemented here

void free_transaction_list(TransactionList* list) {
    if (!list) {
        return; // Handle invalid input
    }

    pthread_mutex_destroy(&list->lock);
    free(list->transactions);
    free(list);
}
