    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Failed to initialize AES-256-GCM\n");
        return;
    }

    // Derive key using PBKDF2 with SHA-512
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Failed to generate random salt\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    int iterations = 100000; // Adjust as needed
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                            iterations, EVP_sha512(), 32, key)) {
        fprintf(stderr, "Failed to derive AES-256-GCM key\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Generate secure random IV
    if (!RAND_bytes(iv, EVP_CIPHER_block_size(cipher))) {
        fprintf(stderr, "Failed to generate random IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

