#define MAX_FILES 1000
#define LOG_SIZE 10000

typedef struct FileMetadata {
    int fd;
    time_t timestamp;
    int ref_count;
} FileMetadata;

typedef struct AccessLogEntry {
    int file_fd;
    time_t access_time;
    struct AccessLogEntry *next, *prev;
} AccessLogEntry;

typedef struct HashTable {
    FileMetadata *buckets[MAX_FILES];
} HashTable;

HashTable *hash_table;
AccessLogEntry *log_head = NULL, *log_tail = NULL;

void init_hash_table() {
    hash_table = (HashTable *)malloc(sizeof(HashTable));
    if (!hash_table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        exit(EXIT_FAILURE);
    }
    memset(hash_table->buckets, 0, sizeof(FileMetadata *) * MAX_FILES);
}

void insert_file_metadata(int fd, time_t timestamp) {
    FileMetadata *entry = (FileMetadata *)malloc(sizeof(FileMetadata));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed for file metadata\n");
        return;
    }
    entry->fd = fd;
    entry->timestamp = timestamp;
    entry->ref_count = 1;

    int index = fd % MAX_FILES;
    if (hash_table->buckets[index]) {
        FileMetadata *current = hash_table->buckets[index];
        while (current->next) current = current->next;
        current->next = entry;
        entry->prev = current;
    } else {
        hash_table->buckets[index] = entry;
    }
}

void insert_access_log(int file_fd, time_t access_time) {
    AccessLogEntry *entry = (AccessLogEntry *)malloc(sizeof(AccessLogEntry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed for access log\n");
        return;
    }
    entry->file_fd = file_fd;
    entry->access_time = access_time;

    if (log_head == NULL) {
        log_head = log_tail = entry;
        entry->next = entry->prev = NULL;
    } else {
        log_tail->next = entry;
        entry->prev = log_tail;
        log_tail = entry;
        entry->next = NULL;
    }
}

void update_file_metadata(int fd, time_t new_timestamp) {
    int index = fd % MAX_FILES;
    FileMetadata *current = hash_table->buckets[index];
    while (current) {
        if (current->fd == fd) {
            current->timestamp = new_timestamp;
            return;
        }
        current = current->next;
    }
}

void check_integrity() {
    // Implement integrity check logic here
}

void monitor_memory_usage() {
    // Implement memory usage monitoring logic here
}

int main() {
    init_hash_table();

    char operation[100];
    while (fgets(operation, sizeof(operation), stdin)) {
        if (strncmp(operation, "INSERT_FILE", 13) == 0) {
            int fd;
            time_t timestamp = time(NULL);
            sscanf(operation + 14, "%d", &fd);
            insert_file_metadata(fd, timestamp);
        } else if (strncmp(operation, "ACCESS_FILE", 12) == 0) {
            int file_fd;
            time_t access_time = time(NULL);
            sscanf(operation + 13, "%d", &file_fd);
            insert_access_log(file_fd, access_time);
        }
    }

    check_integrity();
    monitor_memory_usage();

    return 0;
}
