#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
    size_t size;
    long *offset;
} Record;

typedef struct node {
    Record data;
    struct node *next;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(pthread_mutex_t *mutex, Node** head, Record data) {
    pthread_mutex_lock(mutex);
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(mutex);
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void process_and_manage_data(size_t num_records, long* offsets, int* keys, size_t data_size, pthread_mutex_t *mutex) {
    Record records[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = generate_random(1, 100); // Example range
        records[i].size = data_size;
        records[i].offset = &offsets[keys[i]];
    }

    Node* head = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        insert_node(mutex, &head, records[i]);
    }

    free_list(&head);
}

int main() {
    srand(time(NULL));
    size_t num_records = 1000; // Example number of records
    long offsets[num_records];
