#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <boost/property_tree/ptree.hpp>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

class HttpClient {
public:
    HttpClient(net::io_context& ioc, std::string_view host, std::string_view port)
        : resolver_(ioc), stream_(ioc) {
        resolve(host, port);
    }

    void get(std::string_view target) {
        do_request(http::verb::get, target);
    }

    void post(std::string_view target, std::string_view body) {
        do_request(http::verb::post, target, body);
    }

private:
    void resolve(std::string_view host, std::string_view port) {
        resolver_.async_resolve(host, port,
            beast::bind_front_handler(&HttpClient::on_resolve, this,
                beast::placeholders::error, beast::placeholders::results));
    }

    void on_resolve(beast::error_code ec, tcp::resolver::results_type results) {
        if (ec)
            return fail(ec);

        net::async_connect(stream_.next_layer(), results.begin(), results.end(),
            beast::bind_front_handler(&HttpClient::on_connect, this,
                beast::placeholders::error));
    }

    void on_connect(beast::error_code ec) {
        if (ec)
            return fail(ec);

        stream_.async_handshake(net::ssl::stream_base::client,
            beast::bind_front_handler(&HttpClient::on_ssl_handshake, this,
                beast::placeholders::error));
    }

    void on_ssl_handshake(beast::error_code ec) {
        if (ec)
            return fail(ec);

        do_request(http::verb::get, "/");
    }

    template <http::verb Method>
    void do_request(Method method, std::string_view target, std::string_view body = "") {
        http::request<http::string_body> req{method, target, 11};
        req.set(http::field::host, host_);
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        req.body() = body;
        req.prepare_payload();

        http::async_write(stream_, req,
            beast::bind_front_handler(&HttpClient::on_request_write, this,
                beast::placeholders::error));
    }

    void on_request_write(beast::error_code ec) {
        if (ec)
            return fail(ec);

        http::async_read(stream_, buffer_,
            beast::bind_front_handler(&HttpClient::on_request_read, this,
                beast::placeholders::error));
    }

    void on_request_read(beast::error_code ec, std::size_t bytes_transferred) {
        if (ec)
            return fail(ec);

        // Process the response
        http::response<http::string_body> res;
        beast::from_string(res, beast::buffers_to_string(buffer_.data()));
        buffer_.consume(bytes_transferred);

        do_request(http::verb::get, "/");
    }

    void fail(beast::error_code ec) {
        std::cerr << "Error: " << ec.message() << "\n";
    }

    tcp::resolver resolver_;
    net::ssl::stream<tcp::socket> stream_;
    beast::flat_buffer buffer_;
    std::string host_;
};

int main(int argc, char** argv) {
    try {
        if (argc != 4) {
            std::cerr << "Usage: http_client <host> <port> <target>\n";
            return EXIT_FAILURE;
        }

        net::io_context ioc{1};
        HttpClient client{ioc, argv[1], argv[2]};
        client.get(argv[3]);

        ioc.run();
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
