#define SHM_SIZE 1024

typedef struct {
    int ref_count;
    pthread_mutex_t lock;
    char data[SHM_SIZE];
} SharedMemory;

int create_shared_memory(key_t key, size_t size) {
    return shmget(key, size, IPC_CREAT | 0666);
}

SharedMemory* attach_shared_memory(int shmid) {
    return (SharedMemory*)shmat(shmid, NULL, 0);
}

void detach_shared_memory(void* shmaddr) {
    shmdt(shmaddr);
}

void destroy_shared_memory(int shmid) {
    shmctl(shmid, IPC_RMID, NULL);
}

int main() {
    key_t key = ftok("shmfile", 65); // Generate a unique key
    int shmid = create_shared_memory(key, SHM_SIZE);

    if (shmid == -1) {
        perror("shmget");
        exit(EXIT_FAILURE);
    }

    SharedMemory* shm = attach_shared_memory(shmid);

    if (shm == (void*)-1) {
        perror("shmat");
        destroy_shared_memory(shmid);
        exit(EXIT_FAILURE);
    }

    // Initialize shared memory
    shm->ref_count = 1;
    pthread_mutex_init(&shm->lock, NULL);
    memset(shm->data, 0, SHM_SIZE);

    // Example usage: Write to shared memory
    pthread_mutex_lock(&shm->lock);
    strcpy(shm->data, "Hello, Shared Memory!");
    pthread_mutex_unlock(&shm->lock);

    // Example usage: Read from shared memory
    pthread_mutex_lock(&shm->lock);
    printf("Data in shared memory: %s\n", shm->data);
    pthread_mutex_unlock(&shm->lock);

    detach_shared_memory(shm);
    destroy_shared_memory(shmid);

    return 0;
}
