typedef struct {
    sem_t *sem;
    pthread_mutex_t mutex;
} NetworkedSemaphore;

NetworkedSemaphore* create_networked_semaphore(int initial_value) {
    NetworkedSemaphore *ns = (NetworkedSemaphore*)malloc(sizeof(NetworkedSemaphore));
    ns->sem = sem_open("/networked_semaphore", O_CREAT, 0644, initial_value);
    if (ns->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(ns);
        return NULL;
    }
    pthread_mutex_init(&ns->mutex, NULL);
    return ns;
}

void destroy_networked_semaphore(NetworkedSemaphore *ns) {
    sem_close(ns->sem);
    sem_unlink("/networked_semaphore");
    pthread_mutex_destroy(&ns->mutex);
    free(ns);
}

int networked_semaphore_wait(NetworkedSemaphore *ns, struct timespec *timeout) {
    pthread_mutex_lock(&ns->mutex);
    int result = sem_timedwait(ns->sem, timeout);
    pthread_mutex_unlock(&ns->mutex);
    return result;
}

int networked_semaphore_post(NetworkedSemaphore *ns) {
    pthread_mutex_lock(&ns->mutex);
    int result = sem_post(ns->sem);
    pthread_mutex_unlock(&ns->mutex);
    return result;
}
