#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define structures for file metadata and access events
typedef struct {
    int fd;
    time_t timestamp;
    int ref_count;
} FileMetadata;

typedef struct AccessEvent {
    int fd;
    char operation[10];
    struct AccessEvent *next;
} AccessEvent;

// Define hash table and lock-free queue data structures
#define HASH_SIZE 1024

typedef struct HashTableEntry {
    FileMetadata metadata;
    pthread_mutex_t mutex;
    struct HashTableEntry *next;
} HashTableEntry;

HashTableEntry *hash_table[HASH_SIZE];

pthread_mutex_t queue_lock;
AccessEvent *queue_head = NULL, *queue_tail = NULL;

// Function to initialize data structures
void manage_file_operations() {
    // Initialize hash table and lock-free queue
    for (int i = 0; i < HASH_SIZE; i++) {
        hash_table[i] = NULL;
        pthread_mutex_init(&hash_table[i]->mutex, NULL);
    }
    pthread_mutex_init(&queue_lock, NULL);

    // Read file operations from standard input
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        int fd;
        char operation[10];
        sscanf(buffer, "%d %s", &fd, operation);

        // Insert access event into the queue
        AccessEvent *event = malloc(sizeof(AccessEvent));
        if (event == NULL) {
            perror("Failed to allocate memory for access event");
            continue;
        }
        event->fd = fd;
        strcpy(event->operation, operation);
        event->next = NULL;

        pthread_mutex_lock(&queue_lock);
        if (queue_tail == NULL) {
            queue_head = queue_tail = event;
        } else {
            queue_tail->next = event;
            queue_tail = event;
        }
        pthread_mutex_unlock(&queue_lock);
    }

    // Process each operation
    AccessEvent *current_event = queue_head;
    while (current_event != NULL) {
        AccessEvent *next_event = current_event->next;

        int fd = current_event->fd;
        char *operation = current_event->operation;

        pthread_mutex_lock(&hash_table[fd % HASH_SIZE]->mutex);
        if (strcmp(operation, "open") == 0) {
            hash_table[fd % HASH_SIZE]->metadata.ref_count++;
        } else if (strcmp(operation, "close") == 0) {
            hash_table[fd % HASH_SIZE]->metadata.ref_count--;
        }
        pthread_mutex_unlock(&hash_table[fd % HASH_SIZE]->mutex);

        free(current_event);
        current_event = next_event;
    }

    // Free all allocated memory
    for (int i = 0; i < HASH_SIZE; i++) {
        HashTableEntry *entry = hash_table[i];
        while (entry != NULL) {
            HashTableEntry *next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
        pthread_mutex_destroy(&hash_table[i]->mutex);
    }
    pthread_mutex_destroy(&queue_lock);
}

int main() {
    manage_file_operations();
    return 0;
}
