RecordCollection* initializeRecordCollection(int maxRecords, int keyRangeMin, int keyRangeMax, long offsetLimit) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) {
        return NULL; // Memory allocation failed
    }
    collection->records = (Record*)calloc(maxRecords, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL; // Memory allocation failed
    }
    collection->keyCount = 0;
    collection->offsetSum = 0;
    return collection;
}

void populateRecordCollection(RecordCollection* collection, int maxRecords, int keyRangeMin, int keyRangeMax, long offsetLimit) {
    srand(time(NULL));
    while (collection->keyCount < maxRecords) {
        int key = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
        long offset = rand() % (offsetLimit / collection->keyCount);
        if (!isKeyOffsetUnique(collection, key, offset)) {
            continue;
        }
        collection->records[collection->keyCount].key = key;
        collection->records[collection->keyCount].offset = offset;
        collection->keyCount++;
        collection->offsetSum += offset;
    }
}

void freeRecordCollection(RecordCollection* collection) {
    if (collection->records) {
        free(collection->records);
    }
    free(collection);
}

int isKeyOffsetUnique(RecordCollection* collection, int key, long offset) {
