        free(manager);
        return NULL;
    }
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_record_manager(record_manager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->records[i]->data_block);
            free(manager->records[i]);
        }
        free(manager->records);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

record* create_record(int key, long offset, size_t data_length) {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) {
        perror("Failed to allocate memory for record");
        return NULL;
    }
    rec->key = key;
    rec->offset = offset;
    rec->data_block = (char*)malloc(data_length + 1);
    if (!rec->data_block) {
        perror("Failed to allocate memory for data_block");
        free(rec);
        return NULL;
