        rec->data_block[i] = 'a' + rand() % 26;
    }
    rec->data_block[data_length] = '\0';
    return rec;
}

void add_record(record_manager* manager, record* rec) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->records_capacity) {
        // Resize records array
        size_t new_capacity = manager->records_capacity ? manager->records_capacity * 2 : 16;
        record** new_records = (record**)realloc(manager->records, new_capacity * sizeof(record*));
        if (!new_records) {
            perror("Failed to reallocate memory for records array");
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->records = new_records;
        manager->records_capacity = new_capacity;
    }
    manager->records[manager->count++] = rec;
    pthread_mutex_unlock(&manager->lock);
}

void log_memory_usage(record_manager* manager) {
