                                         void (*external_data_source)(void**, size_t*), size_t external_data_source_capacity) {
    struct Record *records = (struct Record *)malloc(max_records * record_size);
    if (!records) {
        errno = ENOMEM;
        return NULL;
    }

    void *data;
    size_t data_size;
    external_data_source(&data, &data_size);

    if (data_size != max_records * sizeof(struct Record)) {
        free(records);
        errno = EIO;
        return NULL;
    }

    for (int i = 0; i < max_records; ++i) {
        struct Record *record = (struct Record *)((char *)records + i * record_size);
        record->key = ((int *)data)[2 * i];
        record->offset = ((long *)data)[2 * i + 1];

        if (record->key < min_key_range || record->key > max_offset_max / max_records) {
            free(records);
            errno = ERANGE;
            return NULL;
        }
    }

    return records;
}
