#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection) {
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_record(RecordCollection* collection, int key, long offset) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key || collection->records[i].offset == offset) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Duplicate key or offset
        }
    }

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    ++collection->count;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

