int initialize_data(double** double_array, char*** string_array, Node*** node_array,
                    Tree** tree_array, size_t array_size, int num_threads) {
    // Allocate memory for arrays
    *double_array = (double*)malloc(array_size * sizeof(double));
    *string_array = (char**)malloc(array_size * sizeof(char*));
    *node_array = (Node**)malloc(array_size * sizeof(Node*));
    *tree_array = (Tree*)malloc(array_size * sizeof(Tree));

    if (!(*double_array) || !(*string_array) || !(*node_array) || !(*tree_array)) {
        return -1; // Memory allocation failed
    }

    // Initialize arrays
    for (size_t i = 0; i < array_size; ++i) {
        (*double_array)[i] = 0.0;
        (*string_array)[i] = (char*)malloc(64 * sizeof(char));
        if (!(*string_array)[i]) {
            return -1; // Memory allocation failed
        }
        snprintf((*string_array)[i], 64, "ID%d", i);
        (*node_array)[i] = NULL;
    }

    // Initialize tree array
    for (size_t i = 0; i < array_size; ++i) {
        (*tree_array)[i].value = 0.0;
        snprintf((*tree_array)[i].identifier, 64, "Tree%d", i);
        (*tree_array)[i].root = NULL;
    }

    // Initialize node arrays in parallel
    pthread_t threads[MAX_THREADS];
    size_t chunk_size = array_size / num_threads;
    for (int t = 0; t < num_threads; ++t) {
        size_t start = t * chunk_size;
        size_t end = (t == num_threads - 1) ? array_size : (start + chunk_size);
        pthread_create(&threads[t], NULL, initialize_node_array, (void*)(size_t)end);
    }

    // Wait for all threads to finish
    for (int t = 0; t < num_threads; ++t) {
        pthread_join(threads[t], NULL);
    }

    return 0; // Success
}

void* initialize_node_array(void* end_ptr) {
