        for (int j = 0; j < 10; ++j) { // Example: 10 nodes per list
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (!new_node) {
                free(node_array);
                return NULL; // Memory allocation failed
            }
            new_node->value = rand() / (double)RAND_MAX;
            new_node->counter = 0;
            new_node->next = current->next;
            current->next = new_node;
        }
    }

    free(node_array);
    return NULL;
}

int main() {
