#include <vector>
#include <iostream>
#include <cstdlib>
#include <ctime>
#include <string>
#include <mutex>

struct record {
    int value;
    size_t size;
    time_t last_accessed;
};

std::mutex mtx;

void processVectorAndInitializeData(std::vector<int>& vec, int findVal, int replaceVal, int appendVal) {
    auto it = std::find(vec.begin(), vec.end(), findVal);
    if (it != vec.end()) {
        *it = replaceVal;
    } else {
        vec.push_back(appendVal);
    }
}

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        std::cerr << "Memory allocation failed" << std::endl;
        return nullptr;
    }
    return ptr;
}

record* initializeRecords(size_t initialSize, int range, double scaleFactor, const std::string& prefix) {
    record* records = static_cast<record*>(allocateMemory(initialSize * sizeof(record)));
    if (!records) return nullptr;

    for (size_t i = 0; i < initialSize; ++i) {
        std::lock_guard<std::mutex> lock(mtx);
        records[i].value = rand() % range;
        while (std::find_if(records, records + i, [records, i](const record& r) { return r.value == records[i].value; }) != records + i) {
            records[i].value = rand() % range;
        }
        records[i].size = static_cast<size_t>(scaleFactor * (i + 1));
        records[i].last_accessed = time(nullptr);
        std::string key = prefix + std::to_string(i);
        records[i].data = allocateMemory(key.size() + 1);
        if (!records[i].data) {
            for (size_t j = 0; j < i; ++j) free(records[j].data);
            free(records);
            return nullptr;
        }
        std::copy(key.begin(), key.end(), records[i].data);
    }

    return records;
}

int main() {
    srand(time(nullptr));
    std::vector<int> vec = {1, 2, 3, 4, 5};
    processVectorAndInitializeData(vec, 3, 10, 20);

    record* records = initializeRecords(100, 1000, 1.5, "key_");
    if (records) {
        for (size_t i = 0; i < 100; ++i) {
            std::cout << "Record " << i << ": value=" << records[i].value << ", size=" << records[i].size << ", last_accessed=" << records[i].last_accessed << ", data=" << records[i].data << std::endl;
        }
        for (size_t i = 0; i < 100; ++i) free(records[i].data);
        free(records);
    }

    return 0;
}
