#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int value;
    size_t size;
    void* data;
    struct Record* next;
} Record;

typedef struct RecordList {
    pthread_mutex_t lock;
    Record* head;
} RecordList;

Record* create_record(int value, size_t size) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = value;
    record->size = size;
    record->data = malloc(size);
    if (!record->data) {
        free(record);
        return NULL;
    }
    memset(record->data, 0, size);
    record->next = NULL;
    return record;
}

void destroy_record(Record* record) {
    if (record) {
        free(record->data);
        free(record);
    }
}

RecordList* create_record_list() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    return list;
}

void destroy_record_list(RecordList* list) {
    if (list) {
        Record* current = list->head;
        while (current) {
            Record* next = current->next;
            destroy_record(current);
            current = next;
        }
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void insert_record(RecordList* list, int value, size_t size) {
    pthread_mutex_lock(&list->lock);
    Record* new_record = create_record(value, size);
    if (new_record) {
        new_record->next = list->head;
        list->head = new_record;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_record(RecordList* list, int value) {
    pthread_mutex_lock(&list->lock);
    Record** current = &list->head;
    while (*current) {
        if ((*current)->value == value) {
            Record* temp = *current;
            *current = (*current)->next;
            destroy_record(temp);
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&list->lock);
}

Record* find_record(RecordList* list, int value) {
    pthread_mutex_lock(&list->lock);
    Record* current = list->head;
    while (current) {
        if (current->value == value) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

size_t find_max_size(RecordList* list) {
    size_t max_size = 0;
    Record* current = list->head;
    while (current) {
        if (current->size > max_size) {
