#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct line_node {
    char* content;
    size_t length;
    struct line_node* next;
} line_node;

void handle_file_operations(const char* filename, int num_lines_to_read, int num_lines_to_write) {
    FILE* file = fopen(filename, "r+");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Allocate memory for the linked list
    line_node* head = NULL;
    line_node** current = &head;

    // Read lines from the file and store them in a linked list
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file) != NULL && num_lines_to_read > 0) {
        size_t length = strlen(buffer);
        if (buffer[length - 1] == '\n') {
            buffer[length - 1] = '\0';
            length--;
        }

        line_node* new_node = malloc(sizeof(line_node));
        if (!new_node) {
            perror("Failed to allocate memory for new node");
            break;
        }
        new_node->content = strdup(buffer);
        new_node->length = length;
        new_node->next = NULL;

        *current = new_node;
        current = &new_node->next;
        num_lines_to_read--;
    }

    // Write lines back to the file
    fseek(file, 0, SEEK_SET);
    line_node* temp = head;
    while (temp != NULL && num_lines_to_write > 0) {
        if (fprintf(file, "%s\n", temp->content) < 0) {
            perror("Failed to write to file");
            break;
        }
        temp = temp->next;
        num_lines_to_write--;
    }

    // Free all allocated memory
    while (head != NULL) {
        line_node* next = head->next;
        free(head->content);
        free(head);
        head = next;
    }

    fclose(file);
}

int main() {
    const char* filename = "example.txt";
    int num_lines_to_read = 10;
    int num_lines_to_write = 5;

    handle_file_operations(filename, num_lines_to_read, num_lines_to_write);

    return 0;
}
