#include <string.h>

typedef struct record {
    int value;
    size_t size;
    long *offset;
} Record;

typedef struct bst_node {
    int key;
    Record *record;
    struct bst_node *left, *right;
} BSTNode;

BSTNode* create_bst_node(int key, Record *record) {
    BSTNode* node = (BSTNode*)malloc(sizeof(BSTNode));
    if (node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    node->key = key;
    node->record = record;
    node->left = node->right = NULL;
    return node;
}

BSTNode* insert_bst_node(BSTNode* root, int key, Record *record) {
    if (root == NULL) {
        return create_bst_node(key, record);
    }
    if (key < root->key) {
        root->left = insert_bst_node(root->left, key, record);
    } else if (key > root->key) {
        root->right = insert_bst_node(root->right, key, record);
    }
    return root;
}

int find_max(BSTNode* node) {
    while (node->right != NULL) {
        node = node->right;
    }
    return node->key;
}

void initialize_website_directory(const char *directory_path) {
    // Check for web.config file
    FILE *config_file = fopen("web.config", "r");
    if (config_file == NULL) {
        printf("web.config not found in the directory.\n");
        return;
    }
    fclose(config_file);

    // Read integers from standard input
    int num_records;
    scanf("%d", &num_records);
    long *offsets = (long*)malloc(num_records * sizeof(long));
    int *keys = (int*)malloc(num_records * sizeof(int));
    Record *records = (Record*)malloc(num_records * sizeof(Record));

    for (int i = 0; i < num_records; i++) {
        scanf("%d %ld", &keys[i], &offsets[i]);
        records[i].value = keys[i];
        records[i].size = 1;
        records[i].offset = &offsets[i];
    }

    // Initialize BST
    BSTNode *root = NULL;
    for (int i = 0; i < num_records; i++) {
        root = insert_bst_node(root, keys[i], &records[i]);
    }

    // Find and print the largest integer
    int max_value = find_max(root);
    printf("Largest value: %d\n", max_value);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    initialize_website_directory(".");
    return 0;
}
