    if (!new_node) return NULL;

    new_node->value = min_val + (max_val - min_val) * ((double)rand() / RAND_MAX);
    new_node->data.length = sizeof(double);
    new_node->data.checksum = 0; // Placeholder for checksum calculation
    new_node->data.u.raw_data = new_node->value;
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

// Function to initialize the linked list
linked_list* init_linked_list() {
    linked_list* list = (linked_list*)malloc(sizeof(linked_list));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    return list;
}

// Function to add a node to the end of the list
void add_node(linked_list* list, double min_val, double max_val) {
    node* new_node = create_node(min_val, max_val);
    if (!new_node) return;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->size++;
}

// Function to traverse the list in forward direction
void traverse_forward(linked_list* list) {
    node* current = list->head;
    while (current != NULL) {
        printf("Value: %f\n", current->value);
        current = current->next;
    }
}

// Function to traverse the list in backward direction
void traverse_backward(linked_list* list) {
    node* current = list->tail;
    while (current != NULL) {
        printf("Value: %f\n", current->value);
        current = current->prev;
    }
}

// Function to free all allocated memory for the linked list
void free_linked_list(linked_list* list) {
    node* current = list->head;
    while (current != NULL) {
        node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

