    TreeNode* new_node = (TreeNode*)malloc(sizeof(TreeNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->value = value;
    new_node->block.timestamp = timestamp;
    new_node->block.version = version;
    new_node->left = NULL;
    new_node->right = NULL;
    return new_node;
}

void free_tree(TreeNode* node) {
    if (node == NULL) return;
    free_tree(node->left);
    free_tree(node->right);
    free(node);
}

// Depth-first traversal
void dfs(TreeNode* node, void (*visit)(TreeNode*)) {
    if (node != NULL) {
        visit(node);
        dfs(node->left, visit);
        dfs(node->right, visit);
    }
}

// Breadth-first traversal using a queue
typedef struct QueueNode {
    TreeNode* node;
    struct QueueNode* next;
} QueueNode;

QueueNode* create_queue_node(TreeNode* node) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->node = node;
    new_node->next = NULL;
    return new_node;
}

void enqueue(QueueNode** front, QueueNode** rear, TreeNode* node) {
    QueueNode* new_node = create_queue_node(node);
    if (*front == NULL) {
        *front = *rear = new_node;
    } else {
        (*rear)->next = new_node;
        *rear = new_node;
    }
}

TreeNode* dequeue(QueueNode** front, QueueNode** rear) {
    if (*front == NULL) return NULL;
    QueueNode* temp = *front;
    TreeNode* node = temp->node;
    *front = (*front)->next;
    if (*front == NULL) *rear = NULL;
    free(temp);
    return node;
}

void bfs(TreeNode* root, void (*visit)(TreeNode*)) {
    if (root == NULL) return;
    QueueNode* front = NULL, *rear = NULL;
    enqueue(&front, &rear, root);
    while (front != NULL) {
        TreeNode* current = dequeue(&front, &rear);
        visit(current);
        if (current->left != NULL) enqueue(&front, &rear, current->left);
        if (current->right != NULL) enqueue(&front, &rear, current->right);
    }
}

void print_node(TreeNode* node) {
    printf("Value: %lld, Timestamp: %ld, Version: %u\n", node->value, node->block.timestamp, node->block.version);
}
