#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    size_t size;
    void* offset;
} Record;

// Define the red-black tree node structure
typedef struct rb_node {
    int key;
    Record data;
    struct rb_node *left, *right, *parent;
    int color; // 0 for black, 1 for red
} RBNode;

// Function to create a new red-black tree node
RBNode* create_node(int key, Record data) {
    RBNode* new_node = (RBNode*)malloc(sizeof(RBNode));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->data = data;
    new_node->left = new_node->right = new_node->parent = NULL;
    new_node->color = 1; // Red
    return new_node;
}

// Function to perform left rotation on the red-black tree
void left_rotate(RBNode** root, RBNode* x) {
    RBNode* y = x->right;
    x->right = y->left;
    if (y->left != NULL)
        y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL)
        *root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;
    y->left = x;
    x->parent = y;
}

// Function to perform right rotation on the red-black tree
void right_rotate(RBNode** root, RBNode* y) {
    RBNode* x = y->left;
    y->left = x->right;
    if (x->right != NULL)
        x->right->parent = y;
    x->parent = y->parent;
    if (y->parent == NULL)
        *root = x;
    else if (y == y->parent->right)
        y->parent->right = x;
    else
        y->parent->left = x;
    x->right = y;
    y->parent = x;
}

// Function to fix the red-black tree properties after insertion
void insert_fixup(RBNode** root, RBNode* z) {
    while (z->parent != NULL && z->parent->color == 1) {
        if (z->parent == z->parent->parent->left) {
            RBNode* y = z->parent->parent->right;
            if (y != NULL && y->color == 1) {
                z->parent->color = 0;
                y->color = 0;
                z->parent->parent->color = 1;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(root, z);
                }
                z->parent->color = 0;
                z->parent->parent->color = 1;
                right_rotate(root, z->parent->parent);
            }
        } else {
            RBNode* y = z->parent->parent->left;
            if (y != NULL && y->color == 1) {
                z->parent->color = 0;
                y->color = 0;
                z->parent->parent->color = 1;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(root, z);
                }
                z->parent->color = 0;
                z->parent->parent->color = 1;
                left_rotate(root, z->parent->parent);
            }
        }
    }
    (*root)->color = 0;
}

// Function to insert a new node into the red-black tree
void rb_insert(RBNode** root, int key, Record data) {
    RBNode* z = create_node(key, data);
    RBNode* y = NULL;
    RBNode* x = *root;

    while (x != NULL) {
        y = x;
        if (z->key < x->key)
            x = x->left;
        else
            x = x->right;
    }

    z->parent = y;
    if (y == NULL)
        *root = z;
    else if (z->key < y->key)
        y->left = z;
    else
        y->right = z;

    insert_fixup(root, z);
}

// Function to traverse the red-black tree and retrieve data blocks based on specified criteria
void rb_traverse(RBNode* root) {
    if (root != NULL) {
        rb_traverse(root->left);
        printf("Key: %d, Value: %d\n", root->key, root->data.value);
        rb_traverse(root->right);
    }
}

// Function to free the memory allocated for the red-black tree
void rb_free(RBNode* node) {
    if (node != NULL) {
        rb_free(node->left);
        rb_free(node->right);
        free(node);
    }
}

int main() {
    RBNode* root = NULL;
    int n, key;
    Record data;

    printf("Enter the number of integers to insert: ");
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &key);
        data.value = key;
        data.size = sizeof(int);
        data.offset = malloc(data.size);
        if (!data.offset) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        memcpy(data.offset, &key, data.size);
        rb_insert(&root, key, data);
    }

    printf("\nTraversing the red-black tree:\n");
    rb_traverse(root);

    // Free allocated memory
    rb_free(root);

    return 0;
}
