    Record data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* process_large_binary_file(void* arg) {
    uint64_t id;
    double value;
    char name[MAX_NAME_LENGTH];
    Node* new_node;

    while (fread(&id, sizeof(uint64_t), 1, stdin)) {
        fread(&value, sizeof(double), 1, stdin);
        fread(name, sizeof(char), MAX_NAME_LENGTH, stdin);

        pthread_mutex_lock(&lock);
        new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        new_node->data.id = id;
        new_node->data.value = value * (id % 10 + 1); // Polynomial function
        strncpy(new_node->data.name, name, MAX_NAME_LENGTH - 1);
        new_node->data.name[MAX_NAME_LENGTH - 1] = '\0';
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

double calculate_average_value() {
    Node* current = head;
    double sum = 0.0;
    int count = 0;

    while (current) {
        sum += current->data.value;
        count++;
        current = current->next;
    }

    return count > 0 ? sum / count : 0.0;
}

int main() {
