    if (pthread_create(&thread, NULL, process_large_binary_file, NULL) != 0) {
        perror("Thread creation failed");
        exit(EXIT_FAILURE);
    }
    pthread_join(thread, NULL);

    double average = calculate_average_value();
    printf("Average value: %f\n", average);

    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}
