#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define RECORD_SIZE sizeof(uint64_t) + sizeof(double) + 1

typedef struct record {
    uint64_t id;
    double value;
    char *name;
    struct record *next;
} Record;

typedef struct memory_pool {
    size_t block_size;
    size_t num_blocks;
    void *blocks;
    void *free_list;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    pool->free_list = pool->blocks;

    for (size_t i = 1; i < num_blocks; ++i) {
        ((char *)pool->blocks + i * block_size)->next = (void *)((char *)pool->blocks + (i - 1) * block_size);
    }

    return pool;
}

void *memory_pool_alloc(MemoryPool *pool) {
    void *block = pool->free_list;
    if (block != NULL) {
        pool->free_list = ((char *)block)->next;
    }
    return block;
}

void memory_pool_free(MemoryPool *pool, void *block) {
    ((char *)block)->next = pool->free_list;
    pool->free_list = block;
}

Record *create_record(uint64_t id, double value, const char *name, MemoryPool *pool) {
    Record *rec = (Record *)memory_pool_alloc(pool);
    rec->id = id;
    rec->value = value;
    rec->name = strdup(name);
    rec->next = NULL;
    return rec;
}

void free_record(Record *rec, MemoryPool *pool) {
    memory_pool_free(pool, rec);
    free(rec->name);
}

Record **read_large_binary_file(MemoryPool *pool) {
    Record **records = (Record **)malloc(sizeof(Record *));
    *records = NULL;

    uint64_t id;
    double value;
    char name[256];
    while (fread(&id, sizeof(uint64_t), 1, stdin)) {
        fread(&value, sizeof(double), 1, stdin);
        fread(name, sizeof(char), 256, stdin);

        Record *rec = create_record(id, value, name, pool);
        rec->next = *records;
        *records = rec;
    }

    return records;
}

void process_large_binary_file() {
    MemoryPool *pool = create_memory_pool(RECORD_SIZE, 1024);
    Record **records = read_large_binary_file(pool);

    // Process the records
    for (Record *rec = *records; rec != NULL; rec = rec->next) {
        // Perform operations on each record
    }

    // Free all allocated memory
    while (*records != NULL) {
        Record *temp = *records;
        *records = temp->next;
        free_record(temp, pool);
    }
    free(records);
    free_memory_pool(pool);
}

int main() {
    process_large_binary_file();
    return 0;
}
