#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct record {
    uint64_t id;
    double value;
    char* name;
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void polynomial_function(double* value, uint64_t id) {
    *value = 0.0;
    for (int i = 0; i < 64; i++) {
        if (id & (1ULL << i)) {
            *value += pow(2.0, i);
        }
    }
}

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_record(Record data) {
    pthread_mutex_lock(&lock);
    Node* new_node = create_node(data);
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

double calculate_average() {
    double sum = 0.0;
    int count = 0;
    Node* current = head;
    while (current != NULL) {
        sum += current->data.value;
        count++;
        current = current->next;
    }
    return count > 0 ? sum / count : 0.0;
}

void process_large_binary_file() {
    Record records[MAX_RECORDS];
    size_t bytes_read;
    while ((bytes_read = fread(records, sizeof(Record), MAX_RECORDS, stdin)) > 0) {
        for (size_t i = 0; i < bytes_read; i++) {
            polynomial_function(&records[i].value, records[i].id);
            insert_record(records[i]);
        }
    }
}

int main() {
    process_large_binary_file();
    double average = calculate_average();
    printf("Average value: %f\n", average);
    return 0;
}
