#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
    size_t size;
    time_t expiry_time;
    time_t creation_time;
    unsigned long access_count;
} Record;

typedef struct hash_entry {
    int key;
    Record *record;
    struct hash_entry *next;
} HashEntry;

typedef struct hash_table {
    size_t capacity;
    size_t size;
    HashEntry **buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->buckets = (HashEntry**)calloc(initial_capacity, sizeof(HashEntry*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashEntry *entry = table->buckets[i];
        while (entry != NULL) {
            HashEntry *next = entry->next;
            free(entry->record);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

size_t hash_function(int key, size_t capacity) {
    return (size_t)(key % capacity);
}

void insert_record(HashTable *table, int key, Record *record) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    HashEntry *entry = table->buckets[index];
    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }
    if (entry == NULL) {
        entry = (HashEntry*)malloc(sizeof(HashEntry));
        entry->key = key;
        entry->record = record;
        entry->next = table->buckets[index];
        table->buckets[index] = entry;
        ++table->size;
    } else {
        free(entry->record);
        entry->record = record;
    }
    pthread_mutex_unlock(&table->lock);
}

Record* get_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    HashEntry *entry = table->buckets[index];
    while (entry != NULL && entry->key != key) {
        entry = entry->next;
    }
    Record *record = entry ? entry->record : NULL;
    pthread_mutex_unlock(&table->lock);
    return record;
}

void remove_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    HashEntry **entry_ptr = &table->buckets[index];
    while (*entry_ptr != NULL && (*entry_ptr)->key != key) {
        entry_ptr = &(*entry_ptr)->next;
    }
    if (*entry_ptr != NULL) {
        HashEntry *entry = *entry_ptr;
        *entry_ptr = entry->next;
        free(entry->record);
        free(entry);
        --table->size;
    }
    pthread_mutex_unlock(&table->lock);
}

void resize_hash_table(HashTable *table, size_t new_capacity) {
    HashEntry **old_buckets = table->buckets;
    size_t old_capacity = table->capacity;
    table->buckets = (HashEntry**)calloc(new_capacity, sizeof(HashEntry*));
    table->capacity = new_capacity;
    table->size = 0;

    for (size_t i = 0; i < old_capacity; ++i) {
        HashEntry *entry = old_buckets[i];
        while (entry != NULL) {
            insert_record(table, entry->key, entry->record);
            HashEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }

    free(old_buckets);
}

void* garbage_collection_thread(void *arg) {
    HashTable *table = (HashTable*)arg;
    while (1) {
        // Perform garbage collection logic here
        sleep(60); // Example: run every minute
    }
    return NULL;
}

int main() {
    HashTable *table = create_hash_table(1024);
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection_thread, table);

    // Example usage of the hash table
    Record record;
    record.value = 42;
    record.size = sizeof(record);
    record.expiry_time = time(NULL) + 3600; // Expires in 1 hour
    record.creation_time = time(NULL);
    record.access_count = 0;

    insert_record(table, 123, &record);

    Record *retrieved_record = get_record(table, 123);
    if (retrieved_record != NULL) {
        printf("Retrieved value: %d\n", retrieved_record->value);
    }

    remove_record(table, 123);

    pthread_join(gc_thread, NULL);
    destroy_hash_table(table);

    return 0;
}
