#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <openssl/sha.h>

#define MAX_FILE_PATH_LENGTH 256
#define BUFFER_SIZE 1024

typedef struct {
    const char* path;
    time_t last_modified;
    size_t size;
    char* content_buffer;
} file_record;

void read_file_content(const char* path, char** buffer) {
    FILE* file = fopen(path, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *buffer = (char*)malloc(file_size + 1);
    if (*buffer == NULL) {
        perror("Failed to allocate memory for file content");
        fclose(file);
        return;
    }

    fread(*buffer, 1, file_size, file);
    (*buffer)[file_size] = '\0';
    fclose(file);
}

void write_file_content(const char* path, const char* buffer) {
    FILE* file = fopen(path, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(buffer, 1, strlen(buffer), file);
    fclose(file);
}

void calculate_file_hash(const char* content, unsigned char hash[SHA256_DIGEST_LENGTH]) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, content, strlen(content));
    SHA256_Final(hash, &sha256);
}

void process_and_manage_files(const char* file_path, const char* content_string) {
    file_record record;
    record.path = file_path;

    if (content_string != NULL) {
        record.content_buffer = strdup(content_string);
        if (record.content_buffer == NULL) {
            perror("Failed to allocate memory for content buffer");
            return;
        }
        record.size = strlen(content_string);
    } else {
        read_file_content(file_path, &record.content_buffer);
        if (record.content_buffer == NULL) {
            return;
        }
        struct stat file_stat;
        if (stat(file_path, &file_stat) != 0) {
            perror("Failed to get file statistics");
            free(record.content_buffer);
            return;
        }
        record.size = file_stat.st_size;
    }

    time_t last_modified;
    if (stat(file_path, &file_stat) == 0) {
        last_modified = file_stat.st_mtime;
    } else {
        perror("Failed to get file statistics");
        free(record.content_buffer);
        return;
    }
    record.last_modified = last_modified;

    unsigned char hash[SHA256_DIGEST_LENGTH];
    calculate_file_hash(record.content_buffer, hash);

    printf("File Path: %s\n", record.path);
    printf("Last Modified: %s", ctime(&record.last_modified));
    printf("Size: %zu bytes\n", record.size);
    printf("Hash: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    free(record.content_buffer);
}

void free_file_record(file_record* record) {
    if (record->content_buffer != NULL) {
        free((char*)record->content_buffer);
    }
}
