#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int value;
    size_t size;
    void* data;
} record;

typedef struct node {
    record data;
    struct node* next;
} node;

typedef struct {
    node* head;
    pthread_mutex_t lock;
} linked_list;

void init_linked_list(linked_list* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_record(linked_list* list, record new_record) {
    pthread_mutex_lock(&list->lock);
    node* new_node = (node*)malloc(sizeof(node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = new_record;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

record* find_max(linked_list* list) {
    record* max_record = NULL;
    node* current = list->head;
    while (current != NULL) {
        if (max_record == NULL || current->data.value > max_record->value) {
            max_record = &current->data;
        }
        current = current->next;
    }
    return max_record;
}

void free_linked_list(linked_list* list) {
    pthread_mutex_lock(&list->lock);
    node* current = list->head;
    while (current != NULL) {
        node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    linked_list my_list;
    init_linked_list(&my_list);

    int value;
    while (scanf("%d", &value) == 1) {
        record new_record = {value, sizeof(int), malloc(sizeof(int))};
        if (new_record.data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        *((int*)new_record.data) = value;
        insert_record(&my_list, new_record);
    }

    record* max_record = find_max(&my_list);
    if (max_record != NULL) {
        printf("Maximum value: %d\n", max_record->value);
    } else {
        printf("No values found\n");
    }

    free_linked_list(&my_list);

    return 0;
}
