typedef struct {
    int value;
    size_t size;
    char* data;
} record;

void initializeDataStructures(long** offsets, int** keys, record** records, int numRecords, int minRandomValue, int maxRandomValue) {
    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));
    *records = (record*)malloc(numRecords * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle memory allocation failure
        return;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < numRecords; i++) {
        (*keys)[i] = rand() % (maxRandomValue - minRandomValue + 1) + minRandomValue;

        size_t dataSize = rand() % 1024 + 1; // Random data block size between 1 and 1024 bytes
        (*records)[i].size = dataSize;
        (*records)[i].data = (char*)malloc(dataSize);
        if ((*records)[i].data == NULL) {
            // Handle memory allocation failure for individual record
            continue;
        }

        // Fill data block with random characters
        for (size_t j = 0; j < dataSize; j++) {
            (*records)[i].data[j] = 'a' + rand() % 26; // Random lowercase letter
        }
    }
}

void freeDataStructures(long* offsets, int* keys, record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i].data != NULL) {
            free(records[i].data);
        }
    }

    free(offsets);
    free(keys);
    free(records);
}
