public class ThemeCacheManager {
    private final ConcurrentHashMap<String, Bitmap> cache = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private String cacheRootDirectory = "/default/cache/directory";

    public void setCacheRootDirectory(String directory) {
        this.cacheRootDirectory = directory;
    }

    public Bitmap getThemeBitmap(String themeId) {
        return cache.computeIfAbsent(themeId, id -> loadThemeBitmap(id));
    }

    private Bitmap loadThemeBitmap(String themeId) {
        executorService.submit(() -> {
            try {
                String filePath = cacheRootDirectory + "/" + themeId;
                Bitmap bitmap = ExternalImageProcessingLibrary.loadBitmap(filePath);
                cache.put(themeId, bitmap);
            } catch (Exception e) {
                // Handle error
            }
        });
        return null; // Placeholder for actual implementation
    }

    public void recycleUnusedBitmaps() {
        executorService.submit(() -> {
            cache.entrySet().removeIf(entry -> !entry.getValue().isInUse());
        });
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
