#define MAX_RECORDS 1000
#define MAX_NODES 1000

typedef struct {
    int value;
} record;

typedef struct node {
    int value;
    struct node* next;
} node;

int validate_input(int input, int max_sum) {
    static int current_sum = 0;
    if (current_sum + input > max_sum) {
        return -1;
    }
    current_sum += input;
    return 0;
}

void initialize_offsets(long** offsets, int size) {
    *offsets = (long*)calloc(size, sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    long total = 0;
    for (int i = 0; i < size - 1; i++) {
        int value = rand() % 50001;
        if (validate_input(value, 50000) == -1) {
            fprintf(stderr, "Invalid input for offsets\n");
            exit(EXIT_FAILURE);
        }
        (*offsets)[i] = value;
        total += value;
    }
    (*offsets)[size - 1] = 50000 - total;
}

void initialize_records(record** records, int size) {
    *records = (record*)calloc(size, sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        int value;
        do {
            value = rand() % 100001;
        } while (find_record_value(*records, size, value) != -1);
        (*records)[i].value = value;
    }
}

void initialize_linked_list(node** head, int* keys, int size) {
    *head = NULL;
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        node* new_node = (node*)malloc(sizeof(node));
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed for linked list\n");
            exit(EXIT_FAILURE);
        }
        new_node->value = keys[i];
        new_node->next = *head;
        *head = new_node;
    }
}

void print_records(record* records, int size) {
    for (int i = 0; i < size; i++) {
        printf("Record %d: %d\n", i, records[i].value);
    }
}

void print_linked_list(node* head) {
    node* current = head;
    while (current != NULL) {
        printf("Node value: %d\n", current->value);
        current = current->next;
    }
}

int find_record_value(record* records, int size, int value) {
    for (int i = 0; i < size; i++) {
        if (records[i].value == value) {
            return i;
        }
    }
    return -1;
}

void free_memory(long* offsets, record* records, node* head) {
    free(offsets);
    free(records);
    while (head != NULL) {
        node* temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    int size_offsets, size_records, size_keys;
    printf("Enter the number of offsets: ");
    scanf("%d", &size_offsets);
    if (size_offsets > MAX_RECORDS) {
        fprintf(stderr, "Too many offsets\n");
        return EXIT_FAILURE;
    }

    printf("Enter the number of records: ");
    scanf("%d", &size_records);
    if (size_records > MAX_RECORDS) {
        fprintf(stderr, "Too many records\n");
        return EXIT_FAILURE;
    }

    printf("Enter the number of keys: ");
    scanf("%d", &size_keys);
    if (size_keys > MAX_NODES) {
        fprintf(stderr, "Too many keys\n");
        return EXIT_FAILURE;
    }

    long* offsets = NULL;
    record* records = NULL;
    node* head = NULL;

    initialize_offsets(&offsets, size_offsets);
    initialize_records(&records, size_records);

    int keys[MAX_NODES];
    for (int i = 0; i < size_keys; i++) {
        keys[i] = rand() % 100001;
    }

    initialize_linked_list(&head, keys, size_keys);

    print_records(records, size_records);
    print_linked_list(head);

    free_memory(offsets, records, head);

    return EXIT_SUCCESS;
}
