#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_NODES 50
#define MAX_ENTRIES_PER_NODE 1000

typedef struct entry {
    int key;
    double value;
    struct entry* next;
} entry;

typedef struct node {
    unsigned int id;
    entry** entries;
    struct node* next;
} node;

node** allocate_cache(unsigned int num_nodes, unsigned int max_entries_per_node) {
    if (num_nodes > MAX_NODES || max_entries_per_node > MAX_ENTRIES_PER_NODE) {
        fprintf(stderr, "Invalid input: Number of nodes or entries per node exceeds limits.\n");
        return NULL;
    }

    node** cache = (node**)malloc(num_nodes * sizeof(node*));
    if (!cache) {
        fprintf(stderr, "Memory allocation failed for cache array.\n");
        return NULL;
    }

    srand(time(NULL));

    for (unsigned int i = 0; i < num_nodes; ++i) {
        node* new_node = (node*)malloc(sizeof(node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for node %u.\n", i);
            // Free previously allocated nodes
            for (unsigned int j = 0; j < i; ++j) {
                free(cache[j]);
            }
            free(cache);
            return NULL;
        }

        new_node->id = rand() % (num_nodes * max_entries_per_node); // Simplified ID assignment
        new_node->entries = (entry**)malloc(max_entries_per_node * sizeof(entry*));
        if (!new_node->entries) {
            fprintf(stderr, "Memory allocation failed for entries in node %u.\n", i);
            free(new_node);
            // Free previously allocated nodes
            for (unsigned int j = 0; j < i; ++j) {
                free(cache[j]);
            }
            free(cache);
            return NULL;
        }

        for (unsigned int j = 0; j < max_entries_per_node; ++j) {
            entry* new_entry = (entry*)malloc(sizeof(entry));
            if (!new_entry) {
                fprintf(stderr, "Memory allocation failed for entry %u in node %u.\n", j, i);
                // Free previously allocated entries and nodes
                for (unsigned int k = 0; k < j; ++k) {
                    free(new_node->entries[k]);
                }
                free(new_node->entries);
                free(new_node);
                // Free previously allocated nodes
                for (unsigned int k = 0; k < i; ++k) {
                    free(cache[k]);
                }
                free(cache);
                return NULL;
            }

            new_entry->key = rand() % max_entries_per_node; // Simplified key assignment
            new_entry->value = (double)rand() / RAND_MAX;
            new_entry->next = NULL;

            new_node->entries[j] = new_entry;
        }

        cache[i] = new_node;
    }

    return cache;
}

void free_cache(node** cache, unsigned int num_nodes) {
    for (unsigned int i = 0; i < num_nodes; ++i) {
        node* current_node = cache[i];
        while (current_node) {
            entry* current_entry = current_node->entries[0];
            for (unsigned int j = 1; j < MAX_ENTRIES_PER_NODE; ++j) {
                free(current_entry);
                current_entry = current_node->entries[j];
            }
            free(current_node->entries);
            node* next_node = current_node->next;
            free(current_node);
            current_node = next_node;
        }
    }
    free(cache);
}

int main() {
    unsigned int num_nodes = 10;
    unsigned int max_entries_per_node = 500;

    node** cache = allocate_cache(num_nodes, max_entries_per_node);
    if (cache) {
        // Use the cache
        free_cache(cache, num_nodes);
    }

    return 0;
}
