#include <string.h>
#include <time.h>
#include <uuid/uuid.h>

typedef struct {
    char name[256];
    size_t size;
    time_t mod_time;
    mode_t permissions;
    uuid_t uuid;
} FileSystemEntry;

typedef struct {
    FileSystemEntry* entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} FileSystemCollection;

FileSystemCollection* create_collection() {
    FileSystemCollection* collection = (FileSystemCollection*)malloc(sizeof(FileSystemCollection));
    if (!collection) return NULL;

    collection->entries = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(FileSystemCollection* collection) {
    if (collection->entries) {
        free(collection->entries);
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_entry(FileSystemCollection* collection, const char* name, size_t size, mode_t permissions) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        FileSystemEntry* new_entries = realloc(collection->entries, (collection->capacity + 10) * sizeof(FileSystemEntry));
        if (!new_entries) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->entries = new_entries;
        collection->capacity += 10;
    }

    uuid_generate(collection->entries[collection->count].uuid);
    strcpy(collection->entries[collection->count].name, name);
    collection->entries[collection->count].size = size;
    collection->entries[collection->count].mod_time = time(NULL);
    collection->entries[collection->count].permissions = permissions;

    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int update_mod_time(FileSystemCollection* collection, const uuid_t uuid, time_t new_time) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; i++) {
        if (memcmp(collection->entries[i].uuid, uuid, sizeof(uuid_t)) == 0) {
            collection->entries[i].mod_time = new_time;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1;
}

// Serialization and deserialization functions would go here
