#include <stdlib.h>
#include <time.h>

typedef struct Node {
    double value;
    time_t timestamp;
    struct Node* child;
    struct Node* next;
} Node;

Node* create_node(double value, time_t timestamp) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->value = value;
    new_node->timestamp = timestamp;
    new_node->child = NULL;
    new_node->next = NULL;
    return new_node;
}

void free_node(Node* node) {
    if (node == NULL) {
        return;
    }
    Node* child = node->child;
    while (child != NULL) {
        Node* next_child = child->next;
        free(child);
        child = next_child;
    }
    free(node);
}

Node* insert_child(Node* parent, double value, time_t timestamp) {
    Node* new_child = create_node(value, timestamp);
    if (new_child == NULL) {
        return parent; // Handle memory allocation failure
    }
    new_child->next = parent->child;
    parent->child = new_child;
    return parent;
}

Node* delete_child(Node* parent, double value) {
    Node* current = parent->child;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->value == value) {
            if (previous == NULL) {
                parent->child = current->next;
            } else {
                previous->next = current->next;
            }
            free_node(current);
            return parent;
        }
        previous = current;
        current = current->next;
    }
    return parent;
}

void traverse_nodes(Node* node) {
    while (node != NULL) {
        printf("Value: %f, Timestamp: %ld\n", node->value, node->timestamp);
        Node* child = node->child;
        while (child != NULL) {
            printf("  Child Value: %f, Child Timestamp: %ld\n", child->value, child->timestamp);
            child = child->next;
        }
        node = node->next;
    }
}

void free_all_nodes(Node* node) {
    Node* current = node;
    while (current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
}
