#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
} DoubleEntry;

typedef struct {
    time_t timestamp;
} TimestampEntry;

typedef struct {
    char* event_description;
} EventEntry;

typedef struct {
    int log_id;
    char* message;
} LogEntry;

typedef struct {
    DoubleEntry** doubles;
    TimestampEntry** timestamps;
    EventEntry** events;
    LogEntry** logs;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LoggingFramework;

LoggingFramework* create_logging_framework(size_t initial_capacity) {
    LoggingFramework* framework = (LoggingFramework*)malloc(sizeof(LoggingFramework));
    framework->doubles = (DoubleEntry**)malloc(initial_capacity * sizeof(DoubleEntry*));
    framework->timestamps = (TimestampEntry**)malloc(initial_capacity * sizeof(TimestampEntry*));
    framework->events = (EventEntry**)malloc(initial_capacity * sizeof(EventEntry*));
    framework->logs = (LogEntry**)malloc(initial_capacity * sizeof(LogEntry*));
    framework->capacity = initial_capacity;
    framework->count = 0;
    pthread_mutex_init(&framework->mutex, NULL);
    return framework;
}

void destroy_logging_framework(LoggingFramework* framework) {
    for (size_t i = 0; i < framework->count; ++i) {
        free(framework->doubles[i]);
        free(framework->timestamps[i]);
        free(framework->events[i]);
        free(framework->logs[i]->message);
        free(framework->logs[i]);
    }
    free(framework->doubles);
    free(framework->timestamps);
    free(framework->events);
    free(framework->logs);
    pthread_mutex_destroy(&framework->mutex);
    free(framework);
}

void log_double(LoggingFramework* framework, double value) {
    pthread_mutex_lock(&framework->mutex);
    if (framework->count == framework->capacity) {
        framework->capacity *= 2;
        framework->doubles = (DoubleEntry**)realloc(framework->doubles, framework->capacity * sizeof(DoubleEntry*));
    }
    framework->doubles[framework->count++] = (DoubleEntry*)malloc(sizeof(DoubleEntry));
    framework->doubles[framework->count - 1]->value = value;
    pthread_mutex_unlock(&framework->mutex);
}

void log_timestamp(LoggingFramework* framework, time_t timestamp) {
    // Similar to log_double
}

void log_event(LoggingFramework* framework, const char* event_description) {
    // Similar to log_double
}

void log_message(LoggingFramework* framework, int log_id, const char* message) {
    pthread_mutex_lock(&framework->mutex);
    if (framework->count == framework->capacity) {
        framework->capacity *= 2;
        framework->logs = (LogEntry**)realloc(framework->logs, framework->capacity * sizeof(LogEntry*));
    }
    framework->logs[framework->count++] = (LogEntry*)malloc(sizeof(LogEntry));
    framework->logs[framework->count - 1]->log_id = log_id;
    framework->logs[framework->count - 1]->message = strdup(message);
    pthread_mutex_unlock(&framework->mutex);
}
