typedef struct {
    int value;
    size_t size;
} record;

typedef struct {
    long offset;
    int key;
    record data;
} data_entry;

typedef struct {
    data_entry* entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_data_structure;

dynamic_data_structure* create_dynamic_data_structure(size_t initial_capacity) {
    dynamic_data_structure* dds = (dynamic_data_structure*)malloc(sizeof(dynamic_data_structure));
    if (!dds) return NULL;

    dds->entries = (data_entry*)calloc(initial_capacity, sizeof(data_entry));
    if (!dds->entries) {
        free(dds);
        return NULL;
    }

    dds->capacity = initial_capacity;
    dds->size = 0;
    pthread_mutex_init(&dds->lock, NULL);

    return dds;
}

void destroy_dynamic_data_structure(dynamic_data_structure* dds) {
    if (dds->entries) free(dds->entries);
    pthread_mutex_destroy(&dds->lock);
    free(dds);
}

void add_entry(dynamic_data_structure* dds, long offset, int key, record data) {
    pthread_mutex_lock(&dds->lock);

    if (dds->size >= dds->capacity) {
        size_t new_capacity = dds->capacity * 2;
        data_entry* new_entries = (data_entry*)realloc(dds->entries, new_capacity * sizeof(data_entry));
        if (!new_entries) {
            pthread_mutex_unlock(&dds->lock);
            return;
        }
        dds->entries = new_entries;
        dds->capacity = new_capacity;
    }

    dds->entries[dds->size].offset = offset;
    dds->entries[dds->size].key = key;
    dds->entries[dds->size].data = data;
    dds->size++;

    pthread_mutex_unlock(&dds->lock);
}

