    struct Node *left, *right;
} BSTNode;

typedef struct {
    NetworkRecord records[1000];
    int count;
} PacketArray;

BSTNode* createNode(NetworkRecord data) {
    BSTNode* newNode = (BSTNode*)malloc(sizeof(BSTNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

void insertBST(BSTNode** root, NetworkRecord data) {
    if (*root == NULL) {
        *root = createNode(data);
        return;
    }
    if (strcmp(data.ip, (*root)->data.ip) < 0)
        insertBST(&(*root)->left, data);
    else
        insertBST(&(*root)->right, data);
}

void freeBST(BSTNode* root) {
    if (root != NULL) {
        freeBST(root->left);
        freeBST(root->right);
        free(root);
    }
}

int main() {
    srand(time(0));
    BSTNode* bstRoot = NULL;
    PacketArray packetArray;

    // Initialize network records and insert into BST
    for (int i = 0; i < 1000; i++) {
        NetworkRecord record;
        strcpy(record.ip, "192.168.1.");
        sprintf(record.ip + strlen(record.ip), "%d", rand() % 256);
        record.record_size = rand() % MAX_PACKET_SIZE;
        insertBST(&bstRoot, record);
    }

    // Free allocated memory
    freeBST(bstRoot);

    return 0;
}
