struct TaskPriority {
    int priority;
    // Add other factors for task prioritization
};

class HybridPriorityQueue {
private:
    std::priority_queue<TaskPriority> highPriorityQueue;
    std::queue<TaskPriority> lowPriorityQueue;
    std::mutex queueMutex;
    std::condition_variable condition;

public:
    void push(const Task& task, int priority) {
        std::lock_guard<std::mutex> lock(queueMutex);
        if (priority > 50) { // Example threshold for high priority
            highPriorityQueue.push({priority, task});
        } else {
            lowPriorityQueue.push({priority, task});
        }
        condition.notify_one();
    }

    Task pop() {
        std::unique_lock<std::mutex> lock(queueMutex);
        condition.wait(lock, [this] { return !highPriorityQueue.empty() || !lowPriorityQueue.empty(); });
        if (!highPriorityQueue.empty()) {
            TaskPriority task = highPriorityQueue.top();
            highPriorityQueue.pop();
            return task.task;
        } else {
            TaskPriority task = lowPriorityQueue.front();
            lowPriorityQueue.pop();
            return task.task;
        }
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(queueMutex);
        return highPriorityQueue.empty() && lowPriorityQueue.empty();
    }
};

void processTask(const Task& task) {
    // Implement XML validation and conversion to JSON
    // Implement image processing based on parameters
}

void workerThread(HybridPriorityQueue& queue) {
    while (true) {
        Task task = queue.pop();
        if (task.xmlFilename.empty()) break; // Signal to stop
        processTask(task);
    }
}

void process_image_xml_tasks() {
    HybridPriorityQueue taskQueue;
    std::vector<std::thread> workers;

    // Start worker threads
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers.emplace_back(workerThread, std::ref(taskQueue));
    }

    // Read tasks from standard input and push to queue
    while (true) {
        Task task;
        std::cin >> task.xmlFilename >> task.imageParams;
        if (task.xmlFilename.empty()) break; // Signal to stop
        int priority;
        std::cin >> priority;
        taskQueue.push(task, priority);
    }

    // Stop worker threads
    for (int i = 0; i < workers.size(); ++i) {
        taskQueue.push({}, 0); // Push empty task to signal stop
    }
    for (auto& thread : workers) {
        thread.join();
    }

