#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    long key;
    double value;
    char status;
} Record;

typedef struct hash_table_entry {
    Record *record;
    struct hash_table_entry *next;
} HashTableEntry;

typedef struct hash_table {
    int size;
    HashTableEntry **buckets;
    pthread_mutex_t lock;
} HashTable;

unsigned long custom_hash(long key, int size) {
    return (key % size);
}

HashTable* create_hash_table(int initial_size) {
    HashTable *table = malloc(sizeof(HashTable));
    table->size = initial_size;
    table->buckets = calloc(initial_size, sizeof(HashTableEntry *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable *table, Record *record) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = custom_hash(record->key, table->size);
    HashTableEntry *entry = malloc(sizeof(HashTableEntry));
    entry->record = record;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;
    pthread_mutex_unlock(&table->lock);
}

Record* find_record(HashTable *table, long key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = custom_hash(key, table->size);
    HashTableEntry *entry = table->buckets[index];
    while (entry != NULL) {
        if (entry->record->key == key) {
            pthread_mutex_unlock(&table->lock);
            return entry->record;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_record(HashTable *table, long key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = custom_hash(key, table->size);
    HashTableEntry *entry = table->buckets[index];
    HashTableEntry *prev = NULL;
    while (entry != NULL) {
        if (entry->record->key == key) {
            if (prev == NULL) {
                table->buckets[index] = entry->next;
            } else {
                prev->next = entry->next;
            }
            free(entry);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        prev = entry;
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        HashTableEntry *entry = table->buckets[i];
        while (entry != NULL) {
            HashTableEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
