    for (size_t i = 0; i < collection->count; ++i) {
        Record *record = &collection->records[i];
        record->offset = rand() % offset_range;
        record->key = rand() % (max_key - min_key + 1) + min_key;
        record->value = rand();
        record->size = sizeof(Record);
    }
}

void serialize_record_collection(const RecordCollection *collection, FILE *file) {
    fwrite(&collection->count, sizeof(size_t), 1, file);
    fwrite(collection->records, sizeof(Record), collection->count, file);
}

int deserialize_record_collection(RecordCollection *collection, FILE *file) {
    size_t count;
    if (fread(&count, sizeof(size_t), 1, file) != 1) return -1;

    Record *new_records = realloc(collection->records, count * sizeof(Record));
