    int count;
    pthread_mutex_t lock;
} TaskManager;

TaskManager task_manager = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void add_task(int id, int priority, const char* status, void* metadata, DataType type) {
    pthread_mutex_lock(&task_manager.lock);
    if (task_manager.count < MAX_TASKS) {
        Task* new_task = &task_manager.tasks[task_manager.count++];
        new_task->id = id;
        new_task->priority = priority;
        strcpy(new_task->status, status);
        for (int i = 0; i < METADATA_SIZE; i++) {
            if (i < METADATA_SIZE) {
                switch (type) {
                    case INT:
                        new_task->metadata[i].i = *(int*)metadata;
                        break;
                    case FLOAT:
                        new_task->metadata[i].f = *(float*)metadata;
                        break;
                    case CHAR_PTR:
                        new_task->metadata[i].s = strdup((char*)metadata);
                        break;
                }
            } else {
                new_task->metadata[i].i = 0; // Initialize unused fields
            }
        }
    }
    pthread_mutex_unlock(&task_manager.lock);
}

void free_metadata(Task* task) {
    for (int i = 0; i < METADATA_SIZE; i++) {
        if (task->metadata[i].s != NULL) {
            free(task->metadata[i].s);
        }
    }
}

void remove_task(int id) {
    pthread_mutex_lock(&task_manager.lock);
    for (int i = 0; i < task_manager.count; i++) {
        if (task_manager.tasks[i].id == id) {
            free_metadata(&task_manager.tasks[i]);
            memmove(&task_manager.tasks[i], &task_manager.tasks[i + 1], sizeof(Task) * (task_manager.count - i - 1));
            task_manager.count--;
            break;
        }
    }
    pthread_mutex_unlock(&task_manager.lock);
}

void* fetch_task_data(void* arg) {
    // Simulate fetching task data from an external API
    int id = *(int*)arg;
    // Fetch data and update task manager
    return NULL;
}

void manage_tasks() {
    pthread_t threads[MAX_TASKS];
    int ids[MAX_TASKS];

    for (int i = 0; i < MAX_TASKS; i++) {
        ids[i] = i + 1;
        pthread_create(&threads[i], NULL, fetch_task_data, &ids[i]);
    }

    for (int i = 0; i < MAX_TASKS; i++) {
        pthread_join(threads[i], NULL);
    }
}

void cleanup() {
    pthread_mutex_lock(&task_manager.lock);
    for (int i = 0; i < task_manager.count; i++) {
