['```rust
use std::env;
use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::path::Path;
use log::{error, info};

const DEFAULT_PORT: u16 = 8080;
const CONFIG_FILE_PATH: &str = "server_config.txt";

fn get_server_port() -> u16 {
    env::var("SERVER_PORT")
        .ok()
        .and_then(|port| port.parse().ok())
        .unwrap_or(DEFAULT_PORT)
}

fn ensure_config_file_exists(path: &Path) -> io::Result<()> {
    if !path.exists() {
        File::create(path)?;
        info!("Created new configuration file at {:?}", path);
    }
    Ok(())
}

fn update_config_file(port: u16, path: &Path) -> io::Result<()> {
    let mut file = OpenOptions::new()
        .write(true)
        .truncate(true)
        .open(path)?;

    writeln!(file, "Server Port: {}", port)?;
    info!("Updated configuration file at {:?}", path);
    Ok(())
}

fn manage_server_config() -> io::Result<()> {
    let port = get_server_port();
    let config_path = Path::new(CONFIG_FILE_PATH);

    ensure_config_file_exists(&config_path)?;
    update_config_file(port, &config_path)?;

    Ok(())
}

fn main() {
    if let Err(e) = manage_server_config() {
        error!("Failed to manage server configuration: {}", e);
    }
}
```

