#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    int value;
    time_t last_accessed;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} hash_table;

hash_table* create_hash_table() {
    hash_table *ht = (hash_table*)malloc(sizeof(hash_table));
    ht->capacity = INITIAL_CAPACITY;
    ht->size = 0;
    ht->offsets = (long*)calloc(ht->capacity, sizeof(long));
    ht->keys = (int*)calloc(ht->capacity, sizeof(int));
    ht->records = (record**)calloc(ht->capacity, sizeof(record*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->records[i] != NULL) {
            free(ht->records[i]);
        }
    }
    free(ht->offsets);
    free(ht->keys);
    free(ht->records);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

size_t hash_function(int key, size_t capacity) {
    return (key * 31) % capacity;
}

void resize_hash_table(hash_table *ht) {
    size_t new_capacity = ht->capacity * 2;
    long *new_offsets = (long*)calloc(new_capacity, sizeof(long));
    int *new_keys = (int*)calloc(new_capacity, sizeof(int));
    record **new_records = (record**)calloc(new_capacity, sizeof(record*));

    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->records[i] != NULL) {
            size_t new_index = hash_function(ht->keys[i], new_capacity);
            while (new_records[new_index] != NULL) {
                new_index = (new_index + 1) % new_capacity;
            }
            new_offsets[new_index] = ht->offsets[i];
            new_keys[new_index] = ht->keys[i];
            new_records[new_index] = ht->records[i];
        }
    }

    free(ht->offsets);
    free(ht->keys);
    free(ht->records);

    ht->offsets = new_offsets;
    ht->keys = new_keys;
    ht->records = new_records;
    ht->capacity = new_capacity;
}

void insert_record(hash_table *ht, int key, long offset) {
    pthread_mutex_lock(&ht->lock);
    if (ht->size >= ht->capacity * LOAD_FACTOR) {
        resize_hash_table(ht);
    }
    size_t index = hash_function(key, ht->capacity);
    while (ht->records[index] != NULL) {
        index = (index + 1) % ht->capacity;
    }
    record *new_record = (record*)malloc(sizeof(record));
    new_record->value = rand() % 1000; // Random value within range
    new_record->last_accessed = time(NULL);
    ht->offsets[index] = offset;
    ht->keys[index] = key;
    ht->records[index] = new_record;
    ++ht->size;
    pthread_mutex_unlock(&ht->lock);
}

record* get_record(hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->capacity);
    while (ht->keys[index] != key && ht->records[index] != NULL) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->records[index] == NULL) {
        pthread_mutex_unlock(&ht->lock);
        return NULL;
    }
    record *found_record = ht->records[index];
    found_record->last_accessed = time(NULL);
    pthread_mutex_unlock(&ht->lock);
    return found_record;
}

void cleanup_unused_records(hash_table *ht, time_t threshold) {
    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->records[i] != NULL && difftime(time(NULL), ht->records[i]->last_accessed) > threshold) {
            free(ht->records[i]);
            ht->records[i] = NULL;
            --ht->size;
        }
    }
    pthread_mutex_unlock(&ht->lock);
}
