#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long *offsets;
    int *keys;
    record *records;
} memory_manager;

memory_manager* create_memory_manager(int num_offsets, int min_key, int max_key, long max_offset) {
    if (num_offsets <= 0 || min_key > max_key || max_offset < 0) {
        fprintf(stderr, "Invalid parameters\n");
        return NULL;
    }

    memory_manager *mm = malloc(sizeof(memory_manager));
    if (!mm) {
        perror("Failed to allocate memory for memory manager");
        return NULL;
    }

    mm->offsets = malloc(num_offsets * sizeof(long));
    if (!mm->offsets) {
        perror("Failed to allocate memory for offsets");
        free(mm);
        return NULL;
    }

    mm->keys = malloc(num_offsets * sizeof(int));
    if (!mm->keys) {
        perror("Failed to allocate memory for keys");
        free(mm->offsets);
        free(mm);
        return NULL;
    }

    mm->records = malloc(num_offsets * sizeof(record));
    if (!mm->records) {
        perror("Failed to allocate memory for records");
        free(mm->keys);
        free(mm->offsets);
        free(mm);
        return NULL;
    }

    // Initialize offsets and keys
    for (int i = 0; i < num_offsets; i++) {
        mm->offsets[i] = rand() % max_offset;
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (is_key_used(mm, key));
        mm->keys[i] = key;
    }

    // Initialize records
    for (int i = 0; i < num_offsets; i++) {
        mm->records[i].offset = &mm->offsets[i];
        mm->records[i].key = &mm->keys[i];
    }

    return mm;
}

void destroy_memory_manager(memory_manager *mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    free(mm);
}

int is_key_used(memory_manager *mm, int key) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (mm->records[i].key && *mm->records[i].key == key) {
            return 1;
        }
    }
    return 0;
}

void print_records(memory_manager *mm, int num_offsets) {
    for (int i = 0; i < num_offsets; i++) {
        printf("Record %d: Offset = %ld, Key = %d\n", i, *(mm->records[i].offset), *(mm->records[i].key));
    }
}

int main() {
    srand(time(NULL));

    int num_offsets = 10;
    int min_key = 1;
    int max_key = 100;
    long max_offset = 1000;

    memory_manager *mm = create_memory_manager(num_offsets, min_key, max_key, max_offset);
    if (mm) {
        print_records(mm, num_offsets);
        destroy_memory_manager(mm);
    }

    return 0;
}
