#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define LOAD_FACTOR 0.75

typedef struct Record {
    int value;
    time_t timestamp;
    struct Record* dependencies[10];
    int dependency_count;
} Record;

typedef struct HashTable {
    Record** buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash_function(const char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

void resize_hash_table(HashTable* table) {
    size_t new_capacity = table->capacity * 2;
    Record** old_buckets = table->buckets;
    table->buckets = (Record**)calloc(new_capacity, sizeof(Record*));
    table->capacity = new_capacity;
    table->size = 0;

    for (size_t i = 0; i < old_capacity; ++i) {
        Record* record = old_buckets[i];
        if (record != NULL) {
            size_t index = hash_function(record->key);
            while (table->buckets[index] != NULL) {
                index = (index + 1) % table->capacity;
            }
            table->buckets[index] = record;
            ++table->size;
        }
    }

    free(old_buckets);
}

void add_record(HashTable* table, const char* key, int value) {
    if ((double)table->size / table->capacity > LOAD_FACTOR) {
        resize_hash_table(table);
    }

    size_t index = hash_function(key);
    while (table->buckets[index] != NULL) {
        index = (index + 1) % table->capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value;
    record->timestamp = time(NULL);
    record->dependency_count = 0;

    table->buckets[index] = record;
    ++table->size;
}

void remove_record(HashTable* table, const char* key) {
    size_t index = hash_function(key);
    while (table->buckets[index] != NULL) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            Record* record = table->buckets[index];
            table->buckets[index] = NULL;
            free(record);
            --table->size;
            return;
        }
        index = (index + 1) % table->capacity;
    }
}

void update_record(HashTable* table, const char* key, int value) {
    size_t index = hash_function(key);
    while (table->buckets[index] != NULL) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            Record* record = table->buckets[index];
            record->value = value;
            record->timestamp = time(NULL);
            return;
        }
        index = (index + 1) % table->capacity;
    }
}

Record* get_record(HashTable* table, const char* key) {
    size_t index = hash_function(key);
    while (table->buckets[index] != NULL) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            Record* record = table->buckets[index];
            record->timestamp = time(NULL); // Update timestamp on access
            return record;
        }
        index = (index + 1) % table->capacity;
    }
    return NULL;
}

void cleanup_old_records(HashTable* table, time_t threshold) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record* record = table->buckets[i];
        if (record != NULL && difftime(time(NULL), record->timestamp) > threshold) {
            remove_record(table, record->key);
        }
    }
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record* record = table->buckets[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(table->buckets);
    free(table);
}
