#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LogEntry {
    char timestamp[20];
    int severity;
    char message[1024];
    time_t last_accessed;
    struct LogEntry *next;
} LogEntry;

typedef struct TrieNode {
    struct TrieNode *children[256]; // Assuming ASCII characters
    LogEntry *logs;
    pthread_mutex_t lock;
} TrieNode;

TrieNode *create_node() {
    TrieNode *node = (TrieNode *)malloc(sizeof(TrieNode));
    if (!node) return NULL;
    for (int i = 0; i < 256; i++) node->children[i] = NULL;
    node->logs = NULL;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void insert_log(TrieNode *root, const char *key, LogEntry *log) {
    TrieNode *current = root;
    for (int i = 0; key[i]; i++) {
        int index = (unsigned char)key[i];
        if (!current->children[index]) {
            current->children[index] = create_node();
        }
        pthread_mutex_lock(&current->lock);
        current = current->children[index];
        pthread_mutex_unlock(&current->lock);
    }
    log->last_accessed = time(NULL);
    log->next = current->logs;
    current->logs = log;
}

LogEntry *search_log(TrieNode *root, const char *key) {
    TrieNode *current = root;
    for (int i = 0; key[i]; i++) {
        int index = (unsigned char)key[i];
        if (!current->children[index]) return NULL;
        pthread_mutex_lock(&current->lock);
        current = current->children[index];
        pthread_mutex_unlock(&current->lock);
    }
    LogEntry *entry = current->logs;
    while (entry) {
        if (strcmp(entry->timestamp, key) == 0) {
            entry->last_accessed = time(NULL);
            return entry;
        }
        entry = entry->next;
    }
    return NULL;
}

void archive_logs(TrieNode *root, time_t cutoff) {
    TrieNode *current = root;
    for (int i = 0; i < 256; i++) {
        if (current->children[i]) {
            pthread_mutex_lock(&current->lock);
            archive_logs(current->children[i], cutoff);
            pthread_mutex_unlock(&current->lock);
        }
    }
    LogEntry *entry = current->logs;
    while (entry) {
        if (difftime(time(NULL), entry->last_accessed) > cutoff) {
            LogEntry *temp = entry;
            entry = entry->next;
            free(temp);
        } else {
            entry = entry->next;
        }
    }
}

void destroy_node(TrieNode *node) {
    for (int i = 0; i < 256; i++) {
        if (node->children[i]) {
            pthread_mutex_lock(&node->lock);
            destroy_node(node->children[i]);
            pthread_mutex_unlock(&node->lock);
        }
    }
    free(node);
}

void destroy_log_system(TrieNode *root) {
    destroy_node(root);
}
