#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} record;

typedef struct {
    record **records;
    size_t count;
    pthread_mutex_t lock;
} record_manager;

record_manager* create_record_manager(size_t initial_capacity) {
    record_manager *rm = (record_manager*)malloc(sizeof(record_manager));
    rm->records = (record**)calloc(initial_capacity, sizeof(record*));
    rm->count = 0;
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

void destroy_record_manager(record_manager *rm) {
    for (size_t i = 0; i < rm->count; ++i) {
        free(rm->records[i]);
    }
    free(rm->records);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

record* create_record(long offset, int key, record_manager *rm) {
    pthread_mutex_lock(&rm->lock);
    if (rm->count >= rm->capacity) {
        // Resize the records array
        size_t new_capacity = rm->capacity ? rm->capacity * 2 : 16;
        record **new_records = (record**)realloc(rm->records, new_capacity * sizeof(record*));
        if (!new_records) {
            pthread_mutex_unlock(&rm->lock);
            return NULL; // Memory allocation failed
        }
        rm->records = new_records;
        rm->capacity = new_capacity;
    }

    record *r = (record*)malloc(sizeof(record));
    r->value = rand() % 1000; // Random value between 0 and 999
    r->offset = &offset;
    r->key = &key;

    rm->records[rm->count++] = r;
    pthread_mutex_unlock(&rm->lock);
    return r;
}

void destroy_record(record *r, record_manager *rm) {
    pthread_mutex_lock(&rm->lock);
    for (size_t i = 0; i < rm->count; ++i) {
        if (rm->records[i] == r) {
            free(r);
            memmove(&rm->records[i], &rm->records[i + 1], (rm->count - i - 1) * sizeof(record*));
            --rm->count;
            break;
        }
    }
    pthread_mutex_unlock(&rm->lock);
}

