int next_record_index = 0;

pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

void init_memory_management() {
    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_mutex_init(&keys[i].lock, NULL);
    }
}

key* create_key(int key_value) {
    if (next_key_index >= MAX_KEYS) return NULL;
    key* k = &keys[next_key_index++];
    k->key = key_value;
    k->ref_count = 1;
    k->timestamp = time(NULL);
    pthread_mutex_lock(&k->lock);
    return k;
}

void destroy_key(key* k) {
    if (k == NULL) return;
    pthread_mutex_lock(&k->lock);
    k->ref_count--;
    if (k->ref_count <= 0) {
        pthread_mutex_unlock(&k->lock);
        free(k);
    } else {
        pthread_mutex_unlock(&k->lock);
    }
}

record* create_record(int value, const char* metadata, size_t metadata_size) {
