class FrequencyCounter {
public:
    void addEvent(int event) {
        std::lock_guard<std::mutex> lock(mutex_);
        frequency_[event]++;
    }

    void flush() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !queue_.empty(); });
        while (!queue_.empty()) {
            int event = queue_.front();
            queue_.pop();
            // Flush the event to external storage
            flushEvent(event);
        }
    }

private:
    void flushEvent(int event) {
        // Implement flushing logic here
    }

    std::mutex mutex_;
    std::condition_variable condition_;
    std::unordered_map<int, std::atomic<int>> frequency_;
    std::queue<int> queue_;
};

int main() {
    FrequencyCounter counter;
    std::thread flushThread([&counter]() {
        while (true) {
            counter.flush();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    // Simulate adding events
    for (int i = 0; i < 1000000; ++i) {
        counter.addEvent(i % 100);
    }

    flushThread.join();
    return 0;
}
