#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <uuid/uuid.h>
#include <pthread.h>

#define MAX_ENTRIES 1024

typedef struct {
    char name[256];
    size_t size;
    time_t mod_time;
    mode_t permissions;
    uuid_t uuid;
} FileSystemEntry;

typedef struct {
    FileSystemEntry *entries;
    int count;
    pthread_mutex_t lock;
} FileSystemCollection;

void init_collection(FileSystemCollection *collection) {
    collection->entries = (FileSystemEntry *)malloc(MAX_ENTRIES * sizeof(FileSystemEntry));
    if (!collection->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_entry(FileSystemCollection *collection, const char *name, size_t size, mode_t permissions) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= MAX_ENTRIES) {
        fprintf(stderr, "Collection is full\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }
    FileSystemEntry *entry = &collection->entries[collection->count++];
    strcpy(entry->name, name);
    entry->size = size;
    entry->mod_time = time(NULL);
    entry->permissions = permissions;
    uuid_generate(entry->uuid);
    pthread_mutex_unlock(&collection->lock);
}

void update_mod_time(FileSystemCollection *collection, const char *name, time_t new_time) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->count; ++i) {
        if (strcmp(collection->entries[i].name, name) == 0) {
            collection->entries[i].mod_time = new_time;
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

void serialize_collection(FileSystemCollection *collection, FILE *file) {
    fwrite(&collection->count, sizeof(int), 1, file);
    for (int i = 0; i < collection->count; ++i) {
        fwrite(collection->entries[i].name, sizeof(char), 256, file);
        fwrite(&collection->entries[i].size, sizeof(size_t), 1, file);
        fwrite(&collection->entries[i].mod_time, sizeof(time_t), 1, file);
        fwrite(&collection->entries[i].permissions, sizeof(mode_t), 1, file);
        uuid_unparse(collection->entries[i].uuid, (char *)collection->entries[i].name + 256);
    }
}

void deserialize_collection(FileSystemCollection *collection, FILE *file) {
    int count;
    fread(&count, sizeof(int), 1, file);
    if (count > MAX_ENTRIES) {
        fprintf(stderr, "Too many entries\n");
        return;
    }
    collection->count = count;
    for (int i = 0; i < count; ++i) {
        fread(collection->entries[i].name, sizeof(char), 256, file);
        fread(&collection->entries[i].size, sizeof(size_t), 1, file);
        fread(&collection->entries[i].mod_time, sizeof(time_t), 1, file);
        fread(&collection->entries[i].permissions, sizeof(mode_t), 1, file);
        uuid_parse((char *)collection->entries[i].name + 256, collection->entries[i].uuid);
    }
}

void cleanup_collection(FileSystemCollection *collection) {
    pthread_mutex_destroy(&collection->lock);
    free(collection->entries);
}
