    pthread_mutex_t lock;
} ThreadPool;

ThreadPool pool;

void init_pool(int num_threads) {
    pool.front = pool.rear = 0;
    sem_init(&pool.task_count, 0, 0);
    pthread_mutex_init(&pool.lock, NULL);

    for (int i = 0; i < num_threads; ++i) {
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, worker_thread, NULL);
    }
}

void enqueue_task(void (*task_func)(void*), void* arg) {
    pthread_mutex_lock(&pool.lock);
    pool.tasks[pool.rear].task_func = task_func;
    pool.tasks[pool.rear].arg = arg;
    pool.rear = (pool.rear + 1) % MAX_TASKS;
    sem_post(&pool.task_count);
    pthread_mutex_unlock(&pool.lock);
}

void* worker_thread(void* arg) {
    while (1) {
        sem_wait(&pool.task_count);
        pthread_mutex_lock(&pool.lock);

        if (pool.front == pool.rear) {
            // No tasks available, exit thread
            pthread_mutex_unlock(&pool.lock);
            break;
        }

        Task task = pool.tasks[pool.front];
        pool.front = (pool.front + 1) % MAX_TASKS;

        pthread_mutex_unlock(&pool.lock);

        task.task_func(task.arg);
    }
    return NULL;
}

void* example_task(void* arg) {
    int id = *(int*)arg;
    printf("Task %d is running\n", id);
    sleep(2); // Simulate task execution time
    printf("Task %d completed\n", id);
    free(arg);
    return NULL;
}

int main() {
    init_pool(5);

    for (int i = 0; i < 10; ++i) {
        int* task_id = malloc(sizeof(int));
        *task_id = i;
        enqueue_task(example_task, task_id);
    }

    // Wait for all tasks to complete
    sleep(30);

    return 0;
}
```

This code provides a basic implementation of a thread pool in C. It includes functions to initialize the pool, enqueue tasks, and handle worker threads. The `example_task` function demonstrates how tasks can be executed. The main function initializes the pool with 5 worker threads and enqueues 10 tasks.

Please note that this is a simplified example and does not include advanced features such as dynamic thread scaling, error handling, or monitoring. For a production environment, you would need to add these features and ensure proper synchronization and resource management.']

