#include <stdio.h>
#include <stdlib.h>

typedef struct sensor_node {
    int id;
    long *timestamp;
    float temperature;
    struct sensor_node *next;
} sensor_node;

sensor_node* create_sensor_list(long *timestamps, float *temperatures, int count) {
    if (count <= 0 || timestamps == NULL || temperatures == NULL) {
        return NULL;
    }

    sensor_node *head = NULL;
    sensor_node **current = &head;

    for (int i = 0; i < count; ++i) {
        sensor_node *new_node = (sensor_node *)malloc(sizeof(sensor_node));
        if (new_node == NULL) {
            // Handle memory allocation failure
            while (*current != NULL) {
                sensor_node *temp = *current;
                *current = (*current)->next;
                free(temp);
            }
            return NULL;
        }

        new_node->id = i + 1; // Assuming IDs start from 1
        new_node->timestamp = &timestamps[i];
        new_node->temperature = temperatures[i];
        new_node->next = NULL;

        *current = new_node;
        current = &new_node->next;
    }

    return head;
}

void free_sensor_list(sensor_node *head) {
    while (head != NULL) {
        sensor_node *temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    long timestamps[] = {1633072800, 1633072805, 1633072810};
    float temperatures[] = {22.5, 23.0, 22.8};

    int count = sizeof(timestamps) / sizeof(timestamps[0]);

    sensor_node *sensor_list = create_sensor_list(timestamps, temperatures, count);
    if (sensor_list != NULL) {
        // Use the sensor list
        free_sensor_list(sensor_list);
    }

    return 0;
}
