typedef struct {
    int value;
} record;

long* offsets = NULL;
int* keys = NULL;
record** records = NULL;
int num_keys = 0;
int max_offset = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_data_structures(int num_keys, int max_offset) {
    offsets = (long*)malloc(num_keys * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(1);
    }

    keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        exit(1);
    }

    records = (record**)malloc(num_keys * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % max_offset;
        offsets[keys[i]] = i;
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            free(offsets);
            free(keys);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            exit(1);
        }
        records[i]->value = rand() % 100;
    }

    this->num_keys = num_keys;
    this->max_offset = max_offset;
}

void update_offsets(int key, long new_offset) {
    pthread_mutex_lock(&lock);
    if (key >= 0 && key < num_keys) {
        offsets[key] = new_offset;
    }
    pthread_mutex_unlock(&lock);
}

int get_record_value(int key) {
    int index = offsets[key];
    return records[index]->value;
}

void free_data_structures() {
    for (int i = 0; i < num_keys; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

// Example usage
int main() {
    init_data_structures(1000, 10000);
    update_offsets(500, 2000);
    printf("Record value at key 500: %d\n", get_record_value(500));
    free_data_structures();
    return 0;
}
```

