#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SENSORS 10000000

typedef struct sensor_node {
    int id;
    struct sensor_node* next;
    long* timestamp;
    void** hash_table_entry;
} sensor_node;

sensor_node* sensor_list[MAX_SENSORS];
void* hash_table[MAX_SENSORS];

long timestamps[MAX_SENSORS];
float temperatures[MAX_SENSORS];

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t table_lock = PTHREAD_MUTEX_INITIALIZER;

int allocate_sensor(int id, long timestamp) {
    if (id >= MAX_SENSORS) return -1; // Error: ID out of range

    sensor_node* new_node = malloc(sizeof(sensor_node));
    if (!new_node) return -2; // Error: Memory allocation failed

    new_node->id = id;
    new_node->timestamp = &timestamps[id];
    new_node->hash_table_entry = &hash_table[id];

    pthread_mutex_lock(&list_lock);
    new_node->next = sensor_list[id];
    sensor_list[id] = new_node;
    pthread_mutex_unlock(&list_lock);

    return 0; // Success
}

void free_sensor(int id) {
    if (id >= MAX_SENSORS) return;

    pthread_mutex_lock(&list_lock);
    sensor_node* current = sensor_list[id];
    while (current) {
        sensor_node* next = current->next;
        free(current);
        current = next;
    }
    sensor_list[id] = NULL;
    pthread_mutex_unlock(&list_lock);

    pthread_mutex_lock(&table_lock);
    hash_table[id] = NULL;
    pthread_mutex_unlock(&table_lock);
}

int update_temperature(int id, float temperature) {
    if (id >= MAX_SENSORS) return -1; // Error: ID out of range

    pthread_mutex_lock(&table_lock);
    if (!hash_table[id]) {
        pthread_mutex_unlock(&table_lock);
        return -2; // Error: Sensor not found
    }

    temperatures[id] = temperature;
    pthread_mutex_unlock(&table_lock);

    return 0; // Success
}

int get_temperature(int id) {
    if (id >= MAX_SENSORS) return -1; // Error: ID out of range

    pthread_mutex_lock(&table_lock);
    float temp = temperatures[id];
    pthread_mutex_unlock(&table_lock);

    return temp;
}
