#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_CONCURRENT_TRANSFERS 10
#define MAX_MEMORY_USAGE_THRESHOLD 500 // in MB

typedef struct {
    char *file_path;
    int transfer_id;
} FileTransfer;

typedef struct {
    json_object *config;
    pthread_mutex_t lock;
    int current_transfers;
    size_t total_memory_used;
} TransferManager;

void* file_transfer_thread(void* arg) {
    FileTransfer *transfer = (FileTransfer*)arg;
    // Simulate file transfer
    sleep(2); // Simulating time taken for file transfer
    printf("File %s transferred successfully. Transfer ID: %d\n", transfer->file_path, transfer->transfer_id);
    free(transfer);
    return NULL;
}

int validate_json_config(json_object *config) {
    // Implement JSON validation logic here
    // Return 0 on success, non-zero on failure
    return 0; // Placeholder
}

void* parse_and_validate_json(void* arg) {
    TransferManager *manager = (TransferManager*)arg;
    json_object *config = manager->config;

    if (validate_json_config(config)) {
        printf("JSON configuration is invalid.\n");
        return NULL;
    }

    int num_files = json_object_array_length(config);
    for (int i = 0; i < num_files; i++) {
        json_object *file_obj = json_object_array_get_idx(config, i);
        const char *file_path = json_object_get_string(json_object_object_get_ex(file_obj, "path", NULL));

        if (!file_path) {
            printf("File path missing in configuration.\n");
            continue;
        }

        FileTransfer *transfer = (FileTransfer*)malloc(sizeof(FileTransfer));
        transfer->file_path = strdup(file_path);
        transfer->transfer_id = i;

        pthread_mutex_lock(&manager->lock);
        if (manager->current_transfers >= MAX_CONCURRENT_TRANSFERS) {
            printf("Maximum concurrent transfers reached.\n");
            pthread_mutex_unlock(&manager->lock);
            free(transfer);
            continue;
        }
        manager->current_transfers++;
        pthread_mutex_unlock(&manager->lock);

        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, file_transfer_thread, transfer) != 0) {
            printf("Failed to create thread for file transfer.\n");
            free(transfer);
            continue;
        }

        // Simulate memory usage
        manager->total_memory_used += strlen(file_path);

        if (manager->total_memory_used > MAX_MEMORY_USAGE_THRESHOLD * 1024 * 1024) {
            printf("Memory usage threshold exceeded.\n");
            pthread_mutex_lock(&manager->lock);
            manager->current_transfers--;
            pthread_mutex_unlock(&manager->lock);
            pthread_cancel(thread_id);
        }
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <json_config_file>\n", argv[0]);
        return 1;
    }

    TransferManager manager = {0};
    pthread_mutex_init(&manager.lock, NULL);

    json_object *config = json_object_from_file(argv[1]);
    if (!config) {
        printf("Failed to load JSON configuration.\n");
        return 1;
    }
    manager.config = config;

    parse_and_validate_json(&manager);

    json_object_put(config);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
