#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    int* value;
} Record;

Record** create_records(int size, int min_val, int max_val) {
    if (size <= 0 || size > MAX_RECORDS) {
        fprintf(stderr, "Invalid size: %d\n", size);
        return NULL;
    }

    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (!records) {
        perror("Failed to allocate memory for record pointers");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = i * sizeof(Record); // Example offset calculation
        records[i]->key = rand() % (max_val - min_val + 1) + min_val;
        records[i]->value = (int*)malloc(sizeof(int));
        if (!records[i]->value) {
            perror("Failed to allocate memory for record value");
            // Free previously allocated records and values
            for (int j = 0; j <= i; ++j) {
                free(records[j]->value);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        *records[i]->value = rand() % (max_val - min_val + 1) + min_val;
    }

    return records;
}

void cleanup_records(Record** records, int size) {
    if (!records) {
        fprintf(stderr, "Invalid input: records is NULL\n");
        return;
    }

    for (int i = 0; i < size; ++i) {
        free(records[i]->value);
        free(records[i]);
    }
    free(records);
}

int main() {
    int size, min_val, max_val;

    printf("Enter the number of records: ");
    scanf("%d", &size);

    printf("Enter the minimum value for random numbers: ");
    scanf("%d", &min_val);

    printf("Enter the maximum value for random numbers: ");
    scanf("%d", &max_val);

    Record** records = create_records(size, min_val, max_val);
    if (records) {
        // Use the records here
        cleanup_records(records, size);
    }

    return 0;
}
```

This code snippet provides a basic implementation of the described functionality. It includes error handling for memory allocation failures and ensures that the random number generator is seeded correctly. The `create_records` function dynamically allocates memory for an array of records, initializes each record with a random value within the specified range, and returns a pointer to the array of record pointers. The `cleanup_records` function frees all allocated memory when it's no longer needed. The `main` function demonstrates how to use these functions by prompting the user for input and then creating and cleaning up records accordingly.']

