#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double value;
    size_t capacity;
} CustomData;

typedef struct {
    double* doubles;
    unsigned long* keys;
    CustomData* custom;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DataStorage;

void init_data_storage(DataStorage* storage, size_t initial_capacity) {
    storage->doubles = (double*)malloc(initial_capacity * sizeof(double));
    storage->keys = (unsigned long*)malloc(initial_capacity * sizeof(unsigned long));
    storage->custom = (CustomData*)malloc(initial_capacity * sizeof(CustomData));
    storage->count = 0;
    storage->capacity = initial_capacity;
    pthread_mutex_init(&storage->mutex, NULL);
}

void free_data_storage(DataStorage* storage) {
    free(storage->doubles);
    free(storage->keys);
    free(storage->custom);
    pthread_mutex_destroy(&storage->mutex);
}

int add_data(DataStorage* storage, double value, unsigned long key) {
    pthread_mutex_lock(&storage->mutex);
    if (storage->count >= storage->capacity) {
        size_t new_capacity = storage->capacity * 2;
        double* new_doubles = (double*)realloc(storage->doubles, new_capacity * sizeof(double));
        unsigned long* new_keys = (unsigned long*)realloc(storage->keys, new_capacity * sizeof(unsigned long));
        CustomData* new_custom = (CustomData*)realloc(storage->custom, new_capacity * sizeof(CustomData));
