        if (collection->events[i].payload.payload_size > 0) {
            free(collection->events[i].payload.str_payload);
        }
    }
    pthread_mutex_destroy(&collection->lock);
    free(collection->events);
}

void add_event(EventCollection *collection, Event event) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        Event *new_events = realloc(collection->events, new_capacity * sizeof(Event));
        if (!new_events) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->events = new_events;
        collection->capacity = new_capacity;
