#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long offset;
    int key;
    record rec;
    size_t size;
    time_t timestamp;
} structured_record;

typedef struct {
    structured_record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} record_collection;

record_collection* create_record_collection(size_t initial_capacity) {
    record_collection* collection = (record_collection*)malloc(sizeof(record_collection));
    if (!collection) return NULL;

    collection->records = (structured_record*)calloc(initial_capacity, sizeof(structured_record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(record_collection* collection) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].rec.value); // Assuming dynamic allocation for rec.value
    }
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void resize_record_collection(record_collection* collection, size_t new_capacity) {
    if (new_capacity <= collection->capacity) return;

    pthread_mutex_lock(&collection->mutex);
    structured_record* new_records = (structured_record*)realloc(collection->records, new_capacity * sizeof(structured_record));
    if (!new_records) {
        pthread_mutex_unlock(&collection->mutex);
        return;
    }

    memset(new_records + collection->count, 0, (new_capacity - collection->count) * sizeof(structured_record));
    collection->records = new_records;
    collection->capacity = new_capacity;
    pthread_mutex_unlock(&collection->mutex);
}

void add_record(record_collection* collection, long offset, int key, int rec_value, size_t size) {
    if (collection->count >= collection->capacity) resize_record_collection(collection, collection->capacity * 2);

    pthread_mutex_lock(&collection->mutex);
    structured_record* new_record = &collection->records[collection->count++];
    new_record->offset = offset;
    new_record->key = key;
    new_record->rec.value = rec_value; // Assuming static allocation for simplicity
    new_record->size = size;
    new_record->timestamp = time(NULL);
    pthread_mutex_unlock(&collection->mutex);
}

