#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define sensor types
typedef enum {
    TEMP_SENSOR,
    HUMIDITY_SENSOR,
    PRESSURE_SENSOR
} SensorType;

// Define data structure for sensor readings
typedef struct {
    int id;
    float value;
    char metadata[1024];
} SensorData;

// Define data entry structure
typedef struct DataEntry {
    time_t timestamp;
    double reading;
    SensorType type;
    SensorData data;
    struct DataEntry* next;
} DataEntry;

// Define lock-free data store
typedef struct {
    DataEntry* head;
    pthread_mutex_t mutex;
} DataStore;

// Initialize the data store
void init_data_store(DataStore* store) {
    store->head = NULL;
    pthread_mutex_init(&store->mutex, NULL);
}

// Add a new data entry to the store
void add_entry(DataStore* store, double reading, SensorType type, int id, float value, const char* metadata) {
    DataEntry* new_entry = (DataEntry*)malloc(sizeof(DataEntry));
    new_entry->timestamp = time(NULL);
    new_entry->reading = reading;
    new_entry->type = type;
    new_entry->data.id = id;
    new_entry->data.value = value;
    strncpy(new_entry->data.metadata, metadata, sizeof(new_entry->data.metadata) - 1);
    new_entry->next = NULL;

    pthread_mutex_lock(&store->mutex);
    if (store->head == NULL) {
        store->head = new_entry;
    } else {
        DataEntry* current = store->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_entry;
    }
    pthread_mutex_unlock(&store->mutex);
}

// Retrieve data entries from the store
void retrieve_entries(DataStore* store, SensorType type, DataEntry** result) {
    *result = NULL;
    pthread_mutex_lock(&store->mutex);
    DataEntry* current = store->head;
    while (current != NULL) {
        if (current->type == type) {
            DataEntry* new_entry = (DataEntry*)malloc(sizeof(DataEntry));
            new_entry->timestamp = current->timestamp;
            new_entry->reading = current->reading;
            new_entry->type = current->type;
            new_entry->data.id = current->data.id;
            new_entry->data.value = current->data.value;
            strncpy(new_entry->data.metadata, current->data.metadata, sizeof(new_entry->data.metadata) - 1);
            new_entry->next = *result;
            *result = new_entry;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&store->mutex);
}

// Serialize the data store to disk
void serialize_data_store(DataStore* store, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    DataEntry* current = store->head;
    while (current != NULL) {
        fwrite(&current->timestamp, sizeof(time_t), 1, file);
        fwrite(&current->reading, sizeof(double), 1, file);
        fwrite(&current->type, sizeof(SensorType), 1, file);
        fwrite(&current->data.id, sizeof(int), 1, file);
        fwrite(&current->data.value, sizeof(float), 1, file);
        fwrite(current->data.metadata, sizeof(char), sizeof(new_entry->data.metadata) - 1, file);

        current = current->next;
    }

    fclose(file);
}

// Deserialize the data store from disk
void deserialize_data_store(DataStore* store, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    DataEntry* current = store->head;
    while (current != NULL) {
        DataEntry* next = current->next;
        free(current);
        current = next;
    }
    store->head = NULL;

    time_t timestamp;
    double reading;
    SensorType type;
    int id;
    float value;
    char metadata[1024];

    while (fread(&timestamp, sizeof(time_t), 1, file) == 1) {
        fread(&reading, sizeof(double), 1, file);
        fread(&type, sizeof(SensorType), 1, file);
        fread(&id, sizeof(int), 1, file);
        fread(&value, sizeof(float), 1, file);
        fread(metadata, sizeof(char), sizeof(metadata) - 1, file);

        add_entry(store, reading, type, id, value, metadata);
    }

    fclose(file);
}

// Example usage
int main() {
    DataStore store;
    init_data_store(&store);

    add_entry(&store, 23.5, TEMP_SENSOR, 1, 70.0, "Room A");
    add_entry(&store, 45.0, HUMIDITY_SENSOR, 2, 60.0, "Room B");

    DataEntry* entries;
    retrieve_entries(&store, TEMP_SENSOR, &entries);

    while (entries != NULL) {
        printf("Timestamp: %ld, Reading: %.2f, Type: %d, ID: %d, Value: %.2f, Metadata: %s\n",
               entries->timestamp, entries->reading, entries->type, entries->data.id, entries->data.value, entries->data.metadata);
        DataEntry* next = entries->next;
        free(entries);
        entries = next;
    }

    serialize_data_store(&store, "sensor_data.bin");
    deserialize_data_store(&store, "sensor_data.bin");

    return 0;
}
