        return NULL;
    }
    *(r->offset) = offset;
    return r;
}

void free_record(record *r) {
    if (r) {
        free(r->offset);
        free(r);
    }
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record** create_hash_table(size_t size) {
    record **ht = (record **)calloc(size, sizeof(record *));
    if (!ht) return NULL;
    for (size_t i = 0; i < size; ++i) ht[i] = NULL;
    return ht;
}

void free_hash_table(record **ht, size_t size) {
    if (ht) {
        for (size_t i = 0; i < size; ++i) {
            if (ht[i]) free_record(ht[i]);
        }
        free(ht);
    }
}

int find_max(int *arr, size_t size) {
    int max = arr[0];
    for (size_t i = 1; i < size; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

void process_and_find_max(size_t min_val, size_t max_val, size_t hash_size) {
    srand(time(NULL));
    record **ht = create_hash_table(hash_size);
    if (!ht) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        return;
    }

    int *input_arr = NULL;
    size_t input_size = 0;

    // Read integers from standard input
    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;
        input_arr = realloc(input_arr, (input_size + 1) * sizeof(int));
        if (!input_arr) {
            fprintf(stderr, "Failed to allocate memory for input array\n");
            free_hash_table(ht, hash_size);
            return;
        }
        input_arr[input_size++] = num;

        // Populate hash table
        size_t key = generate_random(min_val, max_val);
        record *r = create_record(num, sizeof(int), (long)input_arr + input_size - 1);
        if (!r) {
            fprintf(stderr, "Failed to allocate memory for record\n");
            free_hash_table(ht, hash_size);
            free(input_arr);
            return;
        }
        ht[key % hash_size] = r;
    }

    int max_value = find_max(input_arr, input_size);
    printf("Maximum value: %d\n", max_value);

    // Free all allocated memory
    free_hash_table(ht, hash_size);
    free(input_arr);
}

int main() {
    process_and_find_max(1, 100, 1024); // Example usage
    return 0;
}
