    // Aggregate metrics
    for (const auto& event : events) {
        // Simulate error rate generation
        event.errorRate = dis(gen);

        // Aggregate daily latency
        dailyLatency[event.timestamp % 365] += event.latency;

        // Aggregate weekly bandwidth usage
        weeklyBandwidthUsage[(event.timestamp / 7) % 52] += event.bandwidthUsage;

        // Aggregate monthly error rates
        monthlyErrorRates[(event.timestamp / 30) % 12] += event.errorRate;
    }

    // Generate reports
    for (int i = 0; i < 365; ++i) {
        std::lock_guard<std::mutex> lock(reportMutex);
        std::string report = "Daily Report - Day " + std::to_string(i + 1) + ": Average Latency = " + std::to_string(dailyLatency[i] / events.size());
