typedef struct {
    double mean;
    size_t num_samples;
    char* label;
} data_block;

double compute_average(double* samples, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += samples[i];
    }
    return sum / count;
}

int process_samples_and_compute_statistics(int fd, size_t sample_count, char** labels, data_block** blocks) {
    double* time_measurements = malloc(sample_count * sizeof(double));
    if (!time_measurements) {
        perror("Failed to allocate memory for time measurements");
        return -1;
    }

    *blocks = malloc(sample_count * sizeof(data_block));
    if (!*blocks) {
        free(time_measurements);
        perror("Failed to allocate memory for data blocks");
        return -1;
    }

    for (size_t i = 0; i < sample_count; ++i) {
        (*blocks)[i].label = labels[i];
        (*blocks)[i].num_samples = 0;
        (*blocks)[i].mean = 0.0;
    }

    // Read samples from file descriptor
    for (size_t i = 0; i < sample_count; ++i) {
        if (read(fd, &time_measurements[i], sizeof(double)) != sizeof(double)) {
            perror("Failed to read sample");
            free(time_measurements);
            free(*blocks);
            return -1;
        }
    }

    // Compute averages and store in data blocks
    for (size_t i = 0; i < sample_count; ++i) {
        (*blocks)[i].mean = compute_average(&time_measurements[i], 1); // Assuming each block has one sample for simplicity
        (*blocks)[i].num_samples = 1;
    }

    // Sort data blocks based on mean values in descending order
    qsort(*blocks, sample_count, sizeof(data_block), [](const void* a, const void* b) {
        return ((data_block*)b)->mean - ((data_block*)a)->mean;
    });

    free(time_measurements);
    return 0;
}

void free_data_blocks(data_block** blocks, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free((*blocks)[i].label);
    }
    free(*blocks);
}
