        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        ctx.records[i] = malloc(sizeof(record));
        if (!ctx.records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            goto cleanup;
        }
        ctx.records[i]->value = generate_random_number(min_val, max_val);
        ctx.records[i]->size = sizeof(int);
        ctx.records[i]->offset = &ctx.offsets[i];
    }

    // Custom sorting algorithm (e.g., bubble sort for simplicity)
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = 0; j < num_records - i - 1; ++j) {
            if (ctx.records[j]->value < ctx.records[j + 1]->value) {
                record *temp = ctx.records[j];
                ctx.records[j] = ctx.records[j + 1];
                ctx.records[j + 1] = temp;
            }
        }
