    double measurement;
} Measurement;

typedef struct {
    Timestamp ts;
    Measurement ms;
} SensorRecord;

// Function to allocate memory for sensor records
SensorRecord* allocate_sensor_records(int initial_count) {
    return (SensorRecord*)malloc(initial_count * sizeof(SensorRecord));
}

// Function to reallocate memory for sensor records
void reallocate_sensor_records(SensorRecord** records, int current_count, int new_count) {
    *records = realloc(*records, new_count * sizeof(SensorRecord));
}

// Function to read data from file and populate sensor records
int read_sensor_data(const char* filename, SensorRecord** records, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    // Initial allocation
    *records = allocate_sensor_records(10);
    if (!*records) {
        fclose(file);
        return -1;
    }

    int current_count = 10;
    int new_count = 20;
    while (fscanf(file, "%ld,%lf", &(*records)[*count].ts.timestamp, &(*records)[*count].ms.measurement) == 2) {
        (*count)++;
        if (*count >= current_count) {
            reallocate_sensor_records(records, current_count, new_count);
            current_count = new_count;
            new_count *= 2;
        }
    }

    fclose(file);
    return *count;
}

// Function to free allocated memory
void free_sensor_records(SensorRecord* records, int count) {
    free(records);
}
