typedef struct {
    uint32_t size;
    char* label;
    struct timeval arrival_time;
} network_event;

void get_current_time(struct timeval *tv) {
    gettimeofday(tv, NULL);
}

network_event* process_and_analyze_network_traffic(int num_packets) {
    network_event* events = (network_event*)malloc(num_packets * sizeof(network_event));
    if (!events) {
        perror("Failed to allocate memory for network events");
        return NULL;
    }

    uint32_t* packet_sizes = (uint32_t*)malloc(num_packets * sizeof(uint32_t));
    char** labels = (char**)malloc(num_packets * sizeof(char*));
    if (!packet_sizes || !labels) {
        perror("Failed to allocate memory for packet sizes and labels");
        free(events);
        return NULL;
    }

    struct timeval total_time = {0};
    uint32_t max_size = 0, min_size = UINT32_MAX;

    for (int i = 0; i < num_packets; ++i) {
        printf("Enter packet size and label: ");
        scanf("%u %ms", &packet_sizes[i], &labels[i]);
        events[i].size = packet_sizes[i];
        events[i].label = labels[i];
        get_current_time(&events[i].arrival_time);
        total_time.tv_sec += events[i].arrival_time.tv_sec;
        total_time.tv_usec += events[i].arrival_time.tv_usec;

        if (packet_sizes[i] > max_size) max_size = packet_sizes[i];
        if (packet_sizes[i] < min_size) min_size = packet_sizes[i];
    }

    events[0].total_packets = num_packets;
    events[0].average_size = total_time.tv_sec * 1000000 + total_time.tv_usec;
    events[0].max_size = max_size;
    events[0].min_size = min_size;

    qsort(events, num_packets, sizeof(network_event), (int (*)(const void *, const void *))compare_events);

    return events;
}

int compare_events(const void *a, const void *b) {
    network_event *event_a = (network_event *)a;
    network_event *event_b = (network_event *)b;

    if (event_a->arrival_time.tv_sec != event_b->arrival_time.tv_sec)
        return event_a->arrival_time.tv_sec - event_b->arrival_time.tv_sec;
    else
        return event_a->arrival_time.tv_usec - event_b->arrival_time.tv_usec;
}

void free_network_traffic_data(network_event* events, int num_packets) {
    for (int i = 0; i < num_packets; ++i) {
        free(events[i].label);
    }
    free(events);
}
