typedef struct file_record {
    char filename[256];
    time_t timestamp;
    size_t size;
    int status;
} FileRecord;

typedef struct bst_node {
    FileRecord data;
    struct bst_node *left, *right;
} BSTNode;

typedef struct hash_table_entry {
    char filename[256];
    BSTNode *bst_node;
    struct hash_table_entry *next;
} HashTableEntry;

typedef struct hash_table {
    HashTableEntry **entries;
    int size;
} HashTable;

BSTNode* create_bst_node(FileRecord data) {
    BSTNode* node = (BSTNode*)malloc(sizeof(BSTNode));
    if (node == NULL) {
        perror("Failed to allocate memory for BST node");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

HashTableEntry* create_hash_table_entry(char *filename, BSTNode *bst_node) {
    HashTableEntry* entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (entry == NULL) {
        perror("Failed to allocate memory for hash table entry");
        exit(EXIT_FAILURE);
    }
    strcpy(entry->filename, filename);
    entry->bst_node = bst_node;
    entry->next = NULL;
    return entry;
}

HashTable* create_hash_table(int size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (table == NULL) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->entries = (HashTableEntry**)calloc(size, sizeof(HashTableEntry*));
    if (table->entries == NULL) {
        perror("Failed to allocate memory for hash table entries");
        free(table);
        exit(EXIT_FAILURE);
    }
    table->size = size;
    return table;
}

void insert_bst(BSTNode** root, FileRecord data) {
    if (*root == NULL) {
        *root = create_bst_node(data);
        return;
    }
    if (strcmp(data.filename, (*root)->data.filename) < 0)
        insert_bst(&(*root)->left, data);
    else
        insert_bst(&(*root)->right, data);
}

