    // Free all allocated memory
    free_bst(bst_root);
    free_hash_table(hash_table);
}

void free_bst(BSTNode *root) {
    if (root != NULL) {
        free_bst(root->left);
        free_bst(root->right);
        free(root);
    }
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        HashTableEntry *entry = table->entries[i];
        while (entry != NULL) {
            HashTableEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(table->entries);
    free(table);
}

void find_largest_file_size(FileRecord records[], int num_files) {
    size_t max_size = 0;
    for (int i = 0; i < num_files; i++) {
        if (records[i].size > max_size)
            max_size = records[i].size;
    }
    printf("Largest file size: %zu bytes\n", max_size);
}
```

