#include <iostream>
#include <vector>
#include <mutex>
#include <atomic>
#include <string>
#include <unordered_map>

class ComplexObject {
public:
    unsigned long id;
    int value;
    std::string data;
    uint64_t metadata;

    ComplexObject(unsigned long id, int value, const std::string& data, uint64_t metadata)
        : id(id), value(value), data(data), metadata(metadata) {}
};

class ObjectManager {
private:
    std::vector<ComplexObject> buffer;
    std::mutex mutex;
    std::unordered_map<unsigned long, size_t> indexMap;
    std::atomic<uint64_t> reallocations;

public:
    ObjectManager(size_t initialCapacity = 1024) : buffer(initialCapacity), reallocations(0) {}

    void addObject(const ComplexObject& obj) {
        std::lock_guard<std::mutex> lock(mutex);
        if (indexMap.find(obj.id) != indexMap.end()) {
            throw std::runtime_error("Object with the same ID already exists.");
        }
        buffer.push_back(obj);
        indexMap[obj.id] = buffer.size() - 1;
    }

    ComplexObject* getObject(unsigned long id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = indexMap.find(id);
        if (it == indexMap.end()) {
            return nullptr;
        }
        return &buffer[it->second];
    }

    void updateMetadata(unsigned long id, uint64_t newMetadata) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = indexMap.find(id);
        if (it != indexMap.end()) {
            buffer[it->second].metadata = newMetadata;
        }
    }

    size_t getReallocations() const {
        return reallocations.load();
    }

    void resizeBuffer(size_t newSize) {
        std::lock_guard<std::mutex> lock(mutex);
        if (newSize > buffer.capacity()) {
            buffer.reserve(newSize);
            reallocations++;
        }
    }
};

int main() {
    ObjectManager manager;
    manager.resizeBuffer(2048);

    ComplexObject obj1(1, 10, "Data1", 0x123456789ABCDEF0);
    ComplexObject obj2(2, 20, "Data2", 0xFEDCBA9876543210);

    manager.addObject(obj1);
    manager.addObject(obj2);

    ComplexObject* retrievedObj = manager.getObject(1);
    if (retrievedObj) {
        std::cout << "Retrieved Object: ID=" << retrievedObj->id << ", Value=" << retrievedObj->value
                  << ", Data=" << retrievedObj->data << ", Metadata=" << retrievedObj->metadata << std::endl;
    }

    manager.updateMetadata(1, 0xABCDEF0123456789);
    retrievedObj = manager.getObject(1);
    if (retrievedObj) {
        std::cout << "Updated Object: ID=" << retrievedObj->id << ", Value=" << retrievedObj->value
                  << ", Data=" << retrievedObj->data << ", Metadata=" << retrievedObj->metadata << std::endl;
    }

    std::cout << "Total Reallocations: " << manager.getReallocations() << std::endl;

    return 0;
}
