#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define packet structure
typedef struct {
    char src_ip[16];
    char dst_ip[16];
    int protocol;
    size_t payload_size;
    time_t timestamp;
    int status; // 0 for unprocessed, 1 for processed
} Packet;

// Circular buffer implementation
#define BUFFER_SIZE 1024
Packet circular_buffer[BUFFER_SIZE];
int head = 0, tail = 0, count = 0;

void enqueue(Packet packet) {
    if (count == BUFFER_SIZE) {
        // Handle buffer overflow
        printf("Buffer overflow detected!\n");
        return;
    }
    circular_buffer[tail] = packet;
    tail = (tail + 1) % BUFFER_SIZE;
    count++;
}

Packet dequeue() {
    Packet packet;
    if (count == 0) {
        // Handle buffer underflow
        printf("Buffer underflow detected!\n");
        memset(&packet, 0, sizeof(Packet));
        return packet;
    }
    packet = circular_buffer[head];
    head = (head + 1) % BUFFER_SIZE;
    count--;
    return packet;
}

// Priority queue implementation using binary heap
#define MAX_HEAP_SIZE 1024
Packet priority_queue[MAX_HEAP_SIZE];
int heap_size = 0;

void swap(Packet *a, Packet *b) {
    Packet temp = *a;
    *a = *b;
    *b = temp;
}

void min_heapify(int i) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left < heap_size && priority_queue[left].payload_size < priority_queue[smallest].payload_size)
        smallest = left;
    if (right < heap_size && priority_queue[right].payload_size < priority_queue[smallest].payload_size)
        smallest = right;

    if (smallest != i) {
        swap(&priority_queue[i], &priority_queue[smallest]);
        min_heapify(smallest);
    }
}

void insert(Packet packet) {
    if (heap_size == MAX_HEAP_SIZE) {
        // Handle heap overflow
        printf("Heap overflow detected!\n");
        return;
    }
    priority_queue[heap_size] = packet;
    int i = heap_size;
    heap_size++;
    while (i != 0 && priority_queue[(i - 1) / 2].payload_size > priority_queue[i].payload_size) {
        swap(&priority_queue[i], &priority_queue[(i - 1) / 2]);
        i = (i - 1) / 2;
    }
}

Packet extract_min() {
    if (heap_size == 0) {
        // Handle heap underflow
        printf("Heap underflow detected!\n");
        Packet packet;
        memset(&packet, 0, sizeof(Packet));
        return packet;
    }
    Packet min = priority_queue[0];
    priority_queue[0] = priority_queue[heap_size - 1];
    heap_size--;
    min_heapify(0);
    return min;
}

// Hash map implementation using chaining
#define HASH_TABLE_SIZE 1024
typedef struct Node {
    char src_ip[16];
    char dst_ip[16];
    Packet packet;
    struct Node *next;
} Node;

Node* hash_table[HASH_TABLE_SIZE];

unsigned int hash_function(const char *key) {
    unsigned int hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % HASH_TABLE_SIZE;
}

void insert_hash(const char *src_ip, const char *dst_ip, Packet packet) {
    unsigned int index = hash_function(src_ip);
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        // Handle memory allocation failure
        printf("Memory allocation failed!\n");
        return;
    }
    strcpy(new_node->src_ip, src_ip);
    strcpy(new_node->dst_ip, dst_ip);
    new_node->packet = packet;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
}

Node* search_hash(const char *src_ip, const char *dst_ip) {
    unsigned int index = hash_function(src_ip);
    Node *current = hash_table[index];
    while (current != NULL) {
        if (strcmp(current->src_ip, src_ip) == 0 && strcmp(current->dst_ip, dst_ip) == 0)
            return current;
        current = current->next;
    }
    return NULL;
}

void free_hash() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Node *current = hash_table[i];
        while (current != NULL) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
    }
}

// Thread-safe operations
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t heap_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t hash_mutex = PTHREAD_MUTEX_INITIALIZER;

void enqueue_thread_safe(Packet packet) {
    pthread_mutex_lock(&buffer_mutex);
    enqueue(packet);
    pthread_mutex_unlock(&buffer_mutex);
}

Packet dequeue_thread_safe() {
    Packet packet;
    pthread_mutex_lock(&buffer_mutex);
    packet = dequeue();
    pthread_mutex_unlock(&buffer_mutex);
    return packet;
}

void insert_thread_safe(Packet packet) {
    pthread_mutex_lock(&heap_mutex);
    insert(packet);
    pthread_mutex_unlock(&heap_mutex);
}

Packet extract_min_thread_safe() {
    Packet packet;
    pthread_mutex_lock(&heap_mutex);
    packet = extract_min();
    pthread_mutex_unlock(&heap_mutex);
    return packet;
}

void insert_hash_thread_safe(const char *src_ip, const char *dst_ip, Packet packet) {
    pthread_mutex_lock(&hash_mutex);
    insert_hash(src_ip, dst_ip, packet);
    pthread_mutex_unlock(&hash_mutex);
}

Node* search_hash_thread_safe(const char *src_ip, const char *dst_ip) {
    Node *node;
    pthread_mutex_lock(&hash_mutex);
    node = search_hash(src_ip, dst_ip);
    pthread_mutex_unlock(&hash_mutex);
    return node;
}

void free_hash_thread_safe() {
    pthread_mutex_lock(&hash_mutex);
    free_hash();
    pthread_mutex_unlock(&hash_mutex);
}

// Main function to demonstrate usage
int main() {
    Packet packet1 = {"192.168.1.1", "10.0.0.1", 6, 1024, time(NULL), 0};
    enqueue_thread_safe(packet1);

    Packet packet2 = {"10.0.0.1", "192.168.1.1", 6, 512, time(NULL), 0};
    insert_thread_safe(packet2);

    Node *node = search_hash_thread_safe("192.168.1.1", "10.0.0.1");
    if (node != NULL) {
        printf("Packet found: src_ip=%s, dst_ip=%s, payload_size=%zu\n",
               node->packet.src_ip, node->packet.dst_ip, node->packet.payload_size);
    }

    free_hash_thread_safe();

    return 0;
}
