#include <math.h>

typedef struct {
    int* timestamp;
    double* temperature;
} sensorData;

double gaussian(double mean, double stddev) {
    static const double two_pi = 2.0 * M_PI;
    double u1, u2, v1, v2, s;

    do {
        u1 = (double)rand() / RAND_MAX;
        u2 = (double)rand() / RAND_MAX;
        v1 = 2.0 * u1 - 1.0;
        v2 = 2.0 * u2 - 1.0;
        s = v1 * v1 + v2 * v2;
    } while (s >= 1.0 || s == 0.0);

    double multiplier = sqrt(-2.0 * log(s) / s);
    return mean + stddev * (v1 * multiplier);
}

sensorData* createSensorDataset(int size, double mean, double stddev) {
    if (size <= 0) {
        fprintf(stderr, "Invalid dataset size.\n");
        return NULL;
    }

    sensorData* data = (sensorData*)malloc(sizeof(sensorData));
    if (!data) {
        fprintf(stderr, "Memory allocation failed for sensorData structure.\n");
        return NULL;
    }

    double* temperatures = (double*)calloc(size, sizeof(double));
    int* timestamps = (int*)calloc(size, sizeof(int));
    if (!temperatures || !timestamps) {
        fprintf(stderr, "Memory allocation failed for temperature or timestamp arrays.\n");
        free(data);
        return NULL;
    }

    data->temperature = temperatures;
    data->timestamp = timestamps;

    double prev_temp = -INFINITY;
    int prev_index = -1;
    for (int i = 0; i < size; ) {
        double temp = gaussian(mean, stddev);
        if (temp != prev_temp) {
            data->temperature[i] = temp;
            data->timestamp[i] = rand() % 86400 + 1; // Random timestamp between 1 and 86400
            prev_temp = temp;
            i++;
        }
    }

    return data;
}

void freeSensorDataset(sensorData* data) {
    if (data) {
        free(data->temperature);
        free(data->timestamp);
        free(data);
    }
}
