    }

    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % 1001;
        (*records)[i].offset_ptr = &(*offsets)[rand() % size];
    }

    return 0; // Success
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
