#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    long* offsets;
    int length;
} Offset;

typedef struct {
    int* keys;
    int length;
} Keys;

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    int length;
} Records;

int initialize_structures(Offset* offset, Keys* keys, Records* records, int offset_length, int keys_length) {
    if (offset_length * sizeof(long) + keys_length * sizeof(int) > MAX_MEMORY_LIMIT) {
        return -1; // Memory limit exceeded
    }

    offset->length = offset_length;
    offset->offsets = (long*)malloc(offset_length * sizeof(long));
    if (!offset->offsets) {
        return -2; // Failed to allocate memory for offsets
    }

    keys->length = keys_length;
    keys->keys = (int*)malloc(keys_length * sizeof(int));
    if (!keys->keys) {
        free(offset->offsets);
        return -3; // Failed to allocate memory for keys
    }

    records->length = offset_length;
    records->records = (Record*)malloc(offset_length * sizeof(Record));
    if (!records->records) {
        free(keys->keys);
        free(offset->offsets);
        return -4; // Failed to allocate memory for records
    }

    srand(time(NULL));

    for (int i = 0; i < offset_length; i++) {
        offset->offsets[i] = rand() % MAX_MEMORY_LIMIT;
        keys->keys[i] = rand() % 100 + 1;

        int valid_offset_found = 0;
        while (!valid_offset_found) {
            records->records[i].key = keys->keys[i];
            records->records[i].offset = offset->offsets[rand() % offset_length];

            for (int j = 0; j < i; j++) {
                if (records->records[j].offset == records->records[i].offset) {
                    break;
                }
                if (j == i - 1) {
                    valid_offset_found = 1;
                }
            }
        }
    }

    return 0; // Success
}

void free_structures(Offset* offset, Keys* keys, Records* records) {
    free(offset->offsets);
    free(keys->keys);
    free(records->records);
}
