typedef struct node {
    double value;
    char* str;
} Node;

typedef struct tree {
    int index;
    Node** nodes;
} Tree;

Node** allocate_nodes(int size, char** strings) {
    Node** nodes = (Node**)malloc(size * sizeof(Node*));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for nodes\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            fprintf(stderr, "Memory allocation failed for node %d\n", i);
            for (int j = 0; j < i; j++) {
                free(nodes[j]);
            }
            free(nodes);
            return NULL;
        }
        nodes[i]->value = 0.0;
        int index = rand() % size;
        nodes[i]->str = strings[index];
    }
    return nodes;
}

Tree* allocate_trees(int size, Node** nodes) {
    Tree* trees = (Tree*)malloc(size * sizeof(Tree));
    if (!trees) {
        fprintf(stderr, "Memory allocation failed for trees\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        trees[i].index = 0;
        trees[i].nodes = nodes;
    }
    return trees;
}

void populate_nodes(Node** nodes, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        nodes[i]->value = ((double)rand() / RAND_MAX) * 2000.0 - 1000.0;
    }
}

void deallocate_memory(Node** nodes, Tree* trees, int node_size, int tree_size) {
    for (int i = 0; i < node_size; i++) {
        free(nodes[i]);
    }
    free(nodes);
    free(trees);
}

int main() {
    int node_size, tree_size;
    printf("Enter the size of nodes and trees: ");
    scanf("%d %d", &node_size, &tree_size);

    if (node_size * sizeof(Node) + tree_size * sizeof(Tree) > MAX_MEMORY) {
        fprintf(stderr, "Memory allocation exceeds 2MB limit\n");
        return 1;
    }

    char** strings = (char**)malloc(node_size * sizeof(char*));
    for (int i = 0; i < node_size; i++) {
        strings[i] = (char*)malloc(50 * sizeof(char));
        sprintf(strings[i], "String %d", i);
    }

    Node** nodes = allocate_nodes(node_size, strings);
    if (!nodes) {
        return 1;
    }

    Tree* trees = allocate_trees(tree_size, nodes);
    if (!trees) {
        deallocate_memory(nodes, NULL, node_size, 0);
        return 1;
    }

    populate_nodes(nodes, node_size);

    // Perform operations on nodes and trees

    deallocate_memory(nodes, trees, node_size, tree_size);

    for (int i = 0; i < node_size; i++) {
        free(strings[i]);
    }
    free(strings);

    return 0;
}
