    Record record;
} DataRecord;

typedef struct {
    DataRecord* records;
    size_t capacity;
    size_t count;
    size_t memory_limit;
    int key_min;
    int key_max;
} DataManager;

DataManager* create_data_manager(size_t initial_capacity, size_t memory_limit, int key_min, int key_max) {
    DataManager* manager = (DataManager*)malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->records = (DataRecord*)malloc(initial_capacity * sizeof(DataRecord));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->memory_limit = memory_limit;
    manager->key_min = key_min;
    manager->key_max = key_max;

    return manager;
}

int add_record(DataManager* manager, long offset, int key, Record record) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        DataRecord* new_records = (DataRecord*)realloc(manager->records, new_capacity * sizeof(DataRecord));
        if (!new_records) return -1;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].key == key) return -2;
    }

    if (key < manager->key_min || key > manager->key_max) return -3;

    manager->records[manager->count].offset = offset;
    manager->records[manager->count].key = key;
    manager->records[manager->count].record = record;
    ++manager->count;

    return 0;
}

void destroy_data_manager(DataManager* manager) {
    free(manager->records);
    free(manager);
}
