#include <pthread.h>

#define MAX_CONCURRENT_READS 10

typedef struct {
    long offset;
    int key;
    int record_value;
} Record;

Record* allocate_memory(size_t size) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return records;
}

void populate_records(Record* records, size_t size, int min_value, int max_value) {
    for (size_t i = 0; i < size; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
        records[i].record_value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void* read_file(void* arg) {
    char* filename = (char*)arg;
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Extract last two numeric fields and compute average
        int num1, num2;
        sscanf(line, "%*[^0-9]%d%*[^0-9]%d", &num1, &num2);
        double average = (num1 + num2) / 2.0;
        printf("%.2f\n", average);
    }

    fclose(file);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <file1> <file2> ... <fileN>\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_CONCURRENT_READS];
    int num_files = argc - 1;

    for (int i = 0; i < num_files; ++i) {
        if (pthread_create(&threads[i], NULL, read_file, argv[i + 1]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
