#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define a structure for directory metadata
typedef struct {
    char name[256];
    int access_count;
    time_t last_accessed;
} DirectoryMetadata;

// Define a hash table for quick lookups
#define HASH_TABLE_SIZE 1024
DirectoryMetadata *hash_table[HASH_TABLE_SIZE];

// Function to calculate hash value
unsigned int hash_function(const char *name) {
    unsigned int hash = 0;
    while (*name) {
        hash = (hash << 5) + *name++;
    }
    return hash % HASH_TABLE_SIZE;
}

// Function to insert directory metadata into the hash table
void insert_directory_metadata(const char *name, DirectoryMetadata *metadata) {
    unsigned int index = hash_function(name);
    while (hash_table[index] != NULL) {
        index = (index + 1) % HASH_TABLE_SIZE;
    }
    hash_table[index] = metadata;
}

// Function to retrieve directory metadata from the hash table
DirectoryMetadata* get_directory_metadata(const char *name) {
    unsigned int index = hash_function(name);
    while (hash_table[index] != NULL) {
        if (strcmp(hash_table[index]->name, name) == 0) {
            return hash_table[index];
        }
        index = (index + 1) % HASH_TABLE_SIZE;
    }
    return NULL;
}

// Function to update directory metadata in the hash table
void update_directory_metadata(const char *name, DirectoryMetadata *metadata) {
    unsigned int index = hash_function(name);
    while (hash_table[index] != NULL) {
        if (strcmp(hash_table[index]->name, name) == 0) {
            hash_table[index] = metadata;
            return;
        }
        index = (index + 1) % HASH_TABLE_SIZE;
    }
}

// Function to delete directory metadata from the hash table
void delete_directory_metadata(const char *name) {
    unsigned int index = hash_function(name);
    while (hash_table[index] != NULL) {
        if (strcmp(hash_table[index]->name, name) == 0) {
            free(hash_table[index]);
            hash_table[index] = NULL;
            return;
        }
        index = (index + 1) % HASH_TABLE_SIZE;
    }
}

