        fread(&keys[count], sizeof(int), 1, in);
        records[count].size = fread(&records[count].value, sizeof(int), 1, in);
        count++;
        if (count >= 1024) {
            offsets = realloc(offsets, 2 * 1024 * sizeof(long));
            keys = realloc(keys, 2 * 1024 * sizeof(int));
            records = realloc(records, 2 * 1024 * sizeof(record));
        }
    }

    fclose(in);

    // Process data based on parsing rules
    for (int i = 0; i < count; i++) {
        if (strcmp(parsing_rules, "rule1") == 0) {
            // Apply rule1 logic
        } else if (strcmp(parsing_rules, "rule2") == 0) {
            // Apply rule2 logic
        }
    }

    // Write processed data to output file
    FILE *out = fopen(output_file, "wb");
    if (!out) {
        perror("Failed to open output file");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (int i = 0; i < count; i++) {
        fwrite(&offsets[i], sizeof(long), 1, out);
        fwrite(&keys[i], sizeof(int), 1, out);
