bool are_keys_unique(int* keys, int count) {
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (keys[i] == keys[j]) {
                return false;
            }
        }
    }
    return true;
}

record* initialize_records(int max_records, int key_range_start, int key_range_end, int value_range_start, int value_range_end) {
    srand(time(NULL));

    long* offsets = malloc(max_records * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    int* keys = malloc(max_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record** records = malloc(max_records * sizeof(record*));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < max_records; ++i) {
        offsets[i] = rand() % (max_records * sizeof(record));
        keys[i] = key_range_start + rand() % (key_range_end - key_range_start + 1);

        while (!are_keys_unique(keys, i + 1)) {
            keys[i] = key_range_start + rand() % (key_range_end - key_range_start + 1);
        }

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        records[i]->value = value_range_start + rand() % (value_range_end - value_range_start + 1);
        snprintf(records[i]->name, sizeof(records[i]->name), "Record%d", i);
        records[i]->flag = (rand() % 2 == 0) ? true : false;
    }

    return records;
}

void free_records(record** records, int max_records) {
    for (int i = 0; i < max_records; ++i) {
        free(records[i]);
    }
    free(records);
}
