typedef struct Algorithm {
    char *name;
    void (*implementation)(void);
    // Add any necessary parameters here
} Algorithm;

typedef struct AlgorithmList {
    Algorithm **algorithms;
    size_t count;
    pthread_mutex_t lock;
} AlgorithmList;

AlgorithmList *create_algorithm_list() {
    AlgorithmList *list = (AlgorithmList *)malloc(sizeof(AlgorithmList));
    list->algorithms = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_algorithm(AlgorithmList *list, const char *name, void (*implementation)(void)) {
    pthread_mutex_lock(&list->lock);
    Algorithm **new_algorithms = (Algorithm **)realloc(list->algorithms, (list->count + 1) * sizeof(Algorithm *));
    if (new_algorithms == NULL) {
        perror("Failed to allocate memory for new algorithm");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->algorithms = new_algorithms;

    Algorithm *new_algorithm = (Algorithm *)malloc(sizeof(Algorithm));
    new_algorithm->name = strdup(name);
    new_algorithm->implementation = implementation;
    // Initialize any necessary parameters here

    list->algorithms[list->count] = new_algorithm;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void remove_algorithm(AlgorithmList *list, const char *name) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->algorithms[i]->name, name) == 0) {
            free(list->algorithms[i]->name);
            free(list->algorithms[i]);
            memmove(&list->algorithms[i], &list->algorithms[i + 1], (list->count - i - 1) * sizeof(Algorithm *));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

Algorithm **get_algorithms(AlgorithmList *list, size_t *count) {
    pthread_mutex_lock(&list->lock);
    Algorithm **algorithms = (Algorithm **)malloc(list->count * sizeof(Algorithm *));
    if (algorithms == NULL) {
        perror("Failed to allocate memory for algorithm list");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    memcpy(algorithms, list->algorithms, list->count * sizeof(Algorithm *));
    *count = list->count;
    pthread_mutex_unlock(&list->lock);
    return algorithms;
}

void destroy_algorithm_list(AlgorithmList *list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->algorithms[i]->name);
        free(list->algorithms[i]);
    }
    free(list->algorithms);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
