// Define a structure for storing integers with their indices
typedef struct {
    int value;
    int index;
} IntegerNode;

// Function to dynamically allocate memory and store integers
void readAndStoreIntegers() {
    // Initialize variables
    char input[256];
    IntegerNode *integers = NULL;
    size_t count = 0, capacity = 10;

    // Allocate initial memory for integers
    integers = (IntegerNode *)malloc(capacity * sizeof(IntegerNode));
    if (!integers) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Read integers from standard input
    while (fgets(input, sizeof(input), stdin)) {
        int value = atoi(input);
        if (value == 0 && strcmp(input, "0\n") != 0) {
            continue; // Skip invalid inputs
        }

        // Resize array if necessary
        if (count >= capacity) {
            capacity *= 2;
            integers = (IntegerNode *)realloc(integers, capacity * sizeof(IntegerNode));
            if (!integers) {
                fprintf(stderr, "Memory reallocation failed\n");
                return;
            }
        }

        // Store integer and its index
        integers[count].value = value;
        integers[count].index = count;
        count++;
    }

    // Find the largest integer and its index
    int max_value = INT_MIN;
    size_t max_index = -1;
    for (size_t i = 0; i < count; i++) {
        if (integers[i].value > max_value) {
            max_value = integers[i].value;
            max_index = integers[i].index;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d at index: %zu\n", max_value, max_index);

    // Free allocated memory
    free(integers);
}

int main() {
    readAndStoreIntegers();
    return 0;
}
