    *timestamp_array = (unsigned long *)aligned_alloc(64, n * sizeof(unsigned long));
    *data_points = (data_point *)aligned_alloc(64, n * sizeof(data_point));

    if (!*double_array || !*timestamp_array || !*data_points) {
        return -1; // Memory allocation failed
    }

    // Initialize arrays
    for (size_t i = 0; i < n; ++i) {
        (*double_array)[i] = 0.0;
        (*timestamp_array)[i] = 0;
        memset((*data_points)[i].string, 0, max_string_len);
        (*data_points)[i].type = TYPE_A;
    }

    return 0; // Success
}

void fill_data_points(double *double_array, unsigned long *timestamp_array, data_point *data_points, size_t n, double min_val, double max_val, unsigned int seed) {
    srand(seed);
    for (size_t i = 0; i < n; ++i) {
        double_array[i] = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);
        snprintf(data_points[i].string, MAX_STRING_LEN, "%c", 'a' + rand() % 26);
    }
}

int check_memory_usage(size_t current_usage, size_t memory_limit_mb) {
    return (current_usage > memory_limit_mb * 1024 * 1024);
}

void free_resources(double *double_array, unsigned long *timestamp_array, data_point *data_points) {
    if (double_array) free(double_array);
    if (timestamp_array) free(timestamp_array);
    if (data_points) free(data_points);
}

int main() {
    size_t n = 1000;
    size_t max_string_len = MAX_STRING_LEN;
    size_t memory_limit_mb = 10;
    double *double_array = NULL;
    unsigned long *timestamp_array = NULL;
    data_point *data_points = NULL;

    int result = allocate_and_initialize(&double_array, &timestamp_array, &data_points, n, max_string_len, memory_limit_mb);
    if (result != 0) {
        // Handle error
        return -1;
    }

    fill_data_points(double_array, timestamp_array, data_points, n, 0.0, 1.0, time(NULL));

    free_resources(double_array, timestamp_array, data_points);

    return 0;
}
