using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using YourNamespace.Services;
using YourNamespace.Models;

[ApiController]
[Route("api/[controller]")]
public class ContentController : ControllerBase
{
    private readonly IContentService _contentService;
    private readonly ILogger<ContentController> _logger;

    public ContentController(IContentService contentService, ILogger<ContentController> logger)
    {
        _contentService = contentService;
        _logger = logger;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement([FromBody] ElementUpdateRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        try
        {
            var updateResult = await _contentService.UpdateElementAsync(request.SectionId, request.ElementId, request.HtmlContent, request.Metadata);

            if (updateResult.Success)
            {
                _logger.LogInformation($"Element {request.ElementId} updated successfully. Section: {request.SectionId}, Metadata: {request.Metadata}");
                return Ok(updateResult);
            }
            else
            {
                _logger.LogError($"Failed to update element {request.ElementId}. Section: {request.SectionId}, Error: {updateResult.ErrorMessage}");
                return StatusCode(500, updateResult.ErrorMessage);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"An error occurred while updating element {request.ElementId}: {ex.Message}");
            return StatusCode(500, "Internal server error");
        }
    }
}

public class ElementUpdateRequest
{
    public int SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
    public string Metadata { get; set; }
}

public class UpdateResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
}
```

