import json
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime

def process_jsonl_file(file_url):
    category_counts = defaultdict(int)
    rating_totals = defaultdict(float)
    rating_counts = defaultdict(int)
    keyword_counts = defaultdict(int)

    def process_line(line):
        try:
            review = json.loads(line)
            category = review.get('category')
            rating = review.get('rating')
            date = review.get('date')
            feedback = review.get('feedback')

            if not (isinstance(category, str) and len(category) <= 50):
                return
            if not (isinstance(rating, int) and 1 <= rating <= 5):
                return
            if not (isinstance(date, str) and datetime.fromisoformat(date)):
                return
            if not (isinstance(feedback, str) and feedback and len(feedback) <= 2000):
                return

            category_counts[category] += 1
            rating_totals[category] += rating
            rating_counts[category] += 1

            for word in feedback.split():
                keyword_counts[word.lower()] += 1

        except json.JSONDecodeError:
            pass

    def fetch_and_process(url):
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status()
            for line in response.iter_lines(chunk_size=1024):
                if line:
                    process_line(line.decode('utf-8'))
        except (requests.RequestException, ValueError) as e:
            print(f"Error processing file: {e}")

    with ThreadPoolExecutor(max_workers=5) as executor:
        executor.submit(fetch_and_process, file_url)

    summary = {
        'category_counts': category_counts,
        'average_ratings': {category: rating_totals[category] / rating_counts[category] for category in category_counts},
        'most_common_keywords': sorted(keyword_counts.items(), key=lambda x: -x[1])[:10]
    }

    return summary
