#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int key;
    char name[256];
    bool flag;
    int dependency_count;
    struct Record** dependencies;
} Record;

Record* create_records(int num_records, int min_key, int max_key, int min_dependency, int max_dependency) {
    if (num_records <= 0 || min_key >= max_key || min_dependency > max_dependency) {
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL;
    }

    bool* keys_used = calloc(max_key - min_key + 1, sizeof(bool));
    if (!keys_used) {
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (keys_used[key - min_key]);

        keys_used[key - min_key] = true;

        records[i].key = key;
        snprintf(records[i].name, sizeof(records[i].name), "Record%d", i);
        records[i].flag = rand() % 2 == 0;
        records[i].dependency_count = rand() % (max_dependency - min_dependency + 1) + min_dependency;

        if (records[i].dependency_count > 0) {
            records[i].dependencies = malloc(records[i].dependency_count * sizeof(Record*));
            if (!records[i].dependencies) {
                for (int j = 0; j < i; ++j) {
                    free(records[j].dependencies);
                }
                free(keys_used);
                free(records);
                return NULL;
            }

            int* dependency_keys = malloc(records[i].dependency_count * sizeof(int));
            if (!dependency_keys) {
                for (int j = 0; j < i; ++j) {
                    free(records[j].dependencies);
                }
                free(keys_used);
                free(records);
                return NULL;
            }

            do {
                int count = 0;
                for (int j = 0; j < num_records && count < records[i].dependency_count; ++j) {
                    if (i != j && !keys_used[records[j].key - min_key]) {
                        dependency_keys[count++] = records[j].key;
                    }
                }

                if (count == records[i].dependency_count) {
                    for (int j = 0; j < count; ++j) {
                        int index = dependency_keys[j] - min_key;
                        while (keys_used[index]) {
                            index = (index + 1) % (max_key - min_key + 1);
                        }
                        keys_used[index] = true;
                        records[i].dependencies[j] = &records[index];
                    }
                } else {
                    free(dependency_keys);
                }
            } while (count != records[i].dependency_count);

            free(dependency_keys);
        } else {
            records[i].dependencies = NULL;
        }

        records[i].key = key;
    }

    free(keys_used);
    return records;
}

void free_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i].dependencies) {
            free(records[i].dependencies);
        }
    }
    free(records);
}
