#include <time.h>

typedef struct {
    int value;
    char name[256];
    bool flag;
    // Custom metadata structure
    time_t timestamp;
    int nested_int_array[10];
    struct record* link;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    int max_records;
    int current_records;
} record_manager;

record_manager* create_record_manager(int max_records) {
    record_manager* manager = (record_manager*)malloc(sizeof(record_manager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(max_records, sizeof(long));
    manager->keys = (int*)calloc(max_records, sizeof(int));
    manager->records = (record**)calloc(max_records, sizeof(record*));
    manager->max_records = max_records;
    manager->current_records = 0;

    if (!manager->offsets || !manager->keys || !manager->records) {
        free_record_manager(manager);
        return NULL;
    }

    srand(time(NULL));
    return manager;
}

void free_record_manager(record_manager* manager) {
    for (int i = 0; i < manager->current_records; i++) {
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

bool add_record(record_manager* manager, int key, record* new_record) {
    if (manager->current_records >= manager->max_records) return false;
    for (int i = 0; i < manager->current_records; i++) {
        if (manager->keys[i] == key) return false;
    }
    manager->keys[manager->current_records] = key;
    manager->records[manager->current_records] = new_record;
    manager->offsets[manager->current_records] = (long)new_record;
    manager->current_records++;
    return true;
}

record* create_new_record(int value, const char* name, bool flag) {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) return NULL;

    new_record->value = value;
    strncpy(new_record->name, name, sizeof(new_record->name) - 1);
    new_record->flag = flag;
    new_record->timestamp = time(NULL);
    for (int i = 0; i < 10; i++) {
        new_record->nested_int_array[i] = rand() % 100;
    }
    new_record->link = NULL;

    return new_record;
}

void initialize_records(record_manager* manager, int min_value, int max_value) {
    for (int i = 0; i < manager->current_records; i++) {
        record* rec = manager->records[i];
        rec->value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void free_records(record_manager* manager) {
    for (int i = 0; i < manager->current_records; i++) {
        free(manager->records[i]);
    }
}
