int initialize_arrays(long** offsets, int** keys, record** records, int num_records, int min_val, int max_val) {
    *offsets = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));
    *records = (record*)malloc(num_records * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = i * sizeof(long);
        (*keys)[i] = rand() % (max_val - min_val + 1) + min_val;

        (*records)[i].value = (*keys)[i];
        (*records)[i].size = (*keys)[i] * sizeof(int);
        (*records)[i].data = (unsigned char*)malloc((*records)[i].size);

        if ((*records)[i].data == NULL) {
            // Free previously allocated memory
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; ++j) {
                free((*records)[j].data);
            }
            free(*records);
            return -1; // Memory allocation failed
        }

        // Initialize byte array with a specific pattern based on its index
        for (size_t j = 0; j < (*records)[i].size; ++j) {
            (*records)[i].data[j] = (unsigned char)(i + j);
        }
    }

    return 0; // Success
}

void free_arrays(long* offsets, int* keys, record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].data);
    }
    free(offsets);
    free(keys);
    free(records);
}
