                fclose(file);
                file = NULL;
                break;
            }
        }
        fclose(file);
    } else {
        srand(time(NULL));
        for (long i = 0; i < numOffsets; ++i) {
            keys[i] = rand() % 1001;
        }
    }

    for (long i = 0; i < numRecords; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    return records;
}
