#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    time_t timestamp;
    double temperature;
    char unit[5];
} TemperatureRecord;

typedef struct {
    TemperatureRecord* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(size_t initial_capacity) {
    pthread_mutex_lock(&pool.lock);
    if (pool.records == NULL) {
        pool.capacity = initial_capacity;
        pool.size = 0;
        pool.records = malloc(pool.capacity * sizeof(TemperatureRecord));
        if (pool.records == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    free(ptr);
}

void log_memory_event(const char* event_type, size_t size, int success) {
    // Implement logging using an external library
    printf("%s: %zu bytes - %s\n", event_type, size, success ? "Success" : "Failure");
}

int validate_temperature_record(TemperatureRecord record) {
    if (record.timestamp == 0 || record.temperature < -273.15 || record.temperature > 1000.0) {
        return 0;
    }
    if (strcmp(record.unit, "C") != 0 && strcmp(record.unit, "F") != 0) {
        return 0;
    }
    return 1;
}

void add_temperature_record(TemperatureRecord record) {
    pthread_mutex_lock(&pool.lock);
    if (pool.size >= pool.capacity) {
        size_t new_capacity = pool.capacity * 2;
        TemperatureRecord* new_records = realloc(pool.records, new_capacity * sizeof(TemperatureRecord));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool.records = new_records;
        pool.capacity = new_capacity;
    }
    if (!validate_temperature_record(record)) {
        fprintf(stderr, "Invalid temperature record\n");
        pthread_mutex_unlock(&pool.lock);
        return;
    }
    pool.records[pool.size++] = record;
    log_memory_event("Allocation", sizeof(TemperatureRecord), 1);
    pthread_mutex_unlock(&pool.lock);
}

void* unsafe_memory_management() {
    // Simulate unsafe memory management
    int* ptr = (int*)allocate_memory(sizeof(int));
    *ptr = 42;
    deallocate_memory(ptr); // Memory leak
    return NULL;
}

void resize_temperature_records(size_t new_capacity) {
    pthread_mutex_lock(&pool.lock);
    if (new_capacity > pool.capacity) {
        TemperatureRecord* new_records = realloc(pool.records, new_capacity * sizeof(TemperatureRecord));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool.records = new_records;
        pool.capacity = new_capacity;
    } else if (new_capacity < pool.capacity) {
        TemperatureRecord* new_records = realloc(pool.records, new_capacity * sizeof(TemperatureRecord));
        if (new_records == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool.records = new_records;
        pool.capacity = new_capacity;
    }
    pthread_mutex_unlock(&pool.lock);
}

int main() {
    init_memory_pool(10);

    srand(time(NULL));
    for (size_t i = 0; i < 20; ++i) {
        TemperatureRecord record;
        record.timestamp = time(NULL);
        record.temperature = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
        strcpy(record.unit, "C");
        add_temperature_record(record);
    }

    resize_temperature_records(30);

    unsafe_memory_management();

    return 0;
}
