#define MAX_LOG_LEVELS 5

typedef enum {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
} LogLevel;

typedef struct log_entry {
    time_t timestamp;
    char message[256];
    LogLevel level;
    int id;
} LogEntry;

typedef struct log_system {
    LogEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} LogSystem;

void init_log_system(LogSystem *sys, size_t initial_capacity) {
    sys->capacity = initial_capacity;
    sys->count = 0;
    sys->entries = (LogEntry *)malloc(initial_capacity * sizeof(LogEntry));
    if (!sys->entries) {
        fprintf(stderr, "Failed to allocate memory for log system\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&sys->mutex, NULL);
}

void destroy_log_system(LogSystem *sys) {
    free(sys->entries);
    pthread_mutex_destroy(&sys->mutex);
}

void resize_log_system(LogSystem *sys, size_t new_capacity) {
    LogEntry *new_entries = (LogEntry *)realloc(sys->entries, new_capacity * sizeof(LogEntry));
    if (!new_entries) {
        fprintf(stderr, "Failed to reallocate memory for log system\n");
        exit(EXIT_FAILURE);
    }
    sys->entries = new_entries;
    sys->capacity = new_capacity;
}

void add_log_entry(LogSystem *sys, const char *message, LogLevel level) {
    pthread_mutex_lock(&sys->mutex);
    if (sys->count >= sys->capacity) {
        resize_log_system(sys, sys->capacity * 2);
    }
    LogEntry *entry = &sys->entries[sys->count++];
    entry->timestamp = time(NULL);
    snprintf(entry->message, sizeof(entry->message), "%s", message);
    entry->level = level;
    entry->id = sys->count - 1;
    pthread_mutex_unlock(&sys->mutex);
}

void set_log_level(LogSystem *sys, int id, LogLevel level) {
    pthread_mutex_lock(&sys->mutex);
    if (id >= 0 && id < sys->count) {
        sys->entries[id].level = level;
    }
    pthread_mutex_unlock(&sys->mutex);
}

void free_log_entries(LogSystem *sys) {
    pthread_mutex_lock(&sys->mutex);
    for (size_t i = 0; i < sys->count; ++i) {
        // Free any dynamically allocated memory within log entries if needed
    }
    pthread_mutex_unlock(&sys->mutex);
}
