#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int field;
} record;

typedef struct {
    unsigned char* data;
    size_t length;
    uint32_t checksum;
} metadata;

typedef struct {
    long offset;
    int key;
    record rec;
    metadata meta;
} dataset_entry;

dataset_entry* create_dataset(size_t initial_size) {
    dataset_entry* dataset = (dataset_entry*)malloc(initial_size * sizeof(dataset_entry));
    if (!dataset) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return dataset;
}

void free_dataset(dataset_entry* dataset, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(dataset[i].meta.data);
    }
    free(dataset);
}

void initialize_record(record* rec, int min_value, int max_value) {
    rec->field = rand() % (max_value - min_value + 1) + min_value;
}

void initialize_metadata(metadata* meta, size_t length, uint32_t pattern) {
    meta->data = (unsigned char*)malloc(length);
    if (!meta->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < length; ++i) {
        meta->data[i] = (pattern >> (i % 8)) & 0xFF;
    }
    // Calculate checksum
    meta->checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        meta->checksum += meta->data[i];
    }
}

void update_metadata(metadata* meta, size_t start_index, size_t end_index, uint32_t new_pattern) {
    for (size_t i = start_index; i <= end_index && i < meta->length; ++i) {
        meta->data[i] = (new_pattern >> (i % 8)) & 0xFF;
    }
    // Recalculate checksum
    meta->checksum = 0;
    for (size_t i = 0; i < meta->length; ++i) {
        meta->checksum += meta->data[i];
    }
}

void export_dataset(dataset_entry* dataset, size_t size, const char* filename, int compress) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Write header
    fwrite(&size, sizeof(size_t), 1, file);

    for (size_t i = 0; i < size; ++i) {
        fwrite(&dataset[i].offset, sizeof(long), 1, file);
        fwrite(&dataset[i].key, sizeof(int), 1, file);
        fwrite(&dataset[i].rec.field, sizeof(int), 1, file);

        // Write metadata
        fwrite(&dataset[i].meta.length, sizeof(size_t), 1, file);
        if (compress) {
            // Compress data before writing
            // ...
        } else {
            fwrite(dataset[i].meta.data, sizeof(unsigned char), dataset[i].meta.length, file);
        }
        fwrite(&dataset[i].meta.checksum, sizeof(uint32_t), 1, file);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    size_t initial_size = 100;
    dataset_entry* dataset = create_dataset(initial_size);

    for (size_t i = 0; i < initial_size; ++i) {
        initialize_record(&dataset[i].rec, 0, 100);
        initialize_metadata(&dataset[i].meta, 256, i * 0x12345678);
    }

    export_dataset(dataset, initial_size, "dataset.bin", 0);

    free_dataset(dataset, initial_size);

    return 0;
}
