void* process_and_filter_data(const char* filename, const char* format) {
    pthread_mutex_lock(&mutex);
    if (records != NULL) {
        cleanup();
    }

    FILE* file = fopen(filename, "r");
    if (!file) {
        log_message("Failed to open file");
        pthread_mutex_unlock(&mutex);
        return NULL;
