typedef struct Record {
    int value;
    size_t size;
    void *offset;
    struct Record *next;
} Record;

// Define red-black tree node struct
typedef struct RBTreeNode {
    int key;
    struct RBTreeNode *left, *right, *parent;
    char color;
} RBTreeNode;

// Function prototypes
Device* create_device(int num_devices);
