#define MAX_PATH_LENGTH 256

typedef struct node {
    char path[MAX_PATH_LENGTH];
    int file_count;
    struct node* next;
} Node;

Node* create_node(const char* path, int min_files, int max_files) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    strncpy(new_node->path, path, MAX_PATH_LENGTH - 1);
    new_node->path[MAX_PATH_LENGTH - 1] = '\0';
    new_node->file_count = rand() % (max_files - min_files + 1) + min_files;
    new_node->next = NULL;
    return new_node;
}

void free_nodes(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int calculate_total_files(Node* head) {
    int total_files = 0;
    Node* current = head;
    while (current != NULL) {
        total_files += current->file_count;
        current = current->next;
    }
    return total_files;
}

void add_node(Node** head, const char* path, int min_files, int max_files) {
    Node* new_node = create_node(path, min_files, max_files);
    if (new_node != NULL) {
        new_node->next = *head;
        *head = new_node;
    }
}

int main() {
    srand(time(NULL));
    Node* head = NULL;

    add_node(&head, "/home/user/documents", 10, 50);
    add_node(&head, "/home/user/pictures", 20, 80);

    int total_files = calculate_total_files(head);
    printf("Total files across all directories: %d\n", total_files);

    free_nodes(head);

    return 0;
}
