#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct HashTableEntry {
    char *key;
    void *value;
    int ref_count;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct HashTable {
    HashTableEntry **buckets;
    size_t capacity;
    size_t size;
    float load_factor_threshold;
} HashTable;

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

HashTable *create_hash_table(size_t initial_capacity, float load_factor_threshold) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->buckets = (HashTableEntry **)calloc(initial_capacity, sizeof(HashTableEntry *));
    table->capacity = initial_capacity;
    table->size = 0;
    table->load_factor_threshold = load_factor_threshold;
    return table;
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * 2;
    HashTableEntry **new_buckets = (HashTableEntry **)calloc(new_capacity, sizeof(HashTableEntry *));

    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry != NULL) {
            size_t new_index = hash(entry->key) % new_capacity;
            HashTableEntry *next_entry = entry->next;
            entry->next = new_buckets[new_index];
            new_buckets[new_index] = entry;
            entry = next_entry;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void insert_hash_table(HashTable *table, const char *key, void *value) {
    size_t index = hash(key) % table->capacity;
    HashTableEntry *entry = table->buckets[index];

    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            entry->ref_count++;
            free(value);
            return;
        }
        entry = entry->next;
    }

    entry = (HashTableEntry *)malloc(sizeof(HashTableEntry));
    entry->key = strdup(key);
    entry->value = value;
    entry->ref_count = 1;
    entry->next = table->buckets[index];
    table->buckets[index] = entry;

    table->size++;
    if ((float)table->size / table->capacity > table->load_factor_threshold) {
        resize_hash_table(table);
    }
}

void *get_hash_table(HashTable *table, const char *key) {
    size_t index = hash(key) % table->capacity;
    HashTableEntry *entry = table->buckets[index];

    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            entry->ref_count++;
            return entry->value;
        }
        entry = entry->next;
    }

    return NULL;
}

void update_hash_table(HashTable *table, const char *key, void *new_value) {
    size_t index = hash(key) % table->capacity;
    HashTableEntry *entry = table->buckets[index];

    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            entry->ref_count++;
            free(entry->value);
            entry->value = new_value;
            return;
        }
        entry = entry->next;
    }

    insert_hash_table(table, key, new_value);
}

void delete_hash_table(HashTable *table, const char *key) {
    size_t index = hash(key) % table->capacity;
    HashTableEntry **entry_ptr = &table->buckets[index];
    HashTableEntry *entry = *entry_ptr;

    while (entry != NULL) {
        if (strcmp(entry->key, key) == 0) {
            entry->ref_count--;
            if (entry->ref_count == 0) {
                *entry_ptr = entry->next;
                free(entry->key);
                free(entry->value);
                free(entry);
                table->size--;
            }
            return;
        }
        entry_ptr = &entry->next;
        entry = *entry_ptr;
    }
}

void free_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        HashTableEntry *entry = table->buckets[i];
        while (entry != NULL) {
            HashTableEntry *next_entry = entry->next;
            free(entry->key);
            free(entry->value);
            free(entry);
            entry = next_entry;
        }
    }

    free(table->buckets);
    free(table);
}
