#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 1024
#define SESSION_ID_LEN 32

typedef struct {
    char session_id[SESSION_ID_LEN];
    time_t start_time;
    time_t end_time;
} user_session;

user_session** sessions = NULL;
int session_count = 0;
time_t total_active_duration = 0;

pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_sessions() {
    pthread_mutex_lock(&session_lock);
    if (sessions == NULL) {
        sessions = (user_session**)malloc(MAX_SESSIONS * sizeof(user_session*));
        if (sessions == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        for (int i = 0; i < MAX_SESSIONS; i++) {
            sessions[i] = NULL;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void add_session(const char* session_id) {
    pthread_mutex_lock(&session_lock);
    if (session_count >= MAX_SESSIONS) {
        fprintf(stderr, "Session limit reached\n");
        pthread_mutex_unlock(&session_lock);
        return;
    }
    user_session* new_session = (user_session*)malloc(sizeof(user_session));
    if (new_session == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&session_lock);
        return;
    }
    strncpy(new_session->session_id, session_id, SESSION_ID_LEN - 1);
    new_session->session_id[SESSION_ID_LEN - 1] = '\0';
    new_session->start_time = time(NULL);
    new_session->end_time = 0;
    sessions[session_count++] = new_session;
    pthread_mutex_unlock(&session_lock);
}

void end_session(const char* session_id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i]->session_id, session_id) == 0) {
            sessions[i]->end_time = time(NULL);
            total_active_duration += difftime(sessions[i]->end_time, sessions[i]->start_time);
            free(sessions[i]);
            sessions[i] = NULL;
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void free_sessions() {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; i++) {
        if (sessions[i] != NULL) {
            free(sessions[i]);
        }
    }
    free(sessions);
    sessions = NULL;
    session_count = 0;
    total_active_duration = 0;
    pthread_mutex_unlock(&session_lock);
}

time_t get_total_active_duration() {
    return total_active_duration;
}
