#include <pthread.h>

#define MAX_PATH_LENGTH 256
#define MIN_FILE_SIZE 1024
#define MAX_FILE_SIZE 1024 * 1024

typedef struct node {
    char path[MAX_PATH_LENGTH];
    int num_files;
    int* file_sizes;
    struct node** children;
    int child_count;
    pthread_mutex_t lock;
} Node;

Node* create_node(const char* path, int min_size, int max_size) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    strcpy(new_node->path, path);
    new_node->num_files = rand() % (max_size - min_size + 1) + min_size;
    new_node->file_sizes = (int*)calloc(new_node->num_files, sizeof(int));
    if (!new_node->file_sizes) {
        free(new_node);
        return NULL;
    }

    for (int i = 0; i < new_node->num_files; ++i) {
        new_node->file_sizes[i] = rand() % (max_size - min_size + 1) + min_size;
    }

    new_node->children = NULL;
    new_node->child_count = 0;
    pthread_mutex_init(&new_node->lock, NULL);

    return new_node;
}

void free_node(Node* node) {
    if (!node) return;

    for (int i = 0; i < node->num_files; ++i) {
        free(node->file_sizes[i]);
    }
    free(node->file_sizes);

    for (int i = 0; i < node->child_count; ++i) {
        free_node(node->children[i]);
    }
    free(node->children);

    pthread_mutex_destroy(&node->lock);
    free(node);
}

void add_child(Node* parent, Node* child) {
    pthread_mutex_lock(&parent->lock);
    if (!parent->children) {
        parent->children = (Node**)malloc(sizeof(Node*) * 1);
        if (!parent->children) {
            pthread_mutex_unlock(&parent->lock);
            return;
        }
        parent->child_count = 0;
    } else {
        parent->children = realloc(parent->children, sizeof(Node*) * (parent->child_count + 1));
        if (!parent->children) {
            pthread_mutex_unlock(&parent->lock);
            return;
        }
    }

    parent->children[parent->child_count++] = child;
    pthread_mutex_unlock(&parent->lock);
}

long long calculate_total_size(Node* node) {
    long long total_size = 0;

    for (int i = 0; i < node->num_files; ++i) {
        total_size += node->file_sizes[i];
    }

    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < node->child_count; ++i) {
        total_size += calculate_total_size(node->children[i]);
    }
    pthread_mutex_unlock(&node->lock);

    return total_size;
}

int main() {
    srand(time(NULL));

    Node* root = create_node("/", MIN_FILE_SIZE, MAX_FILE_SIZE);
    if (!root) {
        fprintf(stderr, "Failed to create root node\n");
        return 1;
    }

    // Example of adding children
    Node* child1 = create_node("/home", MIN_FILE_SIZE, MAX_FILE_SIZE);
    if (child1) add_child(root, child1);

    Node* child2 = create_node("/usr", MIN_FILE_SIZE, MAX_FILE_SIZE);
    if (child2) add_child(root, child2);

    long long total_size = calculate_total_size(root);
    printf("Total size of all files: %lld bytes\n", total_size);

    free_node(root);

    return 0;
}
