#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    double value;
    time_t last_updated;
    unsigned long *timestamp;
} data_block;

double generate_random(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

void process_and_analyze_data(int num_elements, double min_val, double max_val, const char* filename) {
    if (num_elements <= 0 || min_val >= max_val) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    double *float_array = malloc(num_elements * sizeof(double));
    unsigned long *timestamp_array = malloc(num_elements * sizeof(unsigned long));
    data_block *data_blocks = malloc(num_elements * sizeof(data_block));

    if (!float_array || !timestamp_array || !data_blocks) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(float_array);
        free(timestamp_array);
        free(data_blocks);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < num_elements; ++i) {
        float_array[i] = generate_random(min_val, max_val);
        timestamp_array[i] = time(NULL);
        data_blocks[i].value = float_array[i];
        data_blocks[i].last_updated = timestamp_array[i];
        data_blocks[i].timestamp = &timestamp_array[i];
    }

    // Read file and store numbers
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file.\n");
        free(float_array);
        free(timestamp_array);
        free(data_blocks);
        return;
    }

    double sum = 0.0;
    int count = 0;
    while (fscanf(file, "%lf", &float_array[count]) == 1) {
        sum += float_array[count];
        ++count;
    }
    fclose(file);

    // Calculate average
    if (count > 0) {
        double average = sum / count;
        printf("Average value: %f\n", average);
    }

    // Find most frequent number
    int *frequency = calloc(num_elements, sizeof(int));
    for (int i = 0; i < count; ++i) {
        for (int j = 0; j < num_elements; ++j) {
            if (float_array[i] == data_blocks[j].value) {
                ++frequency[j];
                break;
            }
        }
    }

    int max_freq = 0;
    double most_frequent = float_array[0];
    for (int i = 0; i < num_elements; ++i) {
        if (frequency[i] > max_freq) {
            max_freq = frequency[i];
            most_frequent = data_blocks[i].value;
        }
    }

    printf("Most frequent number: %f\n", most_frequent);

    // Free allocated memory
    free(float_array);
    free(timestamp_array);
    free(data_blocks);
    free(frequency);
}

int main() {
    process_and_analyze_data(10, 0.0, 100.0, "data.txt");
    return 0;
}
