int find_largest_integer(int *array, size_t length) {
    int max = array[0];
    for (size_t i = 1; i < length; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void process_and_manage_pdu() {
    srand(time(NULL));

    long *offsets = malloc(N * sizeof(long));
    int *keys = malloc(N * sizeof(int));
    record **records = malloc(N * sizeof(record*));
    NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!offsets || !keys || !records || !pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < N; ++i) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % 100;
        records[i] = create_record(1024); // Example size
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record\n");
            exit(EXIT_FAILURE);
        }
        pdus[i] = create_crc_pdu();
        if (!pdus[i]) {
            fprintf(stderr, "Memory allocation failed for CRC PDU\n");
            exit(EXIT_FAILURE);
        }
    }

    int *input_array = malloc(N * sizeof(int));
    if (!input_array) {
        fprintf(stderr, "Memory allocation failed for input array\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter %zu integers:\n", N);
    for (size_t i = 0; i < N; ++i) {
        scanf("%d", &input_array[i]);
    }

    int largest = find_largest_integer(input_array, N);
    printf("Largest integer: %d\n", largest);

    free(input_array);

    for (size_t i = 0; i < N; ++i) {
        free_record(records[i]);
        free_crc_pdu(pdus[i]);
    }

    free(offsets);
    free(keys);
    free(records);
    free(pdus);
}

int main() {
    process_and_manage_pdu();
    return 0;
}
