#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct session {
    long* offsets;
    int* keys;
    Record** records;
    size_t num_elements;
    pthread_mutex_t lock;
} Session;

Session* create_session(size_t num_elements) {
    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) return NULL;

    session->offsets = (long*)calloc(num_elements, sizeof(long));
    session->keys = (int*)calloc(num_elements, sizeof(int));
    session->records = (Record**)calloc(num_elements, sizeof(Record*));
    session->num_elements = num_elements;
    pthread_mutex_init(&session->lock, NULL);

    if (!session->offsets || !session->keys || !session->records) {
        free(session);
        return NULL;
    }

    return session;
}

void destroy_session(Session* session) {
    for (size_t i = 0; i < session->num_elements; ++i) {
        if (session->records[i]) {
            free(session->records[i]);
        }
    }
    free(session->offsets);
    free(session->keys);
    free(session->records);
    pthread_mutex_destroy(&session->lock);
    free(session);
}

void populate_records(Session* session, int min_value, int max_value) {
    for (size_t i = 0; i < session->num_elements; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        if (!record) continue;

        record->value = rand() % (max_value - min_value + 1) + min_value;
        session->records[i] = record;
    }
}

int add_record(Session* session, int key, int value) {
    pthread_mutex_lock(&session->lock);
    for (size_t i = 0; i < session->num_elements; ++i) {
        if (!session->keys[i]) {
            session->keys[i] = key;
            Record* record = (Record*)malloc(sizeof(Record));
            if (!record) {
                pthread_mutex_unlock(&session->lock);
                return -1;
            }
            record->value = value;
            session->records[i] = record;
            pthread_mutex_unlock(&session->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&session->lock);
    return -1;
}

Record* get_record(Session* session, int key) {
    pthread_mutex_lock(&session->lock);
    for (size_t i = 0; i < session->num_elements; ++i) {
        if (session->keys[i] == key) {
            Record* record = session->records[i];
            pthread_mutex_unlock(&session->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&session->lock);
    return NULL;
}

int main() {
    Session* session = create_session(100);
    if (!session) {
        fprintf(stderr, "Failed to create session\n");
        return 1;
    }

    populate_records(session, -100, 100);

    Record* record = get_record(session, 42);
    if (record) {
        printf("Record value: %d\n", record->value);
    } else {
        printf("Record not found\n");
    }

    destroy_session(session);
    return 0;
}
