    // Allocate memory for data structures
    long *offsets = (long *)malloc(num_elements * sizeof(long));
    if (!offsets) return -1;

    int *keys = (int *)malloc(num_elements * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1;
    }

    record *records = (record *)malloc(num_elements * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -1;
    }

    double *timestamps = (double *)malloc(num_elements * sizeof(double));
    if (!timestamps) {
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    // Initialize data structures
    for (int i = 0; i < num_elements; i++) {
        offsets[i] = rand() % num_elements;
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
        timestamps[i] = ((double)rand()) / RAND_MAX * timestamp_precision;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);

    return 0;
}

