    srand(time(NULL));

    int num_elements = 1000;
    int range_start = -1000;
    int range_end = 1000;
    int timestamp_precision = 1e-6;

    if (initialize_data_structures(num_elements, range_start, range_end, timestamp_precision) != 0) {
        fprintf(stderr, "Failed to initialize data structures\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
