    // Dynamically allocate memory for arrays
    double *double_array = NULL;
    unsigned long *timestamp_array = NULL;
    data_block *data_blocks = NULL;

    size_t count = 0;
    while (fscanf(file, "%lf", &min_val) == 1) {
        count++;
    }
    fclose(file);

    double_array = malloc(count * sizeof(double));
    timestamp_array = malloc(count * sizeof(unsigned long));
    data_blocks = malloc(count * sizeof(data_block));

    if (!double_array || !timestamp_array || !data_blocks) {
        perror("Memory allocation failed");
        free(double_array);
        free(timestamp_array);
        free(data_blocks);
        return;
    }

    file = fopen(filename, "r");
    for (size_t i = 0; i < count; i++) {
        fscanf(file, "%lf", &double_array[i]);
        timestamp_array[i] = time(NULL);
        data_blocks[i].value = generate_random(min_val, max_val);
        data_blocks[i].last_updated = timestamp_array[i];
        data_blocks[i].timestamp = &timestamp_array[i];
    }
    fclose(file);

    // Calculate and print average value
    double sum = 0;
    for (size_t i = 0; i < count; i++) {
        sum += double_array[i];
    }
    printf("Average value: %f\n", sum / count);

    // Find and print most frequent number
    int *frequency = malloc(count * sizeof(int));
    if (!frequency) {
        perror("Memory allocation failed");
        free(double_array);
        free(timestamp_array);
        free(data_blocks);
        return;
    }

    for (size_t i = 0; i < count; i++) {
        frequency[i] = 1;
        for (size_t j = 0; j < i; j++) {
            if (double_array[j] == double_array[i]) {
                frequency[i]++;
                break;
            }
        }
    }

    int max_freq = 0;
    double most_frequent = double_array[0];
    for (size_t i = 1; i < count; i++) {
        if (frequency[i] > max_freq) {
            max_freq = frequency[i];
            most_frequent = double_array[i];
        }
    }

    printf("Most frequent number: %f\n", most_frequent);

    // Free allocated memory
    free(double_array);
    free(timestamp_array);
    free(data_blocks);
    free(frequency);
}

int main() {
    srand(time(NULL));
    process_and_analyze_data(0.0, 100.0, "data.txt");
    return 0;
}
