void* allocate_log_memory(size_t num_entries, size_t max_message_length) {
    // Allocate memory for offset array
    long *offsets = (long *)malloc(num_entries * sizeof(long));
    if (!offsets) return NULL;

    // Allocate memory for key array
    int *keys = (int *)malloc(num_entries * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for log entries
    logEntry *entries = (logEntry *)malloc(num_entries * sizeof(logEntry));
    if (!entries) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize log entries
    for (size_t i = 0; i < num_entries; ++i) {
        entries[i].message = (char *)malloc(max_message_length * sizeof(char));
        if (!entries[i].message) {
            for (size_t j = 0; j < i; ++j) free(entries[j].message);
            free(offsets);
            free(keys);
            free(entries);
            return NULL;
        }
    }

    // Initialize random number generator
    srand(time(NULL));

    // Assign unique identifiers to log entries
    for (size_t i = 0; i < num_entries; ++i) {
        keys[i] = rand() % num_entries;
    }

    // Return allocated memory
    return entries;
}

void flush_logs_to_file(logEntry *entries, size_t num_entries, const char *filename) {
    FILE *file = fopen(filename, "a");
    if (!file) return;

    for (size_t i = 0; i < num_entries; ++i) {
        fprintf(file, "Level: %d, Message: %s, Timestamp: %ld\n", entries[i].level, entries[i].message, entries[i].timestamp);
    }

    fclose(file);
}

void free_log_memory(logEntry *entries, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) free(entries[i].message);
    free(entries);
}
