#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;

bool add_record(long offset, int key, int value) {
    if (record_count >= MAX_RECORDS) return false; // Check for memory limit
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) { // Key collision
            records[i].offset = offset;
            records[i].value = value;
            return true;
        }
    }
    records[record_count].offset = offset;
    records[record_count].key = key;
    records[record_count].value = value;
    record_count++;
    return true;
}

void get_records_above_offset(long threshold, Record **result, int *count) {
    *count = 0;
    for (int i = 0; i < record_count; i++) {
        if (records[i].offset > threshold) {
            result[*count] = &records[i];
            (*count)++;
        }
    }
}

int main() {
    // Example usage
    add_record(10, 1, 100);
    add_record(20, 2, 200);
    add_record(30, 1, 300); // Update existing key

    Record *result[MAX_RECORDS];
    int count;
    get_records_above_offset(15, result, &count);

    for (int i = 0; i < count; i++) {
        printf("Offset: %ld, Key: %d, Value: %d\n", result[i]->offset, result[i]->key, result[i]->value);
    }

    return 0;
}
