#define MAX_IP_LEN 16
#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    uint64_t timestamp;
    char source_ip[MAX_IP_LEN];
    unsigned char *payload;
} Event;

Event* create_event(uint64_t start_time, uint64_t end_time, int message_length) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static uint64_t current_time = 0;
    Event *event = (Event *)malloc(sizeof(Event));
    if (!event) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    event->timestamp = current_time++;
    if (current_time > end_time) {
        current_time = start_time + 1;
    }
    pthread_mutex_unlock(&mutex);

    inet_ntop(AF_INET, &event->source_ip, MAX_IP_LEN);
    event->payload = (unsigned char *)malloc(message_length * sizeof(unsigned char));
    if (!event->payload) {
        fprintf(stderr, "Memory allocation failed\n");
        free(event);
        return NULL;
    }

    for (int i = 0; i < message_length; i++) {
        event->payload[i] = rand() % 256;
    }

    return event;
}

void destroy_event(Event *event) {
    if (event->payload) {
        free(event->payload);
    }
    free(event);
}

Event** create_events(int num_events, uint64_t start_time, uint64_t end_time, int message_length) {
    Event **events = (Event **)malloc(num_events * sizeof(Event *));
    if (!events) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_events; i++) {
        events[i] = create_event(start_time, end_time, message_length);
        if (!events[i]) {
            destroy_events(events, i);
            return NULL;
        }
    }

    return events;
}

void destroy_events(Event **events, int num_events) {
    for (int i = 0; i < num_events; i++) {
        destroy_event(events[i]);
    }
    free(events);
}

void print_event(Event *event) {
    printf("Timestamp: %llu\n", event->timestamp);
    printf("Source IP: %s\n", event->source_ip);
    printf("Payload: ");
    for (int i = 0; i < strlen((char *)event->payload); i++) {
        printf("%02x ", event->payload[i]);
    }
    printf("\n");
}

Event* query_event(Event **events, int num_events, uint64_t timestamp) {
    for (int i = 0; i < num_events; i++) {
        if (events[i]->timestamp == timestamp) {
            return events[i];
        }
    }
    return NULL;
}
