#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024
#define RING_BUFFER_SIZE 1024

typedef struct {
    unsigned char data[MAX_PACKET_SIZE];
    int size;
} DataPacket;

typedef struct {
    DataPacket packets[RING_BUFFER_SIZE];
    int head, tail;
    pthread_mutex_t lock;
} RingBuffer;

typedef struct {
    int sequenceNumber;
    long timestamp;
    int priorityLevel;
} PacketMetadata;

typedef struct {
    PacketMetadata *metadata;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MetadataArray;

void initRingBuffer(RingBuffer *rb) {
    rb->head = rb->tail = 0;
    pthread_mutex_init(&rb->lock, NULL);
}

int isRingBufferFull(RingBuffer *rb) {
    return (rb->tail + 1) % RING_BUFFER_SIZE == rb->head;
}

void enqueuePacket(RingBuffer *rb, DataPacket packet) {
    pthread_mutex_lock(&rb->lock);
    if (!isRingBufferFull(rb)) {
        rb->packets[rb->tail] = packet;
        rb->tail = (rb->tail + 1) % RING_BUFFER_SIZE;
    }
    pthread_mutex_unlock(&rb->lock);
}

int isRingBufferEmpty(RingBuffer *rb) {
    return rb->head == rb->tail;
}

DataPacket dequeuePacket(RingBuffer *rb) {
    DataPacket packet = {0};
    pthread_mutex_lock(&rb->lock);
    if (!isRingBufferEmpty(rb)) {
        packet = rb->packets[rb->head];
        rb->head = (rb->head + 1) % RING_BUFFER_SIZE;
    }
    pthread_mutex_unlock(&rb->lock);
    return packet;
}

void initMetadataArray(MetadataArray *ma, size_t initialCapacity) {
    ma->metadata = malloc(initialCapacity * sizeof(PacketMetadata));
    ma->count = 0;
    ma->capacity = initialCapacity;
    pthread_mutex_init(&ma->lock, NULL);
}

void resizeMetadataArray(MetadataArray *ma, size_t newCapacity) {
    pthread_mutex_lock(&ma->lock);
    PacketMetadata *newMetadata = realloc(ma->metadata, newCapacity * sizeof(PacketMetadata));
    if (newMetadata != NULL) {
        ma->metadata = newMetadata;
        ma->capacity = newCapacity;
    }
    pthread_mutex_unlock(&ma->lock);
}

void addPacketMetadata(MetadataArray *ma, PacketMetadata metadata) {
    pthread_mutex_lock(&ma->lock);
    if (ma->count == ma->capacity) {
        resizeMetadataArray(ma, ma->capacity * 2);
    }
    ma->metadata[ma->count++] = metadata;
    pthread_mutex_unlock(&ma->lock);
}

void freeMetadataArray(MetadataArray *ma) {
    pthread_mutex_lock(&ma->lock);
    free(ma->metadata);
    pthread_mutex_destroy(&ma->lock);
}
