#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    size_t size;
    long *offset;
} Record;

// Define the AVL tree node structure
typedef struct Node {
    Record data;
    struct Node *left, *right;
    int height;
} Node;

// Function to create a new node with given data
Node* newNode(Record data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->left = node->right = NULL;
    node->height = 1; // new node is initially added at leaf
    return(node);
}

// Function to get the height of the tree
int height(Node *N) {
    if (N == NULL)
        return 0;
    return N->height;
}

// Function to right rotate subtree rooted with y
Node *rightRotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

// Function to left rotate subtree rooted with x
Node *leftRotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

// Get the balance factor of node N
int getBalance(Node *N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

// Function to insert a new record in AVL tree with given data
Node* insert(Node* node, Record data) {
    // Perform the normal BST insertion
    if (node == NULL)
        return(newNode(data));

    if (data.value < node->data.value)
        node->left = insert(node->left, data);
    else if (data.value > node->data.value)
        node->right = insert(node->right, data);
    else // Equal keys are not allowed in BST
        return node;

    // Update height of this ancestor node
    node->height = 1 + max(height(node->left), height(node->right));

    // Get the balance factor of this ancestor node to check whether
    // this node became unbalanced
    int balance = getBalance(node);

    // If this node becomes unbalanced, then there are 4 cases

    // Left Left Case
    if (balance > 1 && data.value < node->left->data.value)
        return rightRotate(node);

    // Right Right Case
    if (balance < -1 && data.value > node->right->data.value)
        return leftRotate(node);

    // Left Right Case
    if (balance > 1 && data.value > node->left->data.value) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    // Right Left Case
    if (balance < -1 && data.value < node->right->data.value) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    // return the (unchanged) node pointer
    return node;
}

// Function to find and print the largest integer in an array
void findAndPrintLargest(int arr[], int n) {
    if (n == 0) {
        printf("Array is empty\n");
        return;
    }
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("Largest integer: %d\n", max);
}

// Function to free all allocated memory
void freeMemory(Node* node) {
    if (node == NULL)
        return;
    freeMemory(node->left);
    freeMemory(node->right);
    free(node);
}

int main() {
    // Initialize random number generator
    srand(time(0));

    // Example usage of the AVL tree functions
    Node *root = NULL;

    // Insert records into the AVL tree
    Record data1 = {rand() % 100, sizeof(int), (long*)malloc(sizeof(int))};
    root = insert(root, data1);

    Record data2 = {rand() % 100, sizeof(int), (long*)malloc(sizeof(int))};
    root = insert(root, data2);

    // Find and print the largest integer in an array
    int arr[] = {5, 3, 8, 4, 2, 7, 9, 1, 6};
    findAndPrintLargest(arr, sizeof(arr)/sizeof(arr[0]));

    // Free all allocated memory
    freeMemory(root);

    return 0;
}
