#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    size_t size;
    long *offset;
} record;

// Define the AVL tree node structure
typedef struct avl_node {
    record data;
    struct avl_node *left, *right;
    int height;
} avl_node;

// Function to create a new AVL node
avl_node* create_avl_node(record data) {
    avl_node* node = (avl_node*)malloc(sizeof(avl_node));
    if (node == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->data = data;
    node->left = node->right = NULL;
    node->height = 1; // New node is initially added at leaf
    return node;
}

// Function to get the height of a node
int height(avl_node *node) {
    if (node == NULL)
        return 0;
    return node->height;
}

// Function to right rotate subtree rooted with y
avl_node* right_rotate(avl_node *y) {
    avl_node *x = y->left;
    avl_node *T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

// Function to left rotate subtree rooted with x
avl_node* left_rotate(avl_node *x) {
    avl_node *y = x->right;
    avl_node *T2 = y->left;

    // Perform rotation
    y->left = x;
    x->right = T2;

    // Update heights
    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

// Function to get the balance factor of node N
int get_balance(avl_node *N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

// Function to insert a record in AVL tree
avl_node* insert_avl(avl_node* node, record data) {
    // Perform the normal BST insertion
    if (node == NULL)
        return(create_avl_node(data));

    if (data.value < node->data.value)
        node->left = insert_avl(node->left, data);
    else if (data.value > node->data.value)
        node->right = insert_avl(node->right, data);
    else // Equal keys are not allowed in BST
        return node;

    // Update height of this ancestor node
    node->height = 1 + max(height(node->left), height(node->right));

    // Get the balance factor of this ancestor node to check whether
    // this node became unbalanced
    int balance = get_balance(node);

    // If this node becomes unbalanced, then there are 4 cases

    // Left Left Case
    if (balance > 1 && data.value < node->left->data.value)
        return right_rotate(node);

    // Right Right Case
    if (balance < -1 && data.value > node->right->data.value)
        return left_rotate(node);

    // Left Right Case
    if (balance > 1 && data.value > node->left->data.value) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }

    // Right Left Case
    if (balance < -1 && data.value < node->right->data.value) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    // return the (unchanged) node pointer
    return node;
}

// Function to find and print the largest integer in an array
void find_and_print_largest(int arr[], int n) {
    if (n == 0) {
        printf("Array is empty\n");
        return;
    }
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("Largest integer: %d\n", max);
}

// Function to free all allocated memory
void free_memory(avl_node* node) {
    if (node == NULL)
        return;
    free_memory(node->left);
    free_memory(node->right);
    free(node);
}

int main() {
    // Initialize variables and read input
    int n, i;
    scanf("%d", &n);
    int *arr = (int*)malloc(n * sizeof(int));
    for (i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    // Initialize data structures
    avl_node* root = NULL;

    // Insert elements into AVL tree
    srand(time(0)); // Seed for random number generation
    for (i = 0; i < n; i++) {
        record data;
        data.value = arr[i];
        data.size = sizeof(int);
        data.offset = (long*)malloc(sizeof(long));
        *data.offset = rand() % 1000; // Example offset value
        root = insert_avl(root, data);
    }

    // Find and print the largest integer in the array
    find_and_print_largest(arr, n);

    // Free all allocated memory
    free_memory(root);
    free(arr);

    return 0;
}
