#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    size_t size;
} Record;

typedef struct {
    char** strings;
    Record* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} StringArray;

StringArray* create_string_array(size_t initial_capacity) {
    StringArray* array = (StringArray*)malloc(sizeof(StringArray));
    if (!array) return NULL;

    array->strings = (char**)malloc(initial_capacity * sizeof(char*));
    array->records = (Record*)malloc(initial_capacity * sizeof(Record));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    if (!array->strings || !array->records) {
        free(array->strings);
        free(array->records);
        free(array);
        return NULL;
    }

    return array;
}

void destroy_string_array(StringArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->strings[i]);
    }
    pthread_mutex_destroy(&array->lock);
    free(array->strings);
    free(array->records);
    free(array);
}

int add_string(StringArray* array, const char* str) {
    if (!array || !str) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 4;
        char** new_strings = (char**)realloc(array->strings, new_capacity * sizeof(char*));
        Record* new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));

        if (!new_strings || !new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }

        array->strings = new_strings;
        array->records = new_records;
        array->capacity = new_capacity;
    }

    size_t len = strlen(str);
    char* new_str = (char*)malloc((len + 1) * sizeof(char));
    if (!new_str) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    strcpy(new_str, str);
    array->strings[array->count] = new_str;
    array->records[array->count].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    array->records[array->count].size = len;
    ++array->count;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

