    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle allocation failure
        return NULL;
    }
    new_node->index = index;
    new_node->next = NULL;
    return new_node;
}

void free_node(Node* node) {
    if (node != NULL) {
        free(node);
    }
}

Node* insert_node(Node** head, size_t index) {
    Node* new_node = create_node(index);
    if (new_node == NULL) {
        // Handle allocation failure
        return *head;
    }
    new_node->next = *head;
    *head = new_node;
    return *head;
}

Node* delete_node(Node** head, size_t index) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->index != index) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        // Node not found
        return *head;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free_node(current);
    return *head;
}

