typedef struct avl_node {
    Record *data;
    struct avl_node *left, *right;
    int height;
} AVLNode;

typedef struct avl_tree {
    AVLNode *root;
    pthread_mutex_t lock;
} AVLTree;

AVLNode* create_avl_node(Record *data) {
    AVLNode *node = (AVLNode*)malloc(sizeof(AVLNode));
    if (!node) return NULL;
    node->data = data;
    node->left = node->right = NULL;
    node->height = 1;
    return node;
}

int max(int a, int b) {
    return (a > b) ? a : b;
}

int height(AVLNode *node) {
    if (!node) return 0;
    return node->height;
}

AVLTree* create_avl_tree() {
    AVLTree *tree = (AVLTree*)malloc(sizeof(AVLTree));
    if (!tree) return NULL;
    pthread_mutex_init(&tree->lock, NULL);
    tree->root = NULL;
    return tree;
}

int get_balance(AVLNode *node) {
    if (!node) return 0;
    return height(node->left) - height(node->right);
}

AVLNode* right_rotate(AVLNode *y) {
    AVLNode *x = y->left;
    AVLNode *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

AVLNode* left_rotate(AVLNode *x) {
    AVLNode *y = x->right;
    AVLNode *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

AVLNode* insert(AVLNode *node, Record *data) {
    if (!node) return create_avl_node(data);

    if (data->value < node->data->value)
        node->left = insert(node->left, data);
    else if (data->value > node->data->value)
        node->right = insert(node->right, data);
    else
        return node;

    node->height = 1 + max(height(node->left), height(node->right));

    int balance = get_balance(node);

    if (balance > 1 && data->value < node->left->data->value)
        return right_rotate(node);

    if (balance < -1 && data->value > node->right->data->value)
        return left_rotate(node);

    if (balance > 1 && data->value > node->left->data->value) {
        node->left = left_rotate(node->left);
        return right_rotate(node);
    }

    if (balance < -1 && data->value < node->right->data->value) {
        node->right = right_rotate(node->right);
        return left_rotate(node);
    }

    return node;
}

