// JavaScript code to dynamically load multiple specified JavaScript files

function loadScript(url, callback) {
    var script = document.createElement('script');
    script.src = url;
    script.onload = function() {
        if (callback) callback();
    };
    document.head.appendChild(script);
}

function loadScriptsSequentially(urls, index, callback) {
    if (index >= urls.length) {
        if (callback) callback();
        return;
    }

    var url = urls[index];
    var modifiedUrl = modifyExtension(url);

    loadScript(modifiedUrl, function() {
        console.log('Loaded: ' + url);
        loadScriptsSequentially(urls, index + 1, callback);
    });
}

function modifyExtension(url) {
    // Custom logic to modify the extension
    var parts = url.split('.');
    if (parts.length > 1) {
        var baseName = parts[0];
        var ext = parts.slice(1).join('.');
        var sequence = generateSequence(baseName);
        return baseName + '_' + sequence + '.' + ext;
    }
    return url; // Default handling
}

function generateSequence(baseName) {
    // Custom logic to generate a sequence based on the filename
    var sum = 0;
    for (var i = 0; i < baseName.length; i++) {
        sum += baseName.charCodeAt(i);
    }
    return sum.toString(16); // Example: using hexadecimal
}

// Usage
var scriptUrls = ['script1.js', 'script2.js', 'script3.js'];
loadScriptsSequentially(scriptUrls, 0, function() {
    console.log('All scripts loaded');
});
