function fetchAndProcessData(url, processDataCallback, timeout, headers, maxRetries, cacheBust = null) {
    let retryCount = 0;
    const backoffFactor = 2; // Exponential backoff factor

    function fetchData() {
        if (retryCount > maxRetries) {
            console.error('Max retries reached. Unable to fetch data.');
            return;
        }

        const requestUrl = cacheBust ? `${url}?${cacheBust}` : url;

        fetch(requestUrl, { headers })
            .then(response => {
                if (!response.ok) {
                    throw new Error(`HTTP error! status: ${response.status}`);
                }
                return response.json();
            })
            .then(data => {
                processDataCallback(data);
            })
            .catch(error => {
                console.error('Fetch failed:', error);
                retryCount++;
                setTimeout(fetchData, timeout * backoffFactor ** retryCount);
            });
    }

    fetchData();
}
