#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct frame {
    char* data;
    size_t size;
    int ref_count;
    struct frame* prev;
    struct frame* next;
} Frame;

typedef struct {
    Frame** pool;
    size_t pool_size;
    size_t pool_index;
} MemoryPool;

typedef struct {
    Frame* head;
    Frame* tail;
    size_t count;
    size_t max_frames;
    MemoryPool* pool;
    pthread_mutex_t lock;
} FrameBuffer;

Frame* create_frame(size_t size) {
    Frame* frame = (Frame*)malloc(sizeof(Frame));
    if (!frame) return NULL;
    frame->data = (char*)malloc(size);
    if (!frame->data) {
        free(frame);
        return NULL;
    }
    frame->size = size;
    frame->ref_count = 1;
    frame->prev = NULL;
    frame->next = NULL;
    return frame;
}

void destroy_frame(Frame* frame) {
    free(frame->data);
    free(frame);
}

MemoryPool* create_memory_pool(size_t pool_size, size_t frame_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->pool = (Frame**)malloc(pool_size * sizeof(Frame*));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pool->pool_size = pool_size;
    pool->pool_index = 0;
    for (size_t i = 0; i < pool_size; ++i) {
        pool->pool[i] = create_frame(frame_size);
        if (!pool->pool[i]) {
            for (size_t j = 0; j < i; ++j) destroy_frame(pool->pool[j]);
            free(pool->pool);
            free(pool);
            return NULL;
        }
    }
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->pool_size; ++i) destroy_frame(pool->pool[i]);
    free(pool->pool);
    free(pool);
}

FrameBuffer* create_frame_buffer(size_t max_frames, MemoryPool* pool) {
    FrameBuffer* buffer = (FrameBuffer*)malloc(sizeof(FrameBuffer));
    if (!buffer) return NULL;
    buffer->head = NULL;
    buffer->tail = NULL;
    buffer->count = 0;
    buffer->max_frames = max_frames;
    buffer->pool = pool;
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void destroy_frame_buffer(FrameBuffer* buffer) {
    Frame* current = buffer->head;
    while (current) {
        Frame* next = current->next;
        destroy_frame(current);
        current = next;
    }
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

void add_frame_to_buffer(FrameBuffer* buffer, Frame* frame) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count >= buffer->max_frames) {
        Frame* oldest = buffer->head;
        buffer->head = oldest->next;
        if (oldest->next) oldest->next->prev = NULL;
        else buffer->tail = NULL;
        destroy_frame(oldest);
        buffer->count--;
    }
    frame->next = buffer->tail;
    frame->prev = NULL;
    if (buffer->tail) buffer->tail->next = frame;
    else buffer->head = frame;
    buffer->tail = frame;
    buffer->count++;
    pthread_mutex_unlock(&buffer->lock);
}

Frame* get_frame_from_buffer(FrameBuffer* buffer) {
    Frame* frame = NULL;
    pthread_mutex_lock(&buffer->lock);
    if (buffer->head) {
        frame = buffer->head;
        buffer->head = frame->next;
        if (frame->next) frame->next->prev = NULL;
        else buffer->tail = NULL;
        buffer->count--;
    }
    pthread_mutex_unlock(&buffer->lock);
    return frame;
}

void stream_process_and_manage_media(size_t base_timestamp, size_t frame_interval, size_t max_frames) {
    MemoryPool* pool = create_memory_pool(1024, 1024 * 1024); // Example: 1024 frames of 1MB each
    FrameBuffer* buffer = create_frame_buffer(max_frames, pool);

    while (1) {
        size_t timestamp = base_timestamp + frame_interval * buffer->count;
        Frame* frame = get_frame_from_buffer(buffer);
        if (!frame) {
            frame = pool->pool[pool->pool_index++];
            if (pool->pool_index == pool->pool_size) pool->pool_index = 0;
        }
        // Process the frame with the timestamp
        printf("Processing frame at timestamp %zu\n", timestamp);
        add_frame_to_buffer(buffer, frame);
    }

    destroy_frame_buffer(buffer);
    destroy_memory_pool(pool);
}
