// Define the event structure
typedef struct Event {
    double timestamp;
    double temperature;
    char label[100];
    struct Event* next;
} Event;

// Define the min-heap structure
typedef struct MinHeap {
    double* array;
    int size;
    int capacity;
} MinHeap;

// Function to initialize the event structure
Event* create_event(double timestamp, double temperature, const char* label) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (event == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    event->timestamp = timestamp;
    event->temperature = temperature;
    strncpy(event->label, label, sizeof(event->label) - 1);
    event->next = NULL;
    return event;
}

// Function to initialize the min-heap structure
MinHeap* create_min_heap(int capacity) {
    MinHeap* heap = (MinHeap*)malloc(sizeof(MinHeap));
    if (heap == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    heap->array = (double*)calloc(capacity, sizeof(double));
    if (heap->array == NULL) {
        // Handle memory allocation failure
        free(heap);
        return NULL;
    }
    heap->size = 0;
    heap->capacity = capacity;
    return heap;
}

// Function to insert an element into the min-heap
void min_heap_insert(MinHeap* heap, double value) {
    if (heap->size == heap->capacity) {
        // Handle heap overflow
        return;
    }
    int i = heap->size++;
    while (i > 0 && heap->array[(i - 1) / 2] > value) {
        heap->array[i] = heap->array[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    heap->array[i] = value;
}

// Function to extract the minimum element from the min-heap
double min_heap_extract(MinHeap* heap) {
    if (heap->size == 0) {
        // Handle empty heap
        return -1.0; // Return a sentinel value indicating error
    }
    double root = heap->array[0];
    int i = 0;
    while (i * 2 + 1 < heap->size) {
        int left = i * 2 + 1;
        int right = i * 2 + 2;
        int smallest = left;
        if (right < heap->size && heap->array[right] < heap->array[left]) {
            smallest = right;
        }
        if (heap->array[smallest] >= heap->array[i]) {
            break;
        }
        double temp = heap->array[i];
        heap->array[i] = heap->array[smallest];
        heap->array[smallest] = temp;
        i = smallest;
    }
    heap->size--;
    return root;
}

// Function to process and analyze data
void process_and_analyze_data() {
    // Initialize data structures
    MinHeap* min_heap = create_min_heap(1000000);
    Event* event_list_head = NULL;

    // Read temperature readings from standard input
    double temperature;
    while (scanf("%lf", &temperature) == 1) {
        double timestamp = ((double)rand() / RAND_MAX) * time(NULL); // Generate random timestamp
        Event* new_event = create_event(timestamp, temperature, "Temperature Reading");
        if (new_event != NULL) {
            min_heap_insert(min_heap, temperature);
            if (event_list_head == NULL) {
                event_list_head = new_event;
            } else {
                Event* current = event_list_head;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = new_event;
            }
        }
    }

    // Periodically check and print the lowest temperature reading
    while (min_heap->size > 0) {
        double min_temperature = min_heap_extract(min_heap);
        Event* current = event_list_head;
        while (current != NULL && current->temperature != min_temperature) {
            current = current->next;
        }
        if (current != NULL) {
            printf("Lowest Temperature: %.2f at Timestamp: %.2f, Label: %s\n", min_temperature, current->timestamp, current->label);
        }
    }

    // Free all allocated memory
    Event* current = event_list_head;
    while (current != NULL) {
        Event* next = current->next;
        free(current);
        current = next;
    }
    free(min_heap->array);
    free(min_heap);
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    process_and_analyze_data();
    return 0;
}
