#include <pthread.h>

typedef struct {
    char *name;
    char *status;
    char **tags;
    int tag_count;
} Resource;

typedef struct {
    Resource **resources;
    int count;
    pthread_mutex_t lock;
} ResourceList;

ResourceList resource_list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int add_resource(const char *name, const char *status, const char **tags, int tag_count) {
    pthread_mutex_lock(&resource_list.lock);
    for (int i = 0; i < resource_list.count; i++) {
        if (strcmp(resource_list.resources[i]->name, name) == 0) {
            pthread_mutex_unlock(&resource_list.lock);
            return -1; // Resource already exists
        }
    }
    Resource *new_resource = malloc(sizeof(Resource));
    new_resource->name = strdup(name);
    new_resource->status = strdup(status);
    new_resource->tags = malloc(tag_count * sizeof(char *));
    for (int i = 0; i < tag_count; i++) {
        new_resource->tags[i] = strdup(tags[i]);
    }
    new_resource->tag_count = tag_count;
    resource_list.resources = realloc(resource_list.resources, (resource_list.count + 1) * sizeof(Resource *));
    resource_list.resources[resource_list.count++] = new_resource;
    pthread_mutex_unlock(&resource_list.lock);
    return 0; // Success
}

int update_resource(int id, const char *status, const char **tags, int tag_count) {
    pthread_mutex_lock(&resource_list.lock);
    if (id < 0 || id >= resource_list.count) {
        pthread_mutex_unlock(&resource_list.lock);
        return -1; // Invalid ID
    }
    Resource *resource = resource_list.resources[id];
    if (status != NULL) {
        free(resource->status);
        resource->status = strdup(status);
    }
    if (tags != NULL && tag_count > 0) {
        for (int i = 0; i < resource->tag_count; i++) {
            free(resource->tags[i]);
        }
        free(resource->tags);
        resource->tags = malloc(tag_count * sizeof(char *));
        for (int i = 0; i < tag_count; i++) {
            resource->tags[i] = strdup(tags[i]);
        }
        resource->tag_count = tag_count;
    }
    pthread_mutex_unlock(&resource_list.lock);
    return 0; // Success
}

Resource** get_resources_by_tag(const char *tag, int *count) {
    pthread_mutex_lock(&resource_list.lock);
    Resource **result = NULL;
    *count = 0;
    for (int i = 0; i < resource_list.count; i++) {
        for (int j = 0; j < resource_list.resources[i]->tag_count; j++) {
            if (strcmp(resource_list.resources[i]->tags[j], tag) == 0) {
                result = realloc(result, (*count + 1) * sizeof(Resource *));
                result[*count++] = resource_list.resources[i];
                break;
            }
        }
    }
    pthread_mutex_unlock(&resource_list.lock);
    return result; // Return the array of resources
}

void free_resources(Resource **resources, int count) {
    for (int i = 0; i < count; i++) {
        free(resources[i]->name);
        free(resources[i]->status);
        for (int j = 0; j < resources[i]->tag_count; j++) {
            free(resources[i]->tags[j]);
        }
        free(resources[i]->tags);
        free(resources[i]);
    }
    free(resources);
}
