#define MAX_BEARER_ID 1024

typedef struct {
    int MME_ID;
    int EPS_BEARER_ID;
    EVP_CIPHER_CTX *cipher_ctx;
} LTE_MME_CONFIG_T;

typedef struct {
    pthread_mutex_t lock;
    EVP_CIPHER_CTX **cache;
    size_t cache_size;
} CipherCache;

LTE_MME_CONFIG_T* initialize_lte_mme_config(int num_entries, CipherCache *cache) {
    LTE_MME_CONFIG_T *config = malloc(num_entries * sizeof(LTE_MME_CONFIG_T));
    if (!config) return NULL;

    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < num_entries; ++i) {
        int bearer_id;
        do {
            if (!RAND_bytes((unsigned char*)&bearer_id, sizeof(bearer_id))) {
                free(config);
                pthread_mutex_unlock(&cache->lock);
                return NULL;
            }
        } while (bearer_id >= MAX_BEARER_ID || cache->cache[bearer_id % cache->cache_size] != NULL);

        config[i].MME_ID = i + 1; // Example MME ID assignment
        config[i].EPS_BEARER_ID = bearer_id;
        config[i].cipher_ctx = EVP_CIPHER_CTX_new();
        if (!config[i].cipher_ctx) {
            free(config);
            pthread_mutex_unlock(&cache->lock);
            return NULL;
        }

        cache->cache[bearer_id % cache->cache_size] = config[i].cipher_ctx;
    }
    pthread_mutex_unlock(&cache->lock);

    return config;
}

void cleanup_lte_mme_config(LTE_MME_CONFIG_T *config, int num_entries, CipherCache *cache) {
    for (int i = 0; i < num_entries; ++i) {
        if (config[i].cipher_ctx) {
            EVP_CIPHER_CTX_free(config[i].cipher_ctx);
        }
    }
    free(config);

    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->cache_size; ++i) {
        if (cache->cache[i]) {
            EVP_CIPHER_CTX_free(cache->cache[i]);
            cache->cache[i] = NULL;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Additional functions and structures for KMS integration, error handling, logging, etc.
