        records[i].size = sizeof(int);
        offsets[i] = allocate_memory(records[i].size);
        keys[i] = i;
    }
}

void find_and_print_largest(int* array, size_t count) {
    int largest = array[0];
    for (size_t i = 1; i < count; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

void free_memory(record* records, long* offsets, int* keys, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(offsets[i]);
    }
    free(records);
    free(keys);
