#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR 0.75

typedef struct {
    char uuid[37]; // UUID string
    size_t file_size;
    time_t last_modified;
    void* cached_data;
} FileMetadata;

typedef struct HashTable {
    FileMetadata** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (FileMetadata**)calloc(INITIAL_CAPACITY, sizeof(FileMetadata*));
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resize_hash_table(HashTable* table) {
    size_t new_capacity = table->capacity * 2;
    FileMetadata** new_buckets = (FileMetadata**)calloc(new_capacity, sizeof(FileMetadata*));

    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->buckets[i] != NULL) {
            size_t index = hash_function(table->buckets[i]->uuid, new_capacity);
            while (new_buckets[index] != NULL) {
                index = (index + 1) % new_capacity;
            }
            new_buckets[index] = table->buckets[i];
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

size_t hash_function(const char* uuid, size_t capacity) {
    // Simple hash function for demonstration purposes
    return (uuid[0] + uuid[1]) % capacity;
}

FileMetadata* get_file_metadata(HashTable* table, const char* uuid) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(uuid, table->capacity);
    while (table->buckets[index] != NULL && strcmp(table->buckets[index]->uuid, uuid) != 0) {
        index = (index + 1) % table->capacity;
    }
    FileMetadata* metadata = table->buckets[index];
    pthread_mutex_unlock(&table->lock);
    return metadata;
}

void insert_file_metadata(HashTable* table, const char* uuid, size_t file_size, time_t last_modified, void* cached_data) {
    if (table->size >= table->capacity * LOAD_FACTOR) {
        resize_hash_table(table);
    }
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(uuid, table->capacity);
    while (table->buckets[index] != NULL) {
        index = (index + 1) % table->capacity;
    }
    FileMetadata* new_metadata = (FileMetadata*)malloc(sizeof(FileMetadata));
    strcpy(new_metadata->uuid, uuid);
    new_metadata->file_size = file_size;
    new_metadata->last_modified = last_modified;
    new_metadata->cached_data = cached_data;
    table->buckets[index] = new_metadata;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    HashTable* file_cache = create_hash_table();

    // Simulate reading from standard input
    char uuid[37];
    while (scanf("%s", uuid) != EOF) {
        FileMetadata* metadata = get_file_metadata(file_cache, uuid);
        if (metadata == NULL) {
            printf("File not found: %s\n", uuid);
        } else {
            printf("File found: %s, Size: %zu, Last Modified: %ld\n", metadata->uuid, metadata->file_size, metadata->last_modified);
        }
    }

    free_hash_table(file_cache);
    return 0;
}
```

This code provides a basic structure for the `optimized_file_io_and_cache_management` function. It includes a hash table implementation with dynamic resizing and thread safety using mutexes. The main function simulates reading file requests from standard input and demonstrates how to use the hash table to manage file metadata and cached data blocks. This is a simplified version of the task, and further optimizations and features can be added as needed.']

