#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    size_t size;
    long *offset;
} Record;

typedef struct rb_node {
    int key;
    struct rb_node *left, *right, *parent;
    int color; // 0 for red, 1 for black
} RBNode;

RBNode* create_rb_node(int key) {
    RBNode* node = (RBNode*)malloc(sizeof(RBNode));
    if (!node) return NULL;
    node->key = key;
    node->left = node->right = node->parent = NULL;
    node->color = 0; // Red
    return node;
}

void left_rotate(RBNode** root, RBNode* x) {
    RBNode* y = x->right;
    x->right = y->left;
    if (y->left != NULL)
        y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL)
        *root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void right_rotate(RBNode** root, RBNode* y) {
    RBNode* x = y->left;
    y->left = x->right;
    if (x->right != NULL)
        x->right->parent = y;
    x->parent = y->parent;
    if (y->parent == NULL)
        *root = x;
    else if (y == y->parent->right)
        y->parent->right = x;
    else
        y->parent->left = x;
    x->right = y;
    y->parent = x;
}

void rb_insert_fixup(RBNode** root, RBNode* z) {
    while (z->parent != NULL && z->parent->color == 0) {
        if (z->parent == z->parent->parent->left) {
            RBNode* y = z->parent->parent->right;
            if (y != NULL && y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(root, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                right_rotate(root, z->parent->parent);
            }
        } else {
            RBNode* y = z->parent->parent->left;
            if (y != NULL && y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(root, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                left_rotate(root, z->parent->parent);
            }
        }
    }
    (*root)->color = 1;
}

void rb_insert(RBNode** root, int key) {
    RBNode* z = create_rb_node(key);
    if (z == NULL) return;

    RBNode* y = NULL;
    RBNode* x = *root;

    while (x != NULL) {
        y = x;
        if (z->key < x->key)
            x = x->left;
        else
            x = x->right;
    }

    z->parent = y;
    if (y == NULL)
        *root = z;
    else if (z->key < y->key)
        y->left = z;
    else
        y->right = z;

    z->left = NULL;
    z->right = NULL;
    z->color = 0;

    rb_insert_fixup(root, z);
}

int find_max(int* arr, int n) {
    if (n <= 0) return -1; // Handle edge case
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

