struct record {
    int value;
    size_t size;
};

void* safe_malloc(size_t size) {
    void* ptr = std::aligned_alloc(alignof(record), size);
    if (!ptr) {
        throw std::bad_alloc();
    }
    return ptr;
}

void free_memory(void* ptr, size_t size) {
    std::free(ptr);
}

record* allocate_records(size_t count, int min_value, int max_value) {
    record* records = static_cast<record*>(safe_malloc(count * sizeof(record)));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].size = sizeof(int);
    }
    return records;
}

void insert_after(std::forward_list<std::string>& list, const std::string& target, const std::string& to_insert) {
    auto it = list.begin();
    while (it != list.end() && *it != target) {
        ++it;
    }
    if (it == list.end()) {
        list.push_back(to_insert);
    } else {
        list.insert_after(it, to_insert);
    }
}

void manage_memory_and_forward_list(size_t record_count, int min_value, int max_value,
                                   std::forward_list<std::string>& list, const std::string& target, const std::string& to_insert) {
    try {
        record* records = allocate_records(record_count, min_value, max_value);
        // Use records for some operations
        insert_after(list, target, to_insert);
        free_memory(records, record_count * sizeof(record));
    } catch (const std::bad_alloc& e) {
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
    }
}

int main() {
    srand(static_cast<unsigned int>(time(nullptr)));
    std::forward_list<std::string> list = {"apple", "banana", "cherry"};
    manage_memory_and_forward_list(5, 10, 20, list, "banana", "grape");
    for (const auto& item : list) {
        std::cout << item << " ";
    }
    return 0;
}
