    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * 1024L; // Example offset calculation
        keys[i] = i;
        records[i].value = i * 10;
        records[i].size = sizeof(record);
        records[i].timestamp = time(NULL);
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (records) {
        free(records);
    }
}

int main() {
    int num_records = 1000;
    record* records = create_records(num_records);

    if (records) {
        // Use the records array
        free_records(records, num_records);
    }

    return 0;
}
