#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_LEN 16

int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);
        freeaddrinfo(res); // Free the linked list
        return 0;
    }

    freeaddrinfo(res); // Free the linked list if no address found
    return -1;
}

int main() {
    char hostname[MAX_HOSTNAME_LEN];
    u_char ip_address[MAX_IP_LEN];

    printf("Enter a hostname: ");
    fgets(hostname, MAX_HOSTNAME_LEN, stdin);
    hostname[strcspn(hostname, "\n")] = 0; // Remove newline character

    if (resolve_hostname(hostname, ip_address) == 0) {
        printf("IP address for %s is %s\n", hostname, ip_address);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
