#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    size_t buffer_size;
} node;

typedef struct {
    char* description;
    size_t length_estimate;
    resource_pool* pool;
} data_buffer;

typedef struct {
    int task_id;
    int source_id;
    int priority;
    time_t timestamp;
    data_buffer* buffer;
} task;

typedef struct {
    task** tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} task_queue;

task_queue* create_task_queue(size_t initial_capacity) {
    task_queue* queue = (task_queue*)malloc(sizeof(task_queue));
    if (!queue) return NULL;

    queue->tasks = (task**)malloc(initial_capacity * sizeof(task*));
    if (!queue->tasks) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void enqueue_task(task_queue* queue, task* new_task) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        task** new_tasks = (task**)realloc(queue->tasks, new_capacity * sizeof(task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&queue->lock);
            return; // Handle allocation failure
        }
        queue->tasks = new_tasks;
        queue->capacity = new_capacity;
    }
    queue->tasks[queue->size++] = new_task;
    pthread_mutex_unlock(&queue->lock);
}

void free_task_queue(task_queue* queue) {
    for (size_t i = 0; i < queue->size; ++i) {
        free(queue->tasks[i]);
    }
    free(queue->tasks);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int main() {
    srand(time(NULL));

    task_queue* queue = create_task_queue(1024);
    if (!queue) return 1;

    for (size_t i = 0; i < 1000; ++i) {
        node* data_node = (node*)malloc(sizeof(node));
        if (!data_node) continue; // Handle allocation failure

        data_node->value = ((double)rand() / RAND_MAX) * 100.0;
        data_node->buffer_size = rand() % 1024 + 1;

        task* new_task = (task*)malloc(sizeof(task));
        if (!new_task) {
            free(data_node);
            continue; // Handle allocation failure
        }

        new_task->task_id = i;
        new_task->source_id = rand() % 10;
        new_task->priority = rand() % 5 + 1;
        new_task->timestamp = time(NULL);
        new_task->buffer = (data_buffer*)malloc(sizeof(data_buffer));
        if (!new_task->buffer) {
            free(new_task);
            free(data_node);
            continue; // Handle allocation failure
        }

        new_task->buffer->description = "Sample Data";
        new_task->buffer->length_estimate = data_node->buffer_size;
        new_task->buffer->pool = (resource_pool*)malloc(sizeof(resource_pool));
        if (!new_task->buffer->pool) {
            free(new_task->buffer);
            free(new_task);
            free(data_node);
            continue; // Handle allocation failure
        }

        enqueue_task(queue, new_task);
    }

    free_task_queue(queue);

    return 0;
}
