    if (logs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_USERS; i++) {
        logs[i] = (UserLog*)malloc(sizeof(UserLog));
        if (logs[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for user %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(logs[j]);
            }
            free(logs);
            return NULL;
        }

        logs[i]->timestamp = time(NULL);
        logs[i]->session_id = (char*)malloc(10 * sizeof(char));
        if (logs[i]->session_id == NULL) {
            fprintf(stderr, "Memory allocation failed for session ID of user %d\n", i);
            // Free previously allocated memory
            free(logs[i]);
            for (int j = 0; j < i; j++) {
                free(logs[j]->session_id);
                free(logs[j]);
            }
            free(logs);
            return NULL;
        }

        snprintf(logs[i]->session_id, 10, "user%d", i);
        logs[i]->activity_count = rand() % 100; // Random activity count between 0 and 99
    }

    return logs;
}

void free_logs(UserLog** logs) {
    for (int i = 0; i < MAX_USERS; i++) {
        if (logs[i] != NULL) {
            free(logs[i]->session_id);
            free(logs[i]);
        }
    }
    free(logs);
}
