// Define hash table entry structure
typedef struct {
    int key;
    void* record;
} HashTableEntry;

// Define custom hash table structure
typedef struct {
    HashTableEntry** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CustomHashTable;

// Function to initialize the custom hash table
void init_custom_hash_table(CustomHashTable* table, size_t initial_capacity) {
    table->entries = (HashTableEntry**)malloc(initial_capacity * sizeof(HashTableEntry*));
    for (size_t i = 0; i < initial_capacity; ++i) {
        table->entries[i] = NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
}

// Function to insert a key-value pair into the hash table
void insert_into_hash_table(CustomHashTable* table, int key, void* record) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;
    while (table->entries[index] != NULL && table->entries[index]->key != key) {
        index = (index + 1) % table->capacity;
    }
    if (table->entries[index] == NULL) {
        table->entries[index] = (HashTableEntry*)malloc(sizeof(HashTableEntry));
        table->entries[index]->key = key;
        table->entries[index]->record = record;
        ++table->size;
    } else {
        // Handle collision, e.g., replace the existing record
        free(table->entries[index]->record);
        table->entries[index]->record = record;
    }
    pthread_mutex_unlock(&table->lock);
}

// Function to retrieve a value from the hash table by key
void* get_from_hash_table(CustomHashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;
    while (table->entries[index] != NULL && table->entries[index]->key != key) {
        index = (index + 1) % table->capacity;
    }
    void* record = (table->entries[index] != NULL) ? table->entries[index]->record : NULL;
    pthread_mutex_unlock(&table->lock);
    return record;
}

// Function to resize the hash table
void resize_hash_table(CustomHashTable* table, size_t new_capacity) {
    HashTableEntry** old_entries = table->entries;
    size_t old_capacity = table->capacity;
    table->entries = (HashTableEntry**)malloc(new_capacity * sizeof(HashTableEntry*));
    for (size_t i = 0; i < new_capacity; ++i) {
        table->entries[i] = NULL;
    }
    table->capacity = new_capacity;
    table->size = 0;

    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < old_capacity; ++i) {
        if (old_entries[i] != NULL) {
            insert_into_hash_table(table, old_entries[i]->key, old_entries[i]->record);
            free(old_entries[i]);
        }
    }
    pthread_mutex_unlock(&table->lock);

    free(old_entries);
}

// Function to dynamically manage storage
void dynamic_storage_manager() {
    CustomHashTable file_table;
    init_custom_hash_table(&file_table, 1024); // Initial capacity

    FileDescriptor* fd = (FileDescriptor*)malloc(sizeof(FileDescriptor));
    fd->id = 1;
    fd->fp = fopen("example.txt", "w");
    fd->ref_count = 1;

    insert_into_hash_table(&file_table, fd->id, fd);

    // Example of resizing the hash table
    if (file_table.size > file_table.capacity * 0.75) {
        resize_hash_table(&file_table, file_table.capacity * 2);
    }

    // Clean up
    pthread_mutex_destroy(&file_table.lock);
    free(file_table.entries);
    fclose(fd->fp);
    free(fd);
}

int main() {
    dynamic_storage_manager();
    return 0;
}
```

