# Python module for interfacing with a financial API

import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

def fetch_exchange_rates(currencies):
    api_url = "https://api.example.com/exchange_rates"
    headers = {
        "Authorization": "Bearer YOUR_API_KEY",
        "Content-Type": "application/json"
    }

    def fetch_rate(currency):
        response = requests.get(f"{api_url}/{currency}", headers=headers)
        if response.status_code == 200:
            return {currency: response.json()['rate']}
        else:
            return {currency: None}

    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = [executor.submit(fetch_rate, currency) for currency in currencies]
        results = {}
        for future in as_completed(futures):
            try:
                result = future.result()
                if result is not None:
                    results.update(result)
            except Exception as e:
                print(f"Error fetching exchange rate: {e}")

    return results
