#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char* sessionId;
    time_t expirationTime;
    time_t lastAccessed;
    char* metadata;
} Session;

typedef struct {
    Session** sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* createSessionManager(size_t initialCapacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = (Session**)calloc(initialCapacity, sizeof(Session*));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialCapacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroySessionManager(SessionManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->sessions[i]->sessionId);
        free(manager->sessions[i]->metadata);
        free(manager->sessions[i]);
    }
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void addSession(SessionManager* manager, const char* sessionId, time_t expirationTime, const char* metadata) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size == manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        Session** newSessions = (Session**)realloc(manager->sessions, newCapacity * sizeof(Session*));
        if (!newSessions) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }

    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    session->sessionId = strdup(sessionId);
    session->expirationTime = expirationTime;
    session->lastAccessed = time(NULL);
    session->metadata = strdup(metadata);

    manager->sessions[manager->size++] = session;

    pthread_mutex_unlock(&manager->lock);
}

void removeSession(SessionManager* manager, const char* sessionId) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->sessions[i]->sessionId, sessionId) == 0) {
            free(manager->sessions[i]->sessionId);
            free(manager->sessions[i]->metadata);
            free(manager->sessions[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->sessions[j] = manager->sessions[j + 1];
            }
            --manager->size;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void updateSession(SessionManager* manager, const char* sessionId, time_t expirationTime, const char* metadata) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->sessions[i]->sessionId, sessionId) == 0) {
            free(manager->sessions[i]->metadata);
            manager->sessions[i]->expirationTime = expirationTime;
            manager->sessions[i]->lastAccessed = time(NULL);
            manager->sessions[i]->metadata = strdup(metadata);
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int isSessionActive(SessionManager* manager, const char* sessionId) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->sessions[i]->sessionId, sessionId) == 0 && time(NULL) < manager->sessions[i]->expirationTime) {
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void serializeSessions(SessionManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < manager->size; ++i) {
        size_t sessionIdLength = strlen(manager->sessions[i]->sessionId);
        size_t metadataLength = strlen(manager->sessions[i]->metadata);
        fwrite(&sessionIdLength, sizeof(size_t), 1, file);
        fwrite(manager->sessions[i]->sessionId, sizeof(char), sessionIdLength, file);
        fwrite(&manager->sessions[i]->expirationTime, sizeof(time_t), 1, file);
        fwrite(&manager->sessions[i]->lastAccessed, sizeof(time_t), 1, file);
        fwrite(&metadataLength, sizeof(size_t), 1, file);
        fwrite(manager->sessions[i]->metadata, sizeof(char), metadataLength, file);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}

void deserializeSessions(SessionManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    size_t size;
    fread(&size, sizeof(size_t), 1, file);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < size; ++i) {
        size_t sessionIdLength;
        fread(&sessionIdLength, sizeof(size_t), 1, file);
        char* sessionId = (char*)malloc(sessionIdLength + 1);
        fread(sessionId, sizeof(char), sessionIdLength, file);
        sessionId[sessionIdLength] = '\0';

        time_t expirationTime;
        fread(&expirationTime, sizeof(time_t), 1, file);

        time_t lastAccessed;
        fread(&lastAccessed, sizeof(time_t), 1, file);

        size_t metadataLength;
        fread(&metadataLength, sizeof(size_t), 1, file);
        char* metadata = (char*)malloc(metadataLength + 1);
        fread(metadata, sizeof(char), metadataLength, file);
        metadata[metadataLength] = '\0';

        addSession(manager, sessionId, expirationTime, metadata);

        free(sessionId);
        free(metadata);
    }

    pthread_mutex_unlock(&manager->lock);

    fclose(file);
}
