    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->value = strdup(value);
    return new_node;
}

Transaction* create_transaction(Node* node, int min_interval, int max_interval) {
    Transaction* new_transaction = (Transaction*)malloc(sizeof(Transaction));
    if (new_transaction == NULL) {
        fprintf(stderr, "Memory allocation failed for transaction\n");
        exit(EXIT_FAILURE);
    }
    new_transaction->node = node;
    time_t current_time = time(NULL);
    int random_interval = min_interval + rand() % (max_interval - min_interval + 1);
    new_transaction->timestamp = current_time - random_interval;
    return new_transaction;
}

void free_node(Node* node) {
    if (node != NULL) {
        free(node->value);
        free(node);
    }
}

void free_transaction(Transaction* transaction) {
    if (transaction != NULL) {
        free_node(transaction->node);
        free(transaction);
    }
}

int main() {
    srand(time(NULL));

    Node* node1 = create_node(1, "Value1");
    Transaction* transaction1 = create_transaction(node1, 60, 300);

    printf("Node Key: %d\n", transaction1->node->key);
    printf("Transaction Timestamp: %ld\n", transaction1->timestamp);

    free_transaction(transaction1);
    free_node(node1);

    return 0;
}
