int allocate_memory(long *offsets, int *keys, record **records, size_t size, size_t max_size) {
    if (size > max_size / sizeof(record)) {
        return -1; // Exceeds maximum memory limit
    }

    offsets = malloc(size * sizeof(long));
    keys = malloc(size * sizeof(int));
    records = malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % 1000000L; // Random offset value
        keys[i] = rand() % 1000; // Random key value
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].metadata = 'A'; // Static default metadata
    }

    return 0; // Success
}

int update_data(record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        records[i].offset += rand() % 100L; // Update offset randomly
        records[i].key += rand() % 10; // Update key randomly
    }
    return 0; // Success
}

