    if (!new_item->identifier) {
        free(new_item);
        return NULL; // Memory allocation for identifier failed
    }

    new_item->buffer = (char*)calloc(DEFAULT_BUFFER_SIZE, sizeof(char));
    if (!new_item->buffer) {
        free(new_item->identifier);
        free(new_item);
        return NULL; // Memory allocation for buffer failed
    }

    new_item->priority = priority;
    return new_item;
}

void destroy_item(item* item) {
