        fprintf(stderr, "Failed to initialize items\n");
        for (size_t i = 0; i < item_count; ++i) {
            destroy_item(items[i]);
        }
        return EXIT_FAILURE;
    }

    // Use the items...

    for (size_t i = 0; i < item_count; ++i) {
        destroy_item(items[i]);
    }

    return EXIT_SUCCESS;
