#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_NODES 1000
#define MAX_VALUE_SIZE 256
#define MIN_INTERVAL 10
#define MAX_INTERVAL 60

typedef struct {
    int key;
    char *value;
} node;

typedef struct {
    node *node_ptr;
    time_t timestamp;
    int status;
} transaction;

void* handleNodesAndTransactions(int num_nodes, int max_value_size, int min_interval, int max_interval) {
    node **nodes = (node **)malloc(num_nodes * sizeof(node *));
    if (!nodes) {
        perror("Failed to allocate memory for nodes");
        return NULL;
    }

    transaction *transactions = (transaction *)malloc(num_nodes * sizeof(transaction));
    if (!transactions) {
        perror("Failed to allocate memory for transactions");
        free(nodes);
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = (node *)malloc(sizeof(node));
        if (!nodes[i]) {
            perror("Failed to allocate memory for node");
            for (int j = 0; j < i; j++) {
                free(nodes[j]);
            }
            free(nodes);
            free(transactions);
            return NULL;
        }

        nodes[i]->key = i;
        nodes[i]->value = (char *)malloc(max_value_size * sizeof(char));
        if (!nodes[i]->value) {
            perror("Failed to allocate memory for node value");
            for (int j = 0; j <= i; j++) {
                free(nodes[j]);
            }
            free(nodes);
            free(transactions);
            return NULL;
        }

        snprintf(nodes[i]->value, max_value_size, "Value%d", i);

        pthread_mutex_lock(&lock);
        transactions[i].node_ptr = nodes[i];
        transactions[i].timestamp = time(NULL) - (rand() % (max_interval - min_interval + 1)) - min_interval;
        transactions[i].status = rand() % 2; // Randomly set status
        pthread_mutex_unlock(&lock);
    }

    return transactions;
}
