#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Product {
    int id;
    double price;
    char* description;
    struct Transaction* transactions;
} Product;

typedef struct Transaction {
    time_t timestamp;
    struct Product* product;
    struct Transaction* next;
} Transaction;

Product* create_product(int id, double price, const char* description) {
    Product* new_product = (Product*)malloc(sizeof(Product));
    if (!new_product) return NULL;

    new_product->id = id;
    new_product->price = price;
    new_product->description = strdup(description);
    new_product->transactions = NULL;

    return new_product;
}

void add_transaction(Product* product, time_t timestamp) {
    Transaction* new_transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!new_transaction) return;

    new_transaction->timestamp = timestamp;
    new_transaction->product = product;
    new_transaction->next = product->transactions;
    product->transactions = new_transaction;
}

void update_product_price(Product* product, double new_price) {
    product->price = new_price;
}

void free_product(Product* product) {
    if (product->description) free(product->description);
    Transaction* current = product->transactions;
    while (current) {
        Transaction* next = current->next;
        free(current);
        current = next;
    }
    free(product);
}

int main() {
    Product* my_product = create_product(1, 9.99, "Example Product");
    if (!my_product) {
        fprintf(stderr, "Failed to allocate memory for product.\n");
        return 1;
    }

    time_t now = time(NULL);
    add_transaction(my_product, now);

    update_product_price(my_product, 12.99);

    free_product(my_product);

    return 0;
}
