#include <string.h>

#define MAX_RECORDS 10000

typedef struct record {
    int key;
    char *identifier;
    struct record *next;
} Record;

Record* create_record(int key, const char *identifier) {
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for new record.\n");
        return NULL;
    }
    new_record->key = key;
    new_record->identifier = NULL;
    new_record->next = NULL;

    if (identifier) {
        new_record->identifier = strdup(identifier);
        if (!new_record->identifier) {
            fprintf(stderr, "Memory allocation failed for identifier.\n");
            free(new_record);
            return NULL;
        }
    }

    return new_record;
}

void destroy_record(Record *record) {
    if (record->identifier) {
        free(record->identifier);
    }
    free(record);
}

void add_record_to_list(Record **head, Record *new_record) {
    if (*head == NULL) {
        *head = new_record;
    } else {
        Record *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
}

void traverse_list(Record *head, void (*operation)(Record *)) {
    Record *current = head;
    while (current != NULL) {
        operation(current);
        current = current->next;
    }
}

void print_record(Record *record) {
    printf("Key: %d, Identifier: %s\n", record->key, record->identifier ? record->identifier : "NULL");
}

int main() {
    Record *records[MAX_RECORDS] = { NULL };
    int num_records = 0;

    // Example usage
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = create_record(i, "Record");
        if (!records[i]) {
            break;
        }
        add_record_to_list(&records[0], records[i]);
        num_records++;
    }

    traverse_list(records[0], print_record);

    // Clean up
    for (int i = 0; i < num_records; ++i) {
        destroy_record(records[i]);
    }

    return 0;
}
