Item items[MAX_ITEMS];
int item_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *message) {
    // Implement error logging to a file
}

void log_warning(const char *message) {
    // Implement warning logging to a file
}

void initialize_item(Item *item, const char *id, int priority) {
    item->id = strdup(id);
    item->data = (char *)malloc(1); // Allocate 1 byte for null terminator
    item->data[0] = '\0';
    item->priority = priority;
}

void free_item(Item *item) {
    free(item->id);
    free(item->data);
}

int add_item(const char *id, int priority) {
    pthread_mutex_lock(&mutex);
    if (item_count >= MAX_ITEMS) {
        log_error("Maximum number of items reached");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    initialize_item(&items[item_count], id, priority);
    item_count++;
    pthread_mutex_unlock(&mutex);
    return 0;
}

int update_item(const char *id, int new_priority) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < item_count; i++) {
        if (strcmp(items[i].id, id) == 0) {
            items[i].priority = new_priority;
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }
    log_error("Item not found");
    pthread_mutex_unlock(&mutex);
    return -1;
}

char *get_item_data(const char *id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < item_count; i++) {
        if (strcmp(items[i].id, id) == 0) {
            pthread_mutex_unlock(&mutex);
            return items[i].data;
        }
    }
    log_error("Item not found");
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void remove_item(const char *id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < item_count; i++) {
        if (strcmp(items[i].id, id) == 0) {
            free_item(&items[i]);
            for (int j = i; j < item_count - 1; j++) {
                items[j] = items[j + 1];
            }
            item_count--;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    log_error("Item not found");
    pthread_mutex_unlock(&mutex);
}

void *populate_data(void *arg) {
    int seed = *(int *)arg;
    srand(seed);
    for (int i = 0; i < item_count; i++) {
        int length = rand() % 100 + 1; // Random string length between 1 and 100
        items[i].data = realloc(items[i].data, length + 1); // Resize buffer
        for (int j = 0; j < length; j++) {
            items[i].data[j] = 'a' + rand() % 26; // Random lowercase letter
        }
        items[i].data[length] = '\0';
    }
    return NULL;
}

