        free(new_item->identifier);
        free(new_item);
        return NULL;
    }
    memset(new_item->data, 0, DEFAULT_BUFFER_SIZE);

    new_item->priority = priority;

    return new_item;
}

void populate_data(item* item, void (*generator)(char*, int)) {
    generator(item->data, DEFAULT_BUFFER_SIZE);
}

void free_item(item* item) {
    if (item) {
        free(item->identifier);
        free(item->data);
        free(item);
    }
}

int main() {
    srand(time(NULL));

    item* my_item = create_item("example", 5);
    if (my_item) {
