#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t mutex;
} CipherObject;

CipherObject* create_cipher_object(const char *algorithm) {
    CipherObject *cipher = (CipherObject*)malloc(sizeof(CipherObject));
    if (!cipher) return NULL;

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        free(cipher);
        return NULL;
    }

    pthread_mutex_init(&cipher->mutex, NULL);

    // Initialize OpenSSL library and set error handling
    ERR_load_crypto_strings();

    return cipher;
}

void destroy_cipher_object(CipherObject *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        pthread_mutex_destroy(&cipher->mutex);
        free(cipher);
    }
}

int encrypt_data(CipherObject *cipher, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len, const unsigned char *key,
                 const unsigned char *iv) {
    pthread_mutex_lock(&cipher->mutex);

    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        pthread_mutex_unlock(&cipher->mutex);
        return -1;
    }

    if (EVP_EncryptUpdate(cipher->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len) != 1) {
        pthread_mutex_unlock(&cipher->mutex);
        return -1;
    }

    if (EVP_EncryptFinal_ex(cipher->ctx, ciphertext + *ciphertext_len, &len) != 1) {
        pthread_mutex_unlock(&cipher->mutex);
        return -1;
    }
    *ciphertext_len += len;

    pthread_mutex_unlock(&cipher->mutex);
    return 0;
}

int decrypt_data(CipherObject *cipher, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len, const unsigned char *key,
                 const unsigned char *iv) {
    pthread_mutex_lock(&cipher->mutex);

    if (EVP_DecryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        pthread_mutex_unlock(&cipher->mutex);
        return -1;
    }

    if (EVP_DecryptUpdate(cipher->ctx, plaintext, plaintext_len, ciphertext, ciphertext_len) != 1) {
        pthread_mutex_unlock(&cipher->mutex);
        return -1;
    }

    if (EVP_DecryptFinal_ex(cipher->ctx, plaintext + *plaintext_len, &len) != 1) {
        pthread_mutex_unlock(&cipher->mutex);
        return -1;
    }
    *plaintext_len += len;

    pthread_mutex_unlock(&cipher->mutex);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <algorithm> <key> <iv>\n", argv[0]);
        return 1;
    }

    const char *algorithm = argv[1];
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];

    // Parse key and IV from command line arguments
    // ...

    CipherObject *cipher = create_cipher_object(algorithm);
    if (!cipher) {
        fprintf(stderr, "Failed to create cipher object\n");
        return 1;
    }

    unsigned char plaintext[] = "Hello, OpenSSL!";
    int plaintext_len = strlen((char*)plaintext);
    unsigned char ciphertext[plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_cbc())];
    int ciphertext_len;

    if (encrypt_data(cipher, plaintext, plaintext_len, ciphertext, &ciphertext_len, key, iv) != 0) {
        fprintf(stderr, "Encryption failed\n");
        destroy_cipher_object(cipher);
        return 1;
    }

    unsigned char decryptedtext[plaintext_len];
    int decryptedtext_len;

    if (decrypt_data(cipher, ciphertext, ciphertext_len, decryptedtext, &decryptedtext_len, key, iv) != 0) {
        fprintf(stderr, "Decryption failed\n");
        destroy_cipher_object(cipher);
        return 1;
    }

    decryptedtext[decryptedtext_len] = '\0';
    printf("Decrypted text: %s\n", decryptedtext);

    destroy_cipher_object(cipher);
    return 0;
}
