#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t mutex;
} CipherState;

void handle_errors() {
    ERR_print_errors_fp(stderr);
    abort();
}

CipherState* create_cipher_state(const char *algorithm) {
    CipherState *state = malloc(sizeof(CipherState));
    if (!state) {
        handle_errors();
    }
    state->ctx = EVP_CIPHER_CTX_new();
    if (!state->ctx) {
        free(state);
        handle_errors();
    }
    pthread_mutex_init(&state->mutex, NULL);
    return state;
}

void destroy_cipher_state(CipherState *state) {
    pthread_mutex_lock(&state->mutex);
    EVP_CIPHER_CTX_free(state->ctx);
    pthread_mutex_unlock(&state->mutex);
    pthread_mutex_destroy(&state->mutex);
    free(state);
}

int encrypt_data(const CipherState *state, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext) {
    pthread_mutex_lock(&state->mutex);
    int len;
    if (1 != EVP_EncryptUpdate(state->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        handle_errors();
    }
    int ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(state->ctx, ciphertext + len, &len)) {
        handle_errors();
    }
    ciphertext_len += len;
    pthread_mutex_unlock(&state->mutex);
    return ciphertext_len;
}

int decrypt_data(const CipherState *state, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext) {
    pthread_mutex_lock(&state->mutex);
    int len;
    if (1 != EVP_DecryptUpdate(state->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        handle_errors();
    }
    int plaintext_len = len;
    if (1 != EVP_DecryptFinal_ex(state->ctx, plaintext + len, &len)) {
        handle_errors();
    }
    plaintext_len += len;
    pthread_mutex_unlock(&state->mutex);
    return plaintext_len;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <algorithm> <input_file>\n", argv[0]);
        return 1;
    }

    const char *algorithm = argv[1];
    FILE *input_file = fopen(argv[2], "rb");
    if (!input_file) {
        perror("Failed to open input file");
        return 1;
    }

    CipherState *state = create_cipher_state(algorithm);
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    // Initialize key and IV securely using KMS
    // ...

    EVP_CIPHER_CTX_init(state->ctx);
    if (1 != EVP_EncryptInit_ex(state->ctx, EVP_get_cipherbyname(algorithm), NULL, key, iv)) {
        handle_errors();
    }

    unsigned char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), input_file)) > 0) {
        int ciphertext_len = encrypt_data(state, buffer, bytes_read, buffer);
        fwrite(buffer, 1, ciphertext_len, stdout);
    }

    fclose(input_file);
    destroy_cipher_state(state);

    return 0;
}
