#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    size_t size;
    time_t last_access;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dataManager;

dataManager* createDataManager(size_t initialCapacity) {
    dataManager* dm = (dataManager*)malloc(sizeof(dataManager));
    if (!dm) return NULL;

    dm->offsets = (long*)calloc(initialCapacity, sizeof(long));
    dm->keys = (int*)calloc(initialCapacity, sizeof(int));
    dm->records = (record**)calloc(initialCapacity, sizeof(record*));
    dm->capacity = initialCapacity;
    dm->size = 0;
    pthread_mutex_init(&dm->mutex, NULL);

    if (!dm->offsets || !dm->keys || !dm->records) {
        free(dm->offsets);
        free(dm->keys);
        free(dm->records);
        free(dm);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < initialCapacity; ++i) {
        dm->records[i] = (record*)malloc(sizeof(record));
        if (!dm->records[i]) {
            for (size_t j = 0; j < i; ++j) free(dm->records[j]);
            free(dm->offsets);
            free(dm->keys);
            free(dm->records);
            pthread_mutex_destroy(&dm->mutex);
            free(dm);
            return NULL;
        }
        dm->records[i]->value = rand() % 1000;
        dm->records[i]->size = rand() % 1024 + 1;
        dm->records[i]->last_access = time(NULL);
    }

    return dm;
}

void destroyDataManager(dataManager* dm) {
    for (size_t i = 0; i < dm->size; ++i) free(dm->records[i]);
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_destroy(&dm->mutex);
    free(dm);
}

void resizeDataManager(dataManager* dm, size_t newCapacity) {
    pthread_mutex_lock(&dm->mutex);

    long* newOffsets = (long*)realloc(dm->offsets, newCapacity * sizeof(long));
    int* newKeys = (int*)realloc(dm->keys, newCapacity * sizeof(int));
    record** newRecords = (record**)realloc(dm->records, newCapacity * sizeof(record*));

    if (!newOffsets || !newKeys || !newRecords) {
        free(newOffsets);
        free(newKeys);
        free(newRecords);
        pthread_mutex_unlock(&dm->mutex);
        return;
    }

    dm->offsets = newOffsets;
    dm->keys = newKeys;
    dm->records = newRecords;

    for (size_t i = dm->size; i < newCapacity; ++i) {
        dm->records[i] = (record*)malloc(sizeof(record));
        if (!dm->records[i]) {
            for (size_t j = dm->size; j <= i; ++j) free(dm->records[j]);
            pthread_mutex_unlock(&dm->mutex);
            return;
        }
        dm->records[i]->value = rand() % 1000;
        dm->records[i]->size = rand() % 1024 + 1;
        dm->records[i]->last_access = time(NULL);
    }

    dm->capacity = newCapacity;

    pthread_mutex_unlock(&dm->mutex);
}

void compactDataManager(dataManager* dm, double inactiveThreshold) {
    pthread_mutex_lock(&dm->mutex);

    size_t activeCount = 0;
    for (size_t i = 0; i < dm->size; ++i) {
        if (difftime(time(NULL), dm->records[i]->last_access) > inactiveThreshold * 3600) continue;
        dm->offsets[activeCount] = dm->offsets[i];
        dm->keys[activeCount] = dm->keys[i];
        dm->records[activeCount++] = dm->records[i];
    }

    for (size_t i = activeCount; i < dm->size; ++i) free(dm->records[i]);
    dm->size = activeCount;

    pthread_mutex_unlock(&dm->mutex);
}

void updateDataManager(dataManager* dm, int key, long offset, record newRecord) {
    pthread_mutex_lock(&dm->mutex);

    for (size_t i = 0; i < dm->size; ++i) {
        if (dm->keys[i] == key) {
            dm->offsets[i] = offset;
            dm->records[i]->value = newRecord.value;
            dm->records[i]->size = newRecord.size;
            dm->records[i]->last_access = time(NULL);
            pthread_mutex_unlock(&dm->mutex);
            return;
        }
    }

    if (dm->size == dm->capacity) resizeDataManager(dm, dm->capacity * 2);

    dm->offsets[dm->size] = offset;
    dm->keys[dm->size] = key;
    dm->records[dm->size++] = (record*)malloc(sizeof(record));
    dm->records[dm->size - 1]->value = newRecord.value;
    dm->records[dm->size - 1]->size = newRecord.size;
    dm->records[dm->size - 1]->last_access = time(NULL);

    pthread_mutex_unlock(&dm->mutex);
}

void logDataManager(dataManager* dm, const char* message) {
    // Implement logging mechanism here
}
