typedef struct {
    int timestamp;
    int status_code;
    size_t payload_size;
} data_entry;

typedef struct {
    data_entry* entry;
    int processed;
} event_record;

event_record* create_event_records(int num_entries, int** timestamps, int** status_codes, size_t** payload_sizes) {
    if (num_entries <= 0 || !timestamps || !status_codes || !payload_sizes) {
        return NULL;
    }

    event_record* records = (event_record*)malloc(num_entries * sizeof(event_record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        records[i].entry = (data_entry*)malloc(sizeof(data_entry));
        if (!records[i].entry) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(records[j].entry);
            }
            free(records);
            return NULL;
        }

        records[i].entry->timestamp = (*timestamps)[i];
        records[i].entry->status_code = (*status_codes)[i];
        records[i].entry->payload_size = (*payload_sizes)[i];
        records[i].processed = 0; // Initialize processed flag
    }

    return records;
}

void free_event_records(event_record* records, int num_entries) {
    if (records && num_entries > 0) {
        for (int i = 0; i < num_entries; ++i) {
            free(records[i].entry);
        }
        free(records);
    }
}

// Example usage
int main() {
    int timestamps[] = {1, 2, 3};
    int status_codes[] = {200, 404, 500};
    size_t payload_sizes[] = {1024, 2048, 4096};

    int num_entries = sizeof(timestamps) / sizeof(timestamps[0]);
    event_record* records = create_event_records(num_entries, &timestamps, &status_codes, &payload_sizes);

    if (records) {
        // Process events
        for (int i = 0; i < num_entries; ++i) {
            printf("Event %d: Timestamp=%d, Status Code=%d, Payload Size=%zu\n",
                   i, records[i].entry->timestamp, records[i].entry->status_code, records[i].entry->payload_size);
        }

        free_event_records(records, num_entries);
    } else {
        fprintf(stderr, "Failed to create event records.\n");
    }

    return 0;
}
