    dm->offsets = new_offsets;
    dm->keys = new_keys;
    dm->records = new_records;
    dm->capacity = new_capacity;

    for (size_t i = dm->size; i < new_capacity; ++i) {
        dm->records[i] = (record*)malloc(sizeof(record));
        if (!dm->records[i]) {
            // Handle memory allocation failure
            return;
        }
        dm->records[i]->value = rand() % 1000;
        dm->records[i]->size = rand() % 1024 + 1;
        dm->records[i]->last_access = time(NULL);
    }

    dm->size = new_capacity;
}

void dataManager_compact(dataManager *dm, double inactive_threshold) {
    if (!dm || inactive_threshold <= 0.0 || inactive_threshold >= 1.0) return;

