#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define RANDOM_RANGE 1000

typedef struct {
    int key;
    long offset;
    int random_value;
    int initialized;
} Record;

void* initialize_records(void* arg) {
    FILE* file = (FILE*)arg;
    Record records[MAX_RECORDS];
    int keys[MAX_RECORDS], offsets[MAX_RECORDS];
    int num_records, i, j;
    int random_values[RANDOM_RANGE + 1];

    // Initialize semaphores
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (fscanf(file, "%d", &num_records) != 1 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Error reading number of records\n");
        return NULL;
    }

    for (i = 0; i < num_records; i++) {
        if (fscanf(file, "%d,%ld", &keys[i], &offsets[i]) != 2) {
            fprintf(stderr, "Error reading key and offset for record %d\n", i);
            return NULL;
        }
    }

    // Initialize random values
    for (i = 0; i <= RANDOM_RANGE; i++) {
        random_values[i] = i;
    }

    // Shuffle random values
    for (i = RANDOM_RANGE; i > 0; i--) {
        j = rand() % (i + 1);
        int temp = random_values[i];
        random_values[i] = random_values[j];
        random_values[j] = temp;
    }

    // Initialize records
    for (i = 0; i < num_records; i++) {
        pthread_mutex_lock(&mutex);
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].random_value = random_values[i % (RANDOM_RANGE + 1)];
        records[i].initialized = 1;
        pthread_mutex_unlock(&mutex);
    }

    // Clean up semaphores
    pthread_mutex_destroy(&mutex);

    return NULL;
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening input file\n");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_records, file) != 0) {
        fprintf(stderr, "Error creating thread\n");
        fclose(file);
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Error joining thread\n");
        fclose(file);
        return 1;
    }

    fclose(file);
    return 0;
}
