    if (!array) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        return NULL;
    }
    return array;
}

int* allocate_int_array(int size) {
    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for int array\n");
        return NULL;
    }
    return array;
}

record* allocate_record_array(int size) {
    record* array = (record*)malloc(size * sizeof(record));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        return NULL;
    }
    return array;
}

void initialize_records(record* records, int size, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].buffer = (char*)malloc(BUFFER_SIZE * sizeof(char));
        if (!records[i].buffer) {
            fprintf(stderr, "Memory allocation failed for buffer in record %d\n", i);
            continue;
        }
        for (int j = 0; j < BUFFER_SIZE - 1; j++) {
            records[i].buffer[j] = 'A' + rand() % 62; // Alphanumeric characters
        }
        records[i].buffer[BUFFER_SIZE - 1] = '\0';
    }
}

void free_records(record* records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i].buffer) {
            free(records[i].buffer);
        }
    }
    free(records);
}

