#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* buffer;
} Record;

typedef struct {
    unsigned seed;
} RandomGenerator;

RandomGenerator* createRandomGenerator(unsigned seed) {
    RandomGenerator* generator = (RandomGenerator*)malloc(sizeof(RandomGenerator));
    if (generator == NULL) {
        fprintf(stderr, "Memory allocation failed for RandomGenerator\n");
        exit(EXIT_FAILURE);
    }
    generator->seed = seed;
    return generator;
}

int randomInt(RandomGenerator* generator, int min, int max) {
    srand(generator->seed++);
    return rand() % (max - min + 1) + min;
}

char* randomString(RandomGenerator* generator, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* buffer = (char*)malloc((length + 1) * sizeof(char));
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed for random string\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < length; ++i) {
        buffer[i] = charset[randomInt(generator, 0, strlen(charset) - 1)];
    }
    buffer[length] = '\0';
    return buffer;
}

Record* createRecords(RandomGenerator* generator, size_t count, size_t bufferSize, int minValue, int maxValue) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < count; ++i) {
        records[i].value = randomInt(generator, minValue, maxValue);
        records[i].buffer = randomString(generator, bufferSize);
    }
    return records;
}

void freeRecords(Record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
