Record* create_records(int start, int end) {
    Record* records = (Record*)malloc((end - start + 1) * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = start; i <= end; i++) {
        records[i - start].id = i;
        records[i - start].key = rand() % 1000;
        records[i - start].value = (double)i * 0.5 + (rand() / (RAND_MAX + 1.0));
        snprintf(records[i - start].buffer, BUFFER_SIZE, "%d", i);
    }
    return records;
}

void free_records(Record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    Record* records = create_records(1, MAX_RECORDS);
    if (records) {
        for (int i = 0; i < MAX_RECORDS; i++) {
            printf("ID: %d, Key: %d, Value: %.2f, Buffer: %s\n", 
                   records[i].id, records[i].key, records[i].value, records[i].buffer);
        }
        free_records(records);
    }
    return 0;
}
