void initialize_profiles(int num_users) {
    if (num_users > MAX_USERS) {
        printf("Error: Maximum number of users exceeded.\n");
        return;
    }

    pthread_mutex_lock(&mutex);

    scores = (double *)malloc(num_users * sizeof(double));
    user_ids = (char **)malloc(num_users * sizeof(char *));
    profiles = (user_profile **)malloc(num_users * sizeof(user_profile *));

    if (!scores || !user_ids || !profiles) {
        printf("Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < num_users; i++) {
        profiles[i] = (user_profile *)malloc(sizeof(user_profile));
        if (!profiles[i]) {
            printf("Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Initialize user profile
        snprintf(profiles[i]->name, sizeof(profiles[i]->name), "User%d", i + 1);
        profiles[i]->age = rand() % 73 + 18; // Random age between 18 and 90
        snprintf(profiles[i]->email, sizeof(profiles[i]->email), "user%d@example.com", i + 1);

        scores[i] = (double)rand() / RAND_MAX;
        user_ids[i] = strdup(profiles[i]->name); // Assuming user IDs are unique and valid
    }

    user_count = num_users;

    pthread_mutex_unlock(&mutex);
}

void free_profiles() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < user_count; i++) {
        free(profiles[i]);
        free(user_ids[i]);
    }
    free(scores);
    free(user_ids);
    free(profiles);

    user_count = 0;

    pthread_mutex_unlock(&mutex);
}

void *update_profile(void *arg) {
    int index = *(int *)arg;
    if (index < 0 || index >= user_count) {
        printf("Error: Invalid user index.\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);

    // Simulate updating a profile
    snprintf(profiles[index]->name, sizeof(profiles[index]->name), "UpdatedUser%d", index + 1);
    profiles[index]->age += 1; // Increment age by 1

    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    int num_users = 500;

    initialize_profiles(num_users);

    pthread_t threads[num_users];
    for (int i = 0; i < num_users; i++) {
        pthread_create(&threads[i], NULL, update_profile, &i);
    }

    for (int i = 0; i < num_users; i++) {
        pthread_join(threads[i], NULL);
    }

    free_profiles();

    return 0;
}
