#include <semaphore.h>

#define MAX_RECORDS 10000
#define RECORD_SIZE sizeof(int)

typedef struct {
    int value;
} record;

record memory_pool[MAX_RECORDS];
int pool_index = 0;

sem_t pool_mutex;
sem_t pool_full;

void* process_data(void* arg) {
    // Simulate data processing logic here
    return NULL;
}

void init_memory_pool() {
    sem_init(&pool_mutex, 0, 1);
    sem_init(&pool_full, 0, MAX_RECORDS);
}

record* allocate_record() {
    record* rec = NULL;
    sem_wait(&pool_mutex);
    if (pool_index < MAX_RECORDS) {
        rec = &memory_pool[pool_index++];
        sem_post(&pool_full);
    }
    sem_post(&pool_mutex);
    return rec;
}

void free_record(record* rec) {
    sem_wait(&pool_mutex);
    int index = (rec - memory_pool) / RECORD_SIZE;
    if (index >= 0 && index < pool_index) {
        memmove(&memory_pool[index], &memory_pool[index + 1], (pool_index - index - 1) * RECORD_SIZE);
        pool_index--;
        sem_post(&pool_full);
    }
    sem_post(&pool_mutex);
}

void* read_and_process_file(void* arg) {
    FILE* file = fopen((char*)arg, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        record* rec = allocate_record();
        if (rec) {
            // Simulate data validation and processing logic here
            rec->value = rand() % 100; // Example random value generation
        }
    }

    fclose(file);
    return NULL;
}

void write_to_output_file(record* records, int count, const char* output_file) {
    FILE* file = fopen(output_file, "w");
    if (!file) {
        perror("Failed to open output file");
        return;
    }

    for (int i = 0; i < count; i++) {
        fprintf(file, "%d\n", records[i].value);
    }

    fclose(file);
}

int main() {
    init_memory_pool();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, read_and_process_file, "input.txt");
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    record* records = malloc(MAX_RECORDS * RECORD_SIZE);
    int count = pool_index;
    memcpy(records, memory_pool, count * RECORD_SIZE);

    write_to_output_file(records, count, "output.txt");

    free(records);
    sem_destroy(&pool_mutex);
    sem_destroy(&pool_full);

    return 0;
}
