typedef struct node {
    Record data;
    struct node *next;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Record data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

Record find_largest_record(Node* head) {
    Record largest = {0, 0, NULL};
    while (head != NULL) {
        if (head->data.value > largest.value) {
            largest = head->data;
        }
        head = head->next;
    }
    return largest;
}

void free_memory(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

