    handle_memory_allocation_failures();
    return NULL;
}

int main() {
    pthread_t threads[4];
    for (size_t i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, manage_data_structures, NULL);
    }
    for (size_t i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
