#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float value;
    char* name;
    size_t name_length;
} item;

typedef struct {
    time_t timestamp;
    char* message;
    size_t message_length;
} log_entry;

typedef struct {
    item* items;
    double* timestamps;
    log_entry* logs;
    size_t num_items;
    size_t num_timestamps;
    size_t num_logs;
    pthread_mutex_t mutex;
} data_store;

void init_item(item* i, float value, const char* name) {
    i->value = value;
    i->name_length = strlen(name);
    i->name = (char*)malloc(i->name_length + 1);
    strcpy(i->name, name);
}

void free_item(item* i) {
    free(i->name);
}

void init_log_entry(log_entry* e, time_t timestamp, const char* message) {
    e->timestamp = timestamp;
    e->message_length = strlen(message);
    e->message = (char*)malloc(e->message_length + 1);
    strcpy(e->message, message);
}

void free_log_entry(log_entry* e) {
    free(e->message);
}

data_store* create_data_store(size_t num_items, size_t num_timestamps, size_t num_logs) {
    data_store* ds = (data_store*)malloc(sizeof(data_store));
    if (!ds) return NULL;

    ds->items = (item*)calloc(num_items, sizeof(item));
    ds->timestamps = (double*)calloc(num_timestamps, sizeof(double));
    ds->logs = (log_entry*)calloc(num_logs, sizeof(log_entry));
    ds->num_items = num_items;
    ds->num_timestamps = num_timestamps;
    ds->num_logs = num_logs;

    if (!ds->items || !ds->timestamps || !ds->logs) {
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    return ds;
}

void destroy_data_store(data_store* ds) {
    for (size_t i = 0; i < ds->num_items; ++i) {
        free_item(&ds->items[i]);
    }
    free(ds->items);
    free(ds->timestamps);
    for (size_t i = 0; i < ds->num_logs; ++i) {
        free_log_entry(&ds->logs[i]);
    }
    free(ds->logs);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}

void set_random_item_value(item* i, float min_val, float max_val) {
    i->value = (max_val - min_val) * ((float)rand() / RAND_MAX) + min_val;
}
