#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 10000
#define SESSION_EXPIRATION_TIME 3600 // 1 hour in seconds

typedef struct {
    char token[256];
    time_t expiration_time;
} Session;

Session sessions[MAX_SESSIONS];

int find_session_index(const char* token) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (strcmp(sessions[i].token, token) == 0) {
            return i;
        }
    }
    return -1;
}

void create_session(const char* token) {
    int index = find_session_index(token);
    if (index == -1) {
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (sessions[i].expiration_time == 0) {
                strcpy(sessions[i].token, token);
                sessions[i].expiration_time = time(NULL) + SESSION_EXPIRATION_TIME;
                return;
            }
        }
    } else {
        sessions[index].expiration_time = time(NULL) + SESSION_EXPIRATION_TIME;
    }
}

void renew_session(const char* token) {
    int index = find_session_index(token);
    if (index != -1 && time(NULL) < sessions[index].expiration_time) {
        sessions[index].expiration_time = time(NULL) + SESSION_EXPIRATION_TIME;
    }
}

void invalidate_session(const char* token) {
    int index = find_session_index(token);
    if (index != -1) {
        sessions[index].token[0] = '\0';
        sessions[index].expiration_time = 0;
    }
}

int authenticate_user(const char* username, const char* password) {
    // Simulate external authentication service call
    if (strcmp(username, "admin") == 0 && strcmp(password, "password123") == 0) {
        create_session("session_token_123");
        return 1;
    }
    return 0;
}

void handle_user_interaction(const char* token) {
    int index = find_session_index(token);
    if (index != -1 && time(NULL) < sessions[index].expiration_time) {
        // Process user interaction
        printf("User interaction handled successfully.\n");
    } else {
        printf("Invalid or expired session token.\n");
    }
}

int main() {
    authenticate_user("admin", "password123");
    handle_user_interaction("session_token_123");
    renew_session("session_token_123");
    handle_user_interaction("session_token_123");
    invalidate_session("session_token_123");
    return 0;
}
