#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <atomic>

class Session {
public:
    std::string authToken;
    // User profile data
    std::string userProfile;
    // Access logs
    std::vector<std::string> activityLog;
    // Reference count for lifecycle management
    std::atomic<int> refCount{0};
    // Timestamps for login and logout events
    std::chrono::system_clock::time_point loginTime;
    std::chrono::system_clock::time_point logoutTime;

    Session(const std::string& token, const std::string& profile)
        : authToken(token), userProfile(profile) {
        loginTime = std::chrono::system_clock::now();
    }

    ~Session() {
        logoutTime = std::chrono::system_clock::now();
    }
};

class SessionPool {
private:
    std::vector<Session*> pool;
    std::mutex poolMutex;
    std::condition_variable sessionAvailable;
    int maxSessions;
    int concurrencyLevel;
    std::atomic<int> activeSessions{0};
    std::chrono::seconds gcInterval;
    std::chrono::seconds expirationThreshold;

public:
    SessionPool(int max, int conc, std::chrono::seconds gcInt, std::chrono::seconds expThresh)
        : maxSessions(max), concurrencyLevel(conc), gcInterval(gcInt), expirationThreshold(expThresh) {
        for (int i = 0; i < maxSessions; ++i) {
            pool.push_back(new Session("token", "profile"));
        }
    }

    ~SessionPool() {
        for (auto& session : pool) {
            delete session;
        }
    }

    Session* getSession(const std::string& token, const std::string& profile) {
        std::unique_lock<std::mutex> lock(poolMutex);
        while (activeSessions >= maxSessions) {
            sessionAvailable.wait(lock);
        }
        ++activeSessions;
        return new Session(token, profile);
    }

    void releaseSession(Session* session) {
        delete session;
        --activeSessions;
        sessionAvailable.notify_one();
    }

    void garbageCollect() {
        while (true) {
            std::this_thread::sleep_for(gcInterval);
            std::unique_lock<std::mutex> lock(poolMutex);
            for (auto& session : pool) {
                if (session->refCount.load() == 0 && 
                    std::chrono::system_clock::now() - session->logoutTime > expirationThreshold) {
                    delete session;
                    session = new Session("token", "profile");
                }
            }
        }
    }

    void startGCThread() {
        std::thread gcThread(&SessionPool::garbageCollect, this);
        gcThread.detach();
    }
};

int main() {
    SessionPool pool(100, 4, std::chrono::seconds(60), std::chrono::minutes(30));
    pool.startGCThread();

    // Simulate session usage
    for (int i = 0; i < 50; ++i) {
        Session* session = pool.getSession("token", "profile");
        // Use the session...
        pool.releaseSession(session);
    }

    return 0;
}
