#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_FILES 1024
#define BLOCK_SIZE 4096

typedef struct {
    int value;
    size_t data_size;
    void* data_block;
} FileData;

typedef struct {
    char name[256];
    size_t file_size;
    time_t last_modified;
    mode_t permissions;
} FileMetadata;

typedef struct {
    pthread_mutex_t lock;
    FILE* log_file;
    FileData files[MAX_FILES];
    FileMetadata metadata[MAX_FILES];
} ScalableFileSystemManager;

ScalableFileSystemManager* create_sfs_manager() {
    ScalableFileSystemManager* manager = (ScalableFileSystemManager*)malloc(sizeof(ScalableFileSystemManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen("sfs_log.txt", "a");
    return manager;
}

void destroy_sfs_manager(ScalableFileSystemManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    fclose(manager->log_file);
    free(manager);
}

int add_file(ScalableFileSystemManager* manager, const char* name, int value, size_t data_size, void* data_block) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_FILES; i++) {
        if (manager->files[i].data_block == NULL) {
            strcpy(manager->metadata[i].name, name);
            manager->metadata[i].file_size = data_size;
            manager->metadata[i].last_modified = time(NULL);
            manager->metadata[i].permissions = 0644;
            manager->files[i].value = value;
            manager->files[i].data_size = data_size;
            manager->files[i].data_block = malloc(data_size);
            memcpy(manager->files[i].data_block, data_block, data_size);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int read_file(ScalableFileSystemManager* manager, const char* name, void** data_block) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_FILES; i++) {
        if (strcmp(manager->metadata[i].name, name) == 0 && manager->files[i].data_block != NULL) {
            *data_block = malloc(manager->files[i].data_size);
            memcpy(*data_block, manager->files[i].data_block, manager->files[i].data_size);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int write_file(ScalableFileSystemManager* manager, const char* name, void* data_block, size_t data_size) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_FILES; i++) {
        if (strcmp(manager->metadata[i].name, name) == 0 && manager->files[i].data_block != NULL) {
            free(manager->files[i].data_block);
            manager->files[i].data_size = data_size;
            manager->files[i].data_block = malloc(data_size);
            memcpy(manager->files[i].data_block, data_block, data_size);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int delete_file(ScalableFileSystemManager* manager, const char* name) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < MAX_FILES; i++) {
        if (strcmp(manager->metadata[i].name, name) == 0 && manager->files[i].data_block != NULL) {
            free(manager->files[i].data_block);
            memset(&manager->files[i], 0, sizeof(FileData));
            memset(&manager->metadata[i], 0, sizeof(FileMetadata));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int log_operation(ScalableFileSystemManager* manager, const char* user, const char* action) {
    time_t now = time(NULL);
    fprintf(manager->log_file, "%s %s %s\n", ctime(&now), user, action);
    fflush(manager->log_file);
    return 0;
}

int encrypt_data(const unsigned char* password, size_t password_len, const unsigned char* data, size_t data_len, unsigned char** encrypted_data, size_t* encrypted_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    unsigned char key[16];
    unsigned char iv[12];
    if (!EVP_BytesToKey(EVP_aes_128_gcm(), EVP_sha256(), NULL, password, password_len, 1000, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *encrypted_data = (unsigned char*)malloc(data_len + EVP_GCM_TLS_TAG_LEN);
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, iv)) {
        free(*encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    if (!EVP_EncryptUpdate(ctx, *encrypted_data, encrypted_len, data, data_len)) {
        free(*encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    size_t tag_len = 0;
    if (!EVP_EncryptFinal_ex(ctx, (*encrypted_data) + *encrypted_len, &tag_len)) {
        free(*encrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *encrypted_len += tag_len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int decrypt_data(const unsigned char* password, size_t password_len, const unsigned char* encrypted_data, size_t encrypted_len, unsigned char** decrypted_data, size_t* decrypted_len) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    unsigned char key[16];
    unsigned char iv[12];
    if (!EVP_BytesToKey(EVP_aes_128_gcm(), EVP_sha256(), NULL, password, password_len, 1000, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *decrypted_data = (unsigned char*)malloc(encrypted_len);
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, iv)) {
        free(*decrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    if (!EVP_DecryptUpdate(ctx, *decrypted_data, decrypted_len, encrypted_data, encrypted_len)) {
        free(*decrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    size_t tag_len = 0;
    if (!EVP_DecryptFinal_ex(ctx, (*decrypted_data) + *decrypted_len, &tag_len)) {
        free(*decrypted_data);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *decrypted_len += tag_len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
