        data[i].unit = getRandomUnit();
        if (data[i].unit == 'C') {
            data[i].temperature = (data[i].temperature * 9 / 5) + 32; // Convert to Fahrenheit
        }
        data[i].timestamp = time(NULL);
    }

    printf("Sensor data populated successfully.\n");
}

int main() {
    SensorData sensorData[MAX_ENTRIES];
    int entriesToPopulate = 1000;

    populateSensorData(sensorData, entriesToPopulate);

    return 0;
}
