#define MAX_RECORDS 10000000

typedef struct {
    int value;
} record;

void manage_memory(long **offsets, int **keys, record **records, int num_records) {
    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }

    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = i * 10;
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % 10000;
    }
}

void free_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long *offsets;
    int *keys;
    record *records;

    manage_memory(&offsets, &keys, &records, MAX_RECORDS);

    // Use the allocated memory here

    free_memory(offsets, keys, records);

    return 0;
}
