#include <time.h>

typedef struct {
    int value;
    size_t size;
    uint32_t checksum;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t total_records;
    time_t last_accessed;
    int is_open_for_writing;
} file_metadata;

file_metadata* create_file_metadata(size_t num_records, int min_random_value, int max_random_value) {
    file_metadata* metadata = (file_metadata*)malloc(sizeof(file_metadata));
    if (!metadata) {
        return NULL; // Handle allocation failure
    }

    metadata->offsets = (long*)calloc(num_records, sizeof(long));
    metadata->keys = (int*)calloc(num_records, sizeof(int));
    metadata->records = (record**)calloc(num_records, sizeof(record*));

    if (!metadata->offsets || !metadata->keys || !metadata->records) {
        free(metadata->offsets);
        free(metadata->keys);
        free(metadata->records);
        free(metadata);
        return NULL; // Handle allocation failure
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        metadata->records[i] = (record*)malloc(sizeof(record));
        if (!metadata->records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(metadata->records[j]);
            }
            free(metadata->offsets);
            free(metadata->keys);
            free(metadata->records);
            free(metadata);
            return NULL; // Handle allocation failure
        }

