record* create_records(size_t count, double min_value, double max_value) {
    if (count == 0) return NULL;

    record *records = malloc(count * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < count; ++i) {
        records[i].p = malloc(sizeof(point));
        if (!records[i].p) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) free(records[j].p);
            free(records);
            return NULL;
        }
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < count; ++i) {
        records[i].p->x = (float)(rand() / (double)RAND_MAX * (max_value - min_value) + min_value);
        records[i].p->y = (float)(rand() / (double)RAND_MAX * (max_value - min_value) + min_value);
        records[i].value = (double)(rand() / (double)RAND_MAX * (max_value - min_value) + min_value);
        records[i].length = sizeof(point);
    }

    return records;
}

void free_records(record *records, size_t count) {
    if (!records) return;

    for (size_t i = 0; i < count; ++i) {
        free(records[i].p);
    }
    free(records);
}
