file_metadata* initialize_file_metadata(size_t num_records) {
    file_metadata *metadata = (file_metadata*)malloc(sizeof(file_metadata));
    if (!metadata) return NULL;

    metadata->offsets = (long*)calloc(num_records, sizeof(long));
    metadata->keys = (int*)calloc(num_records, sizeof(int));
    metadata->records = (record*)calloc(num_records, sizeof(record));
    metadata->total_records = num_records;
    metadata->last_accessed = time(NULL);
    metadata->is_open_for_writing = 0;

    if (!metadata->offsets || !metadata->keys || !metadata->records) {
        free(metadata->offsets);
        free(metadata->keys);
        free(metadata->records);
        free(metadata);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        metadata->offsets[i] = i * 1024; // Sequential offset values
        metadata->keys[i] = i + 1;       // Sequential key values

        record *rec = &metadata->records[i];
        rec->value = rand() % 1000;     // Random value between 0 and 999
        rec->size = sizeof(record);
        rec->checksum = calculate_checksum(rec); // Function to calculate checksum
    }

    return metadata;
}

uint32_t calculate_checksum(const record *rec) {
    uint32_t sum = 0;
    const char *data = (const char*)rec;
    for (size_t i = 0; i < rec->size; ++i) {
        sum += data[i];
    }
    return sum;
}

void free_file_metadata(file_metadata *metadata) {
    if (metadata) {
        free(metadata->offsets);
        free(metadata->keys);
        free(metadata->records);
        free(metadata);
    }
}
