int allocate_and_initialize(long *offsets, int *keys, record **records, int n, double min_val, double max_val) {
    if (n <= 0 || min_val >= max_val) {
        return -1; // Invalid input
    }

    offsets = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));
    *records = (record *)malloc(n * sizeof(record));

    if (!offsets || !keys || !*records) {
        free(offsets);
        free(keys);
        free(*records);
        return -2; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        offsets[i] = i * 10L; // Example initialization
        keys[i] = i;
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];
        (*records)[i].value = min_val + (double)rand() / RAND_MAX * (max_val - min_val);
    }

    free(offsets);
    free(keys);

    return 0; // Success
}

void sort_records(record *records, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (records[j].key > records[j + 1].key) {
                record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

int main() {
    int n = 5;
    double min_val = 0.0, max_val = 1.0;
    long *offsets;
    int *keys;
    record *records;

    if (allocate_and_initialize(offsets, keys, &records, n, min_val, max_val) == 0) {
        sort_records(records, n);

        for (int i = 0; i < n; i++) {
            printf("Offset: %ld, Key: %d, Value: %f\n", records[i].offset, records[i].key, records[i].value);
        }

        free(records);
    } else {
        printf("Failed to allocate memory or initialize data.\n");
    }

    return 0;
}
