#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    FILE_TYPE_DIR,
    FILE_TYPE_FILE
} FileType;

typedef struct FileObject {
    char name[256];
    size_t size;
    FileType type;
    union {
        struct {
            struct FileObject** children;
            size_t num_children;
        } dir;
        struct {
            // Additional file-specific metadata
        } file;
    };
    pthread_mutex_t lock;
} FileObject;

FileObject* create_file_object(const char* name, FileType type) {
    FileObject* obj = (FileObject*)malloc(sizeof(FileObject));
    if (!obj) {
        perror("Failed to allocate memory for file object");
        return NULL;
    }
    strcpy(obj->name, name);
    obj->size = 0;
    obj->type = type;

    pthread_mutex_init(&obj->lock, NULL);

    if (type == FILE_TYPE_DIR) {
        obj->dir.children = NULL;
        obj->dir.num_children = 0;
    }

    return obj;
}

void destroy_file_object(FileObject* obj) {
    if (!obj) return;

    if (obj->type == FILE_TYPE_DIR) {
        for (size_t i = 0; i < obj->dir.num_children; ++i) {
            destroy_file_object(obj->dir.children[i]);
        }
        free(obj->dir.children);
    }

    pthread_mutex_destroy(&obj->lock);
    free(obj);
}

void add_child(FileObject* parent, FileObject* child) {
    if (!parent || !child) return;

    pthread_mutex_lock(&parent->lock);

    size_t new_size = (parent->dir.num_children + 1) * sizeof(FileObject*);
    FileObject** new_children = realloc(parent->dir.children, new_size);
    if (!new_children) {
        perror("Failed to reallocate memory for children");
        pthread_mutex_unlock(&parent->lock);
        return;
    }
    parent->dir.children = new_children;

    parent->dir.children[parent->dir.num_children++] = child;

    pthread_mutex_unlock(&parent->lock);
}

void remove_child(FileObject* parent, FileObject* child) {
    if (!parent || !child) return;

    pthread_mutex_lock(&parent->lock);

    for (size_t i = 0; i < parent->dir.num_children; ++i) {
        if (parent->dir.children[i] == child) {
            size_t new_size = (parent->dir.num_children - 1) * sizeof(FileObject*);
            FileObject** new_children = realloc(parent->dir.children, new_size);
            if (!new_children) {
                perror("Failed to reallocate memory for children");
                pthread_mutex_unlock(&parent->lock);
                return;
            }
            parent->dir.children = new_children;

            memmove(&parent->dir.children[i], &parent->dir.children[i + 1], (parent->dir.num_children - i - 1) * sizeof(FileObject*));
            --parent->dir.num_children;
            break;
        }
    }

    pthread_mutex_unlock(&parent->lock);
}

void flush_to_storage() {
    // Implement logic to flush all pending changes to persistent storage
    printf("Flushing changes to storage...\n");
}
