typedef struct {
    float x, y;
} point;

typedef struct {
    double value;
    size_t length;
    point p;
} record;

typedef struct {
    int id;
    time_t timestamp;
    record *r;
} event;

void* allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void *ptr) {
    free(ptr);
}

record* create_record(float x, float y, double min_val, double max_val) {
    record *r = (record*)allocate_memory(sizeof(record));
    r->p.x = x;
    r->p.y = y;
    r->value = min_val + (max_val - min_val) * ((double)rand() / RAND_MAX);
    r->length = 0; // Initialize length as needed
    return r;
}

event* create_event(int id, time_t timestamp, record *r) {
    event *e = (event*)allocate_memory(sizeof(event));
    e->id = id;
    e->timestamp = timestamp;
    e->r = r;
    return e;
}

void set_record_value(record *r, double min_val, double max_val) {
    r->value = min_val + (max_val - min_val) * ((double)rand() / RAND_MAX);
    printf("Event %d at %ld: Record value set to %.2f\n", r->p.x, time(NULL), r->value);
}

void* thread_function(void *arg) {
    int id = *(int*)arg;
    record *r = create_record(id, id, 0.0, 100.0);
    set_record_value(r, 0.0, 100.0);
    free_memory(r);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    int ids[10];

    for (int i = 0; i < 10; i++) {
        ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &ids[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
