    char eventType[50];
    ValueType valueType;
    ValueUnion value;
    struct Event* next;
} Event;

typedef struct Task {
    struct Node* node;
    Event* events;
} Task;

typedef struct Node {
    int id;
    char* name;
    int priority;
    pthread_mutex_t lock;
    struct Node* next;
} Node;

Node* createNode(int id, const char* name, int priority) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;
    newNode->id = id;
    newNode->name = strdup(name);
    newNode->priority = priority;
    pthread_mutex_init(&newNode->lock, NULL);
    newNode->next = NULL;
    return newNode;
}

void updatePriority(Node* node, int newPriority) {
    pthread_mutex_lock(&node->lock);
    int oldPriority = node->priority;
    node->priority = newPriority;
    printf("Priority updated: %d -> %d\n", oldPriority, newPriority);
    pthread_mutex_unlock(&node->lock);
}

void freeNode(Node* node) {
    if (node) {
        pthread_mutex_destroy(&node->lock);
        free(node->name);
        free(node);
    }
}

