#include <string.h>
#include <pthread.h>

#define MAX_NODES 1000

typedef struct {
    int value;
    size_t size;
    void* data;
} network_record;

typedef struct rb_node {
    int key;
    long offset;
    struct rb_node *left, *right, *parent;
    int color; // 0 for red, 1 for black
} rb_node;

typedef struct {
    rb_node* root;
    pthread_mutex_t lock;
} rb_tree;

rb_node* create_rb_node(int key, long offset) {
    rb_node* node = (rb_node*)malloc(sizeof(rb_node));
    node->key = key;
    node->offset = offset;
    node->left = node->right = node->parent = NULL;
    node->color = 0; // Red
    return node;
}

void left_rotate(rb_tree* tree, rb_node* x) {
    rb_node* y = x->right;
    x->right = y->left;
    if (y->left != NULL)
        y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL)
        tree->root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void right_rotate(rb_tree* tree, rb_node* y) {
    rb_node* x = y->left;
    y->left = x->right;
    if (x->right != NULL)
        x->right->parent = y;
    x->parent = y->parent;
    if (y->parent == NULL)
        tree->root = x;
    else if (y == y->parent->right)
        y->parent->right = x;
    else
        y->parent->left = x;
    x->right = y;
    y->parent = x;
}

void rb_insert_fixup(rb_tree* tree, rb_node* z) {
    while (z->parent != NULL && z->parent->color == 0) {
        if (z->parent == z->parent->parent->left) {
            rb_node* y = z->parent->parent->right;
            if (y != NULL && y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(tree, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                right_rotate(tree, z->parent->parent);
            }
        } else {
            rb_node* y = z->parent->parent->left;
            if (y != NULL && y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(tree, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                left_rotate(tree, z->parent->parent);
            }
        }
    }
    tree->root->color = 1;
}

void rb_insert(rb_tree* tree, int key, long offset) {
    pthread_mutex_lock(&tree->lock);
    rb_node* z = create_rb_node(key, offset);
    rb_node* y = NULL;
    rb_node* x = tree->root;

    while (x != NULL) {
        y = x;
        if (z->key < x->key)
            x = x->left;
        else
            x = x->right;
    }

    z->parent = y;
    if (y == NULL)
        tree->root = z;
    else if (z->key < y->key)
        y->left = z;
    else
        y->right = z;

    if (z->parent == NULL) {
        z->color = 1;
        pthread_mutex_unlock(&tree->lock);
        return;
    }

    if (z->parent->parent == NULL) {
        pthread_mutex_unlock(&tree->lock);
        return;
    }

    rb_insert_fixup(tree, z);
    pthread_mutex_unlock(&tree->lock);
}

int main() {
    rb_tree tree;
    pthread_mutex_init(&tree.lock, NULL);
    tree.root = NULL;

    int key, offset;
    while (scanf("%d %ld", &key, &offset) != EOF) {
        rb_insert(&tree, key, offset);
    }

    // Find and print the largest integer in the array
    rb_node* current = tree.root;
    while (current->right != NULL)
        current = current->right;

    printf("Largest integer: %d\n", current->key);

    pthread_mutex_destroy(&tree.lock);
    return 0;
}
