#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/types.h>
#include <unistd.h>

#define SHM_SIZE 1024

int create_shared_memory(key_t key) {
    int shmid = shmget(key, SHM_SIZE, IPC_CREAT | 0666);
    if (shmid == -1) {
        perror("shmget");
        exit(EXIT_FAILURE);
    }
    return shmid;
}

void* attach_shared_memory(int shmid) {
    void* shmaddr = shmat(shmid, NULL, 0);
    if (shmaddr == (void*)-1) {
        perror("shmat");
        exit(EXIT_FAILURE);
    }
    return shmaddr;
}

void detach_shared_memory(void* shmaddr) {
    if (shmdt(shmaddr) == -1) {
        perror("shmdt");
        exit(EXIT_FAILURE);
    }
}

void delete_shared_memory(int shmid) {
    if (shmctl(shmid, IPC_RMID, NULL) == -1) {
        perror("shmctl");
        exit(EXIT_FAILURE);
    }
}

int main() {
    key_t key = ftok(".", 'R');
    int shmid = create_shared_memory(key);
    void* shmaddr = attach_shared_memory(shmid);

    // Example usage of shared memory
    char* data = (char*)shmaddr;
    strcpy(data, "Hello, Shared Memory!");

    printf("Data in shared memory: %s\n", data);

    detach_shared_memory(shmaddr);
    delete_shared_memory(shmid);

    return 0;
}
