        event_array[i].data = malloc(sizeof(payload));
        if (!event_array[i].data) {
            fprintf(stderr, "Memory allocation failed for payload.\n");
            return;
        }

        event_array[i].data->size = strlen(default_payload) + 1;
        event_array[i].data->payload = malloc(event_array[i].data->size);
        if (!event_array[i].data->payload) {
