#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct record {
    long offset;
    int key;
    int value;
} Record;

typedef struct metadata {
    time_t creation_time;
    time_t last_accessed_time;
    char* users[10];
    int usage_score;
} Metadata;

typedef struct pool_node {
    Record record;
    Metadata metadata;
    struct pool_node* next;
} PoolNode;

PoolNode* memory_pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory_pool(int max_records) {
    for (int i = 0; i < max_records; i++) {
        PoolNode* new_node = (PoolNode*)malloc(sizeof(PoolNode));
        if (new_node == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        new_node->next = memory_pool;
        memory_pool = new_node;
    }
}

Record* allocate_record(int key) {
    pthread_mutex_lock(&pool_lock);
    PoolNode* node = memory_pool;
    if (node == NULL) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Memory pool exhausted
    }
    memory_pool = node->next;
    Record* record = &node->record;
    Metadata* metadata = &node->metadata;
    record->key = key;
    record->value = rand() % 1000; // Random value between 0 and 999
    metadata->creation_time = time(NULL);
    metadata->last_accessed_time = metadata->creation_time;
    metadata->usage_score = 0;
    pthread_mutex_unlock(&pool_lock);
    return record;
}

void deallocate_record(Record* record) {
    pthread_mutex_lock(&pool_lock);
    PoolNode* node = (PoolNode*)record;
    node->next = memory_pool;
    memory_pool = node;
    pthread_mutex_unlock(&pool_lock);
}

// Additional functions for garbage collection, logging, resource monitoring, and machine learning integration would be implemented here

int main() {
    initialize_memory_pool(MAX_RECORDS);

    Record* record1 = allocate_record(123);
    if (record1 != NULL) {
        printf("Record allocated with key: %d\n", record1->key);
        deallocate_record(record1);
    }

    return 0;
}
```

