#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct task {
    char *name;
    int priority;
    void *payload;
    struct dependency *dependencies;
} task;

typedef struct payload {
    char *buffer;
    size_t size;
} payload;

typedef struct dependency {
    task *task;
    struct dependency *next;
} dependency;

task* create_task(const char *name, int priority, size_t payload_size) {
    task *t = (task *)malloc(sizeof(task));
    if (!t) return NULL;

    t->name = strdup(name);
    t->priority = priority;
    t->payload = malloc(payload_size);
    if (!t->payload) {
        free(t->name);
        free(t);
        return NULL;
    }
    memset(t->payload, 0, payload_size);

    t->dependencies = NULL;

    return t;
}

void destroy_task(task *t) {
    if (t->name) free(t->name);
    if (t->payload) free(t->payload);
    dependency *dep = t->dependencies;
    while (dep) {
        dependency *next = dep->next;
        free(dep);
        dep = next;
    }
    free(t);
}

void add_dependency(task *t, task *dependency_task) {
    dependency *new_dep = (dependency *)malloc(sizeof(dependency));
    if (!new_dep) return;

    new_dep->task = dependency_task;
    new_dep->next = t->dependencies;
    t->dependencies = new_dep;
}

int main() {
    // Example usage
    task *t1 = create_task("Task1", 1, 1024);
    if (!t1) return -1;

    task *t2 = create_task("Task2", 2, 512);
    if (!t2) {
        destroy_task(t1);
        return -1;
    }

    add_dependency(t1, t2);

    // Clean up
    destroy_task(t1);
    destroy_task(t2);

    return 0;
}
