// Function to manage and process data streams
void manage_and_process_data_streams(int min_val, int max_val) {
    // Initialize random seed
    srand(time(NULL));

    // Read number of data streams from standard input
    int num_streams;
    scanf("%d", &num_streams);

    // Allocate memory for data streams
    DataStream* streams = (DataStream*)malloc(num_streams * sizeof(DataStream));
    if (!streams) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize each data stream
    for (int i = 0; i < num_streams; i++) {
        // Allocate memory for offsets and keys arrays
        streams[i].offsets = (long*)malloc(100 * sizeof(long));
        streams[i].keys = (int*)malloc(100 * sizeof(int));
        if (!streams[i].offsets || !streams[i].keys) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Allocate memory for records array
        streams[i].records = (Record**)malloc(100 * sizeof(Record*));
        if (!streams[i].records) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        // Initialize red-black tree for each data stream
        streams[i].rb_tree = create_rb_tree();
        if (!streams[i].rb_tree) {
            fprintf(stderr, "Failed to create red-black tree\n");
            return;
        }
    }

    // Read integers from standard input and store them in arrays for each data stream
    for (int i = 0; i < num_streams; i++) {
        int num_integers;
        scanf("%d", &num_integers);
        for (int j = 0; j < num_integers; j++) {
            int key;
            scanf("%d", &key);

            // Allocate memory for record
            Record* record = (Record*)malloc(sizeof(Record));
            if (!record) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }

            // Initialize record with random value and size
            record->value = rand() % (max_val - min_val + 1) + min_val;
            record->size = sizeof(int);
            record->offset = malloc(record->size);
            if (!record->offset) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            memcpy(record->offset, &record->value, record->size);

            // Insert record into red-black tree
            rb_tree_insert(streams[i].rb_tree, key, record);
        }
    }

    // Find and print the largest integer in each stream
    for (int i = 0; i < num_streams; i++) {
        int max_value = INT_MIN;
        RBTreeNode* node = rb_tree_get_max_node(streams[i].rb_tree);
        while (node) {
            if (((Record*)node->value)->value > max_value) {
                max_value = ((Record*)node->value)->value;
            }
            node = rb_tree_get_prev_node(node);
        }
        printf("Max value in stream %d: %d\n", i, max_value);
    }

    // Free all allocated memory
    for (int i = 0; i < num_streams; i++) {
        free(streams[i].offsets);
        free(streams[i].keys);
        for (int j = 0; j < streams[i].num_records; j++) {
            free(((Record*)streams[i].records[j])->offset);
            free(streams[i].records[j]);
        }
        free(streams[i].records);
        rb_tree_free(streams[i].rb_tree);
    }
    free(streams);

    printf("All memory freed\n");
}
