use tokio::time::{self, Duration};

struct Session {
    user_id: String,
    last_accessed: time::Instant,
}

struct AuthManager {
    sessions: Arc<Mutex<HashMap<String, Session>>>,
    session_dir: PathBuf,
    max_sessions: usize,
    invalidation_interval: Duration,
    mfa_enabled: bool,
    tx: mpsc::Sender<()>,
}

