    fn new(session_dir: PathBuf, max_sessions: usize, invalidation_interval: Duration, mfa_enabled: bool) -> Self {
        let (tx, mut rx) = mpsc::channel(1);
        tokio::spawn(async move {
            loop {
                if rx.recv().await.is_some() {
                    break;
                }
                time::sleep(invalidation_interval).await;
                // Invalidate inactive sessions
            }
        });
        AuthManager {
            sessions: Arc::new(Mutex::new(HashMap::new())),
            session_dir,
            max_sessions,
            invalidation_interval,
            mfa_enabled,
            tx,
        }
    }

    async fn login(&self, user_id: String) -> Result<(), String> {
        let mut sessions = self.sessions.lock().unwrap();
        if sessions.len() >= self.max_sessions {
            return Err("Max sessions reached".to_string());
        }
        sessions.insert(
            user_id.clone(),
            Session {
                user_id,
                last_accessed: time::Instant::now(),
            },
        );
        Ok(())
    }

    async fn logout(&self, user_id: String) -> Result<(), String> {
        let mut sessions = self.sessions.lock().unwrap();
        if sessions.remove(&user_id).is_none() {
            return Err("Session not found".to_string());
        }
        Ok(())
    }

