#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    size_t size;
    long *data;
} Record;

typedef struct RBNode {
    Record data;
    struct RBNode *left, *right, *parent;
    int color; // 0 for black, 1 for red
} RBNode;

typedef struct RBTree {
    RBNode *root;
    pthread_mutex_t lock;
} RBTree;

RBNode* create_node(Record data) {
    RBNode* node = (RBNode*)malloc(sizeof(RBNode));
    if (!node) return NULL;
    node->data = data;
    node->left = node->right = node->parent = NULL;
    node->color = 1; // Red
    return node;
}

void left_rotate(RBTree *tree, RBNode *x) {
    RBNode *y = x->right;
    x->right = y->left;
    if (y->left != NULL)
        y->left->parent = x;
    y->parent = x->parent;
    if (x->parent == NULL)
        tree->root = y;
    else if (x == x->parent->left)
        x->parent->left = y;
    else
        x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void right_rotate(RBTree *tree, RBNode *y) {
    RBNode *x = y->left;
    y->left = x->right;
    if (x->right != NULL)
        x->right->parent = y;
    x->parent = y->parent;
    if (y->parent == NULL)
        tree->root = x;
    else if (y == y->parent->right)
        y->parent->right = x;
    else
        y->parent->left = x;
    x->right = y;
    y->parent = x;
}

void insert_fixup(RBTree *tree, RBNode *z) {
    while (z->parent != NULL && z->parent->color == 1) {
        if (z->parent == z->parent->parent->left) {
            RBNode *y = z->parent->parent->right;
            if (y != NULL && y->color == 1) {
                z->parent->color = 0;
                y->color = 0;
                z->parent->parent->color = 1;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(tree, z);
                }
                z->parent->color = 0;
                z->parent->parent->color = 1;
                right_rotate(tree, z->parent->parent);
            }
        } else {
            RBNode *y = z->parent->parent->left;
            if (y != NULL && y->color == 1) {
                z->parent->color = 0;
                y->color = 0;
                z->parent->parent->color = 1;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(tree, z);
                }
                z->parent->color = 0;
                z->parent->parent->color = 1;
                left_rotate(tree, z->parent->parent);
            }
        }
    }
    tree->root->color = 0;
}

void insert(RBTree *tree, Record data) {
    pthread_mutex_lock(&tree->lock);
    RBNode *z = create_node(data);
    if (z == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&tree->lock);
        return;
    }
    RBNode *y = NULL;
    RBNode *x = tree->root;

    while (x != NULL) {
        y = x;
        if (z->data.value < x->data.value)
            x = x->left;
        else
            x = x->right;
    }

    z->parent = y;
    if (y == NULL)
        tree->root = z;
    else if (z->data.value < y->data.value)
        y->left = z;
    else
        y->right = z;

    insert_fixup(tree, z);
    pthread_mutex_unlock(&tree->lock);
}

void inorder_traversal(RBNode *root) {
    if (root != NULL) {
        inorder_traversal(root->left);
        printf("%d ", root->data.value);
        inorder_traversal(root->right);
    }
}

void free_tree(RBNode *node) {
    if (node != NULL) {
        free_tree(node->left);
        free_tree(node->right);
        free(node);
    }
}

int main() {
    RBTree tree;
    pthread_mutex_init(&tree.lock, NULL);
    tree.root = NULL;

    // Simulate data insertion
    for (int i = 0; i < 1000000; i++) {
        Record data = {rand(), sizeof(int), (long*)malloc(sizeof(int))};
        insert(&tree, data);
    }

    inorder_traversal(tree.root);

    free_tree(tree.root);
    pthread_mutex_destroy(&tree.lock);

    return 0;
}
```

This code snippet provides a basic implementation of a red-black tree in C with thread safety and memory management considerations. It includes functions for inserting records into the tree, performing an in-order traversal, and freeing the allocated memory. The `main` function demonstrates how to use these functions to manage a stream of integers.']

