typedef struct {
    int* value;
} record;

void manage_memory(long num_elements, long max_index_range, int key_range) {
    srand(time(NULL)); // Seed for reproducibility

    // Allocate memory for offsets
    long* offsets = (long*)malloc(num_elements * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    // Initialize offsets with index + random value
    for (long i = 0; i < num_elements; i++) {
        offsets[i] = i + rand() % max_index_range;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc(num_elements * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return;
    }

    // Initialize keys with unique values within the specified range
    for (long i = 0; i < num_elements; i++) {
        int key;
        do {
            key = rand() % key_range;
        } while (is_key_used(keys, num_elements, key));
        keys[i] = key;
    }

    // Allocate memory for records
    record* records = (record*)malloc(num_elements * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize records with pointers to dynamically allocated int values
    for (long i = 0; i < num_elements; i++) {
        records[i].value = (int*)malloc(sizeof(int));
        if (records[i].value == NULL) {
            fprintf(stderr, "Memory allocation failed for record %ld\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        *records[i].value = rand() % key_range;
    }

    // Free allocated memory
    for (long i = 0; i < num_elements; i++) {
        free(records[i].value);
    }
    free(offsets);
    free(keys);
    free(records);
}

int is_key_used(int* keys, long num_elements, int key) {
    for (long i = 0; i < num_elements; i++) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}
