    int height;
} Node;

Node* newNode(Record data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->left = node->right = NULL;
    node->height = 1; 
    return(node);
}

int max(int a, int b) {
    return (a > b)? a : b;
}

int height(Node *N) {
    if (N == NULL)
        return 0;
    return N->height;
}

Node *rightRotate(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;

    x->right = y;
    y->left = T2;

    y->height = max(height(y->left), height(y->right)) + 1;
    x->height = max(height(x->left), height(x->right)) + 1;

    return x;
}

Node *leftRotate(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;

    y->left = x;
    x->right = T2;

    x->height = max(height(x->left), height(x->right)) + 1;
    y->height = max(height(y->left), height(y->right)) + 1;

    return y;
}

int getBalance(Node *N) {
    if (N == NULL)
        return 0;
    return height(N->left) - height(N->right);
}

Node* insert(Node* node, Record data) {
    if (node == NULL)
        return(newNode(data));

    if (data.value < node->data.value)
        node->left = insert(node->left, data);
    else if (data.value > node->data.value)
        node->right = insert(node->right, data);
    else
        return node;

    node->height = 1 + max(height(node->left), height(node->right));

    int balance = getBalance(node);

    if (balance > 1 && data.value < node->left->data.value)
        return rightRotate(node);

    if (balance < -1 && data.value > node->right->data.value)
        return leftRotate(node);

    if (balance > 1 && data.value > node->left->data.value) {
        node->left = leftRotate(node->left);
        return rightRotate(node);
    }

    if (balance < -1 && data.value < node->right->data.value) {
        node->right = rightRotate(node->right);
        return leftRotate(node);
    }

    return node;
}

Record* createRecord(int value, size_t size, long *offset) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    record->size = size;
    record->offset = offset;
    return record;
}

void freeRecord(Record *record) {
    free(record);
}

void freeNode(Node* node) {
    if (node == NULL)
        return;
    freeNode(node->left);
    freeNode(node->right);
    freeRecord(&node->data);
    free(node);
}

int main() {
    srand(time(NULL));
    Node *root = NULL;

    int n, value;
    printf("Enter number of elements: ");
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        printf("Enter element %d: ", i + 1);
        scanf("%d", &value);
        Record *record = createRecord(value, sizeof(int), NULL);
        root = insert(root, *record);
        free(record);
    }

    Node *current = root;
    while (current->right != NULL) {
        current = current->right;
    }
    printf("Largest element: %d\n", current->data.value);

    freeNode(root);
    return 0;
}
