['```java
import java.util.*;
import java.time.*;
import java.util.concurrent.*;

public class MicroserviceManager {
    private Map<String, Service> services;
    private ExecutorService executor;
    private ScheduledExecutorService scheduler;
    private BlockingQueue<Alert> alertQueue;

    public MicroserviceManager() {
        services = new HashMap<>();
        executor = Executors.newFixedThreadPool(10);
        scheduler = Executors.newScheduledThreadPool(2);
        alertQueue = new LinkedBlockingQueue<>(100);
    }

    public void addService(String id, int startHour, int endHour) {
        Service service = new Service(id, startHour, endHour);
        services.put(id, service);
        scheduleHealthCheck(service);
    }

    private void scheduleHealthCheck(Service service) {
        scheduler.scheduleAtFixedRate(() -> {
            if (service.isHealthy()) {
                logEvent("Service " + service.getId() + " is healthy.");
            } else {
                logEvent("Service " + service.getId() + " is unhealthy.");
                sendAlert(service);
            }
        }, 0, 10, TimeUnit.MINUTES);
    }

    private void sendAlert(Service service) {
        Alert alert = new Alert(service.getId(), LocalDateTime.now());
        try {
            alertQueue.put(alert);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void startService(String id) {
        Service service = services.get(id);
        if (service != null && !service.isActive()) {
            executor.submit(() -> {
                try {
                    service.start();
                    logEvent("Service " + id + " started.");
                } catch (Exception e) {
                    logEvent("Failed to start service " + id + ": " + e.getMessage());
                }
            });
        }
    }

    public void stopService(String id) {
        Service service = services.get(id);
        if (service != null && service.isActive()) {
            executor.submit(() -> {
                try {
                    service.stop();
                    logEvent("Service " + id + " stopped.");
                } catch (Exception e) {
                    logEvent("Failed to stop service " + id + ": " + e.getMessage());
                }
            });
        }
    }

    private void logEvent(String message) {
        System.out.println(LocalDateTime.now() + " - " + message);
    }

    public static void main(String[] args) {
        MicroserviceManager manager = new MicroserviceManager();
        manager.addService("service1", 9, 17);
        manager.addService("service2", 8, 16);

        // Simulate service start and stop
        manager.startService("service1");
        manager.stopService("service2");

        // Process alerts
        while (true) {
            try {
                Alert alert = manager.alertQueue.take();
                System.out.println("Alert: " + alert);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    static class Service {
        private String id;
        private int startHour;
        private int endHour;
        private boolean active;

        public Service(String id, int startHour, int endHour) {
            this.id = id;
            this.startHour = startHour;
            this.endHour = endHour;
            this.active = false;
        }

        public String getId() {
            return id;
        }

        public boolean isActive() {
            return active;
        }

        public void start() throws Exception {
            if (LocalTime.now().getHour() >= startHour && LocalTime.now().getHour() < endHour) {
                active = true;
            } else {
                throw new Exception("Service is outside operational hours.");
            }
        }

        public void stop() throws Exception {
            active = false;
        }

        public boolean isHealthy() {
            // Implement health check logic
            return true;
        }
    }

    static class Alert {
        private String serviceId;
        private LocalDateTime timestamp;

        public Alert(String serviceId, LocalDateTime timestamp) {
            this.serviceId = serviceId;
            this.timestamp = timestamp;
        }

        @Override
        public String toString() {
            return "Alert{" +
                    "serviceId='" + serviceId + '\'' +
                    ", timestamp=" + timestamp +
                    '}';
        }
    }
}
