    if (num_records > 1000) {
        printf("Error: Maximum of 1000 records allowed.\n");
        return NULL;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets.\n");
        return NULL;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        printf("Memory allocation failed for keys.\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed for records.\n");
        return NULL;
    }

    time_t current_time = time(NULL);
    struct tm* local_time = localtime(&current_time);

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = i * 100L; // Example offset calculation
        keys[i] = rand() % 5000; // Example key generation

        records[i].offset = offsets[i];
        records[i].key = keys[i];

        if (resolution == 1) { // Seconds resolution
            records[i].timestamp = local_time->tm_sec;
        } else if (resolution == 3) { // Milliseconds resolution
            records[i].timestamp = local_time->tm_sec + (local_time->tm_usec / 1000.0);
        }

        snprintf(records[i].description, sizeof(records[i].description), "Record %d", i);
    }

    free(offsets);
    free(keys);

    return records;
}

void print_records(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        printf("Offset: %ld, Key: %d, Timestamp: %.3f, Description: %s\n",
               records[i].offset, records[i].key, records[i].timestamp, records[i].description);
    }
}

int main() {
    int num_records = 500;
    record* my_records = create_records(num_records, 1); // 1 for seconds resolution
    if (my_records) {
        print_records(my_records, num_records);
        free(my_records);
    }
    return 0;
}
