typedef struct record {
    int value;
    size_t size;
    time_t timestamp;
    int *key_ptr;
} record;

typedef struct bst_node {
    int key;
    record *data;
    struct bst_node *left, *right;
} bst_node;

bst_node* create_bst_node(int key, record *data) {
    bst_node* node = (bst_node*)malloc(sizeof(bst_node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    node->key = key;
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

bst_node* insert_bst(bst_node* root, int key, record *data) {
    if (root == NULL) return create_bst_node(key, data);

    if (key < root->key)
        root->left = insert_bst(root->left, key, data);
    else if (key > root->key)
        root->right = insert_bst(root->right, key, data);

    return root;
}

void inorder_traversal(bst_node* root) {
    if (root != NULL) {
        inorder_traversal(root->left);
        printf("Key: %d, Value: %d\n", root->key, root->data->value);
        inorder_traversal(root->right);
    }
}

int find_largest_key(bst_node* root) {
    while (root->right != NULL)
        root = root->right;
    return root->key;
}

void free_bst(bst_node* node) {
    if (node == NULL) return;
    free_bst(node->left);
    free_bst(node->right);
    free(node);
}

int main() {
    bst_node *root = NULL;

    // Example usage
    record data1 = {10, 256, time(NULL), NULL};
    root = insert_bst(root, 5, &data1);

    record data2 = {20, 512, time(NULL), NULL};
    root = insert_bst(root, 10, &data2);

    inorder_traversal(root);
    printf("Largest Key: %d\n", find_largest_key(root));

    free_bst(root);
    return 0;
}
