#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FILES 10000

typedef struct {
    size_t size;
    time_t timestamp;
    int status; // active, inactive, deleted
} data_record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

time_t get_current_timestamp() {
    return time(NULL);
}

void process_and_manage_data_blocks() {
    size_t* block_sizes = allocate_memory(MAX_FILES * sizeof(size_t));
    void** data_pointers = allocate_memory(MAX_FILES * sizeof(void*));
    data_record* records = allocate_memory(MAX_FILES * sizeof(data_record));

    // Initialize arrays
    for (int i = 0; i < MAX_FILES; i++) {
        block_sizes[i] = 0;
        data_pointers[i] = NULL;
        records[i].size = 0;
        records[i].timestamp = 0;
        records[i].status = 0;
    }

    // Read file paths from standard input
    char file_paths[MAX_FILES][256];
    int count = 0;
    while (fgets(file_paths[count], sizeof(file_paths[count]), stdin) != NULL && count < MAX_FILES) {
        file_paths[count][strcspn(file_paths[count], "\n")] = '\0';
        count++;
    }

    // Asynchronously read files and store data
    pthread_t threads[MAX_FILES];
    for (int i = 0; i < count; i++) {
        int* index = allocate_memory(sizeof(int));
        *index = i;
        if (pthread_create(&threads[i], NULL, read_file_async, (void*)index) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Search for the largest data block and print details
    size_t max_size = 0;
    int max_index = -1;
    for (int i = 0; i < count; i++) {
        if (block_sizes[i] > max_size) {
            max_size = block_sizes[i];
            max_index = i;
        }
    }

    if (max_index != -1) {
        printf("Largest data block details:\n");
        printf("File Path: %s\n", file_paths[max_index]);
        printf("Size: %zu bytes\n", max_size);
        printf("Timestamp: %s", ctime(&records[max_index].timestamp));
    } else {
        printf("No data blocks found.\n");
    }

    // Free all allocated memory
    free(block_sizes);
    for (int i = 0; i < count; i++) {
        if (data_pointers[i] != NULL) {
            free(data_pointers[i]);
        }
    }
    free(data_pointers);
    free(records);

    printf("Memory freed successfully.\n");
}

void* read_file_async(void* arg) {
    int index = *(int*)arg;
    FILE* file = fopen(file_paths[index], "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", file_paths[index]);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    fseek(file, 0, SEEK_SET);

    void* buffer = allocate_memory(size);
    if (fread(buffer, 1, size, file) != size) {
        fprintf(stderr, "Failed to read file: %s\n", file_paths[index]);
        free(buffer);
        fclose(file);
        return NULL;
    }

    block_sizes[index] = size;
    data_pointers[index] = buffer;
    records[index].size = size;
    records[index].timestamp = get_current_timestamp();
    records[index].status = 1; // active

    fclose(file);
    free(arg);

    return NULL;
}
