import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.rabbit.connection.ConnectionFactory;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

@Configuration
public class AuthenticationConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public Queue authenticationQueue() {
        return new Queue("authenticationQueue", true);
    }

    @Bean
    public RabbitTemplate rabbitTemplate(ConnectionFactory connectionFactory) {
        RabbitTemplate template = new RabbitTemplate(connectionFactory);
        template.setMessageConverter(new Jackson2JsonMessageConverter());
        return template;
    }

    @Bean
    public JwtTokenProvider jwtTokenProvider() {
        return new JwtTokenProvider("yourSecretKey");
    }
}

class JwtTokenProvider {

    private String secretKey;

    public JwtTokenProvider(String secretKey) {
        this.secretKey = secretKey;
    }

    public String createToken(String username, long expirationMillis) {
        Claims claims = Jwts.claims().setSubject(username);
        Date now = new Date();
        return Jwts.builder()
                .setClaims(claims)
                .setIssuedAt(now)
                .setExpiration(new Date(now.getTime() + expirationMillis))
                .signWith(SignatureAlgorithm.HS256, secretKey)
                .compact();
    }

    public boolean validateToken(String token) {
        try {
            Jwts.parser().setSigningKey(secretKey).parseClaimsJws(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public String getUsernameFromToken(String token) {
        return Jwts.parser().setSigningKey(secretKey).parseClaimsJws(token).getBody().getSubject();
    }
}

class RateLimiter {

    private Map<String, Integer> loginAttempts = new ConcurrentHashMap<>();
    private int maxAttempts;
    private long timeWindow;

    public RateLimiter(int maxAttempts, long timeWindow) {
        this.maxAttempts = maxAttempts;
        this.timeWindow = timeWindow;
    }

    public boolean allowLogin(String username) {
        loginAttempts.putIfAbsent(username, 0);
        if (loginAttempts.get(username) >= maxAttempts) {
            return false;
        }
        loginAttempts.put(username, loginAttempts.get(username) + 1);
        new Thread(() -> {
            try {
                Thread.sleep(timeWindow);
                loginAttempts.remove(username);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }).start();
        return true;
    }
}

class SessionManager {

    private Map<String, String> sessionTokens = new ConcurrentHashMap<>();

    public void extendSession(String username, String token) {
        sessionTokens.put(username, token);
    }

    public boolean validateSession(String username, String token) {
        return token.equals(sessionTokens.get(username));
    }
}

