#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_OPERATIONS 1000

typedef struct {
    double value;
    char* name;
} Element;

typedef struct {
    double number;
    char* expression;
    Element* element;
    double coefficient;
    size_t operation_type;
} Operation;

typedef struct {
    Operation* operations;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} OperationManager;

OperationManager* create_operation_manager() {
    OperationManager* manager = (OperationManager*)malloc(sizeof(OperationManager));
    if (!manager) {
        perror("Failed to allocate memory for operation manager");
        return NULL;
    }
    manager->operations = (Operation*)calloc(MAX_OPERATIONS, sizeof(Operation));
    if (!manager->operations) {
        perror("Failed to allocate memory for operations array");
        free(manager);
        return NULL;
    }
    manager->count = 0;
    manager->capacity = MAX_OPERATIONS;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_operation_manager(OperationManager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->operations[i].expression);
            free(manager->operations[i].element->name);
            free(manager->operations[i].element);
        }
        free(manager->operations);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

int add_operation(OperationManager* manager, double number, const char* expression, Element* element, double coefficient, size_t operation_type) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        Operation* new_operations = (Operation*)realloc(manager->operations, manager->capacity * 2 * sizeof(Operation));
        if (!new_operations) {
            perror("Failed to reallocate memory for operations array");
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->operations = new_operations;
        manager->capacity *= 2;
    }
    manager->operations[manager->count].number = number;
    manager->operations[manager->count].expression = strdup(expression);
    if (!manager->operations[manager->count].expression) {
        perror("Failed to allocate memory for expression string");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }
    manager->operations[manager->count].element = element;
    manager->operations[manager->count].coefficient = coefficient;
    manager->operations[manager->count].operation_type = operation_type;
    ++manager->count;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

// Example usage
int main() {
    OperationManager* manager = create_operation_manager();
    if (!manager) {
        return -1;
    }

    Element element = {3.14, "pi"};
    add_operation(manager, 2.0, "x + y", &element, 1.5, 1);

    destroy_operation_manager(manager);
    return 0;
}
```

This code snippet demonstrates a basic implementation of an `OperationManager` struct that manages a collection of mathematical operations dynamically. It includes functions to create and destroy the manager, as well as add operations to it. The operations are stored in a dynamically allocated array, and memory is managed using `malloc`, `calloc`, and `realloc`. Error handling is included for memory allocation failures.

The code also demonstrates thread safety by using a mutex to protect shared resources during operation addition. This ensures that concurrent access from multiple threads does not lead to race conditions or data corruption.

This implementation provides a foundation for managing mathematical operations dynamically, but it can be further optimized and extended based on specific requirements and constraints of the application.']

