char* string_list[STRING_LIST_SIZE] = {"apple", "banana", "cherry", /* ... */};

int initialize_records(record** records, int limit, long min_offset, long max_offset, int min_key, int max_key) {
    srand(time(NULL));
    int count = 0;
    for (int i = 0; i < limit; i++) {
        record* new_record = malloc(sizeof(record));
        if (!new_record) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }

        // Allocate string from predefined list
        int random_index = rand() % STRING_LIST_SIZE;
        new_record->str = strdup(string_list[random_index]);
        if (!new_record->str) {
            free(new_record);
            fprintf(stderr, "String allocation failed\n");
            return -1;
        }

        // Initialize other fields with random values
        new_record->offset = min_offset + rand() % (max_offset - min_offset + 1);
        new_record->key = min_key + rand() % (max_key - min_key + 1);

        records[count++] = new_record;

        if (count >= MAX_RECORDS) {
            fprintf(stderr, "Maximum number of records reached\n");
            break;
        }
    }

    return count;
}

void free_records(record** records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]->str);
        free(records[i]);
    }
}

int main() {
    record* records[MAX_RECORDS];
    int limit = 500;
    long min_offset = 100;
    long max_offset = 1000;
    int min_key = 1;
    int max_key = 100;

    int count = initialize_records(records, limit, min_offset, max_offset, min_key, max_key);
    if (count >= 0) {
        printf("Successfully initialized %d records\n", count);
        free_records(records, count);
    }

    return 0;
}
