#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1MB

typedef struct {
    int value;
    long* offset_ptr;
} record;

int allocate_memory(int long_size, int int_size, record** records) {
    size_t total_size = sizeof(long) * long_size + sizeof(int) * int_size + sizeof(record) * int_size;
    if (total_size > MAX_MEMORY) {
        return -1; // Memory allocation exceeds limit
    }

    long* offsets = (long*)malloc(sizeof(long) * long_size);
    if (!offsets) {
        return -2; // Failed to allocate memory for offsets
    }

    int* keys = (int*)malloc(sizeof(int) * int_size);
    if (!keys) {
        free(offsets); // Clean up partial allocation
        return -3; // Failed to allocate memory for keys
    }

    record* records_array = (record*)malloc(sizeof(record) * int_size);
    if (!records_array) {
        free(offsets);
        free(keys); // Clean up partial allocation
        return -4; // Failed to allocate memory for records
    }

    srand(time(NULL));
    for (int i = 0; i < int_size; i++) {
        keys[i] = rand() % 1001;
        offsets[i] = rand() % long_size;
        if (offsets[i] >= long_size) {
            free(offsets);
            free(keys);
            free(records_array); // Clean up partial allocation
            return -5; // Invalid pointer index
        }
        records_array[i].value = 0;
        records_array[i].offset_ptr = &offsets[offsets[i]];
    }

    *records = records_array;
    return 0; // Success
}

void free_memory(record* records, int size) {
    if (records) {
        for (int i = 0; i < size; i++) {
            records[i].offset_ptr = NULL;
        }
        free(records);
    }
}

int main() {
    int long_size, int_size;
    printf("Enter the number of long values: ");
    scanf("%d", &long_size);
    printf("Enter the number of int keys: ");
    scanf("%d", &int_size);

    record* records;
    int result = allocate_memory(long_size, int_size, &records);
    if (result != 0) {
        printf("Memory allocation failed with error code %d\n", result);
        return 1;
    }

    // Use the records array...

    free_memory(records, int_size);

    return 0;
}
