        records[i].string_ptr = strdup(string_list[random_index].data);
        records[i].offset = rand() % 1000L;
        records[i].key = rand() % 1000;
        records[i].value = rand() % 1000;
        snprintf(records[i].name, sizeof(records[i].name), "Name%d", i);
        records[i].flag = (rand() % 2 == 0) ? true : false;

        // Initialize metadata
        records[i].metadata.id = i;
        records[i].metadata.is_valid = true;

        // Simulate nested record creation
        if (i < limit - 1) {
            records[i].nested_record = &records[i + 1];
        } else {
            records[i].nested_record = NULL;
        }
    }

    return records;
}

void free_records(Record* records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i].string_ptr);
    }
    free(records);
}

int main() {
    String string_list[STRING_LIST_SIZE];
    // Populate string_list with predefined strings

    Record* records = create_records(MAX_RECORDS, string_list, STRING_LIST_SIZE);
    if (records) {
        printf("Records created successfully.\n");
        free_records(records, MAX_RECORDS);
    } else {
        printf("Failed to create records.\n");
    }

    return 0;
}
