#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 15000
#define MIN_STRING_LENGTH 10
#define MAX_STRING_LENGTH 1024
#define ALIGNMENT 64

typedef struct {
    int key;
    long offset;
    char *data_block;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    size_t count;
} MemoryPool;

MemoryPool pool;

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment);
    if (!ptr) return NULL;
    void *aligned_ptr = (void*)(((size_t)ptr + alignment - 1) & ~(alignment - 1));
    ((void**)aligned_ptr)[-1] = ptr;
    return aligned_ptr;
}

void aligned_free(void *ptr) {
    free(((void**)ptr)[-1]);
}

int process_and_find_max(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <max_string_length>\n", argv[0]);
        return 1;
    }

    int max_string_length = atoi(argv[1]);
    if (max_string_length < MIN_STRING_LENGTH || max_string_length > MAX_STRING_LENGTH) {
        fprintf(stderr, "Invalid string length. Must be between %d and %d.\n", MIN_STRING_LENGTH, MAX_STRING_LENGTH);
        return 1;
    }

    pool.count = 0;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        Record *record = &pool.records[i];
        record->key = rand();
        record->offset = rand() % 1000000L;
        int string_length = rand() % (max_string_length - MIN_STRING_LENGTH + 1) + MIN_STRING_LENGTH;
        record->data_block = aligned_malloc(string_length, ALIGNMENT);
        if (!record->data_block) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            return 1;
        }
        memset(record->data_block, 'A', string_length - 1);
        record->data_block[string_length - 1] = '\0';
        pool.count++;
    }

    int *input_array = (int*)aligned_malloc(pool.count * sizeof(int), ALIGNMENT);
    if (!input_array) {
        fprintf(stderr, "Memory allocation failed for input array\n");
        return 1;
    }

    printf("Enter %zu integers:\n", pool.count);
    for (size_t i = 0; i < pool.count; ++i) {
        scanf("%d", &input_array[i]);
    }

    int max_value = input_array[0];
    for (size_t i = 1; i < pool.count; ++i) {
        if (input_array[i] > max_value) {
            max_value = input_array[i];
        }
    }

    printf("The largest integer is: %d\n", max_value);

    aligned_free(input_array);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        aligned_free(pool.records[i].data_block);
    }

    return 0;
}
