int find_max(int* array, size_t size) {
    if (size == 0) return -1; // Assuming no elements means invalid input
    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void process_and_find_max(size_t num_records, long min_offset, long max_offset, int range_min, int range_max) {
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    long* offsets = malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        free(records);
        return;
    }

    int* input_array = NULL;
    size_t array_size = 0;

    // Simulate reading integers from standard input
    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;
        input_array = realloc(input_array, (array_size + 1) * sizeof(int));
        if (!input_array) {
            fprintf(stderr, "Memory allocation failed for input array\n");
            free(records);
            free(offsets);
            return;
        }
        input_array[array_size++] = num;
    }

    int max_value = find_max(input_array, array_size);
    printf("Largest integer in the array: %d\n", max_value);

    // Clean up
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].data_block);
    }
    free(records);
    free(offsets);
    free(input_array);
}

int main() {
    size_t num_records;
    long min_offset, max_offset;
    int range_min, range_max;

    // Example usage
    printf("Enter number of records: ");
    scanf("%zu", &num_records);
    printf("Enter minimum and maximum offset values: ");
    scanf("%ld %ld", &min_offset, &max_offset);
    printf("Enter minimum and maximum data block size range: ");
    scanf("%d %d", &range_min, &range_max);

    process_and_find_max(num_records, min_offset, max_offset, range_min, range_max);

    return 0;
}
