#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct rb_node {
    int key;
    long offset;
    Record *record;
    struct rb_node *left, *right, *parent;
    int color; // 0 for red, 1 for black
} RBNode;

typedef struct rb_tree {
    RBNode *root;
    RBNode *NIL;
} RBTree;

RBNode* create_node(int key, long offset) {
    RBNode *new_node = (RBNode*)malloc(sizeof(RBNode));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->key = key;
    new_node->offset = offset;
    new_node->record = (Record*)malloc(sizeof(Record));
    if (!new_node->record) {
        free(new_node);
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->record->value = rand() % 100; // Random value between 0 and 99
    new_node->left = NULL;
    new_node->right = NULL;
    new_node->parent = NULL;
    new_node->color = 0; // Red
    return new_node;
}

RBTree* create_tree() {
    RBTree *tree = (RBTree*)malloc(sizeof(RBTree));
    if (!tree) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    tree->NIL = create_node(0, 0); // Sentinel node
    tree->root = tree->NIL;
    return tree;
}

void left_rotate(RBTree *tree, RBNode *x) {
    RBNode *y = x->right;
    x->right = y->left;
    if (y->left != tree->NIL) {
        y->left->parent = x;
    }
    y->parent = x->parent;
    if (x->parent == tree->NIL) {
        tree->root = y;
    } else if (x == x->parent->left) {
        x->parent->left = y;
    } else {
        x->parent->right = y;
    }
    y->left = x;
    x->parent = y;
}

void right_rotate(RBTree *tree, RBNode *y) {
    RBNode *x = y->left;
    y->left = x->right;
    if (x->right != tree->NIL) {
        x->right->parent = y;
    }
    x->parent = y->parent;
    if (y->parent == tree->NIL) {
        tree->root = x;
    } else if (y == y->parent->right) {
        y->parent->right = x;
    } else {
        y->parent->left = x;
    }
    x->right = y;
    y->parent = x;
}

void insert_fixup(RBTree *tree, RBNode *z) {
    while (z->parent->color == 0) {
        if (z->parent == z->parent->parent->left) {
            RBNode *y = z->parent->parent->right;
            if (y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    z = z->parent;
                    left_rotate(tree, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                right_rotate(tree, z->parent->parent);
            }
        } else {
            RBNode *y = z->parent->parent->left;
            if (y->color == 0) {
                z->parent->color = 1;
                y->color = 1;
                z->parent->parent->color = 0;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(tree, z);
                }
                z->parent->color = 1;
                z->parent->parent->color = 0;
                left_rotate(tree, z->parent->parent);
            }
        }
    }
    tree->root->color = 1;
}

void insert(RBTree *tree, int key, long offset) {
    RBNode *z = create_node(key, offset);
    RBNode *y = tree->NIL;
    RBNode *x = tree->root;

    while (x != tree->NIL) {
        y = x;
        if (z->key < x->key) {
            x = x->left;
        } else {
            x = x->right;
        }
    }

    z->parent = y;
    if (y == tree->NIL) {
        tree->root = z;
    } else if (z->key < y->key) {
        y->left = z;
    } else {
        y->right = z;
    }

    z->left = tree->NIL;
    z->right = tree->NIL;
    z->color = 0;

    insert_fixup(tree, z);
}

int find_max(RBTree *tree) {
    RBNode *current = tree->root;
    while (current->right != tree->NIL) {
        current = current->right;
    }
    return current->key;
}

void free_tree(RBTree *tree, RBNode *node) {
    if (node == tree->NIL) {
        return;
    }
    free_tree(tree, node->left);
    free_tree(tree, node->right);
    free(node->record);
    free(node);
}

int main() {
    srand(time(NULL));
    RBTree *tree = create_tree();

    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        int key, offset;
        printf("Enter integer %d and its offset: ", i + 1);
        scanf("%d %ld", &key, &offset);
        insert(tree, key, offset);
    }

    printf("Largest integer in the array: %d\n", find_max(tree));

    free_tree(tree, tree->root);

    return 0;
}
