#define MAX_LOG_ENTRIES 1024
#define MAX_CATEGORIES 32

typedef struct LogEntry {
    int id;
    time_t timestamp;
    int category_count;
    char **categories;
    void *data_block;
    size_t data_size;
} LogEntry;

typedef struct LogStorage {
    LogEntry entries[MAX_LOG_ENTRIES];
    pthread_mutex_t lock;
} LogStorage;

LogStorage log_storage;

void init_log_storage() {
    memset(&log_storage, 0, sizeof(log_storage));
    pthread_mutex_init(&log_storage.lock, NULL);
}

int create_log_entry(int *id) {
    pthread_mutex_lock(&log_storage.lock);
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        if (!log_storage.entries[i].id) {
            log_storage.entries[i].id = rand();
            *id = log_storage.entries[i].id;
            pthread_mutex_unlock(&log_storage.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&log_storage.lock);
    return -1; // No available entries
}

int update_log_entry(int id, time_t timestamp, int category_count, char **categories, void *data_block, size_t data_size) {
    pthread_mutex_lock(&log_storage.lock);
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        if (log_storage.entries[i].id == id) {
            log_storage.entries[i].timestamp = timestamp;
            log_storage.entries[i].category_count = category_count;
            log_storage.entries[i].categories = categories;
            log_storage.entries[i].data_block = data_block;
            log_storage.entries[i].data_size = data_size;
            pthread_mutex_unlock(&log_storage.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&log_storage.lock);
    return -1; // Entry not found
}

int delete_log_entry(int id) {
    pthread_mutex_lock(&log_storage.lock);
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        if (log_storage.entries[i].id == id) {
            log_storage.entries[i].id = 0;
            pthread_mutex_unlock(&log_storage.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&log_storage.lock);
    return -1; // Entry not found
}

void *get_log_entry_data(int id, size_t *data_size) {
    pthread_mutex_lock(&log_storage.lock);
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        if (log_storage.entries[i].id == id) {
            *data_size = log_storage.entries[i].data_size;
            void *data_block = malloc(log_storage.entries[i].data_size);
            memcpy(data_block, log_storage.entries[i].data_block, log_storage.entries[i].data_size);
            pthread_mutex_unlock(&log_storage.lock);
            return data_block;
        }
    }
    pthread_mutex_unlock(&log_storage.lock);
    return NULL; // Entry not found
}

void free_log_entry_data(void *data_block) {
    free(data_block);
}
