#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    size_t size;
    long *offset;
} record;

long* allocate_and_process_records(int num_records, int min_val, int max_val) {
    // Allocate memory for arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    record *records = (record *)malloc(num_records * sizeof(record));
    int *sorted_order = (int *)malloc(num_records * sizeof(int));

    if (!offsets || !keys || !records || !sorted_order) {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        free(sorted_order);
        return NULL;
    }

    // Initialize records with random values and offsets
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i];
        records[i].size = sizeof(int);
        offsets[i] = i * sizeof(record); // Simplified for demonstration
        records[i].offset = &offsets[i];
    }

    // Sort records based on integer values using a stable sorting algorithm
    qsort(records, num_records, sizeof(record), compare_records);

    // Populate sorted_order array with indices of sorted records
    for (int i = 0; i < num_records; ++i) {
        sorted_order[i] = i;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return sorted_order;
}

int compare_records(const void *a, const void *b) {
    record *record_a = (record *)a;
    record *record_b = (record *)b;
    if (record_a->value < record_b->value) return -1;
    if (record_a->value > record_b->value) return 1;
    return 0;
}

int main() {
    int num_records, min_val, max_val;
    printf("Enter number of records: ");
    scanf("%d", &num_records);
    printf("Enter minimum value for random numbers: ");
    scanf("%d", &min_val);
    printf("Enter maximum value for random numbers: ");
    scanf("%d", &max_val);

    long *sorted_order = allocate_and_process_records(num_records, min_val, max_val);
    if (sorted_order) {
        printf("Sorted order of records based on integer values:\n");
        for (int i = 0; i < num_records; ++i) {
            printf("%d ", sorted_order[i]);
        }
        free(sorted_order);
    }

    return 0;
}
