#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char name[256];
    int size;
    time_t last_modified;
} FileMetadata;

typedef struct {
    FileMetadata *files;
    int count;
    pthread_mutex_t lock;
} FileSystem;

FileSystem* create_file_system() {
    FileSystem *fs = (FileSystem*)malloc(sizeof(FileSystem));
    fs->files = NULL;
    fs->count = 0;
    pthread_mutex_init(&fs->lock, NULL);
    return fs;
}

void destroy_file_system(FileSystem *fs) {
    for (int i = 0; i < fs->count; i++) {
        free(fs->files[i].name);
    }
    free(fs->files);
    pthread_mutex_destroy(&fs->lock);
    free(fs);
}

int add_file(FileSystem *fs, const char *filename, int size) {
    pthread_mutex_lock(&fs->lock);
    FileMetadata *new_files = (FileMetadata*)realloc(fs->files, (fs->count + 1) * sizeof(FileMetadata));
    if (!new_files) {
        pthread_mutex_unlock(&fs->lock);
        return -1;
    }
    fs->files = new_files;
    strcpy(fs->files[fs->count].name, filename);
    fs->files[fs->count].size = size;
    time_t now = time(NULL);
    fs->files[fs->count].last_modified = now;
    fs->count++;
    pthread_mutex_unlock(&fs->lock);
    return 0;
}

int delete_file(FileSystem *fs, const char *filename) {
    pthread_mutex_lock(&fs->lock);
    for (int i = 0; i < fs->count; i++) {
        if (strcmp(fs->files[i].name, filename) == 0) {
            free(fs->files[i].name);
            memmove(&fs->files[i], &fs->files[i + 1], (fs->count - i - 1) * sizeof(FileMetadata));
            fs->count--;
            pthread_mutex_unlock(&fs->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&fs->lock);
    return -1;
}

int modify_file(FileSystem *fs, const char *filename, int new_size) {
    pthread_mutex_lock(&fs->lock);
    for (int i = 0; i < fs->count; i++) {
        if (strcmp(fs->files[i].name, filename) == 0) {
            fs->files[i].size = new_size;
            time_t now = time(NULL);
            fs->files[i].last_modified = now;
            pthread_mutex_unlock(&fs->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&fs->lock);
    return -1;
}
