typedef struct {
    long timestamp;
    int event_id;
    char *message;
} log_entry;

void set_log_entry(log_entry *entry, long timestamp, int event_id, const char *message) {
    entry->timestamp = timestamp;
    entry->event_id = event_id;
    entry->message = strdup(message);
}

log_entry* process_and_filter_records(int num_entries, long min_event_id, long max_event_id) {
    log_entry *entries = (log_entry*)malloc(num_entries * sizeof(log_entry));
    if (!entries) return NULL;

    for (int i = 0; i < num_entries; ++i) {
        set_log_entry(&entries[i], i * 1000, i % 10, "Event Message");
    }

    log_entry *filtered_entries = NULL;
    int filtered_count = 0;

    for (int i = 0; i < num_entries; ++i) {
        if (entries[i].event_id >= min_event_id && entries[i].event_id <= max_event_id) {
            filtered_entries = realloc(filtered_entries, (filtered_count + 1) * sizeof(log_entry));
            if (!filtered_entries) break;
            memcpy(&filtered_entries[filtered_count], &entries[i], sizeof(log_entry));
            ++filtered_count;
        }
    }

    free(entries);
    return filtered_entries;
}

void print_log_entries(const log_entry *entries, int count) {
    for (int i = 0; i < count; ++i) {
        printf("Timestamp: %ld, Event ID: %d, Message: %s\n", entries[i].timestamp, entries[i].event_id, entries[i].message);
    }
}

void free_log_entries(log_entry *entries, int count) {
    for (int i = 0; i < count; ++i) {
        free(entries[i].message);
    }
    free(entries);
}
