        free(col->records);
        col->records = NULL;
    }
    if (col->pool) {
        free(col->pool);
        col->pool = NULL;
    }
}

record* add_record(dynamic_collection* col, int data, size_t size) {
    if (col->count >= col->capacity) {
        col->capacity *= 2;
        col->records = (record*)realloc(col->records, col->capacity * sizeof(record));
    }
    record* new_record = &col->records[col->count++];
    new_record->data = data;
    new_record->size = size;
    return new_record;
}

