void* custom_allocator(size_t size, void* pool, size_t* pool_size) {
    if (pool && *pool_size >= size) {
        void* ptr = pool;
        pool += size;
        *pool_size -= size;
        return ptr;
    } else {
        return malloc(size);
    }
}

