#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct point {
    float x;
    float y;
} point;

typedef struct record {
    point point;
    double value;
    size_t length;
} record;

typedef struct event {
    int identifier;
    time_t timestamp;
    record *record_ptr;
} event;

void process_and_manage_memory(int load, int min_value, int max_value) {
    long *offsets = (long *)malloc(load * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return;
    }

    int *keys = (int *)malloc(load * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    record *records = (record *)calloc(load, sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    event *events = (event *)malloc(load * sizeof(event));
    if (!events) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Memory allocation failed for events\n");
        return;
    }

    double *float_values = (double *)malloc(load * sizeof(double));
    if (!float_values) {
        free(offsets);
        free(keys);
        free(records);
        free(events);
        fprintf(stderr, "Memory allocation failed for float values\n");
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < load; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 1000;
        records[i].point.x = (float)(rand() % 100) / 10.0f;
        records[i].point.y = (float)(rand() % 100) / 10.0f;
        records[i].value = ((double)(rand() % (max_value - min_value + 1)) + min_value);
        records[i].length = rand() % 1000;
        events[i].identifier = i;
        events[i].timestamp = time(NULL);
        events[i].record_ptr = &records[i];
        float_values[i] = ((double)(rand() % (max_value - min_value + 1)) + min_value);

        printf("Event %d: Record value set to %.2f at timestamp %ld\n", i, records[i].value, events[i].timestamp);
    }

    // Helper function to find and print the largest integer or double
    void print_largest(double *values, int size) {
        if (size == 0) {
            printf("Array is empty\n");
            return;
        }
        double max_value = values[0];
        for (int i = 1; i < size; i++) {
            if (values[i] > max_value) {
                max_value = values[i];
            }
        }
        printf("Largest value: %.2f\n", max_value);
    }

    print_largest(float_values, load);

    // Free all allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(events);
    free(float_values);
}

int main() {
    int load = 10;
    int min_value = 1;
    int max_value = 100;
    process_and_manage_memory(load, min_value, max_value);
    return 0;
}
