record* initialize_records(int initial_size, int min_value, int max_value) {
    if (initial_size <= 0 || min_value > max_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    record* records = malloc(initial_size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    long* offsets = malloc(initial_size * sizeof(long));
    if (!offsets) {
        free(records);
        perror("Failed to allocate memory for offsets.");
        return NULL;
    }

    int* keys = malloc(initial_size * sizeof(int));
    if (!keys) {
        free(offsets);
        free(records);
        perror("Failed to allocate memory for keys.");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));

    for (int i = 0; i < initial_size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].size = rand() % 1024 + 1; // Random size between 1 and 1023
        records[i].data = rand() % (max_value - min_value + 1) + min_value;

        offsets[i] = i * sizeof(record);
        keys[i] = i;
    }

    return records;
}

void free_records(record* records, long* offsets, int* keys, pthread_mutex_t* mutex) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
    pthread_mutex_destroy(mutex);
