typedef enum {
    CATEGORY_A,
    CATEGORY_B,
    CATEGORY_C
} Category;

typedef struct {
    double value;
    Category category;
    char* name;
} DataObject;

typedef struct {
    DataObject* objects;
    size_t count;
    pthread_mutex_t mutex;
} DataStore;

DataStore* allocate_and_initialize_data_store(size_t initial_capacity) {
    if (initial_capacity == 0) {
        return NULL; // Handle invalid input
    }

    DataStore* store = malloc(sizeof(DataStore));
    if (!store) {
        return NULL; // Handle memory allocation failure
    }

    store->objects = calloc(initial_capacity, sizeof(DataObject));
    if (!store->objects) {
        free(store);
        return NULL; // Handle memory allocation failure
    }

    store->count = initial_capacity;
    pthread_mutex_init(&store->mutex, NULL);

    return store;
}

void free_data_store(DataStore* store) {
    if (store) {
        for (size_t i = 0; i < store->count; ++i) {
            free(store->objects[i].name);
        }
        free(store->objects);
        pthread_mutex_destroy(&store->mutex);
        free(store);
    }
}

void set_random_value(DataObject* obj, double min, double max) {
    if (obj && min <= max) {
        obj->value = min + (max - min) * ((double)rand() / RAND_MAX);
    }
}

void initialize_data_store(DataStore* store, size_t count, Category category, const char* name_template) {
    pthread_mutex_lock(&store->mutex);
    if (count > store->count) {
        DataObject* new_objects = realloc(store->objects, count * sizeof(DataObject));
        if (!new_objects) {
            pthread_mutex_unlock(&store->mutex);
            return; // Handle memory allocation failure
        }
        store->objects = new_objects;
        store->count = count;
    }

    for (size_t i = 0; i < count; ++i) {
        store->objects[i].value = 0.0;
        store->objects[i].category = category;
        size_t name_length = snprintf(NULL, 0, name_template, i);
        store->objects[i].name = malloc(name_length + 1);
        if (!store->objects[i].name) {
            pthread_mutex_unlock(&store->mutex);
            return; // Handle memory allocation failure
        }
        snprintf(store->objects[i].name, name_length + 1, name_template, i);
    }

    pthread_mutex_unlock(&store->mutex);
}

void set_random_values_in_store(DataStore* store, double min, double max) {
    pthread_mutex_lock(&store->mutex);
    for (size_t i = 0; i < store->count; ++i) {
        set_random_value(&store->objects[i], min, max);
    }
    pthread_mutex_unlock(&store->mutex);
}
