void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* allocate_records(int num_records) {
    record *records = aligned_malloc(num_records * sizeof(record), 64);
    if (!records) {
        return NULL;
    }
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = aligned_malloc(sizeof(long), 64);
        if (!records[i].offset) {
            free(records);
            return NULL;
        }
    }
    return records;
}

void initialize_records(record *records, int num_records, int min_val, int max_val) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
        records[i].size = sizeof(int);
        *records[i].offset = (long)&records[i].value;
    }
}

