    while (scanf("%d", &input) == 1) {
        if (input < min_val || input > max_val) {
            printf("Warning: Input %d is out of bounds\n", input);
            continue;
        }
        // Process the valid input
    }
}

int find_largest_value(record *records, int num_records) {
    int largest = records[0].value;
    for (int i = 1; i < num_records; ++i) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }
    return largest;
}

void free_all_memory(record *records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].offset);
    }
    free(records);
}
