#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    size_t size;
    long *offset;
} record;

long* generate_random_numbers(int min, int max, int count) {
    long* numbers = (long*)malloc(count * sizeof(long));
    if (!numbers) {
        perror("Failed to allocate memory for random numbers");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        numbers[i] = min + rand() % (max - min + 1);
    }
    return numbers;
}

record* process_and_find_max(const char* filename, int min_val, int max_val, size_t max_records) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    long* offsets = generate_random_numbers(0, 1024 * 1024, max_records);
    if (!offsets) {
        fclose(file);
        return NULL;
    }

    int* keys = (int*)malloc(max_records * sizeof(int));
    if (!keys) {
        free(offsets);
        fclose(file);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    record* records = (record*)malloc(max_records * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        fclose(file);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    size_t total_size = 0;
    for (size_t i = 0; i < max_records; ++i) {
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i];
        records[i].size = sizeof(int);
        records[i].offset = offsets + i * sizeof(long);
        total_size += records[i].size;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    if (file_size < total_size) {
        fprintf(stderr, "File is too small to hold all records\n");
        free(records);
        free(keys);
        free(offsets);
        fclose(file);
        return NULL;
    }

    fseek(file, 0, SEEK_SET);
    for (size_t i = 0; i < max_records; ++i) {
        if (fseek(file, records[i].offset, SEEK_SET) != 0) {
            fprintf(stderr, "Failed to seek to offset %ld\n", records[i].offset);
            continue;
        }
        if (fwrite(&records[i].value, sizeof(int), 1, file) != 1) {
            fprintf(stderr, "Failed to write value at offset %ld\n", records[i].offset);
        }
    }

    fclose(file);

    return records;
}

int find_max_in_array(const int* array, size_t size) {
    if (size == 0) {
        return INT_MIN; // Assuming all values are non-negative
    }
    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

int main() {
    record* records = process_and_find_max("data.bin", 1, 100, 10);
    if (!records) {
        return EXIT_FAILURE;
    }

    int* values = (int*)malloc(10 * sizeof(int));
    if (!values) {
        free(records);
        perror("Failed to allocate memory for values");
        return EXIT_FAILURE;
    }

    FILE* file = fopen("data.bin", "rb");
    if (!file) {
        free(values);
        free(records);
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < 10; ++i) {
        if (fseek(file, records[i].offset, SEEK_SET) != 0) {
            fprintf(stderr, "Failed to seek to offset %ld\n", records[i].offset);
            continue;
        }
        if (fread(&values[i], sizeof(int), 1, file) != 1) {
            fprintf(stderr, "Failed to read value at offset %ld\n", records[i].offset);
        }
    }

    fclose(file);

    int max_value = find_max_in_array(values, 10);
    printf("The maximum value is: %d\n", max_value);

    free(values);
    free(records);

    return EXIT_SUCCESS;
}
