#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int id;
    size_t dataSize;
    char* rawData;
    void (*dataManipulate)(void*);
} record;

typedef struct {
    record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} recordCollection;

recordCollection* createRecordCollection() {
    recordCollection* collection = (recordCollection*)malloc(sizeof(recordCollection));
    if (!collection) return NULL;
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void destroyRecordCollection(recordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i]->rawData);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

void resizeRecordCollection(recordCollection* collection, size_t newCapacity) {
    record** newRecords = (record**)realloc(collection->records, newCapacity * sizeof(record*));
    if (!newRecords) return;
    collection->records = newRecords;
    collection->capacity = newCapacity;
}

int addRecordToCollection(recordCollection* collection, int id, size_t dataSize, void (*dataManipulate)(void*)) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= collection->capacity) resizeRecordCollection(collection, collection->capacity ? collection->capacity * 2 : 16);
    record* newRecord = (record*)malloc(sizeof(record));
    if (!newRecord) {
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }
    newRecord->id = id;
    newRecord->dataSize = dataSize;
    newRecord->rawData = (char*)malloc(dataSize);
    if (!newRecord->rawData) {
        free(newRecord);
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }
    memset(newRecord->rawData, 0, dataSize);
    newRecord->dataManipulate = dataManipulate;
    collection->records[collection->count++] = newRecord;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
