#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    size_t size;
} Record;

typedef struct {
    long offset;
    int key;
    Record *record;
    void **data;
    size_t data_size;
    size_t data_capacity;
    pthread_mutex_t mutex;
} DataStructure;

DataStructure* init_data_structure() {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) return NULL;

    ds->offset = 0;
    ds->key = 0;
    ds->record = NULL;
    ds->data = NULL;
    ds->data_size = 0;
    ds->data_capacity = 16; // Initial capacity
    pthread_mutex_init(&ds->mutex, NULL);

    ds->data = (void**)malloc(ds->data_capacity * sizeof(void*));
    if (!ds->data) {
        free(ds);
        return NULL;
    }

    memset(ds->data, 0, ds->data_capacity * sizeof(void*));

    return ds;
}

int allocate_data(DataStructure *ds, size_t size) {
    pthread_mutex_lock(&ds->mutex);

    if (ds->data_size >= ds->data_capacity) {
        void **new_data = (void**)realloc(ds->data, ds->data_capacity * 2 * sizeof(void*));
        if (!new_data) {
            pthread_mutex_unlock(&ds->mutex);
            return -1;
        }
        ds->data = new_data;
        ds->data_capacity *= 2;
    }

    ds->data[ds->data_size] = malloc(size);
    if (!ds->data[ds->data_size]) {
        pthread_mutex_unlock(&ds->mutex);
        return -1;
    }

    ds->data_size++;

    pthread_mutex_unlock(&ds->mutex);
    return 0;
}

void free_data(DataStructure *ds) {
    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->data_size; i++) {
        if (ds->data[i]) {
            free(ds->data[i]);
            ds->data[i] = NULL;
        }
    }

    free(ds->data);
    pthread_mutex_unlock(&ds->mutex);
}

void destroy_data_structure(DataStructure *ds) {
    free_data(ds);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}
