typedef struct {
    int *ports;
    char **hostnames;
    unsigned long *timeout_values;
    void (**handlers)(void);
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* config_manager_init(size_t initial_capacity) {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    manager->ports = (int*)calloc(initial_capacity, sizeof(int));
    manager->hostnames = (char**)calloc(initial_capacity, sizeof(char*));
    manager->timeout_values = (unsigned long*)calloc(initial_capacity, sizeof(unsigned long));
    manager->handlers = (void (**))calloc(initial_capacity, sizeof(void (*)(void)));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void config_manager_add_handler(ConfigManager *manager, int port, const char *hostname, unsigned long timeout, void (*handler)(void)) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        manager->ports = (int*)realloc(manager->ports, new_capacity * sizeof(int));
        manager->hostnames = (char**)realloc(manager->hostnames, new_capacity * sizeof(char*));
        manager->timeout_values = (unsigned long*)realloc(manager->timeout_values, new_capacity * sizeof(unsigned long));
        manager->handlers = (void (**))realloc(manager->handlers, new_capacity * sizeof(void (*)(void)));
        if (!manager->ports || !manager->hostnames || !manager->timeout_values || !manager->handlers) {
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        manager->capacity = new_capacity;
    }

    manager->ports[manager->count] = port;
    manager->hostnames[manager->count] = strdup(hostname);
    manager->timeout_values[manager->count] = timeout;
    manager->handlers[manager->count] = handler;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

void config_manager_set_random_timeout(ConfigManager *manager, unsigned long min_timeout, unsigned long max_timeout) {
    srand(time(NULL));
    for (size_t i = 0; i < manager->count; i++) {
        manager->timeout_values[i] = min_timeout + rand() % (max_timeout - min_timeout + 1);
    }
}

void config_manager_log_changes(ConfigManager *manager, const char *message) {
    printf("Configuration change: %s\n", message);
}

void config_manager_free(ConfigManager *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->hostnames[i]);
    }
    free(manager->ports);
    free(manager->hostnames);
    free(manager->timeout_values);
    free(manager->handlers);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

