#define METADATA_SIZE sizeof(BlockMetadata)
#define SLAB_SIZE 1024

typedef struct {
    size_t size;
    int free;
    pthread_mutex_t lock;
} BlockMetadata;

BlockMetadata *memory_pool = NULL;
size_t pool_size = 0;
size_t used_blocks = 0;

void init_memory_pool(size_t initial_size) {
    pool_size = initial_size;
    memory_pool = (BlockMetadata *)malloc(pool_size);
    for (size_t i = 0; i < pool_size / METADATA_SIZE; ++i) {
        memory_pool[i].size = SLAB_SIZE - METADATA_SIZE;
        memory_pool[i].free = 1;
        pthread_mutex_init(&memory_pool[i].lock, NULL);
    }
}

void *allocate_memory(size_t size) {
    for (size_t i = 0; i < pool_size / METADATA_SIZE; ++i) {
        if (memory_pool[i].free && memory_pool[i].size >= size) {
            pthread_mutex_lock(&memory_pool[i].lock);
            if (memory_pool[i].free) {
                memory_pool[i].free = 0;
                used_blocks++;
                return (void *)(memory_pool + i + 1);
            }
            pthread_mutex_unlock(&memory_pool[i].lock);
        }
    }
    // Handle out of memory scenario
    return NULL;
}

void deallocate_memory(void *ptr) {
    BlockMetadata *metadata = (BlockMetadata *)ptr - 1;
    pthread_mutex_lock(&metadata->lock);
    metadata->free = 1;
    used_blocks--;
    pthread_mutex_unlock(&metadata->lock);
}

