    FILE *output_file = fopen(output_path, "wb");
    if (!output_file) {
        perror("Failed to open output file");
        fclose(input_file);
        return -1;
    }

    ProcessingContext context = {input_file, output_file, threshold, log_level};

    pthread_t threads[MAX_THREADS];
    int num_threads = MAX_THREADS;

    // Dynamically adjust the number of threads based on file size
    fseek(input_file, 0, SEEK_END);
    long file_size = ftell(input_file);
    if (file_size > 10 * 1024 * 1024 * 1024) { // Example threshold for large files
        num_threads = MAX_THREADS / 2;
    }

    fseek(input_file, 0, SEEK_SET);

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_chunk, &context) != 0) {
            perror("Failed to create thread");
            fclose(input_file);
            fclose(output_file);
            return -1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(input_file);
    fclose(output_file);

    return 0;
}
