typedef struct Record {
    int key;
    size_t dataSize;
    char* data;
} Record;

Record* createRecords(int numRecords, int minKey, int maxKey, size_t initialDataSize, int enableAlignment) {
    if (numRecords <= 0 || minKey > maxKey || initialDataSize == 0) {
        return NULL;
    }

    Record* records = malloc(numRecords * sizeof(Record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numRecords; ++i) {
        records[i].key = rand() % (maxKey - minKey + 1) + minKey;
        records[i].dataSize = initialDataSize;

        if (enableAlignment) {
            // Allocate memory with alignment
            records[i].data = aligned_alloc(64, records[i].dataSize);
        } else {
            records[i].data = malloc(records[i].dataSize);
        }

        if (!records[i].data) {
            // Handle allocation failure
            for (int j = 0; j < i; ++j) {
                free(records[j].data);
            }
            free(records);
            return NULL;
        }

        // Initialize data block with random values
        for (size_t j = 0; j < records[i].dataSize; ++j) {
            records[i].data[j] = rand() % 256;
        }
    }

    return records;
}

void freeRecords(Record* records, int numRecords) {
    if (!records || numRecords <= 0) {
        return;
    }

    for (int i = 0; i < numRecords; ++i) {
        free(records[i].data);
    }

    free(records);
}
