        if (records[i].timestamp <= records[i - 1].timestamp) {
            // Log validation issue
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    // Return the initialized data structure
    return records;
}

void* incremental_cleanup(void* data, int start_index, int end_index) {
    if (data == NULL || start_index < 0 || end_index >= initial_size) {
        // Log invalid cleanup parameters
        return NULL;
    }

    record* records = (record*)data;

    for (int i = start_index; i <= end_index; i++) {
        free(records[i].value); // Assuming value is dynamically allocated
    }

    // Reallocate memory to shrink the array
    record* new_records = (record*)realloc(data, (initial_size - (end_index - start_index + 1)) * sizeof(record));
    if (!new_records) {
        // Log reallocation failure
        return NULL;
    }

    initial_size -= (end_index - start_index + 1);
    data = new_records;

    return data;
}
