#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum { PENDING, IN_PROGRESS, COMPLETED } Status;

typedef struct {
    int value;
    size_t size;
    union {
        char* buffer;
        double dbl_value;
    };
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t count;
    size_t capacity;
} TaskList;

void initializeDataStructure(TaskList* list, size_t initialCapacity) {
    list->offsets = (long*)malloc(initialCapacity * sizeof(long));
    list->keys = (int*)malloc(initialCapacity * sizeof(int));
    list->records = (Record*)malloc(initialCapacity * sizeof(Record));
    if (!list->offsets || !list->keys || !list->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initialCapacity;
}

void addTask(TaskList* list, int id, Status status, int priority, int minValue, int maxValue) {
    if (list->count == list->capacity) {
        // Resize the arrays
        list->offsets = (long*)realloc(list->offsets, list->capacity * 2 * sizeof(long));
        list->keys = (int*)realloc(list->keys, list->capacity * 2 * sizeof(int));
        list->records = (Record*)realloc(list->records, list->capacity * 2 * sizeof(Record));
        if (!list->offsets || !list->keys || !list->records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->capacity *= 2;
    }

    list->keys[list->count] = id;
    list->records[list->count].value = rand() % (maxValue - minValue + 1) + minValue;
    list->records[list->count].size = sizeof(int);
    list->records[list->count].buffer = NULL; // Union member not used
    list->offsets[list->count] = (long)&list->records[list->count];
    list->count++;
}

void freeTaskList(TaskList* list) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->records[i].buffer != NULL) {
            free(list->records[i].buffer);
        }
    }
    free(list->offsets);
    free(list->keys);
    free(list->records);
}

int main() {
    srand(time(NULL));
    TaskList taskList;
    initializeDataStructure(&taskList, 10);

    addTask(&taskList, 1, PENDING, 5, 10, 20);
    addTask(&taskList, 2, IN_PROGRESS, 3, 5, 15);

    freeTaskList(&taskList);
    return 0;
}
