#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int key;
    size_t dataSize;
    char* data;
} Record;

typedef struct RecordCollection {
    Record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordCollection;

Record* createRecord(int key, size_t dataSize) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->dataSize = dataSize;
    record->data = (char*)malloc(dataSize);
    if (!record->data) {
        free(record);
        return NULL;
    }

    return record;
}

void destroyRecord(Record* record) {
    if (record->data) free(record->data);
    free(record);
}

RecordCollection* createRecordCollection(size_t initialCapacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)malloc(initialCapacity * sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = initialCapacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroyRecordCollection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        destroyRecord(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int addRecord(RecordCollection* collection, Record* record) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count == collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Record** newRecords = (Record**)realloc(collection->records, newCapacity * sizeof(Record*));
        if (!newRecords) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }

        collection->records = newRecords;
        collection->capacity = newCapacity;
    }

    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void* customRandomNumberGenerator(void* seed) {
    srand((unsigned int)seed);
    while (1) {
        printf("%d\n", rand());
        sleep(1); // Simulate periodic generation
    }
    return NULL;
}

int main() {
    RecordCollection* collection = createRecordCollection(10);

    pthread_t randomThread;
    pthread_create(&randomThread, NULL, customRandomNumberGenerator, (void*)time(NULL));

    for (int i = 0; i < 5; ++i) {
        Record* record = createRecord(rand(), rand() % 1024);
        if (!record) continue;

        if (addRecord(collection, record) != 0) {
            destroyRecord(record);
        }
    }

    pthread_join(randomThread, NULL);
    destroyRecordCollection(collection);

    return 0;
}
