#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    size_t size;
    void* offset;
} record;

record* create_record(size_t size) {
    record* rec = (record*)malloc(sizeof(record));
    if (!rec) return NULL;
    rec->offset = malloc(size);
    if (!rec->offset) {
        free(rec);
        return NULL;
    }
    rec->size = size;
    return rec;
}

void destroy_record(record* rec) {
    if (rec->offset) free(rec->offset);
    free(rec);
}

record** create_data_stream(size_t num_records, int min_val, int max_val) {
    record** stream = (record**)malloc(num_records * sizeof(record*));
    if (!stream) return NULL;
    for (size_t i = 0; i < num_records; ++i) {
        stream[i] = create_record(sizeof(int));
        if (!stream[i]) {
            for (size_t j = 0; j < i; ++j) destroy_record(stream[j]);
            free(stream);
            return NULL;
        }
        ((int*)stream[i]->offset)[0] = rand() % (max_val - min_val + 1) + min_val;
    }
    return stream;
}

void destroy_data_stream(record** stream, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) destroy_record(stream[i]);
    free(stream);
}

int find_largest_value(record** stream, size_t num_records) {
    int largest = INT_MIN;
    for (size_t i = 0; i < num_records; ++i) {
        if (((int*)stream[i]->offset)[0] > largest) {
            largest = ((int*)stream[i]->offset)[0];
        }
    }
    return largest;
}

void process_data_stream(record** stream, size_t num_records, int min_val, int max_val) {
    srand(time(NULL));
    record** new_stream = create_data_stream(num_records, min_val, max_val);
    if (!new_stream) {
        fprintf(stderr, "Failed to allocate memory for data stream.\n");
        return;
    }
    int largest_value = find_largest_value(new_stream, num_records);
    printf("Largest value in the stream: %d\n", largest_value);
    destroy_data_stream(new_stream, num_records);
}

int main() {
    process_data_stream(NULL, 0, 1, 100); // Example usage
    return 0;
}
