#include <time.h>

typedef struct {
    int value;
    size_t size;
    void* offset;
} record;

void generate_random_value(int *value, int min, int max) {
    *value = rand() % (max - min + 1) + min;
}

record* initialize_records(size_t num_records, int min_val, int max_val) {
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (size_t i = 0; i < num_records; ++i) {
        generate_random_value(&records[i].value, min_val, max_val);
        records[i].size = sizeof(int);
        records[i].offset = &records[i].value;
    }
    return records;
}

void process_data_stream(record* records, size_t num_records, int min_val, int max_val) {
    if (!records) {
        fprintf(stderr, "Invalid record pointer\n");
        return;
    }

    int largest_value = INT_MIN;
    for (size_t i = 0; i < num_records; ++i) {
        generate_random_value(&records[i].value, min_val, max_val);
        if (records[i].value > largest_value) {
            largest_value = records[i].value;
        }
    }

