    FILE* file = fopen("largest_value.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fprintf(file, "%d\n", largest_value);
    fclose(file);
}

void free_records(record* records, size_t num_records) {
    free(records);
}
